import json
import pickle
from typing import Any, Dict, List, Set, Tuple, Union
from collections import OrderedDict

class SetSerializer:
    def __init__(self):
        self._set_id_counter = 0
        self._id_to_set: Dict[int, set] = {}
        self._set_to_id: Dict[frozenset, int] = {}

    def _get_set_id(self, s: set) -> int:
        """Get or assign a unique ID for a set"""
        fs = frozenset(s)
        if fs not in self._set_to_id:
            self._set_id_counter += 1
            self._set_to_id[fs] = self._set_id_counter
            self._id_to_set[self._set_id_counter] = s
        return self._set_id_counter

    def _serialize_set(self, obj: set) -> Dict[str, Any]:
        """Serialize a set with its identity"""
        return {
            "__set__": True,
            "id": self._get_set_id(obj),
            "elements": sorted(list(obj))  # Preserve order
        }

    def _deserialize_set(self, data: Dict[str, Any]) -> set:
        """Deserialize a set from JSON"""
        return self._id_to_set[data["id"]]

    def serialize(self, obj: Any) -> str:
        """Serialize object with set identity preservation"""
        def _serialize_recursive(o):
            if isinstance(o, set):
                return self._serialize_set(o)
            elif isinstance(o, dict):
                return {k: _serialize_recursive(v) for k, v in o.items()}
            elif isinstance(o, list):
                return [_serialize_recursive(item) for item in o]
            elif isinstance(o, tuple):
                return {"__tuple__": True, "elements": [_serialize_recursive(item) for item in o]}
            else:
                return o

        serialized = _serialize_recursive(obj)
        return json.dumps(serialized)

    def deserialize(self, json_str: str) -> Any:
        """Deserialize object with set identity restoration"""
        data = json.loads(json_str)

        def _deserialize_recursive(o):
            if isinstance(o, dict) and "__set__" in o:
                return self._deserialize_set(o)
            elif isinstance(o, dict) and "__tuple__" in o:
                return tuple(_deserialize_recursive(item) for item in o["elements"])
            elif isinstance(o, dict):
                return {k: _deserialize_recursive(v) for k, v in o.items()}
            elif isinstance(o, list):
                return [_deserialize_recursive(item) for item in o]
            else:
                return o

        return _deserialize_recursive(data)

# Example usage
if __name__ == "__main__":
    # Create test data with sets
    serializer = SetSerializer()

    set1 = {1, 2, 3}
    set2 = {4, 5, 6}
    data = {
        "sets": [set1, set2],
        "nested": {"inner_set": set1}
    }

    # Serialize
    json_str = serializer.serialize(data)
    print("Serialized:", json_str)

    # Deserialize
    restored_data = serializer.deserialize(json_str)
    print("Restored:", restored_data)

    # Verify identity preservation
    print("Set identity preserved:", restored_data["sets"][0] is set1)
```

## How it works:

1. **Set Identity Tracking**: The serializer maintains a mapping between unique set identities and their actual set objects using `frozenset` as a hash key.

2. **Unique ID Assignment**: Each distinct set gets assigned a unique integer ID that persists across serialization/deserialization.

3. **Order Preservation**: Sets are serialized with their elements sorted (maintaining consistent ordering), since Python sets don't preserve insertion order in older versions.

4. **Cross-Process Compatibility**: The JSON representation is simple and portable, while the identity mapping can be reconstructed on any process by using the same serialization logic.

5. **Recursive Handling**: The serializer recursively processes nested structures, handling dictionaries, lists, tuples, and sets appropriately.

The key insight is that we don't serialize the actual set objects themselves (which would lose identity), but rather create a mapping system that preserves object references across processes while maintaining order through sorted elements.

