import java.util.*;
import java.util.concurrent.*;

// Simple consensus module implementing a basic Paxos-like protocol
public class ConsensusModule {
    private final int nodeId;
    private final List<Integer> allNodes;
    private final Map<Integer, NodeState> nodeStates;
    private final ExecutorService executor;
    private volatile boolean isCrashed = false;

    // State tracking for consensus rounds
    private volatile int currentRound = 0;
    private volatile Object acceptedValue = null;
    private volatile int acceptedRound = -1;

    public ConsensusModule(int nodeId, List<Integer> allNodes) {
        this.nodeId = nodeId;
        this.allNodes = new ArrayList<>(allNodes);
        this.nodeStates = new ConcurrentHashMap<>();
        this.executor = Executors.newCachedThreadPool();

        // Initialize node states
        for (int node : allNodes) {
            nodeStates.put(node, new NodeState());
        }
    }

    // Simulate proposing a value
    public boolean propose(Object value) {
        if (isCrashed) return false;

        try {
            currentRound++;
            System.out.println("Node " + nodeId + " proposing round " + currentRound + " with value: " + value);

            // Phase 1: Prepare phase
            int prepared = 0;
            for (int node : allNodes) {
                if (node != nodeId) {
                    executor.submit(() -> {
                        try {
                            Thread.sleep(10); // Simulate network delay
                            if (!isCrashed && nodeStates.get(node).prepare(currentRound, value)) {
                                prepared++;
                            }
                        } catch (InterruptedException e) {
                            Thread.currentThread().interrupt();
                        }
                    });
                } else {
                    prepared++; // Local node always prepares
                }
            }

            // Wait for majority preparation
            Thread.sleep(50);

            if (prepared > allNodes.size() / 2) {
                // Phase 2: Accept phase
                int accepted = 0;
                Object chosenValue = value;

                // If we have an accepted value from previous rounds, use it
                if (acceptedRound >= 0 && acceptedValue != null) {
                    chosenValue = acceptedValue;
                }

                for (int node : allNodes) {
                    if (node != nodeId) {
                        executor.submit(() -> {
                            try {
                                Thread.sleep(10);
                                if (!isCrashed && nodeStates.get(node).accept(currentRound, chosenValue)) {
                                    accepted++;
                                }
                            } catch (InterruptedException e) {
                                Thread.currentThread().interrupt();
                            }
                        });
                    } else {
                        accepted++; // Local node always accepts
                    }
                }

                Thread.sleep(50);

                if (accepted > allNodes.size() / 2) {
                    acceptedRound = currentRound;
                    acceptedValue = chosenValue;
                    System.out.println("Node " + nodeId + " reached consensus on: " + chosenValue);
                    return true;
                }
            }

        } catch (Exception e) {
            System.err.println("Consensus failed in node " + nodeId + ": " + e.getMessage());
        }

        return false;
    }

    // Simulate node crash
    public void crash() {
        isCrashed = true;
        System.out.println("Node " + nodeId + " crashed");
    }

    // Simulate node recovery
    public void recover() {
        isCrashed = false;
        System.out.println("Node " + nodeId + " recovered");
    }

    // Node state for communication
    private class NodeState {
        private volatile int prepareRound = -1;
        private volatile Object prepareValue = null;
        private volatile int acceptRound = -1;
        private volatile Object acceptValue = null;

        public boolean prepare(int round, Object value) {
            if (round > prepareRound) {
                prepareRound = round;
                prepareValue = value;
                return true;
            }
            return false;
        }

        public boolean accept(int round, Object value) {
            if (round >= acceptRound) {
                acceptRound = round;
                acceptValue = value;
                return true;
            }
            return false;
        }
    }

    // Example usage
    public static void main(String[] args) {
        List<Integer> nodes = Arrays.asList(1, 2, 3, 4, 5);
        List<ConsensusModule> consensusModules = new ArrayList<>();

        // Create consensus modules for each node
        for (int nodeId : nodes) {
            consensusModules.add(new ConsensusModule(nodeId, nodes));
        }

        // Simulate normal operation
        System.out.println("=== Normal Operation ===");
        consensusModules.get(0).propose("Value1");

        // Simulate crash of one node
        System.out.println("\n=== Node 3 Crashes ===");
        consensusModules.get(2).crash();

        // Continue with consensus - should still work due to fault tolerance
        consensusModules.get(0).propose("Value2");
        consensusModules.get(1).propose("Value3");

        // Recover the crashed node
        System.out.println("\n=== Node 3 Recovers ===");
        consensusModules.get(2).recover();

        // Continue with more proposals
        consensusModules.get(4).propose("Value4");
    }
}
```

This example demonstrates:

1. **Basic Consensus Protocol**: Implements a simplified Paxos-like approach with prepare and accept phases
2. **Fault Tolerance**: Can tolerate one node crash due to majority voting (3 out of 5 nodes required)
3. **Asynchronous Network**: Uses thread pools and sleep delays to simulate network behavior
4. **Crash Recovery**: Shows how nodes can crash and recover while maintaining consensus
5. **Agreement Guarantee**: Ensures all non-faulty nodes agree on the same value

The key features:
- **Consensus Algorithm**: Two-phase protocol with prepare/accept phases
- **Majority Voting**: Requires > N/2 nodes to agree for consensus
- **Asynchronous Communication**: Simulated with thread delays
- **Crash Simulation**: Nodes can crash and recover
- **Fault Tolerance**: Works even when one node fails

Note: This is a simplified educational example. Real production implementations would include more sophisticated features like leader election, message ordering, and extensive error handling.

You can't guarantee full ACID transactions across multiple databases without some form of coordination protocol. However, here's a simplified approach using distributed transaction patterns:

```python
class TransactionCoordinator:
    def __init__(self):
        self.participants = []
        self.transactions = {}

    def begin_transaction(self, tx_id):
        # Start transaction on all participants
        for participant in self.participants:
            participant.begin(tx_id)

    def commit_transaction(self, tx_id):
        # Two-phase commit approach
        try:
            # Phase 1: Prepare
            for participant in self.participants:
                participant.prepare(tx_id)

            # Phase 2: Commit
            for participant in self.participants:
                participant.commit(tx_id)

        except Exception as e:
            # Rollback on failure
            for participant in self.participants:
                participant.rollback(tx_id)
            raise
```

**Key point**: True ACID across databases requires some coordination (like 2PC, saga patterns, or eventual consistency). The "no coordination protocol" part is a contradiction - you need some form of communication between databases to ensure atomicity.

