    this.vectorClock.set(machineId, 0);
  }

  // Generate local timestamp (logical clock)
  getTimestamp() {
    this.logicalClock++;
    this.vectorClock.set(this.machineId, this.logicalClock);
    return this.getVectorTimestamp();
  }

  // Process incoming event timestamp and update vector clock
  processEvent(timestamp) {
    const incomingVector = JSON.parse(timestamp);

    // Update vector clock with maximum values
    for (const [machineId, timestamp] of Object.entries(incomingVector)) {
      if (!this.vectorClock.has(machineId)) {
        this.vectorClock.set(machineId, 0);
      }

      const current = this.vectorClock.get(machineId);
      this.vectorClock.set(machineId, Math.max(current, timestamp));
    }

    // Update local logical clock
    this.logicalClock = Math.max(this.logicalClock, this.vectorClock.get(this.machineId));

    return this.getVectorTimestamp();
  }

  // Get current vector timestamp
  getVectorTimestamp() {
    const result = {};
    for (const [machineId, timestamp] of this.vectorClock) {
      result[machineId] = timestamp;
    }
    return JSON.stringify(result);
  }

  // Check if event A happened before event B (total order)
  happensBefore(timestampA, timestampB) {
    const vectorA = JSON.parse(timestampA);
    const vectorB = JSON.parse(timestampB);

    let isLess = false;

    for (const machineId of new Set([...Object.keys(vectorA), ...Object.keys(vectorB)])) {
      const a = vectorA[machineId] || 0;
      const b = vectorB[machineId] || 0;

      if (a < b) {
        isLess = true;
      } else if (a > b) {
        return false; // A happened after B
      }
    }

    return isLess;
  }
}

