```java
import java.util.*;

public class PetrovMatching {
    static class Edge {
        int u, v;
        Edge(int u, int v) {
            this.u = u;
            this.v = v;
        }
    }

    public static int[] findMaximumMatching(int n, List<Edge> edges) {
        // Build adjacency list representation
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }

        Map<String, Integer> edgeMap = new HashMap<>();
        int edgeId = 0;

        for (Edge e : edges) {
            adj[e.u].add(e.v);
            adj[e.v].add(e.u);
            edgeMap.put(e.u + "," + e.v, edgeId++);
        }

        // Initialize matching array
        int[] matching = new int[n];
        Arrays.fill(matching, -1);

        // Greedy approach for maximum matching (simplified)
        // In a true Petrov algorithm, this would be more complex
        for (int u = 0; u < n; u++) {
            if (matching[u] == -1) {
                for (int v : adj[u]) {
                    if (matching[v] == -1) {
                        matching[u] = v;
                        matching[v] = u;
                        break;
                    }
                }
            }
        }

        return matching;
    }

    // More sophisticated implementation using alternating paths
    public static int[] findMaximumMatchingOptimized(int n, List<Edge> edges) {
        // Build adjacency list
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }

        for (Edge e : edges) {
            adj[e.u].add(e.v);
            adj[e.v].add(e.u);
        }

        int[] matching = new int[n];
        Arrays.fill(matching, -1);
        boolean[] visited = new boolean[n];

        // Find augmenting paths using BFS/DFS
        for (int i = 0; i < n; i++) {
            if (matching[i] == -1) {
                Arrays.fill(visited, false);
                if (findAugmentingPath(i, adj, matching, visited)) {
                    // Found augmenting path, continue
                }
            }
        }

        return matching;
    }

    private static boolean findAugmentingPath(int u, List<Integer>[] adj, int[] matching, boolean[] visited) {
        visited[u] = true;

        for (int v : adj[u]) {
            if (visited[v]) continue;

            if (matching[v] == -1 || findAugmentingPath(matching[v], adj, matching, visited)) {
                matching[u] = v;
                matching[v] = u;
                return true;
            }
        }

        return false;
    }

    // Simple example with O(n) time complexity for specific cases
    public static int[] findMaximumMatchingLinear(int n, List<Edge> edges) {
        if (edges.isEmpty()) return new int[n];

        // For a linear graph (path), we can solve in O(n)
        int[] matching = new int[n];
        Arrays.fill(matching, -1);

        boolean[] used = new boolean[n];
        int matchedCount = 0;

        // Greedy approach for path graphs
        for (Edge e : edges) {
            if (!used[e.u] && !used[e.v]) {
                matching[e.u] = e.v;
                matching[e.v] = e.u;
                used[e.u] = true;
                used[e.v] = true;
                matchedCount += 2;
            }
        }

        return matching;
    }

    public static void main(String[] args) {
        // Example: Graph with 6 vertices and edges
        int n = 6;
        List<Edge> edges = Arrays.asList(
            new Edge(0, 1),
            new Edge(1, 2),
            new Edge(2, 3),
            new Edge(3, 4),
            new Edge(4, 5)
        );

        System.out.println("Graph edges: " + edges);

        // Simple greedy matching
        int[] result = findMaximumMatchingLinear(n, edges);

        System.out.print("Matching: ");
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (result[i] != -1) {
                System.out.printf("(%d-%d) ", i, result[i]);
                count++;
            }
        }
        System.out.println("\nMaximum matching size: " + count/2);

        // Alternative approach
        int[] result2 = findMaximumMatchingOptimized(n, edges);
        System.out.print("Optimized matching: ");
        for (int i = 0; i < n; i++) {
            if (result2[i] != -1 && i < result2[i]) {
                System.out.printf("(%d-%d) ", i, result2[i]);
            }
        }
    }
}
