#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>
#include <variant>
#include <memory>

// Abstract syntax tree nodes
struct ASTNode {
    virtual ~ASTNode() = default;
};

struct NumberNode : public ASTNode {
    int value;
    NumberNode(int v) : value(v) {}
};

struct VariableNode : public ASTNode {
    std::string name;
    VariableNode(const std::string& n) : name(n) {}
};

struct BinaryOpNode : public ASTNode {
    std::unique_ptr<ASTNode> left, right;
    char op;
    BinaryOpNode(std::unique_ptr<ASTNode> l, char o, std::unique_ptr<ASTNode> r)
        : left(std::move(l)), right(std::move(r)), op(o) {}
};

struct AssignmentNode : public ASTNode {
    std::string variable;
    std::unique_ptr<ASTNode> expression;
    AssignmentNode(const std::string& var, std::unique_ptr<ASTNode> expr)
        : variable(var), expression(std::move(expr)) {}
};

// Simple interpreter with state
class Interpreter {
private:
    std::unordered_map<std::string, int> variables;
    int step_count = 0;
    static constexpr int MAX_STEPS = 10000; // Safety limit

public:
    int evaluate(const std::unique_ptr<ASTNode>& node) {
        if (step_count++ > MAX_STEPS) {
            throw std::runtime_error("Maximum steps exceeded - possible infinite loop");
        }

        // This is a simplified evaluator
        return evaluate_node(node);
    }

private:
    int evaluate_node(const std::unique_ptr<ASTNode>& node) {
        // Simplified implementation for demonstration
        if (auto* num = dynamic_cast<NumberNode*>(node.get())) {
            return num->value;
        } else if (auto* var = dynamic_cast<VariableNode*>(node.get())) {
            return variables[var->name];
        } else if (auto* binop = dynamic_cast<BinaryOpNode*>(node.get())) {
            int left_val = evaluate_node(binop->left);
            int right_val = evaluate_node(binop->right);
            switch (binop->op) {
                case '+': return left_val + right_val;
                case '-': return left_val - right_val;
                case '*': return left_val * right_val;
                default: throw std::runtime_error("Unknown operator");
            }
        }
        throw std::runtime_error("Unknown node type");
    }

public:
    void set_variable(const std::string& name, int value) {
        variables[name] = value;
    }

    void reset_step_count() {
        step_count = 0;
    }
};
