#include <iostream>
#include <string>
#include <map>
#include <memory>
#include <variant>
#include <vector>

// Expression types
struct Expr {
    virtual ~Expr() = default;
};

struct NumExpr : public Expr {
    int value;
    NumExpr(int v) : value(v) {}
};

struct VarExpr : public Expr {
    std::string name;
    VarExpr(const std::string& n) : name(n) {}
};

struct AddExpr : public Expr {
    std::unique_ptr<Expr> left, right;
    AddExpr(std::unique_ptr<Expr> l, std::unique_ptr<Expr> r)
        : left(std::move(l)), right(std::move(r)) {}
};

// Statement types
struct Stmt {
    virtual ~Stmt() = default;
};

struct AssignStmt : public Stmt {
    std::string var;
    std::unique_ptr<Expr> expr;
    AssignStmt(const std::string& v, std::unique_ptr<Expr> e)
        : var(v), expr(std::move(e)) {}
};

struct WhileStmt : public Stmt {
    std::unique_ptr<Expr> condition;
    std::vector<std::unique_ptr<Stmt>> body;
    WhileStmt(std::unique_ptr<Expr> c, std::vector<std::unique_ptr<Stmt>> b)
        : condition(std::move(c)), body(std::move(b)) {}
};

class SimpleInterpreter {
private:
    std::map<std::string, int> variables;
    int step_count = 0;
    static constexpr int MAX_STEPS = 100000;

public:
    void execute(const std::vector<std::unique_ptr<Stmt>>& program) {
        for (const auto& stmt : program) {
            if (step_count++ > MAX_STEPS) {
                throw std::runtime_error("Program exceeded maximum steps");
            }
            execute_stmt(stmt);
        }
    }

private:
    void execute_stmt(const std::unique_ptr<Stmt>& stmt) {
        if (auto* assign = dynamic_cast<AssignStmt*>(stmt.get())) {
            variables[assign->var] = evaluate_expr(assign->expr);
        } else if (auto* while_stmt = dynamic_cast<WhileStmt*>(stmt.get())) {
            while (evaluate_expr(while_stmt->condition)) {
                if (step_count++ > MAX_STEPS) {
                    throw std::runtime_error("While loop exceeded maximum steps");
                }
                for (const auto& body_stmt : while_stmt->body) {
                    execute_stmt(body_stmt);
                }
            }
        }
    }

    int evaluate_expr(const std::unique_ptr<Expr>& expr) {
        if (auto* num = dynamic_cast<NumExpr*>(expr.get())) {
            return num->value;
        } else if (auto* var = dynamic_cast<VarExpr*>(expr.get())) {
            return variables[var->name];
        } else if (auto* add = dynamic_cast<AddExpr*>(expr.get())) {
            return evaluate_expr(add->left) + evaluate_expr(add->right);
        }
        throw std::runtime_error("Unknown expression type");
    }
};
