This is a classic problem that demonstrates the trade-off between memory usage and accuracy! What you're asking for is impossible to solve exactly with O(1) memory, but I can show you several practical approaches that approximate the answer.

## Why Exact Counting is Impossible

With O(1) memory, you can only store a constant number of bits. If you have `k` bits of memory, you can only represent at most `2^k` distinct values. This means if your stream contains more than `2^k` distinct elements, you **cannot** count them exactly.

## Practical Approximation Approaches

Here are several methods that give you approximate counts with O(1) memory:

### 1. Simple Counter (Most Common)
```cpp
#include <iostream>
#include <unordered_set>
#include <random>

class DistinctCounter {
private:
    int count = 0;
    std::unordered_set<int> seen_elements;

public:
    // This is actually O(n) memory, but here's the O(1) approximation
    void add(int element) {
        if (seen_elements.find(element) == seen_elements.end()) {
            seen_elements.insert(element);
            count++;
        }
    }

    int get_count() const {
        return count;
    }
};

// Better approach: Use probabilistic data structures
```

### 2. Count-Min Sketch (Probabilistic)
```cpp
#include <vector>
#include <functional>
#include <algorithm>

class CountMinSketch {
private:
    std::vector<std::vector<int>> table;
    int width, depth;
    std::vector<std::function<unsigned int(int)>> hash_functions;

public:
    CountMinSketch(int w, int d) : width(w), depth(d) {
        table.assign(depth, std::vector<int>(width, 0));
        // Simple hash functions (in practice, use better ones)
        for (int i = 0; i < depth; i++) {
            hash_functions.push_back([i](int x) -> unsigned int {
                return (x * 1103515245 + 12345 + i) % width;
            });
        }
    }

    void add(int element) {
        for (int i = 0; i < depth; i++) {
            table[i][hash_functions[i](element)]++;
        }
    }

    int estimate_count(int element) {
        int min_count = INT_MAX;
        for (int i = 0; i < depth; i++) {
            min_count = std::min(min_count, table[i][hash_functions[i](element)]);
        }
        return min_count;
    }
};
```

### 3. Bloom Filter with Counter
```cpp
#include <vector>
#include <bitset>

class BloomFilterCounter {
private:
    std::vector<bool> bit_array;
    int size;
    int num_hash_functions;

public:
    BloomFilterCounter(int array_size, int hash_count) 
        : size(array_size), num_hash_functions(hash_count) {
        bit_array.assign(size, false);
    }

    // Simple hash functions
    unsigned int hash1(int element) {
        return element % size;
    }

    unsigned int hash2(int element) {
        return (element * 2654435761UL) % size;
    }

    void add(int element) {
        bit_array[hash1(element)] = true;
        bit_array[hash2(element)] = true;
    }

