### 4. Reservoir Sampling with Approximation
```cpp
#include <random>
#include <vector>

class ApproximateCounter {
private:
    std::vector<int> reservoir;
    int k; // reservoir size
    int total_count;
    std::mt19937 rng;

public:
    ApproximateCounter(int reservoir_size) 
        : k(reservoir_size), total_count(0), rng(std::random_device{}()) {
        reservoir.reserve(k);
    }

    void add(int element) {
        total_count++;

        if (reservoir.size() < k) {
            reservoir.push_back(element);
        } else {
            // Replace with probability k/total_count
            std::uniform_int_distribution<> dis(0, total_count - 1);
            int idx = dis(rng);
            if (idx < k) {
                reservoir[idx] = element;
            }
        }
    }

    // Estimate distinct count using the formula: n * log(1/(1 - k/n))
    double estimate_distinct() const {
        if (total_count == 0) return 0.0;
        double ratio = static_cast<double>(reservoir.size()) / total_count;
        return total_count * std::log(1.0 / (1.0 - ratio));
    }
};
```

