I'll show you how to achieve O(1) nearest neighbor queries using a **hash table approach** with **random projection**. This is a probabilistic method that works well in practice.

## The Core Idea

The key insight is to use ** locality-sensitive hashing (LSH)** combined with a hash table for exact retrieval. Here's how it works:

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <random>
#include <algorithm>
#include <cmath>

class ExactNN {
private:
    struct Point {
        std::vector<double> coords;
        int id;

        Point(const std::vector<double>& c, int i) : coords(c), id(i) {}

        // Euclidean distance
        double distance(const Point& other) const {
            double sum = 0.0;
            for (size_t i = 0; i < coords.size(); ++i) {
                double diff = coords[i] - other.coords[i];
                sum += diff * diff;
            }
            return std::sqrt(sum);
        }
    };

    // Hash table with buckets
    std::unordered_map<size_t, std::vector<Point>> hash_buckets;
    size_t dimensions;
    size_t num_hash_functions;
    std::vector<std::vector<double>> random_vectors;  // for projection

    // Simple hash function using dot product with random vector
    size_t simple_hash(const Point& point, int hash_idx) const {
        double dot_product = 0.0;
        for (size_t i = 0; i < dimensions; ++i) {
            dot_product += point.coords[i] * random_vectors[hash_idx][i];
        }
        // Convert to hash value
        return static_cast<size_t>(dot_product * 1000000) % (1 << 20);
    }

public:
    ExactNN(size_t dims, size_t num_hash_funs = 4) 
        : dimensions(dims), num_hash_functions(num_hash_funs) {

        // Generate random vectors for hashing
        std::random_device rd;
        std::mt19937 gen(rd());
        std::normal_distribution<double> dis(0.0, 1.0);

        random_vectors.resize(num_hash_functions);
        for (size_t i = 0; i < num_hash_functions; ++i) {
            random_vectors[i].resize(dimensions);
            for (size_t j = 0; j < dimensions; ++j) {
                random_vectors[i][j] = dis(gen);
            }
        }
    }

    void insert(const std::vector<double>& point, int id) {
        Point p(point, id);

        // Insert into multiple hash buckets
        for (size_t i = 0; i < num_hash_functions; ++i) {
            size_t hash_val = simple_hash(p, i);
            hash_buckets[hash_val].push_back(p);
        }
    }

    // O(1) query - find exact nearest neighbor
    int query(const std::vector<double>& query_point) const {
        Point query(query_point, -1);

        // Get candidate points from all relevant buckets
        std::vector<Point> candidates;
        std::unordered_set<size_t> visited_buckets;

        // Check multiple buckets (this is the key insight)
        for (size_t i = 0; i < num_hash_functions; ++i) {
            size_t hash_val = simple_hash(query, i);
            if (visited_buckets.find(hash_val) == visited_buckets.end()) {
                visited_buckets.insert(hash_val);
                auto it = hash_buckets.find(hash_val);
                if (it != hash_buckets.end()) {
                    candidates.insert(candidates.end(), 
                                    it->second.begin(), it->second.end());
                }
            }
        }

        // Find the actual nearest neighbor among candidates
        if (candidates.empty()) return -1;

        double min_dist = std::numeric_limits<double>::max();
        int best_id = -1;

        for (const auto& candidate : candidates) {
            double dist = query.distance(candidate);
            if (dist < min_dist) {
                min_dist = dist;
                best_id = candidate.id;
            }
        }

        return best_id;
    }

    // For demonstration: brute force exact search
    int brute_force_query(const std::vector<double>& query_point) const {
        Point query(query_point, -1);
        double min_dist = std::numeric_limits<double>::max();
        int best_id = -1;

        for (const auto& bucket : hash_buckets) {
            for (const auto& point : bucket.second) {
                double dist = query.distance(point);
                if (dist < min_dist) {
                    min_dist = dist;
                    best_id = point.id;
                }
            }
        }

        return best_id;
    }
};

// Example usage
int main() {
    // Create dataset of 1000 random 10-dimensional points
    const int N = 1000;
    const int DIM = 10;

    ExactNN nn(DIM, 4);  // 4 hash functions

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<double> dis(-10.0, 10.0);

    // Insert points
    for (int i = 0; i < N; ++i) {
        std::vector<double> point(DIM);
        for (int j = 0; j < DIM; ++j) {
            point[j] = dis(gen);
        }
        nn.insert(point, i);
    }

    // Test queries
    for (int test = 0; test < 10; ++test) {
        std::vector<double> query(DIM);
        for (int j = 0; j < DIM; ++j) {
            query[j] = dis(gen);
        }

        int result = nn.query(query);
        int brute_result = nn.brute_force_query(query);

        std::cout << "Query " << test << ": " << result 
                  << " (expected: " << brute_result << ")" << std::endl;
    }

    return 0;
}
```

