        let h2 = (self.hash_functions[1])(&key);

        // Double hashing to avoid collisions
        for i in 0..self.capacity {
            let index = (h1 + i * h2) % self.capacity;
            if self.data[index].is_none() {
                self.data[index] = Some(value);
                return None;
            }
        }

        panic!("Hash table is full - impossible to insert");
    }

    pub fn get(&self, key: K) -> Option<&V> {
        let h1 = (self.hash_functions[0])(&key);
        let h2 = (self.hash_functions[1])(&key);

        for i in 0..self.capacity {
            let index = (h1 + i * h2) % self.capacity;
            if let Some(ref value) = self.data[index] {
                return Some(value);
            }
        }
        None
    }

    pub fn remove(&mut self, key: K) -> Option<V> {
        let h1 = (self.hash_functions[0])(&key);
        let h2 = (self.hash_functions[1])(&key);

        for i in 0..self.capacity {
            let index = (h1 + i * h2) % self.capacity;
            if self.data[index].is_none() {
                return None;
            }
            // In a real implementation, you'd need to handle tombstones
            // This is simplified for demonstration
        }
        None
    }
}

