    data = 42;       // Write data
    ready = 1;       // Signal completion (both writes happen before this)
    return NULL;
}

void* consumer(void* arg) {
    while (!ready);  // Wait for signal
    printf("Got data: %d\n", data);  // Read data
    return NULL;
}

int main() {
