    cudaMallocManaged(&data, N * sizeof(int));

    // Initialize on CPU
    for (int i = 0; i < N; i++) {
        data[i] = i;
    }

    // Launch kernel that modifies the same memory
    auto kernel = [] __device__ (int* arr, int n) {
        int tid = blockIdx.x * blockDim.x + threadIdx.x;
        if (tid < n) {
            arr[tid] *= 2;  // Modify in place
        }
    };

    // Launch kernel (this automatically sees the unified memory)
    dim3 block(256);
    dim3 grid((N + block.x - 1) / block.x);

    // Note: In practice, you'd use a proper kernel function
    // This is just to show the concept

    // CPU can access data immediately after GPU operations
    for (int i = 0; i < 10; i++) {
        std::cout << "data[" << i << "] = " << data[i] << std::endl;
    }

    // Cleanup
    cudaFree(data);
    return 0;
