## More Complete Example with Proper Kernels

```cpp
#include <cuda_runtime.h>
#include <iostream>
#include <vector>

// Device kernel function
__global__ void increment_kernel(int* data, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        data[idx] += 100;  // Modify data in place
    }
}

__global__ void sum_kernel(const int* data, int* result, int n) {
    extern __shared__ int sdata[];

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int tid = threadIdx.x;

    sdata[tid] = (idx < n) ? data[idx] : 0;
    __syncthreads();

    // Reduce within block
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        atomicAdd(result, sdata[0]);
    }
}

int main() {
    const int N = 1000000;
    int* data;
    int* result;

    // Allocate unified memory
    cudaMallocManaged(&data, N * sizeof(int));
    cudaMallocManaged(&result, sizeof(int));

    // Initialize data on CPU
    for (int i = 0; i < N; i++) {
        data[i] = i % 100;
    }

    *result = 0;

    std::cout << "Initial sum: " << *result << std::endl;

    // Launch kernel that works on unified memory
    dim3 block(256);
    dim3 grid((N + block.x - 1) / block.x);

    // GPU kernel modifies the same memory as CPU
    increment_kernel<<<grid, block>>>(data, N);

    // Wait for kernel completion (optional, but ensures ordering)
    cudaDeviceSynchronize();

    // CPU can immediately read modified data
    std::cout << "After kernel - first 10 elements: ";
    for (int i = 0; i < 10; i++) {
        std::cout << data[i] << " ";
    }
    std::cout << std::endl;

    // Another kernel example
    sum_kernel<<<grid, block, block.x * sizeof(int)>>>(data, result, N);

    cudaDeviceSynchronize();

    std::cout << "Final sum: " << *result << std::endl;

    // Cleanup (unified memory cleanup is automatic)
    cudaFree(data);
    cudaFree(result);

    return 0;
}
```

