Here's a working example using RDTSC for cross-core timing synchronization:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <immintrin.h>
#include <unistd.h>

// Global variables to store synchronized timestamps
volatile uint64_t global_timestamp = 0;
volatile int timestamp_ready = 0;

// Function to read RDTSC with proper serialization
static inline uint64_t rdtsc_serialized(void) {
    uint32_t lo, hi;
    __asm__ volatile ("cpuid\n\t"
                     "rdtsc"
                     : "=a"(lo), "=d"(hi)
                     :: "ebx", "ecx");
    return ((uint64_t)hi << 32) | lo;
}

// Function to read RDTSC without serialization (faster, but less precise)
static inline uint64_t rdtsc_simple(void) {
    uint32_t lo, hi;
    __asm__ volatile ("rdtsc" : "=a"(lo), "=d"(hi));
    return ((uint64_t)hi << 32) | lo;
}

// Worker thread function
void* worker_thread(void* arg) {
    int thread_id = *(int*)arg;

    // Wait for timestamp to be ready
    while (!timestamp_ready) {
        __asm__ volatile ("pause" ::: "memory");
    }

    // Read timestamp from all cores
    uint64_t start_time = rdtsc_simple();

    // Do some work
    volatile int dummy = 0;
    for (int i = 0; i < 1000000; i++) {
        dummy += i;
    }

    uint64_t end_time = rdtsc_simple();

    printf("Thread %d: Start=%lu, End=%lu, Duration=%lu cycles\n", 
           thread_id, start_time, end_time, end_time - start_time);

    return NULL;
}

int main() {
    const int num_threads = 4;
    pthread_t threads[num_threads];
    int thread_ids[num_threads];

    // Initialize global timestamp
    uint64_t reference_time = rdtsc_serialized();
    global_timestamp = reference_time;
    timestamp_ready = 1;

    printf("Reference timestamp: %lu\n", reference_time);

    // Create threads
    for (int i = 0; i < num_threads; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, worker_thread, &thread_ids[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

**How it works:**

1. **RDTSC Instruction**: Reads the processor's Time Stamp Counter (TSC) which is a 64-bit register that increments at each clock cycle.

2. **Synchronization**: The main thread sets a reference timestamp and signals worker threads to proceed, ensuring all cores start measuring at roughly the same time.

3. **Serialization**: The `cpuid` instruction before `rdtsc` ensures proper serialization - it flushes the pipeline and waits for all previous instructions to complete, making timing measurements more consistent across cores.

4. **Cross-Core Timing**: All threads read their own TSC values, which are synchronized by design on modern Intel/AMD processors (assuming constant TSC and proper CPU frequency management).

**Important caveats:**
- This approach assumes constant TSC and proper CPU frequency scaling
- It may not work reliably on all systems or older CPUs
- For production use, consider using `rdtscp` instead of `rdtsc` for better ordering guarantees
- The synchronization is approximate, not perfect, due to memory model differences between cores

**Compilation:**
```bash
gcc -O2 -pthread -march=native timing_test.c -o timing_test
```

