    }

    // Reset election timeout for follower state
    private void resetElectionTimeout() {
        cancelTimeout();

        int timeout = random.nextInt(electionTimeoutMax - electionTimeoutMin) + electionTimeoutMin;
        ScheduledFuture<?> future = node.scheduler.schedule(() -> {
            if (node.state == State.FOLLOWER) {
                becomeCandidate();
            }
        }, timeout, TimeUnit.MILLISECONDS);

        timeouts.put(node.id, future);
    }

    // Cancel existing timeout
    private void cancelTimeout() {
        ScheduledFuture<?> future = timeouts.get(node.id);
        if (future != null && !future.isDone()) {
            future.cancel(false);
        }
    }

    // Become candidate and start election
    private void becomeCandidate() {
        System.out.println("Node " + node.id + " becoming CANDIDATE");
        node.state = State.CANDIDATE;
        node.currentTerm++;
