        }
    }

    // Become leader and start heartbeats
    private void becomeLeader() {
        System.out.println("Node " + node.id + " became LEADER");
        node.state = State.LEADER;

        // Initialize nextIndex for all peers
        for (int peerId : node.peers) {
            node.nextIndex.put(peerId, 0);
        }

        // Send initial heartbeat
        sendHeartbeat();

        // Schedule periodic heartbeats
        ScheduledFuture<?> heartbeat = node.scheduler.scheduleAtFixedRate(() -> {
            if (node.state == State.LEADER) {
                sendHeartbeat();
            }
        }, 0, heartbeatInterval, TimeUnit.MILLISECONDS);
    }

    // Send heartbeat to all peers
    private void sendHeartbeat() {
