Here's a minimal working example of a lease-based lock with fencing tokens in Go:

```go
package main

import (
    "context"
    "fmt"
    "math/rand"
    "sync"
    "time"
)

// Lock represents a distributed lock with fencing tokens
type Lock struct {
    mu          sync.Mutex
    holder      string
    leaseID     int64
    fencingToken int64
    ttl         time.Duration
    valid       bool
}

// LeaseManager manages locks and handles fencing
type LeaseManager struct {
    locks map[string]*Lock
    mu    sync.Mutex
    // Simulate a distributed store with a simple in-memory approach
    lockStore map[string]struct{}
}

var manager = &LeaseManager{
    locks:     make(map[string]*Lock),
    lockStore: make(map[string]struct{}),
}

// GenerateFencingToken creates a unique fencing token
func GenerateFencingToken() int64 {
    return rand.Int63()
}

// Acquire attempts to acquire a lock with lease and fencing token
func (lm *LeaseManager) Acquire(ctx context.Context, resource string, holder string, ttl time.Duration) (*Lock, error) {
    lm.mu.Lock()
    defer lm.mu.Unlock()

    // Check if already held by same holder
    if existing, exists := lm.locks[resource]; exists && existing.valid && existing.holder == holder {
        // Extend existing lease
        existing.leaseID = time.Now().UnixNano()
        existing.fencingToken = GenerateFencingToken()
        return existing, nil
    }

    // Check if resource is locked by someone else
    if _, locked := lm.lockStore[resource]; locked {
        return nil, fmt.Errorf("resource %s is already locked", resource)
    }

    // Acquire lock
    lock := &Lock{
        holder:      holder,
        leaseID:     time.Now().UnixNano(),
        fencingToken: GenerateFencingToken(),
        ttl:         ttl,
        valid:       true,
    }

    lm.locks[resource] = lock
    lm.lockStore[resource] = struct{}{}

    // Simulate background lease renewal
    go lm.renewLease(ctx, resource, lock)

    return lock, nil
}

// RenewLease automatically renews the lock lease
func (lm *LeaseManager) renewLease(ctx context.Context, resource string, lock *Lock) {
    ticker := time.NewTicker(lock.ttl / 2)
    defer ticker.Stop()

    for {
        select {
        case <-ticker.C:
            lm.mu.Lock()
            if existing, exists := lm.locks[resource]; exists && existing == lock {
                // Renew lease
                lock.leaseID = time.Now().UnixNano()
            } else {
                lm.mu.Unlock()
                return
            }
            lm.mu.Unlock()
        case <-ctx.Done():
            return
        }
    }
}

// Release releases a lock
func (lm *LeaseManager) Release(resource string, holder string, fencingToken int64) error {
    lm.mu.Lock()
    defer lm.mu.Unlock()

    lock, exists := lm.locks[resource]
    if !exists {
        return fmt.Errorf("lock not found for resource %s", resource)
    }

    // Check if the lock is still valid and held by this holder
    if !lock.valid || lock.holder != holder {
        return fmt.Errorf("lock not held by %s", holder)
    }

    // Verify fencing token (simple check - in real systems this would be more robust)
    if lock.fencingToken != fencingToken {
        return fmt.Errorf("fencing token mismatch - possible stale lock")
    }

    lock.valid = false
    delete(lm.locks, resource)
    delete(lm.lockStore, resource)

    return nil
}

// IsLocked checks if a resource is currently locked
func (lm *LeaseManager) IsLocked(resource string) bool {
    lm.mu.Lock()
    defer lm.mu.Unlock()

    _, exists := lm.lockStore[resource]
    return exists
}

// ForceRelease forcefully releases a lock (for failure scenarios)
func (lm *LeaseManager) ForceRelease(resource string) error {
    lm.mu.Lock()
    defer lm.mu.Unlock()

    if lock, exists := lm.locks[resource]; exists {
        lock.valid = false
        delete(lm.locks, resource)
        delete(lm.lockStore, resource)
        return nil
    }
    return fmt.Errorf("lock not found for resource %s", resource)
}

// Simulate a client using the lock
func clientWork(resource string, holder string, duration time.Duration) {
    ctx, cancel := context.WithCancel(context.Background())
    defer cancel()

    // Acquire lock
    lock, err := manager.Acquire(ctx, resource, holder, 3*time.Second)
    if err != nil {
        fmt.Printf("Client %s failed to acquire lock: %v\n", holder, err)
        return
    }

    fmt.Printf("Client %s acquired lock with fencing token %d\n", holder, lock.fencingToken)

    // Simulate work
    time.Sleep(duration)

    // Release lock
    err = manager.Release(resource, holder, lock.fencingToken)
    if err != nil {
        fmt.Printf("Client %s failed to release lock: %v\n", holder, err)
    } else {
        fmt.Printf("Client %s released lock\n", holder)
    }
}

// Simulate failure handling
func simulateFailureScenario() {
    fmt.Println("=== Simulating Failure Scenario ===")

    // Start two clients competing for the same resource
    go clientWork("resource1", "client1", 2*time.Second)
    go clientWork("resource1", "client2", 2*time.Second)

    time.Sleep(5 * time.Second)

    // Force release to simulate failure
    fmt.Println("Force releasing lock due to failure...")
    manager.ForceRelease("resource1")

    // Now acquire again
    ctx, cancel := context.WithCancel(context.Background())
    defer cancel()

    lock, err := manager.Acquire(ctx, "resource1", "client3", 3*time.Second)
    if err != nil {
        fmt.Printf("Client3 failed to acquire lock: %v\n", err)
        return
    }

    fmt.Printf("Client3 acquired lock with fencing token %d after failure recovery\n", lock.fencingToken)

    time.Sleep(2 * time.Second)
    manager.Release("resource1", "client3", lock.fencingToken)
}

func main() {
    // Test basic lock acquisition and release
    fmt.Println("=== Basic Lock Test ===")

    ctx, cancel := context.WithCancel(context.Background())
    defer cancel()

    lock, err := manager.Acquire(ctx, "test-resource", "test-client", 5*time.Second)
    if err != nil {
        fmt.Printf("Failed to acquire lock: %v\n", err)
        return
    }

    fmt.Printf("Acquired lock with fencing token: %d\n", lock.fencingToken)
    fmt.Printf("Lock is valid: %t\n", lock.valid)

    // Test concurrent access
    go clientWork("test-resource", "client1", 1*time.Second)

    time.Sleep(2 * time.Second)

    err = manager.Release("test-resource", "test-client", lock.fencingToken)
    if err != nil {
        fmt.Printf("Failed to release lock: %v\n", err)
    } else {
        fmt.Printf("Released lock successfully\n")
    }

    // Test failure scenario
    fmt.Println()
    simulateFailureScenario()
}
```

This example demonstrates:

## Key Features:

1. **Lease-based locking**: Locks have TTL (Time To Live) periods
2. **Fencing tokens**: Unique tokens generated for each lock acquisition
3. **Failure handling**:
   - Lease renewal in background
   - Force release mechanism
   - Token validation to prevent stale locks
   - Context cancellation support

## Key Components:

- **Lock struct**: Contains holder info, lease ID, fencing token, TTL, and validity flag
- **LeaseManager**: Central manager for lock operations
- **Acquire**: Gets a lock with lease and fencing token
- **Release**: Releases lock with token validation
- **RenewLease**: Automatically renews locks before expiration
- **ForceRelease**: Handles failure scenarios by forcibly releasing locks

## Failure Handling:

1. **Lease expiration**: Background renewal prevents stale locks
2. **Network failures**: Force release mechanism handles lost connections
3. **Token validation**: Prevents operations on stale locks
4. **Context cancellation**: Graceful shutdown of background processes

## Usage Notes:

- In production, replace in-memory store with actual distributed storage (etcd, Redis, etc.)
- Add proper error logging and metrics
- Implement more robust fencing token generation and validation
- Consider using `context.WithTimeout` for better timeout control
- Add retry logic for transient failures

