I'll help you implement a simplified Byzantine Fault Tolerance (BFT) system based on PBFT principles. Here's a complete implementation with clear failure handling:

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <queue>
#include <chrono>
#include <thread>
#include <random>
#include <algorithm>
#include <functional>

// Message types for PBFT protocol
enum class MessageType {
    REQUEST,
    PREPREPARE,
    PREPARE,
    COMMIT,
    REPLY
};

// Message structure
struct Message {
    MessageType type;
    int sender_id;
    int sequence_number;
    std::string request_data;
    std::vector<unsigned char> signature; // Simplified signature

    Message(MessageType t, int id, int seq, const std::string& data = "")
        : type(t), sender_id(id), sequence_number(seq), request_data(data) {}
};

// Node class representing each participant
class PBFTNode {
private:
    int node_id;
    int total_nodes;
    int faulty_threshold; // f nodes can be faulty
    std::vector<bool> is_faulty;

    // Message queues for communication
    std::unordered_map<int, std::queue<Message>> message_queues;

    // State tracking
    std::unordered_map<int, std::vector<Message>> preprepare_messages;
    std::unordered_map<int, std::vector<Message>> prepare_messages;
    std::unordered_map<int, std::vector<Message>> commit_messages;

    // Request tracking
    std::unordered_map<int, std::string> executed_requests;

    // Random number generator for fault simulation
    std::mt19937 rng;

public:
    PBFTNode(int id, int num_nodes) 
        : node_id(id), total_nodes(num_nodes) {
        faulty_threshold = (num_nodes - 1) / 3; // f = (n-1)/3
        rng.seed(std::chrono::steady_clock::now().time_since_epoch().count());

        // Initialize fault status (simulate some nodes being faulty)
        is_faulty.resize(num_nodes, false);
        simulate_faults();
    }

    void simulate_faults() {
        // Randomly mark some nodes as faulty
        int faulty_count = 0;
        for (int i = 0; i < total_nodes && faulty_count < faulty_threshold; ++i) {
            if (std::uniform_int_distribution<int>(0, 1)(rng) && i != node_id) {
                is_faulty[i] = true;
                faulty_count++;
            }
        }
    }

    bool is_node_faulty(int node_id) const {
        return is_faulty[node_id];
    }

    // Simulate network communication
    void send_message(const Message& msg, int receiver_id) {
        if (receiver_id != node_id && !is_node_faulty(receiver_id)) {
            message_queues[receiver_id].push(msg);
        }
    }

    // Process incoming messages
    bool process_messages() {
        bool processed = false;
        auto& queue = message_queues[node_id];

        while (!queue.empty()) {
            Message msg = queue.front();
            queue.pop();

            switch (msg.type) {
                case MessageType::REQUEST:
                    handle_request(msg);
                    break;
                case MessageType::PREPREPARE:
                    handle_preprepare(msg);
                    break;
                case MessageType::PREPARE:
                    handle_prepare(msg);
                    break;
                case MessageType::COMMIT:
                    handle_commit(msg);
                    break;
                default:
                    std::cout << "Node " << node_id << ": Unknown message type\n";
                    break;
            }
            processed = true;
        }
        return processed;
    }

private:
    // Handle client request
    void handle_request(const Message& msg) {
        if (is_node_faulty(node_id)) {
            std::cout << "Node " << node_id << ": Faulty node, ignoring request\n";
            return;
        }

        // Primary node handles the request
        int primary = node_id % total_nodes; // Simplified primary selection

        if (primary == node_id) {
            // Preprepare phase
            Message preprepare_msg(MessageType::PREPREPARE, node_id, 
                                 msg.sequence_number, msg.request_data);
            broadcast_message(preprepare_msg);

            // Immediately start prepare phase
            Message prepare_msg(MessageType::PREPARE, node_id, 
                              msg.sequence_number, msg.request_data);
            broadcast_message(prepare_msg);
        } else {
            // Non-primary nodes just forward the request to primary
            std::cout << "Node " << node_id << ": Forwarding request to primary\n";
        }
    }

    // Handle preprepare message
    void handle_preprepare(const Message& msg) {
        if (is_node_faulty(node_id)) {
            return;
        }

        // Store preprepare message
        preprepare_messages[msg.sequence_number].push_back(msg);

        // Check if we have 2f+1 preprepare messages (simplified)
        if (preprepare_messages[msg.sequence_number].size() >= 
            total_nodes - faulty_threshold) {

            // Start prepare phase
            Message prepare_msg(MessageType::PREPARE, node_id, 
                              msg.sequence_number, msg.request_data);
            broadcast_message(prepare_msg);
        }
    }

    // Handle prepare message
    void handle_prepare(const Message& msg) {
        if (is_node_faulty(node_id)) {
            return;
        }

        // Store prepare message
        prepare_messages[msg.sequence_number].push_back(msg);

        // Check if we have 2f+1 prepare messages
        if (prepare_messages[msg.sequence_number].size() >= 
            total_nodes - faulty_threshold) {

            // Start commit phase
            Message commit_msg(MessageType::COMMIT, node_id, 
                             msg.sequence_number, msg.request_data);
            broadcast_message(commit_msg);
        }
    }

    // Handle commit message
    void handle_commit(const Message& msg) {
        if (is_node_faulty(node_id)) {
            return;
        }

        // Store commit message
        commit_messages[msg.sequence_number].push_back(msg);

        // Check if we have 2f+1 commit messages
        if (commit_messages[msg.sequence_number].size() >= 
            total_nodes - faulty_threshold) {

            // Execute the request
            execute_request(msg);
        }
    }

    void execute_request(const Message& msg) {
        if (executed_requests.find(msg.sequence_number) != executed_requests.end()) {
            return; // Already executed
        }

        executed_requests[msg.sequence_number] = msg.request_data;
        std::cout << "Node " << node_id 
                  << ": Executing request #" << msg.sequence_number 
                  << " with data: " << msg.request_data << "\n";
    }

    void broadcast_message(const Message& msg) {
        for (int i = 0; i < total_nodes; ++i) {
            if (i != node_id && !is_node_faulty(i)) {
                send_message(msg, i);
            }
        }
    }

public:
    // Main PBFT consensus function
    void execute_consensus(const std::string& request_data, int sequence_number) {
        if (is_node_faulty(node_id)) {
            std::cout << "Node " << node_id << ": Faulty node, skipping consensus\n";
            return;
        }

        Message request_msg(MessageType::REQUEST, node_id, sequence_number, request_data);
        send_message(request_msg, node_id); // Process locally first

        // Simulate network propagation
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }

    // Get current state information
    void print_state() {
        std::cout << "Node " << node_id << " State:\n";
        std::cout << "  Faulty nodes: ";
        for (int i = 0; i < total_nodes; ++i) {
            if (is_faulty[i]) std::cout << i << " ";
        }
        std::cout << "\n";
        std::cout << "  Executed requests: " << executed_requests.size() << "\n";
        std::cout << "  Fault tolerance threshold: " << faulty_threshold << "\n\n";
    }
};

// PBFT System class managing multiple nodes
class PBFTSystem {
private:
    std::vector<PBFTNode> nodes;
    int total_nodes;

public:
    PBFTSystem(int num_nodes) : total_nodes(num_nodes) {
        if (num_nodes < 4) {
            throw std::invalid_argument("PBFT requires at least 4 nodes (n >= 3f + 1)");
        }

        for (int i = 0; i < num_nodes; ++i) {
            nodes.emplace_back(i, num_nodes);
        }
    }

    void run_consensus(const std::string& request_data) {
        static int sequence_counter = 0;
        int seq_num = ++sequence_counter;

        std::cout << "=== Starting PBFT Consensus for request: " 
                  << request_data << " (seq #" << seq_num << ") ===\n";

        // Execute consensus on all nodes
        for (auto& node : nodes) {
            node.execute_consensus(request_data, seq_num);
        }

        // Process messages in a loop until completion
        int max_iterations = 100;
        for (int i = 0; i < max_iterations; ++i) {
            bool any_processed = false;
            for (auto& node : nodes) {
                if (node.process_messages()) {
                    any_processed = true;
                }
            }

            if (!any_processed) break;

            // Small delay to allow message processing
            std::this_thread::sleep_for(std::chrono::milliseconds(5));
        }

        std::cout << "=== Consensus completed ===\n\n";
    }

    void print_system_state() {
        std::cout << "=== PBFT System State ===\n";
        std::cout << "Total nodes: " << total_nodes << "\n";
        std::cout << "Fault tolerance (f): " << (total_nodes - 1) / 3 << "\n\n";

        for (auto& node : nodes) {
            node.print_state();
        }
    }
};

