/**
 * Lamport Clock Implementation for Total Order Consistency
 * 
 * This implementation demonstrates how to maintain logical timestamps
 * to establish a partial ordering of events across distributed processes.
 */

class LamportClock {
    constructor(processId) {
        this.processId = processId;
        this.clock = 0;
    }

    /**
     * Get current timestamp
     * @returns {number} Current clock value + 1
     */
    getTimestamp() {
        this.clock += 1;
        return this.clock;
    }

    /**
     * Update clock based on received message timestamp
     * @param {number} receivedTimestamp - Timestamp from incoming message
     */
    updateTimestamp(receivedTimestamp) {
        try {
            if (typeof receivedTimestamp !== 'number' || isNaN(receivedTimestamp)) {
                throw new Error('Invalid timestamp received: must be a valid number');
            }

            this.clock = Math.max(this.clock, receivedTimestamp) + 1;
        } catch (error) {
            console.error(`Failed to update timestamp: ${error.message}`);
            // Fallback: increment clock by 1
            this.clock += 1;
        }
    }

    /**
     * Get current clock value (for debugging)
     * @returns {number} Current clock value
     */
    getValue() {
        return this.clock;
    }
}

/**
 * Message Queue with Lamport Clock ordering
 */
class OrderedMessageQueue {
    constructor(processId) {
        this.processId = processId;
        this.clock = new LamportClock(processId);
        this.messageQueue = [];
    }

    /**
     * Send a message with timestamp
     * @param {string} content - Message content
     * @returns {Object} Message object with timestamp
     */
    sendMessage(content) {
        try {
            const timestamp = this.clock.getTimestamp();
            const message = {
                id: `${this.processId}-${timestamp}`,
                content,
                timestamp,
                sender: this.processId,
                receivedAt: Date.now()
            };

            console.log(`[SEND] ${message.id}: ${content}`);
            return message;
        } catch (error) {
            console.error(`Failed to send message: ${error.message}`);
            throw new Error('Message sending failed due to clock error');
        }
    }

    /**
     * Receive and process a message
     * @param {Object} message - Message object with timestamp
     */
    receiveMessage(message) {
        try {
            // Validate message structure
            if (!message || !message.timestamp || !message.content) {
                throw new Error('Invalid message structure');
            }

            // Update local clock based on received timestamp
            this.clock.updateTimestamp(message.timestamp);

            // Add to queue with ordering info
            const orderedMessage = {
                ...message,
                orderedTimestamp: this.clock.getValue(),
                processedAt: Date.now()
            };

            this.messageQueue.push(orderedMessage);

            console.log(`[RECEIVE] ${orderedMessage.id}: ${orderedMessage.content} (ordered: ${orderedMessage.orderedTimestamp})`);

        } catch (error) {
            console.error(`Failed to process message: ${error.message}`);
            // Continue processing other messages
        }
    }

    /**
     * Get ordered messages (simulated total order)
     * @returns {Array} Ordered messages
     */
    getOrderedMessages() {
        try {
            return [...this.messageQueue].sort((a, b) => a.orderedTimestamp - b.orderedTimestamp);
        } catch (error) {
            console.error(`Failed to sort messages: ${error.message}`);
            return this.messageQueue;
        }
    }

    /**
     * Get current clock value
     * @returns {number} Current clock value
     */
    getClockValue() {
        return this.clock.getValue();
    }
}

