typedef struct {
    atomic_int* proposals;
    atomic_int* decisions;
    int num_processes;
} consensus_state_t;

// Initialize consensus state
consensus_state_t* consensus_init(int num_processes) {
    consensus_state_t* state = malloc(sizeof(consensus_state_t));
    state->num_processes = num_processes;

    state->proposals = calloc(num_processes, sizeof(atomic_int));
    state->decisions = calloc(num_processes, sizeof(atomic_int));

    // Initialize all proposals to 0
    for (int i = 0; i < num_processes; i++) {
        atomic_init(&state->proposals[i], 0);
        atomic_init(&state->decisions[i], 0);
    }

    return state;
}

// Cleanup consensus state
void consensus_destroy(consensus_state_t* state) {
    free(state->proposals);
    free(state->decisions);
    free(state);
}

// Wait-free consensus algorithm using CAS
int consensus_propose(consensus_state_t* state, int process_id, int proposal_value) {
    // Set the proposal value for this process
    atomic_store(&state->proposals[process_id], proposal_value);

    // Try to reach consensus by finding a common value
    int max_seen = 0;
    int count = 0;

    // This is a simplified version - in practice, you'd use a more sophisticated 
    // approach like the one described in the paper "Wait-Free Consensus with 
    // O(n) Expected Time" or similar algorithms

    for (int attempt = 0; attempt < state->num_processes * 2; attempt++) {
        int current_max = 0;
        count = 0;

        // Scan all proposals to find the maximum
        for (int i = 0; i < state->num_processes; i++) {
            int value = atomic_load(&state->proposals[i]);
            if (value > current_max) {
                current_max = value;
            }
            if (value != 0) {
                count++;
            }
        }

        // If we have enough non-zero proposals, decide
        if (count >= state->num_processes / 2 + 1) {
            int decision_value = current_max;

            // Try to set the decision using CAS - this is where we ensure atomicity
            int expected = 0;
            if (atomic_compare_exchange_strong(&state->decisions[process_id], 
                                              &expected, decision_value)) {
                return decision_value;
            }
        }

        // Add some small delay to avoid busy-waiting in a real implementation
        // usleep(1000);
    }

    // Fallback: return the highest proposal value
    int final_max = 0;
    for (int i = 0; i < state->num_processes; i++) {
        int value = atomic_load(&state->proposals[i]);
        if (value > final_max) {
            final_max = value;
        }
    }

    return final_max;
}

