typedef struct {
    atomic_int* values;
    atomic_int* status;
    int num_processes;
    int max_value;
} waitfree_consensus_t;

waitfree_consensus_t* waitfree_init(int num_processes, int max_val) {
    waitfree_consensus_t* consensus = malloc(sizeof(waitfree_consensus_t));
    consensus->num_processes = num_processes;
    consensus->max_value = max_val;

    consensus->values = calloc(num_processes, sizeof(atomic_int));
    consensus->status = calloc(num_processes, sizeof(atomic_int));

    for (int i = 0; i < num_processes; i++) {
        atomic_init(&consensus->values[i], 0);
        atomic_init(&consensus->status[i], 0); // 0=unproposed, 1=proposed, 2=decided
    }

    return consensus;
}

void waitfree_destroy(waitfree_consensus_t* consensus) {
    free(consensus->values);
    free(consensus->status);
    free(consensus);
}

// Wait-free consensus with better failure handling
int waitfree_consensus_propose(waitfree_consensus_t* consensus, 
                              int process_id, int proposal_value) {

    // Bounds checking
    if (proposal_value < 0 || proposal_value > consensus->max_value) {
        return -1; // Invalid proposal
    }

    // Set the proposal
    atomic_store(&consensus->values[process_id], proposal_value);
    atomic_store(&consensus->status[process_id], 1); // Mark as proposed

    // Find minimum value that has been proposed by majority of processes
    int min_proposed = consensus->max_value + 1;
    int proposed_count = 0;

    for (int i = 0; i < consensus->num_processes; i++) {
        int status = atomic_load(&consensus->status[i]);
        if (status == 1) { // Process has proposed
            int value = atomic_load(&consensus->values[i]);
            if (value > 0 && value < min_proposed) {
                min_proposed = value;
            }
            proposed_count++;
        }
    }

    // If we have majority of proposals, try to decide
    if (proposed_count >= consensus->num_processes / 2 + 1) {
        int expected = 0;
        int decision_value = min_proposed;

        // Attempt to set decision using CAS - this ensures atomicity
        if (atomic_compare_exchange_strong(&consensus->values[process_id], 
                                          &expected, decision_value)) {
            atomic_store(&consensus->status[process_id], 2); // Mark as decided
            return decision_value;
        }
    }

    // Return the proposed value if we can't reach consensus immediately
    return proposal_value;
}

