```java
import java.util.HashMap;
import java.util.Map;

public class DiscreteLogarithm {

    /**
     * Computes discrete logarithm using baby-step giant-step algorithm
     * Finds x such that base^x ≡ target (mod p)
     */
    public static int discreteLog(int base, int target, int p) {
        // Precompute baby steps: base^j mod p for j = 0, 1, ..., m-1
        int m = (int) Math.ceil(Math.sqrt(p));
        Map<Integer, Integer> babySteps = new HashMap<>();

        long power = 1;
        for (int j = 0; j < m; j++) {
            if (babySteps.containsKey((int) power)) {
                // Handle case where we might have duplicate values
                // In practice, this shouldn't happen in prime groups
            } else {
                babySteps.put((int) power, j);
            }
            power = (power * base) % p;
        }

        // Compute giant step multiplier: base^(-m) mod p
        long baseM = modPow(base, m, p);
        long invBaseM = modInverse(baseM, p);

        // Search for match
        long current = target;
        for (int i = 0; i < m; i++) {
            if (babySteps.containsKey((int) current)) {
                int j = babySteps.get((int) current);
                return i * m + j;
            }
            current = (current * invBaseM) % p;
        }

        return -1; // No solution found
    }

    /**
     * Fast modular exponentiation
     */
    private static long modPow(long base, long exp, long mod) {
        long result = 1;
        base = base % mod;
        while (exp > 0) {
            if (exp % 2 == 1) {
                result = (result * base) % mod;
            }
            exp = exp >> 1;
            base = (base * base) % mod;
        }
        return result;
    }

    /**
     * Modular multiplicative inverse
     */
    private static long modInverse(long a, long mod) {
        return modPow(a, mod - 2, mod);
    }

    public static void main(String[] args) {
        // Example: Find x such that 3^x ≡ 12 (mod 17)
        int base = 3;
        int target = 12;
        int p = 17;

        int result = discreteLog(base, target, p);
        System.out.println("Discrete log of " + target + " base " + base + 
                          " mod " + p + " is: " + result);

        // Verify
        long verification = modPow(base, result, p);
        System.out.println("Verification: 3^" + result + " ≡ " + verification + " (mod 17)");
    }
}
```

This implementation:

- Uses the baby-step giant-step algorithm for discrete logarithm computation
- Works in a 16-bit group (though the example uses p=17 for demonstration)
- Includes helper functions for modular exponentiation and modular inverse
- Returns -1 if no solution exists
- Includes verification in the main method

The time complexity is O(√p) and space complexity is O(√p), making it suitable for small groups like 16-bit numbers. The algorithm works by precomputing baby steps (base^j mod p) and then searching for matches with giant steps (target * base^(-im) mod p).

