I'll show you how to implement a HyperLogLog sketch in C++ for counting distinct elements in a stream with minimal memory usage.

```cpp
#include <iostream>
#include <vector>
#include <cstdint>
#include <cstring>
#include <algorithm>

class HyperLogLog {
private:
    static const int DEFAULT_P = 14;  // Precision parameter (14 bits = 16,384 registers)
    static const int DEFAULT_M = 1 << DEFAULT_P;  // Number of registers

    std::vector<uint8_t> registers;
    int p;
    int m;

    // Hash function to map elements to register indices
    uint32_t hash(const std::string& element) const {
        uint32_t hash = 0;
        for (char c : element) {
            hash = hash * 31 + static_cast<uint32_t>(c);
        }
        return hash;
    }

    // Get the index of the register using the first 'p' bits
    int get_register_index(uint32_t hash_value) const {
        return hash_value & (m - 1);  // m-1 = 2^p - 1
    }

    // Count leading zeros in the remaining bits after the index
    int count_leading_zeros(uint32_t hash_value, int index) const {
        uint32_t remaining_bits = hash_value >> p;
        if (remaining_bits == 0) return 32 - p;  // All remaining bits are zero

        int zeros = 0;
        while ((remaining_bits & 1) == 0) {
            remaining_bits >>= 1;
            zeros++;
        }
        return zeros + 1;  // Add 1 because we start counting from the first non-zero bit
    }

public:
    // Constructor with custom precision
    explicit HyperLogLog(int precision = DEFAULT_P) : p(precision), m(1 << precision) {
        registers.resize(m, 0);
    }

    // Add an element to the sketch
    void add(const std::string& element) {
        uint32_t hash_value = hash(element);
        int index = get_register_index(hash_value);
        int rank = count_leading_zeros(hash_value, index);

        // Update register if we found a larger rank
        if (rank > registers[index]) {
            registers[index] = static_cast<uint8_t>(rank);
        }
    }

    // Add an integer element
    void add(int value) {
        std::string str = std::to_string(value);
        add(str);
    }

    // Estimate the number of distinct elements
    double estimate() const {
        // Calculate the harmonic mean of all register values
        double sum = 0.0;
        for (int i = 0; i < m; i++) {
            sum += 1.0 / (1 << registers[i]);
        }

        double estimate = alpha_m(m) * (m * m) / sum;

        // Apply corrections for small and large estimates
        if (estimate <= 2.5 * m) {
            // Small range correction
            int zeros = count_zeros();
            if (zeros != 0) {
                estimate = m * std::log(static_cast<double>(m) / zeros);
            }
        } else if (estimate > (1/30.0) * (1ULL << 32)) {
            // Large range correction
            estimate = -1 * (1ULL << 32) * std::log(1.0 - estimate / (1ULL << 32));
        }

        return estimate;
    }

private:
    // Alpha values for different m sizes (precomputed)
    double alpha_m(int m) const {
        switch(m) {
            case 16: return 0.673;
            case 32: return 0.697;
            case 64: return 0.709;
            default: return 0.7213 / (1.0 + 1.079 / m);
        }
    }

    // Count zeros in registers (for small range correction)
    int count_zeros() const {
        int count = 0;
        for (int i = 0; i < m; i++) {
            if (registers[i] == 0) count++;
        }
        return count;
    }
};

// Simple example usage
int main() {
    // Create HyperLogLog sketch with precision 14 (16,384 registers)
    HyperLogLog hll(14);

    // Add elements to the stream
    std::vector<std::string> stream = {
        "apple", "banana", "cherry", "date", "elderberry",
        "fig", "grape", "honeydew", "kiwi", "lemon",
        "mango", "nectarine", "orange", "papaya", "quince",
        "raspberry", "strawberry", "tangerine", "watermelon", "xigua",
        "yuzu", "zucchini", "apple", "banana", "cherry"  // Some duplicates
    };

    std::cout << "Adding elements to stream:\n";
    for (const auto& element : stream) {
        hll.add(element);
        std::cout << "Added: " << element << std::endl;
    }

    // Get the estimate
    double estimate = hll.estimate();
    std::cout << "\nEstimated number of distinct elements: " << estimate << std::endl;

    // Compare with actual count
    std::set<std::string> unique_elements(stream.begin(), stream.end());
    std::cout << "Actual number of distinct elements: " << unique_elements.size() << std::endl;

    return 0;
}
```

