    int blockSize = 256;
    int gridSize = (N + blockSize - 1) / blockSize;
    addTenKernel<<<gridSize, blockSize, 0, stream>>>(d_input, d_output, N);

    // Synchronize the stream (waits for all operations to complete)
    cudaStreamSynchronize(stream);

    // Copy result back to host
    cudaMemcpy(h_output.data(), d_output, dataSize, cudaMemcpyDeviceToHost);

    // Verify results
    bool success = true;
    for (int i = 0; i < N; i++) {
        if (h_output[i] != h_input[i] + 10) {
            success = false;
            break;
        }
    }

    if (success) {
        std::cout << "Success! First 5 results: ";
        for (int i = 0; i < 5; i++) {
            std::cout << h_output[i] << " ";
        }
        std::cout << std::endl;
    } else {
        std::cout << "Error in computation!" << std::endl;
    }

    // Cleanup
    cudaFree(d_input);
    cudaFree(d_output);
    cudaStreamDestroy(stream);

    return 0;
}
```

## Key Points Explained:

### 1. **Memory Allocation**
```cpp
cudaMalloc(&d_input, dataSize);
cudaMalloc(&d_output, dataSize);
```
- Allocates memory on the GPU
- `d_input` and `d_output` are device pointers

### 2. **Stream Creation**
```cpp
