Here's a cache-blocked matrix multiply tuned for L1/L2 caches:

```c
#define BLOCK_SIZE 64
#define L1_SIZE 32768  // 32KB L1
#define L2_SIZE 262144 // 256KB L2

void blocked_matmul(float* A, float* B, float* C, int N) {
    float *B_block = malloc(BLOCK_SIZE * BLOCK_SIZE * sizeof(float));

    for (int ii = 0; ii < N; ii += BLOCK_SIZE) {
        for (int jj = 0; jj < N; jj += BLOCK_SIZE) {
            // Load B block into cache
            for (int i = 0; i < BLOCK_SIZE && ii + i < N; i++) {
                for (int j = 0; j < BLOCK_SIZE && jj + j < N; j++) {
                    B_block[i * BLOCK_SIZE + j] = B[(ii + i) * N + (jj + j)];
                }
            }

            for (int k = 0; k < N; k += BLOCK_SIZE) {
                for (int i = 0; i < BLOCK_SIZE && ii + i < N; i++) {
                    for (int j = 0; j < BLOCK_SIZE && jj + j < N; j++) {
                        float sum = 0;
                        for (int l = 0; l < BLOCK_SIZE && k + l < N; l++) {
                            sum += A[(ii + i) * N + (k + l)] * B_block[i * BLOCK_SIZE + j];
                        }
                        C[(ii + i) * N + (jj + j)] += sum;
                    }
                }
            }
        }
    }
    free(B_block);
}
```

This uses a 64x64 block size optimized for typical L1/L2 cache sizes. The key insight is to load chunks of B into fast cache before computing dot products, reducing memory traffic and improving cache hit rates.

