Here's a complete implementation:

```rust
use subtle::ConstantTimeEq;

fn constant_time_compare(a: &[u8], b: &[u8]) -> bool {
    // Handle different lengths - this is constant time
    let equal_length = a.len().ct_eq(&b.len());

    // If lengths differ, return false immediately (constant time)
    if equal_length.unwrap_u8() == 0 {
        return false;
    }

    // Compare each byte using constant-time operations
    let mut result = subtle::CtOption::new(1u8, 1u8.into()); // Start with true

    for (byte_a, byte_b) in a.iter().zip(b.iter()) {
        let equal_bytes = byte_a.ct_eq(byte_b);
        // If any byte differs, the result becomes false
        result = result.and(subtle::CtOption::new(1u8, equal_bytes.into()));
    }

    // This is a simplified version - better to use the built-in approach below
    a.ct_eq(b)
}

// Simpler and more idiomatic approach:
use subtle::{ConstantTimeEq, ConstantTimeLess};

fn secure_compare(a: &[u8], b: &[u8]) -> bool {
    // First check if lengths are equal (constant time)
    let len_equal = a.len().ct_eq(&b.len());

    // If lengths differ, return false
    if len_equal.unwrap_u8() == 0 {
        return false;
    }

    // Compare the actual contents
    a.ct_eq(b).unwrap_u8() == 1
}

// Even simpler - use the built-in comparison directly:
fn secure_compare_simple(a: &[u8], b: &[u8]) -> bool {
    a.ct_eq(b).into()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_constant_time_compare() {
        let a = b"hello";
        let b = b"hello";
        let c = b"world";

        assert!(secure_compare_simple(a, b));
        assert!(!secure_compare_simple(a, c));
        assert!(!secure_compare_simple(&[1, 2, 3], &[1, 2]));
    }
}
```

