## More Robust Connection with Reconnection Logic

```javascript
const WebSocket = require('ws');

class ReliableWebSocket {
    constructor(url, options = {}) {
        this.url = url;
        this.options = options;
        this.ws = null;
        this.reconnectAttempts = 0;
        this.maxReconnectAttempts = 5;
        this.reconnectDelay = 1000;

        this.connect();
    }

    connect() {
        this.ws = new WebSocket(this.url, this.options);

        this.ws.on('open', () => {
            console.log('WebSocket connected');
            this.reconnectAttempts = 0; // Reset on successful connection
        });

        this.ws.on('message', (data) => {
            console.log('Received:', data.toString());
            // Handle your messages here
            this.handleMessage(data);
        });

        this.ws.on('close', () => {
            console.log('WebSocket disconnected');
            this.reconnect();
        });

        this.ws.on('error', (err) => {
            console.error('WebSocket error:', err);
        });
    }

    handleMessage(data) {
        // Override this method to handle incoming messages
        console.log('Processing message:', data.toString());
    }

    reconnect() {
        if (this.reconnectAttempts < this.maxReconnectAttempts) {
            this.reconnectAttempts++;
            console.log(`Attempting to reconnect... (${this.reconnectAttempts}/${this.maxReconnectAttempts})`);

            setTimeout(() => {
                this.connect();
            }, this.reconnectDelay * this.reconnectAttempts); // Exponential backoff
        } else {
            console.error('Max reconnection attempts reached');
        }
    }

    send(data) {
        if (this.ws && this.ws.readyState === WebSocket.OPEN) {
            this.ws.send(data);
        } else {
            console.warn('WebSocket not connected, cannot send data');
        }
    }

    close() {
        if (this.ws) {
            this.ws.close();
        }
    }
}

// Usage
const client = new ReliableWebSocket('ws://localhost:8080');

// Send messages
setTimeout(() => {
    client.send('Hello from client!');
}, 1000);
```

## Server Example (for testing)

```javascript
const WebSocket = require('ws');

const wss = new WebSocket.Server({ port: 8080 });

wss.on('connection', function connection(ws) {
    console.log('New client connected');

    ws.on('message', function incoming(message) {
        console.log('Received:', message.toString());

        // Echo the message back
        ws.send(`Server received: ${message}`);
    });

    ws.on('close', function close() {
        console.log('Client disconnected');
    });

    ws.on('error', function error(err) {
        console.error('WebSocket error:', err);
    });
});

console.log('WebSocket server running on ws://localhost:8080');
```

## Key Features Explained

- **`open`**: Triggered when connection is established
- **`message`**: Triggered when receiving data
- **`close`**: Triggered when connection closes
- **`error`**: Triggered when errors occur
- **Reconnection logic**: Automatically attempts to reconnect
- **Ready state checking**: Ensures messages are only sent when connected

## Common Use Cases

```javascript
// Sending different types of data
ws.send('string message');
ws.send(JSON.stringify({type: 'message', content: 'Hello'}));
ws.send(Buffer.from('binary data'));

// Checking connection status
if (ws.readyState === WebSocket.OPEN) {
    ws.send('Message can be sent');
}

// Closing connection
ws.close();
```

This setup gives you a robust WebSocket client that handles reconnections automatically and provides proper error handling.

