Here's how to create and sign a JWT using the `jose` library with EdDSA:

```javascript
// First, install the jose package:
// npm install jose

const { SignJWT, importPKCS8 } = require('jose');

// Generate or use an existing Ed25519 key pair
// For demonstration, I'll show both approaches

async function createEdDSASignature() {
  // Option 1: Using a pre-generated key (replace with your actual private key)
  const privateKeyPem = `-----BEGIN PRIVATE KEY-----
MC4CAQAwBQYDK2VwBCIEINd3FJ5rK7v6s8t0Hq9Dk8m0p5x8j8p1g9z8f4u2y7a3
-----END PRIVATE KEY-----`;

  // Option 2: Generate a new key pair (for testing only)
  /*
  const { generateKeyPair } = require('crypto');
  const { privateKey, publicKey } = generateKeyPairSync('ed25519');
  const privateKeyPem = privateKey.export({ format: 'pem', type: 'pkcs8' });
  */

  try {
    // Import the private key
    const privateKey = await importPKCS8(privateKeyPem, 'EdDSA');

    // Create the JWT payload
    const payload = {
      sub: '1234567890',
      name: 'John Doe',
      admin: true,
      exp: Math.floor(Date.now() / 1000) + 3600, // Expires in 1 hour
      iat: Math.floor(Date.now() / 1000),
    };

    // Create and sign the JWT
    const jwt = await new SignJWT(payload)
      .setProtectedHeader({ alg: 'EdDSA' })
      .setIssuedAt()
      .setExpirationTime('1h')
      .sign(privateKey);

    console.log('Signed JWT:', jwt);
    return jwt;

  } catch (error) {
    console.error('Error creating JWT:', error);
  }
}

// Alternative approach using a key pair from file
async function createJWTFromFile() {
  const fs = require('fs');

  try {
    // Read private key from file
    const privateKeyPem = fs.readFileSync('./private-key.pem', 'utf8');
    const privateKey = await importPKCS8(privateKeyPem, 'EdDSA');

    const payload = {
      sub: 'user123',
      email: 'user@example.com',
      role: 'member'
    };

    const jwt = await new SignJWT(payload)
      .setProtectedHeader({ alg: 'EdDSA' })
      .setIssuedAt()
      .setExpirationTime('24h')
      .sign(privateKey);

    console.log('JWT:', jwt);
    return jwt;

  } catch (error) {
    console.error('Error:', error);
  }
}

// Run the function
createEdDSASignature();

// For more complex scenarios, you can also:
async function createAdvancedJWT() {
  const privateKeyPem = `-----BEGIN PRIVATE KEY-----
MC4CAQAwBQYDK2VwBCIEINd3FJ5rK7v6s8t0Hq9Dk8m0p5x8j8p1g9z8f4u2y7a3
-----END PRIVATE KEY-----`;

  const privateKey = await importPKCS8(privateKeyPem, 'EdDSA');

  const payload = {
    iss: 'your-issuer',
    sub: 'subject-id',
    aud: 'your-audience',
    exp: Math.floor(Date.now() / 1000) + 3600,
    iat: Math.floor(Date.now() / 1000),
    jti: 'unique-token-id',
    customClaim: 'custom-value'
  };

  const jwt = await new SignJWT(payload)
    .setProtectedHeader({ 
      alg: 'EdDSA',
      kid: 'key-id' // Key identifier
    })
    .sign(privateKey);

  console.log('Advanced JWT:', jwt);
  return jwt;
}
```

**Important Notes:**

1. **Key Generation**: You'll need an Ed25519 key pair. Generate one using:
```bash
# Generate Ed25519 key pair
openssl genpkey -algorithm ED25519 -out private-key.pem
openssl pkey -in private-key.pem -pubout -out public-key.pem
```

2. **Key Format**: The `jose` library expects keys in PEM format with PKCS#8 structure.

3. **Dependencies**: Make sure you have the required packages:
```bash
npm install jose
```

4. **Common Header Parameters**:
   - `alg`: Algorithm ('EdDSA')
   - `kid`: Key identifier (optional but recommended)
   - `typ`: Token type (usually 'JWT')

5. **Payload Claims**:
   - `iss`: Issuer
   - `sub`: Subject
   - `aud`: Audience
   - `exp`: Expiration time
   - `iat`: Issued at
   - `jti`: JWT ID

The resulting JWT will be a compact string that you can use for authentication, authorization, or other purposes. The EdDSA algorithm is particularly secure and efficient for JWT signing.

