```

```rust
// main.rs
use tokio::task;

#[tokio::main]
async fn main() {
    let mut handles = vec![];

    // Spawn 10 async tasks
    for i in 0..10 {
        let handle = task::spawn(async move {
            println!("Task {i} starting");
            tokio::time::sleep(tokio::time::Duration::from_secs(1)).await;
            println!("Task {i} done");
        });
        handles.push(handle);
    }

    // Wait for all tasks to complete
    for handle in handles {
        handle.await.unwrap();
    }
}
```

This creates a pool of 10 concurrent async tasks that each sleep for 1 second. The `#[tokio::main]` attribute sets up the runtime, and `task::spawn()` creates the concurrent tasks.

