    "strings"
)

// NMEASentence represents a parsed NMEA sentence
type NMEASentence struct {
    Type     string
    Fields   []string
    Checksum string
}

// ParseNMEASentence parses an NMEA 0183 sentence
func ParseNMEASentence(sentence string) (*NMEASentence, error) {
    // Remove carriage return and newline characters
    sentence = strings.TrimSpace(sentence)

    // Validate NMEA sentence format
    if !strings.HasPrefix(sentence, "$") {
        return nil, fmt.Errorf("invalid NMEA sentence: missing $ prefix")
    }

    // Split by checksum indicator
    parts := strings.Split(sentence, "*")
    if len(parts) != 2 {
        return nil, fmt.Errorf("invalid NMEA sentence: missing checksum")
    }

    // Extract fields (everything between $ and *)
    rawFields := parts[0][1:] // Remove the leading $
    checksum := parts[1]

    // Split fields by comma
    var fields []string
    if rawFields != "" {
        fields = strings.Split(rawFields, ",")
    }

    return &NMEASentence{
        Type:     fields[0],
        Fields:   fields[1:],
        Checksum: checksum,
    }, nil
}

// ParseGPGGA parses GPGGA sentence (Global Positioning System Fix Data)
func ParseGPGGA(sentence string) (map[string]interface{}, error) {
    parsed, err := ParseNMEASentence(sentence)
    if err != nil {
        return nil, err
    }

    if parsed.Type != "GPGGA" {
        return nil, fmt.Errorf("not a GPGGA sentence")
    }

    // GPGGA fields: Time, Latitude, N/S, Longitude, E/W, Fix quality, 
    // Number of satellites, Horizontal dilution, Altitude, M, Geoid separation, M

    result := make(map[string]interface{})

    if len(parsed.Fields) >= 10 {
        // Time (UTC)
        if parsed.Fields[0] != "" {
            result["time"] = parsed.Fields[0]
        }

        // Latitude
        if parsed.Fields[1] != "" {
            lat, err := parseCoordinate(parsed.Fields[1], parsed.Fields[2])
            if err == nil {
                result["latitude"] = lat
            }
        }

        // Longitude
        if parsed.Fields[3] != "" {
            lon, err := parseCoordinate(parsed.Fields[3], parsed.Fields[4])
            if err == nil {
                result["longitude"] = lon
            }
        }

        // Fix quality
        if parsed.Fields[5] != "" {
            result["fix_quality"] = parsed.Fields[5]
        }

        // Number of satellites
        if parsed.Fields[6] != "" {
            result["satellites"] = parsed.Fields[6]
        }

        // Altitude
        if parsed.Fields[8] != "" {
            if alt, err := strconv.ParseFloat(parsed.Fields[8], 64); err == nil {
                result["altitude"] = alt
            }
        }
    }

    return result, nil
}

// parseCoordinate converts NMEA coordinate format to decimal degrees
func parseCoordinate(coord, direction string) (float64, error) {
    if coord == "" || direction == "" {
        return 0, fmt.Errorf("empty coordinate")
    }

    // Format: DDMM.MMMM
    if len(coord) < 5 {
        return 0, fmt.Errorf("invalid coordinate format")
    }

    degrees := coord[:len(coord)-6]
    minutes := coord[len(coord)-6:]

    deg, err1 := strconv.ParseFloat(degrees, 64)
    min, err2 := strconv.ParseFloat(minutes, 64)

    if err1 != nil || err2 != nil {
        return 0, fmt.Errorf("invalid coordinate")
    }

    decimal := deg + min/60.0

    // Apply direction (negative for S and W)
    if direction == "S" || direction == "W" {
        decimal = -decimal
    }

    return decimal, nil
}

func main() {
    // Example GPGGA sentence
    gpgga := "$GPGGA,123519,4807.038,N,01131.000,E,1,08,0.9,545.4,M,46.9,M,,*47"

    fmt.Println("Raw sentence:", gpgga)

    // Parse the sentence
    parsed, err := ParseGPGGA(gpgga)
    if err != nil {
        fmt.Printf("Error parsing: %v\n", err)
        return
    }

    fmt.Println("Parsed data:")
    for key, value := range parsed {
        fmt.Printf("  %s: %v\n", key, value)
    }

    // Test with a more complex sentence
    gpgga2 := "$GPGGA,170834,4124.8963,N,08151.6838,W,1,07,1.0,280.2,M,-34.0,M,,*64"
    fmt.Println("\n--- Second example ---")
    fmt.Println("Raw sentence:", gpgga2)

    parsed2, err := ParseGPGGA(gpgga2)
    if err != nil {
        fmt.Printf("Error parsing: %v\n", err)
        return
    }

    fmt.Println("Parsed data:")
    for key, value := range parsed2 {
        fmt.Printf("  %s: %v\n", key, value)
    }
}
```

This example provides:

1. **Basic NMEA parsing**: `ParseNMEASentence()` function that splits sentences into type, fields, and checksum
2. **GPGGA parsing**: `ParseGPGGA()` specifically handles GPS fix data sentences
3. **Coordinate conversion**: `parseCoordinate()` converts NMEA format (DDMM.MMMM) to decimal degrees
4. **Error handling**: Proper validation and error reporting

**Key features:**
