# Parsing SWIFT MT940 Bank Statements in Java

## Overview
This example demonstrates how to parse SWIFT MT940 bank statement messages using Java. The MT940 format uses a structured tag-based syntax where each field is identified by a two-digit tag number.

## Code Example

```java
import java.io.*;
import java.util.*;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;

public class MT940Parser {

    public static class BankStatement {
        private String accountNumber;
        private LocalDate statementDate;
        private double openingBalance;
        private double closingBalance;
        private List<Transaction> transactions;

        public BankStatement() {
            this.transactions = new ArrayList<>();
        }

        // Getters and setters
        public String getAccountNumber() { return accountNumber; }
        public void setAccountNumber(String accountNumber) { this.accountNumber = accountNumber; }
        public LocalDate getStatementDate() { return statementDate; }
        public void setStatementDate(LocalDate statementDate) { this.statementDate = statementDate; }
        public double getOpeningBalance() { return openingBalance; }
        public void setOpeningBalance(double openingBalance) { this.openingBalance = openingBalance; }
        public double getClosingBalance() { return closingBalance; }
        public void setClosingBalance(double closingBalance) { this.closingBalance = closingBalance; }
        public List<Transaction> getTransactions() { return transactions; }
    }

    public static class Transaction {
        private LocalDate transactionDate;
        private String description;
        private double amount;
        private String reference;

        // Getters and setters
        public LocalDate getTransactionDate() { return transactionDate; }
        public void setTransactionDate(LocalDate transactionDate) { this.transactionDate = transactionDate; }
        public String getDescription() { return description; }
        public void setDescription(String description) { this.description = description; }
        public double getAmount() { return amount; }
        public void setAmount(double amount) { this.amount = amount; }
        public String getReference() { return reference; }
        public void setReference(String reference) { this.reference = reference; }
    }

    public static BankStatement parseMT940(String swiftMessage) {
        BankStatement statement = new BankStatement();
        Map<String, String> fields = new HashMap<>();

        // Split by newline and process each line
        String[] lines = swiftMessage.split("\n");
        StringBuilder currentFieldContent = null;
        String currentTag = null;

        for (String line : lines) {
            if (line.startsWith(":")) {
                // Process previous field if exists
                if (currentFieldContent != null && currentTag != null) {
                    fields.put(currentTag, currentFieldContent.toString().trim());
                }

                // Start new field
                int colonIndex = line.indexOf(':');
                currentTag = line.substring(1, Math.min(3, line.length()));
                currentFieldContent = new StringBuilder();

                // Add content after tag if any
                if (line.length() > 3) {
                    currentFieldContent.append(line.substring(3));
                }
            } else if (currentFieldContent != null) {
                // Continue field content (multiline)
                currentFieldContent.append("\n").append(line);
            }
        }

        // Don't forget the last field
        if (currentFieldContent != null && currentTag != null) {
            fields.put(currentTag, currentFieldContent.toString().trim());
        }

        // Parse fields
        parseHeaderFields(statement, fields);
        parseTransactionFields(statement, fields);

        return statement;
    }

    private static void parseHeaderFields(BankStatement statement, Map<String, String> fields) {
        // Field 20: Transaction Reference Number
        String refNumber = fields.get("20");
        if (refNumber != null) {
            statement.setAccountNumber(refNumber);
        }

        // Field 25: Account Number
        String accountNumber = fields.get("25");
        if (accountNumber != null) {
            statement.setAccountNumber(accountNumber);
        }

        // Field 28C: Statement Number
        String statementNumber = fields.get("28C");
        if (statementNumber != null) {
            // This could be used to identify statement sequence
        }

        // Field 60F: Opening Balance
        String openingBalanceField = fields.get("60F");
        if (openingBalanceField != null) {
            parseBalanceField(openingBalanceField, statement);
        }

        // Field 62F: Closing Balance
        String closingBalanceField = fields.get("62F");
        if (closingBalanceField != null) {
            parseBalanceField(closingBalanceField, statement);
        }
    }

    private static void parseBalanceField(String balanceField, BankStatement statement) {
        // Format: [D/C][Date][Currency][Amount]
        try {
            String[] parts = balanceField.split("[A-Z]");
            if (parts.length >= 3) {
                String currency = parts[1];
                String amountStr = parts[2].replaceAll(",", ".");
                double amount = Double.parseDouble(amountStr);

                // Check if it's a debit or credit
                if (balanceField.startsWith("D")) {
                    statement.setOpeningBalance(-amount); // Debit
                } else if (balanceField.startsWith("C")) {
                    statement.setOpeningBalance(amount);  // Credit
                }
            }
        } catch (Exception e) {
            System.err.println("Error parsing balance: " + balanceField);
        }
    }

    private static void parseTransactionFields(BankStatement statement, Map<String, String> fields) {
        // Process all transaction fields (starting with :61:)
        for (Map.Entry<String, String> entry : fields.entrySet()) {
            if (entry.getKey().startsWith("61")) {
                Transaction transaction = parseTransactionField(entry.getValue());
                if (transaction != null) {
                    statement.getTransactions().add(transaction);
                }
            }
        }
    }

    private static Transaction parseTransactionField(String transactionField) {
        try {
            // Format: [Date][Currency][Amount][Description]
            Transaction transaction = new Transaction();

            // Simple parsing - in real implementation, you'd need more sophisticated parsing
            String[] parts = transactionField.split(":");
            if (parts.length >= 4) {
                // Parse date (first 6 digits)
                String dateStr = parts[0].substring(0, 6);
                LocalDate date = parseDate(dateStr);
                transaction.setTransactionDate(date);

                // Parse amount
                String amountStr = parts[2];
                double amount = Double.parseDouble(amountStr.replaceAll(",", "."));
                transaction.setAmount(amount);

                // Parse description
                transaction.setDescription(parts[3]);
            }

            return transaction;
        } catch (Exception e) {
            System.err.println("Error parsing transaction: " + transactionField);
            return null;
        }
    }

    private static LocalDate parseDate(String dateStr) {
        try {
            DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyMMdd");
            return LocalDate.parse(dateStr, formatter);
        } catch (Exception e) {
            return null;
        }
    }

    public static void main(String[] args) {
        // Sample MT940 message
        String sampleMT940 = "" +
            ":20:REFERENCE123\n" +
            ":25:DE12345678901234567890\n" +
            ":28C:001/1\n" +
            ":60F:C180101EUR1234.56\n" +
            ":61:180102EUR100.00NMSC\n" +
            ":61:180103EUR250.00NMSC\n" +
            ":62F:C180103EUR1584.56\n";

        try {
            BankStatement statement = parseMT940(sampleMT940);
            System.out.println("Account: " + statement.getAccountNumber());
            System.out.println("Opening Balance: " + statement.getOpeningBalance());
            System.out.println("Closing Balance: " + statement.getClosingBalance());
            System.out.println("Transactions:");

            for (Transaction t : statement.getTransactions()) {
                System.out.println("  Date: " + t.getTransactionDate() + 
                                 ", Amount: " + t.getAmount() + 
                                 ", Description: " + t.getDescription());
            }
        } catch (Exception e) {
            System.err.println("Error parsing MT940: " + e.getMessage());
        }
    }
}
```

## Key Features

1. **Field Parsing**: Parses standard MT940 fields like account number, dates, balances, and transactions
2. **Transaction Processing**: Handles multiple transaction entries with proper date and amount extraction
3. **Error Handling**: Includes basic error handling for malformed data
4. **Flexible Format Support**: Supports multiline field content as per SWIFT standards

## Important Notes

- This is a simplified parser for demonstration purposes
