I'll show you how to read CAN bus frames in C++. Here are several approaches depending on your platform and requirements:

## Method 1: Using SocketCAN (Linux)

```cpp
#include <iostream>
#include <sys/socket.h>
#include <linux/can.h>
#include <linux/can/raw.h>
#include <cstring>
#include <unistd.h>

class CANReader {
private:
    int sock;
    struct sockaddr_can addr;
    struct can_frame frame;

public:
    CANReader(const char* interface) {
        // Create raw socket
        sock = socket(PF_CAN, SOCK_RAW, CAN_RAW);
        if (sock < 0) {
            throw std::runtime_error("Failed to create CAN socket");
        }

        // Set up address structure
        memset(&addr, 0, sizeof(addr));
        addr.can_family = AF_CAN;

        // Get interface index
        struct ifreq ifr;
        strcpy(ifr.ifr_name, interface);
        if (ioctl(sock, SIOCGIFINDEX, &ifr) < 0) {
            close(sock);
            throw std::runtime_error("Failed to get interface index");
        }
        addr.can_ifindex = ifr.ifr_ifindex;

        // Bind socket
        if (bind(sock, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
            close(sock);
            throw std::runtime_error("Failed to bind CAN socket");
        }
    }

    ~CANReader() {
        if (sock >= 0) {
            close(sock);
        }
    }

    bool readFrame(struct can_frame& frame) {
        ssize_t bytes_read = read(sock, &frame, sizeof(frame));
        return bytes_read > 0;
    }

    void printFrame(const struct can_frame& frame) {
        std::cout << "ID: 0x" << std::hex << frame.can_id 
                  << " DLC: " << std::dec << (int)frame.can_dlc
                  << " Data: ";

        for (int i = 0; i < frame.can_dlc; i++) {
            printf("%02X ", frame.data[i]);
        }
        std::cout << std::endl;
    }
};

int main() {
    try {
        CANReader reader("can0"); // Change to your interface name

        std::cout << "Listening for CAN frames on can0..." << std::endl;

        struct can_frame frame;
        while (true) {
            if (reader.readFrame(frame)) {
                reader.printFrame(frame);
            }
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
```

