struct CompileTimePool {
    std::array<char, N> buffer;
    size_t offset = 0;

    constexpr void* allocate(size_t size) {
        if (offset + size <= N) {
            void* ptr = &buffer[offset];
            offset += size;
            return ptr;
        }
