struct ObjectFactory {
    static constexpr T create(int value) {
        return T{value};
    }
};

// Example class that can be created at compile time
struct MyData {
    int value;
    char name[10];

    constexpr MyData(int v) : value(v) {
        for (int i = 0; i < 10; ++i) {
            name[i] = 'A' + (v % 26);
        }
    }
};

// Compile-time memory management
constexpr auto create_objects() {
    CompileTimePool<1024> pool;

    // Create objects at compile time
    auto* obj1 = static_cast<MyData*>(pool.allocate(sizeof(MyData)));
    new (obj1) MyData(42);

    auto* obj2 = static_cast<MyData*>(pool.allocate(sizeof(MyData)));
    new (obj2) MyData(100);

    return pool;
}

int main() {
    // This will be evaluated at compile time
    constexpr auto pool = create_objects();

    std::cout << "Compile-time memory management example\n";
    return 0;
}
```

However, if you're interested in **true compile-time garbage collection**, here's a more advanced example using concepts and template metaprogramming:

```cpp
#include <iostream>
#include <type_traits>

// Compile-time object tracking
template<typename T>
struct CompileTimeTracker {
    static constexpr bool needs_cleanup = std::is_destructible_v<T>;

    constexpr static void cleanup(T& obj) {
        if constexpr (needs_cleanup) {
            obj.~T();
        }
    }
};

// Simple compile-time memory manager
template<size_t MAX_OBJECTS>
class CompileTimeManager {
private:
    struct ObjectInfo {
        void* ptr;
        bool active;
    };

    std::array<ObjectInfo, MAX_OBJECTS> objects;
    size_t count = 0;

public:
    template<typename T, typename... Args>
    constexpr T* create(Args&&... args) {
        if (count < MAX_OBJECTS) {
            T* obj = reinterpret_cast<T*>(new char[sizeof(T)]);
            new (obj) T(std::forward<Args>(args)...);
            objects[count] = {obj, true};
            count++;
            return obj;
        }
        return nullptr;
    }

    constexpr void cleanup() {
        for (size_t i = 0; i < count; ++i) {
            if (objects[i].active && objects[i].ptr) {
                // This is where we'd call destructors
                // In practice, this would need more sophisticated RTTI
            }
        }
    }
};

// Example usage
struct TestObject {
    int value;

    constexpr TestObject(int v) : value(v) {}

    constexpr ~TestObject() = default;
};

int main() {
    // Compile-time creation of objects
    constexpr auto manager = []() {
        CompileTimeManager<10> mgr;
        return mgr;
    }();

    std::cout << "Compile-time memory management\n";
    return 0;
}
```

**Important Notes:**

1. **No true GC**: C++ doesn't have garbage collection, even at compile time
2. **constexpr limitations**: You can only do limited operations at compile time
3. **Memory allocation**: `constexpr` functions can't allocate memory dynamically in the traditional sense
4. **Destruction**: Compile-time destruction isn't possible in the same way as runtime GC

**What you CAN do:**
- Pre-compute object graphs at compile time
- Use `constexpr` for initialization and computation
- Implement custom compile-time allocators
- Use template metaprogramming for memory management strategies

The closest you can get to "compile-time garbage collection" is using `constexpr` with compile-time data structures and ensuring all objects are properly initialized/deinitialized at compile time through templates and constant expressions.

Here's how to use `auto_memoize` with keyword arguments:

```python
from functools import wraps

def auto_memoize(func):
    cache = {}
    @wraps(func)
    def wrapper(*args, **kwargs):
        # Create a key from args and sorted kwargs
        key = str(args) + str(sorted(kwargs.items()))
        if key not in cache:
            cache[key] = func(*args, **kwargs)
        return cache[key]
    return wrapper

@auto_memoize
def expensive_function(x, y, z=None):
    print(f"Computing with {x}, {y}, {z}")
    return x * y + (z or 0)

# Usage
expensive_function(2, 3)           # Computes and caches
expensive_function(2, 3)           # Returns cached result
expensive_function(2, 3, z=5)      # Different key, computes again
```

The key is creating a unique cache key from both positional args and sorted keyword args.

