## Using quiche (Recommended)

First, let's set up the basic structure:

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <memory>
#include <thread>
#include <chrono>
#include <quiche.h>

class QUICClient {
private:
    quiche_config* config;
    quiche_conn* conn;
    std::string host;
    uint16_t port;
    bool connected;

public:
    QUICClient(const std::string& host, uint16_t port) 
        : host(host), port(port), connected(false) {
        initialize();
    }

    ~QUICClient() {
        if (conn) {
            quiche_conn_free(conn);
        }
        if (config) {
            quiche_config_free(config);
        }
    }

    void initialize() {
        // Create QUIC config
        config = quiche_config_new(0x00000001); // QUIC version
        quiche_config_set_application_protos(config, 
            (uint8_t*)"\x05hq-29\x05hq-32\x05hq-34", 18);
        quiche_config_set_max_idle_timeout(config, 5000);
        quiche_config_set_max_send_udp_payload_size(config, 1200);
        quiche_config_set_max_connection_window(config, 1000000);
        quiche_config_set_max_stream_window(config, 1000000);
        quiche_config_set_enable_dgram(config, true, 1000, 1000);

        // Disable packet loss for lossless communication
        quiche_config_set_disable_active_migration(config, true);
    }

    bool connect() {
        // Create connection
        uint8_t scid[16];
        for (size_t i = 0; i < sizeof(scid); i++) {
            scid[i] = i;
        }

        conn = quiche_conn_new_with_tls(scid, sizeof(scid), 
            nullptr, 0, host.c_str(), port, config);

        if (conn == nullptr) {
            std::cerr << "Failed to create connection" << std::endl;
            return false;
        }

        // Send initial packet
        uint8_t out[2048];
        size_t out_len = sizeof(out);

        int64_t send_result = quiche_conn_send(conn, out, out_len);

        if (send_result > 0) {
            std::cout << "Initial connection sent" << std::endl;
            connected = true;
            return true;
        }

        return false;
    }

    bool send_data(const std::string& data) {
        if (!connected || !conn) return false;

        // Send stream data
        uint32_t stream_id = 0;
        int64_t result = quiche_conn_stream_send(conn, stream_id, 
            (uint8_t*)data.c_str(), data.length(), true);

        if (result < 0) {
            std::cerr << "Failed to send data: " << result << std::endl;
            return false;
        }

        std::cout << "Sent " << data.length() << " bytes" << std::endl;
        return true;
    }

    void receive_data() {
        if (!conn) return;

        uint8_t buf[65535];

        while (true) {
            ssize_t recv_result = quiche_conn_recv(conn, buf, sizeof(buf));

            if (recv_result < 0) {
                break;
            }

            // Process received data
            process_incoming_data(buf, recv_result);
        }
    }

    void process_incoming_data(const uint8_t* data, size_t len) {
        // Process incoming QUIC frames
        quiche_conn_stream_iter iter;
        quiche_conn_streams_iter(conn, &iter);

        while (true) {
            uint64_t stream_id = quiche_conn_streams_iter_next(&iter);
            if (stream_id == UINT64_MAX) break;

            // Read from stream
            uint8_t buf[1024];
            ssize_t read_result = quiche_conn_stream_recv(conn, stream_id, 
                buf, sizeof(buf), nullptr);

            if (read_result > 0) {
                std::cout << "Received " << read_result << " bytes from stream "
                         << stream_id << ": ";
                std::string received_data(buf, read_result);
                std::cout << received_data << std::endl;
            }
        }
    }

    void run() {
        if (!connect()) {
            std::cerr << "Connection failed" << std::endl;
            return;
        }

        // Send some test data
        send_data("Hello QUIC!");
        send_data("This is a lossless stream");

        // Main loop to handle incoming data
        while (connected) {
            receive_data();
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    }
};
```

