            conn = nullptr;
        }
        if (config) {
            quiche_config_free(config);
            config = nullptr;
        }
    }

    bool initialize() {
        // Create QUIC config
        config = quiche_config_new(0x00000001); // QUIC version 1
        if (!config) {
            std::cerr << "Failed to create config" << std::endl;
            return false;
        }

        // Set application protocols (HTTP/3)
        const uint8_t alpns[] = "\x02h3";
        quiche_config_set_application_protos(config, alpns, 3);

        // Configure for lossless communication
        quiche_config_set_max_idle_timeout(config, 5000); // 5 seconds
        quiche_config_set_max_send_udp_payload_size(config, 1200);
        quiche_config_set_max_connection_window(config, 1000000);
        quiche_config_set_max_stream_window(config, 1000000);

        // Enable datagram support for additional features
        quiche_config_set_enable_dgram(config, true, 1000, 1000);

        // Disable migration to ensure reliable connection
        quiche_config_set_disable_active_migration(config, true);

        // Enable lossless mode (retransmissions)
        quiche_config_set_retransmit_timeout(config, 5000); // 5 seconds

        return true;
    }

    bool connect() {
        uint8_t scid[16];
        for (size_t i = 0; i < sizeof(scid); i++) {
            scid[i] = static_cast<uint8_t>(i);
        }

        conn = quiche_conn_new_with_tls(scid, sizeof(scid), 
            nullptr, 0, host.c_str(), port, config);

        if (!conn) {
            std::cerr << "Failed to create connection" << std::endl;
            return false;
        }

        // Send initial handshake
        uint8_t out[2048];
        size_t out_len = sizeof(out);

        int64_t send_result = quiche_conn_send(conn, out, out_len);

        if (send_result < 0) {
            std::cerr << "Failed to send initial packet: " << send_result << std::endl;
            return false;
        }

        connected = true;
        std::cout << "Connected to " << host << ":" << port << std::endl;
        return true;
    }

    bool send_stream_data(const std::string& data) {
        if (!connected || !conn) {
            std::cerr << "Not connected" << std::endl;
            return false;
        }

        // Create new stream
        uint32_t stream_id = stream_id_counter++;

        // Send data on the stream
        int64_t result = quiche_conn_stream_send(conn, stream_id, 
            (const uint8_t*)data.c_str(), data.length(), true);

        if (result < 0) {
            std::cerr << "Failed to send data: " << result << std::endl;
            return false;
        }

        std::cout << "Sent " << data.length() << " bytes on stream " 
                 << stream_id << std::endl;
        return true;
    }

    bool send_unreliable_data(const std::string& data) {
        if (!conn) return false;

        // Send datagram (unreliable but faster)
        int64_t result = quiche_conn_dgram_send(conn, 
            (const uint8_t*)data.c_str(), data.length());

        if (result < 0) {
            std::cerr << "Failed to send datagram: " << result << std::endl;
            return false;
        }

        std::cout << "Sent unreliable datagram of " << data.length() << " bytes" << std::endl;
        return true;
    }

    void process_incoming_data() {
        if (!conn) return;

        uint8_t buf[65535];
        ssize_t recv_result = quiche_conn_recv(conn, buf, sizeof(buf));

        if (recv_result < 0) {
            // Handle error
            std::cerr << "Receive error: " << recv_result << std::endl;
            return;
        }

        // Process incoming frames
        process_frames(buf, recv_result);
    }

    void process_frames(const uint8_t* data, size_t len) {
        quiche_conn_stream_iter iter;
        quiche_conn_streams_iter(conn, &iter);

        while (true) {
            uint64_t stream_id = quiche_conn_streams_iter_next(&iter);
            if (stream_id == UINT64_MAX) break;

            // Read from stream
            uint8_t buf[1024];
            bool fin = false;
            ssize_t read_result = quiche_conn_stream_recv(conn, stream_id, 
                buf, sizeof(buf), &fin);

            if (read_result > 0) {
