            }
        }

        // Process datagrams
        while (true) {
            uint8_t buf[1024];
            ssize_t recv_result = quiche_conn_dgram_recv(conn, buf, sizeof(buf));

            if (recv_result < 0) break;

            std::string received_data(buf, recv_result);
            std::cout << "Datagram received: " << received_data << std::endl;
        }
    }

    void run() {
        if (!connect()) {
            std::cerr << "Connection failed" << std::endl;
            return;
        }

        // Send test data
        send_stream_data("Hello QUIC Lossless!");
        send_stream_data("This is reliable streaming communication");

        // Main processing loop
        while (connected) {
            process_incoming_data();

            // Handle outgoing data
            uint8_t out[2048];
            size_t out_len = sizeof(out);
