Here's a minimal working example of a UDP-reliable, exactly-once server in Go:

```go
package main

import (
    "crypto/rand"
    "fmt"
    "net"
    "sync"
    "time"
)

type Message struct {
    ID      uint64
    Payload string
    Time    int64
}

type Server struct {
    conn       *net.UDPConn
    received   map[uint64]bool
    mutex      sync.RWMutex
    pendingAck map[uint64]chan struct{}
    ackMutex   sync.RWMutex
}

func NewServer(addr string) (*Server, error) {
    udpAddr, err := net.ResolveUDPAddr("udp", addr)
    if err != nil {
        return nil, err
    }

    conn, err := net.ListenUDP("udp", udpAddr)
    if err != nil {
        return nil, err
    }

    server := &Server{
        conn:       conn,
        received:   make(map[uint64]bool),
        pendingAck: make(map[uint64]chan struct{}),
    }

    go server.handleMessages()
    return server, nil
}

func (s *Server) handleMessages() {
    buffer := make([]byte, 1024)

    for {
        n, clientAddr, err := s.conn.ReadFromUDP(buffer)
        if err != nil {
            fmt.Printf("Read error: %v\n", err)
            continue
        }

        var msg Message
        // Simple serialization - in production use protobuf or JSON
        fmt.Sscanf(string(buffer[:n]), "%d:%s:%d", &msg.ID, &msg.Payload, &msg.Time)

        // Check if we've already processed this message
        s.mutex.RLock()
        if s.received[msg.ID] {
            s.mutex.RUnlock()
            // Send acknowledgment for duplicate
            s.sendAck(clientAddr, msg.ID)
            continue
        }
        s.mutex.RUnlock()

        // Process the message
        fmt.Printf("Received message %d: %s\n", msg.ID, msg.Payload)

        // Mark as received
        s.mutex.Lock()
        s.received[msg.ID] = true
        s.mutex.Unlock()

        // Send acknowledgment
        s.sendAck(clientAddr, msg.ID)

        // Simulate processing time
        time.Sleep(10 * time.Millisecond)
    }
}

func (s *Server) sendAck(addr *net.UDPAddr, msgID uint64) {
    ackMsg := fmt.Sprintf("ACK:%d", msgID)
    s.conn.WriteToUDP([]byte(ackMsg), addr)
}

func (s *Server) Close() error {
    return s.conn.Close()
}

// Simple client for testing
func main() {
    // Start server
    server, err := NewServer(":8080")
    if err != nil {
        panic(err)
    }
    defer server.Close()

    fmt.Println("Server started on :8080")
    fmt.Println("Sending test messages...")

    // Send some test messages
    go sendTestMessages()

    // Keep server running
    select {}
}

func sendTestMessages() {
    addr, _ := net.ResolveUDPAddr("udp", "127.0.0.1:8080")
    conn, _ := net.DialUDP("udp", nil, addr)
    defer conn.Close()

    // Send messages with same ID to test deduplication
    for i := 0; i < 3; i++ {
        msgID := uint64(1) // Same ID for testing
        payload := fmt.Sprintf("Hello World %d", i)
        timestamp := time.Now().Unix()

        message := fmt.Sprintf("%d:%s:%d", msgID, payload, timestamp)
        conn.Write([]byte(message))
        fmt.Printf("Sent: %s\n", message)

        time.Sleep(200 * time.Millisecond)
    }

    // Send different messages
    for i := 0; i < 3; i++ {
        msgID := uint64(i + 10) // Different ID
        payload := fmt.Sprintf("Unique Message %d", i)
        timestamp := time.Now().Unix()

        message := fmt.Sprintf("%d:%s:%d", msgID, payload, timestamp)
        conn.Write([]byte(message))
        fmt.Printf("Sent: %s\n", message)

        time.Sleep(200 * time.Millisecond)
    }
}
```

This implementation provides:

## Key Features:

1. **Message Deduplication**: Uses a map to track received message IDs
2. **Exactly-Once Delivery**: Messages with the same ID are only processed once
3. **Acknowledgment System**: Sends ACK messages back to clients
4. **Thread-Safe**: Uses mutexes for concurrent access

## How it works:

1. **Server** receives UDP messages containing `ID:Payload:Timestamp`
2. **Check** if message ID was already received
3. **Process** only new messages (duplicates are ignored)
4. **Send ACK** back to client for all received messages
5. **Store** processed message IDs to prevent reprocessing

## Limitations:

1. **Memory Usage**: Stores all seen message IDs in memory
2. **No Persistence**: IDs are lost on server restart
3. **Simple Serialization**: Uses string parsing instead of proper serialization
4. **No Retransmission**: Basic acknowledgment without retry logic

