## Minimal Example

**example.cpp:**
```cpp
#include <iostream>
#include <cstring>

// Vulnerable code that could leak information through cache timing
int vulnerable_function(const char* input, const char* secret) {
    int result = 0;
    for (int i = 0; i < strlen(secret); i++) {
        if (input[i] == secret[i]) {
            result++;
        }
        // This creates a timing side channel - faster execution for matching characters
    }
    return result;
}

// Secure version using constant-time comparison
int secure_function(const char* input, const char* secret) {
    int len = strlen(secret);
    int result = 0;

    for (int i = 0; i < len; i++) {
        // Constant-time comparison - always execute both branches
        int equal = (input[i] == secret[i]);
        result += equal;
    }
    return result;
}

int main() {
    const char* secret = "secret";
    const char* test_input = "secretx";  // Last char is different

    std::cout << "Vulnerable function result: " << vulnerable_function(test_input, secret) << std::endl;
    std::cout << "Secure function result: " << secure_function(test_input, secret) << std::endl;

    return 0;
}
