    // Create a vector of random floats
    std::vector<float> data(1000000);
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<float> dis(0.0f, 1000.0f);

    for (auto& elem : data) {
        elem = dis(gen);
    }

    // Print first few elements before sorting
    std::cout << "First 10 elements before sorting:\n";
    for (int i = 0; i < 10; ++i) {
        std::cout << data[i] << " ";
    }
    std::cout << "\n\n";

    // Sort using SIMD sort
    std::experimental::simd_sort(data.begin(), data.end());

    // Print first few elements after sorting
    std::cout << "First 10 elements after sorting:\n";
    for (int i = 0; i < 10; ++i) {
        std::cout << data[i] << " ";
    }
    std::cout << "\n\n";

    // Verify the array is sorted
    bool is_sorted = std::is_sorted(data.begin(), data.end());
    std::cout << "Array is sorted: " << (is_sorted ? "Yes" : "No") << "\n";

    return 0;
}
```

