import com.google.common.cache.CacheBuilder;

public class GuavaLRUCacheExample {
    public static void main(String[] args) {
        Cache<String, Integer> cache = CacheBuilder.newBuilder()
                .maximumSize(3)  // LRU capacity
                .build();

        cache.put("A", 1);
        cache.put("B", 2);
        cache.put("C", 3);

        System.out.println(cache.getIfPresent("A")); // null (evicted due to LRU)
    }
}
```

## Option 4: Custom Implementation with Doubly Linked List

For educational purposes, here's a more complete custom implementation:

```java
import java.util.HashMap;
import java.util.Map;

public class CustomLRUCache<K, V> {
    private final int capacity;
    private final Map<K, Node<K, V>> cache;
    private final Node<K, V> head;
    private final Node<K, V> tail;

    private static class Node<K, V> {
        K key;
        V value;
        Node<K, V> prev;
        Node<K, V> next;

        Node(K key, V value) {
            this.key = key;
            this.value = value;
        }
    }

    public CustomLRUCache(int capacity) {
        this.capacity = capacity;
        this.cache = new HashMap<>();
        this.head = new Node<>(null, null);
        this.tail = new Node<>(null, null);
        head.next = tail;
        tail.prev = head;
    }

    public V get(K key) {
        Node<K, V> node = cache.get(key);
        if (node == null) return null;

        // Move to front (most recently used)
        removeNode(node);
        addToFront(node);

        return node.value;
    }

    public void put(K key, V value) {
        Node<K, V> node = cache.get(key);
        if (node == null) {
            Node<K, V> newNode = new Node<>(key, value);
            if (cache.size() >= capacity) {
                // Remove least recently used
                Node<K, V> lastNode = tail.prev;
                removeNode(lastNode);
                cache.remove(lastNode.key);
            }
            cache.put(key, newNode);
            addToFront(newNode);
        } else {
            // Update existing node
            node.value = value;
            removeNode(node);
            addToFront(node);
        }
    }

    private void removeNode(Node<K, V> node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    private void addToFront(Node<K, V> node) {
        node.next = head.next;
        head.next.prev = node;
        head.next = node;
        node.prev = head;
    }
}
```

## Recommendation

For most use cases, I'd recommend:
1. **Option 1** (LinkedHashMap) for simple, lightweight solutions
2. **Option 3** (Guava Cache) for production applications where you need robust features
3. **Option 4** for learning purposes or when you need maximum control

The `LinkedHashMap` approach is probably what you're looking for since it's part of the standard library and provides clean, efficient LRU behavior out of the box.

