## Using with Modern ES6/ES2015+

```javascript
import ReliableWebSocket from 'ws-reliable';

class WebSocketManager {
    constructor(url, options = {}) {
        this.url = url;
        this.options = options;
        this.ws = null;
        this.connect();
    }

    connect() {
        this.ws = new ReliableWebSocket(this.url, this.options);

        this.ws.on('open', () => {
            console.log('Connected to WebSocket');
            this.onOpen();
        });

        this.ws.on('message', (data) => {
            this.onMessage(data);
        });

        this.ws.on('close', () => {
            console.log('Connection closed');
            this.onClose();
        });

        this.ws.on('error', (error) => {
            console.error('WebSocket error:', error);
            this.onError(error);
        });
    }

    onOpen() {
        // Override this method
        console.log('Connection opened');
    }

    onMessage(data) {
        // Override this method
        console.log('Received message:', data);
    }

    onClose() {
        // Override this method
        console.log('Connection closed');
    }

    onError(error) {
        // Override this method
        console.error('Connection error:', error);
    }

    send(data) {
        if (this.ws && this.ws.readyState === 1) { // OPEN
            this.ws.send(data);
        } else {
            console.warn('WebSocket not connected');
        }
    }

    close() {
        if (this.ws) {
            this.ws.close();
        }
    }
}

// Usage
const wsManager = new WebSocketManager('wss://echo.websocket.org', {
    maxRetries: 3,
    retryDelay: 2000,
    autoReconnect: true
});

wsManager.send('Hello World!');
```

## Key Features of ws-reliable

The `ws-reliable` package provides:

