Here's a working example of how to use `sharp-autocrop` to resize and auto-crop images:

```javascript
const sharp = require('sharp');
const autocrop = require('sharp-autocrop');

async function processImage(inputPath, outputPath, targetWidth, targetHeight) {
  try {
    // Read the image
    const imageBuffer = await sharp(inputPath)
      .resize(targetWidth, targetHeight, {
        fit: 'cover', // Maintain aspect ratio, crop if necessary
        position: 'center'
      })
      .jpeg({ quality: 85 })
      .toBuffer();

    // Auto-crop the image using sharp-autocrop
    const croppedImage = await autocrop(imageBuffer, {
      width: targetWidth,
      height: targetHeight,
      tolerance: 0.1, // How much color variation to ignore (0-1)
      background: '#ffffff' // Background color for padding
    });

    // Save the final image
    await croppedImage.toFile(outputPath);

    console.log('Image processed successfully!');
    return croppedImage;
  } catch (error) {
    console.error('Error processing image:', error);
    throw error;
  }
}

// Usage example
processImage('./input.jpg', './output.jpg', 300, 300)
  .then(() => console.log('Done!'))
  .catch(err => console.error('Failed:', err));
```

## How it works:

1. **Sharp resize**: First, we use `sharp` to resize the image to target dimensions while maintaining aspect ratio
2. **Auto-crop**: Then `sharp-autocrop` analyzes the image content and automatically determines where to crop for the best composition
3. **Smart cropping**: It identifies important visual elements (like faces) and crops around them, rather than just centering

## Key features:
- **Content-aware cropping**: Crops based on image content, not just center
- **Tolerance parameter**: Controls how much color variation is ignored when detecting backgrounds
- **Background handling**: Can add padding or background colors where needed

## Installation:
```bash
npm install sharp sharp-autocrop
```

This approach gives you both the initial resize and intelligent cropping for better visual results.

Here's how to use `node-zerocopy-fs` to stream large files with low memory usage:

```javascript
const fs = require('node-zerocopy-fs');
const { createReadStream } = require('fs');

async function streamLargeFile(filePath, outputStream) {
  try {
    // Create a zero-copy read stream
    const stream = fs.createReadStream(filePath, {
      flags: 'r',
      encoding: null, // Binary mode
      highWaterMark: 64 * 1024 // 64KB buffer (adjust as needed)
    });

    // Pipe the stream to your output
    stream.pipe(outputStream);

    // Handle completion
    stream.on('end', () => {
      console.log('File streaming completed');
    });

    // Handle errors
    stream.on('error', (err) => {
      console.error('Streaming error:', err);
      outputStream.destroy(err);
    });

  } catch (error) {
    console.error('Failed to create stream:', error);
  }
}

// Usage example
const fileStream = fs.createReadStream('./large-file.zip');
const writeStream = require('fs').createWriteStream('./output.zip');

streamLargeFile('./large-file.zip', writeStream);
```

**How it works:**

1. **Zero-copy mechanism**: Unlike traditional Node.js streams that copy data between buffers, `node-zerocopy-fs` uses memory mapping and direct file I/O operations to avoid unnecessary data copying.

2. **Memory efficiency**: The `highWaterMark` parameter controls buffer size - it's set to 64KB in this example, meaning only 64KB of data is held in memory at any time, regardless of file size.

3. **Direct file mapping**: The package leverages OS-level zero-copy techniques (like `mmap` on Unix systems) to map file content directly into memory, reducing overhead and memory usage.

4. **Streaming pattern**: Data flows through the pipeline in chunks without accumulating in large buffers, making it ideal for processing files that are larger than available RAM.

This approach is particularly beneficial when dealing with GB-sized files where traditional streaming might cause memory pressure or performance issues.

Here's a working example of using `axios-retry-pro` to retry failed HTTP requests with exponential backoff:

```javascript
const axios = require('axios');
const axiosRetry = require('axios-retry-pro');

// Create axios instance
const client = axios.create({
  baseURL: 'https://api.example.com',
  timeout: 10000,
});

// Add retry functionality with exponential backoff
axiosRetry(client, {
  retries: 3,                    // Number of retry attempts
  retryDelay: 1000,             // Initial delay in milliseconds
  retryBackoff: true,           // Enable exponential backoff
  retryCondition: (error) => {  // Custom retry condition
    return error.response?.status >= 500 || 
           error.code === 'ECONNABORTED' ||
           error.message.includes('timeout');
  },
  onRetry: (error, retryCount, config) => {
    console.log(`Retry attempt ${retryCount} for ${config.url}`);
  }
});

// Usage example
async function fetchData() {
  try {
    const response = await client.get('/users/123');
    console.log('Success:', response.data);
    return response.data;
  } catch (error) {
    console.error('Failed after all retries:', error.message);
    throw error;
  }
}

// Make the request
fetchData();
```

## How it works:

**axios-retry-pro** is a wrapper around Axios that adds automatic retry functionality with configurable backoff strategies. Here's what happens:

1. **Retry Logic**: When an HTTP request fails, the library checks if it should retry based on your conditions
2. **Exponential Backoff**: Each retry waits longer than the previous one (1s, 2s, 4s, etc.) to avoid overwhelming the server
3. **Configurable Parameters**:
   - `retries`: Maximum number of retry attempts
   - `retryDelay`: Initial delay between retries
   - `retryBackoff`: Enables exponential backoff
   - `retryCondition`: Custom function to determine when to retry
   - `onRetry`: Callback for retry events

4. **Automatic Integration**: The library intercepts Axios requests and automatically handles retries without changing your existing code structure

This approach is particularly useful for handling transient network issues, server timeouts, or rate limiting scenarios where temporary failures can be resolved with retries.

