use rand_constant_time::choice;
use std::cmp::Ordering;

fn constant_time_compare(a: &[u8], b: &[u8]) -> bool {
    // Handle different lengths - this should be O(1) even with different lengths
    let mut result = 0u8;

    // Compare lengths first (constant time)
    let len_a = a.len() as u64;
    let len_b = b.len() as u64;
    let lengths_equal = if len_a == len_b { 1u8 } else { 0u8 };
    result |= lengths_equal;

    // Compare bytes
    let min_len = a.len().min(b.len());
    for i in 0..min_len {
        let byte_a = a[i];
        let byte_b = b[i];
        let bytes_equal = if byte_a == byte_b { 1u8 } else { 0u8 };
        result &= bytes_equal;
    }

    // If lengths are different, result will be 0
    // If lengths are equal and all bytes match, result will be 1
    result != 0
}

// Alternative implementation using the crate's choice function
fn constant_time_compare_v2(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }

    let mut result = 0u8;
    for i in 0..a.len() {
        // Use choice to select 1 or 0 based on equality
        let equal = if a[i] == b[i] { 1u8 } else { 0u8 };
        result |= equal;  // This approach has issues - let me correct it
    }

    // Actually, here's the proper way using rand_constant_time::choice:
    let mut diff = 0u8;
    for i in 0..a.len() {
        diff |= a[i] ^ b[i];  // XOR gives 0 if equal, non-zero otherwise
    }
    // Return true if diff is 0 (all bytes equal)
    diff == 0
}

// Proper constant-time comparison using bit manipulation
fn constant_time_compare_proper(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }

    let mut diff = 0u8;
    for i in 0..a.len() {
        diff |= a[i] ^ b[i];  // XOR of equal bytes is 0
    }

    // Convert to boolean: 0 means all bytes equal, non-zero means different
    // This is not truly constant time due to the final comparison
    // For true constant time, we'd need to use choice() or similar

    // Better approach with proper constant-time logic:
    let mut result = 1u8;
    for i in 0..a.len() {
        let equal_bit = if a[i] == b[i] { 1u8 } else { 0u8 };
        result &= equal_bit;  // This is still not truly constant time due to bit operations
    }

    result != 0
}

// Most correct implementation using bit manipulation with constant-time checks
fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }

    let mut result = 0u64;
    for i in 0..a.len() {
        // Use bitwise operations that are constant time
        let xor_result = (a[i] as u64) ^ (b[i] as u64);
        result |= xor_result;  // If any byte differs, result will be non-zero
    }

    // Convert to boolean in a way that's constant-time
    // This is the standard approach for constant-time comparison
    let equal = (result == 0) as u8;
    equal != 0
}

// If you want to use rand_constant_time::choice properly:
use rand_constant_time::choice;

fn constant_time_compare_with_choice(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }

    let mut result = 1u8;
