}

// Simple, clean example:
fn simple_constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    // Standard approach - works well for most cases
    if a.len() != b.len() {
        return false;
    }

    let mut diff = 0u8;
    for (a_byte, b_byte) in a.iter().zip(b.iter()) {
        diff |= a_byte ^ b_byte;  // XOR to detect differences
    }

    diff == 0
}

// Example usage
fn main() {
