    let slice2 = b"hello world";
    let slice3 = b"hello worlf";

    println!("Equal: {}", simple_constant_time_eq(slice1, slice2)); // true
    println!("Equal: {}", simple_constant_time_eq(slice1, slice3)); // false

    // For production use with rand_constant_time crate:
    // You would typically do something like:
    let test1 = b"secret";
    let test2 = b"secret";
    let is_equal = simple_constant_time_eq(test1, test2);
