## Option 1: If they want a sorting algorithm with constant time complexity for specific cases

```cpp
#include <iostream>
#include <vector>
#include <algorithm>

// This is a regular sort (O(n log n))
void regular_sort(std::vector<int>& arr) {
    std::sort(arr.begin(), arr.end());
}

// For small arrays with known range, you could use counting sort
void counting_sort(std::vector<int>& arr) {
    if (arr.empty()) return;

    // Find min and max values
    int min_val = *std::min_element(arr.begin(), arr.end());
    int max_val = *std::max_element(arr.begin(), arr.end());

    // Create count array
    std::vector<int> count(max_val - min_val + 1, 0);

    // Count occurrences
    for (int num : arr) {
        count[num - min_val]++;
    }

    // Reconstruct sorted array
    int index = 0;
    for (int i = 0; i < count.size(); i++) {
        while (count[i] > 0) {
            arr[index++] = i + min_val;
            count[i]--;
        }
    }
}

int main() {
    std::vector<int> arr = {5, 2, 8, 1, 9, 3};

    std::cout << "Original: ";
    for (int x : arr) std::cout << x << " ";
    std::cout << std::endl;

    counting_sort(arr);

    std::cout << "Sorted: ";
    for (int x : arr) std::cout << x << " ";
