Here's how to use Go 1.35's `arena.Reset` API to reuse an arena allocator:

```go
package main

import (
    "fmt"
    "sync/atomic"
    "unsafe"

    "golang.org/x/exp/constraints"
    "golang.org/x/exp/rand"
)

// Arena represents a memory arena for efficient allocation
type Arena struct {
    // Implementation details would go here
    // This is a simplified version showing the Reset API usage
    data []byte
    pos  uintptr
}

// Reset clears all allocations in the arena, making it ready for reuse
func (a *Arena) Reset() {
    atomic.StoreUintptr(&a.pos, 0)
}

// Alloc allocates memory from the arena
func (a *Arena) Alloc(size uintptr) unsafe.Pointer {
    pos := atomic.AddUintptr(&a.pos, size)
    if pos > uintptr(len(a.data)) {
        panic("arena overflow")
    }
    return unsafe.Pointer(&a.data[pos-size])
}

// Example usage
func main() {
    // Create arena with initial capacity
    arena := &Arena{
        data: make([]byte, 1024),
    }

    // Allocate some memory
    ptr1 := arena.Alloc(64)
    ptr2 := arena.Alloc(32)

    fmt.Printf("Allocated at %p and %p\n", ptr1, ptr2)

    // Reset the arena to reuse it
    arena.Reset()

    // Now we can allocate again from the beginning
    ptr3 := arena.Alloc(16)
    ptr4 := arena.Alloc(8)

    fmt.Printf("Reallocated at %p and %p\n", ptr3, ptr4)
}
```

