import java.util.*;
import java.util.concurrent.*;

public class ConsensusModule {
    private final int nodeId;
    private final Map<Integer, Node> nodes = new HashMap<>();
    private final ExecutorService executor = Executors.newFixedThreadPool(10);
    private volatile boolean crashed = false;

    public ConsensusModule(int nodeId) {
        this.nodeId = nodeId;
    }

    // Add other nodes to the network
    public void addNode(Node node) {
        nodes.put(node.getId(), node);
    }

    // Propose a value for consensus
    public CompletableFuture<String> proposeValue(String value) {
        return CompletableFuture.supplyAsync(() -> {
            if (crashed) throw new RuntimeException("Node crashed");

            // Phase 1: Prepare
            int highestProposalId = findHighestProposalId();
            int proposalId = highestProposalId + 1;

            Map<Integer, Boolean> prepareResponses = new HashMap<>();
            for (Node node : nodes.values()) {
                try {
                    boolean response = node.prepare(proposalId);
                    prepareResponses.put(node.getId(), response);
                } catch (Exception e) {
                    // Node might be crashed
                }
            }

            // Need majority of responses
            int majority = nodes.size() / 2 + 1;
            if (prepareResponses.values().stream().filter(b -> b).count() < majority) {
                throw new RuntimeException("Failed to get majority in prepare phase");
            }

            // Phase 2: Accept
            Map<Integer, String> acceptResponses = new HashMap<>();
            for (Node node : nodes.values()) {
                try {
                    String response = node.accept(proposalId, value);
                    acceptResponses.put(node.getId(), response);
                } catch (Exception e) {
                    // Node might be crashed
                }
            }

            if (acceptResponses.values().stream().filter(v -> v != null).count() < majority) {
                throw new RuntimeException("Failed to get majority in accept phase");
            }

            return value;
        }, executor);
    }

    private int findHighestProposalId() {
        // In a real implementation, this would query other nodes
        return 0;
    }

    public void crash() {
        crashed = true;
    }

    public boolean isCrashed() {
        return crashed;
    }
}

class Node {
    private final int id;
    private volatile int highestProposalId = -1;
    private volatile String acceptedValue = null;

    public Node(int id) {
        this.id = id;
    }

    public int getId() {
        return id;
    }

    // Phase 1: Prepare
    public synchronized boolean prepare(int proposalId) {
        if (proposalId > highestProposalId) {
            highestProposalId = proposalId;
            return true;
        }
        return false;
    }

    // Phase 2: Accept
    public synchronized String accept(int proposalId, String value) {
        if (proposalId >= highestProposalId) {
            acceptedValue = value;
            highestProposalId = proposalId;
            return value;
        }
        return null;
    }

    public String getAcceptedValue() {
        return acceptedValue;
    }
}

// Example usage
