        : sender(s), sequence(seq), type(t), data(d) {}
};

class Node {
private:
    int id;
    vector<Node*> peers;
    mutex mtx;
    condition_variable cv;
    bool ready;

    // State variables
    map<int, Message> pre_prepare_messages; // seq -> message
    map<int, map<int, Message>> prepare_messages; // seq -> (node_id -> message)
    map<int, map<int, Message>> commit_messages; // seq -> (node_id -> message)
    map<int, string> replies; // seq -> data

public:
    Node(int id) : id(id), ready(false) {}

    void addPeer(Node* peer) {
        peers.push_back(peer);
    }

    void start() {
        thread([this]() { this->run(); }).detach();
    }

    void run() {
        while (true) {
            unique_lock<mutex> lock(mtx);

            // Wait for work or timeout
            if (!cv.wait_for(lock, chrono::milliseconds(timeout_ms), [this]() { return ready; })) {
                // Timeout occurred - handle view change
                cout << "Node " << id << ": Timeout occurred" << endl;
                handleTimeout();
                continue;
