        cout << "Node " << id << ": Received " << messageTypeToString(msg.type)
             << " from node " << msg.sender << endl;

        switch (msg.type) {
            case PRE_PREPARE:
                handlePrePrepare(msg);
                break;
            case PREPARE:
                handlePrepare(msg);
                break;
            case COMMIT:
                handleCommit(msg);
                break;
            case REPLY:
                handleReply(msg);
                break;
            default:
