            prepare_messages[msg.sequence][msg.sender] = msg;
        }

        // Check if we have enough prepares
        auto& prepares = prepare_messages[msg.sequence];
        if (prepares.size() >= 2 * f + 1) { // n nodes
            // Send commit message to all peers
            Message commit(id, msg.sequence, COMMIT);
            broadcast(commit);
        }
    }

    void handleCommit(const Message& msg) {
