        switch (type) {
            case REQUEST: return "REQUEST";
            case PRE_PREPARE: return "PRE_PREPARE";
            case PREPARE: return "PREPARE";
            case COMMIT: return "COMMIT";
            case REPLY: return "REPLY";
            default: return "UNKNOWN";
        }
    }

public:
    void triggerRequest() {
        lock_guard<mutex> lock(mtx);
        ready = true;
        cv.notify_one();
    }
};

int main() {
    // Create nodes
    vector<Node*> nodes;
    for (int i = 0; i < n; ++i) {
        nodes.push_back(new Node(i));
    }

    // Connect peers
    for (auto node : nodes) {
        for (auto peer : nodes) {
            if (peer->id != node->id) {
                node->addPeer(peer);
            }
        }
    }

    // Start all nodes
    for (auto node : nodes) {
        node->start();
    }

    // Simulate a client request to one node
    this_thread::sleep_for(chrono::milliseconds(100));
    nodes[0]->triggerRequest();

    // Keep running
    while (true) {
        this_thread::sleep_for(chrono::seconds(1));
    }

    return 0;
}
