It's impossible to build a key-value store that simultaneously guarantees **strong consistency**, **full availability**, and **partition tolerance** because these properties violate the **CAP theorem**. You can only satisfy two out of three.

However, if you want a system that prioritizes **strong consistency and partition tolerance (CP)**, here’s an example using **Raft consensus algorithm** in Go. This design sacrifices availability during partitions but ensures strong consistency when the system is operational.

### Example: Raft-based Key-Value Store (Go)
```go
package main

import (
	"fmt"
	"sync"
)

// Node represents a node in the Raft cluster.
type Node struct {
	id          int
	state       string // "follower", "candidate", "leader"
	currentTerm int
	votedFor    int
	log         []LogEntry
}

// LogEntry represents an entry in the Raft log.
type LogEntry struct {
	Command interface{}
	Term    int
}

// KeyValueStore is a simple key-value store using Raft for consensus.
type KeyValueStore struct {
	nodes      map[int]*Node
	leader     *Node
	mu         sync.Mutex
	data       map[string]string
}

// NewKeyValueStore initializes a new key-value store with Raft nodes.
func NewKeyValueStore(nodeIDs []int) *KeyValueStore {
	store := &KeyValueStore{
		nodes: make(map[int]*Node),
		data:  make(map[string]string),
	}

	for _, id := range nodeIDs {
		store.nodes[id] = &Node{
			id:          id,
			state:       "follower",
			currentTerm: 0,
			votedFor:    -1, // No vote
			log:         []LogEntry{},
		}
	}

	return store
}

// Set writes a key-value pair to the store (only leader can accept writes).
func (store *KeyValueStore) Set(key, value string) error {
	store.mu.Lock()
	defer store.mu.Unlock()

	if store.leader == nil {
		return fmt.Errorf("no leader elected")
	}

	// Append to Raft log and replicate
	logEntry := LogEntry{
		Command: map[string]string{key: value},
		Term:    store.leader.currentTerm,
	}
	store.leader.log = append(store.leader.log, logEntry)

	// Replicate to followers (simplified)
	for _, node := range store.nodes {
		if node.id != store.leader.id {
			node.log = append(node.log, logEntry)
		}
	}

	// Apply the command locally
	for k, v := range logEntry.Command.(map[string]string) {
		store.data[k] = v
	}

	return nil
}

// Get retrieves a value by key.
func (store *KeyValueStore) Get(key string) (string, error) {
	store.mu.Lock()
	defer store.mu.Unlock()

	value, exists := store.data[key]
	if !exists {
		return "", fmt.Errorf("key not found")
	}
	return value, nil
}

// ElectLeader simulates leader election (simplified).
func (store *KeyValueStore) ElectLeader() {
	// In a real implementation, use Raft's election algorithm.
	for id, node := range store.nodes {
		if node.state == "follower" {
			node.state = "candidate"
			node.currentTerm++
			node.votedFor = id
		}
	}

	// Assume the first candidate becomes leader (simplified)
	for _, node := range store.nodes {
		if node.state == "candidate" {
			node.state = "leader"
			store.leader = node
			break
		}
	}
}

func main() {
	store := NewKeyValueStore([]int{1, 2, 3})
	store.ElectLeader()

	// Write a key-value pair
	err := store.Set("foo", "bar")
	if err != nil {
		fmt.Println("Error:", err)
		return
	}

	// Read the value
	value, err := store.Get("foo")
	if err != nil {
		fmt.Println("Error:", err)
		return
	}

	fmt.Printf("Value for 'foo': %s\n", value) // Output: Value for 'foo': bar
}
```

### How It Works:
1. **Raft Consensus**: The system uses Raft to ensure strong consistency. Only the leader processes writes, and changes are replicated to followers.
2. **Log Replication**: Writes are appended to a log before being applied to the state machine (key-value store).
3. **Leader Election**: If the leader fails, a new election is triggered to maintain availability when possible.

### Why CAP Theorem Applies:
- **Strong Consistency + Partition Tolerance (CP)**: The system remains consistent but may become unavailable during network partitions.
- **Availability + Partition Tolerance (AP)**: Systems like DynamoDB sacrifice consistency for availability.
- **Strong Consistency + Availability (CA)**: Only possible in non-partitioned networks.

