    // Launch kernel (GPU will access the same memory)
    dim3 threadsPerBlock(256);
    dim3 numBlocks((N + threadsPerBlock.x - 1) / threadsPerBlock.x);

    // Kernel to double each element
    auto kernel = [] __global__(float *d_data) {
        int idx = blockIdx.x * blockDim.x + threadIdx.x;
        d_data[idx] *= 2.0f;
    };

    kernel<<<numBlocks, threadsPerBlock>>>(data);

    // Wait for GPU to finish (implicit synchronization)
    cudaDeviceSynchronize();

    // Verify results on CPU
    for (int i = 0; i < N; ++i) {
        if (data[i] != static_cast<float>(2 * i)) {
            std::cerr << "Error at index " << i << std::endl;
            break;
        }
    }

    // Free memory
    cudaFree(data);

    return 0;
}
```

#### Key Points:
- `cudaMallocManaged` allocates memory that is accessible by both CPU and GPU.
- The kernel operates directly on the same pointer as the CPU.
- `cudaDeviceSynchronize()` ensures the GPU has finished before the CPU reads the results (though UVM often handles this automatically).

---

### 2. Using OpenCL with Shared Virtual Memory
OpenCL supports shared virtual memory (SVM) for coherent access between CPU and GPU.

#### Example:
```cpp
#include <iostream>
#include <CL/cl.h>

int main() {
    const int N = 1024;
    float *data;

    // Initialize OpenCL
    cl_platform_id platform;
    clGetPlatformIDs(1, &platform, NULL);

    cl_device_id device;
    clGetDeviceIDs(platform, CL_DEVICE_TYPE_GPU, 1, &device, NULL);

    cl_context context = clCreateContext(NULL, 1, &device, NULL, NULL, NULL);
    cl_command_queue queue = clCreateCommandQueue(context, device, 0, NULL);

    // Allocate SVM memory
    data = static_cast<float*>(clSVMAlloc(context, CL_MEM_READ_WRITE, N * sizeof(float), 0));

    // Initialize on CPU
    for (int i = 0; i < N; ++i) {
        data[i] = static_cast<float>(i);
    }

    // Build kernel
    const char *kernelSource =
        "kernel void double_data(global float *data, int n) {"
        "   int idx = get_global_id(0);"
        "   if (idx < n) data[idx] *= 2.0f;"
        "}";

    cl_program program = clCreateProgramWithSource(context, 1, &kernelSource, NULL, NULL);
    clBuildProgram(program, 1, &device, NULL, NULL, NULL);

    cl_kernel kernel = clCreateKernel(program, "double_data", NULL);

    // Set SVM pointer as kernel argument
    clSetKernelArgSVMPointer(kernel, 0, data);
    clSetKernelArg(kernel, 1, sizeof(int), &N);

    // Execute kernel
    size_t globalWorkSize = N;
    clEnqueueNDRangeKernel(queue, kernel, 1, NULL, &globalWorkSize, NULL, 0, NULL, NULL);

    // Wait for completion (implicit synchronization)
    clFinish(queue);

    // Verify on CPU
    for (int i = 0; i < N; ++i) {
        if (data[i] != static_cast<float>(2 * i)) {
            std::cerr << "Error at index " << i << std::endl;
            break;
        }
    }

    // Cleanup
    clReleaseKernel(kernel);
    clReleaseProgram(program);
    clReleaseCommandQueue(queue);
    clReleaseContext(context);
    clSVMFree(context, data);

    return 0;
}
```

#### Key Points:
- `clSVMAlloc` allocates memory accessible by both CPU and GPU.
- The kernel uses the same pointer as the CPU.
- `clFinish` ensures the GPU has completed before the CPU reads the results.

---

### Notes:
1. **Performance**: While UVM/SVM eliminates explicit transfers, the runtime may still perform implicit migrations (e.g., on first access). For best performance, profile your workload.
2. **Portability**: CUDA is NVIDIA-specific; OpenCL is cross-platform but may have vendor-specific optimizations.
3. **Synchronization**: Even with UVM/SVM, some operations (e.g., `cudaDeviceSynchronize` or `clFinish`) are needed to ensure correctness.

