import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;

public class RaftConsensus {
    private final String serverId;
    private final List<String> peers;
    private final int electionTimeoutMin;
    private final int electionTimeoutMax;
    private final int heartbeatInterval;
    private final Map<String, Integer> nextIndex = new HashMap<>();
    private final Map<String, Integer> matchIndex = new HashMap<>();
    private final AtomicReference<RaftState> state = new AtomicReference<>(RaftState.FOLLOWER);
    private final AtomicReference<String> currentLeader = new AtomicReference<>(null);
    private final AtomicReference<Integer> currentTerm = new AtomicReference<>(0);
    private final AtomicReference<LogEntry> log = new AtomicReference<>(new LogEntry(0, null));
    private final ScheduledExecutorService executor = Executors.newScheduledThreadPool(2);

    public RaftConsensus(String serverId, List<String> peers) {
        this.serverId = serverId;
        this.peers = new ArrayList<>(peers);
        this.electionTimeoutMin = 150;
        this.electionTimeoutMax = 300;
        this.heartbeatInterval = 50;

        // Initialize nextIndex and matchIndex for all peers
        peers.forEach(peer -> {
            nextIndex.put(peer, log.get().getTerm() + 1);
            matchIndex.put(peer, -1);
        });

        startElectionTimer();
    }

    public void start() {
        executor.scheduleAtFixedRate(this::sendHeartbeat, heartbeatInterval, heartbeatInterval, TimeUnit.MILLISECONDS);
    }

    private void startElectionTimer() {
        int timeout = electionTimeoutMin + new Random().nextInt(electionTimeoutMax - electionTimeoutMin);
        executor.schedule(() -> {
            if (state.get() != RaftState.LEADER) {
                becomeCandidate();
            }
        }, timeout, TimeUnit.MILLISECONDS);
    }

    private void becomeCandidate() {
        state.set(RaftState.CANDIDATE);
        currentTerm.incrementAndGet();

        // Vote for self
        if (requestVote()) {
            becomeLeader();
        } else {
            startElectionTimer(); // Didn't get majority, try again
        }
    }

    private boolean requestVote() {
        int votesReceived = 1; // Self vote

        for (String peer : peers) {
            if (peer.equals(serverId)) continue;

            try {
                // Simulate network call with timeout
                Future<Boolean> future = executor.submit(() -> {
                    // In real implementation, this would be an RPC call
                    return true; // Assume success for example
                });

                boolean voted = future.get(100, TimeUnit.MILLISECONDS);
                if (voted) votesReceived++;
            } catch (TimeoutException | ExecutionException | InterruptedException e) {
                System.err.println("Vote request to " + peer + " failed: " + e.getMessage());
            }
        }

        return votesReceived > peers.size() / 2;
    }

    private void becomeLeader() {
        state.set(RaftState.LEADER);
        currentLeader.set(serverId);

        // Initialize nextIndex and matchIndex for replication
        peers.forEach(peer -> {
            nextIndex.put(peer, log.get().getTerm());
            matchIndex.put(peer, -1);
        });
    }

    private void sendHeartbeat() {
        if (state.get() != RaftState.LEADER) return;

        for (String peer : peers) {
            if (peer.equals(serverId)) continue;

            try {
                // Simulate heartbeat with timeout
                Future<Boolean> future = executor.submit(() -> {
                    // In real implementation, this would be an RPC call
                    return true; // Assume success for example
                });

                boolean success = future.get(50, TimeUnit.MILLISECONDS);
                if (success) {
                    matchIndex.put(peer, log.get().getTerm());
                } else {
                    System.err.println("Heartbeat to " + peer + " failed");
                    // Increment nextIndex for this peer
                    nextIndex.merge(peer, 1, Integer::sum);
                }
            } catch (TimeoutException | ExecutionException | InterruptedException e) {
                System.err.println("Heartbeat to " + peer + " timed out: " + e.getMessage());
                nextIndex.merge(peer, 1, Integer::sum);
            }
        }

        // Reset election timer for leader
        startElectionTimer();
    }

    public void shutdown() {
        executor.shutdown();
    }

    private enum RaftState { FOLLOWER, CANDIDATE, LEADER }
    private static class LogEntry {
        private final int term;
        private final Object command;

        public LogEntry(int term, Object command) {
            this.term = term;
            this.command = command;
        }

        public int getTerm() { return term; }
        public Object getCommand() { return command; }
    }
}
