# Lease-Based Lock with Fencing Tokens in Go

Here's a minimal working example of a lease-based distributed lock with fencing tokens in Go, including clear failure handling:

```go
package main

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"
)

// DistributedLock represents our lease-based lock with fencing tokens
type DistributedLock struct {
	mu          sync.Mutex
	leaseHolder string // ID of the current lease holder
	leaseExpiry time.Time
	fenceToken  int64 // Fencing token for cache invalidation

	// In a real implementation, these would be distributed:
	// - A distributed store (like Redis) to track leases
	// - A way to generate unique fence tokens
}

// NewDistributedLock creates a new lock instance
func NewDistributedLock() *DistributedLock {
	return &DistributedLock{
		fenceToken: 0,
	}
}

// Acquire attempts to acquire the lock with a lease duration
func (dl *DistributedLock) Acquire(ctx context.Context, holderID string, leaseDuration time.Duration) error {
	dl.mu.Lock()
	defer dl.mu.Unlock()

	// Check if we already hold the lease
	if dl.leaseHolder == holderID && time.Now().Before(dl.leaseExpiry) {
		return nil // Already locked by us
	}

	// In a real implementation, this would be an atomic compare-and-swap operation
	// on a distributed store to acquire the lock

	// Simulate acquiring the lock
	if dl.leaseHolder == "" || time.Now().After(dl.leaseExpiry) {
		dl.leaseHolder = holderID
		dl.leaseExpiry = time.Now().Add(leaseDuration)
		dl.fenceToken++ // Increment fence token on new lease
		return nil
	}

	// Lock is held by someone else
	return errors.New("lock not available")
}

// Release releases the lock if we hold it
func (dl *DistributedLock) Release(ctx context.Context, holderID string) error {
	dl.mu.Lock()
	defer dl.mu.Unlock()

	if dl.leaseHolder != holderID || time.Now().After(dl.leaseExpiry) {
		return errors.New("not the lease holder or lease expired")
	}

	// In a real implementation, this would release the lock in the distributed store
	dl.leaseHolder = ""
	return nil
}

// GetFenceToken returns the current fence token for cache invalidation
func (dl *DistributedLock) GetFenceToken() int64 {
	dl.mu.Lock()
	defer dl.mu.Unlock()
	return dl.fenceToken
}

// Renew extends the lease if we hold it
func (dl *DistributedLock) Renew(ctx context.Context, holderID string, newDuration time.Duration) error {
	dl.mu.Lock()
	defer dl.mu.Unlock()

	if dl.leaseHolder != holderID || time.Now().After(dl.leaseExpiry) {
		return errors.New("not the lease holder or lease expired")
	}

	// Extend the lease
	dl.leaseExpiry = time.Now().Add(newDuration)
	return nil
}

// Example usage
func main() {
	lock := NewDistributedLock()
	ctx := context.Background()

	// Worker 1 tries to acquire the lock
	err := lock.Acquire(ctx, "worker-1", 5*time.Second)
	if err != nil {
		fmt.Printf("Worker 1 failed to acquire lock: %v\n", err)
		return
	}
	defer lock.Release(ctx, "worker-1")

	fmt.Println("Worker 1 acquired the lock")
	fenceToken := lock.GetFenceToken()
	fmt.Printf("Current fence token: %d\n", fenceToken)

	// Simulate some work
	time.Sleep(2 * time.Second)

	// Worker 1 renews the lease
	err = lock.Renew(ctx, "worker-1", 5*time.Second)
	if err != nil {
		fmt.Printf("Worker 1 failed to renew lease: %v\n", err)
	}

	// Worker 2 tries to acquire (should fail)
	err = lock.Acquire(ctx, "worker-2", 5*time.Second)
	if err != nil {
		fmt.Printf("Worker 2 correctly failed to acquire locked resource: %v\n", err)
	} else {
		fmt.Println("Worker 2 acquired the lock - this shouldn't happen!")
	}

	// After worker 1 releases, worker 2 can acquire
	lock.Release(ctx, "worker-1")
	err = lock.Acquire(ctx, "worker-2", 5*time.Second)
	if err != nil {
		fmt.Printf("Worker 2 failed to acquire after release: %v\n", err)
	} else {
		fmt.Println("Worker 2 successfully acquired the lock after worker 1 released")
	}
}
```

