# Byzantine Agreement in C++ (PBFT-like Protocol)

Here's a basic implementation of Practical Byzantine Fault Tolerance (PBFT) for n=3f+1 nodes with clear failure handling:

```cpp
#include <iostream>
#include <vector>
#include <map>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <random>

using namespace std;

// Node states
enum State { PRIMARY, BACKUP, PRE_PREPARE, PREPARE, COMMIT, EXECUTE };

// Message types
enum MsgType { REQUEST, PRE_PREPARE, PREPARE, COMMIT, REPLY };

struct Message {
    int sender;
    MsgType type;
    string data;
    int sequence;
    vector<int> signatures; // Simplified - in real PBFT this would be digital signatures
};

// Node class representing a PBFT node
class Node {
private:
    int id;
    State state = BACKUP;
    int primary_id;
    map<int, Message> pre_prepare_messages;
    map<int, vector<Message>> prepare_messages;
    map<int, vector<Message>> commit_messages;
    mutex mtx;
    condition_variable cv;
    bool running = true;

public:
    Node(int id, int n) : id(id) {
        // In PBFT with n=3f+1 nodes, primary is node 0
        primary_id = 0;
    }

    void handle_message(const Message& msg) {
        lock_guard<mutex> lock(mtx);

        switch (msg.type) {
            case PRE_PREPARE:
                handle_pre_prepare(msg);
                break;
            case PREPARE:
                handle_prepare(msg);
                break;
            case COMMIT:
                handle_commit(msg);
                break;
            default:
                cout << "Node " << id << ": Received unexpected message type" << endl;
        }
    }

    void handle_pre_prepare(const Message& msg) {
        if (msg.sender != primary_id) {
            cout << "Node " << id << ": Received PRE-PREPARE from non-primary node " << msg.sender << endl;
            return;
        }

        pre_prepare_messages[msg.sequence] = msg;

        // Check if we have enough PREPARE messages
        int f = (n - 1) / 3; // Maximum number of faulty nodes
        if (prepare_messages[msg.sequence].size() >= 2 * f + 1) {
            state = COMMIT;
            cv.notify_all();
        }
    }

    void handle_prepare(const Message& msg) {
        prepare_messages[msg.sequence].push_back(msg);

        // Check if we have enough PREPARE messages
        int f = (n - 1) / 3; // Maximum number of faulty nodes
        if (prepare_messages[msg.sequence].size() >= 2 * f + 1 &&
            pre_prepare_messages.count(msg.sequence)) {
            state = COMMIT;
            cv.notify_all();
        }
    }

    void handle_commit(const Message& msg) {
        commit_messages[msg.sequence].push_back(msg);

        // Check if we have enough COMMIT messages
        int f = (n - 1) / 3; // Maximum number of faulty nodes
        if (commit_messages[msg.sequence].size() >= 2 * f + 1) {
            state = EXECUTE;
            cv.notify_all();
        }
    }

    void send_pre_prepare(const string& data, int sequence) {
        Message msg;
        msg.sender = id;
        msg.type = PRE_PREPARE;
        msg.data = data;
        msg.sequence = sequence;

        // In a real implementation, we would sign the message here
        msg.signatures.push_back(id); // Simplified

        // Broadcast to all nodes including self
        for (int i = 0; i < n; ++i) {
            if (nodes[i].id != id) { // Don't send to self in this simplified version
                nodes[i].handle_message(msg);
            }
        }
    }

    void run() {
        while (running) {
            unique_lock<mutex> lock(mtx);

            // Wait for state change or timeout
            if (cv.wait_for(lock, chrono::seconds(1)) == cv_status::timeout) {
                handle_timeout();
            }

            // Process state changes
            switch (state) {
                case PRE_PREPARE:
                    // In a real implementation, we would wait for requests here
                    break;
                case COMMIT:
                    // Send commit message
                    if (!commit_messages.empty()) {
                        int seq = commit_messages.begin()->first;
                        Message msg;
                        msg.sender = id;
                        msg.type = COMMIT;
                        msg.sequence = seq;

                        // Broadcast to all nodes including self
                        for (int i = 0; i < n; ++i) {
                            if (nodes[i].id != id) { // Don't send to self in this simplified version
                                nodes[i].handle_message(msg);
                            }
                        }
                    }
                    break;
                case EXECUTE:
                    cout << "Node " << id << ": Executing transaction" << endl;
                    state = BACKUP;
                    break;
            }
        }
    }

    void handle_timeout() {
        // In a real implementation, we would detect primary failure and trigger view change
        cout << "Node " << id << ": Timeout occurred. State: ";
        switch (state) {
            case PRIMARY: cout << "PRIMARY"; break;
            case BACKUP: cout << "BACKUP"; break;
            case PRE_PREPARE: cout << "PRE-PREPARE"; break;
            case PREPARE: cout << "PREPARE"; break;
            case COMMIT: cout << "COMMIT"; break;
            case EXECUTE: cout << "EXECUTE"; break;
        }
        cout << endl;

        // Simplified view change - in real PBFT this is more complex
        if (state == PRE_PREPARE || state == PREPARE) {
            state = COMMIT;
            cv.notify_all();
        }
    }

    void stop() {
        running = false;
        cv.notify_all();
    }

private:
    vector<Node>& nodes; // Reference to all nodes in the system
    int n; // Total number of nodes
};

// Global vector of nodes for simplicity (in real implementation, each node would have its own list)
vector<Node> nodes;

int main() {
    const int n = 4; // 3f+1 where f=1 (can tolerate 1 faulty node)
    nodes.reserve(n);

    // Create nodes
    for (int i = 0; i < n; ++i) {
        nodes.emplace_back(i, n);
