use std::collections::HashMap;

pub struct MinimalPerfectHash {
    keys: Vec<String>,
    hash_table: HashSet<u64>,
}

impl MinimalPerfectHash {
    pub fn new(keys: Vec<String>) -> Self {
        // This is a simplified example - real implementation would use more sophisticated algorithms
        let mut hash_table = HashSet::new();
        for key in &keys {
            let hash = Self::compute_hash(key);
            hash_table.insert(hash);
        }
        MinimalPerfectHash { keys, hash_table }
    }

    fn compute_hash(key: &str) -> u64 {
        // Simple hash function - in practice you'd use something more robust
        let mut hash = 5381;
        for byte in key.bytes() {
            hash = ((hash << 5).wrapping_add(hash)) ^ (byte as u64);
        }
        hash
    }

    pub fn get(&self, key: &str) -> Option<usize> {
        let hash = Self::compute_hash(key);
        if self.hash_table.contains(&hash) {
            // Find the index of this key in our keys vector
            self.keys.iter().position(|k| k == key)
        } else {
            None
        }
    }
}
