```python
def parse(input_string):
    pos = 0

    def match(token):
        nonlocal pos
        if input_string[pos] == token:
            pos += 1
            return True
        else:
            raise SyntaxError(f"Expected {token}, got {input_string[pos]}")

    # Example grammar: S -> a A | b B, A -> c, B -> d
    def parse_S():
        if input_string[pos] == 'a':
            match('a')
            parse_A()
        elif input_string[pos] == 'b':
            match('b')
            parse_B()

    def parse_A():
        match('c')

    def parse_B():
        match('d')

    # Start parsing
