parse(input_str)
```

This example demonstrates a recursive descent parser for a simple LL(1) grammar. The `match` function checks the current token and advances the position if it matches. Each non-terminal has its own parsing function that implements the corresponding production rules.

For more complex grammars, you would need to add more functions and handle more cases, but the basic structure remains the same. The time complexity is O(n) where n is the length of the input string, as each character is processed exactly once.

# Implementing a 2D K-D Tree for Nearest Neighbor Queries in C++

Here's a complete implementation of a 2D k-d tree that can efficiently answer nearest neighbor queries:

```cpp
#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <limits>

using namespace std;

// Point structure to represent 2D points
struct Point {
    double x, y;
    int id; // Optional: identifier for the point

    Point(double x = 0, double y = 0, int id = -1) : x(x), y(y), id(id) {}

    // Calculate Euclidean distance between two points
    double distanceTo(const Point& other) const {
        double dx = x - other.x;
        double dy = y - other.y;
        return sqrt(dx*dx + dy*dy);
    }
};

// Node structure for the k-d tree
struct KDNode {
    Point point;
    KDNode* left;
    KDNode* right;

    KDNode(const Point& p) : point(p), left(nullptr), right(nullptr) {}
};

// K-D Tree class
class KDTree {
private:
    KDNode* root;
    int dim; // Current dimension for splitting (0 for x, 1 for y)

    // Helper function to build the tree recursively
    KDNode* buildTree(vector<Point>& points, int depth = 0) {
        if (points.empty()) return nullptr;

        // Determine current split dimension
        dim = depth % 2;

        // Sort points based on current dimension
        auto cmp = [dim](const Point& a, const Point& b) {
            return (dim == 0) ? (a.x < b.x) : (a.y < b.y);
        };
        sort(points.begin(), points.end(), cmp);

        // Choose median as pivot point
        size_t mid = points.size() / 2;
        KDNode* node = new KDNode(points[mid]);

        // Recursively build left and right subtrees
        vector<Point> leftPoints(points.begin(), points.begin() + mid);
        vector<Point> rightPoints(points.begin() + mid + 1, points.end());

        node->left = buildTree(leftPoints, depth + 1);
        node->right = buildTree(rightPoints, depth + 1);

        return node;
    }

    // Helper function for nearest neighbor search
    void nearestNeighborHelper(KDNode* node, const Point& query,
                             Point& best, double& bestDist, int depth) {
        if (!node) return;

        double currentDist = query.distanceTo(node->point);

        // Update best if current point is closer
        if (currentDist < bestDist) {
            best = node->point;
            bestDist = currentDist;
        }

        // Determine which subtree to explore first
        dim = depth % 2;
        KDNode* firstSubtree, *secondSubtree;

        if ((dim == 0 && query.x < node->point.x) ||
            (dim == 1 && query.y < node->point.y)) {
            firstSubtree = node->left;
            secondSubtree = node->right;
        } else {
            firstSubtree = node->right;
            secondSubtree = node->left;
        }

        // Explore the subtree that might contain the nearest neighbor
        nearestNeighborHelper(firstSubtree, query, best, bestDist, depth + 1);

        // Check if we need to explore the other subtree
        double axisDist;
        if (dim == 0) {
            axisDist = abs(query.x - node->point.x);
        } else {
            axisDist = abs(query.y - node->point.y);
        }

        if (axisDist < bestDist) {
            nearestNeighborHelper(secondSubtree, query, best, bestDist, depth + 1);
        }
    }

public:
    // Constructor
    KDTree(vector<Point>& points) {
        root = buildTree(points);
    }

    // Destructor to free memory
    ~KDTree() {
        destroyTree(root);
    }

    void destroyTree(KDNode* node) {
        if (node) {
            destroyTree(node->left);
            destroyTree(node->right);
            delete node;
        }
    }

    // Find nearest neighbor to the query point
    Point nearestNeighbor(const Point& query) {
        Point best;
        double bestDist = numeric_limits<double>::max();
        nearestNeighborHelper(root, query, best, bestDist, 0);
        return best;
    }
};

int main() {
    // Example usage
    vector<Point> points = {
        {2.0, 3.0, 1},
        {5.0, 4.0, 2},
        {9.0, 6.0, 3},
        {4.0, 7.0, 4},
        {8.0, 1.0, 5},
        {7.0, 2.0, 6}
    };

    KDTree tree(points);

    Point query(9.0, 2.0);
    Point nearest = tree.nearestNeighbor(query);

    cout << "Query point: (" << query.x << ", " << query.y << ")" << endl;
    cout << "Nearest neighbor: (" << nearest.x << ", " << nearest.y
         << ") with ID " << nearest.id << endl;

    return 0;
}
```

## Key Features of This Implementation:

1. **Point Structure**: Represents 2D points with x, y coordinates and an optional ID.

2. **KDNode Structure**: The building block of the k-d tree, containing a point and pointers to left/right children.

3. **Tree Construction**:
   - Points are sorted based on alternating dimensions (x then y)
   - Median point is chosen as the root at each level
   - Recursively builds left and right subtrees

4. **Nearest Neighbor Search**:
   - Uses a priority search approach, exploring the most promising subtree first
   - Only explores other subtrees if they might contain a closer point
   - Maintains the best candidate found so far

5. **Efficiency**:
   - Construction: O(n log n) due to sorting at each level
   - Query: O(log n) on average for balanced trees

## How to Use:

1. Create a vector of Point objects with your data points.
2. Construct a KDTree object by passing the vector.
3. Call nearestNeighbor() with any query point to find its nearest neighbor.

