# Parsing NMEA 0183 GPS Sentences in Go

Here's a minimal working example to parse common NMEA 0183 GPS sentences (like GGA, RMC) in Go:

```go
package main

import (
	"fmt"
	"strconv"
	"strings"
)

type GGA struct {
	Latitude     float64 // Decimal degrees
	Longitude    float64 // Decimal degrees
	FixQuality   int
	Satellites   int
	HorizontalDilution float64
	Altitude     float64 // Meters above mean sea level
}

type RMC struct {
	Time         string
	Status       string // A=valid, V=warning
	Latitude     float64 // Decimal degrees
	Longitude    float64 // Decimal degrees
	Speed        float64 // Knots
	Track        float64 // Degrees true
	Date         string
	MagneticVar  float64 // Degrees
}

func parseGGA(sentence string) (GGA, error) {
	var gga GGA
	parts := strings.Split(sentence, ",")
	if len(parts) < 15 || parts[0] != "$GPGGA" {
		return gga, fmt.Errorf("invalid GGA sentence")
	}

	// Parse latitude
	latParts := strings.Split(parts[2], ".")
	if len(latParts) < 2 {
		return gga, fmt.Errorf("invalid latitude format")
	}
	latDegrees, _ := strconv.ParseFloat(latParts[0][:len(latParts[0])-2], 64)
	latMinutes, _ := strconv.ParseFloat(latParts[0][len(latParts[0])-2:]+"."+latParts[1], 64)
	gga.Latitude = latDegrees + (latMinutes / 60.0)
	if parts[3] == "S" {
		gga.Latitude *= -1
	}

	// Parse longitude
	lonParts := strings.Split(parts[4], ".")
	if len(lonParts) < 2 {
		return gga, fmt.Errorf("invalid longitude format")
	}
	lonDegrees, _ := strconv.ParseFloat(lonParts[0][:len(lonParts[0])-3], 64)
	lonMinutes, _ := strconv.ParseFloat(lonParts[0][len(lonParts[0])-3:]+"."+lonParts[1], 64)
	gga.Longitude = lonDegrees + (lonMinutes / 60.0)
	if parts[5] == "W" {
		gga.Longitude *= -1
	}

	// Parse other fields
	gga.FixQuality, _ = strconv.Atoi(parts[6])
	gga.Satellites, _ = strconv.Atoi(parts[7])
	gga.HorizontalDilution, _ = strconv.ParseFloat(parts[8], 64)
	gga.Altitude, _ = strconv.ParseFloat(parts[9], 64)

	return gga, nil
}

func parseRMC(sentence string) (RMC, error) {
	var rmc RMC
	parts := strings.Split(sentence, ",")
	if len(parts) < 13 || parts[0] != "$GPRMC" {
		return rmc, fmt.Errorf("invalid RMC sentence")
	}

	rmc.Time = parts[1]
	rmc.Status = parts[2]

	// Parse latitude
	latParts := strings.Split(parts[3], ".")
	if len(latParts) < 2 {
		return rmc, fmt.Errorf("invalid latitude format")
	}
	latDegrees, _ := strconv.ParseFloat(latParts[0][:len(latParts[0])-2], 64)
	latMinutes, _ := strconv.ParseFloat(latParts[0][len(latParts[0])-2:]+"."+latParts[1], 64)
	rmc.Latitude = latDegrees + (latMinutes / 60.0)
	if parts[4] == "S" {
		rmc.Latitude *= -1
	}

	// Parse longitude
	lonParts := strings.Split(parts[5], ".")
	if len(lonParts) < 2 {
		return rmc, fmt.Errorf("invalid longitude format")
	}
	lonDegrees, _ := strconv.ParseFloat(lonParts[0][:len(lonParts[0])-3], 64)
	lonMinutes, _ := strconv.ParseFloat(lonParts[0][len(lonParts[0])-3:]+"."+lonParts[1], 64)
	rmc.Longitude = lonDegrees + (lonMinutes / 60.0)
	if parts[6] == "W" {
		rmc.Longitude *= -1
	}

	// Parse other fields
	rmc.Speed, _ = strconv.ParseFloat(parts[7], 64)
	rmc.Track, _ = strconv.ParseFloat(parts[8], 64)
	rmc.Date = parts[9]
	rmc.MagneticVar, _ = strconv.ParseFloat(parts[10], 64)

	return rmc, nil
}

func main() {
	// Example GGA sentence
	ggaSentence := "$GPGGA,123519,4807.038,N,01131.000,E,1,08,0.9,545.4,M,46.9,M,,*47"
	gga, err := parseGGA(ggaSentence)
	if err != nil {
		fmt.Println("Error parsing GGA:", err)
		return
	}
	fmt.Printf("GGA - Lat: %.6f, Lon: %.6f, Alt: %.1f m\n", gga.Latitude, gga.Longitude, gga.Altitude)

	// Example RMC sentence
	rmcSentence := "$GPRMC,123519,A,4807.038,N,01131.000,E,022.4,084.4,230394,003.1,W*6A"
	rmc, err := parseRMC(rmcSentence)
	if err != nil {
		fmt.Println("Error parsing RMC:", err)
		return
	}
	fmt.Printf("RMC - Lat: %.6f, Lon: %.6f, Speed: %.1f knots\n", rmc.Latitude, rmc.Longitude, rmc.Speed)
}
```

## Key Features:

1. **GGA Parser**: Handles position fix data including latitude, longitude, altitude, and satellite info
2. **RMC Parser**: Handles recommended minimum navigation data including time, date, speed, and track
3. **Coordinate Conversion**: Converts DMS (degrees-minutes-seconds) format to decimal degrees
4. **Error Handling**: Basic validation of sentence structure

## How It Works:

1. The code splits the NMEA sentence by commas to access individual fields
2. For coordinates, it separates degrees and minutes then converts to decimal degrees
3. Numeric fields are converted from strings to appropriate types (float64 or int)
4. The example shows parsing both GGA and RMC sentences

