# Java Example for Parsing SWIFT MT940 Bank Statements

Here's a basic Java example that demonstrates how to parse SWIFT MT940 bank statement files. This implementation uses regular expressions to extract key information from the MT940 format.

```java
import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Mt940Parser {

    public static void main(String[] args) {
        String filePath = "path/to/your/mt940/file.txt";
        try {
            List<Transaction> transactions = parseMt940File(filePath);
            for (Transaction t : transactions) {
                System.out.println(t);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static List<Transaction> parseMt940File(String filePath) throws IOException {
        List<Transaction> transactions = new ArrayList<>();
        BufferedReader reader = new BufferedReader(new FileReader(filePath));
        String line;

        while ((line = reader.readLine()) != null) {
            if (line.startsWith(":61:")) { // Transaction entry
                Transaction transaction = parseTransactionEntry(line);
                transactions.add(transaction);
            }
        }

        reader.close();
        return transactions;
    }

    private static Transaction parseTransactionEntry(String line) {
        Transaction transaction = new Transaction();

        // Extract date and time (format: YYMMDD or YYYYMMDD)
        Pattern datePattern = Pattern.compile(":61:(\\d{4})(\\d{2})(\\d{2})");
        Matcher dateMatcher = datePattern.matcher(line);
        if (dateMatcher.find()) {
            String year = dateMatcher.group(1).length() == 2 ? "20" + dateMatcher.group(1) : dateMatcher.group(1);
            transaction.setDate(year + "-" + dateMatcher.group(2) + "-" + dateMatcher.group(3));
        }

        // Extract amount (format: D or C followed by amount)
        Pattern amountPattern = Pattern.compile("([DC])(\\d+\\.?\\d*)");
        Matcher amountMatcher = amountPattern.matcher(line);
        if (amountMatcher.find()) {
            double amount = Double.parseDouble(amountMatcher.group(2));
            transaction.setAmount(amount * (amountMatcher.group(1).equals("C") ? 1 : -1));
        }

        // Extract transaction type (format: / or NON)
        Pattern typePattern = Pattern.compile("(?:/|NON)([A-Z]{3,4})");
        Matcher typeMatcher = typePattern.matcher(line);
        if (typeMatcher.find()) {
            transaction.setType(typeMatcher.group(1));
        }

        return transaction;
    }
}

class Transaction {
    private String date;
    private double amount;
    private String type;

    // Getters and setters
    public String getDate() { return date; }
    public void setDate(String date) { this.date = date; }
    public double getAmount() { return amount; }
    public void setAmount(double amount) { this.amount = amount; }
    public String getType() { return type; }
    public void setType(String type) { this.type = type; }

    @Override
    public String toString() {
        return "Transaction{" +
                "date='" + date + '\'' +
                ", amount=" + amount +
                ", type='" + type + '\'' +
                '}';
    }
}
```

## Key Features of This Implementation:

1. **Basic MT940 Parsing**: Focuses on the :61: transaction entry line which contains core information
2. **Date Extraction**: Handles both 6-digit (YYMMDD) and 8-digit (YYYYMMDD) date formats
3. **Amount Calculation**: Properly handles credit (C) and debit (D) indicators
4. **Transaction Type**: Extracts the transaction code (like NTR, CDV, etc.)

## Limitations:

1. This is a simplified example - real MT940 files contain much more information
2. Doesn't handle all possible MT940 variations or optional fields
3. No validation of the SWIFT format structure

For production use, you would want to:
- Add more robust error handling
- Parse additional fields like :86: for narrative text
- Handle different MT940 versions and formats
- Consider using a dedicated library if available

# Reading CAN Bus Frames in C++

To read CAN bus frames from a vehicle interface in C++, you'll need to use platform-specific APIs or libraries. Here are approaches for different operating systems:

## Windows (using Windows CAN API)

```cpp
#include <windows.h>
#include <can.h> // Requires Windows DDK or WDK

int main() {
    HANDLE hCanHandle;
    CAN_MSG canMsg;

    // Open CAN interface (adjust parameters as needed)
    hCanHandle = CanOpen(0, 1); // 0=first adapter, 1=open read-only
    if (hCanHandle == INVALID_HANDLE_VALUE) {
        printf("Failed to open CAN interface\n");
        return 1;
    }

    while (true) {
        DWORD bytesRead;
        if (CanRead(hCanHandle, &canMsg, sizeof(canMsg), &bytesRead)) {
            printf("CAN ID: 0x%X, Data Length: %d, Data: ",
                   canMsg.MsgID, canMsg.DLC);
            for (int i = 0; i < canMsg.DLC; i++) {
                printf("%02X ", canMsg.Data[i]);
            }
            printf("\n");
        }
    }

    CanClose(hCanHandle);
    return 0;
}
```

## Linux (using SocketCAN)

```cpp
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <net/if.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <linux/can.h>
#include <linux/can/raw.h>

int main() {
    int s;
    struct ifreq ifr;
    struct can_frame frame;

    // Create socket
    s = socket(PF_CAN, SOCK_RAW, CAN_RAW);
    if (s < 0) {
        perror("Socket");
        return 1;
    }

    // Set interface name
    strcpy(ifr.ifr_name, "can0"); // Change to your CAN interface
    ioctl(s, SIOCGIFINDEX, &ifr);

    // Bind socket to CAN interface
    struct sockaddr_can addr;
    memset(&addr, 0, sizeof(addr));
    addr.can_family = AF_CAN;
    addr.can_ifindex = ifr.ifr_ifindex;
    bind(s, (struct sockaddr *)&addr, sizeof(addr));

    while (1) {
        // Read CAN frame
        int nbytes = read(s, &frame, sizeof(frame));
        if (nbytes < 0) {
            perror("Read");
            break;
        }

        printf("CAN ID: %X, Data Length: %d, Data: ",
               frame.can_id, frame.can_dlc);
        for (int i = 0; i < frame.can_dlc; i++) {
            printf("%02X ", frame.data[i]);
        }
        printf("\n");
    }

    close(s);
    return 0;
}
```

## Cross-platform using PCAN library

```cpp
#include <stdio.h>
#include <windows.h>
#include "PCANBasic.h" // Requires PEAK-System PCAN-Basic API

int main() {
    TPCANHandle handle = PCAN_ISA02; // Adjust based on your hardware
    TPCANMsg msg;
    DWORD lResult;

    // Initialize CAN interface
    lResult = CAN_Initialize(handle, PCAN_BAUD_500K);
    if (lResult != PCAN_ERROR_OK) {
        printf("CAN initialization failed\n");
        return 1;
    }

    while (true) {
        // Read message
        lResult = CAN_Read(handle, &msg, NULL);

        if (lResult == PCAN_ERROR_OK) {
            printf("CAN ID: %X, Data Length: %d, Data: ",
                   msg.ID, msg.LEN);
            for (int i = 0; i < msg.LEN; i++) {
                printf("%02X ", msg.DATA[i]);
            }
            printf("\n");
        } else if (lResult != PCAN_ERROR_ILLOPERATION) {
            printf("CAN read error\n");
        }
    }

    CAN_Uninitialize(handle);
    return 0;
}
```

## Important Notes:

1. **Hardware Requirements**: You'll need a CAN interface adapter connected to your computer.

2. **Permissions**:
   - On Linux, you may need to add your user to the `can` group or run as root
   - On Windows, administrator privileges are typically required

3. **CAN Configuration**:
   - Bit rate must match the vehicle's CAN bus (common rates: 500k, 250k)
   - Some vehicles use CAN FD which requires different handling

4. **Libraries**:
   - For Linux, install SocketCAN tools: `sudo apt-get install can-utils`
   - For Windows, you may need to install drivers for your specific CAN adapter

