    let pool = FastPool::new(4);

    // Create a channel to send tasks to the pool
    let (tx, mut rx) = mpsc::channel(32);

    // Spawn some async tasks into the pool
    for i in 0..5 {
        let tx = tx.clone();
        pool.spawn(FastTask::new(async move {
            println!("Task {} started", i);
            tokio::time::sleep(tokio::time::Duration::from_secs(1)).await;
            println!("Task {} completed", i);
            // Send completion signal
            let _ = tx.send(i).await;
        }));
    }

    // Wait for tasks to complete
    let mut count = 0;
    while let Some(result) = rx.recv().await {
        count += 1;
        if count == 5 {
            break;
        }
    }

    println!("All tasks completed");
}
```

Key points:
- `FastPool::new(n)` creates a pool with n workers
- `pool.spawn(FastTask::new(async { ... }))` runs an async task in the pool
- The pool handles task scheduling more efficiently than regular tokio threads

