    std::lock_guard<std::mutex> lock(dataMutex); // Acquire lock, ensuring exclusive access
    sharedData.push_back(value); // Write operation
    std::cout << "Wrote: " << value << std::endl;
}

void readerThread() {
    int sum = 0;
    std::vector<int> localCopy;

    {
        std::lock_guard<std::mutex> lock(dataMutex); // Acquire lock for reading
        localCopy = sharedData; // Copy data to avoid holding the lock during processing
    }

    for (int v : localCopy) {
