import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;

public class SandboxRunner {

    public static void main(String[] args) {
        // 1. Load the untrusted class bytes from an external source (e.g., network, file)
        //    In a real deployment you would verify signatures, use a secure loader, etc.
        byte[] classBytes = /* fetch untrusted bytecode */;

        // 2. Create a custom ClassLoader that restricts permissions
        RestrictedClassLoader restrictedLoader = new RestrictedClassLoader(
                SandboxRunner.class.getClassLoader());

        // 3. Define the class inside the restricted environment
        Class<?> untrustedClass = restrictedLoader.defineClass("UntrustedCode", classBytes, 0, classBytes.length);

        try {
            // 4. Instantiate the untrusted code (it must implement a known interface)
            Object instance = untrustedClass.getDeclaredConstructor().newInstance();

            // 5. Proxy all calls through a guard that only forwards allowed methods
            HardwareProxy proxy = new HardwareProxy(new TrustedHardwareService());

            // Cast to a known safe interface; this forces the bytecode to conform.
            SafeHardwareApi api = (SafeHardwareApi) Proxy.newProxyInstance(
                    untrustedClass.getClassLoader(),
                    new Class<?>[] { SafeHardwareApi.class },
                    (proxyTarget, method, argsArray) -> {
                        // Intercept every call and route it through our guard
                        return proxy.invoke(method.getName(), argsArray);
                    });

            // 6. Execute the untrusted code – it can only use the safe API methods
            Method runMethod = untrustedClass.getMethod("run", SafeHardwareApi.class);
            runMethod.invoke(instance, api);

        } catch (Exception e) {
            System.err.println("Sandbox execution failed: " + e.getMessage());
        }
    }

    // -------------------------------------------------------------------
    // Minimal safe interface that the sandboxed code may use
    // -------------------------------------------------------------------
    public interface SafeHardwareApi {
        void setLedState(int ledId, boolean on);
        // Add other carefully‑designed methods here…
    }

    // -------------------------------------------------------------------
    // Guard/proxy that delegates to the trusted service for allowed ops
    // -------------------------------------------------------------------
    private static class HardwareProxy {
        private final TrustedHardwareService delegate;

        public HardwareProxy(TrustedHardwareService svc) { this.delegate = svc; }

        @SuppressWarnings("unchecked")
        public Object invoke(String methodName, Object[] args) throws Exception {
            switch (methodName) {
                case "setLedState":
                    if (args.length != 2 ||
                        !(args[0] instanceof Integer) ||
                        !(args[1] instanceof Boolean)) {
                        throw new IllegalArgumentException("Invalid arguments for setLedState");
                    }
                    delegate.setLedState((Integer) args[0], (Boolean) args[1]);
                    return null; // void method
                default:
                    throw new SecurityException("Forbidden hardware operation: " + methodName);
            }
        }
    }

    // -------------------------------------------------------------------
    // Restricted ClassLoader – revokes most permissions for loaded classes
    // -------------------------------------------------------------------
    private static class RestrictedClassLoader extends ClassLoader {
        public RestrictedClassLoader(ClassLoader parent) { super(parent); }

        @Override
        protected Class<?> loadClass(String name, boolean resolve)
                throws ClassNotFoundException {
            if (name.startsWith("java.") || name.startsWith("javax.")) {
                // Force the JVM’s system loader to handle core classes,
                // ensuring we cannot replace them with malicious versions.
                return super.loadClass(name, resolve);
            }
            // Load bytes from somewhere secure (omitted for brevity)
            byte[] b = /* obtain trusted bytecode */;
            return defineClass(name, b, 0, b.length);
        }

        @Override
        public Class<?> defineClass(String name, byte[] b, int off, int len) {
            // Remove all dangerous permissions from the generated ProtectionDomain.
            java.security.ProtectionDomain pd = new java.security.ProtectionDomain(
                    null, new java.security.Permission[0]);
            return super.defineClass(name, b, off, len, pd);
        }
    }
}
```

#### How This Example Meets Security Goals

| Goal | Implementation |
|------|----------------|
| **Isolation** | `RestrictedClassLoader` gives the loaded class a *null* code source and an empty `PermissionCollection`, effectively revoking all JVM‑level permissions (e.g., file I/O, network, reflection). |
| **Controlled Hardware Access** | The only way for sandboxed code to affect hardware is through the `SafeHardwareApi` interface. All calls are routed through `HardwareProxy`, which validates arguments and forwards them to a *trusted* `TrustedHardwareService`. |
| **No Raw Register Exposure** | Untrusted bytecode never sees memory addresses, JNI handles, or native method descriptors that could be abused to rewrite JVM internals. |
| **Auditable & Extensible** | Adding new safe operations is as simple as extending `SafeHardwareApi` and updating the guard logic in `HardwareProxy`. All interactions are logged (see print statements) for traceability. |

