// Also assume we have a TransactionManager (tm) that can enlist resources in a distributed transaction

public void performDistributedTransaction(Object dataForDB1, Object dataForDB2) {
    try {
        // Phase 1: Prepare
        tm.begin(); // Start the global transaction

        // Enlist both databases in the transaction
        XAResource xaResource1 = Database1XADataSource.getXAResource();
        XAResource xaResource2 = Database2XADataSource.getXAResource();
        tm.getTransaction().enlistResource(xaResource1);
        tm.getTransaction().enlistResource(xaResource2);

