        executeLocalTransaction(dataForDB1, xaResource1); // This could be an insert/update in DB1
        executeLocalTransaction(dataForDB2, xaResource2); // This could be an insert/update in DB2

        // Prepare phase: Ask all participants if they are ready to commit
        tm.getTransaction().prepare(); // This will send a prepare request to both databases

        // Phase 2: Commit or Rollback
        boolean prepared = true; // Assume preparation succeeded initially

        // Check for any failures during the prepare phase (e.g., exceptions)
        if (!prepared) {
            tm.getTransaction().rollback();
            throw new RuntimeException("Transaction prepare failed, rolling back.");
        }

        // If all participants report they are ready, commit
        tm.getTransaction().commit(); // This will send a commit request to both databases

    } catch (Exception e) {
        // Handle any exception that occurs during the transaction
        try {
            if (tm != null && tm.getTransaction() != null) {
                tm.getTransaction().rollback();
            }
        } catch (SystemException se) {
            se.printStackTrace(); // Log or handle system exceptions appropriately
        }
        throw new RuntimeException("Distributed transaction failed.", e);
    } finally {
        // Cleanup resources, close connections, etc.
    }
}

