```go
package main

import (
    "fmt"
    "io" // Import the io package
)

// Example function that copies data from a source stream to a destination stream.
func copyStreams(src io.Reader, dst io.Writer) (written int64, err error) {
    return io.Copy(dst, src)
}

func main() {
    // For demonstration purposes, let's use byte streams.
    // In real scenarios, these could be file handles, network connections, etc.
    sourceData := []byte("Hello, Go IO Streams!")
    destinationBuffer := make([]byte, len(sourceData))

    // Create an io.Reader from the source data
    srcReader := io.ReaderFrom(bytes.NewReader(sourceData))

    // Create an io.Writer to the destination buffer
    dstWriter := io.WriterTo(bytes.NewBuffer(destinationBuffer))

    // Copy data from srcReader to dstWriter
    written, err := copyStreams(srcReader, dstWriter)
    if err != nil {
        fmt.Printf("Error copying streams: %v\n", err)
        return
    }

    fmt.Printf("Copied %d bytes.\n", written)
    fmt.Printf("Destination buffer content: %s\n", destinationBuffer)
}
```

**Note:** The above example uses `bytes.NewReader` and `bytes.NewBuffer` for demonstration purposes, which means you'll also need to import the `bytes` package. In real-world scenarios, your source (`io.Reader`) could be a file opened with `os.Open`, a network connection, or any other type that implements the `io.Reader` interface. Similarly, your destination (`io.Writer`) could be a file handle ready for writing, a network socket, etc.

