        HttpClient httpClient = HttpClient.newBuilder()
                .version(HttpClient.Version.HTTP_2) // Explicitly set the version to HTTP/2
                .build();

        // Define the request. Here we're making a GET request to an example URL that supports HTTP/2.
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create("https://http2.example.com")) // Replace with your target URL
