    let file_path = "path/to/your/file.csv"; // Replace with your CSV file path
    let users = read_users_from_csv(file_path)?;

    for user in users {
        println!("{:?}", user);
    }

    Ok(())
}
```

### Explanation

- **`ReaderBuilder::new().has_headers(true).from_path(file_path)?;`**: This line creates a new CSV reader configured to expect headers (the first row of the CSV file) and opens the specified file. The `?` operator is used for error propagation, which will return any encountered errors up the call stack.

