function fizzBuzzModified() {
    // Loop through numbers from 1 to 100 (you can adjust the range as needed)
    for (let i = 1; i <= 100; i++) {
        let output = ''; // Initialize an empty string for the output

        // Check if the number is a multiple of both 7 and 5
        if (i % 7 === 0 && i % 5 === 0) {
            output = 'FizzBuzz';
        } else if (i % 7 === 0) { // Check if the number is a multiple of 7
            output = 'Fizz';
        } else if (i % 5 === 0) { // Check if the number is a multiple of 5
