	Quality        int     // GPS quality indicator (0-5)
	Satellites     int     // Number of satellites in use
	HDOP           float64 // Horizontal dilution of precision
	Altitude       float64 // Altitude above mean sea level in meters
	AltitudeUnits  string  // Units for altitude ("M" for meters)
	GeoidalSeparation float64 // Difference between WGS-84 earth ellipsoid and mean sea level in meters
	GeoSepUnits     string  // Units for geoidal separation ("M" for meters)
	AgeOfDGPSData   string  // Age of differential GPS data (seconds)
	DGPSReference   int    // ID of DGPS reference station
	Checksum        string  // Checksum for error detection
}

// parseNMEAGGA parses a GGA sentence into an NMEAGGA struct.
func parseNMEAGGA(sentence string) (*NMEAGGA, error) {
	// Split the sentence by commas. The first comma is part of the prefix ($GPGGA).
	parts := strings.SplitN(sentence, ",", 12)

	if len(parts) < 12 || parts[0] != "$GPGGA" {
		return nil, fmt.Errorf("invalid or incomplete GGA sentence: %s", sentence)
	}

	gga := &NMEAGGA{}

	// Time
	gga.Time = parts[1]

	// Latitude (DDMM.MMMM)
	if latStr := parts[2]; latStr != "" {
		gga.Latitude, _ = parseLatitude(latStr, parts[3]) // Assuming DDMM.MMMM format and 'N' or 'S'
	}

	// Longitude (DDDMM.MMMM)
	if lonStr := parts[4]; lonStr != "" {
		gga.Longitude, _ = parseLongitude(lonStr, parts[5]) // Assuming DDDMM.MMMM format and 'E' or 'W'
	}

	// Quality
	if qStr := parts[6]; qStr != "" {
		q, err := strconv.Atoi(qStr)
		if err == nil {
			gga.Quality = q
		}
	}

	// Satellites
	if sStr := parts[7]; sStr != "" {
		s, err := strconv.Atoi(sStr)
		if err == nil {
			gga.Satellites = s
		}
	}

	// HDOP
	if hdopStr := parts[8]; hdopStr != "" {
		f, err := strconv.ParseFloat(hdopStr, 64)
		if err == nil {
			gga.HDOP = f
		}
	}

	// Altitude
	if altStr := parts[9]; altStr != "" {
		f, err := strconv.ParseFloat(altStr, 64)
		if err == nil {
			gga.Altitude = f
		}
		if len(parts) > 10 && parts[10] != "" {
			gga.AltitudeUnits = parts[10]
		}
	}

	// Geoidal Separation
	if geoStr := parts[11]; geoStr != "" {
		f, err := strconv.ParseFloat(geoStr, 64)
		if err == nil {
			gga.GeoidalSeparation = f
		}
		if len(parts) > 12 && parts[12] != "" {
			gga.GeoSepUnits = parts[12]
		}
	}

	return gga, nil
}

