import java.util.LinkedHashMap;
import java.util.Map;

public class LRUCache<K, V> extends LinkedHashMap<K, V> {
    private final int cacheSize;

    // Constructs a new LinkedHashMap with the specified capacity,
    // load factor and ordering mode (true = access order).
    public LRUCache(int cacheSize) {
        // The 1.0f load factor ensures that rehashing happens as soon as
        // the size of the map exceeds its capacity.
        super(cacheSize + 1, 1.0f, true);
        this.cacheSize = cacheSize;
    }

    @Override
    protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
        // This method is called by put and putAll after adding an entry to the map.
        // It returns true if this entry should be removed (eldest).
        return size() > cacheSize;
    }

    public static void main(String[] args) {
        LRUCache<Integer, String> lruCache = new LRUCache<>(3); // Cache capacity of 3

        // Adding elements
        lruCache.put(1, "One");
        lruCache.put(2, "Two");
        lruCache.put(3, "Three");

        System.out.println("Initial cache: " + lruCache);

        // Accessing an element to make it recently used
        String value = lruCache.get(1);
        System.out.println("Accessed value for key 1: " + value);

