Create a file, e.g., `retryExample.js`, and add the following code:

```javascript
const axios = require('axios');
const createRetryInterceptor = require('axios-retry-pro');

// Create an Axios instance
const api = axios.create({
  baseURL: 'https://api.example.com', // Replace with your API's base URL
});

// Configure retry logic
createRetryInterceptor(api, {
  retries: 3, // Number of retries before giving up
  onRetry: (error, retryCount, requestConfig) => {
    console.log(`Attempt #${retryCount}: Retrying request...`, requestConfig.url);
  },
  shouldRetry: (error) => {
    // Decide if this error should trigger a retry.
    // For example, retry on network errors or specific HTTP status codes.
    return true; // Retry for any error in this simple example
  },
  backoffType: 'exponential', // Use exponential backoff
  retryDelay: (retryCount) => {
    // Custom delay calculation if needed. Here we use the default exponential logic.
    return undefined;
  },
});

// Example function to make a request that might fail and be retried
async function fetchData() {
  try {
    const response = await api.get('/data'); // Replace '/data' with your endpoint
    console.log('Data fetched successfully:', response.data);
  } catch (error) {
    console.error('Failed to fetch data after retries:', error.message);
  }
}

// Call the function
