To address the requirement of building a clock service that ensures a total order on events across machines without a shared clock or message exchange, we can use vector timestamps. Each node maintains its own counter and increments it each time an event occurs. Events are then timestamped with these counters to establish a relative order.

Here's a JavaScript example demonstrating this:

```javascript
// Internal documentation: Clock Service using Vector Timestamps

/**
 * Creates a clock service for a node.
 * @param {string} id - Unique identifier for the node.
 * @returns {Object} An object with generateEvent method.
 */
function createClock(id) {
  let count = 0;

  return {
    /**
     * Generates an event and increments the local timestamp.
     * @returns {Object} The generated event with timestamp information.
     */
    generateEvent: () => {
      count++;
      // This is a simplified example; in reality, each event should carry a vector timestamp
      // including all nodes' counters, but for brevity, we'll just return the local counter.
      return { id, timestamp: count };
    }
  };
}

// Create nodes and generate events
const nodeA = createClock('A');
const nodeB = createClock('B');
const nodeC = createClock('C');

// Generate events
const event1 = nodeA.generateEvent(); // A:1
const event2 = nodeB.generateEvent(); // B:1
const event3 = nodeC.generateEvent(); // C:1

// Collect all events in an array
const events = [event1, event2, event3];

// Function to compare two events based on their timestamps (this is a simplified comparator)
