  if (event1.timestamp < event2.timestamp) return -1;
  else if (event1.timestamp > event2.timestamp) return 1;
  // If timestamps are the same (same node), order by node ID
  else {
    if (event1.id < event2.id) return -1;
    else if (event1.id > event2.id) return 1;
    else return 0; // Same event, which shouldn't happen
  }
}

