This example demonstrates how each node maintains its own timestamp and generates events with those timestamps. By collecting all events and sorting them based on their timestamps (and node IDs as a tiebreaker), we can establish a total order of events across nodes without relying on shared clocks or direct message exchange.

Note: This is a simplified example for documentation purposes. In a real-world scenario, each event should carry a vector timestamp that includes the state of all nodes' counters at the time of the event to accurately determine causality and ordering. Additionally, conflict resolution mechanisms would be necessary to handle cases where events might appear concurrent based on their timestamps.

Building a distributed lock service in an asynchronous network with crash failures is challenging but can be achieved using a consensus algorithm like Raft. Below is a minimal example of how you might implement this in Go.

This implementation uses the `github.com/hashicorp/raft` library (note: the original link was modified to use a more commonly used library) to handle leader election and crash recovery.

```go
package main

import (
	"fmt"
	"log"
	"net/rpc"
	"time"

	"github.com/hashicorp/raft"
)

const (
	Port = 1234
)

type Server struct {
	nodeID int
	raft   *raft.Raft
}

func NewServer(id int, peers []string) (*Server, error) {
	// Initialize Raft configuration
	config := raft.DefaultConfig()
	config.NodeID = id
	config.Election.Ticker = time.NewTicker(10 * time.Second)
	config.Heartbeat.Ticker = time.NewTicker(time.Second)

	storage := raft.NewInMemStorage()

	raftNode, err := raft.New(config, storage, nil, nil, "")
	if err != nil {
		return nil, fmt.Errorf("failed to create raft node: %v", err)
	}

	addr := fmt.Sprintf("localhost:%d", Port)
	conn, err := rpc.DialHTTP("tcp", addr)
	if err != nil {
		return nil, fmt.Errorf("failed to connect to peer: %v", err)
	}
	defer conn.Close()

	// Setup Raft with peers
	for i, peer := range(peers) {
		if i == id-1 { // subtract 1 because IDs start at 0 in the list and 1 in the config
			continue
		}
		addr := fmt.Sprintf("localhost:%d", Port+i)
		_, err = conn.Call("Raft.JoinCluster", addr, &struct{}{})
		if err != nil {
			return nil, fmt.Errorf("failed to join peer: %v", err)
		}
	}

	server := &Server{
		nodeID: id,
		raft:   raftNode,
	}

	go server.run()
	return server, nil
}

func (s *Server) run() {
	select {
	case <-s.raft.Ready:
		if s.raft.State == raft.Leader {
			log.Printf("Node %d is now the leader", s.nodeID)
		}
	}
}

type Client struct {
	nodeID int
	leader bool
	mutex  sync.Mutex
}

func NewClient(id int, peers []string) *Client {
	c := &Client{
		nodeID: id,
		mutex:   sync.Mutex{},
	}

	return c
}

func (c *Client) IsLeader() bool {
	if !c.leader {
		// Check with all servers to see if any are the leader
		// This is a simplified version; in practice, you would use Raft's API
		for i := 0; i < len(peers); i++ {
			addr := fmt.Sprintf("localhost:%d", Port+i)
			conn, err := rpc.DialHTTP("tcp", addr)
			if err != nil {
				continue // node is down; skip
			}
			defer conn.Close()

			var response bool
			err = conn.Call("Server.IsLeader", struct{}{}, &response)
			if err == nil && response {
				if c.nodeID == i+1 { // adjust for 1-based vs 0-based IDs
					c.leader = true
				}
				break
			}
		}
	}

	return c.leader
}

func (c *Client) AcquireLock(key string, timeout time.Duration) bool {
	for {
		if !c.IsLeader() {
			time.Sleep(time.Second)
			continue
		}

		// Send request to leader to acquire lock
		conn, err := rpc.DialHTTP("tcp", fmt.Sprintf("localhost:%d", Port))
		if err != nil {
			time.Sleep(time.Second)
			continue
		}
		defer conn.Close()

		args := &struct {
			Key    string
			Client int
		}{
			Key:    key,
			Client: c.nodeID,
		}

		var reply bool
		err = conn.Call("Server.AcquireLock", args, &reply)
		if err != nil || !reply {
			time.Sleep(time.Second)
			continue
		}

		return true
	}
}

func (c *Client) ReleaseLock(key string) {
	conn, err := rpc.DialHTTP("tcp", fmt.Sprintf("localhost:%d", Port))
	if err != nil {
		log.Printf("Failed to connect: %v", err)
		return
	}
	defer conn.Close()

	args := &struct {
		Key string
	}{
		Key: key,
	}

	var reply bool
	err = conn.Call("Server.ReleaseLock", args, &reply)
	if err != nil || !reply {
		log.Printf("Failed to release lock: %v", err)
		return
	}
}

func (s *Server) AcquireLock(args *struct {
	Key    string
	Client int
}, reply *bool) error {
	if s.raft.State == raft.Leader {
		// Simple implementation; in practice, you would store the lock state in a persistent manner
		s.mutex.Lock()
		defer s.mutex.Unlock()

		reply.Msg = "Granted"
		return nil
	}
	return fmt.Errorf("not leader")
}

func (s *Server) ReleaseLock(args *struct {
	Key string
}, reply *bool) error {
	if s.raft.State == raft.Leader {
		s.mutex.Lock()
		defer s	mutex.Unlock()

		reply.Msg = "Released"
		return nil
	}
	return fmt.Errorf("not leader")
}

// Minimal Raft integration (this is a simplified version)
func main() {
	peers := []int{1, 2, 3} // Simple case with 3 nodes

	servers := make([]*Server, len(peers))
	for i, id := range(peers) {
		s, err := NewServer(id, peers)
		if err != nil {
			log.Fatalf("Failed to create server %d: %v", id, err)
		}
		servers[i] = s
	}

	clients := make([]*Client, len(peers))
	for i, id := range(peers) {
		clients[i] = NewClient(id, peers)
	}

	// Example usage:
	client := clients[0]
	lockKey := "critical-section"
	timeout := time.Second * 15

	if client.AcquireLock(lockKey, timeout) {
		log.Printf("Client %d acquired lock %s", client.nodeID, lockKey)
		defer func() {
			client.ReleaseLock(lockKey)
		}()

		log.Printf("Client %d holding lock %s for 3 seconds...", client.nodeID, lockKey)
		time.Sleep(3 * time.Second)
	} else {
		log.Printf("Client %d failed to acquire lock %s", client.nodeID, lockKey)
	}
}
```

