### Step-by-Step Explanation and Code Outline

#### 1. **Define the Message Structure**
We need to define the structure of messages exchanged between nodes, including pre-prepared, prepared, commit, and client request/reply messages.

```cpp
#include <iostream>
#include <queue>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <chrono>

using namespace std;

struct Message {
    enum Type { 
        PRE_PREPARE,
        PREPARE,
        COMMIT,
        CLIENT_REQUEST,
        CLIENT_REPLY
    };
    Type type;
    int round_number;
    string value;
    int sender_id;
    string signature; // For message authenticity and integrity

    Message(Type t, int r, const string& v, int s) : 
        type(t), round_number(r), value(v), sender_id(s), signature("") {}
};
```

#### 2. **Define the Node Class**
Each node will have an ID, a queue for incoming messages, and state variables to track its role (primary/secondary) and current consensus state.

```cpp
class Node {
private:
    int id;
    vector<int> peers; // List of other node IDs
    queue<Message> inbox;
    bool is_primary;
    int current_round;
    string agreed_value;

public:
    Node(int i, const vector<int>& p, bool primary) : 
        id(i), peers(p), is_primary(primary), current_round(0), agreed_value("") {}

    void send(Message& msg) {
        for (int peer : peers) {
            if (peer != id) { // Avoid sending to self
                // In a real system, this would be over a network or messaging queue
                // For simulation, we can use shared queues or print messages
                cout << "Node " << id << " sends message to " << peer << endl;
            }
        }
    }

    void handle_pre_prepare(const Message& msg) {
        if (!inbox.empty()) {
            const Message& m = inbox.front();
            // Process the pre-prepare message
            // Here, we would verify the signature and ensure it's from the primary
            if (is_primary) {
                // Primary sends commit after receiving enough prepares
                // For simulation, assume all received messages are valid
                current_round = msg.round_number;
                agreed_value = msg.value;
                inbox.pop();
            } else {
                // Secondary nodes send prepare messages in response
                Message prepare_msg(Message::PREPARE, current_round, "", id);
                send(prepare_msg);
                inbox.pop();
            }
        }
    }

    void handle_commit(const Message& msg) {
        if (!inbox.empty()) {
            const Message& m = inbox.front();
            // Apply the committed value
            agreed_value = m.value;
            inbox.pop();
        }
    }

    void process_messages() {
        while (true) {
            if (!inbox.empty()) {
                Message msg = inbox.front();
                inbox.pop();

                switch(msg.type) {
                    case Message::PRE_PREPARE:
                        handle_pre_prepare(msg);
                        break;
                    case Message::PREPARE:
                        // For primary, count prepares
                        if (is_primary && current_round == msg.round_number) {
                            // Assuming we track the number of prepares received
                            // When enough are received, send commit
                            Message commit_msg(Message::COMMIT, current_round, agreed_value, id);
                            send(commit_msg);
                        }
                        break;
                    case Message::COMMIT:
                        handle_commit(msg);
                        break;
                    default:
                        break;
                }
            }
        }
    }

    void start() {
        thread t([this]() {
            while (true) {
                process_messages();
                // Sleep to prevent busy loop
                this_thread::sleep_for(chrono::milliseconds(100));
            }
        });
        t.detach();
    }
};
```

#### 3. **Simulate the Network and Nodes**
Create a set of nodes, assign roles (primary and secondaries), and simulate client requests.

```cpp
