func (p *PNCounter) Merge(other *PNCounter) {
    // For each node in the other's state, update this counter's up and lo arrays
    for id, index := range other.nodes {
        if _, exists := p.nodes[id]; !exists {
            // Add new nodes to this instance
            p.up = append(p.up, other.up[index])
            p.lo = append(p.lo, other.lo[index])
            p.nodes[id] = len(p.up) - 1
