type KeyValueStore struct {
	store map[string]string
}

func (k *KeyValueStore) Get(key string, reply *string) error {
	if k.store[key] == "" {
		return fmt.Errorf("key not found")
	}
	*reply = k.store[key]
	return nil
}

func (k *KeyValueStore) Put(key string, value string) error {
	k.store[key] = value
	return nil
}

type Node struct {
	raft raft.Raft
	store KeyValueStore
	rpc  *rpc.Server
}

func NewNode(raftConfig *raft.Config, address string) *Node {
	node := &Node{
		raft: *raft.NewRaft(raftConfig),
		store: KeyValueStore{store: make(map[string]string)},
	}
	return node
}

func (n *Node) Start() error {
	n.rpc = new(rpc.Server)
	RegisterNode(n.rpc, n)

	listener, err := net.Listen("tcp", fmt.Sprintf(":%d", 1234))
	if err != nil {
		log.Fatal("Failed to listen:", err)
	}
	go func() {
		<-ctxpkg.Background().Wait()
		n.rpc.Stop()
	}()

	err = n.rpc.Serve(listener)
	if err != nil {
		return fmt.Errorf("failed to serve: %v", err)
	}

	return nil
}

func (n *Node) BecameLeader() {
	log.Println("Became leader. Marking as available.")
	// Mark this node as available
	n.available = true
}

func (n *Node) BecameFollower() {
	log.Println("Became follower. Marking as unavailable.")
	// Mark this node as unavailable
	n.available = false
}

func (n *Node) GetKV(ctx context.Context, key string) (*string, error) {
	if !n.available {
		return nil, fmt.Errorf("node is unavailable due to partition")
	}
	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	default:
	}
	reply := ""
	n.store.Get(key, &reply)
	if reply == "" {
		return nil, fmt.Errorf("key not found")
	}
	return &reply, nil
}

func (n *Node) PutKV(ctx context.Context, key string, value string) (*string, error) {
	if !n.available {
		return nil, fmt.Errorf("node is unavailable due to partition")
	}
	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	default:
	}
	n.store.Put(key, value)
	return &value, nil
}

