Here's a concise implementation of a cache-blocked matrix multiplication optimized for L1/L2 caches:

```c
#include <stdlib.h>
#include <stdio.h>

#define K 64  // Block size; can be tuned based on cache size

void blocked_matmul(float* A, float* B, float* C, int N) {
    for (int i = 0; i < N; i += K) {
        for (int j = 0; j < N; j += K) {
            // Compute block starting at (i, j)
            for (int ii = i; ii < i + K && ii < N; ++ii) {
                for (int jj = j; jj < j + K && jj < N; ++jj) {
                    float sum = 0;
                    // Process all k's in steps of K
                    for (int k_block = 0; k_block < N; k_block += K) {
                        for (int kk = k_block; kk < k_block + K && kk < N; ++kk) {
                            sum += A[ii][kk] * B[kk][jj];
                        }
                    }
                    C[ii][jj] += sum;
                }
            }
        }
    }
}

int main() {
    int N = 432; // Matrix size
    float* A = (float*)malloc(N*N*sizeof(float));
    float* B = (float*)malloc(N*N*sizeof(float));
    float* C = (float*)malloc(N*N*sizeof(float));

    // Initialize matrices with random values or zeros

    blocked_matmul(A, B, C, N);

    free(A); free(B); free(C);
    return 0;
}
```

This implementation processes the matrix in blocks of size KxK, reducing cache misses by reusing data within each block. The block size (K) can be adjusted based on the target cache size.

