using System;

public class Program
{
    [Tailcall]
    public static int TailSum(int n, int accumulator)
    {
        if (n == 0)
            return accumulator;
        return TailSum(n - 1, accumulator + 1);
    }

    public static void Main()
    {
        Console.WriteLine(TailSum(5, 0)); // Output: 15
    }
}
```

