        connection_id = conn_id;
        std::cout << "Connected to server, connection ID: " << conn_id << "\n";
    };

    endpoint->CreateConnection(
        "localhost",  // Server's hostname
        4433,         // Server's port
        {},
        quiche::TransportSettings(),
        on_connect);

    // Keep the event loop running to process events.
    event_loop->Run();

    return 0;
}
```

