        n, addr, err := conn.ReadFromUDP(buffer)
        if err != nil {
            fmt.Printf("Error reading: %v\n", err)
            continue
        }

        // Convert the data to a string (assuming data is ASCII/UTF-8)
        message := buffer[:n]
        msgStr := string(message)

        if !received[msgStr] {
            received[msgStr] = true
            fmt.Printf("Received new message: %s\n", msgStr)
        } else {
            fmt.Printf("Duplicate message received: %s\n", msgStr)
        }
    }
}
```

