Here's a short example of using `github.com/gofast/turbopool` for database connection pooling:

```go
package main

import (
    "context"
    "database/sql"
    "fmt"
    "log"

    _ "github.com/lib/pq"           // PostgreSQL driver
    "github.com/gofast/turbopool"  // Import the turbopool package
)

func main() {
    // Create a new pool with max connections and other parameters
    pool, err := turbopool.New(
        turbopool.URL("postgresql://user:password@localhost:5432 dbname=testdb"),
        turbopool.MaxConnections(10),
        turbopool.MaxIdleConnections(5),
        turbopool.IdleTimeout(60 * 60 * 1000), // Idle timeout in milliseconds
    )
    if err != nil {
        log.Fatal("Failed to create connection pool:", err)
    }

    defer func() {
        // Close all connections when done
        _ = pool.Close()
   }()

    // Use the pool to get a connection and execute a query
    db := pool.DB()

    ctx := context.Background()

    rows, err := db.QueryContext(ctx, "SELECT id, name FROM users")
    if err != nil {
        log.Fatal("Query failed:", err)
    }
    defer rows.Close()

    // Iterate over the results
    for rows.Next() {
        var id int
        var name string

        if err := rows.Scan(&id, &name); err != nil {
            log.Fatal("Scan failed:", err)
        }
        fmt.Printf("ID: %d, Name: %s\n", id, name)
    }

    // Check for any errors during iteration
    if err = rows.Err(); err != nil {
        log.Fatal("Error iterating over rows:", err)
    }
}
