    ws.on('message', (message) => {
        console.log('Received:', message.toString());
        ws.send('Echo:', message);
    });

    ws.on('close', () => {
        console.log('Connection closed by client');
    });

    ws.on('error', (err) => {
        console.error('Error occurred:', err);
    });
});

