### The C++ Implementation (Single Machine Simulation)

This code simulates 3 processes on one machine using threads.

```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <random>
#include <chrono>
#include <algorithm>

// Constants
const int N = 3;        // Total nodes
const int F = 1;        // Max Byzantine faults tolerated (n = 2f + 1 => 3 = 2*1 + 1)

// Simulating a "Byzantine" node that can behave arbitrarily
enum class NodeType { HONEST, BYZANTINE };

class Node {
public:
    int id;
    bool isByzantine;
    std::vector<int> initialValues; // For testing multiple runs

    // Communication state
    std::mutex mtx;
    std::condition_variable cv;

    // For sending messages to "network"
    std::queue<std::pair<int, int>> inbox; // (sender_id, value)

    // Result
    bool decided = false;
    int decisionValue = -1;

    Node(int nodeId, bool byzantine) 
        : id(nodeId), isByzantine(byzantine) {}

    void start(std::vector<int> inputValues) {
        initialValues = inputValues;

        for (int val : initialValues) {
            // Run one instance of the agreement protocol per value
            runAgreement(val);
        }
    }

private:

    // Helper to send message to all nodes (including self)
    void broadcast(int round, int senderId, const std::vector<int>& values) {
        for (int target = 0; target < N; ++target) {
            if (!isByzantine || shouldSendValidMessage(round)) {
                // Simulate network delay
                std::this_thread::sleep_for(std::chrono::milliseconds(10));

                // Put message into target's inbox
                std::lock_guard<std::mutex> lock(nodes[target]->mtx);
                for (int v : values) {
                    nodes[target]->inbox.push({senderId, v});
                }
                nodes[target]->cv.notify_one();
            } else {
                // BYZANTINE BEHAVIOR: Send conflicting values to different nodes
                if (round == 1 && target != 0) {
                     std::this_thread::sleep_for(std::chrono::milliseconds(10));
                    int fakeValue = (target % 2 == 0) ? 1 : 0; // Confuse peers
                    std::lock_guard<std::mutex> lock(nodes[target]->mtx);
                    nodes[target]->inbox.push({senderId, fakeValue});
                    nodes[target]->cv.notify_one();
                }
            }
        }
    }

    bool shouldSendValidMessage(int round) {
        // Simplified Byzantine strategy: Lie about 30% of the time
        static std::mt19937 gen(std::random_device{}());
        std::uniform_int_distribution<> dis(0, 99);
        return dis(gen) > 30;
    }

    void runAgreement(int myValue) {
        // Round 1: Broadcast initial value
        broadcast(1, id, {myValue});

        // Wait to collect messages from all nodes (or timeout)
        std::vector<int> receivedValues;
        {
            std::unique_lock<std::mutex> lock(mtx);
            while (inbox.size() < N) {
                cv.wait_for(lock, std::chrono::seconds(1));
            }
            // Drain inbox
            while (!inbox.empty()) {
                auto msg = inbox.front(); inbox.pop();
                receivedValues.push_back(msg.second);
            }
        }

        // Process Round 1: Compute "majority vote"
        int countOnes = std::count(receivedValues.begin(), receivedValues.end(), 1);
        int currentVote = (countOnes > N/2) ? 1 : 0;

        // Round 2: Broadcast my computed vote
        broadcast(2, id, {currentVote});

        // Wait for round 2 messages
        std::vector<int> receivedVotes;
        {
            std::unique_lock<std::mutex> lock(mtx);
            while (inbox.size() < N) {
                cv.wait_for(lock, std::chrono::seconds(1));
            }
            while (!inbox.empty()) {
                auto msg = inbox.front(); inbox.pop();
                receivedVotes.push_back(msg.second);
            }
        }

        // Decision Logic
        int voteOnes = std::count(receivedVotes.begin(), receivedVotes.end(), 1);

        if (voteOnes > N/2) {
            setDecision(1);
        } else {
            setDecision(0);
        }
    }

    void setDecision(int val) {
        if (!decided) { // Only decide once
            std::lock_guard<std::mutex> lock(mtx);
            decided = true;
            decisionValue = val;

            if (isByzantine) {
                // Byzantine node pretends to decide but may lie later
                std::cout << "[Node " << id << "] (Byzantine) says I decided: " << val << "\n";
            } else {
                std::cout << "[Node " << id << "] (Honest) AGREED on value: " << val << "\n";
            }
        }
    }
};

// Global storage for node pointers (to allow message routing)
std::vector<Node*> nodes(N);

int main() {
    // Initialize nodes
    // Node 0: Honest, starts with 1
    // Node 1: Honest, starts with 1 (Agreement should be 1)
    // Node 2: Byzantine
    nodes[0] = new Node(0, false);
    nodes[1] = new Node(1, false);
    nodes[2] = new Node(2, true); 

    std::cout << "Starting Byzantine Agreement Simulation (n=" << N << ", f=" << F << ")\n";
    std::cout << "Honest Nodes start with 1. Byzantine node starts with 0 but may lie.\n\n";

    // Run agreement for Honest Node 0 & 1, and Byzantine Node 2
    std::vector<std::thread> threads;

    threads.emplace_back([&]() { nodes[0]->start({1}); });
    threads.emplace_back([&]() { nodes[1]->start({1}); });
    threads.emplace_back([&]() { nodes[2]->start({0}); }); // Byzantine starts with 0

    for (auto& t : threads) {
        t.join();
    }

    std::cout << "\nFinal Results:\n";
    int agreedValue = -1;
    bool allHonestAgreed = true;

    for (int i = 0; i < N; ++i) {
        if (!nodes[i]->isByzantine && nodes[i]->decided) {
            if (agreedValue == -1) agreedValue = nodes[i]->decisionValue;
            else if (agreedValue != nodes[i]->decisionValue) allHonestAgreed = false;

            std::cout << "Node " << i << ": Decided " << nodes[i]->decisionValue << "\n";
        } else if (nodes[i]->isByzantine && nodes[i]->decided) {
             std::cout << "Node " << i << " (Byzantine): Claimed decision " << nodes[i]->decisionValue << "\n";
        }
    }

    if (allHonestAgreed && agreedValue != -1) {
        std::cout << "✅ SUCCESS: Honest nodes reached agreement on " << agreedValue << "\n";
    } else {
        std::cout << "❌ FAILURE: Agreement not reached among honest nodes.\n";
    }

    // Cleanup
    for (auto n : nodes) delete n;

    return 0;
}
```

### How This Code Works

1.  **`Node` Class**:
    *   Each node has an inbox queue, a mutex to protect it, and a `cv` (condition variable) to sleep efficiently while waiting for messages.
    *   The `isByzantine` flag determines whether the node follows the protocol or sends conflicting information.

2.  **Broadcast Method**:
    *   This is the core network simulation. When a node calls `broadcast`, it loops through all node IDs (0, 1, and 2).
    *   It directly pushes messages into their `inbox` queues and notifies them via `cv.notify_one()`.
    *   If the sender is Byzantine (`shouldSendValidMessage` returns false), it sends a different value to Node 1 than it does to Node 2. This simulates the "split message" attack.

3.  **Round Logic**:
    *   The node enters a `while (inbox.size() < N)` loop, using `wait_for`. This is better than spinning because it saves CPU.
    *   Once it has collected messages from all `N` nodes (simulating delivery), it processes them.

4.  **Decision Logic**:
    *   In Round 2, we look for a "supermajority" (`> N/2`, which means at least 2 out of 3 votes).
    *   Because honest nodes (2 of them) start with `1` and vote `1`, they will always have a majority. The Byzantine node's lie doesn't matter here because 2 > 1.

