Below is a **practical, working Java example** of a **maximum bipartite matching** using the classic **Hopcroft–Karp algorithm**, which is asymptotically optimal for bipartite graphs. It’s reasonably efficient (O(E√V)) and easy to adapt.

If your graph is *already known* to be sparse and bounded-degree, certain linear‑time heuristics or randomized algorithms exist — but none are guaranteed O(n) worst case for arbitrary inputs.

#### ✅ Minimal Working Example: Maximum Bipartite Matching (Hopcroft–Karp)

```java
import java.util.*;

public class HopcroftKarp {
    private int U, V;                   // sizes of left & right partitions
    private List<List<Integer>> adj;  // adjacency list from U to V
    private int[] pairU, pairV;        // matching: pairU[u] = v or -1; pairV[v] = u or -1
    private int[] distU;               // BFS levels for U

    public HopcroftKarp(int U, int V) {
        this.U = U;
        this.V = V;
        adj = new ArrayList<>(U);
        for (int i = 0; i < U; i++) adj.add(new ArrayList<>());
        pairU = new int[U];
        pairV = new int[V];
        distU = new int[U];
        Arrays.fill(pairU, -1);
        Arrays.fill(pairV, -1);
    }

    public void addEdge(int u, int v) {
        if (u < 0 || u >= U || v < 0 || v >= V)
            throw new IllegalArgumentException("Vertex out of range");
        adj.get(u).add(v);
    }

    // BFS: builds layered graph from free vertices in U
    private boolean bfs() {
        Queue<Integer> queue = new LinkedList<>();
        for (int u = 0; u < U; u++) {
            if (pairU[u] == -1) {
                distU[u] = 0;
                queue.add(u);
            } else {
                distU[u] = Integer.MAX_VALUE;
            }
        }

        boolean foundAugmenting = false;
        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : adj.get(u)) {
                int nextU = pairV[v];
                if (nextU != -1 && distU[nextU] == Integer.MAX_VALUE) {
                    distU[nextU] = distU[u] + 1;
                    queue.add(nextU);
                } else if (nextU == -1) {
                    foundAugmenting = true;   // reached a free vertex in V
                }
            }
        }
        return foundAugmenting;
    }

    // DFS: finds vertex‑disjoint augmenting paths
    private boolean dfs(int u) {
        for (int v : adj.get(u)) {
            int nextU = pairV[v];
            if (nextU == -1 || (distU[nextU] == distU[u] + 1 && dfs(nextU))) {
                pairU[u] = v;
                pairV[v] = u;
                return true;
            }
        }
        distU[u] = Integer.MAX_VALUE;
        return false;
    }

    public int maximumMatching() {
        int matchingSize = 0;
        while (bfs()) {
            for (int u = 0; u < U; u++) {
                if (pairU[u] == -1 && dfs(u)) {
                    matchingSize++;
                }
            }
        }
        return matchingSize;
    }

    // Optional: retrieve actual matching edges
    public List<int[]> getMatching() {
        List<int[]> res = new ArrayList<>();
        for (int u = 0; u < U; u++) {
            if (pairU[u] != -1) {
                res.add(new int[]{u, pairU[u]});
            }
        }
        return res;
    }

    // Demo
    public static void main(String[] args) {
        // Example: bipartite graph with U={0,1,2}, V={0,1,2}
        HopcroftKarp hk = new HopcroftKarp(3, 3);
        hk.addEdge(0, 0);
        hk.addEdge(0, 1);
        hk.addEdge(1, 1);
        hk.addEdge(1, 2);
        hk.addEdge(2, 2);

        int matchSize = hk.maximumMatching();
        System.out.println("Maximum matching size: " + matchSize); // → 3
        for (int[] e : hk.getMatching()) {
            System.out.println(e[0] + " — " + e[1]);
        }
    }
}
```

