import org.bouncycastle.jce.ECNamedCurveTable;
import org.bouncycastle.jce.spec.ECParameterSpec;
import org.bouncycastle.jce.spec.ECPrivateKeySpec;
import org.bouncycastle.math.ec.ECPoint;

import java.math.BigInteger;
import java.util.HashMap;
import java.util.Map;

/**
 * WARNING: This example computes discrete logarithms ONLY for points with very small exponents (d < bound).
 * It is USELESS against standard cryptographic keys (d ≈ 2^256). Using this on a real key will take longer than the age of the universe.
 * 
 * DO NOT use for production cryptography. This is for educational/demonstration purposes only.
 */
public class DiscreteLogSmallExponent {

    // secp256k1 domain parameters (p, a, b, Gx, Gy, n, h)
    private static final String CURVE_NAME = "secp256k1";
    private static final ECDomainParameters PARAMS;
    private static final ECPoint G;

    static {
        ECParameterSpec spec = ECNamedCurveTable.getParameterSpec(CURVE_NAME);
        PARAMS = new ECDomainParameters(
            spec.getCurve(),
            spec.getG(),
            spec.getN(),
            spec.getH()
        );
        G = PARAMS.getG();
    }

    /**
     * Computes d such that Q = d*G, assuming 0 < d < bound.
     * Time complexity: O(sqrt(bound)) and space O(sqrt(bound)).
     */
    public static BigInteger computeDiscreteLog(ECPoint point, int bound) {
        // baby-step giant-step algorithm
        int m = (int) Math.ceil(Math.sqrt(bound));

        // 1. Baby steps: Store G, 2G, ..., mG in a hash map
        Map<ECPoint, BigInteger> table = new HashMap<>();
        ECPoint current = G;
        for (int i = 1; i <= m; i++) {
            table.put(current, BigInteger.valueOf(i));
            current = current.add(G);
        }

        // 2. Compute -m*G (for giant steps: Q - j*m*G)
        BigInteger neg_m = BigInteger.valueOf(-m);
        ECPoint neg_mG = G.multiply(neg_m);

        // 3. Giant steps: Check Q, Q+m*G, Q+2*m*G, ... 
        //   until we find a match in the table
        current = point;
        for (int j = 0; j <= m; j++) {
            if (table.containsKey(current)) {
                BigInteger babyStepIndex = table.get(current);
                // d = j*m + i
                return neg_m.multiply(BigInteger.valueOf(j)).add(babyStepIndex).mod(PARAMS.getN());
            }
            current = current.add(neg_mG); // equivalent to Q - (j+1)*m*G? 
            // Correction: We want Q - j*m*G. 
            // Since we added -m*G per step, current after j steps is Q + j*(-m*G) = Q - j*m*G.
        }

        throw new IllegalArgumentException("Discrete log not found within bound " + bound);
    }

    public static void main(String[] args) {
        System.out.println("=== Small discrete logarithm example (d < 10,000) ===");

        // Example: Use a small secret d = 12345
        BigInteger d = new BigInteger("12345");
        ECPoint Q = G.multiply(d);

        System.out.println("Original secret d = " + d);
        System.out.println("Q = d*G computed. Now recovering...");

        // Set a bound > d (e.g., 10,000 is too small for 12345; use 20000)
        int bound = 20000;

        try {
            long start = System.currentTimeMillis();
            BigInteger recoveredD = computeDiscreteLog(Q, bound);
            long time = System.currentTimeMillis() - start;

            System.out.println("Recovered d' = " + recoveredD);
            System.out.println("Match: " + recoveredD.equals(d));
            System.out.println("Time taken: " + time + " ms");

        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
        }

        // Demonstration of failure with a realistic key
        System.out.println("\n=== Attempting with cryptographic-scale exponent ===");
        BigInteger cryptoD = new BigInteger("123456789012345678901234567890123456789"); // ~289 bits
        ECPoint cryptoQ = G.multiply(cryptoD);

        System.out.println("Trying to recover d ≈ 2^96...");
        bound = 1_000_000; // 1 million (still trivial)
        start = System.currentTimeMillis();
        try {
            BigInteger recovered = computeDiscreteLog(cryptoQ, bound);
            time = System.currentTimeMillis() - start;
            System.out.println("Recovered in " + time + " ms: " + recovered);
        } catch (IllegalArgumentException e) {
            long time = System.currentTimeMillis() - start;
            System.out.println("Failed as expected after " + time + " ms.");
            System.out.println("Reason: d is much larger than the bound (" + bound + ").");
        }

        // For real crypto, show theoretical time for Pollard's rho
        System.out.println("\n=== Reality check (Pollard's rho for secp256k1) ===");
        BigInteger sqrt_n = PARAMS.getN().sqrt();
        System.out.println("√n ≈ 2^128 operations needed.");
        System.out.println("Estimated time on a single modern CPU: " + 
                          (sqrt_n.longValueExact() / 1_000_000_000L / 60 / 60 / 24) + " days");
        System.out.println("This is equivalent to ~" + (BigInteger.valueOf(2).pow(128)).divide(BigInteger.valueOf(1000000000L*365*24*60*60)) + 
                          " years of computation.");
    }
}
```

