## 🧪 Demo: Linear Scan in C++ (exact, works for any dim)

```cpp
#include <vector>
#include <cmath>
#include <limits>

using Point = std::vector<double>;

double squared_euclidean_distance(const Point& a, const Point& b) {
    double sum = 0.0;
    for (size_t i = 0; i < a.size(); ++i) {
        double diff = a[i] - b[i];
        sum += diff * diff;
    }
    return sum;
}

// Returns index of nearest point in `data` to `query`
size_t brute_force_nn(const std::vector<Point>& data,
                      const Point& query) {
    if (data.empty()) throw std::runtime_error("Empty database");

    size_t best_idx = 0;
    double best_dist = squared_euclidean_distance(query, data[0]);

    for (size_t i = 1; i < data.size(); ++i) {
        double dist = squared_euclidean_distance(query, data[i]);
        if (dist < best_dist) {
            best_dist = dist;
            best_idx = i;
        }
    }
    return best_idx;
}

