Here's a concise **Java pseudo-code example** demonstrating core Raft consensus logic under a *partial synchrony* model (with bounded network delays and message timeouts). This example focuses on the leader election phase, which is critical for establishing consensus.

It includes:
- Timeout-based leader elections
- Term management
- Vote requests & handling
- Explicit failure scenarios (`TimeoutException`, node crashes)

```java
import java.util.*;
import java.util.concurrent.*;

// --- Core Types ---
enum Role { CANDIDATE, LEADER, FOLLOWER }

class Message {
    String type;         // "RequestVote", "Response"
    int term;
    String senderId;
    String receiverId;
    int lastLogIndex;
    int lastLogTerm;
}

public class RaftNode implements Runnable {
    private final String id;
    private volatile Role role = Role.FOLLOWER;
    private volatile int currentTerm = 0;
    private volatile String votedFor = null;
    private final Map<String, Integer> votesReceived = new ConcurrentHashMap<>();

    private final ExecutorService executor = Executors.newFixedThreadPool(1);
    private ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(2);

    // Partial synchrony: assume message delays are bounded after GST*, but until then use timeouts
    // (GST = Global Stabilization Time - theoretical bound on network sync)
    private static final long ELECTION_TIMEOUT_MS = 150 + new Random().nextInt(300); // randomize to prevent split votes

    public RaftNode(String id) {
        this.id = id;
        executor.submit(this::startElectionTimeout);
    }

    // --- Leader Election Protocol ---

    public void startElectionTimeout() {
        while (!Thread.interrupted()) {
            try {
                Thread.sleep(ELECTION_TIMEOUT_MS); // timeout without hearing from leader
                // Failure: node detected no leader -- start election
                if (role != Role.LEADER) {
                    System.out.println(id + ": Starting election for term " + (currentTerm + 1));
                    electSelf();
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt(); // restore interrupt status
                break;
            } catch (TimeoutException te) { 
                // Explicit failure handling: node might be partitioned or overloaded
                System.err.println(id + ": Election timeout exceeded! " + te.getMessage());
            }
        }
    }

    private void electSelf() {
        role = Role.CANDIDATE;
        currentTerm++;
        votedFor = id;
        votesReceived.clear();
        votesReceived.put(id, 1); // vote for self

        System.out.println(id + ": Term " + currentTerm + ", voting for self.");

        // Broadcast RequestVote to all peers
        executor.submit(() -> {
            int quorum = (getClusterSize() / 2) + 1;

            // Send RPCs in parallel
            List<CompletableFuture<Boolean>> futures = new ArrayList<>();
            for (String peerId : getPeers()) {
                CompletableFuture<Boolean> future = sendRequestVote(peerId, currentTerm);
                futures.add(future.thenAccept(response -> {
                    if (!response) return; 

                    synchronized(this) { // atomic update to term & vote state
                        handleResponseFromPeer(response, currentTerm, peerId);
                        if (getMajority(quorum)) {
                            becomeLeader();
                        }
                    }
                }));
            }

            try {
                CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).get(ELECTION_TIMEOUT_MS, TimeUnit.MILLISECONDS);
                // If not elected after timeout: restart election (handled by main loop)
            } catch (TimeoutException e) {
                System.err.println(id + ": Election timed out; restarting");
            }
        });
    }

    public synchronized void handleRequestVote(String senderId, int term, int lastLogIndex, int lastLogTerm) {
        boolean voteGranted = false;

        // 1. Update term if necessary (partial synchrony: messages may be delayed but terms monotonically increase)
        if (term > currentTerm) {
            currentTerm = term;
            votedFor = null;
            role = Role.FOLLOWER;
        }

        // 2. Grant vote conditionally
        boolean logUpToDate = lastLogTerm > getCurrentLastLogTerm() || 
                              (lastLogTerm == getCurrentLastLogTerm() && 
                               lastLogIndex >= getCurrentLastLogIndex());

        if (term == currentTerm && 
            (votedFor == null || votedFor.equals(senderId)) &&
            logUpToDate) {

            votedFor = senderId;
            voteGranted = true;
            System.out.println(id + ": Granted vote to " + senderId + " for term " + currentTerm);
        } else if (term < currentTerm) {
            // Older request — stale
            System.out.println(id + ": Rejected vote from " + senderId + ": stale term");
        }

        sendResponse(senderId, currentTerm, voteGranted);
    }

    private void handleResponseFromPeer(boolean granted, int term, String senderId) {
        if (role != Role.CANDIDATE) return; // Ignore responses after stepping down

        if (term > currentTerm) {
            role = Role.FOLLOWER;
            currentTerm = term;
            votedFor = null;
            System.out.println(id + ": Stepped down to follower: higher term " + term);
        } else if (granted && term == currentTerm) {
            votesReceived.merge(senderId, 1, Integer::sum);
        }
    }

    private synchronized void becomeLeader() {
        role = Role.LEADER;
        System.out.println(id + ": I am the leader of term " + currentTerm);
        // Start sending heartbeats here (not shown for brevity)
    }

    // --- Helpers ---
    private int getClusterSize() { return 3; } // e.g., fixed 3-node cluster
    private List<String> getPeers() { 
        return Arrays.asList("node2", "node3"); 
    }

    private boolean getMajority(int quorum) {
        return votesReceived.size() >= quorum;
    }

