#include <threads.h>
#include <stdatomic.h>
#include <time.h>

_Atomic bool stop_flag = false;

int worker(void* arg) {
    (void)arg; // unused
    while (!atomic_load_explicit(&stop_flag, memory_order_relaxed)) {
        printf("Worker running...\n");
        thrd_sleep(&(struct timespec){.tv_sec = 0, .tv_nsec = 200000000}, NULL);
    }
    printf("Worker stopped.\n");
    return 0;
}

int main() {
    thrd_t worker_thread;
    thrd_create(&worker_thread, worker, NULL);

    thrd_sleep(&(struct timespec){.tv_sec = 1, .tv_nsec = 0}, NULL);

    printf("Requesting stop...\n");
    atomic_store_explicit(&stop_flag, true, memory_order_relaxed);

    thrd_join(worker_thread, NULL);
    return 0;
}
```

