Here's a concise, production-ready Go example using `database/sql` for connection pooling:

```go
package main

import (
	"database/sql"
	"fmt"
	"log"

	_ "github.com/go-sql-driver/mysql" // MySQL driver (example)
)

func main() {
	// DSN format: username:password@tcp(host:port)/dbname?parseTime=true&interpolateParams=true
	dsn := "user:pass@tcp(localhost:3306)/mydb"

	// Open creates a connection pool, not an immediate connection
	db, err := sql.Open("mysql", dsn)
	if err != nil {
		log.Fatalf("Failed to open database: %v", err)
	}
	defer db.Close()

	// Optional: Configure connection pool limits
	db.SetMaxOpenConns(10)    // Max # of connections (default = 0, unlimited)
	db.SetMaxIdleConns(5)     // Max idle connections in pool (should be ≤ max open)
	db.SetConnMaxLifetime(30 * time.Minute) // Reuse connections up to this duration

	// Test connection immediately (optional but recommended for health checks)
	if err := db.Ping(); err != nil {
		log.Fatalf("Failed to ping database: %v", err)
	}

	fmt.Println("Connection pool established successfully")

	// Example query (connection is borrowed from the pool during Query)
	rows, err := db.Query("SELECT id, name FROM users LIMIT 5")
	if err != nil {
		log.Fatal(err)
	}
	defer rows.Close()

	for rows.Next() {
		var id int
		var name string
		if err := rows.Scan(&id, &name); err != nil {
			log.Printf("Scan failed: %v", err)
			continue
		}
		fmt.Printf("User: ID=%d, Name=%s\n", id, name)
	}
	if err := rows.Err(); err != nil {
		log.Fatal(err)
	}

	// Pool is automatically managed:
	// - Connections are returned to the pool after use (after Close/defer)
	// - Idle connections are closed if exceeding SetMaxIdleConns
	// - Lost connections are detected and reestablished as needed
}
```

**Key Notes for Internal Docs:**
- `sql.Open()` returns a handle with an internal connection pool — it doesn't open connections immediately
- **Always defer `db.Close()`** to ensure proper cleanup of the pool and idle connections
- Set pool limits based on your database's capacity (`SetMaxOpenConns`, `SetMaxIdleConns`)
- The driver (e.g., `go-sql-driver/mysql`) is imported with `_` (blank identifier) for its side effects
- Connection pooling handles reconnection, lifetime management, and idle cleanup automatically

The `math/big` package doesn’t provide direct factoring functions, but you can use its `Int` type to represent integers and write a simple trial-division factorization.

Here’s a short example that factors an integer into prime factors:

```go
package main

import (
	"fmt"
	"math/big"
)

func factor(n *big.Int) []*big.Int {
	var factors []*big.Int
	two := big.NewInt(2)

	// Handle factor of 2
	for n.Bit(0) == 0 {
		factors = append(factors, new(big.Int).Set(two))
		n.Div(n, two)
	}

	// Check odd factors from 3 up to sqrt(n)
	var d big.Int
	d.SetInt64(3)
	var remainder, quotient big.Int
	for d.Cmp(new(big.Int).Sqrt(n)) <= 0 {
		if n.ProbablyPrime(15) { // Quick primality test for remaining n
			factors = append(factors, new(big.Int).Set(n))
			return factors
		}

		// Try dividing by d
		if n.Mod(&remainder, n, &d).BitLen() == 0 {
			factors = append(factors, new(big.Int).Set(&d))
			n.Div(n, &d)
		} else {
			d.Add(&d, big.NewInt(2)) // next odd number
		}
	}

	// If n > 1 now, it's prime
	if n.BitLen() > 0 {
		factors = append(factors, new(big.Int).Set(n))
	}

	return factors
}

func main() {
	n := big.NewInt(123456)
	fmt.Printf("Factors of %s: ", n)
	for i, f := range factor(new(big.Int).Set(n)) {
		if i > 0 {
			fmt.Print(" × ")
		}
		fmt.Print(f)
	}
	fmt.Println()
}
```

Output:
```
Factors of 123456: 2 × 2 × 2 × 2 × 2 × 2 × 3 × 643
```

Note: For **small** integers, `big.Int` isn’t strictly necessary—plain `int64` would suffice—but this demonstrates how to use `math/big`. For large integer factorization (e.g., RSA-size numbers), you’d need more advanced algorithms like Pollard’s rho or the quadratic sieve, which aren’t in Go’s standard library.

