### ✅ Step 2: C++ QUIC Lossless Client (uses streams + checksum)

```cpp
// quic_client_lossless.cpp
#include <quiche.h>
#include <iostream>
#include <string>
#include <vector>
#include <cstring>

void die(const std::string& msg) {
    std::cerr << "Error: " << msg << "\n";
    exit(1);
}

int main() {
    const char* host = "example.com"; // Replace with real server
    const char* path = "/test.txt";
    uint16_t port = 443;

    // --- TLS configuration (required for QUIC) ---
    quiche_config* config = quiche_config_new(QUICHE_PROTOCOL_VERSION);
    if (!config) die("Failed to create config");

    // For demo only: disable cert verification
    quiche_config_set_verify_peer(config, false);

    // Enable loss recovery tuning (not needed for most apps, but good for latency)
    quiche_config_set_max_idle_timeout(config, 30000); // 30 sec

    // --- Create connection ---
    quiche_conn* conn = nullptr;
    uint8_t buf[1500];
    size_t len;

    // Connect to server (UDP-like)
    struct sockaddr_in serv_addr {};
    serv_addr.sin_family = AF_INET;
    inet_pton(AF_INET, "93.184.216.34", &serv_addr.sin_addr); // example.com IP
    serv_addr.sin_port = htons(port);

    quiche_path* path_obj = nullptr;  // We'll use default

    std::vector<uint8_t> scid(QUICHE_MAX_CONN_ID_LEN);
    if (quiche_randomize(scid.data(), scid.size()) != 0)
        die("Failed to generate random CID");

    conn = quiche_connect(host, scid.data(), scid.size(),
                          reinterpret_cast<sockaddr*>(&serv_addr),
                          sizeof(serv_addr), config);

    if (!conn) die("Failed to create connection");

    // --- Send initial packet ---
    len = quiche_conn_send(conn, buf, sizeof(buf));
    if (len == 0) {
        std::cout << "No data to send.\n";
    } else {
        // In real code: sendto(sockfd, buf, len, 0, ...)
        std::cout << "Sent " << len << " bytes\n";
    }

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) die("socket() failed");

    // Simulate blocking UDP send/recv for brevity
    auto sendto_fd = [&](const uint8_t* data, size_t len) {
        sendto(sockfd, (char*)data, len, MSG_NOSIGNAL,
               reinterpret_cast<sockaddr*>(&serv_addr), sizeof(serv_addr));
    };

    auto recvfrom_fd = [&](uint8_t* buf, size_t cap) -> ssize_t {
        struct sockaddr_in from;
        socklen_t from_len = sizeof(from);
        return recvfrom(sockfd, (char*)buf, cap, 0,
                        reinterpret_cast<sockaddr*>(&from), &from_len);
    };

    // Send initial packet
    sendto_fd(buf, len);

    // --- Open a unidirectional stream for reliability ---
    int64_t stream_id = quiche_conn_stream_next(conn);
    if (stream_id < 0) {
        die("Failed to get next stream ID");
    }

    std::string message = "Hello from C++! This is lossless.";
    uint8_t fin = 1; // Close stream after sending data

    // Write data + fin on stream
    ssize_t written = quiche_conn_stream_send(conn, stream_id,
                                              (uint8_t*)message.data(),
                                              message.size(), fin);
    if (written < 0) {
        die("Failed to send on stream");
    }

    std::cout << "Wrote " << written << " bytes to stream " << stream_id << "\n";

    // --- Send data ---
    len = quiche_conn_send(conn, buf, sizeof(buf));
    if (len > 0) sendto_fd(buf, len);

    // --- Wait for response (poll loop, simplified) ---
    bool done = false;
    uint8_t recv_buf[65536];
    while (!done) {
        ssize_t read_len = recvfrom_fd(recv_buf, sizeof(recv_buf));
        if (read_len <= 0) break; // timeout or error

        quiche_recv_info recv_info{};
        quiche_conn_recv(conn, recv_buf, read_len, &recv_info);

        // Check for handshake completion
        if (quiche_conn_is_established(conn)) {
            std::cout << "Handshake complete\n";
        }

        // Read incoming streams
        int64_t stream_id;
        while (true) {
            uint8_t fin;
            ssize_t len = quiche_conn_stream_recv(conn, &stream_id,
                                                  recv_buf, sizeof(recv_buf),
                                                  &fin);
            if (len <= 0) break; // no more data on streams

            std::string response((char*)recv_buf, len);

            // For lossless: apply your own checksum here!
            // e.g., MD5/SHA256 + ACK
            std::cout << "Received stream " << stream_id 
                      << ": " << response;

            if (fin) {
                std::cout << " [FIN]\n";
                done = true;
            }
        }

        len = quiche_conn_send(conn, buf, sizeof(buf));
        if (len > 0) sendto_fd(buf, len);
    }

    // Graceful close
    uint8_t app_err = 0; // no error
    len = quiche_conn_close(conn, true, &app_err, 1, buf, sizeof(buf));
    if (len > 0) sendto_fd(buf, len);

    quiche_conn_free(conn);
    quiche_config_free(config);
    close(sockfd);

    std::cout << "Connection closed.\n";
}
