UDP doesn’t provide reliability or ordering guarantees, and there’s no standard protocol called **“UDP-Reliable-ExactlyOnce”** — but you can build your own lightweight reliable-delivery layer on top of UDP using the classic **stop-and-wait ARQ (Automatic Repeat reQuest)** with unique message IDs + acknowledgements.

For “exactly-once”, you need to handle duplicate detection and ensure the server doesn’t process the same message twice even if it crashes or restarts. Below is a **minimal, self-contained Go example**:

---

### Key Concepts Used
- **Unique Message IDs**: Each client-generated message has a UUID.
- **ACK/NAK**: Server sends ACK for received messages with unique ID.
- **Retransmission**: Client retransmits if no ACK within timeout (not fully implemented in minimal server, but shown).
- **Deduplication**: Server maintains a `map[string]struct{}` of seen IDs + an offset (e.g., last processed) to enforce exactly-once ordering.
- **Persistence** (optional for crash recovery): Use a file/DB; omitted here for minimalism.

---

### Minimal Working Example

#### 1. Protocol Definition (`protocol.go`)
```go
package main

import "encoding/json"

type Message struct {
	ID      string `json:"id"`       // Unique per send (e.g., UUID)
	Payload string `json:"payload"`  // Your data
}

// ACK contains the message ID to confirm receipt
type Ack struct {
	ID string `json:"id"`
}
```

---

#### 2. Server (`server.go`)
```go
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net"
	"sync"
)

type Server struct {
	conn     *net.UDPConn
	seenMu   sync.RWMutex
	seenIDs  map[string]bool // deduplication set
}

func NewServer(addr string) (*Server, error) {
	udpAddr, err := net.ResolveUDPAddr("udp", addr)
	if err != nil {
		return nil, err
	}
	conn, err := net.ListenUDP("udp", udpAddr)
	if err != nil {
		return nil, err
	}

	return &Server{
		conn:    conn,
		seenIDs: make(map[string]bool),
	}, nil
}

func (s *Server) Run() {
	buf := make([]byte, 1500) // MTU-sized buffer

	for {
		n, clientAddr, err := s.conn.ReadFromUDP(buf)
		if err != nil {
			log.Printf("Read error: %v", err)
			continue
		}

		msg := new(Message)
		if err := json.Unmarshal(buf[:n], msg); err != nil {
			log.Printf("Invalid JSON from %v", clientAddr)
			continue
		}

		s.seenMu.Lock()
		if s.seenIDs[msg.ID] {
			// Idempotent: already processed → send ACK but skip processing
			s.seenMu.Unlock()
			fmt.Printf("Duplicate message ignored: %s\n", msg.ID)
		} else {
			// Process exactly-once
			s.seenIDs[msg.ID] = true
			s.seenMu.Unlock()

			// Your business logic here:
			fmt.Printf("[EXACTLY-ONCE] Received: ID=%s Payload=%q from %v\n",
				msg.ID, msg.Payload, clientAddr)

			// Simulate crash-safe write (in real code, use DB/file)
		}

		// Send ACK
		ack := Ack{ID: msg.ID}
		ackBytes, _ := json.Marshal(ack)
		s.conn.WriteToUDP(ackBytes, clientAddr)
	}
}

func main() {
	server, err := NewServer("localhost:8081")
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println("Reliable UDP server listening on :8081")
	server.Run()
}
```

---

#### 3. Client (Example: `client.go`)
*(To test the server)*
```go
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net"
	"time"
)

func main() {
	// Generate unique ID (in real usage, use UUIDs)
	msg := Message{ID: "msg-001", Payload: "Hello Exactly-Once!"}

	client, err := net.DialUDP("udp", nil, &net.UDPAddr{
		IP:   net.ParseIP("127.0.0.1"),
		Port: 8081,
	})
	if err != nil {
		log.Fatal(err)
	}
	defer client.Close()

	data, _ := json.Marshal(msg)

	for attempt := 1; attempt <= 3; attempt++ {
		fmt.Printf("[Client] Sending (attempt %d)...\n", attempt)
		client.Write(data)

		client.SetReadDeadline(time.Now().Add(500 * time.Millisecond))

		buf := make([]byte, 256)
		n, _, _ := client.ReadFromUDP(buf)
		if n > 0 {
			var ack Ack
			json.Unmarshal(buf[:n], &ack)
			if ack.ID == msg.ID {
				fmt.Println("[Client] ACK received — success!")
				break
			}
		} else {
			log.Printf("No ACK — retrying...")
		}
	}
}
```

---

### How This Achieves “Exactly-Once”
1. **Deduplication via UUID**: The server checks `seenIDs[msg.ID]` in a mutex-protected map.
2. **ACKs**: Ensures the client knows when the server has processed the message — client can ignore duplicates on retransmission.
3. **Idempotency**: Receiving the same ID again doesn’t trigger double processing.

