Here’s a concise Go example you can include in your internal documentation. It shows how to configure and use `turbopool` with an existing `*sql.DB` (e.g., MySQL or PostgreSQL):

```go
package main

import (
	"database/sql"
	"fmt"
	"log"
	"time"

	_ "github.com/go-sql-driver/mysql" // Example driver; replace with your DB's driver
	"github.com/gofast/turbopool"
)

func main() {
	// 1. Create a standard database connection (using turbopool doesn’t replace this)
	db, err := sql.Open("mysql", "user:password@tcp(localhost:3306)/mydb")
	if err != nil {
		log.Fatalf("failed to open DB: %v", err)
	}
	defer db.Close()

	// 2. Wrap the *sql.DB in a turbopool.Pool
	pool, err := turbopool.NewPool(turbopool.Config{
		TargetDB:       db,
		PoolSize:       10,          // Max connections in the pool (optional; defaults to DB max)
		AcquireTimeout: 5 * time.Second,
	})
	if err != nil {
		log.Fatalf("failed to create pool: %v", err)
	}
	defer pool.Close()

	// 3. Use pool.DB() wherever you’d normally use db
	rows, err := pool.Query("SELECT id FROM users WHERE active = ?", true)
	if err != nil {
		log.Fatalf("query failed: %v", err)
	}
	defer rows.Close()

	for rows.Next() {
		var id int
		if err := rows.Scan(&id); err != nil {
			log.Printf("scan error: %v", err)
			continue
		}
		fmt.Println("User ID:", id)
	}

	if err := rows.Err(); err != nil {
		log.Fatalf("rows error: %v", err)
	}

	// Note: You can still call methods like Exec, Prepare, etc. on pool.DB()
}
```

