#include <iostream>
#include <vector>
#include <tbb/parallel_for.h>

void parallel_sum() {
    const size_t N = 1'000'000;
    std::vector<int> data(N);
    for (size_t i = 0; i < N; ++i) data[i] = static_cast<int>(i);

    int sum = 0;
    tbb::parallel_for(
        size_t{0}, 
        N,
        [&](const tbb::blocked_range<size_t>& r) {
            int local_sum = 0;
            for (size_t i = r.begin(); i < r.end(); ++i) {
                local_sum += data[i];
            }
            // Thread-safe accumulation using atomic or reduction
            sum += local_sum;  // ⚠️ Not thread-safe! See explanation below.
        }
    );

    std::cout << "Sum (naive parallel): " << sum << '\n'; 
