#include <vector>
#include <algorithm>

void simd_sort_floats(std::vector<float>& v) {
    // Sort in-place with std::sort (compiler may auto-vectorize)
    std::sort(v.begin(), v.end());

    // Manual SIMD step: if needed, do SIMD operations *after* sort
    // Example: zero out small values using AVX2:
    for (size_t i = 0; i + 7 < v.size(); i += 8) {
