import javax.json.*;
import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;

public class JsonTurboDemo {
    public static void main(String[] args) {
        String json = "{\"name\":\"Alice\",\"age\":30,\"skills\":[\"Java\",\"JSON-P\"]}";

        try (JsonParser parser = Json.createParser(new StringReader(json))) {

            List<String> skills = new ArrayList<>();
            String currentKey = null;

            while (parser.hasNext()) {
                Event event = parser.next();

                switch (event) {
                    case KEY_NAME:
                        currentKey = parser.getString();
                        break;
                    case VALUE_STRING:
                        if ("name".equals(currentKey)) {
                            System.out.println("Name: " + parser.getString());
                        } else if ("skills".equals(currentKey)) {
                            // We'll collect skills separately below
                        }
                        break;
                    case VALUE_NUMBER:
                        if ("age".equals(currentKey)) {
                            System.out.println("Age: " + parser.getInt());
                        }
                        break;
                    case START_ARRAY:
                        if ("skills".equals(currentKey)) {
                            while (parser.hasNext() && parser.next() != Event.END_ARRAY) {
                                skills.add(parser.getString());
                            }
                        }
                        break;
                }
            }

