/**
 * A thread-safe map offering constant-time (amortized O(1)) put, get,
 * and remove operations using a hash table.
 *
 * @param <K> the type of keys maintained by this map
 * @param <V> the type of mapped values
 */
public class ConstantTimeMap<K, V> implements Map<K, V> {

    private final ConcurrentHashMap<K, V> delegate;

    /**
     * Creates a new {@code ConstantTimeMap} with default initial capacity (16)
     * and load factor (0.75).
     */
    public ConstantTimeMap() {
        this.delegate = new ConcurrentHashMap<>();
    }

    /**
     * Creates a new {@code ConstantTimeMap} with the specified initial capacity
     * and default load factor.
     *
     * @param initialCapacity the initial capacity. The implementation
     *                        performs no bounds-checking; this value is passed directly to
     *                        the underlying {@link ConcurrentHashMap}.
     */
    public ConstantTimeMap(int initialCapacity) {
        this.delegate = new ConcurrentHashMap<>(initialCapacity);
    }

    /**
     * Creates a new {@code ConstantTimeMap} with the same mappings as the specified map.
     *
     * @param m the map whose mappings are to be placed in this map
     * @throws NullPointerException if the specified map is null
     */
    public ConstantTimeMap(Map<? extends K, ? extends V> m) {
        this.delegate = new ConcurrentHashMap<>(m);
    }

    // Core Map methods (delegated for O(1) operations)

    @Override
    public int size() {
        return delegate.size();
    }

    @Override
    public boolean isEmpty() {
        return delegate.isEmpty();
    }

    @Override
    public boolean containsKey(Object key) {
        return delegate.containsKey(key);
    }

    @Override
    public boolean containsValue(Object value) {
        // Note: containsValue is O(n) in ConcurrentHashMap!
        return delegate.containsValue(value);
    }

    @Override
    public V get(Object key) {
        return delegate.get(key);
    }

    @Override
    public V put(K key, V value) {
        return delegate.put(key, value);
    }

    @Override
    public V remove(Object key) {
        return delegate.remove(key);
    }

    // Optional unsupported operations for simplicity (or could be implemented as needed)
    @Override
    public void putAll(Map<? extends K, ? extends V> m) {
        delegate.putAll(m);
    }

    @Override
    public void clear() {
        delegate.clear();
    }

    @Override
    public java.util.Set<K> keySet() {
        return delegate.keySet();
    }

    @Override
    public java.util.Collection<V> values() {
        return delegate.values();
    }

    @Override
    public java.util.Set<Entry<K, V>> entrySet() {
        return delegate.entrySet();
    }
}
```

