Here’s a **working, minimal example** using `sharp-autocrop` with Sharp:

```javascript
const sharp = require('sharp');
const autocrop = require('sharp-autocrop');

async function processImage(inputPath, outputPath) {
  try {
    // Load image and apply autocrop + resize in one chain
    await sharp(inputPath)
      .rotate()                 // auto-orient using EXIF metadata (recommended)
      .autocrop()              // use sharp-autocrop plugin to trim transparent/border areas
      .resize({                // resize the cropped result
        width: 800,
        height: 600,
        fit: 'cover',          // fills dimensions, crops excess
        withoutEnlargement: true
      })
      .toFile(outputPath);

