    "time"
)

// Node represents a node in the distributed system.
type Node struct {
    id           int
    peers         []int
    raftState     map[int]bool // Simplified Raft state tracking
    lockHeld      bool
    requestChan   chan *LockRequest
    responseChan  chan *LockResponse
    leaderChan    chan bool    // Whether the node is currently leader
}

// LockRequest represents a request to acquire or release a lock.
type LockRequest struct {
    ProcessID int
    RequestType string // "acquire" or "release"
    ResponseChan chan *LockResponse
}

// LockResponse represents the response to a lock request.
type LockResponse struct {
    Granted bool
}

func main() {
    numNodes := 3
    nodes := make([]*Node, numNodes)

    for i := range nodes {
        nodes[i] = newNode(i, numNodes)
    }

    // Start Raft processes (simplified for example)
    for _, node := range nodes {
        go raftProcess(node)
    }

    // Test the distributed lock
    testLock(nodes[0], 1)
}

func newNode(id int, totalPeers int) *Node {
    peers := make([]int, totalPeers-1)
    for i := 0; i < totalPeers; i++ {
        if i != id {
            peers[i] = i
        }
    }

    node := &Node{
        id:           id,
        peers:         peers,
        raftState:     make(map[int]bool),
        lockHeld:      false,
        requestChan:   make(chan *LockRequest, 10),
        responseChan:  make(chan *LockResponse, 10),
        leaderChan:    make(chan bool, 1),
    }

    go node.processRequests()
    return node
}

func (n *Node) processRequests() {
    for {
        select {
        case req := <-n.requestChan:
            if !n.isLeader() {
                // Forward request to current leader
                leaderID := n.getCurrentLeader()
                if leaderID != -1 && leaderID != n.id {
                    fmt.Printf("Node %d forwarding request to leader %d\n", n.id, leaderID)
                    nodes[leaderID].requestChan <- req
                }
            } else {
                // Leader processes the request
                if req.RequestType == "acquire" {
                    if !n.lockHeld {
                        n.lockHeld = true
                        fmt.Printf("Node %d granted lock to process %d\n", n.id, req.ProcessID)
                        respond(req.ResponseChan, true)
                    } else {
                        fmt.Printf("Node %d cannot grant lock (held by someone)\n", n.id)
                        respond(req.ResponseChan, false)
                    }
                } else if req.RequestType == "release" {
                    if n.lockHeld && n.isLeader() {
                        n.lockHeld = false
                        fmt.Printf("Node %d released lock\n", n.id)
                        respond(req.ResponseChan, true)
                    }
                }
            }
        case isLeader := <-n.leaderChan:
            // Update Raft state (simplified)
            for peerID := range n.raftState {
                n.raftState[peerID] = false
            }
            if isLeader {
                fmt.Printf("Node %d became leader\n", n.id)
                n.raftState[n.id] = true
            } else {
                fmt.Printf("Node %d is not leader\n", n.id)
            }
        }
    }
}

func (n *Node) isLeader() bool {
    for peerID, state := range n.raftState {
        if state && peerID == n.id {
            return true
        }
    }
    return false
}

func (n *Node) getCurrentLeader() int {
    for peerID, state := range n.raftState {
        if state {
            return peerID
        }
    }
    return -1
}

// Simplified Raft process
func raftProcess(n *Node) {
    // This is a simplified example; in real Raft implementation,
    // you'd have election and heartbeat mechanisms.
    time.Sleep(2 * time.Second)
    n.leaderChan <- true

    for {
        // Simulate Raft state changes (simplified)
        time.Sleep(time.Second)
        if !n.isLeader() {
            n.leaderChan <- false
        }
    }
}

func respond(responseChan chan *LockResponse, granted bool) {
    responseChan <- &LockResponse{Granted: granted}
}

// Test the lock mechanism with a simple example.
func testLock(node *Node, processID int) {
    // Request lock
    requestChan := make(chan *LockResponse)
    node.requestChan <- &LockRequest{
        ProcessID:  processID,
        RequestType: "acquire",
        ResponseChan: requestChan,
    }

    response := <-requestChan
    fmt.Printf("Process %d acquired lock? %v\n", processID, response.Granted)

    // Release lock after some time
    time.Sleep(1 * time.Second)
    releaseRequestChan := make(chan *LockResponse)
    node.requestChan <- &LockRequest{
        ProcessID:  processID,
        RequestType: "release",
        ResponseChan: releaseRequestChan,
    }

    response = <-releaseRequestChan
    fmt.Printf("Process %d released lock? %v\n", processID, response.Granted)
}
```

### Key Features of This Implementation:

1. **Raft Consensus Algorithm**: The implementation uses Raft to ensure consistent state across all nodes in the distributed system. A single leader is elected, and only the leader can grant locks.

2. **Safety**: Only one node (the current leader) can hold the lock at any time, ensuring safety.

3. **Liveness**: If a process requests the lock, it will eventually get it as long as there's no conflicting request.

4. **Crash Recovery**: The Raft algorithm handles node crashes by re-electing a new leader when necessary.

### How It Works:

1. Each node has a state indicating whether it is the current leader and whether it holds the lock.

2. When a process requests a lock, it sends a request to any node in the cluster. If the node receiving the request is not the current leader, it forwards the request to the current leader.

3. The leader processes all lock requests:
   - It grants the lock only if it's currently available.
   - It releases the lock when requested by the process holding it.

4. The Raft algorithm ensures that all nodes eventually agree on who is the leader and whether a lock is held or not, even in the presence of crashes and network partitions.

### Usage:

1. Create multiple nodes as shown in the `main` function.
2. Start the Raft processes for each node.
3. Use the `testLock` function to request and release locks.

### Notes:

- This is a simplified example. In a real-world implementation, you would need to handle more edge cases and implement the full Raft algorithm with elections, heartbeats, and log replication.
- For better fault tolerance, you should implement proper leader election mechanisms and handle network partitions correctly.
- You might want to add timeouts and retry logic for processes waiting for lock responses.

