pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/extensions/ERC20PresetMinterPauser.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract SecureToken is ERC20PresetMinterPauser, ReentrancyGuard {
    event OwnershipRenounced(address indexed previousOwner);
    event AttackDetected(string description);

    constructor() 
        ERC20PresetMinterPauser("SecureToken", "STK")
    {}

    function renounceOwnership() public override onlyOwner {
        emit OwnershipRenounced(owner());
        _transferOwnership(address(0));
    }

    modifier onlyRoleAdmin() {
        require(hasRole(DEFAULT_ADMIN_ROLE, msg.sender), "Not admin");
        _;
    }

    function approve(address spender, uint256 amount) public virtual override returns (bool) {
        address sender = msg.sender;
        _approve(sender, spender, amount);
        return true;
    }

    function transferFrom(
        address sender,
        address recipient,
        uint256 amount
    ) public virtual override returns (bool) {
        _transfer(sender, recipient, amount);

        uint256 currentAllowance = allowance[sender][msg.sender];
        if (currentAllowance != type(uint256).max) {
            require(currentAllowance >= amount, "ERC20: transfer amount exceeds allowance");
            if (amount > 0) {
                _approve(sender, msg.sender, currentAllowance - amount);
            }
        }

        return true;
    }

    function secureApprove(address spender, uint256 amount) public returns (bool) {
        address sender = msg.sender;
        require(spender != address(0), "ERC20: approve to the zero address");

        uint256 currentAllowance = allowance[sender][spender];
        if (currentAllowance > 0) {
            _approve(sender, spender, currentAllowance - currentAllowance);
        }
        _approve(sender, spender, amount);

        emit Approval(sender, spender, amount);
        return true;
    }

    function detectAttack(string memory description) public onlyRoleAdmin {
        emit AttackDetected(description);
    }

    receive() external payable {
        revert("No payments accepted");
    }
}
```

