class Node:
    def __init__(self, node_id):
        self.node_id = node_id
        self.state = {}
        self.log = []
        self.current_term = 0
        self.voted_for = None
        self.commit_index = 0
        self.last_heartbeat = time.time()
        self.is_leader = False
        self.vote_count = 0
        self.heartbeat_timeout = 1  # seconds
        self.majority = 2  # for simplicity, assuming majority is n/2 + 1 where n=3

    def start(self):
        threading.Thread(target=self.run).start()

    def run(self):
        while True:
            if not self.is_leader:
                self.follow_behavior()
            else:
                self.leader_behavior()
            time.sleep(0.1)

    def follow_behavior(self):
        if time.time() - self.last_heartbeat > self.heartbeat_timeout:
            # Leader is down, start election
            self.request_vote()

    def leader_behavior(self):
        # Send heartbeats to followers
        for node in other_nodes:
            node.receive_heartbeat()
        # Handle write operations here

    def request_vote(self):
        if not self.is_leader and time.time() - self.last_heartbeat > 1:
            self.current_term += 1
            self.voted_for = self.node_id
            votes = 1
            for node in other_nodes:
                if node.vote_request(self.node_id, self.current_term):
                    votes += 1
            if votes >= self.majority:
                self.become_leader()

    def vote_request(self, candidate_id, term):
        if term > self.current_term or (term == self.current_term and not self.voted_for):
            self.current_term = term
            self.voted_for = candidate_id
            return True
        return False

    def become_leader(self):
        self.is_leader = True
        self.vote_count = 0

    def receive_heartbeat(self):
        self.last_heartbeat = time.time()

class RaftCluster:
    def __init__(self, num_nodes=3):
        self.nodes = [Node(i) for i in range(num_nodes)]
        for node in self.nodes:
            node.other_nodes = [n for n in self.nodes if n != node]
