```java
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

public class FailureDetector {
    private static final int HEARTBEAT_INTERVAL = 1000; // milliseconds
    private static final double PHI_FAILURE_THRESHOLD = 6.0;

    private ConcurrentHashMap<String, Node> nodes = new ConcurrentHashMap<>();

    public void registerNode(String nodeId) {
        nodes.putIfAbsent(nodeId, new Node());
    }

    public void sendHeartbeat(String nodeId) {
        Node node = nodes.get(nodeId);
        if (node == null) {
            throw new IllegalArgumentException("Node not registered");
        }
        node.lastHeartbeatTime = System.currentTimeMillis();
        node.heartbeatCount++;
    }

    public void detectFailures() {
        long currentTime = System.currentTimeMillis();

        for (String nodeId : nodes.keySet()) {
            Node node = nodes.get(nodeId);
            long elapsedTime = currentTime - node.lastHeartbeatTime;

            if (elapsedTime > calculateExpirationTime()) {
                // Node has expired due to no heartbeats
                markNodeAsFailed(nodeId);
            } else if (node.heartbeatCount > 0) {
                double phiValue = calculatePhi(elapsedTime, node);
                if (phiValue > PHI_FAILURE_THRESHOLD) {
                    markNodeAsFailed(nodeId);
                }
            }
        }
    }

    private void markNodeAsFailed(String nodeId) {
        Node node = nodes.get(nodeId);
        if (!node.failed) {
            // Implement your failure handling logic here
            System.out.println("Marking node " + nodeId + " as failed");
            node.failed = true;
            // You can add a callback or notification mechanism here
        }
    }

    private double calculatePhi(long elapsedTime, Node node) {
        // Simplified phi calculation (you may want to use actual network latency statistics)
        double meanInterArrivalTime = HEARTBEAT_INTERVAL * 1.0; 
        double maxDeviation = meanInterArrivalTime * 0.5;

        if (elapsedTime <= meanInterArrivalTime) {
            return 0.0; // Node is responding as expected
        }

        double phi = (elapsedTime - meanInterArrivalTime) / maxDeviation;
        return phi;
    }

    private long calculateExpirationTime() {
        // Calculate expiration time based on heartbeat interval and network latency
        double meanInterArrivalTime = HEARTBEAT_INTERVAL * 1.0; 
        double maxDeviation = meanInterArrivalTime * 0.5;

        return (long) (2 * (HEARTBEAT_INTERVAL + meanInterArrivalTime) + maxDeviation);
    }

    private static class Node {
        volatile long lastHeartbeatTime = System.currentTimeMillis();
        volatile int heartbeatCount = 0;
        volatile boolean failed = false;
    }

    public static void main(String[] args) {
        FailureDetector detector = new FailureDetector();

        // Register nodes
        detector.registerNode("node1");
        detector.registerNode("node2");

        // Simulate heartbeats
        detector.sendHeartbeat("node1");
        try { TimeUnit.SECONDS.sleep(2); } catch (InterruptedException e) {}

        // Detect failures
        detector.detectFailures();
    }
}
```

