#include <thread>

std::atomic<int> x(0);
std::atomic<bool> y(false);

void writer() {
    x = 42;        // Store to x
    std::atomic_thread_fence(std::memory_order_release); // Fence after writing x
    y = true;       // Signal that x is ready
