    if (error != cudaSuccess) {
        std::cerr << "CUDA Error: " << cudaGetErrorString(error) << std::endl;
        exit(EXIT_FAILURE);
    }
}

int main() {
    const int N = 1024;
    float *hostData, *deviceData;

    // Allocate memory
    hostData = new float[N]();
    cudaCheckError(cudaMalloc((void **)&deviceData, N * sizeof(float)));

    // Set up stream
    cudaStream_t stream;
    cudaCheckError(cudaStreamCreate(&stream));

    // Copy data to device
    cudaCheckError(cudaMemcpyAsync(deviceData, hostData, N * sizeof(float), cudaMemcpyHostToDevice, stream));

    // Kernel launch (example: vector addition)
    dim3 threadsPerBlock(256);
    dim3 blocks(1);
    myKernel<<<blocks, threadsPerBlock, 0, stream>>>(deviceData);

    // Synchronize after kernel
    cudaCheckError(cudaStreamSynchronize(stream));

    // Copy results back
    cudaCheckError(cudaMemcpyAsync(hostData, deviceData, N * sizeof(float), cudaMemcpyDeviceToHost, stream));
    cudaCheckError(cudaStreamSynchronize(stream));  // Ensure data is ready

    // Cleanup
    delete[] hostData;
    cudaFree(deviceData);
    cudaStreamDestroy(stream);

    return 0;
}
