Now let's write the code in `src/main.rs`. Here's what we'll do:

1. Decode a PNG from bytes
2. Crop it to 100x100 pixels
3. Save the cropped image

Here's the complete implementation:

```rust
extern crate image;

use image::{ImageReader, DynamicImage, ImageFormat};
use std::fs;
use std::path::Path;

fn decode_and_crop(png_bytes: &[u8]) -> DynamicImage {
    // Decode the PNG bytes into an image
    let mut reader = match ImageReader::new(png_bytes) {
        Ok(r) => r,
        Err(e) => panic!("Error decoding image: {}", e),
    };

    let image = match reader.into_image() {
        Ok(img) => img,
        Err(e) => panic!("Error converting to dynamic image: {}", e),
    };

    // Get the dimensions
    let (width, height) = image.dimensions();
    println!("Original image size: {}x{}", width, height);

    if width < 100 || height < 100 {
        panic!("Image is too small to crop to 100x100");
    }

    // Calculate the center
    let x = (width - 100) / 2;
    let y = (height - 100) / 2;

    // Crop the image
    match image.crop(x, y, 100, 100) {
        Ok(cropped) => cropped,
        Err(e) => panic!("Error cropping image: {}", e),
    }
}

fn main() {
    // Read input PNG file
    let bytes = fs::read("input.png").expect("Failed to read input.png");

    // Decode and crop
    let cropped_image = decode_and_crop(&bytes);

    // Save the cropped image
    let output_path = Path::new("output.png");
    cropped_image.save_buffer_with_format(
        output_path,
        ImageFormat::Png,
    ).expect("Failed to save cropped image");
}
```

