Here's a minimal working example of parsing NMEA 0183 GPS sentences in Go:

```go
package main

import (
    "fmt"
    "strings"
)

// GPSTime represents the time in UTC format
type GPSTime struct {
    Hours   int
    Minutes int
    Seconds int
}

// Position contains latitude and longitude information
type Position struct {
    Latitude  float64 // Degrees (N/S)
    Longitude float64 // Degrees (E/W)
}

// RMCData represents the data from an NMEA RMC sentence
type RMCData struct {
    Time      GPSTime
    Status    string // 'A' for active, 'V' for invalid
    Position  Position
    Speed     float64   // Knots
    Course    float64   // Degrees True
}

// GGAData represents the data from an NMEA GGA sentence
type GGAData struct {
    Time      GPSTime
    Position  Position
    Altitude  float64   // Meters above mean sea level
    HDOP      float64   // Horizontal Dilution of Precision
}

// ParseNMEASentence parses a single NMEA sentence
func ParseNMEASentence(sentence string) (interface{}, error) {
    // Split the sentence into parts
    parts := strings.Split(sentence, ",")

    if len(parts) < 1 { 
        return nil, fmt.Errorf("invalid sentence format")
    }

    // Extract the talker ID and sentence type
   talkerID := parts[0][1:3]
    sentenceType := parts[0][3:]

    switch sentenceType {
    case "RMC":
        if len(parts) < 12 { 
            return nil, fmt.Errorf("invalid RMC sentence format")
        }

        rmc := &RMCData{}

        // Parse time
        timeStr := parts[1]
        if len(timeStr) >= 6 {
            rmc.Time.Hours = int(timeStr[0:2])
            rmc.Time.Minutes = int(timeStr[2:4])
            rmc.Time.Seconds = int(timeStr[4:6])
        }

        // Parse status
        rmc.Status = parts[2]

        // Parse latitude
        lat := strings.ReplaceAll(parts[3], ".", "")
        if len(lat) >= 4 {
            degrees := lat[:2]
            minutes := lat[2:]
            decMinutes, _ := fmt.Sscanf(minutes, "%f", &rmc.Position.Latitude)
            rmc.Position.Latitude = (float64(degrees)/10 + decMinutes/60)
            if parts[4] == "S" {
                rmc.Position.Latitude *= -1
            }
        }

        // Parse longitude
        lon := strings.ReplaceAll(parts[5], ".", "")
        if len(lon) >= 5 {
            degrees := lon[:3]
            minutes := lon[3:]
            decMinutes, _ := fmt.Sscanf(minutes, "%f", &rmc.Position.Longitude)
            rmc.Position.Longitude = (float64(degrees)/10 + decMinutes/60)
            if parts[6] == "W" {
                rmc.Position.Longitude *= -1
            }
        }

        // Parse speed and course
        if parts[7] != "" {
            speed, _ := fmt.Sscanf(parts[7], "%f", &rmc.Speed)
            rmc.Speed = speed
        }
        if parts[8] != "" {
            course, _ := fmt.Sscanf(parts[8], "%f", &rmc.Course)
            rmc.Course = course
        }

        return rmc, nil

    case "GGA":
        if len(parts) < 15 { 
            return nil, fmt.Errorf("invalid GGA sentence format")
        }

        gga := &GGAData{}

        // Parse time
        timeStr := parts[1]
        if len(timeStr) >= 6 {
            gga.Time.Hours = int(timeStr[0:2])
            gga.Time.Minutes = int(timeStr[2:4])
            gga.Time.Seconds = int(timeStr[4:6])
        }

        // Parse latitude
        lat := strings.ReplaceAll(parts[3], ".", "")
        if len(lat) >= 4 {
            degrees := lat[:2]
            minutes := lat[2:]
            decMinutes, _ := fmt.Sscanf(minutes, "%f", &gga.Position.Latitude)
            gga.Position.Latitude = (float64(degrees)/10 + decMinutes/60)
            if parts[4] == "S" {
                gga.Position.Latitude *= -1
            }
        }

        // Parse longitude
        lon := strings.ReplaceAll(parts[5], ".", "")
        if len(lon) >= 5 {
            degrees := lon[:3]
            minutes := lon[3:]
            decMinutes, _ := fmt.Sscanf(minutes, "%f", &gga.Position.Longitude)
            gga.Position.Longitude = (float64(degrees)/10 + decMinutes/60)
            if parts[6] == "W" {
                gga.Position.Longitude *= -1
            }
        }

        // Parse altitude and HDOP
        if parts[9] != "" {
            altitude, _ := fmt.Sscanf(parts[9], "%f", &gga.Altitude)
            gga.Altitude = altitude
        }
        if parts[12] != "" {
            hdop, _ := fmt.Sscanf(parts[12], "%f", &gga.HDOP)
            gga.HDOP = hdop
        }

        return gga, nil

    default:
        return nil, fmt.Errorf("unsupported NMEA sentence type: %s", sentenceType)
    }
}

func main() {
    // Example RMC sentence: $GPRMC,123456.00,A,3758.0000,N,12223.0000,W,0.0,0.0,250198,0,E*6C
    rmcSentence := "$GPRMC,123456.00,A,3758.0000,N,12223.0000,W,0.0,0.0,250198,0,E*6C"
    data, err := ParseNMEASentence(rmcSentence)
    if err != nil {
        fmt.Println("Error parsing sentence:", err)
        return
    }

    // Check which type we got and handle accordingly
    switch v := data.(type) {
    case *RMCData:
        fmt.Printf("Time: %02d:%02d:%02d\n", 
            v.Time.Hours, v.Time.Minutes, v.Time.Seconds)
        fmt.Printf("Status: %s\n", v.Status)
        fmt.Printf("Latitude: %.4f°\nLongitude: %.4f°\n", 
            v.Position.Latitude, v.Position.Longitude)
        fmt.Printf("Speed: %.1fknots\nCourse: %.1f°\n", 
            v.Speed, v.Course)
    case *GGAData:
        // Handle GGA data similarly
    }
}
```

