    // Read the Sketch file contents
    const sketchContent = fs.readFileSync(sketchFilePath, 'utf8');

    // Parse the JSON content (Note: Sketch files are in JSON format)
    const sketchJson = JSON.parse(sketchContent);

    // The layer tree is contained within the "pages" array
    const pages = sketchJson.pages || [];

    // Process each page to get its layers
