Here's an example Java code that parses SWIFT MT940 bank statements:

```java
import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStreamReader;

public class Mt940Parser {

    public static void main(String[] args) {
        try {
            // Read the MT940 file
            FileInputStream fis = new FileInputStream("path/to/mt940.txt");
            BufferedReader reader = new BufferedReader(new InputStreamReader(fis));

            String line;
            while ((line = reader.readLine()) != null) {
                parseLine(line);
            }
            reader.close();

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void parseLine(String line) {
        // Check if the line starts with a known tag
        if (line.startsWith("20")) {
            // Date of statement
            String date = line.substring(4).trim();
            System.out.println("Statement Date: " + date);

        } else if (line.startsWith("21")) {
            // Account number
            String accountNumber = line.substring(4).trim();
            System.out.println("Account Number: " + accountNumber);

        } else if (line.startsWith("60F")) {
            // Balance information
            String balanceInfo = line.substring(4).trim();
            System.out.println("Balance Information: " + balanceInfo);

        } else if (line.startsWith("61")) {
            // Debit transaction
            parseTransaction(line, "Debit");

        } else if (line.startsWith("62")) {
            // Credit transaction
            parseTransaction(line, "Credit");
        }
    }

    private static void parseTransaction(String line, String type) {
        String[] parts = line.split(":");

        if (parts.length >= 3) {
            String amount = parts[parts.length - 1].trim();
            String description = parts[1].trim();

            System.out.println(type + " Transaction:");
            System.out.println("Amount: " + amount);
            System.out.println("Description: " + description);
        }
    }
}
```

This example demonstrates:
1. Reading a file containing MT940 statements
2. Parsing key fields like:
   - Statement date (tag 20)
   - Account number (tag 21) 
   - Balance information (tag 60F)
   - Debit transactions (tag 61)
   - Credit transactions (tag 62)

