fn main() {
    let s = String::from("hello");

    let result = process(s);
    println!("{}", result); // Outputs "world"
}

fn process(mut s: String) -> String {
    let b = runtime_borrow_checker::borrow(&s);
    assert_eq!(*b, "hello");
    runtime_borrow_checker::return_borrow(b);

    let m = runtime_borrow_checker::borrow_mut(&mut s);
    *m = String::from("world");
    runtime_borrow_checker::return_borrow(m);

    s
}
```

This code dynamically checks borrows at runtime, allowing mutable and immutable operations as needed.

