Here's a complete implementation:

```rust
use csv_turbo::prelude::*;
use std::fs::File;
use std::io;

#[derive(Debug)]
struct User {
    id: Option<i32>,
    name: String,
    email: String,
}

impl FromRecord for User {
    fn from_record(record: &mut Record) -> Result<Self> {
        Ok(User {
            id: record.get::<i32>(0).ok(), // Optional parsing for integer
            name: record.get_string(1)?,   // Parse as String
            email: record.get_string(2)?,
        })
    }
}

fn read_csv_users(file_path: &str) -> Result<Vec<User>> {
    let file = File::open(file_path)?;

    let mut reader = ReaderBuilder::new()
        .has_headers(true)
        .from_path(file)?;

    let users: Vec<User> = reader.records()
        .map(|record| User::from_record(&mut record?))
        .collect::<Result<_>>()?;

    Ok(users)
}

fn main() -> io::Result<()> {
