## 3️⃣ Code

### 3.1 `cache.go`

```go
package main

import (
	"sync"

	"github.com/hashicorp/raft"
)

// KV is a simple in‑memory key/value store.
type KV struct {
	mu    sync.RWMutex
	store map[string][]byte
}

func NewKV() *KV {
	return &KV{store: make(map[string][]byte)}
}

// Get retrieves a value; it does not acquire the write lock because Raft guarantees ordering.
func (k *KV) Get(key string) ([]byte, bool) {
	k.mu.RLock()
	defer k.mu.RUnlock()
	val, ok := k.store[key]
	return val, ok
}

func (k *KV) Set(key string, value []byte) {
	k.mu.Lock()
	defer k.mu.Unlock()
	k.store[key] = value
}
```

### 3.2 `raftnode.go`

```go
package main

import (
	"context"
	"fmt"
	"net/http"
	"os"

	"github.com/hashicorp/raft"
	"github.com/hashicorp/raft-boltdb"
)

// FSM implements raft.FSM for the KV store.
type FSM struct{ kv *KV }

func NewFSM(kv *KV) *FSM { return &FSM{kv: kv} }

// Apply is called by Raft when a log entry is committed. It must be fast!
func (f *FSM) Apply(l *raft.Log) interface{} {
	// We only use the first byte to indicate operation:
	// 0x01 = set; payload format: key len|key|value
	if l.Type != raft.LogCommand { return nil }

	cmd := l.Data
	if len(cmd) == 0 { return nil }
	switch cmd[0] {
	case 0x01: // SET
		kv := f.kv
		keyLen := int(cmd[1])
		key := string(cmd[2 : 2+keyLen])
		val := cmd[2+keyLen:]
		kv.Set(key, val)
	default:
	}
	return nil
}

func (f *FSM) Snapshot() (raft.FSMSnapshot, error) { return &fsmSnapshot{f.kv}, nil }

func (f *FSM) Restore(rc io.ReadCloser) error {
	s := &fsmSnapshot{f.kv}
	return s.Restore(rc)
}

// fsmSnapshot is a simple snapshot representation.
type fsmSnapshot struct{ kv *KV }

func (s *fsmSnapshot) Persist(sink raft.SnapshotSink) error {
	s.kv.mu.RLock()
	defer s.kv.mu.RUnlock()

	// We serialize as: key len|key|value, one after another.
	for k, v := range s.kv.store {
		if err := sink.Write([]byte{0x01}); err != nil { return err }
		if err := sink.Write([]byte{k}); err != nil { return err } // key length is a single byte
		if err := sink.Write([]byte(k)); err != nil { return err }
		if _, err := sink.Write(v); err != nil { return err }
	}
	return sink.Close()
}

func (s *fsmSnapshot) Restore(rc io.ReadCloser) error {
	// Not implemented for brevity; restore works from the log.
	return nil
}

// Node holds Raft and HTTP server plumbing.
type Node struct {
	addr string
	id   string
	kv   *KV

	rf *raft.Raft // Hashicorp Raft instance
}

func NewNode(id, addr string) (*Node, error) {
	config := raft.DefaultConfig()
	config.LocalID = raft.ServerID(id)

	fsm := NewFSM(NewKV())
	snapStore, err := raft.NewInmemSnapshotStore()
	if err != nil { return nil, err }

	logStore, _ := boltdb.NewBoltStore(fmt.Sprintf("%s-log.bolt", id))
	stableStore, _ := boltdb.NewBoltStore(fmt.Sprintf("%s-stable.bolt", id))

	// Set up Raft's communication: we use the HTTP server below.
	address, err := net.ResolveTCPAddr("tcp", addr)
	if err != nil { return nil, err }

	rf, err := raft.NewRaft(config, fsm, logStore, stableStore, snapStore,
		raft.NewTCPTransport(addr, address, 3, 10*time.Second, os.Stderr))
	if err != nil { return nil, err }

	return &Node{
		addr: addr,
		id:   id,
		kv:   fsm.kv,
		rf:   rf,
	}, nil
}

// StartHTTP starts a very small API for PUT/GET.
func (n *Node) StartHTTP(ctx context.Context) {
	mux := http.NewServeMux()
	mux.HandleFunc("/get", n.handleGet)
	mux.HandleFunc("/put", n.handlePut)

	server := &http.Server{Addr: n.addr, Handler: mux}
	go func() { _ = server.ListenAndServe() }()
	<-ctx.Done()
	server.Shutdown(ctx)
}

func (n *Node) handleGet(w http.ResponseWriter, r *http.Request) {
	key := r.URL.Query().Get("k")
	if key == "" {
		http.Error(w, "missing key", http.StatusBadRequest); return
	}
	val, ok := n.kv.Get(key)
	if !ok { http.NotFound(w, r); return }
	w.Write(val)
}

func (n *Node) handlePut(w http.ResponseWriter, r *http.Request) {
	key := r.URL.Query().Get("k")
	if key == "" {
		http.Error(w, "missing key", http.StatusBadRequest); return
	}
	val, err := io.ReadAll(r.Body)
	if err != nil { http.Error(w, err.Error(), http.StatusInternalServerError); return }

	cmd := make([]byte, 1+len(key)+len(val))
	cmd[0] = 0x01 // SET
	cmd[1] = byte(len(key)) // assumes <256 length; tweak if you need longer keys
	copy(cmd[2:], key)
	copy(cmd[2+len(key):], val)

	// Propose to Raft. This will block until the entry is committed.
	future := n.rf.Propose(context.Background(), cmd)
	if err := future.Error(); err != nil {
		http.Error(w, fmt.Sprintf("raft propose failed: %v", err), http.StatusInternalServerError); return
	}
	w.WriteHeader(http.StatusOK)
}
```

> **Why this is “no metadata”?**  
> The client never tells the server anything about a session or version; it only sends key/value. All ordering guarantees are enforced by Raft, not by custom tags.

### 3.3 `main.go`

```go
package main

import (
	"context"
	"fmt"
	"log"
	"net"
	"os"
	"strconv"
	"time"

	"github.com/hashicorp/raft"
)

func main() {
	if len(os.Args) < 4 {
		fmt.Fprintf(os.Stderr, "Usage: %s <id> <addr> <is_leader>\n", os.Args[0])
		os.Exit(1)
	}

	id := os.Args[1]
	addr := os.Args[2]           // e.g. ":5001"
	isLeader, _ := strconv.ParseBool(os.Args[3])

	node, err := NewNode(id, addr)
	if err != nil { log.Fatalf("node init: %v", err) }

	// Bootstrap cluster on first node; otherwise join an existing leader.
	if isLeader {
		config := raft.Configuration{
			Servers: []raft.Server{{
				ID:      raft.ServerID(id),
				Suffrage: raft.Voter,
				Address: net.JoinHostPort("127.0.0.1", addr[1:]), // strip ':'
			}},
		}
		node.rf.BootstrapCluster(config)
	} else {
		// For demo we simply wait a bit and then add ourselves as a follower.
		time.Sleep(3 * time.Second) // in real life, fetch the leader address
		config := raft.Configuration{
			Servers: []raft.Server{{
				ID:      raft.ServerID(id),
				Suffrage: raft.Voter,
				Address: net.JoinHostPort("127.0.0.1", addr[1:]),
			}},
		}
		node.rf.AddVoter(raft.ServerID(id), node.rf.LocalID(), config)
	}

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go node.StartHTTP(ctx)

	// Simple keep‑alive loop to let the process run
	for {
		time.Sleep(10 * time.Second)
	}
}
```

