/* aes.h – Public interface for the minimal AES implementation.
 * Author: OpenAI ChatGPT
 * Licence: CC0 (public domain) – feel free to adapt or use in any project. */

#ifndef AES_H
#define AES_H

#include <stdint.h>
#include <stddef.h>

/* The number of 32‑bit words in a key for AES‑128, AES‑192 and AES‑256. */
enum {
    AES_KEY_SIZE_128 = 16,
    AES_KEY_SIZE_192 = 24,
    AES_KEY_SIZE_256 = 32
};

/* The number of rounds (10, 12 or 14) for the respective key sizes. */
enum {
    AES_ROUNDS_128 = 10,
    AES_ROUNDS_192 = 12,
    AES_ROUNDS_256 = 14
};

/* Maximum key size accepted by this implementation (32 bytes). */
#define AES_MAX_KEY_SIZE      32

/* Structure holding pre‑computed round keys. */
typedef struct {
    uint8_t rounds;                /* Number of rounds for the selected key size */
    uint32_t round_keys[60];       /* Expanded key: max 14*4 + 4 = 60 words (AES‑256) */
} aes_key_schedule;

/**
 * Pre‑compute the AES key schedule from a raw key.
 *
 * @param out      Output schedule structure; must be pre‑allocated.
 * @param key      Pointer to raw key bytes. Must point to
 *                 `key_len` valid bytes.
 * @param key_len  Length of the key in bytes (16, 24 or 32).
 * @return 0 on success, non‑zero otherwise.
 */
int aes_key_setup(aes_key_schedule *out,
                  const uint8_t *key,
                  size_t key_len);

/**
 * Encrypt a single 16‑byte block in ECB mode using the provided schedule.
 *
 * @param out      Destination buffer; must be at least 16 bytes long.
 * @param in       Source plaintext block; must be exactly 16 bytes.
 * @param sched    Pre‑computed round keys from aes_key_setup().
 */
void aes_encrypt_block(const uint8_t *in,
                       uint8_t *out,
                       const aes_key_schedule *sched);

#endif /* AES_H */
```

