/* ------------------------------------------------------------------ */
/* 2) Rcon – the round constants used in key expansion. */
static const uint32_t r_con[10] = {
    0x01000000, 0x02000000, 0x04000000, 0x08000000,
    0x10000000, 0x20000000, 0x40000000, 0x80000000,
    0x1B000000, 0x36000000
};

/* ------------------------------------------------------------------ */
/* Utility: rotate a word left by one byte. */
static inline uint32_t rot_word(uint32_t w)
{
    return (w << 8) | (w >> 24);
}

/* Utility: apply the S‑box to each of the four bytes in a word. */
static inline uint32_t sub_word(uint32_t w)
{
    return ((uint32_t)s_box[(w >> 24) & 0xFF] << 24) |
           ((uint32_t)s_box[(w >> 16) & 0xFF] << 16) |
           ((uint32_t)s_box[(w >> 8 ) & 0xFF] << 8)  |
           (uint32_t)s_box[w & 0xFF];
}

/* ------------------------------------------------------------------ */
/* 3) Key expansion */
int aes_key_setup(aes_key_schedule *out,
                  const uint8_t *key, size_t key_len)
{
    assert(out);
    if (!key || (key_len != AES_KEY_SIZE_128 &&
                 key_len != AES_KEY_SIZE_192 &&
                 key_len != AES_KEY_SIZE_256)) {
        return -1;  /* invalid key length */
    }

    const uint32_t Nb = 4;               // block size in words
    const uint32_t Nk = (uint32_t)key_len / 4;
    const uint32_t Nr = (Nk == 8 ? AES_ROUNDS_192 :
                         Nk == 12 ? AES_ROUNDS_256 : AES_ROUNDS_128);

    out->rounds = (uint8_t)Nr;

    /* --- Copy the original key into the first Nk words */
    for (uint32_t i = 0; i < Nk; ++i) {
        out->round_keys[i] =
            ((uint32_t)key[4*i]   << 24) |
            ((uint32_t)key[4*i+1] << 16) |
            ((uint32_t)key[4*i+2] << 8 ) |
             (uint32_t)key[4*i+3];
    }

    /* --- Generate the remaining words */
    for (uint32_t i = Nk; i < Nb * (Nr + 1); ++i) {
        uint32_t temp = out->round_keys[i - 1];

        if (i % Nk == 0) {
            temp = sub_word(rot_word(temp)) ^ r_con[(i / Nk) - 1];
        } else if (Nk > 6 && i % Nk == 4) {
            temp = sub_word(temp);
        }

        out->round_keys[i] = out->round_keys[i - Nk] ^ temp;
    }
    return 0;   // success
}

/* ------------------------------------------------------------------ */
/* 4) MixColumns – GF(2^8) multiplication with the fixed matrix. */

/* Multiply by {02} in GF(2^8). */
static inline uint8_t mul_by_02(uint8_t x)
{
    return (x & 0x80 ? (x << 1) ^ 0x1b : x << 1);
}

/* Multiply by {03} = {02}+{01}. */
static inline uint8_t mul_by_03(uint8_t x)
{
    return mul_by_02(x) ^ x;
}

static void mix_columns(uint8_t *state)
{
    for (int c = 0; c < 4; ++c) {
        const int i = 4*c;
        uint8_t s0 = state[i];
        uint8_t s1 = state[i+1];
        uint8_t s2 = state[i+2];
        uint8_t s3 = state[i+3];

        state[i]   = mul_by_02(s0) ^ mul_by_03(s1) ^ s2 ^ s3;
        state[i+1] = s0 ^ mul_by_02(s1) ^ mul_by_03(s2) ^ s3;
        state[i+2] = s0 ^ s1 ^ mul_by_02(s2) ^ mul_by_03(s3);
        state[i+3] = mul_by_03(s0) ^ s1 ^ s2 ^ mul_by_02(s3);
    }
}

/* ------------------------------------------------------------------ */
/* 5) AddRoundKey – XOR the round key into the state. */
static inline void add_round_key(uint8_t *state, const uint32_t *round_key)
{
    /* AES is column‑major; each word maps to a column of 4 bytes. */
    for (int i = 0; i < 4; ++i) {
        uint32_t rk = round_key[i];
        state[4*i]   ^= (rk >> 24) & 0xFF;
        state[4*i+1] ^= (rk >> 16) & 0xFF;
        state[4*i+2] ^= (rk >> 8 ) & 0xFF;
        state[4*i+3] ^=  rk        & 0xFF;
    }
}

/* ------------------------------------------------------------------ */
/* 6) SubBytes – Apply the S‑box to every byte of the state. */
static inline void sub_bytes(uint8_t *state)
{
    for (int i = 0; i < 16; ++i) {
        state[i] = s_box[state[i]];
    }
}

/* ------------------------------------------------------------------ */
/* 7) ShiftRows – cyclic left shift of each row by its index. */
static inline void shift_rows(uint8_t *state)
{
    /* Row 1: shift left by 1 */
    uint8_t t;
    t = state[ 1];
    state[ 1] = state[ 5];
    state[ 5] = state[ 9];
    state[ 9] = state[13];
    state[13] = t;

    /* Row 2: shift left by 2 */
    t = state[ 2];
    state[ 2] = state[10];
    state[10] = t;
    t = state[ 6];
    state[ 6] = state[14];
    state[14] = t;

    /* Row 3: shift left by 3 (right by 1) */
    t = state[15];
    state[15] = state[11];
    state[11] = state[ 7];
    state[ 7] = state[ 3];
    state[ 3] = t;
}

/* ------------------------------------------------------------------ */
/* 8) Full encryption of a single block. */
void aes_encrypt_block(const uint8_t *in,
                       uint8_t *out,
                       const aes_key_schedule *sched)
{
    assert(in && out && sched);

    /* Copy plaintext into state (column‑major). */
    for (int i = 0; i < 16; ++i) {
        out[i] = in[i];
    }

    /* Initial AddRoundKey. */
    add_round_key(out, &sched->round_keys[0]);

    /* Main rounds – Nr‑1 times */
    for (uint32_t round = 1; round < sched->rounds; ++round) {
        sub_bytes(out);
        shift_rows(out);
        mix_columns(out);
        add_round_key(out,
                      &sched->round_keys[round * 4]);   /* 4 words per round */
    }

    /* Final round – no MixColumns. */
    sub_bytes(out);
    shift_rows(out);
    add_round_key(out, &sched->round_keys[sched->rounds * 4]);
}
