```go
// Node represents a Raft server.
type Node struct {
    id          string   // human readable ID
    peers       []string // addresses of all nodes in the cluster

    mu          sync.Mutex        // protects everything below
    state       State              // Follower | Candidate | Leader
    term        int64              // current term
    votedFor    string             // candidate voted for in this term
    log         []*Entry           // replicated log (index 0 is a dummy entry)
    commitIndex int64              // index of highest log entry known to be committed
    lastApplied int64              // index of highest log entry applied to state machine

    nextIndex   map[string]int64   // for each follower, the next log index to send
    matchIndex  map[string]int64   // for each follower, highest replicated index

    sm          *StateMachine      // our key/value store

    rpcServer   *rpc.Server
    conn        net.Listener

    hbCh        chan struct{}     // heartbeat tick channel
    stopCh      chan struct{}
}
