## 4. Core algorithms

### 4.1 Leader election (simplified)

```go
func (n *Node) runElection() {
    n.mu.Lock()
    n.state = Candidate
    n.term++
    term := n.term
    n.votedFor = n.id
    votes := 1
    n.mu.Unlock()

    var wg sync.WaitGroup
    for _, p := range n.peers {
        wg.Add(1)
        go func(peer string) {
            defer wg.Done()
            args := RequestVoteArgs{
                Term:        term,
                CandidateID: n.id,
                LastLogIndex: int64(len(n.log)-1),
                LastLogTerm:  n.log[len(n.log)-1].Term,
            }
            var reply RequestVoteReply
            if err := rpcCall(peer, "Node.RequestVote", args, &reply); err != nil {
                return
            }
            n.mu.Lock()
            defer n.mu.Unlock()
            if reply.Term > n.term {
                n.term = reply.Term
                n.state = Follower
                n.votedFor = ""
                return
            }
            if reply.VoteGranted {
                votes++
            }
        }(p)
    }

    wg.Wait()

    n.mu.Lock()
    defer n.mu.Unlock()
    if n.state != Candidate || term != n.term { // lost election or out‑of‑date
        return
    }
    if votes*2 > len(n.peers)+1 {
        n.becomeLeader()
    } else {
        // wait for next timeout to retry
    }
}
```

### 4.2 Become leader

```go
func (n *Node) becomeLeader() {
    n.state = Leader
    for _, p := range n.peers {
        n.nextIndex[p] = int64(len(n.log))
        n.matchIndex[p] = 0
    }
    go n.sendHeartbeats()
}
```

### 4.3 Send heartbeats / replicate logs

```go
func (n *Node) sendHeartbeats() {
    ticker := time.NewTicker(heartbeatInterval)
    defer ticker.Stop()

    for {
        select {
        case <-ticker.C:
            n.mu.Lock()
            term := n.term
            commit := n.commitIndex
            // send empty AppendEntries as heartbeat to each follower
            for _, p := range n.peers {
                go func(peer string) {
                    args := AppendEntriesArgs{
                        Term:        term,
                        LeaderID:    n.id,
                        PrevLogIndex: int64(len(n.log)-1),
                        PrevLogTerm:  n.log[len(n.log)-1].Term,
                        Entries:     nil,
                        LeaderCommit: commit,
                    }
                    var reply AppendEntriesReply
                    rpcCall(peer, "Node.AppendEntries", args, &reply)
                }(p)
            }
        case <-n.stopCh:
            return
        }
    }
}
```

### 4.4 Handling client writes

```go
func (n *Node) Write(cmd []byte) error {
    n.mu.Lock()
    if n.state != Leader {
        // redirect to known leader (simple: first peer that responds with success)
        for _, p := range n.peers {
            var reply AppendEntriesReply
            args := AppendEntriesArgs{Term: n.term, LeaderID: n.id}
            err := rpcCall(p, "Node.WriteCommand", cmd, &reply) // we’ll expose this RPC separately
            if err == nil && reply.Success {
                n.mu.Unlock()
                return nil
            }
        }
        n.mu.Unlock()
        return errors.New("no leader available")
    }

    // Append to local log
    entry := &Entry{Term: n.term, Index: int64(len(n.log)), Cmd: cmd}
    n.log = append(n.log, entry)

    // Replicate immediately (in real Raft we could batch but keep it simple)
    var wg sync.WaitGroup
    successCount := 1 // leader itself counts

    for _, p := range n.peers {
        wg.Add(1)
        go func(peer string) {
            defer wg.Done()
            args := AppendEntriesArgs{
                Term:        n.term,
                LeaderID:    n.id,
                PrevLogIndex: entry.Index-1,
                PrevLogTerm:  n.log[entry.Index-1].Term,
                Entries:     []*Entry{entry},
                LeaderCommit: n.commitIndex,
            }
            var reply AppendEntriesReply
            if err := rpcCall(peer, "Node.AppendEntries", args, &reply); err == nil && reply.Success {
                n.mu.Lock()
                successCount++
                n.matchIndex[peer] = entry.Index
                n.nextIndex[peer] = entry.Index + 1
                n.mu.Unlock()
            }
        }(p)
    }

    wg.Wait()

    if successCount*2 <= len(n.peers)+1 {
        n.mu.Unlock()
        return errors.New("failed to reach majority")
    }

    // Commit the entry
    n.commitIndex = entry.Index
    n.applyLogEntries()  // apply to state machine
    n.mu.Unlock()
    return nil
}
```

### 4.5 Applying committed entries

```go
func (n *Node) applyLogEntries() {
    for n.lastApplied < n.commitIndex {
        n.lastApplied++
        cmd := n.log[n.lastApplied].Cmd
        // assume our command is “SET key value” text format for demo
        parts := strings.Split(string(cmd), " ")
        if len(parts) >= 3 && parts[0] == "SET" {
            n.sm.mu.Lock()
            n.sm.store[parts[1]] = parts[2]
            n.sm.mu.Unlock()
        }
    }
}
```

### 4.6 Read RPC

```go
func (n *Node) Read(key string, reply *string) error {
    n.mu.Lock()
    if n.state != Leader {
        // redirect to leader
        for _, p := range n.peers {
            var r string
            err := rpcCall(p, "Node.Read", key, &r)
            if err == nil {
                *reply = r
                n.mu.Unlock()
                return nil
            }
        }
        n.mu.Unlock()
        return errors.New("no leader")
    }
    n.sm.mu.RLock()
    val, ok := n.sm.store[key]
    n.sm.mu.RUnlock()
    if !ok {
        *reply = "" // or “<nil>”
    } else {
        *reply = val
    }
    n.mu.Unlock()
    return nil
}
```

## 5. Failure handling

1. **Heartbeat timeout** – a follower that misses `heartbeatInterval` (say 150 ms) becomes candidate and starts an election.
2. **Leader crash** – all followers time out, start elections; the node that wins obtains the highest term.
3. **Follower crash** – the leader continues to replicate logs; no client writes are affected.
4. **Split brain / stale leader** – the “term” field ensures only the newest leader can accept writes: if a follower’s `AppendEntries` has a lower term, it rejects it, and the follower will step down.

The election logic guarantees that *exactly one* node is leader at any time (as long as no partition contains >half of nodes). Reads always go to the current leader, so they are **linearizable**: every read sees all writes that were committed before it started.

