## 2. Consumer – manual commits & idempotency store

The consumer does **not** commit its offset until it has:

1. Checked a deduplication table (here Redis) that this event was not processed before.
2. Performed the business work and persisted any side‑effects.
3. Updated the deduplication table with the event key.

If anything in those steps throws, we let the exception propagate – the container will **not** ack the offset → Kafka re‑delivers the message.  Duplicate events are recognised by Redis and skipped without performing the business logic again.

```java
// src/main/java/com/example/kafka/consumer/KafkaConsumerConfig.java
package com.example.kafka.consumer;

import java.util.HashMap;
import java.util.Map;
import org.apache.kafka.clients.consumer.*;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.kafka.config.ConcurrentKafkaListenerContainerFactory;
import org.springframework.kafka.core.*;

@Configuration
public class KafkaConsumerConfig {

    @Bean
    public ConsumerFactory<String, String> consumerFactory() {
        Map<String,Object> props = new HashMap<>();
        props.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
        props.put(ConsumerConfig.GROUP_ID_CONFIG, "group1");
        props.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG,
                org.apache.kafka.common.serialization.StringDeserializer.class);
        props.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG,
                org.apache.kafka.common.serialization.StringDeserializer.class);

        /* -----------  Manual offset commit  ----------------- */
        // We want to control *when* the offset is committed.
        props.put(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG, false);

        return new DefaultKafkaConsumerFactory<>(props);
    }

    @Bean
    public ConcurrentKafkaListenerContainerFactory<String, String> kafkaListenerContainerFactory() {
        ConcurrentKafkaListenerContainerFactory<String, String> factory =
                new ConcurrentKafkaListenerContainerFactory<>();
        factory.setConsumerFactory(consumerFactory());
        // Manual commit – we will call ack.acknowledge()
        factory.getContainerProperties().setAckMode(
                org.springframework.kafka.listener.ContainerProperties.AckMode.MANUAL_IMMEDIATE);
        return factory;
    }
}
```

```java
// src/main/java/com/example/kafka/consumer/IdempotentListener.java
package com.example.kafka.consumer;

import io.lettuce.core.api.StatefulRedisConnection;
import io.lettuce.core.api.sync.RedisCommands;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.slf4j.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.messaging.handler.annotation.Payload;
import org.springframework.stereotype.Component;
import org.springframework.kafka.support.Acknowledgment;

@Component
public class IdempotentListener {

    private static final Logger log = LoggerFactory.getLogger(IdempotentListener.class);

    // Redis used as deduplication store
    @Autowired
    StatefulRedisConnection<String, String> redisConn;

    /**
     * Simple idempotency check – a message key is considered unique.
     * In production you might use a hash of the payload or an explicit ID field.
     */
    private boolean alreadyProcessed(String key) {
        RedisCommands<String,String> sync = redisConn.sync();
        return sync.exists(key) == 1;
    }

    private void markAsProcessed(String key) {
        RedisCommands<String,String> sync = redisConn.sync();
        // store a dummy value; optionally set an expiry if you want to
        // keep the store from growing forever.
        sync.setex(key, 24 * 60 * 60, "1");
    }

    /** Example business logic – e.g. write to DB */
    private void processBusinessLogic(String payload) throws Exception {
        // Simulate a risky operation that may fail
        if (payload.contains("FAIL")) throw new RuntimeException("Simulated failure");
        log.info("Processed: {}", payload);
        /* ... persist data, call downstream services ... */
    }

    @KafkaListener(topics = "input-topic", groupId = "group1")
    public void listen(@Payload String payload,
                       @org.apache.kafka.common.annotation.Header(org.springframework.kafka.support.KafkaHeaders.RECEIVED_MESSAGE_KEY) String key,
                       Acknowledgment ack) {

        log.info("Received msg[{}] -> {}", key, payload);

        try {
            // 1️⃣ dedup check
            if (alreadyProcessed(key)) {
                log.debug("Duplicate detected; skipping processing");
                ack.acknowledge();           // still commit offset so we don't keep re‑consuming it
                return;
            }

            // 2️⃣ business work
            processBusinessLogic(payload);

            // 3️⃣ mark as processed – must happen *before* acknowledging
            markAsProcessed(key);

            // 4️⃣ commit offset (ACK)
            ack.acknowledge();
        } catch (Exception e) {
            log.error("Processing failed for key {}: {}", key, e.getMessage());
            /* ── Failure handling ──────────────────────── */
            // The exception propagates – the container will NOT ack.
            // Kafka will re‑deliver the message after `session.timeout.ms`.
            throw new RuntimeException(e);
        }
    }
}
```

