class Network {
public:
    explicit Network(int n) : inboxes_(n)
    {
        for (auto &mb: inboxes_)
            mb = std::make_unique<Mailbox>();
    }

    std::vector<Mailbox*> inboxes() const
    {
        std::vector<Mailbox*> ptrs;
        for (auto& m: inboxes_) ptrs.push_back(m.get());
        return ptrs;
    }
private:
