## 6. Main program – spin up a small PBFT group

```cpp
int main()
{
    constexpr int N = 4;               // n = 3f + 1 → f = 1
    constexpr int F = (N - 1) / 3;     // = 1

    Network net(N);
    std::vector<Mailbox*> inboxes = net.inboxes();

    // Create nodes
    std::vector<std::unique_ptr<Node>> nodes;
    for (int i=0; i<N; ++i)
        nodes.emplace_back(std::make_unique<Node>(i, N, F, inboxes));

    // Launch each node in its own thread
    std::vector<std::thread> ths;
    for (auto &node: nodes)
        ths.emplace_back(&Node::run, node.get());

    // Let them run a bit
    std::this_thread::sleep_for(10s);

    // Stop all nodes
    for (auto &node: nodes) node->stop();
    for (auto &t: ths) t.join();

    return 0;
}
```

