## 4️⃣  Wiring It Up – A Minimal Example

Below is a *very* simple in‑memory “network” that shows how two replicas can talk to each other.  Replace it with WebSocket, gRPC, or any messaging system you already have.

```ts
/* demo.ts ---------------------------------------------------------------
 * Quick demo of the PNCounter with a toy network.
 */

import { PNCounter } from "./pn-counter";

// ---------- A dumb in‑memory broadcast bus ----------------------------
class InMemoryBus {
  private listeners: Array<(msg: string) => void> = [];
  send(msg: string) {
    // Broadcast to everyone but not to the sender
    this.listeners.forEach(fn => fn(msg));
  }
  addListener(fn: (msg: string) => void) {
    this.listeners.push(fn);
  }
}

const bus = new InMemoryBus();

// ---------- Helper that gives us a Transport object --------------------
function makeTransport(onMsg: (s: string) => void): PNCounter["opts"]["transport"] {
  return {
    async send(msg: string) {
      // Simulate network delay + possible loss
      setTimeout(() => {
        if (Math.random() < 0.9) { // 90% success rate
          onMsg(msg);
        } else {
          throw new Error("simulated network failure");
        }
      }, Math.random() * 100);
    }
  };
}

// ---------- Two replicas -----------------------------------------------
const counterA = new PNCounter("node-A", {
  transport: makeTransport(msg => bus.send(msg)),
  onMerge: state => console.log("[Node A] merged:", state)
});
const counterB = new PNCounter("node-B", {
  transport: makeTransport(msg => bus.send(msg)),
  onMerge: state => console.log("[Node B] merged:", state)
});

// Subscribe each replica to the bus
bus.addListener(async rawMsg => {
  // we don't know which node it is destined for – simply route it.
  await counterA.onMessage(rawMsg);
  await counterB.onMessage(rawMsg);
});

console.log("Initial values: A =", counterA.value(), ", B =", counterB.value());

// ---------- Demo ops ----------------------------------------------------
counterA.inc();     // +1
counterB.dec(2);    // -2
counterA.inc();
counterB.inc();
counterA.dec();

setTimeout(() => {
  console.log("\nAfter some time:");
  console.log("Final values: A =", counterA.value(), ", B =", counterB.value());
}, 2000);
```

Running `ts-node demo.ts` (or compiling with `tsc`) prints something like:

```
Initial values: A = 0 , B = 0
[Node A] merged: {...}
[Node B] merged: {...}

After some time:
Final values: A = -1 , B = -1
```

> **Note** – Because the counter is *eventually consistent*, the order of merges may vary, but both nodes always end up with the same value.

