### Quick‑start

```bash
# Install the library (requires Node ≥ 12)
npm i sharp
```

---

#### Example – resize + auto‑crop to a fixed 400×300 square

```js
// resizeCrop.js
const sharp = require('sharp');
const fs   = require('fs').promises;
const path = require('path');

/**
 * Resize an image to the given dimensions and crop it automatically.
 *
 * @param {string} inputPath  Path of the source image (JPEG, PNG, …)
 * @param {string} outputPath Path where the transformed image will be written
 * @param {number} width      Target width in pixels
 * @param {number} height     Target height in pixels
 */
async function resizeAndCrop(inputPath, outputPath, width = 400, height = 300) {
  try {
    // Sharp builds a pipeline of operations.  The input file is read lazily,
    // so nothing expensive happens until the .toFile() step.
    await sharp(inputPath)
      // Resize while keeping the original aspect ratio *and* fill the
      // target box. `fit: 'cover'` means "stretch/crop to cover the entire
      // area, discarding any excess".  Position defaults to 'center'.
      .resize({
        width,
        height,
        fit: 'cover',    // <- Auto‑crop so the output is exactly width×height
        position: sharp.strategy.entropy // optional – keeps “important” parts
      })
      // Optional: convert to JPEG / PNG, set quality, etc.
      .toFile(outputPath);

    console.log(`✓ Resized & cropped image written to ${outputPath}`);
  } catch (err) {
    console.error('❌ Error processing image:', err);
  }
}

// Example usage from the command line:
// node resizeCrop.js input.jpg output.jpg
if (require.main === module) {
  const [, , inFile, outFile] = process.argv;
  if (!inFile || !outFile) {
    console.log('Usage: node resizeCrop.js <inputPath> <outputPath>');
    process.exit(1);
  }
  resizeAndCrop(inFile, outFile);
}
```

**Run it**

```bash
node resizeCrop.js photo.jpg thumb.jpg
# → ✓ Resized & cropped image written to thumb.jpg
```

---

### How the code works

| Step | What happens |
|------|--------------|
| `sharp(inputPath)` | Creates a Sharp instance that lazily reads the source file. |
| `.resize({ width, height, fit: 'cover' })` | The `resize()` call **preserves the aspect ratio** but forces the output to fill *both* dimensions (`width × height`). Any surplus beyond the target box is automatically cropped out, centering (by default) on the image. |
| `.toFile(outputPath)` | Triggers execution of the pipeline: Sharp reads the source file, applies the resize/crop transform in a single pass using libvips, and writes the result to `outputPath`. No intermediate files or buffers are written to disk – everything stays in memory (fast & low‑memory). |
| Error handling | If anything goes wrong (missing file, unsupported format, etc.) the promise rejects and we log the error. |

**Key points**

* `fit: 'cover'` is the trick that gives you *auto‑crop*: Sharp calculates the best way to fill the output rectangle while keeping the aspect ratio.
* You can tweak the crop area with `position:` (e.g., `'center'`, `'entropy'`, or coordinates).
* Sharp uses libvips under the hood, so it’s very fast even for large images.

Feel free to plug this into your server code, CLI tool, or any build pipeline!

Here’s a minimal, ready‑to‑run example that shows how to deep‑clone a nested object with **lodash** (`npm install lodash` first).

```js
// 1️⃣  Import the cloneDeep helper from lodash
import cloneDeep from 'lodash/cloneDeep';   // (Node >=14 with ES modules)
              // or: const cloneDeep = require('lodash/cloneDeep'); // CommonJS

// 2️⃣  A nested object you want to copy
const original = {
  user: {
    name: 'Alice',
    address: { city: 'Wonderland', zip: 12345 }
  },
  hobbies: ['reading', { type: 'sports', sport: 'chess' }]
};

// 3️⃣  Perform a deep clone
const cloned = cloneDeep(original);

// 4️⃣  Mutate the clone – original stays untouched
cloned.user.name   = 'Bob';
cloned.hobbies[1].sport = 'soccer';

