## Pure‑Go minimal manual parser

If you don’t want to pull in an external dependency you can do the heavy lifting yourself – the code below only handles `RMC` sentences but shows how checksum validation and the *DDMM.MMMM* latitude/longitude format are parsed.

```go
package main

import (
	"bufio"
	"fmt"
	"log"
	"os"
	"strconv"
	"strings"
)

// Convert "4807.038,N" into decimal degrees 48.1173
func parseLatLon(raw string, dir string) (float64, error) {
	if raw == "" || dir == "" {
		return 0, fmt.Errorf("empty value")
	}
	deg, err := strconv.ParseFloat(raw[:len(raw)-7], 64)
	if err != nil {
		return 0, err
	}
	min := raw[len(raw)-7:]

	val, err := strconv.ParseFloat(min, 64)
	if err != nil {
		return 0, err
	}

	degrees := deg + val/60.0
	if dir == "S" || dir == "W" {
		degrees = -degrees
	}
	return degrees, nil
}

// Verify NMEA checksum – returns true if ok.
func verifyChecksum(sentence string) bool {
	// sentence must start with '$' and contain '*'
	i := strings.Index(sentence, "*")
	if i < 0 || !strings.HasPrefix(sentence, "$") {
		return false
	}
	checksumStr := sentence[i+1 : i+3]
	expected, err := strconv.ParseUint(checksumStr, 16, 8)
	if err != nil {
		return false
	}

	var checksum byte = 0
	for _, b := range []byte(sentence[1:i]) { // skip '$'
		checksum ^= b
	}
	return checksum == byte(expected)
}

func parseRMC(line string) (time, lat, lon string, err error) {
	if !verifyChecksum(line) {
		return "", "", "", fmt.Errorf("bad checksum")
	}
	fields := strings.Split(strings.TrimSuffix(line[1:len(line)-3], ""), ",") // drop $ and *XX

	if fields[0] != "GPRMC" || len(fields) < 12 {
		return "", "", "", fmt.Errorf("not an RMC sentence or too few fields")
	}

	time = fields[1]
	latVal, latDir := fields[3], fields[4]
	lonVal, lonDir := fields[5], fields[6]

	latFloat, err := parseLatLon(latVal, latDir)
	if err != nil {
		return "", "", "", err
	}
	lonFloat, err := parseLatLon(lonVal, lonDir)
	if err != nil {
		return "", "", "", err
	}

	return time, fmt.Sprintf("%.6f", latFloat), fmt.Sprintf("%.6f", lonFloat), nil
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	fmt.Println("Enter RMC sentences:")

	for scanner.Scan() {
		line := scanner.Text()
		if t, lat, lon, err := parseRMC(line); err == nil {
			fmt.Printf("Time: %s  Lat: %s  Lon: %s\n", t, lat, lon)
		} else {
			log.Printf("skip (%v): %s", err, line)
		}
	}

	if err := scanner.Err(); err != nil {
		log.Fatal(err)
	}
}
```

