## 7. Browser‑ready snippet

If you want to sign in a browser, you only need the WebCrypto version of `jwt-ed25519-turbo` (the same npm package works).

```html
<script type="module">
import { JwtEdDSATurbo } from 'https://cdn.jsdelivr.net/npm/jwt-ed25519-turbo/+esm';

const signer = new JwtEdDSATurbo();

async function createKeyPair() {
  const pair = await crypto.subtle.generateKey(
    { name: 'NODE-ED25519', namedCurve: 'Ed25519' },
    true,
    ['sign', 'verify']
  );
  const privateJwk = await crypto.subtle.exportKey('jwk', pair.privateKey);
  const publicJwk  = await crypto.subtle.exportKey('jwk', pair.publicKey);
  return { privateJwk, publicJwk };
}

(async () => {
  const { privateJwk } = await createKeyPair();
  const token = signer.sign({ sub: 'user-1234' }, {}, privateJwk);
  console.log(token);
})();
</script>
```

> The same `JwtEdDSATurbo.verify()` works on the server or in a browser.

