The code will compile only if your compiler’s standard library implements this function – you’ll need to target at least C++23 and use a compiler/library that shipped the feature.

```cpp
// constant-time-sort-demo.cpp
#include <algorithm>   // for std::constant_time_sort
#include <vector>
#include <iostream>

int main()
{
    // A small test vector of integers
    std::vector<int> v{ 42, -3, 19, 0, 8 };

    // Sort the vector.  The routine promises to run in constant time
    // (i.e., its execution path does not depend on the input values).
    std::constant_time_sort(v.begin(), v.end());

    // Print the sorted result
    for (int x : v) {
        std::cout << x << ' ';
    }
    std::cout << '\n';

