#include <iostream>
#include <vector>
#include <map>

using namespace std;

enum MessageType {
    PREPARE,
    COMMIT,
    DECISION
};

struct Message {
    int sender;
    int value;
    MessageType type;
};

class Node {
public:
    int id;
    vector<Node*> peers;
    map<int, int> prepareCounts;
    map<int, int> commitCounts;

    Node(int _id) : id(_id) {}

    void receiveMessage(const Message& msg) {
        switch (msg.type) {
            case PREPARE: handlePrepare(msg); break;
            case COMMIT: handleCommit(msg); break;
            default: cout << "Unknown message type\n"; break;
        }
    }

private:
    void sendToPeers(const Message& msg) {
        for (auto& peer : peers) {
            peer->receiveMessage(msg);
        }
    }

    void handlePrepare(const Message& msg) {
        prepareCounts[msg.value]++;
        if (prepareCounts[msg.value] > f()) {
            Message commitMsg = {id, msg.value, COMMIT};
            sendToPeers(commitMsg);
        }
    }

    void handleCommit(const Message& msg) {
        commitCounts[msg.value]++;
        if (commitCounts[msg.value] >= n()/2 + 1) {
            cout << "Node " << id << " decided on value: " << msg.value << endl;
            Message decisionMsg = {id, msg.value, DECISION};
            sendToPeers(decisionMsg);
        }
    }

    int f() const {
        return peers.size() / 2; // n = 2f, so f = n/2
    }

    int n() const {
        return peers.size();
    }
};

int main() {
    vector<Node*> nodes;
    for (int i = 0; i < 4; ++i) { // Example with n=4, f=2
        nodes.push_back(new Node(i));
    }

    // Connect nodes to each other
    for (auto& node : nodes) {
        for (auto& peer : nodes) {
            if (node != peer) {
                node->peers.push_back(peer);
            }
        }
    }

    // Start a proposal from the first node
    Message proposal = {0, 42, PREPARE}; // Proposal value is 42
    nodes[0]->receiveMessage(proposal);

    for (auto& node : nodes) {
        delete node;
    }

    return 0;
}
