Building a total-order broadcast (TOB) system without consensus or coordination is quite challenging because TOB inherently requires some form of agreement on the order of messages among participants to ensure all nodes receive messages in the same order.

However, if we assume a simplified scenario where we have a central server that can handle message ordering and broadcasting, we can simulate a total-order broadcast. The central server will maintain the order of messages received and send them out to clients in that specific order. This is more like a "centralized" TOB rather than a fully distributed one.

Here's a simple example using Python with sockets:

### Central Server

```python
import socket
import threading
from collections import deque

class MessageLogServer:
    def __init__(self, host='127.0.0.1', port=65432):
        self.host = host
        self.port = port
        self.clients = []
        self.message_queue = deque()
        self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server_socket.bind((self.host, self.port))
        self.server_socket.listen(5)

    def broadcast(self):
        while True:
            if self.message_queue:
                message = self.message_queue.popleft()
                for client in self.clients:
                    try:
                        client.sendall(message.encode('utf-8'))
                    except Exception as e:
                        print(f"Failed to send message: {e}")
                        self.clients.remove(client)

    def handle_client(self, client_socket):
        while True:
            try:
                data = client_socket.recv(1024)
                if not data:
                    break
                self.message_queue.append(data.decode('utf-8'))
            except Exception as e:
                print(f"Error receiving message: {e}")
                break

    def start(self):
        broadcast_thread = threading.Thread(target=self.broadcast)
        broadcast_thread.daemon = True
        broadcast_thread.start()

        while True:
            client_socket, addr = self.server_socket.accept()
            print(f"Connected by {addr}")
            self.clients.append(client_socket)
            threading.Thread(target=self.handle_client, args=(client_socket,)).start()


if __name__ == "__main__":
    server = MessageLogServer()
    server.start()
```

