### Standard Dijkstra Algorithm Implementation Using Priority Queue

```java
import java.util.*;

class Graph {
    private final Map<Integer, List<Edge>> adjList = new HashMap<>();

    public void addEdge(int source, int destination, int weight) {
        adjList.computeIfAbsent(source, k -> new ArrayList<>()).add(new Edge(destination, weight));
    }

    public Map<Integer, Integer> dijkstra(int startVertex) {
        PriorityQueue<Node> priorityQueue = new PriorityQueue<>(Comparator.comparingInt(node -> node.distance));

        Map<Integer, Integer> distances = new HashMap<>();
        for (int vertex : adjList.keySet()) {
            if (vertex == startVertex) {
                distances.put(vertex, 0);
                priorityQueue.add(new Node(startVertex, 0));
            } else {
                distances.put(vertex, Integer.MAX_VALUE);
            }
        }

        while (!priorityQueue.isEmpty()) {
            Node current = priorityQueue.poll();

            for (Edge edge : adjList.getOrDefault(current.vertex, new ArrayList<>())) {
                int distanceThroughCurrentNode = current.distance + edge.weight;

                if (distanceThroughCurrentNode < distances.get(edge.destination)) {
                    distances.put(edge.destination, distanceThroughCurrentNode);
                    priorityQueue.add(new Node(edge.destination, distanceThroughCurrentNode));
                }
            }
        }

        return distances;
    }

    static class Edge {
        final int destination;
        final int weight;

        public Edge(int destination, int weight) {
            this.destination = destination;
            this.weight = weight;
        }
    }

    static class Node {
        final int vertex;
        final int distance;

        public Node(int vertex, int distance) {
            this.vertex = vertex;
            this.distance = distance;
        }
    }
}

public class DijkstraExample {
    public static void main(String[] args) {
        Graph graph = new Graph();
        graph.addEdge(0, 1, 4);
        graph.addEdge(0, 2, 1);
        graph.addEdge(2, 1, 2);
        graph.addEdge(2, 3, 5);
        graph.addEdge(1, 3, 1);

        Map<Integer, Integer> distances = graph.dijkstra(0);

        System.out.println("Shortest distances from vertex 0:");
        for (Map.Entry<Integer, Integer> entry : distances.entrySet()) {
            System.out.println("Vertex: " + entry.getKey() + ", Distance: " + entry.getValue());
        }
    }
}
```

### Explanation
- **Graph Representation**: The graph is represented using an adjacency list where each vertex points to a list of edges.
- **Priority Queue**: We use a priority queue (min-heap) to always expand the least costly node first.
- **Distance Tracking**: A map (`distances`) keeps track of the shortest known distance from the start vertex to each vertex.

