1. First, ensure you have an NVIDIA GPU and CUDA installed on your system.
2. Create a C++ file with the following code:

```cpp
#include <iostream>
#include <cuda_runtime.h>

// Kernel that modifies an array element
__global__ void modifyArray(int *array, int value) {
    if (threadIdx.x == 0) {
        array[0] = value;
    }
}

int main() {
    int *d_array; // Pointer to unified memory

    // Allocate unified memory accessible by both host and device
    cudaMallocManaged(&d_array, sizeof(int));

    // Initialize the data on the host
    d_array[0] = 10;

    std::cout << "Initial value (host): " << d_array[0] << std::endl;

    // Launch kernel to modify the array element on the device
    modifyArray<<<1, 1>>>(d_array, 20);

    // Ensure all operations are complete before accessing from the host
    cudaDeviceSynchronize();

    std::cout << "Modified value (host): " << d_array[0] << std::endl;

    // Free unified memory
    cudaFree(d_array);

    return 0;
}
