Building a Byzantine Fault Tolerant (BFT) system like Practical Byzantine Fault Tolerance (PBFT) is a complex task, especially when dealing with the specifics of network communication and consensus algorithms. PBFT requires careful implementation to ensure that even if up to one-third of the nodes are faulty, the system can still reach agreement.

Below, I'll provide you with a simplified version of PBFT in C++. This example will not cover all edge cases and optimizations but should give you a good starting point to understand the key components. For brevity, we won't implement actual network communication; instead, we'll simulate it using function calls and shared data structures.

### Key Components:
1. **Message Types**: Pre-prepare, Prepare, Commit.
2. **States**: Each node maintains its own state (e.g., view number, primary, sequence number).
3. **Leader Election**: In PBFT, the leader is determined by a round-robin scheme.
4. **Fault Handling**: Nodes check validity of messages and handle faulty nodes.

### Simplified PBFT Implementation

Let's assume we have `n = 4` nodes (`f=1` fault tolerance). We'll use structs to represent messages and a simple class for each node.

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <algorithm>

// Define message types
struct PrePrepare {
    int view;
    int seq_num;
    std::string value;
};

struct Prepare {
    int view;
    int seq_num;
    std::string value;
    int sender_id;
};

struct Commit {
    int view;
    int seq_num;
    std::string value;
    int sender_id;
};

// Node class
class Node {
public:
    Node(int id, int total_nodes) : node_id(id), n(total_nodes), current_view(0), last_committed_seq(-1) {}

    void set_primary() { primary = (current_view % n); }

    bool is_primary() const { return node_id == primary; }

    // Simulate receiving a message
    void receive_pre_prepare(const PrePrepare& msg);
    void receive_prepare(const Prepare& msg);
    void receive_commit(const Commit& msg);

    void broadcast_prepare(const PrePrepare& pp_msg);
    void broadcast_commit(const Prepare& p_msg);

    std::string propose_value(const std::string& value);

private:
    int node_id;
    int n; // total number of nodes
    int primary;
    int current_view;
    int last_committed_seq;
    std::unordered_map<int, std::vector<Prepare>> prepare_votes;  // key: seq_num, value: prepares received
    std::unordered_map<int, std::string> committed_values;        // key: seq_num, value: committed value
};

// Simulate network communication by passing messages directly
std::vector<Node*> nodes;

void Node::receive_pre_prepare(const PrePrepare& msg) {
    if (msg.view != current_view || !is_primary()) return;

    std::cout << "Node " << node_id << " received PRE-PREPARE for seq " << msg.seq_num << ": " << msg.value << "\n";
    broadcast_prepare(msg);
}

void Node::receive_prepare(const Prepare& msg) {
    if (msg.view != current_view || committed_values.find(msg.seq_num) != committed_values.end()) return;

    std::cout << "Node " << node_id << " received PREPARE from " << msg.sender_id << " for seq " << msg.seq_num << ": " << msg.value << "\n";
    prepare_votes[msg.seq_num].push_back(msg);

    if (prepare_votes[msg.seq_num].size() == 2 * n / 3 + 1) {
        broadcast_commit(prepare_votes[msg.seq_num][0]);
    }
}

void Node::receive_commit(const Commit& msg) {
    if (msg.view != current_view || committed_values.find(msg.seq_num) != committed_values.end()) return;

    std::cout << "Node " << node_id << " received COMMIT from " << msg.sender_id << " for seq " << msg.seq_num << ": " << msg.value << "\n";

    if (std::count_if(committed_values.begin(), committed_values.end(),
                      [&](const auto& pair) { return pair.second == msg.value; }) >= n - f) {
        committed_values[msg.seq_num] = msg.value;
        last_committed_seq = msg.seq_num;
        std::cout << "Node " << node_id << " COMMITTED seq " << msg.seq_num << ": " << msg.value << "\n";
    }
}

void Node::broadcast_prepare(const PrePrepare& pp_msg) {
    Prepare p_msg{pp_msg.view, pp_msg.seq_num, pp_msg.value, node_id};

    for (int i = 0; i < n; ++i) {
        if (i != node_id) nodes[i]->receive_prepare(p_msg);
    }
}

void Node::broadcast_commit(const Prepare& p_msg) {
    Commit c_msg{p_msg.view, p_msg.seq_num, p_msg.value, p_msg.sender_id};

    for (int i = 0; i < n; ++i) {
        if (i != node_id) nodes[i]->receive_commit(c_msg);
    }
}

std::string Node::propose_value(const std::string& value) {
    if (!is_primary()) return "";

    PrePrepare pp_msg{current_view, last_committed_seq + 1, value};
    receive_pre_prepare(pp_msg); // simulate sending to self
    return value;
}

int main() {
    int n = 4; // total number of nodes (f=1 fault tolerance)
    f = 1;     // max faulty nodes

    for (int i = 0; i < n; ++i) {
        nodes.push_back(new Node(i, n));
    }

    for (auto node : nodes) {
        node->set_primary();
    }

    // Primary proposes a value
    std::string proposed_value = "some_value";
    if (nodes[0]->is_primary()) {
        nodes[0]->propose_value(proposed_value);
    }

    return 0;
}
```

