```go
package main

import (
	"database/sql"
	"fmt"
	"log"

	_ "github.com/lib/pq" // Import the postgres driver
)

func main() {
	// Connection string
	connStr := "user=yourusername dbname=yourdbname sslmode=disable password=yourpassword host=localhost port=5432"

	// Open a database connection pool. The first argument is the driver name.
	db, err := sql.Open("postgres", connStr)
	if err != nil {
		log.Fatalf("Failed to open database connection: %v\n", err)
	}
	defer db.Close() // Ensure the database connection is closed when the main function exits

	// Set up the maximum number of connections in the pool.
	db.SetMaxOpenConns(10)  // Maximum number of open connections to the database
	db.SetMaxIdleConns(5)   // Maximum number of idle connections in the pool
	db.SetConnMaxLifetime(0) // Maximum amount of time a connection may be reused

	// Test the connection.
	err = db.Ping()
	if err != nil {
		log.Fatalf("Failed to ping database: %v\n", err)
	}

	fmt.Println("Successfully connected to the database!")

	// Example query execution
	rows, err := db.Query("SELECT id, name FROM your_table")
	if err != nil {
		log.Fatalf("Failed to execute query: %v\n", err)
	}
	defer rows.Close()

	for rows.Next() {
		var id int
		var name string
		err = rows.Scan(&id, &name)
		if err != nil {
			log.Fatalf("Error scanning row: %v\n", err)
		}
		fmt.Printf("ID: %d, Name: %s\n", id, name)
	}

	// Check for errors from iterating over rows.
	err = rows.Err()
	if err != nil {
		log.Fatalf("Error iterating over rows: %v\n", err)
	}
}
```

