```go
package main

import (
	"fmt"
	"math/big"
)

// Factorize returns the prime factors of n.
func Factorize(n *big.Int) []*big.Int {
	var factors []*big.Int
	two := big.NewInt(2)
	one := big.NewInt(1)
	zero := big.NewInt(0)

	// Check for smallest factors starting from 2
	for n.Cmp(two) >= 0 {
		remainder := new(big.Int).Mod(n, two)
		if remainder.Cmp(zero) == 0 {
			factors = append(factors, two)
			n.Div(n, two)
		} else {
			two.Add(two, one)
		}
	}

	return factors
}

func main() {
	number := big.NewInt(56) // Example number to factorize
	factors := Factorize(number)

	fmt.Printf("Factors of %s are: ", number.String())
	for _, factor := range factors {
		fmt.Printf("%s ", factor.String())
	}
	fmt.Println()
}
```

This code defines a `Factorize` function that uses trial division to find the prime factors of a given integer. It starts dividing by 2 and continues with odd numbers until the input number is reduced to 1. The factors are collected in a slice and printed in the `main` function.

You can replace `56` with any other small integer you wish to factorize.

