import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.channels.FileChannel;

public class FileCopier {

    public static void main(String[] args) {
        String sourcePath = "path/to/source/file.txt";
        String destinationPath = "path/to/destination/file_copy.txt";

        try (FileInputStream fis = new FileInputStream(sourcePath);
             FileOutputStream fos = new FileOutputStream(destinationPath);
             FileChannel sourceChannel = fis.getChannel();
             FileChannel destChannel = fos.getChannel()) {

            // Transfer bytes from the source channel to the destination channel
            long bytesTransferred = sourceChannel.transferTo(0, sourceChannel.size(), destChannel);

            System.out.println("File copied successfully. Bytes transferred: " + bytesTransferred);

        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```

