// In production, you should securely store these keys.
const { publicKey, privateKey } = generateKeyPairSync('ed25519', {
    namedCurve: 'Ed25519'
});

// Convert the generated private key to PKCS8 format which is required by jose
const pkcs8PrivateKey = privateKey.export({
  type: 'pkcs8',
  format: 'pem',
});

