    const alg = 'EdDSA';

    // Import the private key using PKCS8 format
    const privateJwk = await importPKCS8(pkcs8PrivateKey, alg);

    // Create and sign the JWT with Ed25519 private key
    return await new SignJWT(payload)
        .setProtectedHeader({ alg })
        .sign(privateJwk);
}

