```go
package main

import (
	"fmt"
	"strings"
)

// parseNMEASentence parses an NMEA 0183 sentence.
func parseNMEASentence(sentence string) (string, []string, error) {
	if !strings.HasPrefix(sentence, "$") || !strings.HasSuffix(sentence, "*") {
		return "", nil, fmt.Errorf("invalid NMEA sentence format")
	}

	// Remove the start and checksum characters
	sentence = strings.TrimPrefix(strings.TrimSuffix(sentence, "*"), "$")

	// Split the sentence into fields
	parts := strings.Split(sentence, ",")

	if len(parts) < 2 {
		return "", nil, fmt.Errorf("not enough parts in NMEA sentence")
	}

	// The first part is the sentence type (e.g., GPGGA)
	sentenceType := parts[0]

	// The rest are the data fields
	dataFields := parts[1:]

	return sentenceType, dataFields, nil
}

func main() {
	// Example NMEA 0183 sentence (GPGGA - Global Positioning System Fix Data)
	nmeaSentence := "$GPGGA,123519,4807.038,N,01131.000,E,1,08,0.9,545.4,M,46.9,M,,*47"

	sentenceType, dataFields, err := parseNMEASentence(nmeaSentence)
	if err != nil {
		fmt.Println("Error parsing NMEA sentence:", err)
		return
	}

	fmt.Printf("Sentence Type: %s\n", sentenceType)
	fmt.Println("Data Fields:")
	for i, field := range dataFields {
		fmt.Printf("Field %d: %s\n", i+1, field)
	}
}
```

### Explanation:
- **Input Sentence**: The example NMEA 0183 sentence `$GPGGA,123519,4807.038,N,01131.000,E,1,08,0.9,545.4,M,46.9,M,,*47` is a GPGGA sentence which contains GPS fix data.
