```java
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class MT940Parser {

    public static void main(String[] args) {
        String mt940 = 
            "{1:F01BANKXYZAXXX0001000000}{2:O560108150730BNK111100XXXXN}{3:{113:BANKXYZ}{108:123456789}}{4:\n" +
            ":20:REFERENCE\n" +
            ":25:NL12INGB0123456789\n" +
            ":28C:1/1\n" +
            ":60F:C20070715EUR1234,56\n" +
            ":61:0707150707C123,45NTRFNONREF//REMI/INFORMATION\n" +
            ":86:123456789012345 REMI INFORMATION\n" +
            ":61:0707150707D456,78NTRFNONREF//REMI/INFORMATION\n" +
            ":86:123456789012345 REMI INFORMATION\n" +
            ":62F:C20070715EUR1111,11\n" +
            "-}";

        parseMT940(mt940);
    }

    public static void parseMT940(String mt940) {
        // Extract basic fields using regex
        Pattern referencePattern = Pattern.compile(":20:([^\n]+)");
        Pattern accountNumberPattern = Pattern.compile(":25:([^\n]+)");
        Pattern openingBalancePattern = Pattern.compile(":60F:(\\w)(\\d{6})([A-Z]{3})(\\d+),(\\d+)");
        Pattern closingBalancePattern = Pattern.compile(":62F:(\\w)(\\d{6})([A-Z]{3})(\\d+),(\\d+)");

        Matcher referenceMatcher = referencePattern.matcher(mt940);
        Matcher accountNumberMatcher = accountNumberPattern.matcher(mt940);
        Matcher openingBalanceMatcher = openingBalancePattern.matcher(mt940);
        Matcher closingBalanceMatcher = closingBalancePattern.matcher(mt940);

        if (referenceMatcher.find()) {
            System.out.println("Reference: " + referenceMatcher.group(1));
        }

        if (accountNumberMatcher.find()) {
            System.out.println("Account Number: " + accountNumberMatcher.group(1));
        }

        if (openingBalanceMatcher.find()) {
            String sign = openingBalanceMatcher.group(1);
            String date = openingBalanceMatcher.group(2);
            String currency = openingBalanceMatcher.group(3);
            String amountWhole = openingBalanceMatcher.group(4);
            String amountFractional = openingBalanceMatcher.group(5);

            System.out.println("Opening Balance: " + sign + " " + date + " " + currency + " " + amountWhole + "." + amountFractional);
        }

        if (closingBalanceMatcher.find()) {
            String sign = closingBalanceMatcher.group(1);
            String date = closingBalanceMatcher.group(2);
            String currency = closingBalanceMatcher.group(3);
            String amountWhole = closingBalanceMatcher.group(4);
            String amountFractional = closingBalanceMatcher.group(5);

            System.out.println("Closing Balance: " + sign + " " + date + " " + currency + " " + amountWhole + "." + amountFractional);
        }

        // Extract transactions
        Pattern transactionPattern = Pattern.compile(":61:(\\d{6})(\\d{4})[CD](\\d+),(\\d+)[A-Z]{3}[^/]+//([^/]+)/(.*)");
        Matcher transactionMatcher = transactionPattern.matcher(mt940);

        while (transactionMatcher.find()) {
            String datePosting = transactionMatcher.group(1);
            String timeEntry = transactionMatcher.group(2);
            String amountWhole = transactionMatcher.group(3);
            String amountFractional = transactionMatcher.group(4);
            String transactionCode = transactionMatcher.group(5);
            String description = transactionMatcher.group(6);

            System.out.println("Transaction: Date=" + datePosting + ", Time=" + timeEntry + 
                               ", Amount=" + amountWhole + "." + amountFractional + " EUR, Code=" + transactionCode + 
                               ", Description=" + description);
        }
    }
}
```

### Explanation:
1. **Regular Expressions**: The program uses regular expressions to extract specific fields from the MT940 message.
2. **Fields Extracted**:
   - `:20:` Reference number
   - `:25:` Account number
   - `:60F:` Opening balance
   - `:61:` Transactions
   - `:62F:` Closing balance

### Note:
