// Function to compare two integers in a constant time manner
bool constant_time_compare(uint32_t a, uint32_t b) {
    // XOR the values and check if all bits are zero
    uint32_t result = a ^ b;

    // Sum up all bits in the result using bitwise operations
    result |= result >> 16;
    result |= result >> 8;
    result |= result >> 4;
