	pool, err := turbopool.New(func() (interface{}, error) {
		db, err := sql.Open("postgres", connStr)
		if err != nil {
			return nil, err
		}
		return db, nil
	}, 10) // Max pool size is 10

	if err != nil {
		log.Fatalf("Failed to create TurboPool: %v", err)
	}
	defer pool.Close()

	// Get a connection from the pool
	resource, err := pool.Get()
	if err != nil {
		log.Fatalf("Failed to get resource from pool: %v", err)
	}

	db := resource.(*sql.DB)

	// Use the database connection to query the database
	var result string
	err = db.QueryRow("SELECT 'Hello, world!'").Scan(&result)
	if err != nil {
		log.Fatalf("Query failed: %v", err)
	}

	fmt.Println(result)

	// Put the connection back into the pool
	pool.Put(resource)
}
