package main

import (
	"fmt"
	"sort"
)

type ByDescending []int

func (a ByDescending) Len() int           { return len(a) }
func (a ByDescending) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a ByDescending) Less(i, j int) bool { return a[i] > a[j] }

func main() {
	numbers := []int{5, 2, 6, 3, 1, 4}

