```cpp
#include <iostream>
#include <vector>
#include <tbb/parallel_for.h>

int main() {
    // Initialize a vector with some data
    std::vector<int> data(1000);
    for (size_t i = 0; i < data.size(); ++i) {
        data[i] = i;
    }

    // Parallelize the loop using TBB's parallel_for
    tbb::parallel_for(tbb::blocked_range<size_t>(0, data.size()), [&](const tbb::blocked_range<size_t>& range) {
        for (size_t i = range.begin(); i != range.end(); ++i) {
            // Example operation: increment each element by 1
            data[i] += 1;
        }
    });

    // Print the first few elements to verify the result
    for (size_t i = 0; i < 10; ++i) {
        std::cout << "data[" << i << "] = " << data[i] << std::endl;
    }

    return 0;
}
```

