import java.util.LinkedHashMap;
import java.util.Map;

public class LRUCache<K, V> {
    private final int capacity;
    private final Map<K, V> cache;

    public LRUCache(int capacity) {
        this.capacity = capacity;
        // The LinkedHashMap constructor parameters are:
        // initialCapacity - the initial capacity of the map
        // loadFactor - the load factor threshold that triggers an expansion
        // accessOrder - the ordering mode - true for access-order, false for insertion-order
        this.cache = new LinkedHashMap<>(capacity, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
                return size() > LRUCache.this.capacity;
            }
        };
    }

    public synchronized V get(K key) {
        return cache.getOrDefault(key, null);
    }

    public synchronized void put(K key, V value) {
        cache.put(key, value);
    }

    @Override
    public String toString() {
        return "LRUCache{" + "cache=" + cache.toString() + '}';
    }

    public static void main(String[] args) {
        LRUCache<Integer, String> lruCache = new LRUCache<>(3);

        lruCache.put(1, "One");
        lruCache.put(2, "Two");
        lruCache.put(3, "Three");

        System.out.println(lruCache); // Output: LRUCache{cache={1=One, 2=Two, 3=Three}}

        lruCache.get(1);
        System.out.println(lruCache); // Output: LRUCache{cache={2=Two, 3=Three, 1=One}}

        lruCache.put(4, "Four");
        System.out.println(lruCache); // Output: LRUCache{cache={3=Three, 1=One, 4=Four}}
    }
}
```

