import java.util.concurrent.atomic.AtomicReference;

public class ConstantTimeMap<K, V> {
    private final AtomicReference<V>[] array;
    private final int size;

    @SuppressWarnings("unchecked")
    public ConstantTimeMap(int size) {
        this.size = size;
        this.array = new AtomicReference[size];
        for (int i = 0; i < size; i++) {
            array[i] = new AtomicReference<>();
        }
    }

    public V get(int key) {
        if (key >= 0 && key < size) {
            return array[key].get();
        } else {
            throw new IllegalArgumentException("Key out of bounds");
        }
    }

    public void put(int key, V value) {
        if (key >= 0 && key < size) {
            array[key].set(value);
        } else {
            throw new IllegalArgumentException("Key out of bounds");
        }
    }

    public static void main(String[] args) {
        ConstantTimeMap<Integer, String> map = new ConstantTimeMap<>(10);
        map.put(5, "Hello");
        System.out.println(map.get(5)); // Output: Hello
        System.out.println(map.get(9)); // Output: null (since nothing was put at index 9)
    }
}
```

