    console.log(`Server is running on http://localhost:${PORT}`);
});
```

### Step 3: Configure `nodemon` in Your Project

You can use `nodemon` directly from the command line or configure it using a `nodemon.json` file or by adding a script to your `package.json`.

#### Using Command Line Directly:

You can run `nodemon` with your server file like this:

```bash
npx nodemon server.js
```

#### Adding Script in `package.json`:

Alternatively, you can add a script to your `package.json` for easier access. Open your `package.json` and modify the `"scripts"` section as follows:

```json
{
  "name": "your-project-name",
  "version": "1.0.0",
  "description": "",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "dev": "nodemon server.js"
  },
  "dependencies": {
    "express": "^4.18.2"
  },
  "devDependencies": {
    "nodemon": "^3.0.1"
  }
}
```

