    }

    private void becomeCandidate() {
        term++;
        sendVotes();
        // Start an election timeout timer
        Timer timer = new Timer();
        timer.scheduleAtFixedRate(() -> {
            if (state == State.CANDIDATE) {
                step(); // Re-check state every 150ms
