3. Create a function to initialize a client and return a session with an associated lock.

```go
func createLockClient(endpoints []string) (*concurrency.Session, error) {
    // Create a new client
    cli, err := concurrency.NewClient(context.Background(), endpoints...)
    if err != nil {
        return nil, fmt.Errorf("failed to create etcd client: %v", err)
    }

    // Create a session with an associated lock
    s := concurrency.NewSession(cli)
    return s, nil
}
```

4. Use the session to acquire and release the lock.

```go
func main() {
    endpoints := []string{"http://localhost:2379"}
    sess, err := createLockClient(endpoints)
    if err != nil {
        log.Fatalf("Failed to create client: %v", err)
    }
    defer sess.Close()

    // Create a lock with the session
    mu := concurrency.NewMutex(sess, "/my-lock")

    // Acquire the lock
    ctx, cancel := context.WithTimeout(context.Background(), time.Second)
    if err := mu.Lock(ctx); err != nil {
        log.Fatalf("Failed to acquire lock: %v", err)
    }
    defer cancel()

    fmt.Println("Lock acquired. Performing protected operations...")
    time.Sleep(5 * time.Second)

    // Release the lock
    if err := mu.Unlock(context.Background()); err != nil {
        log.Fatalf("Failed to release lock: %v", err)
    }

    fmt.Println("Lock released.")
}
```

This example initializes an etcd client, creates a session with a distributed lock, acquires the lock, performs protected operations while holding the lock, and finally releases the lock. The lock is automatically released if the session ends or if the application crashes, ensuring that the system remains in a consistent state.

