struct Expression {
    Operation op;
    int arg1;
    int arg2;
};

// Function to evaluate the expression
int eval(const Expression& expr, std::vector<int>& variables) {
    switch (expr.op) {
        case ADD:
            return expr.arg1 + expr.arg2;
        case MUL:
            return expr.arg1 * expr.arg2;
        default:
            throw std::runtime_error("Invalid operation");
    }
}

// Interpreter function
void interpreter(const std::vector<Expression>& program, std::vector<int>& variables) {
    for (const auto& expr : program) {
        int result = eval(expr, variables);
        // Update the first variable with the result of the expression
        if (!variables.empty()) {
            variables[0] = result;
        } else {
            throw std::runtime_error("No variables available to store results");
        }
    }
}

int main() {
