    queue = clCreateCommandQueue(context, device, 0, NULL);

    // Load and build the program
    cl_program program = clCreateProgramWithSource(context, 1, (const char**)&kernelSource, NULL, NULL);
    clBuildProgram(program, 1, &device, NULL, NULL, NULL);

    // Create kernel
    kernel = clCreateKernel(program, "add", NULL);

    // Allocate memory on the device
    int size = 1024;
    float* h_A = new float[size];
    float* h_B = new float[size];
    float* h_C = new float[size];

    for (int i = 0; i < size; ++i) {
        h_A[i] = i;
        h_B[i] = i * 2;
    }

    cl_mem d_A = clCreateBuffer(context, CL_MEM_READ_ONLY | CL_MEM_COPY_HOST_PTR, size * sizeof(float), h_A, NULL);
    cl_mem d_B = clCreateBuffer(context, CL_MEM_READ_ONLY | CL_MEM_COPY_HOST_PTR, size * sizeof(float), h_B, NULL);
    cl_mem d_C = clCreateBuffer(context, CL_MEM_WRITE_ONLY, size * sizeof(float), NULL, NULL);

    // Set kernel arguments
    clSetKernelArg(kernel, 0, sizeof(cl_mem), &d_A);
    clSetKernelArg(kernel, 1, sizeof(cl_mem), &d_B);
    clSetKernelArg(kernel, 2, sizeof(cl_mem), &d_C);

    // Execute the kernel
    size_t globalSize = size;
    clEnqueueNDRangeKernel(queue, kernel, 1, NULL, &globalSize, NULL, 0, NULL, NULL);

    // Copy result back to host
    clEnqueueReadBuffer(queue, d_C, CL_TRUE, 0, size * sizeof(float), h_C, 0, NULL, NULL);

    for (int i = 0; i < size; ++i) {
        std::cout << "h_C[" << i << "] = " << h_C[i] << std::endl;
    }

    // Clean up
    delete[] h_A;
    delete[] h_B;
    delete[] h_C;

    clReleaseMemObject(d_A);
    clReleaseMemObject(d_B);
    clReleaseMemObject(d_C);

    clReleaseKernel(kernel);
    clReleaseProgram(program);
    clReleaseCommandQueue(queue);
    clReleaseContext(context);

    return 0;
}
```

### Using CUDA

CUDA is a parallel computing platform and application programming interface (API) model created by NVIDIA for general-purpose computing on GPUs.

1. **Setup a CUDA environment**:
   - Initialize CUDA.
   - Allocate memory on the GPU.
   - Copy data between CPU and GPU.

2. **Define the kernel**:
   - The kernel will run on the GPU and will access shared coherent memory.

3. **Copy data between CPU and GPU**:
   - Use `cudaMemcpy` to transfer data from CPU to GPU.
   - Use `cudaMemcpy` again to transfer data from GPU to CPU after processing.

Here's a basic example:

```cpp
#include <iostream>
#include <cuda_runtime.h>

__global__ void add(float* A, float* B, float* C) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    C[idx] = A[idx] + B[idx];
}

int main() {
    // Allocate memory on the CPU
    int size = 1024 * 1024;
    float* h_A = new float[size];
    float* h_B = new float[size];
    float* h_C = new float[size];

    for (int i = 0; i < size; ++i) {
        h_A[i] = i;
        h_B[i] = i * 2;
    }

    // Allocate memory on the GPU
    float* d_A, *d_B, *d_C;
    cudaMalloc((void**)&d_A, size * sizeof(float));
    cudaMalloc((void**)&d_B, size * sizeof(float));
    cudaMalloc((void**)&d_C, size * sizeof(float));

    // Copy data from CPU to GPU
    cudaMemcpy(d_A, h_A, size * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_B, h_B, size * sizeof(float), cudaMemcpyHostToDevice);

    // Define grid and block dimensions
    dim3 blockSize(256);
    dim3 gridSize((size + blockSize.x - 1) / blockSize.x);

    // Launch the kernel
    add<<<gridSize, blockSize>>>(d_A, d_B, d_C);

    // Copy result back to CPU
    cudaMemcpy(h_C, d_C, size * sizeof(float), cudaMemcpyDeviceToHost);

    for (int i = 0; i < size; ++i) {
        std::cout << "h_C[" << i << "] = " << h_C[i] << std::endl;
    }

    // Clean up
    delete[] h_A;
    delete[] h_B;
    delete[] h_C;

    cudaFree(d_A);
    cudaFree(d_B);
    cudaFree(d_C);

    return 0;
}
```

### Summary

- **OpenCL**: Provides a cross-platform solution for parallel computing.
- **CUDA**: Specific to NVIDIA GPUs but offers high performance and low-level control.

Both frameworks allow you to share coherent memory between the GPU and CPU, enabling efficient data transfer and computation. Make sure to handle errors properly in both examples, as shown with `clBuildProgram` and `cudaMalloc`.

In C++, the standard does not guarantee that the compiler will not reorder memory operations across a function call unless you explicitly tell it to do so. However, there are certain mechanisms and techniques to enforce this behavior if necessary.

One such mechanism is the use of `std::atomic` variables, which provide a way to perform atomic operations that cannot be reordered by the compiler or hardware.

Here's a minimal working example demonstrating how you can use `std::atomic` variables to ensure that memory operations are not reordered across a function call:

```cpp
#include <iostream>
#include <atomic>

// Atomic variables to ensure ordering
std::atomic<int> before = 0;
std::atomic<int> after = 0;

void myFunction() {
    // Function logic
    std::cout << "Function called" << std::endl;
}

int main() {
    before.store(1);

    // Ensure that the store operation to 'before' is visible before the function call
    std::atomic_thread_fence(std::memory_order_release);

    myFunction();

    // Ensure that the function completes before any subsequent load operation from 'after'
    std::atomic_thread_fence(std::memory_order_acquire);

    after.store(2);

    return 0;
}
```

In this example:
1. `before` and `after` are atomic variables.
2. `std::atomic_thread_fence(std::memory_order_release)` ensures that all store operations before the fence are visible to other threads or processes.
3. `std::atomic_thread_fence(std::memory_order_acquire)` ensures that all subsequent load operations after the fence observe changes made by previous stores, including those in the function call.

This example demonstrates how you can use atomic variables and memory fences to control the ordering of memory operations across a function call.

