        this.peers = peers;
        resetElectionTimeout();
    }

    public void start() {
        while (true) {
            switch (state) {
                case Follower:
                    follow();
                    break;
                case Candidate:
                    candidate();
                    break;
                case Leader:
                    leader();
                    break;
            }
            try {
                Thread.sleep(100);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }

    private void follow() {
        electionTimer.reset();
        System.out.println("Node " + id + " is in follower state");
        // Handle append entries RPCs from leaders
    }

    private void candidate() {
        currentTerm++;
        votedFor = id;
        int grantedVotes = 1;

        resetElectionTimeout();

        // Send RequestVote RPCs to all other servers
        for (RaftNode peer : peers) {
            new Thread(() -> {
                boolean voteGranted = peer.requestVote(this);
                if (voteGranted) {
                    synchronized (this) {
                        grantedVotes++;
                        if (grantedVotes > peers.size() / 2) {
                            state = State.Leader;
                            currentTerm++;
                            // Send AppendEntries RPCs to all other servers
                            for (RaftNode peer : peers) {
                                new Thread(() -> peer.appendEntries(this)).start();
                            }
                            break;
                        }
                    }
                } else {
                    synchronized (this) {
                        if (peer.currentTerm > currentTerm) {
                            state = State.Follower;
                            currentTerm = peer.currentTerm;
                            resetElectionTimeout();
                        }
                    }
                }
            }).start();
        }

        electionTimer.start();
    }

    private void leader() {
        // Send AppendEntries RPCs to all followers
        for (RaftNode peer : peers) {
            new Thread(() -> peer.appendEntries(this)).start();
        }

        // Reset election timer and send out heartbeats periodically
        resetElectionTimeout();
        while (true) {
            try {
                Thread.sleep(HEARTBEAT_INTERVAL);
                for (RaftNode peer : peers) {
                    new Thread(() -> peer.appendEntries(this)).start();
                }
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }

    private boolean requestVote(RaftNode candidate) {
        System.out.println("Node " + id + " received vote request from Node " + candidate.id);
        if ((votedFor == null || votedFor.equals(candidate.id)) && candidate.currentTerm >= currentTerm) {
            votedFor = candidate.id;
            return true;
        }
        return false;
    }

    private void appendEntries(RaftNode leader) {
        System.out.println("Node " + id + " received AppendEntries from Node " + leader.id);
        // Handle AppendEntries RPC
    }

    private void resetElectionTimeout() {
        electionTimer = new Timer();
        electionTimer.schedule(new TimerTask() {
            @Override
            public void run() {
                if (state == State.Follower) {
                    state = State.Candidate;
                    currentTerm++;
                    votedFor = id;
                    candidate();
                }
            }
        }, TIMEOUT);
    }

    public static void main(String[] args) {
        List<RaftNode> nodes = new ArrayList<>();
        for (int i = 1; i <= 3; i++) {
            nodes.add(new RaftNode(i, nodes));
        }

        for (RaftNode node : nodes) {
            new Thread(node::start).start();
        }
    }
}
```

### Explanation:
