#include <iostream>
#include <vector>

// Function to perform cache-blocked matrix multiplication
void blockedMatrixMultiply(const std::vector<std::vector<double>>& A,
                          const std::vector<std::vector<double>>& B,
                          std::vector<std::vector<double>>& C,
                          int block_size) {
    int M = A.size();
    int N = B[0].size();
    int K = A[0].size();

    // Initialize the result matrix C to zero
    for (int i = 0; i < M; ++i) {
        for (int j = 0; j < N; ++j) {
            C[i][j] = 0;
        }
    }

    // Cache-blocked matrix multiplication
    for (int mb = 0; mb < M; mb += block_size) {
        for (int nb = 0; nb < N; nb += block_size) {
            for (int kb = 0; kb < K; kb += block_size) {
                // Block dimensions
                int mb_block = std::min(block_size, M - mb);
                int nb_block = std::min(block_size, N - nb);
                int kb_block = std::min(block_size, K - kb);

                // Perform the matrix multiplication for the current block
                for (int i = 0; i < mb_block; ++i) {
                    for (int j = 0; j < nb_block; ++j) {
                        for (int k = 0; k < kb_block; ++k) {
                            C[mb + i][nb + j] += A[mb + i][kb + k] * B[kb + k][nb + j];
                        }
                    }
                }
            }
        }
    }
}

// Example usage
int main() {
    int block_size = 16; // Typically, you would choose a value around the cache line size (e.g., 32 or 64 bytes)

    std::vector<std::vector<double>> A = {
        {1, 2, 3},
        {4, 5, 6},
        {7, 8, 9}
    };

    std::vector<std::vector<double>> B = {
        {9, 8, 7},
        {6, 5, 4},
        {3, 2, 1}
    };

    int M = A.size();
    int N = B[0].size();

    std::vector<std::vector<double>> C(M, std::vector<double>(N, 0));

    blockedMatrixMultiply(A, B, C, block_size);

    for (int i = 0; i < M; ++i) {
        for (int j = 0; j < N; ++j) {
            std::cout << C[i][j] << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}
```

### Explanation:
1. **Block Size**: The `block_size` determines the size of each block in the matrix multiplication. This value should typically be around the cache line size (e.g., 32 or 64 bytes) to maximize cache utilization.

2. **Loop Unrolling**: While not shown in this basic example, you can further optimize by unrolling loops inside the blocks for better instruction-level parallelism.

3. **Matrix Initialization**: The result matrix `C` is initialized to zero before performing the multiplication.

4. **Blocked Looping**: The main loops are structured to iterate over the matrices in blocks:
   - Outermost loop (`mb`, `nb`, `kb`) iterates over the blocks.
   - Inner loops handle the computation within each block, ensuring that the computations fit into the cache.

This implementation provides a basic framework for cache-blocked matrix multiplication. Depending on your specific requirements and the characteristics of your data, further optimizations may be necessary.

