import (
	"fmt"
	"math/big"
)

func main() {
	// Number to be factored
	n := big.NewInt(15) // For example, factor 15

	// Find factors of n
	var f big.Int
	for i := big.NewInt(2); ; i.Add(i, big.NewInt(1)) {
		if i.Cmp(n) > 0 {
			break
		}
		if n.Mod(n, i).Sign() == 0 { // Check if i is a factor of n
			f.Set(i)
			fmt.Printf("Factor found: %s\n", f.String())
			n.Div(n, i) // Divide n by the factor to continue factoring
			i.Sub(i, big.NewInt(1)) // Adjust i to restart the loop with the correct value
		}
	}

	// Print remaining factor if any
	if n.Cmp(big.NewInt(1)) > 0 {
		fmt.Printf("Remaining factor: %s\n", n.String())
	}
}
```

