```rust
use clap::{Parser, Arg};

/// My amazing CLI tool!
#[derive(Parser)]
#[clap(author, version, about = "Does awesome things", long_about = None)]
struct Cli {
    /// Name of the person to greet
    #[clap(short, long, default_value_t = String::from("world"))]
    name: String,

    /// Sets the level of verbosity
    #[clap(short, parse(from_occurrences))]
    verbose: u8,
}

fn main() {
    let args = Cli::parse();

    // Print the greeting with the provided name and verbosity level
    for _ in 0..args.verbose {
        println!("verbose");
    }
    println!("Hello {}!", args.name);
}
```

### Explanation:

