      this.minHeap.push(-max);
    }

    // Update median heap
    this.medianHeap.push(value);

    if (this.medianHeap.length > 1) {
      const median = this.medianHeap[Math.floor(this.medianHeap.length / 2)];
      this.medianHeap.push(-median);
    }
  }

  delete(value) {
