Here's an example of how you could implement a cache-blocked matrix multiply using OpenMP in C:
```c
#include <stdio.h>
#include <stdlib.h>
#include <omp.h>

#define BLOCK_SIZE 1024 // Block size in elements
#define N 1000 // Matrix size
#define K 100 // Number of iterations

int main() {
    int i, j, k;
    float *A = malloc(N*N*sizeof(float));
    float *B = malloc(N*N*sizeof(float));
    float *C = malloc(N*N*sizeof(float));

    // Initialize matrices
    for (i = 0; i < N; i++) {
        for (j = 0; j < N; j++) {
            A[i*N + j] = i;
            B[i*N + j] = j;
            C[i*N + j] = 0;
        }
    }

    // Compute the product in tiles using cache blocking
    #pragma omp parallel for collapse(2)
    for (i = 0; i < N; i += BLOCK_SIZE) {
        for (j = 0; j < N; j += BLOCK_SIZE) {
            for (k = 0; k < K; k++) {
                int ii = i + k*BLOCK_SIZE;
                int jj = j + k*BLOCK_SIZE;
                for (int p = 0; p < BLOCK_SIZE; p++) {
                    C[ii*N + jj] += A[ii*N + p]*B[p*N + jj];
                }
            }
        }
    }

    // Print the result
    printf("C = \n");
    for (i = 0; i < N; i++) {
        for (j = 0; j < N; j++) {
            printf("%f ", C[i*N + j]);
        }
        printf("\n");
    }

    free(A);
    free(B);
    free(C);

    return 0;
}
```
This implementation uses a block size of 1024 elements, which is small enough to fit entirely in the L3 cache on most modern processors. The matrix multiply is performed in tiles using the `collapse` clause, which allows multiple threads to access the same cache line simultaneously. The `parallel for` clause is used to distribute the work among multiple threads.

