package main

import (
	"log"
	"net/http"
)

func main() {
	// Create a new http.Server and specify the root directory for serving files
	server := &http.Server{Addr: ":8080", Root: "/path/to/root/directory"}

	// Handle incoming HTTP requests by serving files from the root directory
	http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		file := r.URL.Path[1:]
		if _, err := os.Stat(file); err == nil {
			http.ServeFile(w, r, file)
		} else {
			http.Error(w, http.StatusText(404), 404)
		}
	})

	// Start the server and listen for incoming requests
	log.Println("Server started on port 8080")
	if err := server.ListenAndServe(); err != nil {
		log.Fatal(err)
	}
}
```
This code creates a new `http.Server` instance and specifies the root directory for serving files using the `Root` field. It then handles incoming HTTP requests by serving files from the root directory using the `ServeFile` method of the `http.ResponseWriter` object. If a file is not found, it returns an error response with a status code of 404. Finally, the server is started and listens for incoming requests on port 8080 using the `ListenAndServe` method.

In this example, we are serving files from the root directory `/path/to/root/directory`. You can change the value of the `Root` field to serve files from a different directory.

