public class SwiftMt940Parser {
    public static void main(String[] args) throws IOException {
        // Read the MT940 file into a list of lines
        List<String> lines = Files.readAllLines(new File("path/to/mt940/file").toPath());

        // Create a pattern to match the fields in the MT940 file
        Pattern pattern = Pattern.compile("(\\w{6}) (\\w{3}) (\\d+)-(\\d+)-(\\d+) (\\d{2}):(\\d{2}):(\\d{2})");

