```
#include <iostream>
#include <linux/can.h>
#include <linux/can/raw.h>

int main() {
  // Open the CAN interface
  int fd = socket(PF_CAN, SOCK_RAW, CAN_RAW);
  if (fd == -1) {
    perror("socket");
    return 1;
  }

  // Set up the CAN interface
  struct ifreq ifr;
  strcpy(ifr.ifr_name, "can0"); // Replace with your CAN interface name
  ioctl(fd, SIOCGIFINDEX, &ifr);
  int ifindex = ifr.ifr_ifindex;

  // Set up the socket options
  struct sockaddr_can addr;
  memset(&addr, 0, sizeof(addr));
  addr.can_family = AF_CAN;
  addr.can_ifindex = ifindex;
  bind(fd, (struct sockaddr*)&addr, sizeof(addr));

  // Read the CAN frames from the interface
  while (1) {
    struct can_frame frame;
    int nbytes = read(fd, &frame, sizeof(frame));
    if (nbytes < 0) {
      perror("read");
      break;
    }

    // Print the CAN frame data
    std::cout << "Frame received: ";
    for (int i = 0; i < 8; i++) {
      std::cout << std::hex << std::setw(2) << std::setfill('0') << (unsigned int)frame.data[i] << ' ';
    }
    std::cout << '\n';
  }

  // Close the socket
  close(fd);
  return 0;
}
```
This code opens a raw CAN socket and binds it to the `can0` interface. It then enters a loop that reads CAN frames from the interface using the `read()` system call, and prints out the data for each frame.

You can modify this code to read from any other CAN interface by changing the value of the `ifr_name` field in the `ifreq` structure before calling `ioctl()`.

