  private IQueue sourceQueue;
  private IQueue targetQueue;

  public ProxyServer(Connection connection, IQueue sourceQueue, IQueue targetQueue) {
    this.connection = connection;
    this.sourceQueue = sourceQueue;
    this.targetQueue = targetQueue;
  }

  public void start() {
