To make this server reliable, you can use the `net` package's built-in support for Reliable UDP (RFC 9105). This will ensure that the server sends a duplicate ACK if it does not receive an ACK from the client within a certain time period. Here is an example of how to modify the previous code to use Reliable UDP:
```
package main

import (
	"fmt"
	"log"
	"net"
)

func main() {
	// Listen for incoming UDP connections on port 8080
	addr, err := net.ResolveUDPAddr("udp", ":8080")
	if err != nil {
		log.Fatal(err)
	}
	conn, err := net.ListenUDP("udp", addr)
	if err != nil {
		log.Fatal(err)
	}
	defer conn.Close()

	// Set up Reliable UDP
	conn.SetReliableUDP()

	// Buffer for incoming messages
	buf := make([]byte, 1024)

	// Loop indefinitely to receive messages
	for {
		// Receive a message from the client
		n, _, err := conn.ReadFromUDP(buf)
		if err != nil {
			log.Fatal(err)
		}

		// Print the received message
		fmt.Printf("Received: %s\n", buf[:n])

		// Send an acknowledgement back to the client
		_, err = conn.WriteToUDP([]byte("ACK"), addr)
		if err != nil {
			log.Fatal(err)
		}
	}
}
```
This server will now use Reliable UDP and send a duplicate ACK if it does not receive an ACK from the client within a certain time period. This will ensure that messages are received exactly once by the server.

