typedef struct {
    volatile long counter;
} shared_counter_t;

shared_counter_t shared_counter = {0};

long get_and_increment_counter() {
    long counter;

    // Acquire the memory before reading the counter.
    __asm__ __volatile__("lfence" :::);

    counter = shared_counter.counter;

    // Increment the counter.
    shared_counter.counter = counter + 1;

    // Release the memory after writing the counter.
    __asm__ __volatile__("sfence" :::);

    return counter;
}
