  int thread1_value = 1;
  int thread2_value = 2;
  int thread3_value = 3;

  wait_free_consensus(thread1_value);
  wait_free_consensus(thread2_value);
  wait_free_consensus(thread3_value);

  // All threads have now reached consensus on the shared value of 3.
}
```

