    int n = 5;
    int f = 2;

    ByzantineAgreementService service(n, f);

    // Send messages from different nodes
    service.sendMessage(0, "a");
    service.sendMessage(1, "b");
    service.sendMessage(2, "a");

    // Get the agreement
    string agreement = service.getAgreement();

    // Print the agreement
    cout << "Agreement: " << agreement << endl;

    return 0;
}
```

