```java
import java.util.Arrays;

public class PetrovBoundMatching {

    private final int n;
    private final boolean[][] graph;
    private int[] matching;
    private boolean[] visited;
    private int bound;

    public PetrovBoundMatching(boolean[][] graph) {
        this.n = graph.length;
        this.graph = graph;
        this.matching = new int[n];
        Arrays.fill(matching, -1);
        this.visited = new boolean[n];
        this.bound = 0;
    }

    public int maxMatching() {
        while (bfs()) {
            for (int i = 0; i < n; i++) {
                if (graph[i][matching[i]] && !visited[i]) {
                    dfs(i);
                }
            }
        }
        return bound;
    }

    private boolean bfs() {
        Arrays.fill(visited, false);
        int m = 0;
        for (int i = 0; i < n; i++) {
            if (matching[i] == -1) {
                if (dfs(i)) {
                    m++;
                }
            }
        }
        return m == n;
    }

    private boolean dfs(int v) {
        if (v == -1) {
            return true;
        }
        visited[v] = true;
        for (int i = 0; i < n; i++) {
            if (!visited[i] && graph[v][i]) {
                if (dfs(matching[i])) {
                    matching[i] = v;
                    return true;
                }
            }
        }
        return false;
    }
}
```

