#include <stdint.h>
#include <stdlib.h>
#include <string.h>

// Memory-safe version of memcpy
void memcpy_safe(void* dst, const void* src, size_t size) {
  if (dst == NULL || src == NULL || size == 0) {
    return;
  }

  if (dst == src) {
    return;
  }

  uint8_t* dst_ptr = (uint8_t*)dst;
  const uint8_t* src_ptr = (const uint8_t*)src;

  for (size_t i = 0; i < size; i++) {
    dst_ptr[i] = src_ptr[i];
  }
}

// Memory-safe version of memmove
void memmove_safe(void* dst, const void* src, size_t size) {
  if (dst == NULL || src == NULL || size == 0) {
    return;
  }

  if (dst == src) {
    return;
  }

  uint8_t* dst_ptr = (uint8_t*)dst;
  const uint8_t* src_ptr = (const uint8_t*)src;

  if (dst_ptr < src_ptr) {
    for (size_t i = 0; i < size; i++) {
      dst_ptr[i] = src_ptr[i];
    }
  } else {
    for (size_t i = size - 1; i >= 0; i--) {
      dst_ptr[i] = src_ptr[i];
    }
  }
}

// Memory-safe version of strlen
size_t strlen_safe(const char* str) {
  if (str == NULL) {
    return 0;
  }

  size_t len = 0;
  while (str[len] != '\0') {
    len++;
  }

  return len;
}

// Memory-safe version of strcpy
char* strcpy_safe(char* dst, const char* src) {
  if (dst == NULL || src == NULL) {
    return NULL;
  }

  size_t len = strlen_safe(src);
  memcpy_safe(dst, src, len + 1);

  return dst;
}

// Memory-safe version of strncpy
char* strncpy_safe(char* dst, const char* src, size_t n) {
  if (dst == NULL || src == NULL) {
    return NULL;
  }

  size_t len = strlen_safe(src);
  if (n > len) {
    n = len;
  }

  memcpy_safe(dst, src, n);
  dst[n] = '\0';

  return dst;
}
```

**How it works:**

* The code provides memory-safe versions of fundamental functions like memcpy, memmove, strlen, strcpy, and strncpy.
* These functions perform bounds checking and type safety to ensure that memory is accessed correctly.
* They also handle special cases like NULL pointers and empty strings.
* By using these memory-safe functions, we can avoid memory corruption and other runtime errors that can occur with traditional functions.

