// FencingToken represents a token used to acquire a lease.
type FencingToken struct {
	mu    sync.Mutex
	owner string
}

// Lock creates a new lease-based lock.
func Lock(token *FencingToken) *sync.Mutex {
	return &token.mu
}

// TryAcquire attempts to acquire a lease.
func TryAcquire(token *FencingToken, owner string) bool {
	token.mu.Lock()
	defer token.mu.Unlock()

	if token.owner == "" {
		token.owner = owner
		return true
	}

	return false
}

// Release releases a lease.
func Release(token *FencingToken) {
	token.mu.Lock()
	defer token.mu.Unlock()

	token.owner = ""
}
