```cpp
class Consensus {
private:
  std::vector<Node> nodes;
  int f;

public:
  Consensus(int n) : f((n - 1) / 3) {
    for (int i = 0; i < n; i++) {
      nodes.push_back(Node(i));
    }
  }

  bool reachConsensus(std::string data) {
    // Broadcast the data to all nodes.
    for (Node& node : nodes) {
      node.receiveMessage({id, data});
    }

    // Wait for all nodes to become ready.
    while (!allNodesReady()) {}

    // Check if there is a majority consensus.
    std::string consensus = getConsensus();
    return consensus == data;
  }

private:
  bool allNodesReady() {
    for (Node& node : nodes) {
      if (!node.isReady()) {
        return false;
      }
    }
    return true;
  }

  std::string getConsensus() {
    // Extract the data from the messages of all nodes.
    std::set<std::string> proposals;
    for (Node& node : nodes) {
      for (Message message : node.getMessages()) {
        proposals.insert(message.data);
      }
    }

    // Return the most common proposal.
    if (proposals.size() > 2 * f) {
      return *proposals.begin();
    } else {
      return "";
    }
  }
};
```

