```java
import java.util.HashMap;

public class DiscreteLogarithm {

    private static final int MODULUS = 2^16;
    private static final int GENERATOR = 2;

    public static int discreteLogarithm(int h) {
        int order = findOrder();
        int stepSize = (int) Math.ceil(Math.sqrt(order));

        HashMap<Integer, Integer> babySteps = new HashMap<>();
        int x = 1;
        for (int i = 0; i < stepSize; i++) {
            babySteps.put(x, i);
            x = (x * GENERATOR) % MODULUS;
        }

        int y = h;
        for (int j = 0; j < stepSize; j++) {
            if (babySteps.containsKey(y)) {
                return j * stepSize + babySteps.get(y);
            }
            y = (y * GENERATOR) % MODULUS;
        }

        return -1;
    }

    private static int findOrder() {
        int order = MODULUS;
        int x = GENERATOR;
        while (x != 1) {
            order--;
            x = (x * GENERATOR) % MODULUS;
        }
        return order;
    }

    public static void main(String[] args) {
        int h = 5; // Example value
        int log = discreteLogarithm(h);
        System.out.println("Discrete logarithm of " + h + " is " + log);
    }
}
```

**Explanation:**

* The `discreteLogarithm()` method implements the baby-step giant-step algorithm.
* It takes the value `h` as input and returns the discrete logarithm of `h`.
* The `findOrder()` method calculates the order of the group, which is the smallest positive integer `n` such that `g^n ≡ 1 (mod p)`.
* The algorithm works by splitting the search space into two parts:
    * Baby steps: Iterates over values of `x` from 1 to `stepSize`.
    * Giant steps: Iterates over values of `y` from 0 to `order / stepSize`.
* When `x` and `y` have a common value, the discrete logarithm is calculated and returned.

**Note:**

* The modulus `p` and generator `g` can be chosen for the specific group.
* The example uses a 16-bit group with `p = 2^16` and `g = 2`.
* The time complexity of the algorithm is O(√n), where n is the order of the group.

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Point {
    int x, y;
};

struct Node {
    Point p;
    int split;
    Node *left, *right;
};

class KDTree {
public:
    KDTree() { root = NULL; }

    void build(vector<Point>& points, int depth = 0);
    pair<Point, double> nearestNeighbour(Point query, int depth = 0);

private:
    Node* root;
    int split;

    Node* createNode(Point p);
    void splitPoints(vector<Point>& points, int depth);
};

Node* KDTree::createNode(Point p) {
    Node* node = new Node();
    node->p = p;
    node->split = depth % 2;
    node->left = node->right = NULL;
    return node;
}

void KDTree::splitPoints(vector<Point>& points, int depth) {
    sort(points.begin(), points.end(), [&depth](Point a, Point b) {
        return depth % 2 ? a.y < b.y : a.x < b.x;
    });
}

void KDTree::build(vector<Point>& points, int depth) {
    splitPoints(points, depth);
    int mid = points.size() / 2;
    root = createNode(points[mid]);
    build(vector<Point>(points.begin(), points.begin() + mid), depth + 1);
    build(vector<Point>(points.begin() + mid + 1, points.end()), depth + 1);
}

pair<Point, double> KDTree::nearestNeighbour(Point query, int depth) {
    Node* curr = root;
    pair<Point, double> best = make_pair(Point{-1, -1}, numeric_limits<double>::max());

    while (curr) {
        int axis = depth % 2;
        double dist = sqrt(pow(curr->p.x - query.x, 2) + pow(curr->p.y - query.y, 2));
        if (dist < best.second) best = make_pair(curr->p, dist);

        if (query.x <= curr->p.x) {
            curr = curr->left;
        } else {
            curr = curr->right;
        }
        depth++;
    }

    return best;
}
```

**Usage:**

```cpp
int main() {
    vector<Point> points = {{1, 2}, {3, 4}, {5, 6}, {7, 8}};
    KDTree tree;
    tree.build(points);

    Point query = {4, 5};
    pair<Point, double> nearest = tree.nearestNeighbour(query);

    cout << "Nearest neighbour: (" << nearest.first.x << ", " << nearest.first.y << ")" << endl;
    cout << "Distance: " << nearest.second << endl;

    return 0;
}
```

