use core::cmp::Ordering;

/// Constant-time memory comparison.
///
/// Returns `true` if the two slices are equal, and `false` otherwise.
///
/// This function uses constant-time comparison, which means that the time it takes to
/// complete does not depend on the length of the slices. This can help to reduce
/// timing leakage, which can be useful for security-sensitive applications.
pub fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
