    public static void main(String[] args) throws IOException {
        // Input file path
        String inputFilePath = "input.txt";

        // Output file path
        String outputFilePath = "output.txt";

        // Open input and output files
        FileInputStream in = new FileInputStream(inputFilePath);
        FileOutputStream out = new FileOutputStream(outputFilePath);

        // Get FileChannel instances
        FileChannel inChannel = in.getChannel();
        FileChannel outChannel = out.getChannel();

        // Copy file using transferTo() method
        long bytesTransferred = inChannel.transferTo(0, inChannel.size(), outChannel);

        // Close channels
        inChannel.close();
        outChannel.close();
        in.close();
        out.close();

        // Print number of bytes copied
        System.out.println("Number of bytes copied: " + bytesTransferred);
    }
}
```

