#include <iostream>
#include <vector>
using namespace std;

vector<int> mergeSortedListsDesc(const vector<int>& list1, const vector<int>& list2) {
  vector<int> merged;
  int i = list1.size() - 1;
  int j = list2.size() - 1;

  while (i >= 0 && j >= 0) {
    if (list1[i] > list2[j]) {
      merged.push_back(list1[i--]);
    } else {
      merged.push_back(list2[j--]);
    }
  }

  while (i >= 0) {
    merged.push_back(list1[i--]);
  }

  while (j >= 0) {
    merged.push_back(list2[j--]);
  }

  return merged;
}

int main() {
  vector<int> list1 = {5, 3, 1};
  vector<int> list2 = {4, 2, 0};

  vector<int> merged = mergeSortedListsDesc(list1, list2);

  for (int num : merged) {
