```cpp
#include <vector>

using namespace std;

vector<int> moveZeroesFront(vector<int>& nums) {
  int count = 0;
  for (int i = 0; i < nums.size(); i++) {
    if (nums[i] == 0) {
      count++;
    } else {
      nums[i - count] = nums[i];
    }
  }

  for (int i = 0; i < count; i++) {
    nums[nums.size() - 1 - i] = 0;
  }

  return nums;
}
```

