// NMEA0183Sentence represents a single NMEA 0183 GPS sentence.
type NMEA0183Sentence struct {
	SentenceType string
	Data          map[string]string
}

// Parse parses a NMEA 0183 GPS sentence from a reader.
func Parse(r io.Reader) (*NMEA0183Sentence, error) {
	scanner := bufio.NewScanner(r)
	for scanner.Scan() {
		line := scanner.Text()
		if strings.HasPrefix(line, "$GPGGA") || strings.HasPrefix(line, "$GPRMC") { // Example sentence types
			parts := strings.Split(line, ",")
			sentence := &NMEA0183Sentence{
				SentenceType: parts[0][1:],
				Data:          make(map[string]string),
			}
			for _, part := range parts[1:] {
				keyValuePair := strings.SplitN(part, "=", 2)
				if len(keyValuePair) == 2 {
					sentence.Data[keyValuePair[0]] = keyValuePair[1]
				}
			}
			return sentence, nil
		}
	}
	return nil, io.EOF
}
