```go
package main

import (
	"fmt"
	"net"
	"sync"
)

func main() {
	// Create a UDP listener.
	listener, err := net.ListenUDP("udp", &net.UDPAddr{Port: 8080})
	if err != nil {
		panic(err)
	}
	defer listener.Close()

	// Create a map to track received messages.
	received := make(map[string]bool)
	mu := sync.Mutex{}

	// Start a goroutine to handle incoming messages.
	go func() {
		for {
			// Read a message.
			buf := make([]byte, 1024)
			n, addr, err := listener.ReadFromUDP(buf)
			if err != nil {
				panic(err)
			}

			// Lock the map.
			mu.Lock()
			defer mu.Unlock()

			// Check if the message has already been received.
			if _, ok := received[string(buf[:n])]; !ok {
				// Mark the message as received.
				received[string(buf[:n])] = true

				// Print the message.
				fmt.Println("Received message:", string(buf[:n]), "from", addr)
			}
		}
	}()

	// Send messages.
	for {
		// Write a message.
		msg := []byte("Hello, world!")
		_, err := listener.WriteToUDP(msg, &net.UDPAddr{Port: 8080})
		if err != nil {
			panic(err)
		}
	}
}
```

**How it works:**

* The server creates a UDP listener on port 8080.
* It maintains a map to track received messages.
* A goroutine is started to handle incoming messages.
* When a message is received, it is checked if it has been received before.
* If it has not been received, it is marked as received and printed.
* The server continues to send messages until the program is stopped.

**Notes:**

* This code uses the UDP-Reliable-ExactlyOnce (UDP-REX) protocol.
* The `sync.Mutex` is used to protect the map of received messages.
* The `WriteToUDP()` method is used to send messages.
* The `ReadFromUDP()` method is used to receive messages.

