func connectWPA2Network(ssid, passphrase string) error {
	ctx := context.Background()

	// Create a new WPA2 client.
	client, err := wpa2.NewClient(ctx)
	if err != nil {
		return err
	}
	defer client.Close()

	// Join the WPA2 network.
	if err := client.Join(ctx, &wpa2.Config{
		SSID:       ssid,
		Passphrase: passphrase,
	}); err != nil {
		return err
	}

	// Check if the connection is successful.
	if err := client.WaitForConnection(ctx); err != nil {
		return err
	}

	log.Println("Connected to WPA2 network.")

	return nil
}
