class SharedCounter(object):
    def __init__(self, initial=0):
        self._counter = initial
        self._local_counters = {}

    def increment(self, n=1):
        # Get the current thread ID and create a local counter if it doesn't exist.
        tid = threading.get_ident() 
        if not self._local_counters.get(tid):
            self._local_counters[tid] = 0

        # Increment the local counter and update shared counter.
        self._local_counters[tid] += n
        self._counter += n

    def value(self):
        return self._counter
