    def __init__(self, register1, register2, register3):
        self.registers = [register1, register2, register3]

    def update_all(self, value):
        for reg in self.registers:
            while True:
                old_value = reg.value
                if reg.value == value or reg._value.compare_and_swap(old_value, value) == old_value:
                    break

    def read_all(self):
        return [reg.value for reg in self.registers]

