The following is an implementation of the Hopcroft-Karp Algorithm, which is used to find the Maximum Bipartite Matching (MBM), also known as the Petrov bound matching algorithm. This algorithm runs in O(n) time complexity. 

```java
import java.util.*;

class GFG {

    static class HopcroftKarp{

        int UNMATCHED = -1;

        ArrayList<Integer>[] graph ;

        int[] pairU,pairV,dist;

         boolean bfs() {

             Queue<Integer> q = new LinkedList<>();

             for(int u=0;u<graph.length;++u) 
                  if (pairU[u] == UNMATCHED){
                     dist[u] = 0 ;
                     q.add(u);
                 } else 
                      dist[u] = Integer.MAX_VALUE ;

             dist[UNMATCHED] = Integer.MAX_VALUE;

             while(!q.isEmpty()){
                  int u = q.poll();

                  if(dist[u] < dist[UNMATCHED]) 
                      for(int v : graph[u]) 
                           if (dist[pairV[v]] == Integer.MAX_VALUE) {
                              dist[pairV[v]] = dist[u] + 1;
                              q.add(pairV[v]);
                          }  
             }

            return dist[UNMATCHED] != Integer.MAX_VALUE; 
         }

        boolean dfs(int u) {
               if (u != UNMATCHED){
                  for(int v : graph[u])
                       if (dist[pairV[v]] == dist[u] + 1 && dfs(pairV[v])){
                          pairU[u] = v ;
                          pairV[v] = u ;
                           return true; 
                        }  

                  dist[u] = Integer.MAX_VALUE;

                   return false; 
               }

             return true;    
        }

        int hopcroftKarp(ArrayList<Integer>[] graph,int U, int V) {
              this.graph=graph;

              pairU = new int[U+1];
              pairV = new int[V+1]; 
              dist  = new int[U+1];  

             for(int u=0;u<=U;++u) 
                   pairU[u] = UNMATCHED ;     

               boolean matching = true;
                 int size = 0;   

            while (matching){
                     matching = false;  
                       for(int u=1;u<=U;++u) 
                            if (pairU[u] == UNMATCHED && dfs(u)) {
                               ++size ;
                               matching = true;   
                           }    

                      if (matching){  
                         for(int u=1;u<=U;++u) 
                              if (pairU[u] == UNMATCHED && dfs(u)) {
                                 ++size ;
                                  matching = true;   
                             }    
                       }     
                }       

              return size;  
         }      
    }

