Here's an oversimplified representation in Python of what you might need for a min heap, which can be used as a basic priority queue:
```python
class MinHeap:
    def __init__(self):
        self._data = []
        self._key_index_map = {}  # Record the position (index) in data list of each node.

    @property
    def size(self):
        return len(self._data)

    def _swap(self, i, j):
        self._data[i], self._data[j] = self._data[j], self._data[i]
        # Update the index map after swap.
        self._key_index_map[self._data[i][0]] = i 
        self._key_index_map[self._data[j][0]] = j

    def _heapify(self, idx):
        smallest = idx
        left = 2 * idx + 1
        right = 2 * idx + 2

        if (left < self.size and self._data[smallest] > self._data[left]):
            smallest = left 

        if (right < self.size and self._data[smallest] > self._data[right]):
            smallest = right

        if smallest != idx:
            self._swap(idx, smallest)
            self._heapify(smallest)

    def push(self, key):
        item = (key, len(self._data))  # The pair (key, index).
        self._data.append(item)
        self._key_index_map[key] = len(self._data) - 1  # Update the index map after appending.

    def pop(self):
        if not self._data:
            return None

        root = self._data[0][0]
        last_item = self._data.pop()
        if len(self._data) > 0:  # After pop operation, the heap might become empty.
            self._key_index_map[last_item[0]] = 0  
            self._swap(0, -1)
            del self._key_index_map[root]
            self._heapify(0)  # Heapify from root again after swap operation.
        return root  # Return the minimum item (the root node).

    def decrease_key(self, old_key, new_key):
        if not old_key in self._key_index_map:
            raise ValueError("old key is not in heap.")

        if new_key > old_key:   # New key should be less than or equal to old key.
            raise ValueError("new key is greater than old key")

        idx = self._key_index_map[old_key]
        self._data[idx] = (new_key, idx)  # Update the new key-value pair in heap array.

        while(idx > 0 and self._data[(idx - 1) // 2][0] > self._data[idx][0]):  
            parent = (idx - 1) // 2
            self._swap(parent, idx)
            idx = parent
```
This implementation supports `push`, `pop` and `decrease_key` operations in worst case O(log n), which satisfies the requirement. The `decrease_key` operation has a complexity of O(n). You can further improve this by using a Fibonacci Heap data structure (which is more complicated to implement than MinHeap) but it provides better amortized time complexity for these operations: insertion, deletion and decrease-key.

