```go
package main

import (
	"context"
	"fmt"
	"time"

	clientv3 "go.etcd.io/etcd/client/v3"
)

type LeaseLock struct {
	LeaseID clientv3.LeaseID
	Key     string
	Client  *clientv3.Client
}

func NewLeaseLock(key string, ttl int64, endpoints []string) (*LeaseLock, error) {
	cli, err := clientv3.New(clientv3.Config{Endpoints: endpoints})
	if err != nil {
		return nil, fmt.Errorf("error creating etcd client: %v", err)
	}

	// create a lease and acquire it
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	leaseResp, err := cli.Grant(ctx, ttl)
	cancel()
	if err != nil {
		return nil, fmt.Errorf("error creating etcd lease: %v", err)
	}

	// create a txn to set the key if it doesn't exist with our new lease
	txn := cli.Txn(context.Background())
	txnResp, err := txn.If(clientv3.Compare(clientv3.CreateRevision(key), "=", 0)).
		Then(clientv3.OpPut(key, "", clientv3.WithLease(leaseResp.ID))).
		Commit()
	if err != nil {
		return nil, fmt.Errorf("error creating etcd txn: %v", err)
	}

	// if the key didn't exist in the txn response, we failed to acquire the lock
	if !txnResp.Succeeded {
		return nil, fmt.Errorf("failed to acquire lease")
	}

	return &LeaseLock{
		LeaseID: leaseResp.ID,
		Key:     key,
		Client:  cli,
	}, nil
}

func (l *LeaseLock) Refresh(ctx context.Context) error {
	// extend the ttl of our lease
	_, err := l.Client.KeepAliveOnce(ctx, l.LeaseID)
	return err
}

// example usage:
func main() {
	lock, err := NewLeaseLock("my-key", 5 /* TTL in seconds */, []string{"localhost:2379"})
	if err != nil {
		fmt.Println(err)
		return
	}

	// keep refreshing the lease until our program ends or we want to give up
	for {
		err := lock.Refresh(context.Background())
		if err != nil {
			fmt.Printf("error keeping alive lease: %v", err)
			return // perhaps retry, logging, etc
		}

		// do work here...

		time.Sleep(1 * time.Second)
	}
}
```

This code creates a lock by using etcd's transactions to set the key if it doesn't exist with a new lease. If another process already holds the lock, this operation will fail and we know that our process could not acquire the lock.

