  receive(otherTimestamp) {
    if (typeof otherTimestamp !== 'undefined' && typeof otherTimestamp === 'number'){
      this.timestamp = Math.max(this.timestamp, otherTimestamp) + 1;
    } else {
      throw new Error('Invalid timestamp');
    }
  }
}

