```javascript
const sharp = require('sharp');
const fs = require('fs');

async function resize() {
    try {
        // Read the original image
        const imageBuffer = await fs.promises.readFile('./path_to_your_image')

        // Resize and crop the image
        const resizedImageBuffer = await sharp(imageBuffer)
            .resize(300, 300)   // resize image to 300x300 pixels
            .crop(sharp.fit.cover)    // crops image cover to fit aspect ratio of image
            .toBuffer();              // convert the sharp object back into a Buffer

        // Write resized and cropped image back to file
