import java.util.*;
public class Main {
    public static boolean areParenthesesBalanced(String exp) {
        Stack<Character> stack = new Stack<>();

        for (int i = 0; i < exp.length(); i++) {
            char ch = exp.charAt(i);

            switch(ch){
                case '(': 
                    stack.push(')'); break;
                case '{': 
                    stack.push('}'); break;
                case '[': 
                    stack.push(']'); break;
                case '<': // new case
                    stack.push('>'); break;                    
                default: // at this point, we have a closing bracket
