```go
package main

import (
	"fmt"
	"sync"
)

func main() {
	var arenaPool = sync.Pool{
		New: func() interface{} {
			return new(arena.Arena) // Initialize a new Arena instance when the pool is empty.
		},
	}

	// Get an Arena from the Pool.
	a := arenaPool.Get().(*arena.Arena)

	// Use your Arena here...
