import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.concurrent.locks.*;

public class ConsensusModule implements Runnable {
    public enum MessageType { PROPOSE, ACK, DECIDE }

    public static class Message {
        public final MessageType type;
        public final int senderId;
        public final Object value;

        public Message(MessageType type, int senderId, Object value) {
            this.type = type;
            this.senderId = senderId;
            this.value = value;
        }
    }

    private final int nodeId;
    private final Set<Integer> peers;
    private final Network network;
    private final BlockingQueue<Message> inbox;

    private final ReentrantLock lock = new ReentrantLock();
    private final Condition decidedCond = lock.newCondition();

    private volatile boolean decided = false;
    private volatile Object decidedValue = null;
    private volatile Object pendingProposal = null;
    private final AtomicInteger pendingAckCount = new AtomicInteger(0);

    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private volatile boolean running = true;

    public ConsensusModule(int nodeId, Set<Integer> peers, Network network) {
        this.nodeId = nodeId;
        this.peers = peers;
        this.network = network;
        this.inbox = network.getInbox(nodeId);
    }

    public void start() {
        Thread t = new Thread(this, "ConsensusNode-" + nodeId);
        t.setDaemon(true);
        t.start();

        // Fallback leader election: if no decision after 10 seconds, propose a value.
        scheduler.scheduleAtFixedRate(() -> {
            if (!decided) {
                // If we haven't decided yet, try to become proposer by proposing a default value.
                // In a real protocol you would run a leader election first.
                // Here we simply retry the proposal once.
                // The retry is safe because the node only proposes if it hasn't decided yet.
                if (pendingProposal == null) {
                    // choose a deterministic value based on nodeId to avoid collisions
                    try {
                        propose(nodeId);
                    } catch (Exception e) {
                        // ignore
                    }
                }
            }
        }, 10, 10, TimeUnit.SECONDS);
    }

    /**
     * Propose a value and wait until consensus is reached.
     *
     * @param value the value to propose
     * @return the agreed value
     */
    public Object propose(Object value) throws Exception {
        lock.lock();
        try {
            // Reset state for a new round
            decided = false;
            decidedValue = null;
            pendingProposal = value;
            pendingAckCount.set(1); // count self as an implicit ACK

            // Broadcast PROPOSE to all peers
            for (int peer : peers) {
                network.send(nodeId, peer, new Message(MessageType.PROPOSE, nodeId, value));
            }

            // Wait for decision or timeout
            long deadline = System.currentTimeMillis() + 5000; // 5 seconds timeout
            while (!decided && System.currentTimeMillis() < deadline) {
                decidedCond.await(deadline - System.currentTimeMillis(), TimeUnit.MILLISECONDS);
            }

            // If we still haven't decided after timeout, we treat this as a failure
            // and let the periodic background task retry later.
            if (!decided) {
                // The pending proposal is cleared so that a future round can start.
                pendingProposal = null;
                throw new Exception("Consensus timed out for value: " + value);
            }

            return decidedValue;
        } finally {
            lock.unlock();
        }
    }

    public Object getDecision() {
        lock.lock();
        try {
            while (!decided) {
                decidedCond.await();
            }
            return decidedValue;
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return null;
        } finally {
            lock.unlock();
        }
    }

    public void shutdown() {
        running = false;
        scheduler.shutdownNow();
    }

    @Override
    public void run() {
        while (running) {
            try {
                Message msg = inbox.poll(1, TimeUnit.SECONDS);
                if (msg != null) {
                    handleMessage(msg);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    private void handleMessage(Message msg) {
        switch (msg.type) {
            case PROPOSE:
                // Always ACK a proposal (accept phase)
                network.send(nodeId, msg.senderId, new Message(MessageType.ACK, nodeId, msg.value));
                // If we haven't decided yet, we also treat this as a potential value.
                // In a full consensus protocol we would store promises, but for the simple demo
                // we just store the value as pending if we haven't decided yet.
                lock.lock();
                try {
                    if (!decided && pendingProposal == null) {
                        // Accept the proposal as our own if we haven't proposed anything.
                        pendingProposal = msg.value;
                        pendingAckCount.set(1);
                        // We can also try to become a leader by broadcasting PROPOSE again.
                        // For the demo we simply rely on the background task.
                    }
                } finally {
                    lock.unlock();
                }
                break;

            case ACK:
                // Only count ACKs for the value we are currently proposing.
                if (pendingProposal != null && Objects.equals(msg.value, pendingProposal)) {
                    int cnt = pendingAckCount.incrementAndGet();
                    if (cnt >= majority() && !decided) {
                        setDecided(msg.value);
                        // Broadcast DECIDE to make everyone commit.
                        for (int peer : peers) {
                            network.send(nodeId, peer, new Message(MessageType.DECIDE, nodeId, msg.value));
                        }
                    }
                }
                break;

            case DECIDE:
                // Once we see a DECIDE we lock in the value.
                setDecided(msg.value);
                break;
        }
    }

    private int majority() {
        // For a system that can tolerate one crash we need a majority of size > total/2.
        return peers.size() / 2 + 1;
    }

    private void setDecided(Object value) {
        lock.lock();
        try {
            if (!decided) {
                decided = true;
                decidedValue = value;
                pendingProposal = null; // clear pending after decision
                decidedCond.signalAll();
            }
        } finally {
            lock.unlock();
        }
    }
}
