package main

import (
    "context"
    "fmt"
    "log"
    "net"
    "os"
    "sync"
    "time"

    "google.golang.org/grpc"
    pb "github.com/yourname/yourproject/proto" // Update import path
)

const (
    leaseDuration = 5 * time.Second
)

type lockState struct {
    holder    string
    timestamp int64
    expiry    time.Time
}

type LockServer struct {
    pb.UnimplementedLockServiceServer
    mu     sync.Mutex
    locks  map[string]*lockState
    nodeID string
}

func newLockServer(nodeID string) *LockServer {
    return &LockServer{
        locks:  make(map[string]*lockState),
        nodeID: nodeID,
    }
}

func (s *LockServer) Acquire(ctx context.Context, req *pb.LockRequest) (*pb.LockResponse, error) {
    s.mu.Lock()
    defer s.mu.Unlock()

    now := time.Now()
    state, ok := s.locks[req.LockId]

    if !ok || now.After(state.expiry) {
        s.locks[req.LockId] = &lockState{
            holder:    req.HolderId,
            timestamp: req.Timestamp,
            expiry:    now.Add(leaseDuration),
        }
        fmt.Printf("[Node %s] Granted lock %s to %s\n", s.nodeID, req.LockId, req.HolderId)
        return &pb.LockResponse{Granted: true}, nil
    }

    if state.holder == req.HolderId && req.Timestamp >= state.timestamp {
        state.timestamp = req.Timestamp
        state.expiry = now.Add(leaseDuration)
        fmt.Printf("[Node %s] Renewed lock %s for %s\n", s.nodeID, req.LockId, req.HolderId)
        return &pb.LockResponse{Granted: true}, nil
    }

    fmt.Printf("[Node %s] Denied lock %s to %s (held by %s)\n", s.nodeID, req.LockId, req.HolderId, state.holder)
    return &pb.LockResponse{Granted: false}, nil
}

func (s *LockServer) Release(ctx context.Context, req *pb.ReleaseRequest) (*pb.ReleaseResponse, error) {
    s.mu.Lock()
    defer s.mu.Unlock()

    state, ok := s.locks[req.LockId]
    if ok && state.holder == req.HolderId {
        delete(s.locks, req.LockId)
        fmt.Printf("[Node %s] Released lock %s by %s\n", s.nodeID, req.LockId, req.HolderId)
        return &pb.ReleaseResponse{Released: true}, nil
    }
    return &pb.ReleaseResponse{Released: false}, nil
}

func (s *LockServer) Renew(ctx context.Context, req *pb.RenewRequest) (*pb.RenewResponse, error) {
    s.mu.Lock()
    defer s.mu.Unlock()

    now := time.Now()
    state, ok := s.locks[req.LockId]

    if ok && state.holder == req.HolderId && req.Timestamp >= state.timestamp && now.Before(state.expiry) {
        state.expiry = now.Add(leaseDuration)
        fmt.Printf("[Node %s] Renewed lock %s for %s\n", s.nodeID, req.LockId, req.HolderId)
        return &pb.RenewResponse{Renewed: true}, nil
    }
    return &pb.RenewResponse{Renewed: false}, nil
}

func main() {
    if len(os.Args) != 3 {
        log.Fatal("Usage: go run server.go <node_id> <port>")
    }
    nodeID := os.Args[1]
    port := os.Args[2]

    lis, err := net.Listen("tcp", port)
    if err != nil {
        log.Fatalf("Failed to listen: %v", err)
    }

    s := grpc.NewServer()
    pb.RegisterLockServiceServer(s, newLockServer(nodeID))
    fmt.Printf("Node %s listening on %s\n", nodeID, port)
    if err := s.Serve(lis); err != nil {
        log.Fatalf("Failed to serve: %v", err)
    }
}
