func (s *LockServer) Acquire(ctx context.Context, req *pb.LockRequest) (*pb.LockResponse, error) {
    s.mu.Lock()
    defer s.mu.Unlock()

    state, ok := s.locks[req.LockId]
    now := time.Now()

