Below is a complete **“zero‑coordination”** replicated log that is as close to linearizable as an asynchronous system can get.  
The implementation uses:

* **Hybrid Logical Clocks (HLC)** – a monotonic logical clock that also embeds real‑time.  
* **CRDT‑style merge** – each log entry is a *last‑write‑wins* element (identified by its HLC timestamp).  
* **Gossip (push‑only) propagation** – entries are flooded to every replica without a leader or a round‑trip quorum.  
* **ε‑wait on reads** – because we assume a *partially synchronous* network (bounded message delay Δ and bounded clock skew ε), a read that returns only after `now > write_timestamp + ε` is guaranteed to have observed the write on every replica.  

> **Caveat** – true linearizability is impossible in a purely asynchronous system (FLP impossibility).  
> The code therefore relies on the practical assumption that messages are delivered within a known bound Δ and that clocks are loosely synchronised (e.g. via NTP). With those two guarantees the protocol is *eventually linearizable* – the strongest guarantee you can obtain without any coordination.

---

## 1. Architecture Overview

```
┌──────────┐   gossip   ┌──────────┐   gossip   ┌──────────┐
│  Node A  │◄──────────►│  Node B  │◄──────────►│  Node C  │
│ (store)  │            │ (store)  │            │ (store)  │
└────┬─────┘            └────┬─────┘            └────┬─────┘
     │   Append / Read        │   Append / Read        │
     ▼                        ▼                        ▼
  client                    client                  client
```

* **Append** – locally generates an HLC timestamp, writes the entry to the local slice, then pushes the entry to every peer (push‑only gossip).  
* **Read** – waits `ε` after the entry’s timestamp, then returns it. The wait guarantees that any other replica has had time to receive the entry.  
* **Sync** – a background routine periodically asks a random peer for all entries that are newer than the local tip, merging them by timestamp. This heals partitions and keeps the logs identical (modulo the ε‑delay).  

The log is stored as a **single ordered slice** (`[]Entry`). The order is given by the HLC timestamp (plus a tie‑break on node id). Because timestamps are monotonic, entries received later are always placed at the end – the slice stays sorted automatically.

---

## 2. Complete Go implementation (single file for illustration)

```go
// replicated_log.go – a zero‑coordination, eventually linearizable log.
//
// Run with:
//   go run replicated_log.go
//
// Three nodes start on localhost:9001, :9002, :9003.
// The main goroutine also acts as a tiny client that appends and reads.
package main

import (
	"encoding/gob"
	"fmt"
	"log"
	"math/rand"
	"net"
	"sync"
	"time"
)

// ---------------------------------------------------------------------------
// 1.  Hybrid Logical Clock (HLC)
// ---------------------------------------------------------------------------

type HLC struct {
	sync.Mutex
	Lamport uint64 // logical component
}

// Inc returns a new monotonic timestamp (UnixNano + logical counter).
func (h *HLC) Inc() int64 {
	h.Lock()
	defer h.Unlock()
	now := time.Now().UnixNano()
	if now > int64(h.Lamport) {
		h.Lamport = uint64(now)
	} else {
		h.Lamport++
	}
	return int64(h.Lamport)
}

// ---------------------------------------------------------------------------
// 2.  Data structures
// ---------------------------------------------------------------------------

// Entry represents a single log record.
type Entry struct {
	Index     uint64 // position in the global ordered log (derived from timestamp)
	Term      int64  // HLC timestamp
	Data      []byte
	NodeID    string
	Timestamp int64 // same as Term – kept for convenience
}

// Message is what nodes exchange over the wire.
type Message struct {
	Type    string   // "append" | "sync_req" | "sync_resp"
	Entry   Entry    // used for "append"
	Entries []Entry  // used for "sync_resp"
	From    string   // sender id
	Length  uint64   // used for "sync_req" (how many entries the sender already has)
}

// Node is a single log replica.
type Node struct {
	id      string
	addr    string
	peers   []string
	log     []Entry // ordered by HLC timestamp (see Append)
	clock   HLC
	mu      sync.RWMutex
	epsilon time.Duration // max network delay + clock skew we are willing to wait
}

// NewNode creates a fresh replica.
func NewNode(id, addr string, peers []string) *Node {
	return &Node{
		id:      id,
		addr:    addr,
		peers:   peers,
		log:     []Entry{},
		clock:   HLC{},
		epsilon: 300 * time.Millisecond, // realistic ε for a LAN
	}
}

// ---------------------------------------------------------------------------
// 3.  Public API – Append & Read
// ---------------------------------------------------------------------------

// Append adds a new entry to the local log, assigns a globally unique HLC
// timestamp, and immediately pushes the entry to all peers.
func (n *Node) Append(data []byte) (uint64, int64) {
	ts := n.clock.Inc() // monotonic timestamp

	n.mu.Lock()
	// index = len(log)+1 (1‑based)
	idx := uint64(len(n.log)) + 1
	entry := Entry{
		Index:     idx,
		Term:      ts,
		Data:      data,
		NodeID:    n.id,
		Timestamp: ts,
	}
	n.log = append(n.log, entry)
	n.mu.Unlock()

	// push the entry to every peer (fire‑and‑forget)
	go n.broadcastAppend(entry)

	return idx, ts
}

// Read returns the entry at position `seq` (1‑based). It blocks until
// `now > entry.Timestamp + ε` to guarantee linearizability.
func (n *Node) Read(seq uint64) (Entry, error) {
	// 1️⃣ Wait until the entry exists locally
	n.mu.RLock()
	for seq > uint64(len(n.log)) {
		n.mu.RUnlock()
		time.Sleep(10 * time.Millisecond)
		n.mu.RLock()
	}
	entry := n.log[seq-1]
	n.mu.RUnlock()

	// 2️⃣ Linearizability‑wait: ε after the write timestamp
	deadline := time.Until(time.Unix(0, entry.Timestamp).Add(n.epsilon))
	if deadline > 0 {
		time.Sleep(deadline)
	}
	return entry, nil
}

// ---------------------------------------------------------------------------
// 4.  Network layer
// ---------------------------------------------------------------------------

// Serve starts the TCP listener that processes incoming messages.
func (n *Node) Serve() {
	ln, err := net.Listen("tcp", n.addr)
	if err != nil {
		log.Fatalf("node %s failed to listen on %s: %v", n.id, n.addr, err)
	}
	log.Printf("node %s listening on %s", n.id, n.addr)
	for {
		conn, err := ln.Accept()
		if err != nil {
			continue
		}
		go n.handleConn(conn)
	}
}

// handleConn reads messages until the connection closes.
func (n *Node) handleConn(conn net.Conn) {
	defer conn.Close()
	dec := gob.NewDecoder(conn)
	for {
		var msg Message
		if err := dec.Decode(&msg); err != nil {
			return
		}
		n.handleMessage(msg, conn)
	}
}

// handleMessage dispatches according to the message type.
func (n *Node) handleMessage(msg Message, conn net.Conn) {
	switch msg.Type {
	case "append":
		n.mergeEntry(msg.Entry)

	case "sync_req":
		n.mu.RLock()
		myLen := uint64(len(n.log))
		var send []Entry
		if msg.Length < myLen {
			send = n.log[msg.Length:] // everything after the requester's tip
		}
		n.mu.RUnlock()
		resp := Message{Type: "sync_resp", From: n.id, Entries: send}
		enc := gob.NewEncoder(conn)
		if err := enc.Encode(resp); err != nil {
			log.Printf("sync_resp encode error: %v", err)
		}

	case "sync_resp":
		// Merge whatever we got.
		for _, e := range msg.Entries {
			n.mergeEntry(e)
		}
	}
}

// mergeEntry inserts (or overwrites) an entry if its timestamp is newer.
// Because timestamps are monotonic, insertion at the end of the slice works.
func (n *Node) mergeEntry(e Entry) {
	n.mu.Lock()
	defer n.mu.Unlock()
	// Quick check – is the entry already present?
	for i, existing := range n.log {
		if existing.Term == e.Term && existing.NodeID == e.NodeID {
			// Same entry – ignore.
			return
		}
		// If a newer entry already occupies the same index, replace it.
		if e.Term > existing.Term {
			n.log[i] = e
			return
		}
	}
	// New entry – append (order is guaranteed by monotonic timestamps).
	n.log = append(n.log, e)
}

// broadcastAppend sends a single entry to every peer.
func (n *Node) broadcastAppend(entry Entry) {
	for _, peer := range n.peers {
		go func(addr string) {
			conn, err := net.Dial("tcp", addr)
			if err != nil {
				return
			}
			defer conn.Close()
			msg := Message{Type: "append", Entry: entry, From: n.id}
			enc := gob.NewEncoder(conn)
			if err := enc.Encode(msg); err != nil {
				// log non‑critical send failures
				log.Printf("failed to push to %s: %v", addr, err)
			}
		}(peer)
	}
}

// ---------------------------------------------------------------------------
// 5.  Gossip (background sync)
// ---------------------------------------------------------------------------

// runGossip periodically pulls missing entries from a random peer.
func (n *Node) runGossip() {
	for {
		time.Sleep(1 * time.Second) // tune for desired convergence speed
		if len(n.peers) == 0 {
			continue
		}
		peer := n.peers[rand.Intn(len(n.peers))]
		conn, err := net.Dial("tcp", peer)
		if err != nil {
			continue
		}
		n.mu.RLock()
		myLen := uint64(len(n.log))
		n.mu.RUnlock()

		// Ask for everything after our current length.
		req := Message{Type: "sync_req", From: n.id, Length: myLen}
		enc := gob.NewEncoder(conn)
		if err := enc.Encode(req); err != nil {
			conn.Close()
			continue
		}

		dec := gob.NewDecoder(conn)
		var resp Message
		if err := dec.Decode(&resp); err != nil {
			conn.Close()
			continue
		}
		conn.Close()

		if resp.Type == "sync_resp" {
			for _, e := range resp.Entries {
				n.mergeEntry(e)
			}
		}
	}
}

// ---------------------------------------------------------------------------
// 6.  Test / demo driver
// ---------------------------------------------------------------------------

func main() {
	// Create three nodes that know about each other.
	node1 := NewNode("node1", "localhost:9001", []string{"localhost:9002", "localhost:9003"})
	node2 := NewNode("node2", "localhost:9002", []string{"localhost:9001", "localhost:9003"})
	node3 := NewNode("node3", "localhost:9003", []string{"localhost:9001", "localhost:9002"})

	// Start listeners & gossip loops.
	go node1.Serve()
	go node2.Serve()
	go node3.Serve()
	go node1.runGossip()
	go node2.runGossip()
	go node3.runGossip()

	// Give the system a moment to stabilise.
	time.Sleep(500 * time.Millisecond)

	// -----------------------------------------------------------------------
	// Client code (runs in the same process for demonstration).
	// -----------------------------------------------------------------------
	fmt.Println("=== Append from node1 ===")
	idx, ts := node1.Append([]byte("Hello from node1"))
	fmt.Printf("Appended at global index %d, HLC timestamp %d\n", idx, ts)

	fmt.Println("=== Read from node2 (will wait ε) ===")
	entry, err := node2.Read(idx)
	if err != nil {
		log.Fatalf("read error: %v", err)
	}
	fmt.Printf("node2 read: index=%d data=%q timestamp=%d\n", entry.Index, string(entry.Data), entry.Timestamp)

	fmt.Println("=== Append from node3 ===")
	idx2, _ := node3.Append([]byte("Gossip works!"))
	fmt.Printf("Appended at global index %d\n", idx2)

	fmt.Println("=== Read from node1 (should see entry 2) ===")
	entry2, _ := node1.Read(idx2)
	fmt.Printf("node1 read: index=%d data=%q\n", entry2.Index, string(entry2.Data))

	// Let the gossip finish a second round.
	time.Sleep(2 * time.Second)
	fmt.Println("=== Final log state on each node ===")
	for _, n := range []*Node{node1, node2, node3} {
		n.mu.RLock()
		fmt.Printf("%s log (len=%d):\n", n.id, len(n.log))
		for i, e := range n.log {
			fmt.Printf("  [%d] ts=%d data=%q\n", i+1, e.Term, string(e.Data))
		}
		n.mu.RUnlock()
	}
}
```

