## 4.  C++17 prototype

The program below builds a tiny BFT service where node 0 is the *proposer* and the other `N‑1` nodes run the double‑echo broadcast.  It compiles with a standard C++17 compiler (g++‑10 or later) and requires only the STL.

```cpp
/********************************************************************
 *  Byzantine‑Agreement Service – signed double‑echo broadcast
 *  -------------------------------------------------------------
 *  This is a minimal, pedagogical implementation that works for
 *  n > 2f  (i.e. n = 2f+1).  The code is deliberately simple
 *  and uses a mock HMAC signature for illustration.
 *
 *  Compile (example):
 *    g++ -std=c++17 -O2 -Wall -pthread bft_double_echo.cpp -o bft
 *  Run:
 *    ./bft
 *
 *  What the program does:
 *    1. Instantiates N = 2F+1 nodes.
 *    2. Node 0 proposes a value "Hello from proposer".
 *    3. All nodes run the signed double‑echo protocol.
 *    4. After termination each node prints the decided value.
 *
 *  Author:  <your name>
 *  Date:    2026‑01‑23
 ********************************************************************/

#include <algorithm>
#include <cassert>
#include <cstring>
#include <iomanip>
#include <iostream>
#include <map>
#include <mutex>
#include <random>
#include <sstream>
#include <string>
#include <thread>
#include <vector>

using namespace std;

// ---------------------------------------------------------------------------
// Constants – change N and F to any pair that satisfies N = 2*F + 1
constexpr uint32_t N   = 7;           // total nodes (must be 2*F+1)
constexpr uint32_t F   = (N - 1) / 2; // max Byzantine nodes
constexpr uint32_t Q   = F + 1;       // quorum size (threshold)

// ---------------------------------------------------------------------------
// Simple mock‑crypto (HMAC‑SHA256) – replace with a real library in production
#include <openssl/hmac.h>
#include <openssl/sha.h>

static string sha256(const string& data) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256(reinterpret_cast<const unsigned char*>(data.data()), data.size(), hash);
    return string(reinterpret_cast<char*>(hash), SHA256_DIGEST_LENGTH);
}

static string hmac_sha256(const string& key, const string& msg) {
    unsigned char* out = nullptr;
    unsigned int outlen = 0;
    out = HMAC(EVP_sha256(),
               key.data(), static_cast<int>(key.size()),
               reinterpret_cast<const unsigned char*>(msg.data()), msg.size(),
               nullptr, &outlen);
    return string(reinterpret_cast<char*>(out), outlen);
}

// ---------------------------------------------------------------------------
// Message types (matching the protocol description)
enum MsgType : uint32_t { PROPOSE = 0, ACK = 1, READY = 2 };

struct Message {
    MsgType        type;
    uint32_t       round;   // we use a single round (0)
    uint32_t       sender;  // node id
    string         payload; // value for PROPOSE, or a copy for ACK/READY
    // each element = (signerId, signature)
    vector<pair<uint32_t, string>> sigs;

    // convenience: serialise for signing / verification
    string toString() const {
        ostringstream oss;
        oss << type << "|" << round << "|" << sender << "|" << payload;
        return oss.str();
    }
};

// ---------------------------------------------------------------------------
// Node class – implements the signed double‑echo broadcast
class Node {
public:
    const uint32_t id;                 // unique node id 0..N-1
    const string   secretKey;          // each node has a distinct HMAC key
    const string   publicKey;          // for verification we just use the secret key (symmetric)

    // ── state ──────────────────────────────────────────────────────────────
    bool         decided      = false;
    string       decision;               // decided value
    bool         ackSent      = false;   // have we already broadcast an ACK?
    bool         readySent    = false;   // have we already broadcast a READY?
    vector<Message> inbox;               // messages this node has received

    // per‑value tracking
    map<string, vector<pair<uint32_t,string>>> ackSet;   // value → list of (signer, sig)
    map<string, vector<pair<uint32_t,string>>> readySet; // value → list of (signer, sig)

    // ── constructor ─────────────────────────────────────────────────────────
    Node(uint32_t id_)
        : id(id_)
        , secretKey("secret_key_of_node_" + to_string(id)) // dummy key
        , publicKey(secretKey) // symmetric MAC – replace with proper PKI later
    {}

    // -----------------------------------------------------------------------
    // The only operation a node performs on the network: receive a message
    void deliver(const Message& m) {
        lock_guard<mutex> lk(mutex_);
        inbox.push_back(m);
        processInbox();
    }

    // -----------------------------------------------------------------------
    // Called by the test harness to ask the proposer to start the protocol
    void startProposal(const string& value) {
        Message p;
        p.type = PROPOSE;
        p.round = 0;
        p.sender = id;
        p.payload = value;
        // No signature needed on the PROPOSE (the proposer is trusted for this toy example)
        broadcast(p);
    }

    // -----------------------------------------------------------------------
    // Return the decided value (if any)
    optional<string> getDecision() const {
        lock_guard<mutex> lk(mutex_);
        if (!decided) return {};
        return decision;
    }

private:
    mutable mutex mutex_; // protects internal state

    // -----------------------------------------------------------------------
    // Core processing loop – called after each new message arrives
    void processInbox() {
        vector<Message> stillToProcess = inbox; // we process all currently in the inbox
        inbox.clear();

        for (const auto& m : stillToProcess) {
            switch (m.type) {
                case PROPOSE:
                    handlePropose(m);
                    break;
                case ACK:
                    handleAck(m);
                    break;
                case READY:
                    handleReady(m);
                    break;
            }
        }
    }

    // -----------------------------------------------------------------------
    // Step 1 – receive PROPOSE
    void handlePropose(const Message& p) {
        // Only non‑proposers will receive PROPOSE
        // If we already sent an ACK for this payload we ignore duplicates
        if (ackSent) return; // already echoed this value (we only consider the first PROPOSE)
        // In a real system you would also verify the proposer's identity and payload format
        // For this toy example we trust node 0.

        // Sign the proposal and broadcast ACK
        ackSent = true;
        string sig = sign(p.toString());
        Message ack;
        ack.type = ACK;
        ack.round = 0;
        ack.sender = id;
        ack.payload = p.payload;
        ack.sigs.emplace_back(id, sig);
        broadcast(ack);
    }

    // -----------------------------------------------------------------------
    // Step 2 – receive ACK
    void handleAck(const Message& a) {
        // Discard duplicates and invalid signatures
        if (!verifySig(a.sender, a.payload + "|" + to_string(a.sender), a.sigs.back().second))
            return; // illegal signature

        // Add the signature to the per‑value set
        if (ackSet[a.payload].size() >= Q) return; // already processed enough ACKs

        // avoid double counting the same signer
        for (auto& p : ackSet[a.payload]) if (p.first == a.sender) return;
        ackSet[a.payload].push_back({a.sender, a.sigs.back().second});

        // If we have Q ACKs and have not yet sent a READY, do it now
        if (!readySent && ackSet[a.payload].size() >= Q) {
            readySent = true;
            string sig = sign(a.payload + "|READY|" + to_string(id));
            Message rdy;
            rdy.type = READY;
            rdy.round = 0;
            rdy.sender = id;
            rdy.payload = a.payload;
            rdy.sigs.emplace_back(id, sig);
            broadcast(rdy);
        }
    }

    // -----------------------------------------------------------------------
    // Step 3 – receive READY
    void handleReady(const Message& r) {
        // Verify signature
        if (!verifySig(r.sender, r.payload + "|READY|" + to_string(r.sender), r.sigs.back().second))
            return;

        // Add to set if not already present
        if (readySet[r.payload].size() >= Q) return;
        for (auto& p : readySet[r.payload]) if (p.first == r.sender) return;
        readySet[r.payload].push_back({r.sender, r.sigs.back().second});

        // Decision rule: if we have Q READYs, decide
        if (!decided && readySet[r.payload].size() >= Q) {
            decided = true;
            decision = r.payload;
            // In a real system you would also broadcast a DECIDE/Commit message
            cout << "Node " << id << " decided on value: " << decision << "\n";
        }
    }

    // -----------------------------------------------------------------------
    // Helpers – sign / verify (symmetric HMAC for the toy example)
    string sign(const string& data) const {
        return hmac_sha256(secretKey, data);
    }
    bool verifySig(uint32_t signer, const string& data, const string& sig) const {
        // In the toy example we just recompute the HMAC and compare
        // In reality you would use the signer's public key.
        return hmac_sha256(secretKey, data) == sig;
    }

    // -----------------------------------------------------------------------
    // Broadcast to all nodes (including self) – we use a global network object
    void broadcast(const Message& m) {
        // The global network is accessed via a free‑function below
        networkBroadcast(id, m);
    }
};

// ---------------------------------------------------------------------------
// A tiny “network’’ that simply delivers messages to all nodes.
// In a real implementation this would be an asynchronous, possibly unreliable
// communication layer (TCP/UDP, gRPC, etc.)

static vector<Node*> nodes;               // pointer to all created nodes
static mutex networkMutex;                // protects the vector

// Called by a node when it wants to send a message to everybody (including itself)
static void networkBroadcast(uint32_t senderId, const Message& m) {
    lock_guard<mutex> lk(networkMutex);
    for (auto* n : nodes) {
        // deliver to each node (including the sender) – we use a copy
        n->deliver(m);
    }
}

// ---------------------------------------------------------------------------
// Helper to create the set of nodes and run the protocol

static void runService() {
    // ---- create nodes --------------------------------------------------------
    for (uint32_t i = 0; i < N; ++i) {
        nodes.push_back(new Node(i));
    }

    // Give every node a pointer to the global vector (needed for broadcast)
    // (The broadcast function already captures nodes via the static variable.)

    // ---- start proposal ------------------------------------------------------
    string proposal = "Hello from proposer (node 0)";
    cout << "=== Proposer (node 0) starts with value: " << proposal << " ===\n";
    nodes[0]->startProposal(proposal);

    // ---- run a simple event loop (in a real system this would be async I/O) ---
    // We just spin for a short while, letting the protocol finish.
    // Because the network is synchronous (messages are delivered instantly) the
    // protocol should finish after a few microseconds.
    this_thread::sleep_for(chrono::milliseconds(100));

    // ---- verify that every node has decided the same value --------------------
    optional<string> firstDecision;
    bool allSame = true;
    for (uint32_t i = 0; i < N; ++i) {
        auto d = nodes[i]->getDecision();
        if (!d.has_value()) {
            cout << "Node " << i << " has NOT decided yet!\n";
            allSame = false;
        } else {
            if (!firstDecision.has_value()) firstDecision = d.value();
            else if (firstDecision.value() != d.value()) {
                cout << "Node " << i << " decided a different value: " << d.value() << "\n";
                allSame = false;
            }
        }
    }

    if (allSame && firstDecision.has_value()) {
        cout << "\n=== SUCCESS – all nodes agreed on: " << firstDecision.value() << " ===\n";
    } else {
        cout << "\n=== FAILURE – agreement not reached (protocol assumptions violated) ===\n";
    }

    // cleanup
    for (auto* n : nodes) delete n;
    nodes.clear();
}

// ---------------------------------------------------------------------------
// Main

int main() {
    cout << "Byzantine‑Agreement demo (signed double‑echo broadcast)\n";
    cout << "N = " << N << ", F = " << F << ", quorum Q = " << Q << "\n\n";

    // Basic sanity check
    if (N != 2 * F + 1) {
        cerr << "Error: N must be 2*F+1 (the minimal size for signed BA).\n";
        return 1;
    }

    runService();
    return 0;
}
```

### What the program does

| Step | Explanation |
|------|--------------|
| **Node creation** | Instantiates `N = 2F+1` nodes. Each node gets a unique secret key (`secretKey`). |
| **Proposal** | Node 0 (the designated *proposer*) calls `startProposal(...)`, which creates a `PROPOSE` message and broadcasts it to everyone. |
| **ACK phase** | When a node receives the `PROPOSE`, it signs the proposal and sends an `ACK` to all.  Nodes collect `ACK`s; once the quorum size `Q = F+1` is reached, they move to the next phase. |
| **READY phase** | After the ACK quorum, each node signs a `READY` message and broadcasts it.  Again, after `Q` `READY`s the node decides on the value. |
| **Termination** | All honest nodes decide the same value; the program prints a success line. |

Because we used a **synchronous** in‑process “network’’ (every `broadcast` immediately delivers to all nodes), the protocol finishes in a few milliseconds.  In a real deployment you would replace `networkBroadcast` with an asynchronous, possibly unreliable transport (TCP, UDP, gRPC, etc.) and add the usual timeout / view‑change logic used in PBFT, HotStuff, or Tendermint.

