The "Petrov bound" isn't a standard term in graph algorithms for maximum matching. It's possible you're referring to a specialized case or a misunderstanding. For **general graphs**, maximum matching requires at least \(O(n^{2.5})\) time (Edmonds' algorithm). For **bipartite graphs**, Hopcroft–Karp achieves \(O(E\sqrt{V})\), which is optimal for that class.

If you mean a specific algorithm under a different name (perhaps from Russian literature), please clarify. Otherwise, here’s a minimal working example for **maximum bipartite matching** in Java using Hopcroft–Karp:

```java
import java.util.*;

public class HopcroftKarp {
    private final int n, m;
    private final List<Integer>[] adj; // Graph (U to V)
    private int[] pairU, pairV, dist;

    @SuppressWarnings("unchecked")
    public HopcroftKarp(int n, int m) {
        this.n = n;
        this.m = m;
        adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        pairU = new int[n];
        pairV = new int[m];
        dist = new int[n];
        Arrays.fill(pairU, -1);
        Arrays.fill(pairV, -1);
    }

    public void addEdge(int u, int v) { // u in [0,n), v in [0,m)
        adj[u].add(v);
    }

    private boolean bfs() {
        Queue<Integer> q = new LinkedList<>();
        for (int u = 0; u < n; u++) {
            if (pairU[u] == -1) {
                dist[u] = 0;
                q.add(u);
            } else {
                dist[u] = Integer.MAX_VALUE;
            }
        }
        boolean found = false;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) {
                int pu = pairV[v];
                if (pu != -1 && dist[pu] == Integer.MAX_VALUE) {
                    dist[pu] = dist[u] + 1;
                    q.add(pu);
                }
                if (pu == -1) found = true;
            }
        }
        return found;
    }

    private boolean dfs(int u) {
        for (int v : adj[u]) {
            int pu = pairV[v];
            if (pu == -1 || (dist[pu] == dist[u] + 1 && dfs(pu))) {
                pairU[u] = v;
                pairV[v] = u;
                return true;
            }
        }
        dist[u] = Integer.MAX_VALUE;
        return false;
    }

    public int maxMatching() {
        int matching = 0;
        while (bfs()) {
            for (int u = 0; u < n; u++) {
                if (pairU[u] == -1 && dfs(u)) matching++;
            }
        }
        return matching;
    }

    public static void main(String[] args) {
        // Example: 4 U nodes, 4 V nodes, edges: (0,0),(0,1),(1,1),(2,2),(3,3)
        HopcroftKarp hk = new HopcroftKarp(4, 4);
        hk.addEdge(0, 0);
        hk.addEdge(0, 1);
        hk.addEdge(1, 1);
        hk.addEdge(2, 2);
        hk.addEdge(3, 3);
        System.out.println("Maximum matching size: " + hk.maxMatching()); // Output: 4
    }
}
```

