## 2. Python implementation (self‑contained)

```python
#!/usr/bin/env python3
"""
Strassen's fast matrix multiplication.

Public functions
----------------
multiply(A, B) -> C
    Multiply two square matrices A and B (must be square and have the same size).
    The size is automatically padded to the next power of two to keep the divide‑and‑conquer
    simple.  For tiny matrices (size <= BASE) a naive triple‑loop is used.

License: MIT (free to use in commercial projects)
"""

from typing import List
import numpy as np

# ------------------------------------------------------------
# Constants & helpers
# ------------------------------------------------------------
BASE: int = 64          # Switch to naïve multiplication below this size
EPS: float = 1e-9       # For sanity checks (not used in pure integer code)

def is_power_of_two(k: int) -> bool:
    return k > 0 and (k & (k - 1)) == 0

def next_power_of_two(k: int) -> int:
    """Return the smallest power of two >= k."""
    if is_power_of_two(k):
        return k
    return 1 << (k.bit_length())

def pad_to_power_of_two(M: List[List[float]]) -> List[List[float]]:
    """Pad a square matrix with zeros until its size is a power of two."""
    n = len(M)
    p = next_power_of_two(n)
    if p == n:
        return M
    # Build a (p x p) zero matrix and copy the original entries
    P = [[0.0] * p for _ in range(p)]
    for i in range(n):
        P[i][:n] = M[i]
    return P

def sub_matrix(A: List[List[float]], rs: int, cs: int, size: int) -> List[List[float]]:
    """Extract a contiguous sub‑matrix of `size` rows/cols starting at (rs, cs)."""
    return [row[cs:cs+size] for row in A[rs:rs+size]]

def add(A: List[List[float]], B: List[List[float]]) -> List[List[float]]:
    """Element‑wise addition of two same‑shaped matrices."""
    n = len(A)
    C = [[0.0] * n for _ in range(n)]
    for i in range(n):
        Ai = A[i]; Bi = B[i]; Ci = C[i]
        for j in range(n):
            Ci[j] = Ai[j] + Bi[j]
    return C

def sub(A: List[List[float]], B: List[List[float]]) -> List[List[float]]:
    """Element‑wise subtraction: A - B."""
    n = len(A)
    C = [[0.0] * n for _ in range(n)]
    for i in range(n):
        Ai = A[i]; Bi = B[i]; Ci = C[i]
        for j in range(n):
            Ci[j] = Ai[j] - Bi[j]
    return C

# ------------------------------------------------------------
# Naïve O(n³) multiplication (used for tiny blocks)
# ------------------------------------------------------------
def naive_multiply(A: List[List[float]], B: List[List[float]]) -> List[List[float]]:
    n = len(A)
    C = [[0.0] * n for _ in range(n)]
    for i in range(n):
        Ai = A[i]
        Ci = C[i]
        for k in range(n):
            aik = Ai[k]
            Bk = B[k]
            if aik != 0.0:               # tiny optimization
                for j in range(n):
                    Ci[j] += aik * Bk[j]
    return C

# ------------------------------------------------------------
# Strassen recursion
# ------------------------------------------------------------
def strassen(A: List[List[float]], B: List[List[float]]) -> List[List[float]]:
    n = len(A)
    # Base case: fall back to naïve multiplication for small sizes
    if n <= BASE:
        return naive_multiply(A, B)

    half = n // 2

    # Split A and B into quadrants
    A11 = sub_matrix(A, 0, 0, half)
    A12 = sub_matrix(A, 0, half, half)
    A21 = sub_matrix(A, half, 0, half)
    A22 = sub_matrix(A, half, half, half)

    B11 = sub_matrix(B, 0, 0, half)
    B12 = sub_matrix(B, 0, half, half)
    B21 = sub_matrix(B, half, 0, half)
    B22 = sub_matrix(B, half, half, half)

    # Compute the seven Strassen products
    M1 = strassen(add(A11, A22), add(B11, B22))
    M2 = strassen(add(A21, A22), B11)
    M3 = strassen(A11, sub(B12, B22))
    M4 = strassen(A22, sub(B21, B11))
    M5 = strassen(add(A11, A12), B22)
    M6 = strassen(sub(A21, A11), add(B11, B12))
    M7 = strassen(sub(A12, A22), add(B21, B22))

    # Combine the M's into the result quadrants
    C11 = add(sub(add(M1, M4), M5), M7)
    C12 = add(M3, M5)
    C21 = add(M2, M4)
    C22 = add(sub(add(M1, M2), M3), M6)

    # Stitch the quadrants together into a (n x n) matrix
    C = [[0.0] * n for _ in range(n)]
    for i in range(half):
        C[i][:half]          = C11[i]
        C[i][half:]          = C12[i]
        C[i + half][:half]   = C21[i]
        C[i + half][half:]   = C22[i]

    return C

# ------------------------------------------------------------
# Public API
# ------------------------------------------------------------
def multiply(A, B, *, pad=True):
    """
    Multiply two square matrices using Strassen's algorithm.

    Parameters
    ----------
    A, B : 2‑D array‑like (list of lists, numpy array, etc.)
        Must be square and have the same dimensions.
    pad : bool, default True
        If True, the matrices are automatically padded to the next power of two.
        Set to False only if you already guarantee power‑of‑two sizes.

    Returns
    -------
    C : list[list[float]]
        The product A·B as a plain Python list of lists.
    """
    # Convert to plain Python lists for uniform handling
    A = [list(row) for row in A]
    B = [list(row) for row in B]

    if len(A) != len(A[0]) or len(B) != len(B[0]):
        raise ValueError("Both A and B must be square matrices.")
    if len(A) != len(B):
        raise ValueError("Matrices A and B must have the same size.")

    if pad:
        A = pad_to_power_of_two(A)
        B = pad_to_power_of_two(B)

    return strassen(A, B)

# ------------------------------------------------------------
# Simple sanity test (you can run this file directly)
# ------------------------------------------------------------
if __name__ == "__main__":
    import random, sys

    def random_square_matrix(n):
        return [[random.random() for _ in range(n)] for _ in range(n)]

    for n in (63, 64, 65, 127, 128):
        A = random_square_matrix(n)
        B = random_square_matrix(n)

        # Our Strassen implementation
        C_strassen = multiply(A, B)

        # Reference using NumPy (double‑precision)
        C_ref = np.dot(np.array(A), np.array(B))

        # Compare (ignoring tiny floating‑point round‑off)
        diff = np.max(np.abs(np.array(C_strassen) - C_ref))
        print(f"n = {n:3d}  max |error| = {diff:.2e}")
        if diff > 1e-6:
            sys.exit("FAIL: results differ beyond tolerance")
    print("All tests passed.")
```

### What the code does

| Step | Explanation |
|------|-------------|
| **Padding** | `pad_to_power_of_two` expands the input to the next power of two so the divide‑and‑conquer recursion stays clean. |
| **Base case** | When the block size ≤ `BASE` (64 by default) we switch to a classic triple‑loop multiplication – this avoids the overhead of many small recursive calls. |
| **Strassen products** | The seven intermediate products `M1…M7` are computed recursively (each call reduces the problem size by a factor of 2). |
| **Combination** | The quadrants `C11, C12, C21, C22` are assembled from the `M`‑terms using only additions/subtractions, giving the final product. |
| **Return** | A plain Python list of lists is returned; if you need a NumPy array just wrap it: `np.array(multiply(A, B))`. |

