## 3. If you need a C++ version for maximum speed

Below is a lean C++17 implementation that mirrors the Python logic.  It uses `std::vector<std::vector<double>>` (or a flat `std::vector<double>` for cache‑friendliness) and a compile‑time constant `BASE_SIZE` for the naïve‑multiplication threshold.

```cpp
// strassen.hpp
#pragma once
#include <vector>
#include <cmath>      // for std::size_t
#include <algorithm>  // std::copy, std::fill
#include <stdexcept>

namespace fastmat {

using Matrix = std::vector<std::vector<double>>;

/* ---------- utilities ------------------------------------------------- */
static inline std::size_t next_power_of_two(std::size_t n) {
    if ((n & (n - 1)) == 0) return n;
    while ((n & (n - 1)) != 0) n &= n - 1;
    return n << 1;
}

/* Pad a square matrix to the next power of two (in‑place). */
void pad_to_power_of_two(Matrix &M) {
    std::size_t n = M.size();
    std::size_t p = next_power_of_two(n);
    if (p == n) return;
    M.resize(p, std::vector<double>(p, 0.0));
    for (auto &row : M) row.resize(p, 0.0);
}

/* Naïve O(n³) multiplication for tiny blocks. */
Matrix naive_mul(const Matrix &A, const Matrix &B) {
    std::size_t n = A.size();
    Matrix C(n, std::vector<double>(n, 0.0));
    for (std::size_t i = 0; i < n; ++i) {
        for (std::size_t k = 0; k < n; ++k) {
            double aik = A[i][k];
            if (aik == 0.0) continue;
            for (std::size_t j = 0; j < n; ++j) {
                C[i][j] += aik * B[k][j];
            }
        }
    }
    return C;
}

/* Element‑wise addition / subtraction. */
Matrix add(const Matrix &A, const Matrix &B) {
    std::size_t n = A.size();
    Matrix C(n, std::vector<double>(n));
    for (std::size_t i = 0; i < n; ++i)
        for (std::size_t j = 0; j < n; ++j)
            C[i][j] = A[i][j] + B[i][j];
    return C;
}
Matrix sub(const Matrix &A, const Matrix &B) {
    std::size_t n = A.size();
    Matrix C(n, std::vector<double>(n));
    for (std::size_t i = 0; i < n; ++i)
        for (std::size_t j = 0; j < n; ++j)
            C[i][j] = A[i][j] - B[i][j];
    return C;
}

/* Extract a quadrant of a matrix. */
Matrix quadrant(const Matrix &M, std::size_t r0, std::size_t c0, std::size_t sz) {
    Matrix Q(sz, std::vector<double>(sz));
    for (std::size_t i = 0; i < sz; ++i)
        for (std::size_t j = 0; j < sz; ++j)
            Q[i][j] = M[r0 + i][c0 + j];
    return Q;
}

/* Write a quadrant back into a larger matrix (in‑place). */
void set_quadrant(Matrix &C, const Matrix &Q, std::size_t r0, std::size_t c0) {
    std::size_t sz = Q.size();
    for (std::size_t i = 0; i < sz; ++i)
        for (std::size_t j = 0; j < sz; ++j)
            C[r0 + i][c0 + j] = Q[i][j];
}

/* ------------------------------------------------------------------ */
/* Strassen recursion                                                   */
static constexpr std::size_t BASE_SIZE = 64; // tune for your hardware

Matrix strassen(const Matrix &A, const Matrix &B) {
    std::size_t n = A.size();
    if (n <= BASE_SIZE) return naive_mul(A, B);

    std::size_t h = n / 2;

    // split A & B into quadrants
    Matrix A11 = quadrant(A, 0, 0, h);
    Matrix A12 = quadrant(A, 0, h, h);
    Matrix A21 = quadrant(A, h, 0, h);
    Matrix A22 = quadrant(A, h, h, h);

    Matrix B11 = quadrant(B, 0, 0, h);
    Matrix B12 = quadrant(B, 0, h, h);
    Matrix B21 = quadrant(B, h, 0, h);
    Matrix B22 = quadrant(B, h, h, h);

    // seven Strassen products
    Matrix M1 = strassen(add(A11, A22), add(B11, B22));
    Matrix M2 = strassen(add(A21, A22), B11);
    Matrix M3 = strassen(A11, sub(B12, B22));
    Matrix M4 = strassen(A22, sub(B21, B11));
    Matrix M5 = strassen(add(A11, A12), B22);
    Matrix M6 = strassen(sub(A21, A11), add(B11, B12));
    Matrix M7 = strassen(sub(A12, A22), add(B21, B22));

    // combine
    Matrix C11 = add(sub(add(M1, M4), M5), M7);
    Matrix C12 = add(M3, M5);
    Matrix C21 = add(M2, M4);
    Matrix C22 = add(sub(add(M1, M2), M3), M6);

    // stitch quadrants back together
    Matrix C(n, std::vector<double>(n));
    set_quadrant(C, C11, 0, 0);
    set_quadrant(C, C12, 0, h);
    set_quadrant(C, C21, h, 0);
    set_quadrant(C, C22, h, h);
    return C;
}

/* ------------------------------------------------------------------ */
/* Public API                                                           */
Matrix multiply(const Matrix &A, const Matrix &B, bool pad = true) {
    if (A.empty() || B.empty())
        throw std::invalid_argument("Matrices must not be empty.");
    if (A.size() != A[0].size() || B.size() != B[0].size())
        throw std::invalid_argument("Matrices must be square.");
    if (A.size() != B.size())
        throw std::invalid_argument("Matrices must have the same dimension.");

    Matrix a = A, b = B;
    if (pad) {
        pad_to_power_of_two(a);
        pad_to_power_of_two(b);
    }
    return strassen(a, b);
}

} // namespace fastmat
```

