### 3.2 `cache.proto` – the service contract

```protobuf
syntax = "proto3";

package cache;

option go_package = "github.com/you/replicated-cache/pb";

service Cache {
    // PUT forwards the request to the leader, which replicates to all replicas.
    rpc Put(PutRequest) returns (PutResponse);
    // GET is served locally on whichever replica the client contacts.
    rpc Get(GetRequest) returns (GetResponse);
}

// Put – a write that must be applied on *every* replica before the client gets OK.
message PutRequest {
    string key   = 1;
    string value = 2;
}
message PutResponse { bool ok = 1; }

// Get – read from the local cache (safe after a successful Put).
message GetRequest { string key = 1; }
message GetResponse { string value = 2; bool found = 3; }
```

### 3.3 `cache_grpc.go` – the replicated cache server

```go
package cache

import (
	"context"
	"log"
	"net"
	"sync"

	"github.com/hashicorp/raft"
	boltStore "github.com/hashicorp/raft-boltdb"
	"google.golang.org/grpc"
	"google.golang.org/grpc/peer"
)

// Server is the stateful object that lives on each replica.
type Server struct {
	mu    sync.RWMutex
	cache map[string]string // the actual cache

	raftDir string
	raftID  string
	raft    *raft.Raft // used only on the leader; followers just apply logs

	// gRPC server
	grpcServer *grpc.Server
}

// NewServer creates a replica.  The first node (raftID = "1") becomes the initial leader.
func NewServer(raftDir, raftID, listenAddr string, bootstrap bool) (*Server, error) {
	s := &Server{
		cache:    make(map[string]string),
		raftDir:  raftDir,
		raftID:   raftID,
		grpcServer: grpc.NewServer(),
	}

	// ----- Raft setup -----
	trans, err := newTransport(listenAddr)
	if err != nil {
		return nil, err
	}

	store, err := boltStore.NewBoltStore(raftDir + "/raft.db")
	if err != nil {
		return nil, err
	}

	snapshotStore, err := raft.NewFileSnapshotStore(raftDir, 2, nil)
	if err != nil {
		return nil, err
	}

	cfg := raft.DefaultConfig()
	cfg.LogLevel = raft.LogInfo
	cfg.LocalID = raft.ServerID(raftID)

	// We use a simple in‑memory TCP transport for Raft.
	ra, err := raft.NewRaft(cfg, &fsm{s}, store, store, snapshotStore, trans)
	if err != nil {
		return nil, err
	}
	s.raft = ra

	// Bootstrap the cluster if this is the first node.
	if bootstrap {
		raftIdx, _ := raft.NewMemStore()
		configuration := raft.Configuration{
			Servers: []raft.Server{
				{ID: raft.ServerID(raftID), Address: raft.ServerAddress(listenAddr)},
			},
		}
		ra.BootstrapCluster(configuration)
	}

	// Register the gRPC service.
	RegisterCacheServer(s.grpcServer, s)

	lis, err := net.Listen("tcp", listenAddr)
	if err != nil {
		return nil, err
	}
	go s.grpcServer.Serve(lis)

	return s, nil
}

// ---- gRPC service implementation ---------------------------------

type PutRequest = PutRequestPB
type PutResponse = PutResponsePB
type GetRequest = GetRequestPB
type GetResponse = GetResponsePB

func (s *Server) Put(ctx context.Context, req *PutRequest) (*PutResponse, error) {
	// Encode the command as a Raft log entry.
	cmd := Command{Op: "put", Key: req.Key, Value: req.Value}
	data, err := encodeCmd(cmd)
	if err != nil {
		return nil, err
	}

	// Ask Raft to replicate the command.
	// For a leader this is a local commit; for a follower it forwards to the leader.
	future := s.raft.Apply(data, 500*time.Millisecond)
	if future.Error() != nil {
		return nil, future.Error()
	}
	// The command is now committed on a majority, thus on *all* replicas.
	return &PutResponse{Ok: true}, nil
}

func (s *Server) Get(ctx context.Context, req *GetRequest) (*GetResponse, error) {
	s.mu.RLock()
	val, ok := s.cache[req.Key]
	s.mu.RUnlock()
	return &GetResponse{Value: val, Found: ok}, nil
}

// ---- Raft FSM (the only place where we actually modify the cache) ----

type Command struct {
	Op    string
	Key   string
	Value string
}

// fsm implements raft.FSM.
type fsm struct {
	server *Server
}

func (f *fsm) Apply(log *raft.Log) interface{} {
	var cmd Command
	if err := decodeCmd(log.Data, &cmd); err != nil {
		return err
	}
	switch cmd.Op {
	case "put":
		f.server.mu.Lock()
		f.server.cache[cmd.Key] = cmd.Value
		f.server.mu.Unlock()
		return nil
	default:
		return errors.New("unknown op")
	}
}

// Snapshot, Restore, and other FSM methods omitted for brevity (use boltdb defaults).
func (f *fsm) Snapshot() (raft.FSMSnapshot, error) { return &noopSnapshot{}, nil }
func (f *fsm) Restore(snapshot io.ReadCloser) error { return nil }

type noopSnapshot struct{}
func (n *noopSnapshot) Persist(sink raft.SnapshotSink) error { return nil }
func (n *noopSnapshot) Release() {}

// ---- Helpers for encoding/decoding commands (you can use msgp, protobuf, etc.) ----

func encodeCmd(cmd Command) ([]byte, error) { /* use json/msgpack/etc. */ }
func decodeCmd(data []byte, cmd *Command) error { /* matching decode */ }
```

