### 3.5 `client.go` – simple client that uses the cache

```go
package main

import (
	"context"
	"fmt"
	"log"
	"time"

	"google.golang.org/grpc"
	"google.golang.org/grpc/credentials/insecure"

	cache "github.com/you/replicated-cache/pb"
)

func main() {
	conn, err := grpc.Dial(":50051", grpc.WithTransportCredentials(insecure.NewCredentials()))
	if err != nil {
		log.Fatal(err)
	}
	c := cache.NewCacheClient(conn)

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	// Write a value – this will block until *all* replicas have applied it.
	putResp, err := c.Put(ctx, &cache.PutRequest{Key: "hello", Value: "world"})
	if err != nil || !putResp.Ok {
		log.Fatalf("put failed: %v", err)
	}
	log.Println("Put succeeded – all replicas now hold key 'hello'")

	// Read from any replica – no extra round‑trip needed.
	getResp, err := c.Get(ctx, &cache.GetRequest{Key: "hello"})
	if err != nil {
		log.Fatalf("get failed: %v", err)
	}
	fmt.Printf("Got value: %q (found=%v)\n", getResp.Value, getResp.Found)
}
```

