       Fallback for older compilers that don’t support stdatomic.h
       or std::atomic.  We rely on the fact that a 64‑bit value that
       is *properly aligned* (e.g. on a 8‑byte boundary) is accessed
       atomically on all mainstream architectures (x86‑64, ARMv8,
       Power‑PC64, etc.).  The volatile qualifier prevents the
       compiler from generating non‑atomic byte‑wise accesses.
       ------------------------------------------------------------- */
    #define ATOMIC64_ALIGNED    alignas(8)

    typedef struct { volatile uint64_t v; } atomic64_t;

    static inline uint64_t atomic64_load(const atomic64_t *obj)
    {
        /* The “volatile” guarantees the compiler will emit a single
           64‑bit load.  The underlying hardware guarantees that the
           load is atomic on aligned accesses. */
        return obj->v;
    }

    static inline void atomic64_store(atomic64_t *obj, uint64_t val)
    {
        /* Same reasoning as above – a single aligned 64‑bit store. */
        obj->v = val;
    }

#endif /* fallback */

/* -------------------------------------------------------------
   Example of how to use the helpers.
   ------------------------------------------------------------- */
static atomic64_t g_counter = ATOMIC64_ALIGNED {0};

static uint64_t read_counter(void)
{
    return atomic64_load(&g_counter);
}

static void write_counter(uint64_t new_val)
{
    atomic64_store(&g_counter, new_val);
}

#endif /* ATOMIC64_H */
```

### How it works

| Layer | What it does | Why it is safe |
|-------|--------------|----------------|
| **Standard C11 / C++11 atomics** | Calls the language‑defined `atomic_load_explicit` / `atomic_store_explicit` (or `std::atomic::load/store`) with **acquire** / **release** ordering. | The implementation uses the platform’s native atomic instructions (e.g. `lock`‑prefixed `mov` on x86, `ldar`/`stlr` on ARM) and guarantees that the operation cannot be torn into two 32‑bit accesses. |
