 */

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

/* The data we want to pass from producer → consumer */
int shared_data = 0;

/* A flag that signals “data is ready”.  Marked volatile so the compiler
 * won’t reorder reads/writes of this variable relative to each other. */
volatile int data_ready = 0;

/* ------------------------------------------------------------------ */
void *producer(void *arg)
{
    (void)arg;               /* unused */

    /* ---- write the data first ---- */
    shared_data = 0xDEADBEEF;    /* arbitrary test value */

    /* ---- then set the flag ---- */
    data_ready = 1;               /* store‑release on x86‑64 */

    return NULL;   /* thread terminates */
}

void *consumer(void *arg)
{
    (void)arg;

    /* Spin until the flag becomes non‑zero */
    while (data_ready == 0)
        ;   /* empty spin – on x86‑64 a plain load is already acquire */

    /* ---- now the flag is set, the data must be visible ---- */
    printf("Consumer saw: 0x%08X\n", shared_data);

    return NULL;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    pthread_t prod, cons;

    /* Create the two threads */
    if (pthread_create(&prod, NULL, producer, NULL) != 0) {
        perror("pthread_create producer");
        exit(EXIT_FAILURE);
    }
    if (pthread_create(&cons, NULL, consumer, NULL) != 0) {
        perror("pthread_create consumer");
        exit(EXIT_FAILURE);
    }

    /* Wait for them to finish */
    pthread_join(prod, NULL);
    pthread_join(cons, NULL);

    return 0;
}
```

