In C++ programming, fully coherent memory sharing between CPU and GPU typically requires specific APIs like CUDA managed memory or OpenCL shared memory. However, even with these technologies, **explicit synchronization is often still necessary** to ensure correct data ordering and visibility. Here are two examples:

### 1. CUDA Unified Memory (Managed Memory)
Unified memory allows CPU and GPU to share a single address space, but the runtime manages data migration. While it simplifies memory management, synchronization is required to avoid race conditions.

```cpp
#include <cuda_runtime.h>
#include <stdio.h>

// CUDA kernel
__global__ void add_vectors(float* a, float* b, float* c, int n) {
    int idx = blockIdx.x * threadIdx.x;
    if (idx < n) c[idx] = a[idx] + b[idx];
}

int main() {
    const int N = 1024;
    float *a, *b, *c;

    // Allocate unified memory
    cudaMallocManaged(&a, N * sizeof(float));
    cudaMallocManaged(&b, N * sizeof(float));
    cudaMallocManaged(&c, N * sizeof(float));

    // Initialize data on CPU
    for (int i = 0; i < N; i++) {
        a[i] = i;
        b[i] = i * 2;
    }

    // Launch kernel
    add_vectors<<<1, N>>>(a, b, c, N);

    // Synchronize to ensure kernel completion before CPU access
    // Note: Without synchronization, CPU reads may see stale/incorrect data
    cudaDeviceSynchronize();

    // Verify result
    printf("Result[0] = %f\n", c[0]); // Should be 0.0

    // Cleanup
    cudaFree(a);
    cudaFree(b);
    cudaFree(c);

    return 0;
}
```

### 2. OpenCL Shared Memory (Using CL_MEM_ALLOC_HOST_PTR)
OpenCL allows creating buffers in host memory accessible by both devices, but explicit synchronization via events or barriers is needed.

```cpp
#include <CL/cl.h>
#include <stdio.h>

// OpenCL kernel (simplified for illustration)
const char* kernel_source = R"(
    __kernel void add_vectors(__global float* a, 
                              __global float* b, 
                              __global float* c) {
        int idx = get_global_id(0);
        c[idx] = a[idx] + b[idx];
    }
)";

int main() {
    const int N = 1024;
    float *h_a = (float*)malloc(N * sizeof(float));
    float *h_b = (float*)malloc(N * sizeof(float));
    float *h_c = (float*)malloc(N * sizeof(float));

    // Initialize host arrays
    for (int i = 0; i < N; i++) {
        h_a[i] = i;
        h_b[i] = i * 2;
    }

    // OpenCL setup (simplified)
    cl_platform_id platform;
