// Shared variable
int shared_data = 0;

// A function that the compiler might assume does not access shared_data
void __attribute__((noinline)) potentially_pure_function() {
    // Empty or some computation not involving shared_data
}

// Function without barrier
void without_barrier() {
    shared_data = 42;                  // Store
    potentially_pure_function();        // Function call
    int x = shared_data;               // Load
    // The compiler might reorder the load before the store if it thinks
    // the function doesn't access shared_data, leading to x == 0.
    // This is undefined behavior if the reordering changes observable behavior.
