// Function with compiler barrier
void with_barrier() {
    shared_data = 42;                  // Store
    asm volatile("" ::: "memory");      // Compiler barrier
    potentially_pure_function();        // Function call
    int x = shared_data;               // Load
    // The barrier prevents reordering: x is guaranteed to be 42.
