**Important Caveat**: RDTSC synchronization across cores is **NOT guaranteed** by hardware on modern processors due to:
- Dynamic frequency scaling (Turbo Boost, SpeedStep)
- Different power states per core
- Architecture differences (e.g., multi-socket systems)

**However**, on modern Intel/AMD processors within the **same socket/package**, with proper configuration, RDTSC can be sufficiently synchronized for short-duration timing. Here's working code:

```c
// cross_core_timing.c
// Compile with: gcc -O2 -pthread cross_core_timing.c

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <sched.h>
#include <string.h>

// Portable RDTSC implementation
static inline uint64_t rdtsc() {
    unsigned int lo, hi;
    __asm__ __volatile__ (
        "rdtsc\n"
        "shl $32, %%rdx\n"
        "or %%rdx, %%rax"
        : "=a"(lo), "=d"(hi)
        :: "rcx", "memory"
    );
    return ((uint64_t)hi << 32) | lo;
}

// Serializing RDTSC (waits for all instructions before timestamp)
static inline uint64_t rdtsc_serialized() {
    unsigned int lo, hi;
    __asm__ __volatile__ (
        "lfence\n"
        "rdtsc\n"
        "shl $32, %%rdx\n"
        "or %%rdx, %%rax\n"
        "lfence"
        : "=a"(lo), "=d"(hi)
        :: "rcx", "memory"
    );
    return ((uint64_t)hi << 32) | lo;
}

// Shared synchronization primitives
typedef struct {
    volatile int ready;
    volatile int start;
    volatile int done;
    volatile uint64_t start_time;
    volatile uint64_t end_time;
    volatile uint64_t core1_timestamp;
    volatile uint64_t core2_timestamp;
} sync_data_t;

sync_data_t sync;

// Thread running on Core 0
void* core0_thread(void* arg) {
    cpu_set_t cpuset;
    CPU_ZERO(&cpuset);
    CPU_SET(0, &cpuset);
    pthread_setaffinity_np(pthread_self(), sizeof(cpu_set_t), &cpuset);

    // Wait for core1 to be ready
    while (!sync.ready) {
        __asm__ __volatile__("pause" ::: "memory");
    }

    // Synchronized start
    __sync_synchronize();

    // Core 0 starts timing
    uint64_t t0 = rdtsc_serialized();

    // Signal core 1 to start its work
    sync.start = 1;
    __sync_synchronize();

    // Wait for core 1 to complete
    while (!sync.done) {
        __asm__ __volatile__("pause" ::: "memory");
    }

    // Core 0 ends timing
    uint64_t t1 = rdtsc_serialized();

    sync.start_time = t0;
    sync.end_time = t1;

    return NULL;
