    sync.core1_timestamp = t_received;
    sync.core2_timestamp = t_completed;

    // Signal completion
    sync.done = 1;
    __sync_synchronize();

    return NULL;
}

int main() {
    pthread_t t0, t1;

    memset(&sync, 0, sizeof(sync_data));

    printf("Cross-Core RDTSC Timing Example\n");
    printf("================================\n\n");

    // Create threads (core1 first to ensure it's waiting)
    if (pthread_create(&t1, NULL, core1_thread, NULL) != 0) {
        perror("Failed to create core1 thread");
        return 1;
    }

    // Small delay to ensure core1 is waiting
    usleep(1000);

    if (pthread_create(&t0, NULL, core0_thread, NULL) != 0) {
        perror("Failed to create core0 thread");
        return 1;
    }

    // Wait for both threads
    pthread_join(t0, NULL);
    pthread_join(t1, NULL);

    // Calculate results
    uint64_t total_cycles = sync.end_time - sync.start_time;
    uint64_t core1_latency = sync.core1_timestamp - sync.start_time;
    uint64_t core1_work = sync.core2_timestamp - sync.core1_timestamp;

    printf("Results (in CPU cycles):\n");
    printf("------------------------\n");
    printf("Total cross-core round-trip: %lu cycles\n", total_cycles);
    printf("Core 1 signal reception latency: %lu cycles\n", core1_latency);
    printf("Core 1 processing time: %lu cycles\n", core1_work);
    printf("Core 1 response latency: %lu cycles\n", 
           (sync.end_time - sync.core2_timestamp));

