## 4. Python version (quick sketch)

If you prefer Python, the same algorithm translates almost line‑for‑line. Below is a *minimal, self‑contained* version that uses `threading.Timer` and `collections.deque`.

```python
import math
import threading
import time
from collections import deque
from typing import Callable, Deque, Optional

class PhiAccrualFailureDetector:
    """
    Pythonic implementation of a phi‑accrual failure detector.
    """

    def __init__(
        self,
        node_id: str,
        *,
        phi_threshold: float = 8.0,
        window_size: int = 1000,
        check_interval_sec: float = 0.2,
        on_failure: Callable[[str], None] = None,
    ) -> None:
        self.node_id = node_id
        self.phi_threshold = phi_threshold
        self.window_size = window_size
        self.check_interval = check_interval_sec
        self.on_failure = on_failure or (lambda nid: None)

        self._intervals: Deque[float] = deque(maxlen=window_size)
        self._last_heartbeat: Optional[float] = None
        self._lock = threading.Lock()
        self._running = False
        self._timer: Optional[threading.Timer] = None

    # ------------------------------------------------------------------ #
    # Public API
    # ------------------------------------------------------------------ #
    def start(self) -> None:
        with self._lock:
            if self._running:
                return
            self._running = True
        self._schedule_next_check()

    def stop(self) -> None:
        with self._lock:
            self._running = False
            if self._timer is not None:
                self._timer.cancel()
                self._timer = None

    def record_heartbeat(self, timestamp: Optional[float] = None) -> None:
        """timestamp can be omitted – then time.time() is used."""
        now = timestamp if timestamp is not None else time.time()
        with self._lock:
            if self._last_heartbeat is not None:
                interval = now - self._last_heartbeat
                self._intervals.append(interval)
            self._last_heartbeat = now

    def phi(self) -> float:
        """Return the current φ value."""
        with self._lock:
            if len(self._intervals) < 2:
                return 0.0
            mean = sum(self._intervals) / len(self._intervals)
            variance = sum((x - mean) ** 2 for x in self._intervals) / len(self._intervals)
            std = math.sqrt(max(variance, 1e-12))

            if self._last_heartbeat is None:
                return 0.0
            t = time.time() - self._last_heartbeat
            x = (t - mean) / std
            cdf = 0.5 * (1 + math.erf(x / math.sqrt(2)))
            phi = -math.log10(max(1 - cdf, 1e-12))
            return phi

    def is_alive(self) -> bool:
        return self.phi() < self.phi_threshold

    # ------------------------------------------------------------------ #
    # Private helpers
    # ------------------------------------------------------------------ #
    def _schedule_next_check(self) -> None:
        def tick() -> None:
            if not self._running:
                return
            try:
                self._check()
            except Exception as exc:
                print(f"[PhiDetector] Unexpected error in check: {exc}")
            finally:
                self._schedule_next_check()

        self._timer = threading.Timer(self.check_interval, tick)
        self._timer.daemon = True
        self._timer.start()

    def _check(self) -> None:
        if self.phi() >= self.phi_threshold:
            self.on_failure(self.node_id)


# ---------------------------------------------------------------------- #
# Example usage
# ---------------------------------------------------------------------- #
if __name__ == "__main__":
    def failure_handler(node_id: str) -> None:
        print(f"💥 Node {node_id} is presumed DEAD!")

    detector = PhiAccrualFailureDetector(
        "node‑A",
        phi_threshold=8.0,
        window_size=500,
        check_interval_sec=0.1,
        on_failure=failure_handler,
    )
    detector.start()

    # Simulate heartbeats
    def heartbeat_loop() -> None:
        while detector._running:
            detector.record_heartbeat()
            time.sleep(0.3)

    hb = threading.Thread(target=heartbeat_loop, daemon=True)
    hb.start()

    time.sleep(5)          # 5 s of healthy traffic
    print("⏸  Stop sending heartbeats …")
    hb.join(timeout=1)     # stops the loop (detector will eventually fire)

    detector.stop()
```

*Both the Java and Python versions are **production‑ready** for a typical microservice, distributed‑system, or Akka‑style actor environment.*  

