## 2. `node.go`

```go
package main

import (
	"encoding/gob"
	"fmt"
	"log"
	"math/rand"
	"net"
	"net/rpc"
	"sync"
	"time"
)

// -----------------------------------------------------------------------
// Data structures

type Command struct {
	Type  string // "write" or "read"
	Key   string
	Value string
}

type LogEntry struct {
	Term    int
	Index   int64
	Command Command
}

// -----------------------------------------------------------------------
// RPC arguments / replies

type AppendEntriesArgs struct {
	Term         int
	LeaderID     int
	PrevLogIndex int64
	PrevLogTerm  int
	Entries      []LogEntry
	LeaderCommit int64
}

type AppendEntriesReply struct {
	Success bool
	Term    int
}

type RequestVoteArgs struct {
	Term         int
	CandidateID  int
	LastLogIndex int64
	LastLogTerm  int
}

type RequestVoteReply struct {
	VoteGranted bool
	Term        int
}

type ClientRequestArgs struct {
	Command Command
}

type ClientReply struct {
	Success bool
	Error   string
	Value   string
	Found   bool
}

// -----------------------------------------------------------------------
// Node

type NodeState int

const (
	Follower NodeState = iota
	Candidate
	Leader
)

type Node struct {
	mu sync.Mutex // protects all fields below

	id               int
	address          string          // "host:port"
	peers            []int           // IDs of other nodes
	peerAddrs        []string        // addresses of other nodes (same order as peers)
	state            NodeState
	currentTerm      int
	votedFor         int
	log              []LogEntry
	stateMachine     map[string]string

	// leader bookkeeping
	nextIndex  map[int]int // per‑peer
	matchIndex map[int]int // per‑peer

	// timers
	electionTimeout   time.Duration
	heartbeatInterval time.Duration
	electionTimer     *time.Timer
	heartbeatTimer    *time.Timer

	// network
	listener net.Listener
	server   *rpc.Server
	clients  map[int]*rpc.Client

	// shutdown
	killCh chan struct{}
}

// -----------------------------------------------------------------------
// helpers

func (n *Node) resetElectionTimerLocked() {
	n.electionTimer.Reset(time.Duration(150+rand.Intn(150)) * time.Millisecond)
}

func (n *Node) resetElectionTimer() {
	n.mu.Lock()
	defer n.mu.Unlock()
	n.resetElectionTimerLocked()
}

func (n *Node) isLogUpToDate(lastLogIndex int64, lastLogTerm int) bool {
	lastIdx := int64(len(n.log))
	lastTerm := 0
	if lastIdx > 0 {
		lastTerm = n.log[lastIdx-1].Term
	}
	if lastTerm != lastLogTerm {
		return lastTerm < lastLogTerm
	}
	return lastLogIndex >= lastIdx
}

func (n *Node) becomeLeader() {
	n.state = Leader
	// initialise leader state
	for _, p := range n.peers {
		n.nextIndex[p] = len(n.log) + 1
		n.matchIndex[p] = 0
	}
	// start sending heartbeats
	go n.runHeartbeat()
}

// -----------------------------------------------------------------------
// Node lifecycle

func newNode(id int, addr string, peers []int, peerAddrs []string) *Node {
	n := &Node{
		id:               id,
		address:          addr,
		peers:            peers,
		peerAddrs:        peerAddrs,
		state:            Follower,
		currentTerm:      0,
		votedFor:         -1,
		log:              []LogEntry{},
		stateMachine:     make(map[string]string),
		nextIndex:        make(map[int]int),
		matchIndex:       make(map[int]int),
		electionTimeout:  150 * time.Millisecond,
		heartbeatInterval: 50 * time.Millisecond,
		killCh:           make(chan struct{}),
		clients:          make(map[int]*rpc.Client),
	}
	n.electionTimer = time.NewTimer(n.electionTimeout)
	n.heartbeatTimer = time.NewTimer(n.heartbeatInterval)
	return n
}

// Start creates the TCP listener, registers the RPC service, dials all peers and starts the main event loop.
func (n *Node) Start() error {
	ln, err := net.Listen("tcp", n.address)
	if err != nil {
		return fmt.Errorf("listen %s: %w", n.address, err)
	}
	n.listener = ln
	n.server = rpc.NewServer()
	if err := n.server.Register(n); err != nil {
		return fmt.Errorf("register node: %w", err)
	}
	go n.server.Accept(ln)

	// dial peers
	for i, pid := range n.peers {
		addr := n.peerAddrs[i]
		client, err := rpc.Dial("tcp", addr)
		if err != nil {
			log.Printf("dial peer %d (%s): %v", pid, addr, err)
		} else {
			n.clients[pid] = client
		}
	}

	go n.run()
	return nil
}

// Stop shuts the node down.
func (n *Node) Stop() {
	close(n.killCh)
	if n.listener != nil {
		n.listener.Close()
	}
	for _, c := range n.clients {
		c.Close()
	}
}

// -----------------------------------------------------------------------
// Main event loop (election & heartbeat timers)

func (n *Node) run() {
	for {
		select {
		case <-n.killCh:
			return
		case <-n.electionTimer.C:
			n.mu.Lock()
			if n.state != Leader {
				n.startElection()
			}
			n.resetElectionTimerLocked()
			n.mu.Unlock()
		}
	}
}

// -----------------------------------------------------------------------
// Heartbeat goroutine (only runs while node is leader)

func (n *Node) runHeartbeat() {
	ticker := time.NewTicker(n.heartbeatInterval)
	defer ticker.Stop()
	for {
		select {
		case <-n.killCh:
			return
		case <-ticker.C:
			n.mu.Lock()
			if n.state != Leader {
				n.mu.Unlock()
				return
			}
			n.broadcastAppendEntries()
			n.mu.Unlock()
		}
	}
}

// -----------------------------------------------------------------------
// Leader: broadcast AppendEntries (heartbeat) to all followers

func (n *Node) broadcastAppendEntries() {
	for _, pid := range n.peers {
		go n.sendAppendEntries(pid, nil) // nil entries ⇒ heartbeat
	}
}

// -----------------------------------------------------------------------
// AppendEntries – RPC handler (also used for heartbeats)

func (n *Node) AppendEntries(args *AppendEntriesArgs, reply *AppendEntriesReply) error {
	n.mu.Lock()
	defer n.mu.Unlock()

	// reject stale terms
	if args.Term < n.currentTerm {
		reply.Success = false
		reply.Term = n.currentTerm
		return nil
	}
	// update term and become follower if we see a higher term
	if args.Term > n.currentTerm {
		n.currentTerm = args.Term
		n.state = Follower
		n.votedFor = -1
	}
	// reset election timer on any valid AppendEntries
	n.resetElectionTimerLocked()

	// check log consistency
	if args.PrevLogIndex > 0 {
		if int(args.PrevLogIndex) > len(n.log) ||
			n.log[args.PrevLogIndex-1].Term != args.PrevLogTerm {
			reply.Success = false
			reply.Term = n.currentTerm
			return nil
		}
	}

	// append new entries
	n.log = append(n.log[:args.PrevLogIndex], args.Entries...)

	// advance commitIndex
	if args.LeaderCommit > int64(n.commitIndex) {
		if args.LeaderCommit < int64(len(n.log)) {
			n.commitIndex = int(args.LeaderCommit)
		} else {
			n.commitIndex = len(n.log)
		}
	}

	// apply to state machine
	n.applyEntriesLocked()
	reply.Success = true
	reply.Term = n.currentTerm
	return nil
}

// -----------------------------------------------------------------------
// RequestVote – RPC handler

func (n *Node) RequestVote(args *RequestVoteArgs, reply *RequestVoteReply) error {
	n.mu.Lock()
	defer n.mu.Unlock()

	if args.Term < n.currentTerm {
		reply.VoteGranted = false
		reply.Term = n.currentTerm
		return nil
	}
	if args.Term > n.currentTerm {
		n.currentTerm = args.Term
		n.state = Follower
		n.votedFor = -1
	}
	if (n.votedFor == -1 || n.votedFor == args.CandidateID) && n.isLogUpToDate(args.LastLogIndex, args.LastLogTerm) {
		n.votedFor = args.CandidateID
		n.resetElectionTimerLocked()
		reply.VoteGranted = true
	} else {
		reply.VoteGranted = false
	}
	reply.Term = n.currentTerm
	return nil
}

// -----------------------------------------------------------------------
// Client request – the only place where the state machine is read/written

func (n *Node) ClientRequest(args *ClientRequestArgs, reply *ClientReply) error {
	n.mu.Lock()
	defer n.mu.Unlock()

	if n.state != Leader {
		reply.Success = false
		reply.Error = "not leader"
		return nil
	}

	if args.Command.Type == "write" {
		// append to log
		entry := LogEntry{
			Term:    n.currentTerm,
			Index:   int64(len(n.log) + 1),
			Command: args.Command,
		}
		n.log = append(n.log, entry)

		// replicate to a majority
		if n.replicate() {
			// commit & apply
			n.commitIndex = len(n.log)
			n.applyEntriesLocked()
			reply.Success = true
		} else {
			reply.Success = false
			reply.Error = "replication to majority failed"
		}
		return nil
	}

	if args.Command.Type == "read" {
		// Linearizable read: confirm leadership with a quorum
		if !n.ensureLeaderWithQuorum() {
			reply.Success = false
			reply.Error = "leadership not confirmed"
			return nil
		}
		// read from committed state
		val, ok := n.stateMachine[args.Command.Key]
		reply.Success = true
		reply.Value = val
		reply.Found = ok
		return nil
	}

	reply.Success = false
	reply.Error = "unknown command"
	return nil
}

// -----------------------------------------------------------------------
// Apply committed log entries to the state machine

func (n *Node) applyEntriesLocked() {
	for n.lastApplied < n.commitIndex {
		n.lastApplied++
		entry := n.log[n.lastApplied-1]
		if entry.Command.Type == "write" {
			n.stateMachine[entry.Command.Key] = entry.Command.Value
		}
	}
}

// -----------------------------------------------------------------------
// Replicate latest un‑replicated log entries to a majority of followers
// (called while holding n.mu)

func (n *Node) replicate() bool {
	// we try at most a few rounds; in a real Raft we would back‑off per‑peer
	for round := 0; round < 3; round++ {
		successes := 1 // leader itself
		for _, pid := range n.peers {
			nextIdx := n.nextIndex[pid]
			if nextIdx < 1 {
				nextIdx = 1
			}
			prevLogIndex := int64(nextIdx - 1)
			prevLogTerm := 0
			if prevLogIndex > 0 {
				prevLogTerm = n.log[prevLogIndex-1].Term
			}
			entries := []LogEntry{}
			if nextIdx <= len(n.log) {
				entries = n.log[nextIdx-1:]
			}
			args := &AppendEntriesArgs{
				Term:         n.currentTerm,
				LeaderID:     n.id,
				PrevLogIndex: prevLogIndex,
				PrevLogTerm:  prevLogTerm,
				Entries:      entries,
				LeaderCommit: int64(n.commitIndex),
			}
			var reply AppendEntriesReply
			err := n.callPeer(pid, "Node.AppendEntries", args, &reply)
			if err == nil && reply.Success {
				// update indices
				n.matchIndex[pid] = int(prevLogIndex) + len(entries)
				n.nextIndex[pid] = n.matchIndex[pid] + 1
				successes++
			} else {
				// move nextIndex backwards
				n.nextIndex[pid]--
				if n.nextIndex[pid] < 0 {
					n.nextIndex[pid] = 0
				}
			}
		}
		if successes > len(n.peers)/2 {
			return true
		}
	}
	return false
}

// -----------------------------------------------------------------------
// Linearizable read – confirm leadership with a quorum before serving

func (n *Node) ensureLeaderWithQuorum() bool {
	// we need acknowledgement from a majority (including self)
	threshold := len(n.peers)/2 + 1
	acks := 1 // leader
	var mu sync.Mutex
	var wg sync.WaitGroup
	cond := sync.NewCond(&mu)

	for _, pid := range n.peers {
		wg.Add(1)
		go func(pid int) {
			defer wg.Done()
			args := &AppendEntriesArgs{
				Term:         n.currentTerm,
				LeaderID:     n.id,
				PrevLogIndex: int64(len(n.log)),
				PrevLogTerm:  0,
				Entries:      nil, // no‑op heartbeat
				LeaderCommit: int64(n.commitIndex),
			}
			var reply AppendEntriesReply
			err := n.callPeer(pid, "Node.AppendEntries", args, &reply)
			mu.Lock()
			defer mu.Unlock()
			if err == nil && reply.Success {
				acks++
				cond.Signal()
			}
		}(pid)
	}

	mu.Lock()
	for acks < threshold {
		cond.Wait()
	}
	mu.Unlock()
	wg.Wait()
	return true
}

// -----------------------------------------------------------------------
// Election

func (n *Node) startElection() {
	n.state = Candidate
	n.currentTerm++
	n.votedFor = n.id
	// reset election timer (already done by caller)
	lastLogIndex := int64(len(n.log))
	lastLogTerm := 0
	if lastLogIndex > 0 {
		lastLogTerm = n.log[lastLogIndex-1].Term
	}
	args := &RequestVoteArgs{
		Term:         n.currentTerm,
		CandidateID:  n.id,
		LastLogIndex: lastLogIndex,
		LastLogTerm:  lastLogTerm,
	}

	votes := 1 // self‑vote
	var mu sync.Mutex
	var wg sync.WaitGroup
	cond := sync.NewCond(&mu)

	for _, pid := range n.peers {
		wg.Add(1)
		go func(pid int) {
			defer wg.Done()
			var reply RequestVoteReply
			err := n.callPeer(pid, "Node.RequestVote", args, &reply)
			mu.Lock()
			defer mu.Unlock()
			if err == nil && reply.VoteGranted {
				votes++
				cond.Signal()
			} else if reply.Term > n.currentTerm {
				// we discovered a newer term – step down
				n.currentTerm = reply.Term
				n.state = Follower
				n.votedFor = -1
				n.resetElectionTimerLocked()
			}
		}(pid)
	}

	mu.Lock()
	threshold := len(n.peers)/2 + 1
	for votes < threshold {
		cond.Wait()
	}
	mu.Unlock()
	wg.Wait()

	// Did we win the election while still being a candidate?
	n.mu.Lock()
	if n.state == Candidate && votes >= threshold {
		n.becomeLeader()
	}
	n.mu.Unlock()
}

// -----------------------------------------------------------------------
// Helper: send an AppendEntries RPC to a specific peer (maybe a heartbeat)

func (n *Node) sendAppendEntries(pid int, entries []LogEntry) {
	n.mu.Lock()
	prevLogIndex := int64(len(n.log))
	prevLogTerm := 0
	if prevLogIndex > 0 {
		prevLogTerm = n.log[prevLogIndex-1].Term
	}
	args := &AppendEntriesArgs{
		Term:         n.currentTerm,
		LeaderID:     n.id,
		PrevLogIndex: prevLogIndex,
		PrevLogTerm:  prevLogTerm,
		Entries:      entries,
		LeaderCommit: int64(n.commitIndex),
	}
	n.mu.Unlock()
	var reply AppendEntriesReply
	n.callPeer(pid, "Node.AppendEntries", args, &reply)
}

// -----------------------------------------------------------------------
// RPC call helper

func (n *Node) callPeer(peerID int, method string, args, reply interface{}) error {
	client, ok := n.clients[peerID]
	if !ok {
		return fmt.Errorf("no connection to peer %d", peerID)
	}
	return client.Call(method, args, reply)
}

// -----------------------------------------------------------------------
// Register concrete types with the Gob encoder (required by net/rpc)

func init() {
	gob.Register(Command{})
	gob.Register(LogEntry{})
}
