## 3. `main.go`

```go
package main

import (
	"fmt"
	"log"
	"time"
)

func main() {
	// ---------- bootstrap 3‑node cluster ----------
	addrs := []string{
		"localhost:12345",
		"localhost:12346",
		"localhost:12347",
	}
	peerMap := [][]int{
		{1, 2},
		{0, 2},
		{0, 1},
	}
	peerAddrMap := [][]string{
		{"localhost:12346", "localhost:12347"},
		{"localhost:12345", "localhost:12347"},
		{"localhost:12345", "localhost:12346"},
	}

	nodes := make([]*Node, 3)
	for i := 0; i < 3; i++ {
		nodes[i] = newNode(i, addrs[i], peerMap[i], peerAddrMap[i])
		if err := nodes[i].Start(); err != nil {
			log.Fatalf("start node %d: %v", i, err)
		}
		fmt.Printf("Node %d listening on %s\n", i, addrs[i])
	}

	// Give the cluster time to elect a leader
	time.Sleep(2 * time.Second)

	// Locate the leader
	var leader *Node
	for _, n := range nodes {
		n.mu.Lock()
		if n.state == Leader {
			leader = n
		}
		n.mu.Unlock()
	}
	if leader == nil {
		log.Fatal("no leader elected")
	}
	fmt.Printf(">>> Leader elected: node %d (%s)\n", leader.id, leader.address)

	// ---------- simple client ----------
	client, err := newClient(leader.address)
	if err != nil {
		log.Fatalf("client dial: %v", err)
	}

	// Write "foo" → "bar"
	fmt.Println("\n--- Write foo=bar ---")
	if ok, err := client.write("foo", "bar"); !ok {
		log.Fatalf("write failed: %v", err)
	}
	fmt.Println("Write succeeded")

	// Linearizable read of "foo"
	fmt.Println("\n--- Linearizable read foo ---")
	if val, ok, err := client.read("foo"); !ok {
		log.Fatalf("read failed: %v", err)
	} else {
		fmt.Printf("Read foo = %q (found=%v)\n", val, ok)
	}

	// ---------- simulate leader crash ----------
	fmt.Println("\n--- Killing leader (node", leader.id, ") ---")
	leader.Stop()

	// Wait for a new leader to be elected
	time.Sleep(2 * time.Second)

	var newLeader *Node
	for _, n := range nodes {
		if n == leader {
			continue
		}
		n.mu.Lock()
		if n.state == Leader {
			newLeader = n
		}
		n.mu.Unlock()
	}
	if newLeader == nil {
		log.Fatal("no new leader elected after crash")
	}
	fmt.Printf(">>> New leader elected: node %d (%s)\n", newLeader.id, newLeader.address)

	// Connect to new leader and repeat the read (must still see "bar")
	client2, err := newClient(newLeader.address)
	if err != nil {
		log.Fatalf("client2 dial: %v", err)
	}
	fmt.Println("\n--- Linearizable read after leader change ---")
	if val, ok, err := client2.read("foo"); !ok {
		log.Fatalf("read after leader change failed: %v", err)
	} else {
		fmt.Printf("Read foo = %q (found=%v) – still linearizable!\n", val, ok)
	}

	// ---------- cleanup ----------
	for _, n := range nodes {
		n.Stop()
	}
	fmt.Println("\nAll nodes stopped. Test passed.")
}

// -----------------------------------------------------------------------
// Tiny RPC client helper

type client struct {
	addr string
}

func newClient(addr string) (*client, error) {
	return &client{addr: addr}, nil
}

func (c *client) write(key, value string) (bool, error) {
	conn, err := dialRPC(c.addr)
	if err != nil {
		return false, err
	}
	defer conn.Close()
	args := &ClientRequestArgs{
		Command: Command{Type: "write", Key: key, Value: value},
	}
	var reply ClientReply
	if err := conn.Call("Node.ClientRequest", args, &reply); err != nil {
		return false, err
	}
	if !reply.Success {
		return false, fmt.Errorf("%s", reply.Error)
	}
	return true, nil
}

func (c *client) read(key string) (string, bool, error) {
	conn, err := dialRPC(c.addr)
	if err != nil {
		return "", false, err
	}
	defer conn.Close()
	args := &ClientRequestArgs{
		Command: Command{Type: "read", Key: key},
	}
	var reply ClientReply
	if err := conn.Call("Node.ClientRequest", args, &reply); err != nil {
		return "", false, err
	}
	if !reply.Success {
		return "", false, fmt.Errorf("%s", reply.Error)
	}
	return reply.Value, reply.Found, nil
}

func dialRPC(addr string) (*rpc.Client, error) {
	return rpc.Dial("tcp", addr)
}
