import java.util.HashMap;

/**
 * Baby‑step‑giant‑step (BSGS) demo for a 16‑bit cyclic group.
 *
 * The group is the multiplicative group modulo the Fermat prime p = 2^16 + 1 = 65537.
 * Its order is p‑1 = 65536 = 2^16, so a square‑root of the order is 256.
 */
public class BSGSDiscreteLog {

    // ---------- modular exponentiation (binary exponentiation) ----------
    private static long powMod(long base, long exp, long mod) {
        long result = 1L;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1L) == 1L) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    /**
     * Solves  h ≡ g^x (mod p)  for x.
     *
     * @param g   generator of the cyclic group (must have order p‑1)
     * @param h   target element (0 < h < p)
     * @param p   prime modulus (group size = p‑1)
     * @return the smallest non‑negative x satisfying the equation,
     *         or -1 if no solution exists.
     */
    public static long discreteLog(long g, long h, long p) {
        // Group order = p‑1.  Its square‑root is the BSGS step size.
        long n = p - 1;               // n = 65536
        long m = (long) Math.ceil(Math.sqrt((double) n)); // m = 256

        // ---- Baby steps: store g^j (mod p) for 0 ≤ j < m ----
        HashMap<Long, Integer> table = new HashMap<>(2 * (int) m);
        for (long j = 0; j < m; ++j) {
            long val = powMod(g, j, p);
            // keep the smallest j for each value (optional)
            table.putIfAbsent(val, (int) j);
        }

        // ---- Giant‑step factor = g^{-m} (mod p) ----
        // g^{-m} ≡ g^{(p‑1)‑m}  because g^{p‑1} ≡ 1 (mod p)
        long factor = powMod(g, (p - 1 - m) % (p - 1), p);

        // ---- Giant steps: test (h * factor^i) for i = 0 … m ----
        long cur = h;
        for (long i = 0; i <= m; ++i) {
            Integer j = table.get(cur);
            if (j != null) {
                // x = i*m + j  (mod p‑1) – the solution we need
                long x = i * m + j;
                // Normalise to the range [0, n‑1]
                return x % n;
            }
            cur = (cur * factor) % p;   // advance to the next giant step
        }

        // No solution – this should not happen if h really is a power of g.
        return -1;
    }

    // ---------- simple sanity test ----------
    public static void main(String[] args) {
        long p = 65537L;               // prime modulus
        long g = 3L;                   // a known primitive root of 65537
        long xSecret = 12345L;         // the exponent we will recover
        long h = powMod(g, xSecret, p);

