 * read() before any decide() has succeeded).
 */
template <typename T>
class WaitFreeConsensus {
    // The flag that tells whether a decision has already been made.
    std::atomic<bool> decided_{false};
    // The value that the winning thread wrote.
    std::atomic<T>    decidedValue_{};

public:
    WaitFreeConsensus() = default;                 // all atomics initialise to zero/false

    /**
     * Attempt to decide on `proposal`.
