     *
     * @return std::nullopt if no decision has been made yet, otherwise the decided value.
     */
    std::optional<T> read() const {
        if (decided_.load(std::memory_order_seq_cst)) {
            return decidedValue_.load(std::memory_order_seq_cst);
        }
        return std::nullopt;
    }

private:
    // Example validity test – adjust to your domain.
    static bool isValidProposal(const T& v) {
        // For integer types we reject 0; for pointers we reject nullptr.
        // If T is not a scalar you can always return true.
        if constexpr (std::is_integral_v<T>) {
            return v != T{0};
        } else if constexpr (std::is_pointer_v<T>) {
            return v != nullptr;
        }
        return true;
