## 3️⃣ Full source (`main.go`)

```go
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"strings"
	"sync"
	"time"

	"github.com/hashicorp/raft"
)

// ---------------------------------------------------------------------------
// Data structures
// ---------------------------------------------------------------------------

// command is the JSON payload that we send through the Raft log.
type command struct {
	Op    string `json:"op"` // only "set" for now
	Key   string `json:"key"`
	Value string `json:"value"`
}

// KVStore is the finite‑state‑machine (FSM) that actually stores the data.
type KVStore struct {
	mu   sync.RWMutex
	data map[string]string
}

// Apply is called for every committed Raft log entry.
func (s *KVStore) Apply(l *raft.Log) interface{} {
	var cmd command
	if err := json.Unmarshal(l.Data, &cmd); err != nil {
		return err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	switch cmd.Op {
	case "set":
		s.data[cmd.Key] = cmd.Value
		return "ok"
	default:
		return fmt.Errorf("unknown op %q", cmd.Op)
	}
}

// Snapshot returns a snapshot of the current state.
func (s *KVStore) Snapshot() (raft.FSMSnapshot, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	// deep‑copy the map so the snapshot can be persisted independently
	dataCopy := make(map[string]string)
	for k, v := range s.data {
		dataCopy[k] = v
	}
	return &kvSnapshot{data: dataCopy}, nil
}

// kvSnapshot implements raft.FSMSnapshot.
type kvSnapshot struct {
	data map[string]string
}

func (s *kvSnapshot) Persist(sink raft.SnapshotSink) error {
	enc := json.NewEncoder(sink)
	if err := enc.Encode(s.data); err != nil {
		return err
	}
	return sink.Close()
}

func (s *kvSnapshot) Release() {}

// Restore re‑loads a snapshot into the FSM.
func (s *KVStore) Restore(reader io.ReadCloser) error {
	dec := json.NewDecoder(reader)
	var data map[string]string
	if err := dec.Decode(&data); err != nil {
		return err
	}
	s.mu.Lock()
	s.data = data
	s.mu.Unlock()
	return nil
}

// ---------------------------------------------------------------------------
// HTTP handlers
// ---------------------------------------------------------------------------

// makeHTTPHandler builds an http.ServeMux that ties the KV store to the Raft
// instance.
func makeHTTPHandler(store *KVStore, r *raft.Raft, httpAddr string) *http.ServeMux {
	mux := http.NewServeMux()

	// GET /kv/get?key=...
	mux.HandleFunc("/kv/get", func(w http.ResponseWriter, req *http.Request) {
		// Only the leader can serve reads.
		if r.State() != raft.Leader {
			http.Error(w, "not leader", http.StatusServiceUnavailable)
			return
		}
		key := req.URL.Query().Get("key")
		if key == "" {
			http.Error(w, "key parameter required", http.StatusBadRequest)
			return
		}
		store.mu.RLock()
		val, ok := store.data[key]
		store.mu.RUnlock()
		if !ok {
			http.Error(w, "key not found", http.StatusNotFound)
			return
		}
		fmt.Fprintln(w, val)
	})

	// PUT /kv/put?key=...&value=...
	mux.HandleFunc("/kv/put", func(w http.ResponseWriter, req *http.Request) {
		if r.State() != raft.Leader {
			http.Error(w, "not leader", http.StatusServiceUnavailable)
			return
		}
		key := req.URL.Query().Get("key")
		value := req.URL.Query().Get("value")
		if key == "" || value == "" {
			http.Error(w, "key and value parameters required", http.StatusBadRequest)
			return
		}
		cmd := command{Op: "set", Key: key, Value: value}
		data, err := json.Marshal(cmd)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		// Apply waits for the log to be committed to a majority.
		future := r.Apply(data, 5*time.Second)
		if err := future.Error(); err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		fmt.Fprintln(w, "ok")
	})

	// POST /join?address=<raft‑addr>  (used by follower nodes to join the cluster)
	mux.HandleFunc("/join", func(w http.ResponseWriter, req *http.Request) {
		if r.State() != raft.Leader {
			http.Error(w, "not leader", http.StatusServiceUnavailable)
			return
		}
		peerAddr := req.URL.Query().Get("address")
		if peerAddr == "" {
			http.Error(w, "address parameter required", http.StatusBadRequest)
			return
		}
		// In this simple demo we use the address as both ID and address.
		peerID := raft.ServerID(peerAddr)
		if err := r.AddPeer(raft.ServerAddress(peerAddr)).Error; err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		fmt.Fprintf(w, "joined %s (ID=%s)\n", peerAddr, peerID)
	})

	// Expose leadership state for debugging.
	mux.HandleFunc("/raft/state", func(w http.ResponseWriter, req *http.Request) {
		state := r.State()
		leader := r.Leader()
		fmt.Fprintf(w, "State: %s, Leader: %s\n", state, leader)
	})

	return mux
}

// ---------------------------------------------------------------------------
// Bootstrap helpers
// ---------------------------------------------------------------------------

// buildRaftConfig creates a default Raft configuration for the node.
func buildRaftConfig(nodeID string) *raft.Config {
	cfg := raft.DefaultConfig()
	cfg.LocalID = raft.ServerID(nodeID)
	// Keep timeouts short for local testing.
	cfg.HeartbeatTimeout = 1000 * time.Millisecond
	cfg.ElectionTimeout = 1000 * time.Millisecond
	cfg.LeaderLeaseTimeout = 500 * time.Millisecond
	cfg.CommitTimeout = 500 * time.Millisecond
	return cfg
}

// joinCluster attempts to join an existing cluster by contacting a peer.
func joinCluster(r *raft.Raft, peerAddr string) error {
	peerID := raft.ServerID(peerAddr)
	return r.AddPeer(raft.ServerAddress(peerAddr)).Error
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

func main() {
	// Required environment variables:
	//   NODE_ID      – unique identifier for this node (e.g. "node1")
	//   HTTP_ADDR    – address the HTTP server listens on (e.g. "127.0.0.1:8001")
	//   RAFT_ADDR    – address the Raft transport uses (e.g. "127.0.0.1:9001")
	//   RAFT_PEERS   – semicolon‑separated list of all Raft addresses (including this one)
	//   JOIN_ADDR    – (optional) address of an existing node to join; if empty the node bootstraps itself.
	nodeID := os.Getenv("NODE_ID")
	httpAddr := os.Getenv("HTTP_ADDR")
	raftAddr := os.Getenv("RAFT_ADDR")
	peersStr := os.Getenv("RAFT_PEERS")
	joinAddr := os.Getenv("JOIN_ADDR")

	if nodeID == "" || httpAddr == "" || raftAddr == "" || peersStr == "" {
		log.Fatal("NODE_ID, HTTP_ADDR, RAFT_ADDR, and RAFT_PEERS must be set")
	}

	// Parse the peer list.
	peers := strings.Split(peersStr, ";")

	// Build the Raft configuration.
	config := buildRaftConfig(nodeID)

	// Create a TCP transport for Raft.
	transport, err := raft.NewTCPTransport(raftAddr, nil, 3, 10*time.Second, os.Stderr)
	if err != nil {
		log.Fatalf("failed to create transport: %v", err)
	}

	// In‑memory stores – fine for a demo; use BoltDB or Badger in production.
	logStore := raft.NewInmemStore()
	stableStore := raft.NewInmemStore()
	snapshotStore := raft.NewInmemSnapshotStore()

	// Initialize the FSM.
	store := &KVStore{data: make(map[string]string)}

	// Instantiate the Raft node.
	ra, err := raft.NewRaft(config, store, logStore, stableStore, snapshotStore, transport)
	if err != nil {
		log.Fatalf("failed to create Raft node: %v", err)
	}

	// Bootstrap the cluster only on the very first start (when JOIN_ADDR is empty).
	// For a real deployment you’d persist whether the node has already been bootstrapped.
	if joinAddr == "" {
		// Build a configuration that contains all known peers.
		var servers []raft.Server
		for _, addr := range peers {
			servers = append(servers, raft.Server{
				ID:       raft.ServerID(addr),
				Address:  raft.ServerAddress(addr),
			})
		}
		configuration := raft.Configuration{Servers: servers}
		ra.BootstrapCluster(configuration)
	} else {
		// Wait a moment for the leader to be elected, then join.
		time.Sleep(2 * time.Second)
		if err := joinCluster(ra, joinAddr); err != nil {
			log.Fatalf("failed to join cluster at %s: %v", joinAddr, err)
		}
	}

	// Set up HTTP handlers.
	mux := makeHTTPHandler(store, ra, httpAddr)

	log.Printf("starting HTTP server on %s, Raft on %s (ID=%s)", httpAddr, raftAddr, nodeID)
	if err := http.ListenAndServe(httpAddr, mux); err != nil {
		log.Fatalf("HTTP server error: %v", err)
	}
}
```

