type Network struct {
    mu    sync.RWMutex
    peers map[uint64]chan raftpb.Message
}

// NewNetwork creates a network with channels for each node ID.
func NewNetwork(ids []uint64) *Network {
    n := &Network{peers: make(map[uint64]chan raftpb.Message)}
    for _, id := range ids {
        n.peers[id] = make(chan raftpb.Message, 1024)
    }
    return n
}

// Send sends a message to a specific node.
func (n *Network) Send(to uint64, msg raftpb.Message) {
    n.mu.RLock()
    ch, ok := n.peers[to]
    n.mu.RUnlock()
    if ok {
        select {
        case ch <- msg:
        default:
            // drop if channel is full
        }
    }
}

// Receive returns the channel for a node to receive messages.
func (n *Network) Receive(id uint64) chan raftpb.Message {
    n.mu.RLock()
    ch, ok := n.peers[id]
    n.mu.RUnlock()
    if !ok {
        return nil
    }
    return ch
}
