// node holds the state for a single Raft node.
type node struct {
    id       uint64
    raftNode raft.Node
    proposeC chan []byte
    deliverC chan string
    network  *Network
    ticker   *time.Ticker
}

// startNode creates a new Raft node and runs its main loop.
func startNode(id uint64, peers []uint64, network *Network) (proposeC chan<- []byte, deliverC <-chan string) {
    proposeC = make(chan []byte, 1024)
    deliverC = make(chan string, 1024)

    // Create memory storage.
    storage := raft.NewMemoryStorage()

    // Raft configuration.
    cfg := &raft.Config{
        ID:              id,
        ElectionTick:    10,
        HeartbeatTick:   1,
        MaxInflightMsgs: 256,
        Storage:         storage,
        // Set a logger for debug output (optional).
        Logger: &raftLogger{},
    }

    // Initial peer list.
    var peerList []raft.Peer
    for _, p := range peers {
        peerList = append(peerList, raft.Peer{ID: p})
    }

    // Start the Raft node.
    rn := raft.StartNode(cfg, peerList)

    n := &node{
        id:       id,
        raftNode: rn,
        proposeC: proposeC,
        deliverC: deliverC,
        network:  network,
        ticker:   time.NewTicker(100 * time.Millisecond),
    }

    // Run the main loop in a separate goroutine.
    go n.run()

    return proposeC, deliverC
}

// run is the main event loop for the Raft node.
func (n *node) run() {
    defer n.ticker.Stop()

    for {
        select {
        case <-n.ticker.C:
            n.raftNode.Tick()
        case rd := <-n.raftNode.Ready():
            // Send any outgoing messages to the network.
            for _, msg := range rd.Messages {
                // Raft uses the To field to specify the destination.
                n.network.Send(msg.To, msg)
            }
            // Apply committed entries to the state machine.
            for _, entry := range rd.CommittedEntries {
                if entry.Type == raftpb.EntryNormal {
                    if len(entry.Data) > 0 {
                        select {
                        case n.deliverC <- string(entry.Data):
                        default:
                            // If the delivery channel is full, we drop the message.
                        }
                    }
                } else if entry.Type == raftpb.EntryConfChange {
                    var cc raftpb.ConfChange
                    if err := cc.Unmarshal(entry.Data); err != nil {
                        log.Printf("node %d: failed to unmarshal ConfChange: %v", n.id, err)
                        continue
                    }
                    // Apply the configuration change.
                    n.raftNode.ApplyConfChange(&cc)
                }
            }
            // Advance the state machine.
            n.raftNode.Advance()
        case p := <-n.proposeC:
            // Propose a new entry.
            if err := n.raftNode.Propose(context.Background(), p); err != nil {
                log.Printf("node %d: failed to propose: %v", n.id, err)
            }
        case msg := <-n.network.Receive(n.id):
            // Deliver a message received from the network to Raft.
            if err := n.raftNode.Step(context.Background(), msg); err != nil {
                // It is normal for a node to step a message that it sent itself,
                // or to step a message after it has been removed from the cluster.
                // Log non-fatal errors only.
                // log.Printf("node %d: failed to step message: %v", n.id, err)
            }
        }
    }
}
