## 7️⃣  Quick recap (code you can copy‑paste)

```cpp
#include <atomic>
#include <thread>
#include <iostream>

int   shared_data = 0;
std::atomic<bool> ready{false};

void producer() {
    shared_data = 42;
    std::atomic_thread_fence(std::memory_order_release);
    ready.store(true, std::memory_order_relaxed);
}

void consumer() {
    while (!ready.load(std::memory_order_relaxed)) { }
    std::atomic_thread_fence(std::memory_order_acquire);
    std::cout << shared_data << '\n';
}

int main() {
    std::thread p(producer), c(consumer);
    p.join(); c.join();
}
```

That tiny program demonstrates **exactly** where and why you’d insert an `atomic_thread_fence` when ordering matters. Happy synchronising! 🚀

Below is a **step‑by‑step guide** that shows the complete flow you asked for:

1. **Allocate host memory** (pinned memory is required for true async copies).  
2. **Allocate device memory**.  
3. **Create a CUDA stream** – the stream is the “pipeline” into which you will enqueue copies and kernel launches.  
4. **Copy data to the device asynchronously** (`cudaMemcpyAsync`).  
5. **Launch a kernel** (still inside the same stream).  
6. **Synchronise the stream** (`cudaStreamSynchronize`) so you know the kernel (and the preceding copy) have finished.  
7. **Copy the result back to the host asynchronously**.  
8. **Synchronise again** (optional, but good practice) and then read the result.  
9. **Free everything**.

I’ll start with the **simple, “everything in the default stream”** version, and then show the **full‑featured version with a custom stream** (which is what you need if you want to overlap copies and kernel execution).

---

## 1️⃣ Minimal example – default (null) stream, synchronous copy

This works for learning, but it blocks the device while copying.  
**Only use this for debugging or very small inputs.**

```cpp
#include <cuda_runtime.h>
#include <iostream>
#include <vector>

// ------------------------------------------------------------
// Simple error‑checking macro – never ignore CUDA errors
// ------------------------------------------------------------
#define CUDA_CHECK(call)                                                  \
    do {                                                                  \
        cudaError_t err = call;                                           \
        if (err != cudaSuccess) {                                         \
            std::cerr << "CUDA error at " << __FILE__ << ":" << __LINE__  \
                      << " – " << cudaGetErrorString(err) << '\n';        \
            std::exit(EXIT_FAILURE);                                      \
        }                                                                 \
    } while (0)

// ------------------------------------------------------------
// A trivial kernel that doubles each element
// ------------------------------------------------------------
__global__ void doubleElements(int *data, int N)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N) data[idx] *= 2;
}

// ------------------------------------------------------------
int main()
{
    const int N = 1 << 20;                 // 1 048 576 elements
    const size_t bytes = N * sizeof(int);

    // ---------- host memory ----------
    std::vector<int> h_in(N);
    std::vector<int> h_out(N);
    for (int i = 0; i < N; ++i) h_in[i] = i;   // fill with 0,1,2,...

    // ---------- device memory ----------
    int *d_data = nullptr;
    CUDA_CHECK(cudaMalloc(&d_data, bytes));

    // ---------- copy host → device (blocking) ----------
    CUDA_CHECK(cudaMemcpy(d_data, h_in.data(), bytes, cudaMemcpyHostToDevice));

    // ---------- kernel launch ----------
    int blockSize = 256;
    int gridSize  = (N + blockSize - 1) / blockSize;
    doubleElements<<<gridSize, blockSize>>>(d_data, N);

    // ---------- wait for kernel ----------
    CUDA_CHECK(cudaDeviceSynchronize());          // blocks the host

    // ---------- copy device → host (blocking) ----------
    CUDA_CHECK(cudaMemcpy(h_out.data(), d_data, bytes, cudaMemcpyDeviceToHost));

    // ---------- show a few results ----------
    std::cout << "First 5 doubled values: ";
    for (int i = 0; i < 5; ++i) std::cout << h_out[i] << ' ';
    std::cout << '\n';

    // ---------- cleanup ----------
    CUDA_CHECK(cudaFree(d_data));
    return 0;
}
```

Compile with the NVIDIA compiler (`nvcc`):

```bash
nvcc -o double_vec double_vec.cu
./double_vec
```

You should see: `First 5 doubled values: 0 2 4 6 8`.

