Below is a minimal **two‑level cache‑blocked** GEMM (matrix‑matrix product) that is tuned for the typical sizes of an L1 ≈ 32 KB and L2 ≈ 256 KB caches on modern x86/ARM CPUs.

```c
/* -------------------------------------------------
 *  Blocked double‑precision GEMM (C = A * B)
 *  -------------------------------------------------
 *  L1 block size  : L1_BLK   (≈ 64 double‑precision elements)
 *  L2 block size  : L2_BLK   (≈ 256 double‑precision elements)
 *
 *  The algorithm uses three nested loops over the L2‑blocks
 *  and an inner three‑loop micro‑kernel that works on L1‑blocks.
 *  The innermost multiply‑accumulate order is “i‑k‑j” to keep
 *  B’s row‑vector streamed through L1 while A’s column‑vector
 *  stays in a register.
 *
 *  You can tune L1_BLK/L2_BLK further by measuring throughput
 *  on your target hardware.
 * ------------------------------------------------- */

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

/* ----------------------------------------------------------------
 *  Cache‑size constants (change to match your machine)
 * ---------------------------------------------------------------- */
#define L1_SIZE   (32 * 1024)          /* 32 KB L1 data cache */
#define L2_SIZE   (256 * 1024)         /* 256 KB L2 cache   */
#define DSIZE     sizeof(double)       /* 8 bytes per double */

/*  Approximate square‑root of the number of doubles that fit
 *  in half the cache (we keep one operand for read‑write).   */
#define L2_BLK  ((int)(sqrt((double)L2_SIZE / (2.0 * DSIZE))) & ~3)   // round to multiple of 4
#define L1_BLK  ((int)(sqrt((double)L1_SIZE / (2.0 * DSIZE))) & ~3)

/* ----------------------------------------------------------------
 *  Basic matrix multiply on a L1‑sized block (naïve i‑k‑j order)
 * ---------------------------------------------------------------- */
static inline void
micro_kernel(double *C, const double *A, const double *B,
             int M, int N, int K, int lda, int ldb, int ldc)
{
    /*  C[M×N] += A[M×K] * B[K×N]  */
    for (int i = 0; i < M; ++i) {
        for (int k = 0; k < K; ++k) {
            double aik = A[i * lda + k];
            for (int j = 0; j < N; ++j) {
                C[i * ldc + j] += aik * B[k * ldb + j];
            }
        }
    }
}

/* ----------------------------------------------------------------
 *  Two‑level blocked GEMM
 * ---------------------------------------------------------------- */
void
blocked_gemm(double *C, const double *A, const double *B, int n)
{
    /*  n must be a multiple of the block sizes for the snippet.
        For production code pad or handle the remainder.          */
    for (int ii = 0; ii < n; ii += L2_BLK) {
        for (int jj = 0; jj < n; jj += L2_BLK) {
            for (int kk = 0; kk < n; kk += L2_BLK) {

                /* L2‑block extents */
                int i_end = (ii + L2_BLK > n) ? n : ii + L2_BLK;
                int j_end = (jj + L2_BLK > n) ? n : jj + L2_BLK;
                int k_end = (kk + L2_BLK > n) ? n : kk + L2_BLK;

                /* Iterate over L1 sub‑blocks inside the L2 block */
                for (int i = ii; i < i_end; i += L1_BLK) {
                    for (int j = jj; j < j_end; j += L1_BLK) {
                        for (int k = kk; k < k_end; k += L1_BLK) {

                            /* L1‑block extents */
                            int Mb = (i + L1_BLK > i_end) ? i_end - i : L1_BLK;
                            int Nb = (j + L1_BLK > j_end) ? j_end - j : L1_BLK;
                            int Kb = (k + L1_BLK > k_end) ? k_end - k : L1_BLK;

                            /* Pointers to the current L1 blocks */
                            double *C_blk = C + i * n + j;
                            const double *A_blk = A + i * n + k;
