// ------------------------------------------------------------
// 1️⃣  Require the pandas library
// ------------------------------------------------------------
const pandas = require('pandas');

// ------------------------------------------------------------
// 2️⃣  Helper: turn a file path into a DataFrame
// ------------------------------------------------------------
async function loadCSV(path) {
  // The npm 'pandas' library is promise‑based for I/O
  return await pandas.readCSV(path);
}

// ------------------------------------------------------------
// 3️⃣  Use the DataFrame
// ------------------------------------------------------------
(async () => {
  const df = await loadCSV('./people.csv');

  // ── Show the whole DataFrame (pretty‑printed)
