  console.log(df['age']);

  // ── Basic descriptive stats (like df.describe())
  console.log('\n=== df.describe() ===');
  console.log(df.describe());

  // ── Convert the DataFrame to a plain JavaScript object/array
  console.log('\n=== As JSON ===');
  console.log(df.toJSON());

  // ── If you just want a synchronous read (the library also exposes it)
  // const dfSync = pandas.readCSVSync('./people.csv');
  // console.log(dfSync.head());
})().catch(err => {
