// src/main.rs
//! A minimal example that trains an SVM classifier via the Rust `sklearn` crate.

use sklearn::svm::SVC;
use numpy::array;

fn main() {
    // -------------------------------------------------
    // 1️⃣  Create a tiny labelled dataset (XOR‑like)
    // -------------------------------------------------
    // Features – 4 samples, 2 features each
    let X = array![[0., 0.],
                   [0., 1.],
                   [1., 0.],
                   [1., 1.]];

    // Labels – matches XOR truth table
    let y = array![0, 1, 1, 0];

    // -------------------------------------------------
    // 2️⃣  Train a Support‑Vector‑Classifier (SVC)
    // -------------------------------------------------
    // `SVC::new()` creates a default classifier.
    // `set_param` mirrors the scikit‑learn API (e.g. kernel="rbf", C=1.0).
    let clf = SVC::new()
        .set_param("kernel", "rbf")
        .set_param("C", 1.0)
        .fit(&X, &y)
        .expect("Failed to fit the SVC");

    // -------------------------------------------------
    // 3️⃣  Predict on the same data (just for demo)
    // -------------------------------------------------
    let predictions = clf.predict(&X).expect("Failed to predict");

    println!("Predictions: {:?}", predictions);
    // Expected output (order may vary):
    // Predictions: [0, 1, 1, 0]

    // -------------------------------------------------
    // 4️⃣  Compute training accuracy (simple manual calc)
    // -------------------------------------------------
    // `predictions` and `y` are both 1‑D arrays of the same length.
    let correct = predictions
        .iter()
        .zip(y.iter())
        .filter(|(p, t)| *p == *t)
        .count();

    let accuracy = correct as f32 / y.shape()[0] as f32;
    println!("Training accuracy: {:.1}%", accuracy * 100.0);
    // For the XOR dataset the SVM with RBF kernel should reach 100 %
}
```

