```cpp
#include <iostream>
#include <cstring>
#include <sys/socket.h>
#include <net/if.h>
#include <sys/ioctl.h>
#include <linux/can.h>
#include <linux/can/raw.h>

class CanReader {
private:
    int sockfd;
    struct sockaddr_can addr;
    struct ifreq ifr;

public:
    bool init(const char* interface) {
        // Create socket
        sockfd = socket(PF_CAN, SOCK_RAW, CAN_RAW);
        if (sockfd < 0) {
            std::cerr << "Error creating socket\n";
            return false;
        }

        // Get interface index
        strncpy(ifr.ifr_name, interface, IFNAMSIZ - 1);
        ifr.ifr_name[IFNAMSIZ - 1] = '\0';
        if (ioctl(sockfd, SIOCGIFINDEX, &ifr) < 0) {
            std::cerr << "Error getting interface index\n";
            return false;
        }

        // Bind to socket
        addr.can_family = AF_CAN;
        addr.can_ifindex = ifr.ifr_ifindex;
        if (bind(sockfd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
            std::cerr << "Error binding socket\n";
            return false;
        }

        return true;
    }

    bool readFrame(can_frame& frame) {
        int nbytes = read(sockfd, &frame, sizeof(struct can_frame));
        if (nbytes < 0) {
            std::cerr << "Error reading CAN frame\n";
            return false;
        }
        if (nbytes < sizeof(struct can_frame)) {
            std::cerr << "Incomplete frame read\n";
            return false;
        }
        return true;
    }

    void printFrame(const can_frame& frame) {
        std::cout << "ID: 0x" << std::hex << frame.can_id 
                  << " DLC: " << std::dec << (int)frame.can_dlc << " Data: ";
        for (int i = 0; i < frame.can_dlc; i++) {
            std::cout << std::hex << (int)frame.data[i] << " ";
        }
        std::cout << std::dec << "\n";
    }

    ~CanReader() {
        close(sockfd);
    }
};

int main() {
    CanReader reader;

    if (!reader.init("can0")) {  // Use "vcan0" for virtual CAN
        return 1;
    }

    struct can_frame frame;
    std::cout << "Listening for CAN frames...\n";

    while (true) {
        if (reader.readFrame(frame)) {
            reader.printFrame(frame);
        }
    }

    return 0;
}
```

