import { readFileSync } from 'fs';

async function main() {
  const buffer = readFileSync('./MyDesign.sketch');
  const sketch = new Sketch(buffer);
  const doc = await sketch.parse();           // full document object

  for (const page of doc.pages) {
    console.log(`\n🔹 Page: ${page.name}`);
    function walk(layers) {
      layers.forEach(l => {
        console.log(`   - ${l._class}: ${l.name}`);
        if (l.layers) walk(l.layers);
      });
    }
    walk(page.layers);
  }
}

main().catch(console.error);
```

`sketch-constructor` hides the ZIP extraction, version differences, and image handling – it returns a nicely typed JavaScript object you can explore programmatically.

