## 2. Core parser – reading a file line‑by‑line

```java
import java.io.BufferedReader;
import java.io.IOException;
import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Very simplistic MT940 parser that extracts the most common tags.
 * It is not exhaustive (no support for multi‑line fields, Swift
 * extensions, or transaction type codes beyond the basics).
 */
public class Mt940Parser {

    // ---------- pattern helpers ----------
    // Tag pattern: :<tag>:<optional continuation>
    private static final Pattern TAG = Pattern.compile("^:(\\d{2}[A-Z]?):(.*)$");

    // :60F: C/DDDDYYYYMMDDCURRENCYAMOUNT
    // e.g. :60F:C180101EUR1000,00
    private static final Pattern PAT_OPEN_BAL = Pattern.compile(
        "^[CD](\\d{6})([A-Z]{3})([\\d,]+)$");  // C/D + YYMMDD + CUR + amount

    // :61: line – format: YYMMDD[MMDD]C/D[Amount][Reference]...
    // We'll keep it simple: capture date, debit/credit, amount and the textual reference.
    private static final Pattern PAT_TRANS = Pattern.compile(
        "^(\\d{6})(?:\\d{4})?" +               // value date (YYMMDD) + entry date optional
        "([CD])" +                             // Debit/Credit
        "([\\d,]+)" +                          // amount
        "(?:[A-Z]\\d{3})?" +                   // optional transaction type (ignored)
        "([A-Z0-9]{1,16})"                     // reference (up to 16 chars)
    );

    // :62F: same format as :60F:
    private static final Pattern PAT_CLOSE_BAL = Pattern.compile(
        "^[CD](\\d{6})([A-Z]{3})([\\d,]+)$");

    // :86: can be multi‑line – we accumulate until next tag
    private static final Pattern NEXT_TAG = Pattern.compile("^:(\\d{2}[A-Z]?):");

    /** Parse an MT940 file located at the given path. */
    public static Mt940Statement parse(Path file) throws IOException {
        List<Mt940Transaction> transactions = new ArrayList<>();

        String accountId = null;
        BigDecimal openBal = null;
        String openCur = null;
        BigDecimal closeBal = null;
        String closeCur = null;

        String currentTag = null;               // currently reading tag
        StringBuilder currentField = new StringBuilder();

        // temporary fields for building a transaction
        LocalDate txValueDate = null;
        LocalDate txEntryDate = null;
        BigDecimal txAmount = null;
        String txDebitCredit = null;
        String txReference = null;
        String txDescription = null;

        try (BufferedReader br = Files.newBufferedReader(file)) {
            String line;
            while ((line = br.readLine()) != null) {

                // If line starts a new tag while we are accumulating a previous one:
                if (NEXT_TAG.matcher(line).lookingAt()) {
                    // Finish previous tag processing
                    if (":61".equals(currentTag)) {
                        // finish transaction
                        if (txValueDate != null && txAmount != null) {
                            transactions.add(new Mt940Transaction(
                                txValueDate, txEntryDate, txAmount,
                                txDebitCredit, txReference,
                                (txDescription != null) ? txDescription.toString().trim() : ""));
                        }
                        // reset
                        txValueDate = txEntryDate = null;
                        txAmount = null; txDebitCredit = null;
                        txReference = null; txDescription = null;
                    }

                    // Start new tag
                    Matcher m = TAG.matcher(line);
                    if (m.find()) {
                        currentTag = m.group(1);
                        currentField.setLength(0);
                        currentField.append(m.group(2));
                    }
                } else {
                    // continuation of previous field
                    currentField.append(line.trim());
                }

                // Process the just‑finished tag (if we just moved to a new tag)
                // We do it right after we set currentTag/currentField.
                processTag(currentTag, currentField.toString(),
                        accountId, openBal, openCur,
                        (bal, cur) -> { openBal = bal; openCur = cur; },
                        (bal, cur) -> { closeBal = bal; closeCur = cur; },
                        (id) -> { accountId = id; },
                        // transaction accumulator
                        (valueDate, entryDate, amount, dc, ref, desc) -> {
                            txValueDate = valueDate;
                            txEntryDate = entryDate;
                            txAmount = amount;
                            txDebitCredit = dc;
                            txReference = ref;
                            txDescription = desc;
                        }
                );
            }

            // End‑of‑file: flush any open transaction
            if (":61".equals(currentTag) && txValueDate != null) {
                transactions.add(new Mt940Transaction(
                    txValueDate, txEntryDate, txAmount,
                    txDebitCredit, txReference,
                    (txDescription != null) ? txDescription.toString().trim() : ""));
            }
        }

        return new Mt940Statement(accountId, openBal, openCur,
                closeBal, closeCur, transactions);
    }

    /** Single method that routes processing for each tag. */
    private static void processTag(
            String tag,
            String value,
            // account identifier
            String accountId,
            // balances
            BigDecimal openBal, String openCur,
            java.util.function.BiConsumer<BigDecimal, String> setOpen,
            java.util.function.BiConsumer<BigDecimal, String> setClose,
            java.util.function.Consumer<String> setAccount,
            // transaction accumulator
            TransactionAccumulator acc) {

        if (tag == null) return;
        switch (tag) {
            case "20": // Transaction Reference Number – ignore
                break;
            case "25": // Account Identification
                setAccount.accept(value.trim());
                break;
            case "28C": // Statement Number – ignore
                break;
            case "60F": // Opening Balance
                parseBalance(value, setOpen);
                break;
            case "61": // Statement Line
                parseTransaction(value, acc);
                break;
            case "86": // Information to Account Owner – we already accumulate it in currentField
                // nothing to do here – handled in the loop as continuation of :61:
                break;
            case "62F": // Closing Balance
                parseBalance(value, setClose);
                break;
            default:
                // ignore any other tags
                break;
        }
    }

    // ---------- Balance parsing helpers ----------
    private static final DateTimeFormatter DATE6 = DateTimeFormatter.ofPattern("yyMMdd");

    private static void parseBalance(String raw, java.util.function.BiConsumer<BigDecimal, String> setter) {
        Matcher m = PAT_OPEN_BAL.matcher(raw);
        if (m.find()) {
            String sign = m.group(0).startsWith("C") ? "1" : "-1"; // C = credit (positive), D = debit (negative)
            BigDecimal amount = new BigDecimal(m.group(3).replace(",", "."));
            if (sign.equals("-1")) amount = amount.negate();
            String currency = m.group(2);
            setter.accept(amount, currency);
        }
    }

    // ---------- Transaction parsing helpers ----------
    private static void parseTransaction(String raw, TransactionAccumulator acc) {
        Matcher m = PAT_TRANS.matcher(raw);
        if (m.find()) {
            LocalDate valueDate = LocalDate.parse(m.group(1), DATE6);
            // optional entry date (MMDD) – we ignore for simplicity
            String dc = m.group(2); // "C" or "D"
            BigDecimal amount = new BigDecimal(m.group(3).replace(",", "."));
            String reference = m.group(4).trim();

            // entry date could be present after value date, we skip it for brevity
            acc.accept(valueDate, null, amount, dc, reference, "");
        }
    }

    /** Functional interface for building a transaction step‑by‑step. */
    @FunctionalInterface
    interface TransactionAccumulator {
        void accept(LocalDate valueDate, LocalDate entryDate,
                    BigDecimal amount, String dc, String reference, String desc);
    }
}
```

