## 3.  Quick Python version (using **pyOpenSSL**)

If you prefer a script that you can run without a C compiler, here’s a minimal example with the same logic using the **pyOpenSSL** package (`pip install pyopenssl`).

```python
#!/usr/bin/env python3
"""
tls13_early_data_py.py
-----------------------
Pythonic TLS 1.3 early‑data client that uses a fixed PSK.
"""

import socket
import binascii
from OpenSSL import SSL, crypto

# ------------------------------------------------------------------
# 1️⃣  Deterministic PSK (same as the C example)
# ------------------------------------------------------------------
PSK_IDENTITY = b"deterministic_psk_identity"
PSK_HEX = "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef"
PSK_BYTES = binascii.unhexlify(PSK_HEX)


def psk_client_callback(conn, identity):
    # pyOpenSSL will ask us for the PSK.
    # Return (identity, psk_bytes) as bytes.
    return PSK_IDENTITY, PSK_BYTES


# ------------------------------------------------------------------
# 2️⃣  Helper: create a TCP socket and wrap it with an OpenSSL context
# ------------------------------------------------------------------
def create_tls_connection(host: str, port: int, path: str):
    # Open plain TCP socket
    sock = socket.create_connection((host, port), timeout=10)

    # Build a TLS context (TLS 1.3 only)
    ctx = SSL.Context(SSL.TLSv1_3_METHOD)

    # Enable early‑data (0‑RTT) mode
    # OpenSSL constant for SSL_MODE_ENABLE_EARLY_DATA = 0x100000
    ctx.set_mode(0x100000)

    # Register the PSK callback
    ctx.set_psk_client_callback(psk_client_callback)

    # Wrap the socket
    ssl_conn = SSL.Connection(ctx, sock)
    ssl_conn.set_tlsext_host_name(host.encode())  # SNI
    ssl_conn.set_connect_state()

    # ------------------------------------------------------------------
    # 3️⃣  Handshake (sends ClientHello) – early‑data is enabled implicitly
    # ------------------------------------------------------------------
    ssl_conn.do_handshake()

    # ------------------------------------------------------------------
    # 4️⃣  Build a deterministic HTTP request
    # ------------------------------------------------------------------
    request = (
        f"GET {path} HTTP/1.1\r\n"
        f"Host: {host}\r\n"
        "Connection: close\r\n"
        "\r\n"
    ).encode()

    # ------------------------------------------------------------------
    # 5️⃣  Send request as early‑data (0‑RTT)
    # ------------------------------------------------------------------
    ssl_conn.send(request)

    # ------------------------------------------------------------------
    # 6️⃣  Read the server response (normal encrypted read)
    # ------------------------------------------------------------------
    response = b""
    while True:
        chunk = ssl_conn.recv(4096)
        if not chunk:
            break
        response += chunk

    # ------------------------------------------------------------------
    # 7️⃣  Cleanup
    # ------------------------------------------------------------------
    ssl_conn.shutdown()
    ssl_conn.close()
    sock.close()

    return response


if __name__ == "__main__":
    import sys
    if len(sys.argv) != 4:
        print(f"Usage: {sys.argv[0]} <host> <port> <path>")
        sys.exit(1)

    host, port, path = sys.argv[1], int(sys.argv[2]), sys.argv[3]
    resp = create_tls_connection(host, port, path)
    print(resp.decode())
```

### How to run

```bash
pip install pyopenssl
python3 tls13_early_data_py.py www.example.com 443 /
```

The Python wrapper does the same thing: the PSK callback supplies a static key, the context enables early‑data mode, and the `send()` call transmits the request as 0‑RTT.

