## 3.  A tiny echo server (to test the client)

`quic_server.c`

```c
/*
 * quic_server.c – tiny QUIC echo server.
 *
 * Build:
 *   gcc -Wall -O2 quic_server.c -lquiche -lssl -lcrypto -lpthread -o quic_server
 *
 * Run:
 *   ./quic_server 127.0.0.1 4433
 *
 * The server accepts one client, reads whatever the client sends on a
 * bidirectional stream and echoes it back.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <quiche.h>

#define BACKLOG 1
#define MAX_DGRAM 1350
#define BUFFER_SIZE (MAX_DGRAM * 4)

int main(int argc, char *argv[])
{
    const char *host = (argc > 1) ? argv[1] : "127.0.0.1";
    uint16_t port = (argc > 2) ? (uint16_t)atoi(argv[2]) : 4433;

    /* ---- 1. UDP socket ---- */
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) { perror("socket"); exit(EXIT_FAILURE); }

    struct sockaddr_in addr = {
        .sin_family = AF_INET,
        .sin_port   = htons(port),
        .sin_addr.s_addr = htonl(INADDR_ANY),
    };
    if (bind(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind"); close(sock); exit(EXIT_FAILURE);
    }

    /* ---- 2. QUIC listener configuration ---- */
    quiche_config *config = quiche_config_new(QUICHE_PROTOCOL_VERSION);
    if (!config) { fprintf(stderr, "config error\n"); exit(EXIT_FAILURE); }

    uint8_t alpn[] = { 0x05, 'h', 'q', '-', '2', '9' };
    quiche_config_set_application_protos(config, alpn, sizeof(alpn));
    quiche_config_set_initial_max_data(config, 10_000_000);
    quiche_config_set_initial_max_stream_data_bidi_local(config, 1_000_000);
    quiche_config_set_initial_max_stream_data_bidi_remote(config, 1_000_000);
    quiche_config_set_initial_max_stream_data_uni(config, 1_000_000);
    quiche_config_set_max_idle_timeout(config, 10_000);
    quiche_config_set_max_udp_payload_size(config, MAX_DGRAM);

    /* ---- 3. Accept a single client (for demo purposes) ---- */
    uint8_t recv_buf[BUFFER_SIZE];
    uint8_t send_buf[BUFFER_SIZE];
    struct sockaddr_storage client_addr;
    socklen_t client_addr_len = sizeof(client_addr);

    /* Receive the client’s first packet (the client‑hello) */
    ssize_t n = recvfrom(sock, recv_buf, sizeof(recv_buf), 0,
                         (struct sockaddr *)&client_addr, &client_addr_len);
    if (n < 0) { perror("recvfrom"); exit(EXIT_FAILURE); }

    /* Create a listener object */
    quiche_conn *conn = quiche_accept((const char *)recv_buf, n,
                                      (struct sockaddr *)&client_addr,
                                      client_addr_len,
                                      config);
    if (!conn) {
        fprintf(stderr, "failed to create server connection\n");
        exit(EXIT_FAILURE);
    }
    printf("Server connection created, CID=%s\n", quiche_conn_trace_id(conn));

    bool done = false;
    while (!done) {
        /* Send any outgoing packets */
        ssize_t written = quiche_conn_send(conn, send_buf, sizeof(send_buf));
        if (written < 0) { fprintf(stderr, "send error\n"); break; }
        if (written > 0) {
            sendto(sock, send_buf, written, 0,
                   (struct sockaddr *)&client_addr, client_addr_len);
        }

        /* Wait for data */
        fd_set read_fds;
        FD_ZERO(&read_fds);
        FD_SET(sock, &read_fds);
        struct timeval tv = { .tv_sec = 0, .tv_usec = 100_000 };
        int ready = select(sock + 1, &read_fds, NULL, NULL, &tv);
        if (ready <= 0) continue;

        n = recvfrom(sock, recv_buf, sizeof(recv_buf), 0,
                     (struct sockaddr *)&client_addr, &client_addr_len);
        if (n < 0) { perror("recvfrom"); break; }

        ssize_t consumed = quiche_conn_recv(conn, recv_buf, n);
        if (consumed < 0) { fprintf(stderr, "recv error\n"); break; }

        /* Read stream data and echo it back */
        int64_t stream_id;
        uint64_t offset;
        uint8_t data[8192];
        ssize_t len;
        while ((len = quiche_conn_stream_recv(conn, &stream_id, &offset,
                                              data, sizeof(data))) > 0) {
            /* Echo it back on the same stream */
            quiche_conn_stream_send(conn, stream_id, data, len, true);
        }

        if (quiche_conn_is_closed(conn) || quiche_conn_is_draining(conn))
            done = true;
    }

    quiche_conn_free(conn);
    quiche_config_free(config);
    close(sock);
    return 0;
}
```

