I'll provide a minimal working example of a UDP server that implements exactly-once delivery semantics in Go. This requires a protocol layer on top of UDP to handle reliability and deduplication.

```go
package main

import (
	"encoding/binary"
	"fmt"
	"log"
	"net"
	"sync"
	"time"
)

// Message represents a message with its metadata
type Message struct {
	ID      uint64
	Content []byte
}

// ReliableServer implements UDP with exactly-once semantics
type ReliableServer struct {
	conn          *net.UDPConn
	addr          *net.UDPAddr
	processedIDs  map[uint64]bool
	mu            sync.RWMutex
	windowSize    int
	maxSequenceID uint64
	cleanupInterval time.Duration
	quit          chan struct{}
}

// NewReliableServer creates a new reliable UDP server
func NewReliableServer(address string, port int) (*ReliableServer, error) {
	addr := net.UDPAddr{
		Port: port,
		IP:   net.ParseIP(address),
	}
	conn, err := net.ListenUDP("udp", &addr)
	if err != nil {
		return nil, err
	}

	return &ReliableServer{
		conn:             conn,
		addr:             &addr,
		processedIDs:     make(map[uint64]bool),
		windowSize:       100000, // Window size for deduplication
		cleanupInterval:  5 * time.Minute,
		quit:             make(chan struct{}),
	}, nil
}

// Start begins listening for messages
func (s *ReliableServer) Start(handler func(Message)) error {
	go s.cleanupRoutine()

	log.Printf("Server listening on %s:%d", s.addr.IP, s.addr.Port)

	for {
		select {
		case <-s.quit:
			return nil
		default:
			data := make([]byte, 65535)
			s.conn.SetReadDeadline(time.Now().Add(100 * time.Millisecond))
			n, clientAddr, err := s.conn.ReadFromUDP(data)
			if err != nil {
				if netErr, ok := err.(net.Error); ok && netErr.Timeout() {
					continue
				}
				log.Printf("Read error: %v", err)
				continue
			}

			go s.handleMessage(data[:n], clientAddr, handler)
		}
	}
}

// handleMessage processes incoming messages
func (s *ReliableServer) handleMessage(data []byte, clientAddr *net.UDPAddr, handler func(Message)) {
	if len(data) < 8 { // Minimum: 8 bytes for ID
		return
	}

	// Parse message ID (first 8 bytes)
	msgID := binary.BigEndian.Uint64(data[:8])
	content := data[8:]

	// Check if already processed
	s.mu.Lock()
	isDuplicate := s.processedIDs[msgID]

	if !isDuplicate {
		// Mark as processed
		s.processedIDs[msgID] = true
		s.maxSequenceID = msgID

		// Cleanup old entries if window is full
		if len(s.processedIDs) > s.windowSize {
			s.cleanupOldEntries()
		}
	}
	s.mu.Unlock()

	// Send ACK
	ack := make([]byte, 9)
	ack[0] = 0 // ACK type
	binary.BigEndian.PutUint64(ack[1:9], msgID)

	if isDuplicate {
		ack[0] = 2 // Duplicate ACK type
	} else {
		ack[0] = 1 // ACK type
		// Process the message
		handler(Message{ID: msgID, Content: content})
	}

	s.conn.WriteToUDP(ack, clientAddr)
}

// cleanupOldEntries removes old entries to maintain window size
func (s *ReliableServer) cleanupOldEntries() {
	// Remove entries older than the window allows
	minID := s.maxSequenceID - uint64(s.windowSize)
	for id := range s.processedIDs {
		if id < minID {
			delete(s.processedIDs, id)
		}
	}
}

// cleanupRoutine periodically cleans up old entries
func (s *ReliableServer) cleanupRoutine() {
	ticker := time.NewTicker(s.cleanupInterval)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			s.mu.Lock()
			// Keep only recent entries
			minID := s.maxSequenceID - uint64(s.windowSize)
			for id := range s.processedIDs {
				if id < minID {
					delete(s.processedIDs, id)
				}
			}
			s.mu.Unlock()
		case <-s.quit:
			return
		}
	}
}

// Close stops the server
func (s *ReliableServer) Close() error {
	close(s.quit)
	return s.conn.Close()
}

// ReliableClient implements UDP client with exactly-once semantics
type ReliableClient struct {
	conn         *net.UDPConn
	serverAddr   *net.UDPAddr
	pending      map[uint64]chan bool
	mu           sync.Mutex
	retryTimeout time.Duration
	maxRetries   int
}

// NewReliableClient creates a new reliable UDP client
func NewReliableClient(serverAddress string, serverPort int) (*ReliableClient, error) {
	serverAddr := net.UDPAddr{
		Port: serverPort,
		IP:   net.ParseIP(serverAddress),
	}

	conn, err := net.DialUDP("udp", nil, &serverAddr)
	if err != nil {
		return nil, err
	}

	return &ReliableClient{
		conn:         conn,
		serverAddr:   &serverAddr,
		pending:      make(map[uint64]chan bool),
		retryTimeout: 1 * time.Second,
		maxRetries:   5,
	}, nil
}

// Send sends a message with exactly-once semantics
func (c *ReliableClient) Send(id uint64, content []byte) error {
	// Build message
	msg := make([]byte, 8+len(content))
	binary.BigEndian.PutUint64(msg[:8], id)
	copy(msg[8:], content)

	// Create channel for this message
	responseChan := make(chan bool, 1)

	c.mu.Lock()
	c.pending[id] = responseChan
	c.mu.Unlock()

	// Send with retries
	for retries := 0; retries < c.maxRetries; retries++ {
		_, err := c.conn.Write(msg)
		if err != nil {
			return err
		}

		// Wait for ACK with timeout
		c.conn.SetReadDeadline(time.Now().Add(c.retryTimeout))
		ack := make([]byte, 9)
		n, err := c.conn.Read(ack)
		if err != nil {
			if netErr, ok := err.(net.Error); ok && netErr.Timeout() {
				continue // Retry
			}
			return err
		}

		if n == 9 && ack[0] == 1 { // Success ACK
			c.mu.Lock()
			delete(c.pending, id)
			c.mu.Unlock()
			return nil
		}

		// If we got a duplicate ACK, we're done
		if n == 9 && ack[0] == 2 {
			c.mu.Lock()
			delete(c.pending, id)
			c.mu.Unlock()
			return nil
		}
	}

	c.mu.Lock()
	delete(c.pending, id)
	c.mu.Unlock()

	return fmt.Errorf("max retries exceeded for message %d", id)
}

// Close closes the client connection
func (c *ReliableClient) Close() error {
	return c.conn.Close()
}

func main() {
	// Start server
	server, err := NewReliableServer("127.0.0.1", 8080)
	if err != nil {
		log.Fatal(err)
	}

	// Handle messages
	messageHandler := func(msg Message) {
		log.Printf("Received message ID=%d, Content=%s", msg.ID, string(msg.Content))
	}

	// Start server in goroutine
	go func() {
		if err := server.Start(messageHandler); err != nil {
			log.Fatal(err)
		}
	}()

	// Give server time to start
	time.Sleep(100 * time.Millisecond)

	// Start client
	client, err := NewReliableClient("127.0.0.1", 8080)
	if err != nil {
		log.Fatal(err)
	}
	defer client.Close()

	// Send messages
	testMessages := []struct {
		id      uint64
		content string
	}{
		{1, "Hello, World!"},
		{2, "This is a test"},
		{3, "Exactly-once delivery"},
	}

	for _, msg := range testMessages {
		err := client.Send(msg.id, []byte(msg.content))
		if err != nil {
			log.Printf("Failed to send message %d: %v", msg.id, err)
		} else {
			log.Printf("Successfully sent message %d", msg.id)
		}
	}

	// Test duplicate send (simulating retry)
	log.Println("\nTesting duplicate send (retry simulation):")
	err = client.Send(1, []byte("Hello, World!"))
	if err != nil {
		log.Printf("Duplicate send failed: %v", err)
	} else {
		log.Println("Duplicate send succeeded (already received by server)")
	}

	// Keep running to receive more messages
	time.Sleep(1 * time.Second)

	// Cleanup
	server.Close()
}
```

## Key Features:

1. **Exactly-Once Delivery**: Uses sequence IDs and acknowledgment system
2. **Deduplication**: Server tracks processed message IDs in a sliding window
3. **Reliability**: Client retries until ACK received
4. **ACK Types**: Separate ACKs for success (1) and duplicate (2)

## Protocol Details:

**Message Format (Client → Server):**
- Bytes 0-7: Message ID (uint64)
- Bytes 8+: Message content

**ACK Format (Server → Client):**
- Byte 0: ACK type (1=success, 2=duplicate)
- Bytes 1-8: Message ID (uint64)

## Testing the Example:

1. Run the program
2. Server receives messages and logs them
3. Duplicate sends are handled gracefully
4. Check server logs for "Received message" entries (only one per ID)

## Important Considerations:

1. **Window Size**: Adjust `windowSize` based on expected message volume
2. **Timeout**: Adjust retry timeout based on network conditions
3. **Storage**: For production, consider using Redis or similar for distributed systems
4. **Security**: Add message authentication (HMAC) for production use
5. **Scaling**: This example is single-server; distributed systems need shared state

This implementation provides a foundation for exactly-once UDP delivery. For production use, you'd want to add encryption, authentication, and more sophisticated deduplication strategies.

