public class CognivaultEsbClient {

    private final String baseUrl;            // e.g. https://cognivault-host:8443/api/v1
    private final String apiKey;             // supplied by the ESB admin
    private final HttpClient httpClient;
    private final ObjectMapper jsonMapper;   // for POJO → JSON

    /**
     * Constructs a new client.
     *
     * @param baseUrl  the base of the ESB REST API (no trailing slash)
     * @param apiKey   the API key placed in the {@code X‑API‑Key} header
     */
    public CognivaultEsbClient(String baseUrl, String apiKey) {
        this.baseUrl = baseUrl;
        this.apiKey = apiKey;
        this.httpClient = HttpClient.newBuilder()
                .connectTimeout(Duration.ofSeconds(10))
                .build();
        this.jsonMapper = new ObjectMapper();
    }

    /**
     * Sends a POJO payload to the ESB and returns the JSON response body.
     *
     * @param payload any object that Jackson can serialize (e.g. a Map or a custom DTO)
     * @return the JSON string returned by the ESB
     * @throws CognivaultIntegrationException if the call fails or the ESB returns a non‑2xx status
     */
    public String sendMessage(Object payload) throws CognivaultIntegrationException {
        try {
            String jsonPayload = jsonMapper.writeValueAsString(payload);

            HttpRequest request = HttpRequest.newBuilder()
                    .uri(URI.create(baseUrl + "/messages"))
                    .header("Content-Type", "application/json")
                    .header("X-API-Key", apiKey)
                    .POST(HttpRequest.BodyPublishers.ofString(jsonPayload))
                    .timeout(Duration.ofSeconds(30))
                    .build();

            HttpResponse<String> response = httpClient.send(request,
                    HttpResponse.BodyHandlers.ofString());

            int status = response.statusCode();
            if (status >= 200 && status < 300) {
                return response.body();                     // 2xx → success
            } else {
                throw new CognivaultIntegrationException(
                        "ESB returned an error. HTTP " + status + " – " + response.body());
            }
        } catch (IOException | InterruptedException e) {
            // Restore the interrupt flag and wrap the exception
            Thread.currentThread().interrupt();
            throw new CognivaultIntegrationException("Communication error with Cognivault ESB", e);
        }
    }

    /** Convenience method for sending a plain‑text message. */
    public String sendTextMessage(String text) throws CognivaultIntegrationException {
        return sendMessage(Map.of("content", text));
    }
}
```

