```go
// +build ignore

/*
Copy‑streams‑zero‑copy.go

A tiny program that demonstrates how to use the third‑party package
io/zerocopyutil to copy data between two streams without the usual
read/write buffer overhead.

Before you can build this file you need to have the package available:

	go get <repo>/io/zerocopyutil

Replace <repo> with the actual module path (e.g. github.com/user/zerocopyutil).

The program can be used directly to copy a file:

	go run copy‑streams‑zero‑copy.go src.txt dst.txt

or you can pipe data through it:

	cat src.txt | go run copy‑streams‑zero‑copy.go > dst.txt
*/
package main

import (
	"fmt"
	"io"
	"os"

	// This import assumes the module has been fetched with `go get`.
	"io/zerocopyutil"
)

func main() {
	// When no arguments are given we copy stdin → stdout.
	if len(os.Args) == 1 {
		if err := copyStreams(os.Stdin, os.Stdout); err != nil {
			fmt.Fprintf(os.Stderr, "stdin→stdout copy error: %v\n", err)
			os.Exit(1)
		}
		return
	}

	// When exactly two arguments are given we treat them as source and destination files.
	if len(os.Args) != 3 {
		fmt.Fprintf(os.Stderr, "Usage: %s [srcFile dstFile]\n", os.Args[0])
		os.Exit(1)
	}
	srcPath, dstPath := os.Args[1], os.Args[2]
	if err := copyFile(srcPath, dstPath); err != nil {
		fmt.Fprintf(os.Stderr, "file copy error: %v\n", err)
		os.Exit(1)
	}
}

// copyStreams copies all data from src to dst using the zero‑copy utility.
// It returns any error encountered.
func copyStreams(src io.Reader, dst io.Writer) error {
	// The API of io/zerocopyutil is intentionally simple:
	//   func Copy(dst io.Writer, src io.Reader) (int64, error)
	//
	// If the underlying platform does not support the required system call
	// (e.g. splice on Linux) the package may fall back to a normal buffered copy.
	n, err := zerocopyutil.Copy(dst, src)
	if err != nil {
		return err
	}
	fmt.Fprintf(os.Stderr, "copied %d bytes\n", n)
	return nil
}

// copyFile opens a source file for reading and a destination file for writing,
// then delegates to copyStreams.
func copyFile(srcPath, dstPath string) error {
	src, err := os.Open(srcPath)
	if err != nil {
		return fmt.Errorf("open source: %w", err)
	}
	defer src.Close()

	dst, err := os.Create(dstPath)
	if err != nil {
		return fmt.Errorf("create destination: %w", err)
	}
	defer dst.Close()

	return copyStreams(src, dst)
}
```

