package main

import (
	"context"
	"fmt"
	"log"
	"net"
	"os"
	"time"

	"gopkg.in/yaml.v3" // you can use any YAML parser you like

	"golang.org/x/enterprise/wpa2" // ← the package you asked for
)

// Config mirrors the YAML layout.
type Config struct {
	Interface   string        `yaml:"interface"`
	SSID        string        `yaml:"ssid"`
	Passphrase  string        `yaml:"passphrase"`
	Timeout     time.Duration `yaml:"timeout"`
}

func main() {
	// 1️⃣ Load configuration
	cfg, err := loadConfig("wifi.yaml")
	if err != nil {
		log.Fatalf("❌ failed to read config: %v", err)
	}

	// 2️⃣ Create a new wpa2 controller for the given interface.
	ctrl, err := wpa2.New(cfg.Interface)
	if err != nil {
		log.Fatalf("❌ failed to create wpa2 controller: %v", err)
	}
	defer ctrl.Close()

	// 3️⃣ (Optional) Verify the interface is up.
	if !ctrl.IsInterfaceUp() {
		log.Fatalf("❌ interface %s is not up; bring it up with `ip link set %s up`", cfg.Interface, cfg.Interface)
	}

	// 4️⃣ Add / update the network definition.
	netID, err := ctrl.AddNetwork(wpa2.NetworkConfig{
		SSID:      cfg.SSID,
		PSK:       cfg.Passphrase,
		KeyMgmt:   wpa2.KeyMgmtWPA2PSK,
		Proto:     wpa2.ProtoWPA2,
		Pairwise:  wpa2.PairwiseCCMP,
		Group:     wpa2.GroupCCMP,
		Priority:  10,
	}, true) // the second `true` tells the library to “enable” the network immediately
	if err != nil {
		log.Fatalf("❌ failed to add network: %v", err)
	}
	log.Printf("✅ Network added/updated (ID=%d) for SSID=%q", netID, cfg.SSID)

	// 5️⃣ Trigger a scan (optional, but good for validation).
	if err := ctrl.Scan(); err != nil {
		log.Printf("⚠️  scan request returned an error (non‑fatal): %v", err)
	}
	// Give the AP a moment to appear in the scan results.
	time.Sleep(2 * time.Second)

	// 6️⃣ Wait for the interface to get an IP address (DHCP).
	ctx, cancel := context.WithTimeout(context.Background(), cfg.Timeout)
	defer cancel()

	ip, err := waitForIP(ctx, cfg.Interface)
	if err != nil {
		log.Fatalf("❌ could not obtain IP on %s: %v", cfg.Interface, err)
	}
	log.Printf("🎉 Successfully connected! %s has IP %s", cfg.Interface, ip)
}

// loadConfig reads a YAML file and returns a populated Config.
func loadConfig(path string) (*Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("reading config file: %w", err)
	}
	var cfg Config
	if err := yaml.Unmarshal(data, &cfg); err != nil {
		return nil, fmt.Errorf("parsing YAML: %w", err)
	}
	// Sensible defaults if some fields are missing.
	if cfg.Timeout == 0 {
		cfg.Timeout = 30 * time.Second
	}
	if cfg.Interface == "" {
		cfg.Interface = "wlan0"
	}
	return &cfg, nil
}

// waitForIP polls the interface's addresses until an IPv4 address appears.
func waitForIP(ctx context.Context, iface string) (net.IP, error) {
	ticker := time.NewTicker(500 * time.Millisecond)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return nil, fmt.Errorf("timeout waiting for IP: %w", ctx.Err())
		case <-ticker.C:
			addrs, err := net.Interfaces()
			if err != nil {
				log.Printf("⚠️ net.Interfaces error: %v", err)
				continue
			}
			for _, a := range addrs {
				if a.Name != iface {
					continue
				}
				// Look for an IPv4 address that is up and not a loopback.
				ips, err := a.Addrs()
				if err != nil {
					continue
				}
				for _, ip := range ips {
					if ipv4, ok := ip.(*net.IPNet); ok && ipv4.IP.To4() != nil && !ipv4.IP.IsLoopback() {
						return ipv4.IP, nil
					}
				}
			}
		}
	}
}
```

