```cpp
// ---------------------------------------------------------------
// demo_auto_parallel.cpp
//
// Compile with (example on Linux):
//   g++ -std=c++17 -O2 -I${TBB_INC} demo_auto_parallel.cpp -ltbb -lpthread -o demo
//
// If you don't have the environment variables set, replace
// ${TBB_INC} with the path to the TBB include directory and
// ${TBB_LIB} with the path to the TBB libraries.
// ---------------------------------------------------------------

#include <tbb/auto_parallel.h>   // TBB_AUTO_PARALLEL_FOR lives here

#include <vector>
#include <cmath>
#include <iostream>

int main()
{
    // -------------------------------------------------
    // 1️⃣  Prepare some work – a vector of doubles.
    // -------------------------------------------------
    const std::size_t N = 1'000'000;
    std::vector<double> a(N);
    for (std::size_t i = 0; i < N; ++i) a[i] = static_cast<double>(i);

    // -------------------------------------------------
    // 2️⃣  Parallelise the loop that processes each element.
    // -------------------------------------------------
    // The macro expects four comma‑separated “clauses”
    //   init‑statement, condition, increment, loop‑body
    //
    //   TBB_AUTO_PARALLEL_FOR(init, test, inc, body);
    //
    // It expands (under the hood) to a call to
    //   tbb::parallel_for( blocked_range<size_t>(0,N), … )
    // using the default auto_partitioner that chooses the grain size
    // automatically at run‑time.
    //
    TBB_AUTO_PARALLEL_FOR(
        std::size_t i = 0,          // init
        i < N,                      // test
        ++i,                        // increment
        a[i] = std::sqrt(a[i]);     // body
    )

    // -------------------------------------------------
    // 3️⃣  Quick sanity‑check – print a few results.
    // -------------------------------------------------
    std::cout << "a[0]      = " << a[0]      << '\n';
    std::cout << "a[1]      = " << a[1]      << '\n';
    std::cout << "a[1000]   = " << a[1000]   << '\n';
    std::cout << "a[N‑1]    = " << a[N - 1]  << '\n';

    return 0;
}
```

