## 2. Minimal example

```cpp
// simd_sort_demo.cpp
// Compile with (e.g.):
//   g++ -std=c++17 -O3 -march=native -o simd_sort_demo simd_sort_demo.cpp

#include <experimental/simd_sort>   // the experimental SIMD sort API
#include <vector>
#include <iostream>
#include <random>
#include <algorithm>   // for std::generate, only needed to fill the vector
#include <chrono>      // for timing, optional

int main()
{
    // ------------------------------------------------------------
    // 1️⃣  Create a vector of floats and fill it with random values
    // ------------------------------------------------------------
    constexpr std::size_t N = 1'000'000;   // 1 M elements – enough to see a speed‑up
    std::vector<float> data(N);

    std::random_device rd;
    std::mt19937_64 gen(rd());
    std::uniform_real_distribution<float> dist(0.0f, 1'000'000.0f);

    std::generate(data.begin(), data.end(), [&]() { return dist(gen); });

    // ------------------------------------------------------------
    // 2️⃣  Time the SIMD sort (optional, just to see the benefit)
    // ------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // ---- This is the call you care about ----
    std::experimental::simd_sort(data.begin(), data.end());

    auto finish = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> elapsed = finish - start;

    // ------------------------------------------------------------
    // 3️⃣  Verify that the data really got sorted
    // ------------------------------------------------------------
    bool ok = std::is_sorted(data.begin(), data.end());
    std::cout << "Sorted: " << (ok ? "YES" : "NO") << '\n';
    std::cout << "SIMD sort took " << elapsed.count() << " seconds.\n";

    // ------------------------------------------------------------
    // 4️⃣  (Optional) Show a few first/last elements
    // ------------------------------------------------------------
    constexpr std::size_t PREVIEW = 5;
    std::cout << "\nFirst " << PREVIEW << " elements: ";
    for (std::size_t i = 0; i < PREVIEW; ++i)
        std::cout << data[i] << ' ';
    std::cout << "\nLast  " << PREVIEW << " elements: ";
    for (std::size_t i = N - PREVIEW; i < N; ++i)
        std::cout << data[i] << ' ';
    std::cout << '\n';
}
```

