**Install the package**

```bash
npm install react-magic-hooks   # or yarn add react-magic-hooks
```

**Typical usage in a component**

```tsx
import React from 'react';
import { useForm } from 'react-magic-hooks';

export default function ContactForm() {
  const {
    values,               // { name: string, email: string, … }
    errors,               // { name?: string, email?: string, … }
    touched,              // { name?: boolean, email?: boolean, … }
    isSubmitting,         // boolean – true while onSubmit is running
    handleChange,         // (e: ChangeEvent) => void
    handleBlur,           // (e: FocusEvent) => void
    handleSubmit,         // (e: FormEvent) => void
    resetForm,            // () => void
  } = useForm({
    // 1️⃣ Initial values for every field
    initialValues: { name: '', email: '' },

    // 2️⃣ Optional validation – return an object of field errors
    validate: (vals) => {
      const errs = {};
      if (!vals.name) errs.name = 'Name is required';
      if (!vals.email || !/\S+@\S+\.\S+/.test(vals.email))
        errs.email = 'Valid email is required';
      return errs;
    },

    // 3️⃣ Submit handler – receives the sanitised values
    onSubmit: async (vals, { setSubmitting }) => {
      console.log('🚀 Submitting:', vals);
      // e.g. await fetch('/api/contact', { method: 'POST', body: JSON.stringify(vals) });
      setSubmitting(false);   // tell the hook the async work is done
    },
  });

  return (
    <form onSubmit={handleSubmit} noValidate>
      <input
        name="name"
        value={values.name}
        onChange={handleChange}
        onBlur={handleBlur}
        placeholder="Name"
      />
      {touched.name && errors.name && <span style={{ color: 'red' }}>{errors.name}</span>}

      <input
        name="email"
        value={values.email}
        onChange={handleChange}
        onBlur={handleBlur}
        placeholder="Email"
      />
      {touched.email && errors.email && <span style={{ color: 'red' }}>{errors.email}</span>}

      <button type="submit" disabled={isSubmitting}>
        {isSubmitting ? 'Sending…' : 'Send'}
      </button>
      <button type="button" onClick={resetForm}>Reset</button>
    </form>
  );
}
```

**What you get**

- `values` – the current field values.
- `errors` / `touched` – populated by the `validate` function.
- `handleChange` / `handleBlur` – standard React event handlers that keep the hook’s state in sync.
- `handleSubmit` – runs validation and, if everything is clean, calls `onSubmit`.
- `isSubmitting` / `resetForm` – helpers for async submit flows and form resetting.

Just drop the hook into any functional component and you’ve got a tidy, all‑in‑one form state manager. 🚀

