async function fetchUserProfile(userId) {
  try {
    const { data } = await api.get(`/users/${userId}`);
    return data;
  } catch (err) {
    // After the configured number of retries the error will be thrown.
    // At this point you can decide how to present the failure to the user.
    console.error('❌ Failed to fetch user profile after retries', err.message);
    throw err;
