## 2️⃣  A tiny program that makes one HTTP GET

```rust
// src/main.rs
use hyper::{Body, Client, Method, Request};
use hyper::client::HttpConnector; // plain, non‑TLS connector
use http::header::HOST; // convenient constant for the Host header

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // ----- 1️⃣  Build a Hyper client -----
    // Hyper 0.14 ships its own default connector for HTTP/1.1.
    let client: Client<HttpConnector, Body> = Client::new();

    // ----- 2️⃣  Construct the request -----
    // (hyper requires a Host header for HTTP/1.1)
    let req = Request::builder()
        .method(Method::GET)
        .uri("http://example.com/")   // <-- change this to any URL you like
        .header(HOST, "example.com")
        .body(Body::empty())?;       // no body for a simple GET

    // ----- 3️⃣  Send it and await the response -----
    let res = client.request(req).await?;

    // ----- 4️⃣  Process the response -----
    println!("Response status: {}", res.status());

    // `res.into_body()` gives us a `Body` which implements `HttpBody`.
    // `hyper::body::to_bytes` collects the whole body into a single `Bytes`.
    let body_bytes = hyper::body::to_bytes(res.into_body()).await?;
    println!("Body (first 200 bytes):\n{:?}",
             String::from_utf8_lossy(&body_bytes).chars().take(200).collect::<String>());

    Ok(())
}
```

### What the snippet does, step‑by‑step

| Step | What we do | Why |
|------|------------|-----|
| **Create a `Client`** | `Client::new()` | Gives us a ready‑to‑use HTTP/1.1 (and optional HTTP/2) driver. |
