After the code you’ll find a short explanation of how the crate works and why you might want to use it.

---

## 1️⃣ Add the dependency

```toml
# Cargo.toml
[dependencies]
# The core SQLx runtime you need (tokio in this case)
sqlx = { version = "0.7", features = ["runtime-tokio", "tls-rustls", "postgres"] }

# The “turbocharged” pool wrapper
sqlx-turbopool = "0.1"

# Tokio runtime (required for async)
tokio = { version = "1", features = ["full"] }

# Optional: more convenient error handling
anyhow = "1"
```

> **Tip** – Make sure the `DATABASE_URL` environment variable is set, e.g.  
> `export DATABASE_URL=postgres://user:password@localhost/mydb`.

---

## 2️⃣ Full source (`src/main.rs`)

```rust
use anyhow::Result;
use sqlx::Row;
use sqlx_turbopool::{Config, TurboPool};

#[tokio::main]
async fn main() -> Result<()> {
    // -----------------------------------------------------------------
    // 1️⃣ Build a configuration from the usual DATABASE_URL env var.
    //    You can also tweak pool size, timeouts, TLS, etc. here.
    // -----------------------------------------------------------------
    let cfg = Config::from_env("DATABASE_URL")?
        .max_connections(10)   // optional – defaults are already sensible
        .min_connections(2);   // optional – keep a few connections warm

    // -----------------------------------------------------------------
    // 2️⃣ Create the TurboPool.  Under the hood it spins up a
    //    sqlx::PgPool and wraps it with a high‑throughput task queue.
    // -----------------------------------------------------------------
    let pool = TurboPool::new(cfg).await?;

    // -----------------------------------------------------------------
    // 3️⃣ Use the pool exactly like a normal sqlx::PgPool.
    //    TurboPool implements Deref<Target = sqlx::PgPool>, so any
    //    sqlx call that expects a pool works unchanged.
    // -----------------------------------------------------------------

    // A trivial query that returns a single integer.
    let row = sqlx::query("SELECT 42 AS answer")
        .fetch_one(pool.as_ref())   // pool.as_ref() gives &PgPool
        .await?;
    println!("The answer is: {}", row.get::<i32, _>("answer"));

    // A parameterised query – demonstrates binding & fetching.
    let user_id: i64 = 1;
    let row = sqlx::query("SELECT id, name, created_at FROM users WHERE id = $1")
        .bind(user_id)
        .fetch_one(pool.as_ref())
        .await?;
    let id: i64 = row.get("id");
    let name: String = row.get("name");
    let created: chrono::NaiveDateTime = row.get("created_at");
    println!("User #{} – {} (since {})", id, name, created);

    // Multiple rows – using fetch_all.
    let rows = sqlx::query("SELECT id, name FROM users ORDER BY id LIMIT 10")
