    constexpr auto stable_partition_inplace_fast(Rng& rng, Pred pred)
        -> std::ranges::subrange< std::ranges::iterator_t<Rng> >
    {
        // The standard algorithm already does an in‑place partition while
        // preserving the order of elements inside each partition.
        auto it = std::stable_partition(std::ranges::begin(rng),
                                        std::ranges::end(rng),
                                        pred);
