    // a file descriptor, a background task, etc.
    handle: tokio::task::JoinHandle<()>,
}

// --------------------------------------------------------------
// 4️⃣  Implement AsyncDrop – the compiler will call this when the
//      value’s lifetime ends inside an async context.
// --------------------------------------------------------------
impl AsyncDrop for MyResource {
    // The method must be `async fn` and takes `&mut self`.
    async fn drop(&mut self) {
        // This block runs *asynchronously* when the value is dropped.
        // Because we are already in an async runtime we can safely await.
        println!("[async drop] cleaning up resource #{}", self.id);

        // Example async cleanup: abort the background task and wait for it.
        self.handle.abort();               // ask the task to stop
        let _ = self.handle.await;        // wait for it to finish (will finish immediately after abort)

        println!("[async drop] resource #{} cleaned up", self.id);
    }
}

// --------------------------------------------------------------
// 5️⃣  Helper to create a `MyResource` that spawns a dummy background task
// --------------------------------------------------------------
impl MyResource {
    fn new(id: u32) -> Self {
        // Spawn a trivial background task that does nothing forever.
        let handle = tokio::spawn(async move {
            loop {
                tokio::time::sleep(std::time::Duration::from_secs(10)).await;
            }
        });

        MyResource { id, handle }
    }
}

// --------------------------------------------------------------
// 6️⃣  The async main function – everything lives inside an async context
// --------------------------------------------------------------
#[tokio::main]
async fn main() {
    println!("=== Creating a resource ===");
    let _r = MyResource::new(42);

    // … do some async work …
    tokio::time::sleep(std::time::Duration::from_millis(100)).await;
    println!("=== End of main – r will be dropped here ===");
}

// --------------------------------------------------------------
// Expected output (the async drop runs after the `main` function)
// --------------------------------------------------------------
// === Creating a resource ===
// === End of main – r will be dropped here ===
// [async drop] cleaning up resource #42
// [async drop] resource #42 cleaned up
```

### What the compiler does for you

When the compiler sees `impl AsyncDrop for MyResource`, it automatically synthesises a hidden *drop‑glue* future that looks (conceptually) like:

```rust
fn __async_drop_glue_myresource(this: &mut MyResource) -> impl Future<Output = ()> {
    async move {
        // the body of AsyncDrop::drop
        MyResource::drop(this).await;
    }
}
```

Whenever a value of type `MyResource` goes out of scope **inside an async block**, the runtime will schedule that hidden future and poll it to completion. The whole process is transparent to the programmer – you just write `let _r = …;` and the cleanup runs automatically.

---

## 3️⃣  Things you **must** keep in mind

| Rule | Why it matters |
|------|----------------|
| **You must be inside an async context** (`async fn`, `#[tokio::main]`, etc.) when the value is dropped. | The generated drop‑future needs a runtime to be polled. If you drop a `MyResource` in a non‑async context the program will panic (or dead‑lock) because there is no executor to drive the future. |
