    clock_gettime(CLOCK_MONOTONIC, &start);

    // --- Code to be timed starts here ---
    printf("Doing some work (sleeping for 2 seconds)...\n");
    sleep(2); 
    // --- Code to be timed ends here ---

    // 2. Capture end time
    clock_gettime(CLOCK_MONOTONIC, &end);

    double time_taken = get_elapsed_time(start, end);
    printf("Elapsed time: %.6f seconds\n", time_taken);

