use std::path::Path;

fn main() -> Result<(), ImageError> {
    // 1. Define our paths and crop area
    let input_path = "input.png";
    let output_path = "cropped_output.png";

    // Crop coordinates: (x, y, width, height)
    let (crop_x, crop_y, crop_width, crop_height) = (50, 50, 300, 200);

    println!("Loading image: {}...", input_path);

    // 2. Decode the PNG
    // open() automatically detects the format (PNG, JPEG, etc.)
    let img = image::open(input_path)?;

    // 3. Validate crop boundaries to prevent panics
    let (width, height) = img.dimensions();
    if crop_x + crop_width > width || crop_y + crop_height > height {
        panic!(
            "Crop area ({}, {}, {}, {}) exceeds image dimensions ({}x{})",
            crop_x, crop_y, crop_width, crop_height, width, height
        );
    }

    println!("Cropping image at ({}, {}) with size {}x{}...", 
              crop_x, crop_y, crop_width, crop_height);

