    // crop() returns a view; we call to_image() to convert it back to a DynamicImage
    let cropped = img.crop_imm(crop_x, crop_y, crop_width, crop_height);

    // 5. Save the result
    cropped.save(output_path)?;

    println!("Successfully saved cropped image to {}", output_path);
    Ok(())
}
```

