const readline = require('readline');

async function meanFromStream(readable) {
    const rl = readline.createInterface({ input: readable, crlfDelay: Infinity });

    let n = 0;
    let mu = 0;               // current mean (Number)

    for await (const line of rl) {
        const x = Number(line.trim());
        if (Number.isNaN(x)) continue;   // skip empty / non‑numeric lines
        n += 1;
        mu += (x - mu) / n;               // incremental update
    }

    if (n === 0) throw new Error('empty stream – mean undefined');
    return mu;
}

