### 3.1️⃣  Zero‑coordination CRDT Log (OR‑Set)

```go
// crdt_log.go
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"sync"
	"time"
)

// -------------------------------------------------------------------
// 1️⃣  Entry & unique identifier (Lamport timestamp + replica ID)
// -------------------------------------------------------------------
type Entry struct {
	ID        string `json:"id"`        // e.g. "3:nodeA"
	Timestamp int64  `json:"ts"`        // Lamport clock
	Payload   string `json:"payload"`   // user data
}

// -------------------------------------------------------------------
// 2️⃣  OR-Set based Log (add‑only, never removes)
// -------------------------------------------------------------------
type Log struct {
	mu       sync.RWMutex
	entries  map[string]Entry // map[id]Entry for O(1) dedup
	ordered  []Entry          // slice kept sorted by Timestamp, then ID
	clock    int64            // local Lamport clock
	replica  string           // unique name of this node
	peers    []string         // other replica HTTP endpoints
	httpPort string
}

// NewLog creates a fresh log instance.
func NewLog(replica, httpPort string, peers []string) *Log {
	return &Log{
		entries:  make(map[string]Entry),
		ordered:  []Entry{},
		clock:    0,
		replica:  replica,
		peers:    peers,
		httpPort: httpPort,
	}
}

// -------------------------------------------------------------------
// 3️⃣  Local append (no coordination)
// -------------------------------------------------------------------
func (l *Log) Append(payload string) Entry {
	l.mu.Lock()
	defer l.mu.Unlock()

	// Lamport tick
	l.clock++
	id := fmt.Sprintf("%d:%s", l.clock, l.replica)
	e := Entry{
		ID:        id,
		Timestamp: l.clock,
		Payload:   payload,
	}
	l.entries[id] = e
	l.ordered = append(l.ordered, e)

	// Fire‑and‑forget gossip to peers (best‑effort, no waiting)
	go l.gossip(e)

	return e
}

// -------------------------------------------------------------------
// 4️⃣  Gossip a single entry to all peers (zero‑coordination)
// -------------------------------------------------------------------
func (l *Log) gossip(e Entry) {
	body, _ := json.Marshal(e)
	for _, peer := range l.peers {
		// fire‑and‑forget POST; ignore errors (best‑effort)
		_, _ = http.Post(fmt.Sprintf("http://%s/gossip", peer), "application/json", bytesReader(body))
	}
}

// -------------------------------------------------------------------
// 5️⃣  Merge an incoming entry (idempotent)
// -------------------------------------------------------------------
func (l *Log) Merge(e Entry) {
	l.mu.Lock()
	defer l.mu.Unlock()

	// Update Lamport clock on receive
	if e.Timestamp > l.clock {
		l.clock = e.Timestamp
	}
	// If we already have this entry, ignore
	if _, ok := l.entries[e.ID]; ok {
		return
	}
	l.entries[e.ID] = e
	l.ordered = append(l.ordered, e)
}

// -------------------------------------------------------------------
// 6️⃣  HTTP handlers (append, read, gossip)
// -------------------------------------------------------------------
func (l *Log) serve() {
	http.HandleFunc("/append", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "POST only", http.StatusMethodNotAllowed)
			return
		}
		var payload struct{ Data string `json:"data"` }
		if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
			http.Error(w, "bad json", http.StatusBadRequest)
			return
		}
		e := l.Append(payload.Data)
		json.NewEncoder(w).Encode(e)
	})

	http.HandleFunc("/read", func(w http.ResponseWriter, r *http.Request) {
		l.mu.RLock()
		defer l.mu.RUnlock()
		json.NewEncoder(w).Encode(l.ordered)
	})

	http.HandleFunc("/gossip", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "POST only", http.StatusMethodNotAllowed)
			return
		}
		var e Entry
		if err := json.NewDecoder(r.Body).Decode(&e); err != nil {
			http.Error(w, "bad json", http.StatusBadRequest)
			return
		}
		l.Merge(e)
		w.WriteHeader(http.StatusNoContent)
	})

	log.Printf("[%s] listening on %s", l.replica, l.httpPort)
	log.Fatal(http.ListenAndServe(l.httpPort, nil))
}

// -------------------------------------------------------------------
// 7️⃣  Helper to turn []byte into io.Reader without allocation
// -------------------------------------------------------------------
func bytesReader(b []byte) *bytes.Reader { return bytes.NewReader(b) }

func main() {
	/*
	   Run two processes (or Docker containers) with different args, e.g.:

	   go run crdt_log.go nodeA :8000 nodeB:8001
	   go run crdt_log.go nodeB :8001 nodeA:8000
	*/
	if len(os.Args) < 4 {
		fmt.Println("usage: crdt_log <replica-id> <listen-addr> <peer1,peer2,...>")
		os.Exit(1)
	}
	replica := os.Args[1]
	listen := os.Args[2]
	peerList := strings.Split(os.Args[3], ",")

	log := NewLog(replica, listen, peerList)
	log.serve()
}
```

#### How it works

* **Append** – client POSTs `/append` with `{"data":"my event"}`. The node locally increments its Lamport clock, creates a globally unique ID (`<clock>:<replica>`), stores the entry, and *asynchronously* gossips it to all peers. No quorum, no waiting.
* **Read** – client GET `/read` returns the *local* view of the log. Because gossip is best‑effort, a read may be behind the latest write on another replica – this is the price of zero coordination.
* **Merge** – when a peer receives a gossip POST, it merges the entry idempotently and updates its clock.

**Safety property**: The set of entries is *monotonic* (once added, never removed) and the total order is deterministic (`Timestamp` then `ID`). All replicas that eventually receive the same set of entries will converge to the *same* ordered log.

**Limitations**  
* No linearizability.  
* No built‑in compaction – you’ll need a background job to truncate the log once entries are no longer needed.  

