### 3.2️⃣  Linearizable Log with Raft (using `etcd/raft`)

Below is a **minimal** Raft node that stores a log of strings. It uses the `etcd/raft` library (the same core used by etcd, TiKV, CockroachDB). The code is deliberately compact for learning purposes; production‑grade systems need snapshots, persistent storage, membership changes, etc.

```go
// raft_log.go
package main

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"strconv"
	"sync"
	"time"

	"go.etcd.io/etcd/raft/v3"
	pb "go.etcd.io/etcd/raft/v3/raftpb"
)

// -------------------------------------------------------------------
// 1️⃣  In‑memory Raft node wrapper
// -------------------------------------------------------------------
type Node struct {
	id        uint64
	peers     []uint64 // IDs of all members (including self)
	storage   *raft.MemoryStorage
	raftNode  raft.Node
	commitC   chan []byte // committed entries (application layer)
	errorC    chan error
	stopc     chan struct{}
	proposeC  chan string // client proposals (writes)
	snapshotC chan []byte // optional snapshot support (not used here)

	mu      sync.RWMutex
	leader  uint64 // current leader ID (0 = unknown)
	logs    []string
	httpPort string
}

// NewNode creates a fresh Raft node.
func NewNode(id uint64, peers []uint64, httpPort string) *Node {
	storage := raft.NewMemoryStorage()
	c := &raft.Config{
		ID:              id,
		ElectionTick:    10,
		HeartbeatTick:   1,
		Storage:         storage,
		MaxSizePerMsg:   4096,
		MaxInflightMsgs: 256,
		CheckQuorum:     true,
	}
	// First node starts a new cluster, others join an existing one.
	var startPeers []raft.Peer
	for _, p := range peers {
		startPeers = append(startPeers, raft.Peer{ID: p})
	}
	raftNode := raft.StartNode(c, startPeers)

	n := &Node{
		id:        id,
		peers:     peers,
		storage:   storage,
		raftNode:  raftNode,
		commitC:   make(chan []byte),
		errorC:    make(chan error),
		stopc:     make(chan struct{}),
		proposeC:  make(chan string),
		snapshotC: make(chan []byte),
		httpPort:  httpPort,
	}
	go n.run()
	return n
}

// -------------------------------------------------------------------
// 2️⃣  Core Raft event loop
// -------------------------------------------------------------------
func (n *Node) run() {
	ticker := time.NewTicker(100 * time.Millisecond)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			n.raftNode.Tick()
		case rd := <-n.raftNode.Ready():
			// Persist hard state & entries
			n.storage.Append(rd.Entries)
			if !raft.IsEmptyHardState(rd.HardState) {
				// In a real system you would persist HardState to stable storage.
			}
			// Apply committed entries to the state machine
			for _, entry := range rd.CommittedEntries {
				switch entry.Type {
				case pb.EntryNormal:
					if len(entry.Data) == 0 {
						// empty entry, usually a heartbeat
						continue
					}
					var cmd string
					if err := json.Unmarshal(entry.Data, &cmd); err != nil {
						log.Printf("[node %d] bad entry: %v", n.id, err)
						continue
					}
					n.apply(cmd)
				case pb.EntryConfChange:
					var cc pb.ConfChange
					cc.Unmarshal(entry.Data)
					n.raftNode.ApplyConfChange(cc)
				}
			}
			// Send messages to other nodes (network layer)
			n.sendMessages(rd.Messages)
			n.raftNode.Advance()
		case prop := <-n.proposeC:
			// Client wants to append a new log entry
			data, _ := json.Marshal(prop)
			n.raftNode.Propose(context.TODO(), data)
		case err := <-n.errorC:
			log.Fatalf("[node %d] fatal error: %v", n.id, err)
		case <-n.stopc:
			n.raftNode.Stop()
			return
		}
	}
}

// -------------------------------------------------------------------
// 3️⃣  Apply a command to the local state machine (our log)
// -------------------------------------------------------------------
func (n *Node) apply(cmd string) {
	n.mu.Lock()
	defer n.mu.Unlock()
	n.logs = append(n.logs, cmd)
}

// -------------------------------------------------------------------
// 4️⃣  Simple in‑process transport (HTTP) – send Raft messages
// -------------------------------------------------------------------
func (n *Node) sendMessages(msgs []pb.Message) {
	for _, m := range msgs {
		if m.To == n.id {
			// local message – feed it back directly
			n.raftNode.Step(context.TODO(), m)
			continue
		}
		// Remote: POST to peer's /raft endpoint
		url := fmt.Sprintf("http://%s/raft", peerAddr(m.To))
		body, _ := json.Marshal(m)
		resp, err := http.Post(url, "application/octet-stream", bytesReader(body))
		if err != nil {
			log.Printf("[node %d] send to %d failed: %v", n.id, m.To, err)
			continue
		}
		io.Copy(io.Discard, resp.Body)
		resp.Body.Close()
	}
}

// -------------------------------------------------------------------
// 5️⃣  HTTP API (client‑facing)
// -------------------------------------------------------------------
func (n *Node) serve() {
	http.HandleFunc("/append", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "POST only", http.StatusMethodNotAllowed)
			return
		}
		var payload struct{ Data string `json:"data"` }
		if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
			http.Error(w, "bad json", http.StatusBadRequest)
			return
		}
		// Propose to Raft – will be committed once a majority ack's it.
		n.proposeC <- payload.Data
		// For simplicity we respond *after* the proposal is queued.
		// In a production system you would wait for the entry to appear in the log.
		w.WriteHeader(http.StatusAccepted)
	})

	http.HandleFunc("/read", func(w http.ResponseWriter, r *http.Request) {
		// Linearizable read: forward to leader (or wait for read-index)
		if n.id != n.leader {
			leaderAddr := peerAddr(n.leader)
			if leaderAddr == "" {
				http.Error(w, "no leader known", http.StatusServiceUnavailable)
				return
			}
			// Proxy the request
			resp, err := http.Get(fmt.Sprintf("http://%s/read", leaderAddr))
			if err != nil {
				http.Error(w, "leader unreachable", http.StatusBadGateway)
				return
			}
			defer resp.Body.Close()
			w.WriteHeader(resp.StatusCode)
			io.Copy(w, resp.Body)
			return
		}
		// We are the leader – serve our local log
		n.mu.RLock()
		defer n.mu.RUnlock()
		json.NewEncoder(w).Encode(n.logs)
	})

	// Raft internal endpoint – receives messages from peers
	http.HandleFunc("/raft", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "POST only", http.StatusMethodNotAllowed)
			return
		}
		var msg pb.Message
		if err := json.NewDecoder(r.Body).Decode(&msg); err != nil {
			http.Error(w, "bad msg", http.StatusBadRequest)
			return
		}
		n.raftNode.Step(context.TODO(), msg)
		w.WriteHeader(http.StatusNoContent)
	})

	log.Printf("[node %d] listening on %s (leader=%d)", n.id, n.httpPort, n.leader)
	log.Fatal(http.ListenAndServe(n.httpPort, nil))
}

// -------------------------------------------------------------------
// 6️⃣  Helper: map node ID → address (hard‑coded for demo)
// -------------------------------------------------------------------
var addrMap = map[uint64]string{
	1: "localhost:9001",
	2: "localhost:9002",
	3: "localhost:9003",
}

func peerAddr(id uint64) string { return addrMap[id] }

// -------------------------------------------------------------------
// 7️⃣  Helper: bytesReader (same as in CRDT example)
// -------------------------------------------------------------------
func bytesReader(b []byte) *bytes.Reader { return bytes.NewReader(b) }

func main() {
	/*
	   Run three processes (or Docker containers) with args:

	   go run raft_log.go 1 localhost:9001 1,2,3
	   go run raft_log.go 2 localhost:9002 1,2,3
	   go run raft_log.go 3 localhost:9003 1,2,3

	   The third argument is a comma‑separated list of all node IDs.
	*/
	if len(os.Args) < 4 {
		fmt.Println("usage: raft_log <node-id> <listen-addr> <comma-separated-node-ids>")
		os.Exit(1)
	}
	id, _ := strconv.ParseUint(os.Args[1], 10, 64)
	listen := os.Args[2]
	idsStr := strings.Split(os.Args[3], ",")
	var peers []uint64
	for _, s := range idsStr {
		if v, err := strconv.ParseUint(s, 10, 64); err == nil {
			peers = append(peers, v)
		}
	}
	node := NewNode(id, peers, listen)
	go node.serve()

	// Block forever (or you could add signal handling)
	select {}
}
