### 3.2 `rpc.proto`

```proto
syntax = "proto3";

package lock;

service LockService {
  // Try to acquire a lock.  Returns a lease if successful.
  rpc Lock(LockRequest) returns (LockResponse);
  // Release a lock (or a lease that has already expired).
  rpc Unlock(UnlockRequest) returns (UnlockResponse);
  // Extend the lease.
  rpc Renew(RenewRequest) returns (RenewResponse);
}

// ------------------------------------------------------------------
// Requests / responses
// ------------------------------------------------------------------
message LockRequest {
  string lock_name = 1;   // name of the lock
  string client_id = 2;   // any unique identifier for the client
  int64  ttl_ms    = 3;   // desired lease time in ms (max 30000)
}
message LockResponse {
  bool   granted   = 1;   // false → lock already held
  string lease_id  = 2;   // opaque lease identifier (if granted)
  int64  ttl_ms    = 3;   // actual TTL granted (may be less than requested)
  string holder    = 4;   // current holder if not granted
}

message UnlockRequest {
  string lock_name = 1;
  string lease_id  = 2;   // must match the lease that granted the lock
}
message UnlockResponse {
  bool ok = 1;
}

message RenewRequest {
  string lease_id = 1;
  int64  ttl_ms   = 2;   // new TTL (must be <= max)
}
message RenewResponse {
  bool ok = 1;
}
```

