```java
import java.util.*;

public class KunduRahmanDemo {

    /* -------------------------------------------------
       1️⃣  Graph data structures
       ------------------------------------------------- */
    static class Edge {
        final int to;
        final int weight;
        Edge(int to, int weight) { this.to = to; this.weight = weight; }
    }

    static class Graph {
        final int V;
        final List<Edge>[] adj;
        @SuppressWarnings("unchecked")
        Graph(int V) {
            this.V = V;
            adj = new List[V];
            for (int i = 0; i < V; ++i) adj[i] = new ArrayList<>();
        }
        void addEdge(int from, int to, int weight) {
            if (weight < 0) throw new IllegalArgumentException("negative weight");
            adj[from].add(new Edge(to, weight));
        }
    }

    /* -------------------------------------------------
       2️⃣  Minimal integer deque (no boxing)
       ------------------------------------------------- */
    static final class IntArrayDeque {
        private int[] data = new int[8];
        private int head = 0, tail = 0;   // [head, tail)

        void addLast(int x) {
            if (tail == data.length) grow();
            data[tail++] = x;
        }

        int removeFirst() {
            return data[head++];
        }

        boolean isEmpty() {
            return head == tail;
        }

        private void grow() {
            int newCap = data.length * 2;
            int[] nd = new int[newCap];
            System.arraycopy(data, head, nd, 0, tail - head);
            tail -= head;
            head = 0;
            data = nd;
        }
    }

    /* -------------------------------------------------
       3️⃣  Bucket priority queue
       ------------------------------------------------- */
    static final class BucketQueue {
        private final IntArrayDeque[] buckets;
        int curIdx;          // smallest non‑empty bucket
        private int size;    // number of elements still in the queue

        BucketQueue(int maxDist) {
            buckets = new IntArrayDeque[maxDist + 1];
            for (int i = 0; i <= maxDist; ++i) buckets[i] = new IntArrayDeque();
            curIdx = 0;
            size = 0;
        }

        void add(int v, int d) {
            buckets[d].addLast(v);
            size++;
            if (d < curIdx) curIdx = d;
        }

        void decreaseKey(int v, int oldDist, int newDist) {
            // lazy deletion – just insert the new copy
            add(v, newDist);
        }

        int poll() {
            while (curIdx < buckets.length && buckets[curIdx].isEmpty()) curIdx++;
            if (curIdx >= buckets.length) return -1;
            int v = buckets[curIdx].removeFirst();
            size--;
            return v;
        }

        boolean isEmpty() { return size == 0; }
    }

    /* -------------------------------------------------
       4️⃣  Kundu‑Rahman (Dial) Dijkstra
       ------------------------------------------------- */
    static int[] kunduRahmanDijkstra(Graph g, int source, int maxWeight) {
        final int V = g.V;
        final int INF = Integer.MAX_VALUE;

        int[] dist = new int[V];
        Arrays.fill(dist, INF);
        dist[source] = 0;

        int maxDist = maxWeight * V;               // safe upper bound on any distance
        BucketQueue pq = new BucketQueue(maxDist);
        pq.add(source, 0);

        while (!pq.isEmpty()) {
            int u = pq.poll();
            int du = dist[u];

            // stale entry check – the bucket index we just popped is `pq.curIdx`
            if (du != pq.curIdx) continue;   // old copy, ignore

            for (Edge e : g.adj[u]) {
                int v = e.to;
                int nd = du + e.weight;
                if (nd < dist[v]) {
                    int old = dist[v];
                    dist[v] = nd;
                    if (old == INF) {
                        pq.add(v, nd);
                    } else {
                        pq.decreaseKey(v, old, nd);
                    }
                }
            }
        }
        return dist;
    }

    /* -------------------------------------------------
       5️⃣  Demo / test
       ------------------------------------------------- */
    public static void main(String[] args) {
        Graph g = new Graph(6);
        g.addEdge(0, 1, 2);
        g.addEdge(0, 2, 5);
        g.addEdge(1, 2, 1);
        g.addEdge(1, 3, 2);
        g.addEdge(2, 3, 3);
        g.addEdge(2, 4, 1);
        g.addEdge(3, 4, 2);
        g.addEdge(3, 5, 1);
        g.addEdge(4, 5, 2);

        int source = 0;
        int maxEdgeWeight = 5;   // we know the largest weight in the graph

        int[] dist = kunduRahmanDijkstra(g, source, maxEdgeWeight);

        System.out.println("Shortest distances from vertex " + source + ":");
        for (int v = 0; v < g.V; ++v) {
            if (dist[v] == Integer.MAX_VALUE) {
                System.out.printf("  %d : unreachable%n", v);
            } else {
                System.out.printf("  %d : %d%n", v, dist[v]);
            }
        }
    }
}
