## 4. Compiler from Mini‑Imp → StackVM

The compiler is a **syntax‑directed translation** that produces a *linear* list of instructions.  The only non‑trivial part is handling control flow (`if`/`while`).  We generate fresh labels using a simple counter.

```java
public final class Compiler {

    private static int labelCounter = 0;
    private static String freshLabel(String prefix) {
        return prefix + "_" + (labelCounter++);
    }

    /** Compile an expression, leaving its value on the stack. */
    public static void compileExpr(MiniImp.Expr e, StackVM.Program prog) {
        switch (e) {
            case MiniImp.Lit lit -> prog.add(new StackVM.Push(lit.v()));
            case MiniImp.Var v   -> prog.add(new StackVM.Load(v.name()));
            case MiniImp.Add a   -> {
                compileExpr(a.l(), prog);
                compileExpr(a.r(), prog);
                prog.add(StackVM.BinOp.ADD);
            }
            case MiniImp.Sub a   -> {
                compileExpr(a.l(), prog);
                compileExpr(a.r(), prog);
                prog.add(StackVM.BinOp.SUB);
            }
            case MiniImp.Mul a   -> {
                compileExpr(a.l(), prog);
                compileExpr(a.r(), prog);
                prog.add(StackVM.BinOp.MUL);
            }
            default -> throw new AssertionError("unexpected expr: " + e);
        }
    }

    /** Compile a Boolean expression, leaving 0 (false) or 1 (true) on the stack. */
    public static void compileBool(MiniImp.Bool b, StackVM.Program prog) {
        switch (b) {
            case MiniImp.BTrue _  -> prog.add(new StackVM.Push(1));
            case MiniImp.BFalse _ -> prog.add(new StackVM.Push(0));
            case MiniImp.Eq eq    -> {
                compileExpr(eq.l(), prog);
                compileExpr(eq.r(), prog);
                prog.add(StackVM.BinOp.EQ);
            }
            case MiniImp.Lt lt    -> {
                compileExpr(lt.l(), prog);
                compileExpr(lt.r(), prog);
                prog.add(StackVM.BinOp.LT);
            }
            case MiniImp.Not n    -> {
                compileBool(n.b(), prog);
                prog.add(StackVM.UnOp.NOT);
            }
            case MiniImp.And a    -> {
                compileBool(a.l(), prog);
                compileBool(a.r(), prog);
                prog.add(StackVM.BinOp.AND);
            }
            default -> throw new AssertionError("unexpected bool: " + b);
        }
    }

    /** Compile a command. */
    public static void compileCmd(MiniImp.Cmd c, StackVM.Program prog) {
        switch (c) {
            case MiniImp.Skip _ -> { /* nothing */ }
            case MiniImp.Assign a -> {
                compileExpr(a.e(), prog);
                prog.add(new StackVM.Store(a.name()));
            }
            case MiniImp.Seq s -> {
                compileCmd(s.c1(), prog);
                compileCmd(s.c2(), prog);
            }
            case MiniImp.If iff -> {
                String elseLbl = freshLabel("else");
                String endLbl  = freshLabel("endif");
                compileBool(iff.cond(), prog);
                prog.add(new StackVM.JumpZero(elseLbl));
                compileCmd(iff.thn(), prog);
                prog.add(new StackVM.Jump(endLbl));
                prog.add(new StackVM.Label(elseLbl));
                compileCmd(iff.els(), prog);
                prog.add(new StackVM.Label(endLbl));
            }
            case MiniImp.While w -> {
                String testLbl = freshLabel("while_test");
                String bodyLbl = freshLabel("while_body");
                String endLbl  = freshLabel("while_end");
                prog.add(new StackVM.Label(testLbl));
                compileBool(w.cond(), prog);
                prog.add(new StackVM.JumpZero(endLbl));
                prog.add(new StackVM.Label(bodyLbl));
                compileCmd(w.body(), prog);
                prog.add(new StackVM.Jump(testLbl));
                prog.add(new StackVM.Label(endLbl));
            }
            default -> throw new AssertionError("unexpected cmd: " + c);
        }
    }

    /** Convenience: compile a whole program and return the bytecode. */
    public static StackVM.Program compile(MiniImp.Cmd top) {
        labelCounter = 0; // reset for reproducibility
        StackVM.Program prog = new StackVM.Program();
        compileCmd(top, prog);
        return prog;
    }
}
```

**Running the compiled version**

```java
public class Demo {
    public static void main(String[] args) {
        MiniImp.Cmd prog = /* same factorial program as before */;
        MiniImp.Store init = new MiniImp.Store();

        // 1️⃣ Reference result (interpreter)
        MiniImp.Store ref = MiniImp.exec(prog, init);
        System.out.println("Interpreter: out = " + ref.get("out")); // 120

        // 2️⃣ Compile → bytecode
        StackVM.Program bytecode = Compiler.compile(prog);
        // 3️⃣ Run the bytecode on the same empty store
        Map<String,Integer> vmResult = StackVM.run(bytecode);
        System.out.println("VM: out = " + vmResult.get("out")); // 120
    }
}
```

Both prints should show `120`.  That empirical test is *not* a proof, but it tells us the compiler works on at least one non‑trivial program.

