Below is a **self‑contained, header‑only** implementation that gives you **portable, lock‑free 64‑bit loads and stores** on every platform that the C11 (or later) standard library supports.  
If the compiler does not have full C11 support it falls back to the GCC/Clang `__atomic` built‑ins, and as a last resort it uses a tiny spin‑lock that works everywhere.

```c
/* -------------------------------------------------------------------------
 * atomic64.h
 *
 * Portable, lock‑free 64‑bit atomic load/store.
 *
 *   uint64_t atomic_load64 (const volatile uint64_t *p);
 *   void    atomic_store64(volatile uint64_t *p, uint64_t v);
 *
 * The implementation prefers C11 <stdatomic.h>.  If that header is not
 * available it uses GCC/Clang __atomic built‑ins, and finally a fallback
 * based on a spin‑lock.
 *
 * The functions are safe on any architecture that can perform a naturally
 * aligned 64‑bit load/store atomically (most 64‑bit CPUs, and many 32‑bit
 * CPUs such as x86‑64, ARMv8, PowerPC, etc.).  On platforms where that
 * guarantee does not exist the fallback lock guarantees atomicity.
 *
 * ------------------------------------------------------------------------- */
#ifndef ATOMIC64_H
#define ATOMIC64_H

/* -------------------------------------------------------------------------
 * 1. Detect the best implementation we can use
 * ------------------------------------------------------------------------- */
#if defined(__STDC_VERSION__) && (__STDC_VERSION__ >= 201112L) && \
    !defined(__STDC_NO_ATOMICS__) && !defined(__cplusplus)
/* -------------------------------------------------
 *   C11 atomics (the preferred path)
 * ------------------------------------------------- */
#include <stdatomic.h>
#include <stddef.h>

static inline uint64_t atomic_load64(const volatile uint64_t *p)
{
    /* The object must be _Atomic or be accessed through an
       atomic_load_explicit call.  We cast to _Atomic to avoid
       requiring the caller to declare the variable as _Atomic.   */
    return atomic_load_explicit((_Atomic uint64_t *)p,
                                memory_order_seq_cst);
}

static inline void atomic_store64(volatile uint64_t *p, uint64_t v)
{
    atomic_store_explicit((_Atomic uint64_t *)p,
                          v,
                          memory_order_seq_cst);
}

/* -------------------------------------------------
 *   C++11 atomics (if compiled as C++)
 * ------------------------------------------------- */
#elif defined(__cplusplus) && (__cplusplus >= 201103L)
#include <atomic>

static inline uint64_t atomic_load64(const volatile uint64_t *p)
{
    return std::atomic_load_explicit(
        reinterpret_cast<volatile std::atomic<uint64_t> *>(const_cast<uint64_t *>(p)),
        std::memory_order_seq_cst);
}

static inline void atomic_store64(volatile uint64_t *p, uint64_t v)
{
    std::atomic_store_explicit(
        reinterpret_cast<volatile std::atomic<uint64_t> *>(p),
        v,
        std::memory_order_seq_cst);
}

/* -------------------------------------------------
 *   GCC/Clang __atomic built‑ins (C99 or older C++)
 * ------------------------------------------------- */
#elif defined(__GNUC__) || defined(__clang__)
#include <stddef.h>

static inline uint64_t atomic_load64(const volatile uint64_t *p)
{
    return __atomic_load_n(p, __ATOMIC_SEQ_CST);
}

static inline void atomic_store64(volatile uint64_t *p, uint64_t v)
{
    __atomic_store_n(p, v, __ATOMIC_SEQ_CST);
}

/* -------------------------------------------------
 *   Fallback: a tiny spin‑lock (works everywhere)
 * ------------------------------------------------- */
#else
#include <stddef.h>
#include <stdint.h>

/* A single global lock is enough for the tiny library – it adds only a few
   nanoseconds of overhead on platforms that need it.  If you need higher
   concurrency you can replace this with a per‑variable lock or a lock‑free
   implementation for your target. */
static volatile int atomic64_fallback_lock = 0;

/* Simple test‑and‑set spin lock (busy‑wait).  It works on any CPU that
   provides atomic read‑modify‑write of a byte (most do). */
static inline void atomic64_lock(void)
{
    while (__sync_lock_test_and_set(&atomic64_fallback_lock, 1))
        ;   /* spin */
}

static inline void atomic64_unlock(void)
{
    __sync_lock_release(&atomic64_fallback_lock);
}

static inline uint64_t atomic_load64(const volatile uint64_t *p)
{
    uint64_t v;
    atomic64_lock();
    v = *p;                     /* ordinary read – protected by the lock */
    atomic64_unlock();
    return v;
}

static inline void atomic_store64(volatile uint64_t *p, uint64_t v)
{
    atomic64_lock();
    *p = v;                     /* ordinary write – protected by the lock */
    atomic64_unlock();
}
#endif   /* implementation selector */

/* -------------------------------------------------------------------------
 * 2. Optional helpers (compare‑and‑swap, fetch‑add) – not required for the
 *    question but often useful together with load/store.
 * ------------------------------------------------------------------------- */
#if defined(__STDC_VERSION__) && (__STDC_VERSION__ >= 201112L) && \
    !defined(__STDC_NO_ATOMICS__) && !defined(__cplusplus)

static inline bool atomic_cas64(volatile uint64_t *p,
                                uint64_t *expected,
                                uint64_t desired)
{
    return atomic_compare_exchange_strong_explicit(
        (_Atomic uint64_t *)p,
        expected,
        desired,
        memory_order_seq_cst,
        memory_order_seq_cst);
}

static inline uint64_t atomic_fetch_add64(volatile uint64_t *p, uint64_t inc)
{
    return atomic_fetch_add_explicit((_Atomic uint64_t *)p,
                                     inc,
                                     memory_order_seq_cst);
}
#endif

#endif /* ATOMIC64_H */
```

---

## How it works

| Step | What the code does | Why it guarantees atomicity |
|------|--------------------|-----------------------------|
| **1. Prefer C11 `<stdatomic.h>`** | Uses `atomic_load_explicit` / `atomic_store_explicit` on a pointer that is cast to `_Atomic uint64_t *`. | The C11 memory model guarantees that a *naturally aligned* 64‑bit load/store on an `_Atomic` object is **lock‑free** on any platform that reports `ATOMIC_UINT64_T_LOCK_FREE == 2`. If the platform cannot do it lock‑free the implementation still provides the required atomicity (it may use a hidden lock internally). |
| **2. C++11 fallback** | Same idea, but with `std::atomic<uint64_t>`. | C++11 inherits the same guarantees as C11. |
| **3. GCC/Clang `__atomic` built‑ins** | Calls `__atomic_load_n` / `__atomic_store_n` with `__ATOMIC_SEQ_CST`. | These built‑ins are defined to be atomic on any target the compiler supports; they emit the appropriate lock‑free instruction or a library call if needed. |
| **4. Pure‑C fallback** | Implements a tiny spin‑lock (`atomic64_fallback_lock`) using the GCC/Clang `__sync_*` primitives (which are themselves atomic test‑and‑set). The lock protects a plain `uint64_t` read or write. | The lock serialises all accesses, so even on a 32‑bit CPU that cannot move 64 bits in one bus cycle the operation is still atomic with respect to other threads. The overhead is only a few extra instructions on platforms that actually need the lock. |
| **5. Alignment** | All functions expect the pointer to be *naturally aligned* (8‑byte aligned). | On most CPUs an unaligned 64‑bit access either traps or is performed as two separate bus cycles, breaking atomicity. The caller should either declare the variable with `alignas(8)` (C11) or ensure it lives in a struct that is naturally aligned. |
| **6. Memory ordering** | `memory_order_seq_cst` (sequentially consistent) is used, the strongest ordering. | This matches the “atomic read/write” guarantee most developers expect: every load sees the most recent store in a total order that is consistent across all threads. If you need weaker ordering you can replace the `*_explicit` calls with `memory_order_relaxed`, `memory_order_acquire`, etc. |

### When is the lock‑free path taken?

* **64‑bit CPUs** (x86‑64, AArch64, PowerPC64, s390x, …) – the compiler reports `ATOMIC_UINT64_T_LOCK_FREE == 2` and the load/store compiles to a single `mov`/`ldr`/`str` instruction.
* **Modern 32‑bit CPUs** that support atomic 64‑bit accesses (e.g., ARMv7 with LDREXD/STREXD, x86‑32 with `cmpxchg8b`) – the compiler also emits a lock‑free sequence.
* **Older 32‑bit CPUs** that lack such instructions – the compiler falls back to a library call that internally uses a lock, or our own spin‑lock fallback is used. In all cases the caller sees a *single* atomic operation.

