## 3. `fsm.go` – the state machine (KV store)

```go
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"sync"

	"github.com/hashicorp/raft"
)

// Command is the payload that gets replicated via Raft.
type Command struct {
	Op    string // "set" or "delete"
	Key   string
	Value string // only for "set"
}

// KVStore implements raft.FSM – the deterministic state machine.
type KVStore struct {
	mu   sync.RWMutex
	data map[string]string
}

// NewKVStore creates an empty store.
func NewKVStore() *KVStore {
	return &KVStore{
		data: make(map[string]string),
	}
}

// Apply is called by Raft on the leader *and* on followers when a log entry
// becomes committed.  It must be deterministic.
func (k *KVStore) Apply(l *raft.Log) interface{} {
	var cmd Command
	if err := json.Unmarshal(l.Data, &cmd); err != nil {
		log.Printf("[FSM] failed to unmarshal command: %v", err)
		return err
	}

	k.mu.Lock()
	defer k.mu.Unlock()

	switch cmd.Op {
	case "set":
		k.data[cmd.Key] = cmd.Value
		return nil
	case "delete":
		delete(k.data, cmd.Key)
		return nil
	default:
		return fmt.Errorf("unknown op %s", cmd.Op)
	}
}

// Snapshot returns a point‑in‑time snapshot of the FSM.
func (k *KVStore) Snapshot() (raft.FSMSnapshot, error) {
	k.mu.RLock()
	defer k.mu.RUnlock()

	// Deep‑copy the map so the snapshot can be taken without holding the lock.
	clone := make(map[string]string, len(k.data))
	for k, v := range k.data {
		clone[k] = v
	}
	return &kvSnapshot{store: clone}, nil
}

// Restore restores the FSM from a snapshot.
func (k *KVStore) Restore(rc io.ReadCloser) error {
	defer rc.Close()
	dec := json.NewDecoder(rc)
	newData := make(map[string]string)
	if err := dec.Decode(&newData); err != nil {
		return err
	}
	k.mu.Lock()
	k.data = newData
	k.mu.Unlock()
	return nil
}

// ---------- Snapshot implementation ----------
type kvSnapshot struct {
	store map[string]string
}

// Persist writes the snapshot to the given sink.
func (s *kvSnapshot) Persist(sink raft.SnapshotSink) error {
	b, err := json.Marshal(s.store)
	if err != nil {
		sink.Cancel()
		return err
	}
	if _, err := sink.Write(b); err != nil {
		sink.Cancel()
		return err
	}
	return sink.Close()
}

// Release is a no‑op for this simple implementation.
func (s *kvSnapshot) Release() {}
```

