## 5. `client.go` – thin RPC client for `PUT`/`GET`

```go
package main

import (
	"encoding/json"
	"fmt"
	"net"
	"net/rpc"
	"time"
)

// RPC request / response structs
type PutArgs struct {
	Key   string
	Value string
}
type PutReply struct{}
type GetArgs struct {
	Key string
}
type GetReply struct {
	Value string
	Found bool
}

// Client wraps an RPC connection to a single Raft node.
type Client struct {
	addr string
}

// NewClient creates a client that talks to the node at addr (host:port).
func NewClient(addr string) *Client {
	return &Client{addr: addr}
}

// Put sends a write request.  The server will forward it to the leader if
// this node is not the leader.
func (c *Client) Put(key, value string) error {
	args := PutArgs{Key: key, Value: value}
	var reply PutReply
	return c.call("Node.Put", args, &reply)
}

// Get sends a read request.  The server will reject the request if it is not
// the leader (or if it cannot guarantee linearizability), forcing the client
// to retry against the current leader.
func (c *Client) Get(key string) (string, bool, error) {
	args := GetArgs{Key: key}
	var reply GetReply
	err := c.call("Node.Get", args, &reply)
	if err != nil {
		return "", false, err
	}
	return reply.Value, reply.Found, nil
}

// internal RPC helper
func (c *Client) call(serviceMethod string, args interface{}, reply interface{}) error {
	conn, err := net.DialTimeout("tcp", c.addr, 2*time.Second)
	if err != nil {
		return err
	}
	defer conn.Close()
	client := rpc.NewClient(conn)
	defer client.Close()
	call := client.Go(serviceMethod, args, reply, nil)
	select {
	case <-call.Done:
		return call.Error
	case <-time.After(3 * time.Second):
		return fmt.Errorf("rpc timeout")
	}
}
```

