## 6. `main.go` – the Raft node + RPC server

```go
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net"
	"net/rpc"
	"os"
	"path/filepath"
	"time"

	"github.com/hashicorp/raft"
	"github.com/hashicorp/raft-boltdb"
)

// Node implements the RPC methods exposed to clients.
type Node struct {
	Raft *raft.Raft
	FSM  *KVStore
}

// Put is the client‑facing write operation.  It is *only* allowed on the leader.
// If the node is not the leader we return a special error so the client can
// retry against the known leader.
func (n *Node) Put(args PutArgs, reply *PutReply) error {
	if n.Raft.State() != raft.Leader {
		leader := n.Raft.Leader()
		return fmt.Errorf("not leader; current leader is %s", leader)
	}
	cmd := Command{
		Op:    "set",
		Key:   args.Key,
		Value: args.Value,
	}
	data, err := json.Marshal(cmd)
	if err != nil {
		return err
	}
	// Apply with a timeout – the command is replicated and committed before we
	// return, giving linearizability.
	future := n.Raft.Apply(data, 5*time.Second)
	if err := future.Error(); err != nil {
		return err
	}
	return nil
}

// Get is the client‑facing read operation.  To guarantee linearizability we
// perform a *ReadIndex* round‑trip first (the Raft library does this when we
// call `ReadIndex`).  If the node is not the leader we reject the request.
func (n *Node) Get(args GetArgs, reply *GetReply) error {
	if n.Raft.State() != raft.Leader {
		leader := n.Raft.Leader()
		return fmt.Errorf("not leader; current leader is %s", leader)
	}
	// ---- Linearizable read via ReadIndex ----
	// The future completes once the leader has committed a no‑op entry that
	// guarantees the read sees all prior writes.
	riFuture := n.Raft.ReadIndex()
	if err := riFuture.Error(); err != nil {
		return fmt.Errorf("read index failed: %w", err)
	}
	// At this point the leader's commit index is up‑to‑date.
	n.FSM.mu.RLock()
	val, ok := n.FSM.data[args.Key]
	n.FSM.mu.RUnlock()
	reply.Value = val
	reply.Found = ok
	return nil
}

// ---------- Raft bootstrap helpers ----------
func setupRaft(nodeID, bindAddr, dataDir string, peers []raft.Server) (*raft.Raft, *KVStore, error) {
	// 1️⃣  Transport (TCP)
	transport, err := NewTransport(bindAddr, 3)
	if err != nil {
		return nil, nil, err
	}

	// 2️⃣  Stable storage (BoltDB)
	if err := os.MkdirAll(dataDir, 0700); err != nil {
		return nil, nil, err
	}
	boltDB, err := raftboltdb.NewBoltStore(filepath.Join(dataDir, "raft.db"))
	if err != nil {
		return nil, nil, err
	}

	// 3️⃣  Log store (also BoltDB)
	logStore := boltDB

	// 4️⃣  Snapshot store (file system)
	snapshots, err := raft.NewFileSnapshotStore(dataDir, 2, os.Stderr)
	if err != nil {
		return nil, nil, err
	}

	// 5️⃣  FSM (our KV store)
	fsm := NewKVStore()

	// 6️⃣  Raft config
	config := raft.DefaultConfig()
	config.LocalID = raft.ServerID(nodeID)
	// Short election timeout for demo purposes – in production use larger values.
	config.HeartbeatTimeout = 500 * time.Millisecond
	config.ElectionTimeout = 2 * time.Second
	config.LeaderLeaseTimeout = 500 * time.Millisecond
	config.CommitTimeout = 50 * time.Millisecond

	// 7️⃣  Build the Raft node
	ra, err := raft.NewRaft(config, fsm, logStore, boltDB, snapshots, transport)
	if err != nil {
		return nil, nil, err
	}

	// 8️⃣  Bootstrap the cluster if this is the first node.
	if len(peers) > 0 {
		configuration := raft.Configuration{Servers: peers}
		ra.BootstrapCluster(configuration)
	}
	return ra, fsm, nil
}

// ---------- RPC server ----------
func startRPCServer(node *Node, listenAddr string) error {
	rpcServer := rpc.NewServer()
	if err := rpcServer.RegisterName("Node", node); err != nil {
		return err
	}
	l, err := net.Listen("tcp", listenAddr)
	if err != nil {
		return err
	}
	log.Printf("[RPC] listening on %s", listenAddr)
	go func() {
		for {
			conn, err := l.Accept()
			if err != nil {
				log.Printf("[RPC] accept error: %v", err)
				continue
			}
			go rpcServer.ServeConn(conn)
		}
	}()
	return nil
}

// ---------- Main ----------
func main() {
	/*
	   Usage (run three terminals for a 3‑node cluster):
	     go run . -id node1 -bind 127.0.0.1:12001 -rpc 127.0.0.1:13001 -data ./data1 -join ""
	     go run . -id node2 -bind 127.0.0.1:12002 -rpc 127.0.0.1:13002 -data ./data2 -join "node1=127.0.0.1:12001"
	     go run . -id node3 -bind 127.0.0.1:12003 -rpc 127.0.0.1:13003 -data ./data3 -join "node1=127.0.0.1:12001,node2=127.0.0.1:12002"
	*/

	var (
		nodeID    string
		raftAddr  string
		rpcAddr   string
		dataDir   string
		joinStr   string
	)
	// Simple flag parsing – you can replace with spf13/pflag if you like.
	flag.StringVar(&nodeID, "id", "", "unique node ID")
	flag.StringVar(&raftAddr, "bind", "127.0.0.1:12000", "raft bind address")
	flag.StringVar(&rpcAddr, "rpc", "127.0.0.1:13000", "client RPC address")
	flag.StringVar(&dataDir, "data", "./data", "directory for Raft storage")
	flag.StringVar(&joinStr, "join", "", "comma‑separated list of existing nodes (id=addr)")
	flag.Parse()

	if nodeID == "" {
		log.Fatal("node ID must be provided")
	}

	// Parse the join list into a slice of raft.Server structs.
	var peers []raft.Server
	if joinStr != "" {
		for _, part := range strings.Split(joinStr, ",") {
			kv := strings.SplitN(part, "=", 2)
			if len(kv) != 2 {
				log.Fatalf("invalid join entry %q", part)
			}
			peerID := kv[0]
			peerAddr := kv[1]
			peers = append(peers, raft.Server{
				ID:      raft.ServerID(peerID),
				Address: raft.ServerAddress(peerAddr),
			})
		}
	}

	// 1️⃣  Build Raft node
	ra, fsm, err := setupRaft(nodeID, raftAddr, dataDir, peers)
	if err != nil {
		log.Fatalf("failed to start Raft: %v", err)
	}
	node := &Node{Raft: ra, FSM: fsm}

	// 2️⃣  Start RPC server for client traffic
	if err := startRPCServer(node, rpcAddr); err != nil {
		log.Fatalf("failed to start RPC server: %v", err)
	}

	// 3️⃣  If we are joining an existing cluster, ask the leader to add us.
	if len(peers) > 0 {
		// Wait a bit for the leader to be elected.
		time.Sleep(2 * time.Second)
		leaderAddr := ra.Leader()
		if leaderAddr == "" {
			log.Fatalf("no leader yet – cannot join")
		}
		// Use the Raft transport directly to add ourselves.
		future := ra.AddVoter(raft.ServerID(nodeID), raft.ServerAddress(raftAddr), 0, 0)
		if err := future.Error(); err != nil {
			log.Fatalf("failed to add self as voter: %v", err)
		}
		log.Printf("[JOIN] successfully added %s to cluster", nodeID)
	}

	// 4️⃣  Observe leadership changes – useful for debugging / client redirection.
	go func() {
		for {
			select {
			case isLeader := <-ra.LeaderCh():
				if isLeader {
					log.Printf("[RAFT] I (%s) am now the LEADER", nodeID)
				} else {
					log.Printf("[RAFT] I (%s) am a FOLLOWER", nodeID)
				}
			}
		}
	}()

	// Block forever.
	select {}
}
```

