## 8. Simple client demo

Create a file `demo_client.go` (or just use the `client.go` package from above) and run it against the cluster:

```go
package main

import (
	"log"
	"time"
)

func main() {
	// Assume node1 is the initial leader.
	c := NewClient("127.0.0.1:13001")

	// Helper that retries on "not leader" errors.
	put := func(key, value string) {
		for {
			if err := c.Put(key, value); err != nil {
				log.Printf("PUT error: %v – retrying...", err)
				// Extract leader address from error string (very naive parsing)
				if leader := parseLeader(err.Error()); leader != "" {
					c = NewClient(leader) // switch client to the leader
				}
				time.Sleep(200 * time.Millisecond)
				continue
			}
			log.Printf("PUT %s=%s succeeded", key, value)
			return
		}
	}

	get := func(key string) {
		for {
			val, ok, err := c.Get(key)
			if err != nil {
				log.Printf("GET error: %v – retrying...", err)
				if leader := parseLeader(err.Error()); leader != "" {
					c = NewClient(leader)
				}
				time.Sleep(200 * time.Millisecond)
				continue
			}
			if ok {
				log.Printf("GET %s => %s", key, val)
			} else {
				log.Printf("GET %s => <not found>", key)
			}
			return
		}
	}

	put("foo", "bar")
	get("foo")
}

// Very naive leader extraction – production code should use a structured error.
func parseLeader(errMsg string) string {
	// Expected format: "not leader; current leader is 127.0.0.1:12002"
	const prefix = "current leader is "
	idx := strings.Index(errMsg, prefix)
	if idx == -1 {
		return ""
	}
	leaderAddr := errMsg[idx+len(prefix):]
	// Convert Raft address (host:port) to the RPC address (same host, +1000)
	parts := strings.Split(leaderAddr, ":")
	if len(parts) != 2 {
		return ""
	}
	port, _ := strconv.Atoi(parts[1])
	return fmt.Sprintf("%s:%d", parts[0], port+1000) // our RPC ports are +1000
}
```

