## 3. The code (single file: `main.go`)

```go
package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"os"
	"time"

	clientv3 "go.etcd.io/etcd/client/v3"
	"go.etcd.io/etcd/client/v3/concurrency"
)

// ---------------------------------------------------------------------
// Public errors – callers can inspect them with errors.Is()
var (
	ErrLockNotAcquired = errors.New("lock not acquired")
	ErrLeaseLost       = errors.New("lease lost while holding lock")
	ErrKeepAliveFailed = errors.New("keep‑alive failed")
)

// ---------------------------------------------------------------------
// LeaseLock is a thin wrapper around an etcd lease + a key that stores a
// fencing token.  The token is the *revision* of the transaction that
// created the lock, which is guaranteed to be monotonically increasing.
type LeaseLock struct {
	cli          *clientv3.Client
	leaseID      clientv3.LeaseID
	key          string // the lock key (e.g., "/myapp/lock")
	fenceKey     string // where we store the latest token (e.g., "/myapp/fence")
	fencingToken int64  // token that this holder must present
	cancelKA     context.CancelFunc
}

// NewLeaseLock creates a lock object but does NOT acquire it yet.
func NewLeaseLock(cli *clientv3.Client, lockKey, fenceKey string) *LeaseLock {
	return &LeaseLock{
		cli:      cli,
		key:      lockKey,
		fenceKey: fenceKey,
	}
}

// Acquire tries to obtain the lock.  It creates a lease with ttl seconds,
// starts a keep‑alive goroutine, and writes the lock key together with a
// new fencing token (the transaction revision).  If any step fails the
// lease is revoked and the error is returned.
func (l *LeaseLock) Acquire(ctx context.Context, ttl int64) error {
	// 1️⃣  Create a lease.
	leaseResp, err := l.cli.Grant(ctx, ttl)
	if err != nil {
		return fmt.Errorf("grant lease: %w", err)
	}
	l.leaseID = leaseResp.ID

	// 2️⃣  Start keep‑alive in a separate goroutine.
	kaCtx, kaCancel := context.WithCancel(context.Background())
	l.cancelKA = kaCancel
	kaCh, err := l.cli.KeepAlive(kaCtx, l.leaseID)
	if err != nil {
		l.revokeLease()
		return fmt.Errorf("keepalive start: %w", err)
	}
	go l.watchKeepAlive(kaCh)

	// 3️⃣  Try to acquire the lock *and* bump the fencing token atomically.
	// The transaction does:
	//   IF lock key does NOT exist
	//   THEN put lock key = leaseID   AND   put fenceKey = <new token>
	//
	// The token we use is the *revision* of the transaction itself.
	txn := l.cli.Txn(ctx)

	// Condition: lock key must be missing (or expired)
	cmp := clientv3.Compare(clientv3.CreateRevision(l.key), "=", 0)

	// Operations:
	//   - put lock key with lease attached
	//   - put fence key with a dummy value (the real token is txn.Revision)
	putLock := clientv3.OpPut(l.key, fmt.Sprintf("%d", l.leaseID), clientv3.WithLease(l.leaseID))
	putFence := clientv3.OpPut(l.fenceKey, "placeholder") // value will be overwritten by txn header

	txnResp, err := txn.If(cmp).Then(putLock, putFence).Commit()
	if err != nil {
		l.revokeLease()
		return fmt.Errorf("txn commit: %w", err)
	}
	if !txnResp.Succeeded {
		l.revokeLease()
		return ErrLockNotAcquired
	}

	// The transaction succeeded → its header.Revision is a unique, monotonically
	// increasing number.  Use it as the fencing token.
	l.fencingToken = txnResp.Header.Revision
	return nil
}

// watchKeepAlive monitors the keep‑alive channel and cancels the lease if it
// stops receiving heartbeats.
func (l *LeaseLock) watchKeepAlive(ch <-chan *clientv3.LeaseKeepAliveResponse) {
	for resp := range ch {
		if resp == nil {
			// Channel closed → keep‑alive failed.
			l.cancelKA()
			return
		}
		// Normal heartbeat, nothing to do.
	}
	// If we exit the loop because the channel closed, treat it as a failure.
}

// Release revokes the lease (which automatically deletes the lock key) and
// stops the keep‑alive goroutine.
func (l *LeaseLock) Release() error {
	if l.cancelKA != nil {
		l.cancelKA()
	}
	_, err := l.cli.Revoke(context.Background(), l.leaseID)
	if err != nil {
		return fmt.Errorf("revoke lease: %w", err)
	}
	return nil
}

// revokeLease is a tiny helper used when we fail to acquire the lock.
func (l *LeaseLock) revokeLease() {
	if l.cancelKA != nil {
		l.cancelKA()
	}
	_, _ = l.cli.Revoke(context.Background(), l.leaseID)
}

// ---------------------------------------------------------------------
// Simulated protected resource ------------------------------------------------
// In a real system this would be a DB row, a file, etc.  The only thing we
// care about is that writes are accepted **only** if the caller presents
// a fencing token that is greater than the last one we have seen.
type ProtectedResource struct {
	value        string
	lastFence    int64
}

// Write updates the resource only if token > lastFence.
func (r *ProtectedResource) Write(token int64, v string) error {
	if token <= r.lastFence {
		return fmt.Errorf("stale fencing token %d (last=%d)", token, r.lastFence)
	}
	r.value = v
	r.lastFence = token
	return nil
}

// Read returns the current value (no token needed for reads).
func (r *ProtectedResource) Read() string { return r.value }

// ---------------------------------------------------------------------
// Example usage --------------------------------------------------------------

func main() {
	if len(os.Args) != 2 {
		fmt.Printf("usage: %s <instance-id>\n", os.Args[0])
		os.Exit(1)
	}
	id := os.Args[1] // e.g. "A" or "B"

	cli, err := clientv3.New(clientv3.Config{
		Endpoints:   []string{"localhost:2379"},
		DialTimeout: 5 * time.Second,
	})
	if err != nil {
		log.Fatalf("etcd client: %v", err)
	}
	defer cli.Close()

	lock := NewLeaseLock(cli, "/demo/lock", "/demo/fence")
	const ttl = 5 // seconds

	// Try to acquire the lock, retry with back‑off if we lose the race.
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	for {
		err = lock.Acquire(ctx, ttl)
		if err == nil {
			break // success!
		}
		if errors.Is(err, ErrLockNotAcquired) {
			// Someone else holds the lock – wait a bit and retry.
			fmt.Printf("[%s] lock busy, retrying...\n", id)
			time.Sleep(500 * time.Millisecond)
			continue
		}
		// Any other error is fatal for this demo.
		log.Fatalf("[%s] failed to acquire lock: %v", id, err)
	}
	fmt.Printf("[%s] acquired lock, fencing token=%d\n", id, lock.fencingToken)

	// -----------------------------------------------------------------
	// Critical section – write to the protected resource using the token.
	//
	// In a real program the resource would be external (DB, file, etc.).
	// Here we keep it in‑process just to demonstrate the token check.
	//
	// NOTE: The resource must be *shared* between the two processes.
	// For the demo we use a simple in‑memory singleton guarded by a
	// separate etcd key.  In production you would have a DB row with a
	// "fence" column.
	// -----------------------------------------------------------------
	resource := getSharedResource(cli)

	// Simulate some work while holding the lock.
	time.Sleep(2 * time.Second)

	// Write using the fencing token.
	newValue := fmt.Sprintf("written-by-%s-at-%d", id, time.Now().Unix())
	if err := resource.Write(lock.fencingToken, newValue); err != nil {
		// This should never happen if the token is truly monotonic.
		log.Fatalf("[%s] write rejected: %v", id, err)
	}
	fmt.Printf("[%s] wrote value: %q (token=%d)\n", id, newValue, lock.fencingToken)

	// -----------------------------------------------------------------
	// Release the lock (lease revocation automatically deletes the key).
	// -----------------------------------------------------------------
	if err := lock.Release(); err != nil {
		log.Fatalf("[%s] release error: %v", id, err)
	}
	fmt.Printf("[%s] lock released\n", id)

	// Show final value (any instance can read it without a token).
	fmt.Printf("[%s] final resource value: %q\n", id, resource.Read())
}

// ---------------------------------------------------------------------
// Helper that creates a *process‑wide* shared resource backed by etcd.
// This is only for the demo – it stores the value and the last fence token
// in two separate etcd keys so that two separate OS processes can see the
// same data.
//
// In a real system you would replace this with a DB row, a file, etc.
type etcdResource struct {
	cli *clientv3.Client
}

func getSharedResource(cli *clientv3.Client) *ProtectedResource {
	// Load current state from etcd (ignore errors for brevity).
	resp, _ := cli.Get(context.Background(), "/demo/resource/value")
	val := ""
	if len(resp.Kvs) > 0 {
		val = string(resp.Kvs[0].Value)
	}
	resp, _ = cli.Get(context.Background(), "/demo/resource/fence")
	fence := int64(0)
	if len(resp.Kvs) > 0 {
		fmt.Sscanf(string(resp.Kvs[0].Value), "%d", &fence)
	}
	return &ProtectedResource{
		value:     val,
		lastFence: fence,
	}
}

// The Write method of ProtectedResource is already defined above.
// To persist the new state back to etcd we wrap it:
func (r *ProtectedResource) Write(token int64, v string) error {
	if token <= r.lastFence {
		return fmt.Errorf("stale fencing token %d (last=%d)", token, r.lastFence)
	}
	// Persist atomically: both value and fence token must be written together.
	cli, _ := clientv3.New(clientv3.Config{
		Endpoints:   []string{"localhost:2379"},
		DialTimeout: 2 * time.Second,
	})
	defer cli.Close()

	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	defer cancel()

	txn := cli.Txn(ctx)
	putVal := clientv3.OpPut("/demo/resource/value", v)
	putFence := clientv3.OpPut("/demo/resource/fence", fmt.Sprintf("%d", token))
	_, err := txn.Then(putVal, putFence).Commit()
	if err != nil {
		return fmt.Errorf("etcd txn write: %w", err)
	}
	// Update local copy after successful persistence.
	r.value = v
	r.lastFence = token
	return nil
}

// ---------------------------------------------------------------------
```

