## 4. `fsm.go` – the finite‑state machine that receives committed entries

```go
package main

import (
	"bytes"
	"encoding/gob"
	"io"

	"github.com/hashicorp/raft"
)

// MessageFSM is the Raft FSM.  It simply forwards every committed message
// to a channel that the rest of the program reads from.
type MessageFSM struct {
	// Deliver is the channel that receives messages in total order.
	Deliver chan<- string
}

// Apply is called by Raft once a log entry is committed.
func (f *MessageFSM) Apply(log *raft.Log) interface{} {
	// The log entry data is the raw message bytes.
	msg := string(log.Data)
	// Non‑blocking send – if the channel is full we drop the message
	// (in a real system you would block or use a larger buffer).
	select {
	case f.Deliver <- msg:
	default:
	}
	return nil
}

// Snapshot returns a snapshot of the FSM.  For this demo we snapshot only the
// number of messages seen so far (useful to keep the log short).
func (f *MessageFSM) Snapshot() (raft.FSMSnapshot, error) {
	// No state to snapshot, return a no‑op snapshot.
	return &noopSnapshot{}, nil
}

// Restore restores the FSM from a snapshot.  No state to restore.
func (f *MessageFSM) Restore(rc io.ReadCloser) error {
	_ = rc.Close()
	return nil
}

// -------------------------------------------------------------------
// Minimal snapshot implementation – required by the Raft interface.

type noopSnapshot struct{}

func (s *noopSnapshot) Persist(sink raft.SnapshotSink) error {
	// Write an empty gob just to satisfy the contract.
	var buf bytes.Buffer
	enc := gob.NewEncoder(&buf)
	if err := enc.Encode(struct{}{}); err != nil {
		sink.Cancel()
		return err
	}
	if _, err := sink.Write(buf.Bytes()); err != nil {
		sink.Cancel()
		return err
	}
	return sink.Close()
}

func (s *noopSnapshot) Release() {}
```

