// NewTransport creates a Raft TCP transport that listens on the given address.
func NewTransport(bindAddr string) (*raft.NetworkTransport, error) {
	addr, err := net.ResolveTCPAddr("tcp", bindAddr)
	if err != nil {
		return nil, err
	}
	// MaxPool = 5 connections per remote node, timeout = 10s.
	return raft.NewNetworkTransport(addr, 5, 10*time.Second, nil), nil
}
