## 6. `main.go` – wiring everything together

```go
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"time"

	"github.com/gorilla/mux"
	"github.com/hashicorp/raft"
	"github.com/hashicorp/raft-boltdb"
)

// Configurable constants – tweak for your environment.
const (
	raftTimeout   = 10 * time.Second
	snapshotInterval = 30 * time.Second
)

type Server struct {
	Raft      *raft.Raft
	DeliverCh chan string // receives messages in total order
	NodeID    string
	BindAddr  string // host:port for Raft transport
	HTTPAddr  string // host:port for client API
}

// broadcastRequest is the JSON payload accepted from clients.
type broadcastRequest struct {
	Msg string `json:"msg"`
}

// NewServer creates a Raft node (leader or follower) and starts the HTTP API.
func NewServer(nodeID, bindAddr, httpAddr, dataDir string, peers []raft.Server) (*Server, error) {
	// 1️⃣  Create Raft configuration.
	config := raft.DefaultConfig()
	config.LocalID = raft.ServerID(nodeID)
	config.SnapshotInterval = snapshotInterval
	config.SnapshotThreshold = 2 // take a snapshot after 2 logs (tiny for demo)

	// 2️⃣  Set up the Raft log store (BoltDB) and stable store.
	if err := os.MkdirAll(dataDir, 0o755); err != nil {
		return nil, err
	}
	boltDB, err := raftboltdb.NewBoltStore(filepath.Join(dataDir, "raft.db"))
	if err != nil {
		return nil, err
	}
	stableStore := boltDB // Raft uses the same store for both log & stable store.

	// 3️⃣  Set up the snapshot store (in‑memory for demo, can be file‑based).
	snapshots, err := raft.NewFileSnapshotStore(dataDir, 2, os.Stdout)
	if err != nil {
		return nil, err
	}

	// 4️⃣  Set up the transport (TCP).
	transport, err := NewTransport(bindAddr)
	if err != nil {
		return nil, err
	}

	// 5️⃣  Create the FSM that will receive committed messages.
	deliverCh := make(chan string, 1024)
	fsm := &MessageFSM{Deliver: deliverCh}

	// 6️⃣  Build the Raft node.
	ra, err := raft.NewRaft(config, fsm, stableStore, boltDB, snapshots, transport)
	if err != nil {
		return nil, err
	}

	s := &Server{
		Raft:      ra,
		DeliverCh: deliverCh,
		NodeID:    nodeID,
		BindAddr:  bindAddr,
		HTTPAddr:  httpAddr,
	}

	// 7️⃣  Bootstrap the cluster if this is the first node.
	if len(peers) == 0 {
		configuration := raft.Configuration{
			Servers: []raft.Server{
				{
					ID:      config.LocalID,
					Address: transport.LocalAddr(),
				},
			},
		}
		ra.BootstrapCluster(configuration)
	} else {
		// Join an existing cluster – we ask the leader to add us.
		// In a production system you would have a separate “join” RPC.
		// For the demo we just wait for the leader to notice us via Raft’s
		// peer discovery (the transport will connect to the peers we list).
		// The peers slice is used only to open outbound connections.
		for _, p := range peers {
			if p.ID == config.LocalID {
				continue
			}
			// Open a connection so Raft can talk to the peer.
			_, err := transport.Dial(p.Address, raftTimeout)
			if err != nil {
				log.Printf("[WARN] could not connect to peer %s: %v", p.ID, err)
			}
		}
	}

	// 8️⃣  Start the HTTP API.
	go s.serveHTTP()

	// 9️⃣  Start a goroutine that prints delivered messages (demonstrates total order).
	go s.printDelivered()

	return s, nil
}

// serveHTTP creates a tiny HTTP server with a single POST /broadcast endpoint.
func (s *Server) serveHTTP() {
	r := mux.NewRouter()
	r.HandleFunc("/broadcast", s.handleBroadcast).Methods("POST")
	r.HandleFunc("/status", s.handleStatus).Methods("GET")
	srv := &http.Server{
		Addr:    s.HTTPAddr,
		Handler: r,
	}
	log.Printf("[INFO] HTTP API listening on %s", s.HTTPAddr)
	if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
		log.Fatalf("[FATAL] HTTP server error: %v", err)
	}
}

// handleBroadcast receives a client message and forwards it to the Raft leader.
func (s *Server) handleBroadcast(w http.ResponseWriter, r *http.Request) {
	// Decode JSON payload.
	var req broadcastRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid json", http.StatusBadRequest)
		return
	}
	if req.Msg == "" {
		http.Error(w, "msg field required", http.StatusBadRequest)
		return
	}

	// 1️⃣  If we are not the leader, redirect the client.
	if s.Raft.State() != raft.Leader {
		leaderAddr := s.Raft.Leader()
		if leaderAddr == "" {
			// No leader known yet (cluster bootstrapping).
			http.Error(w, "no leader elected yet", http.StatusServiceUnavailable)
			return
		}
		// Build a URL that points to the same path on the leader's HTTP server.
		// We assume the HTTP port is the same as the Raft port + 1000 (convention).
		leaderHTTP := leaderAddr.String()
		host, _, _ := net.SplitHostPort(leaderHTTP)
		leaderHTTP = fmt.Sprintf("%s:%s", host, s.HTTPPortFromRaftPort(leaderHTTP))
		redirectURL := fmt.Sprintf("http://%s/broadcast", leaderHTTP)
		http.Redirect(w, r, redirectURL, http.StatusTemporaryRedirect)
		return
	}

	// 2️⃣  We are the leader – propose the command to Raft.
	// The command is just the raw message bytes.
	future := s.Raft.Apply([]byte(req.Msg), raftTimeout)
	if err := future.Error(); err != nil {
		http.Error(w, fmt.Sprintf("raft apply failed: %v", err), http.StatusInternalServerError)
		return
	}
	// Success – return 202 Accepted (the message will be delivered shortly).
	w.WriteHeader(http.StatusAccepted)
}

// handleStatus is a tiny health‑check endpoint.
func (s *Server) handleStatus(w http.ResponseWriter, r *http.Request) {
	type status struct {
		NodeID   string `json:"node_id"`
		Leader   string `json:"leader"`
		State    string `json:"state"`
		CommitIdx uint64 `json:"commit_index"`
	}
	resp := status{
		NodeID:   s.NodeID,
		Leader:   string(s.Raft.Leader()),
		State:    s.Raft.State().String(),
		CommitIdx: s.Raft.CommitIndex(),
	}
	_ = json.NewEncoder(w).Encode(resp)
}

// HTTPPortFromRaftPort is a tiny helper that assumes the HTTP port is the Raft
// port + 1000 (e.g. Raft 12000 → HTTP 13000).  Adjust as you like.
func (s *Server) HTTPPortFromRaftPort(raftAddr string) string {
	_, portStr, _ := net.SplitHostPort(raftAddr)
	port, _ := net.LookupPort("tcp", portStr)
	return fmt.Sprintf("%d", port+1000)
}

// printDelivered simply logs every message that the FSM delivers.
func (s *Server) printDelivered() {
	for msg := range s.DeliverCh {
		log.Printf("[DELIVERED][%s] %s", s.NodeID, msg)
	}
}

// -------------------------------------------------------------------
// main – start a cluster of 3 nodes on the same machine for demo purposes.
// In production you would run each node on its own host.

func main() {
	if len(os.Args) < 2 {
		fmt.Println("Usage: totalorder <node-id>")
		os.Exit(1)
	}
	nodeID := os.Args[1]

	// Simple static mapping: nodeID → ports.
	// Raft port = 12000 + id, HTTP port = Raft port + 1000.
	raftPort := 12000 + atoi(nodeID)
	raftAddr := fmt.Sprintf("127.0.0.1:%d", raftPort)
	httpAddr := fmt.Sprintf("127.0.0.1:%d", raftPort+1000)

	// Data directory per node.
	dataDir := fmt.Sprintf("./data/node%s", nodeID)

	// List of all peers (used only for outbound connections).
	var peers []raft.Server
	for i := 1; i <= 3; i++ {
		id := fmt.Sprintf("%d", i)
		if id == nodeID {
			continue
		}
		peerRaftPort := 12000 + i
		peerAddr := fmt.Sprintf("127.0.0.1:%d", peerRaftPort)
		peers = append(peers, raft.Server{
			ID:      raft.ServerID(id),
			Address: raft.ServerAddress(peerAddr),
		})
	}

	srv, err := NewServer(nodeID, raftAddr, httpAddr, dataDir, peers)
	if err != nil {
		log.Fatalf("[FATAL] failed to start server: %v", err)
	}

	// Block forever – the server runs in background goroutines.
	select {}
}

// atoi is a tiny wrapper that never panics (inputs are controlled).
func atoi(s string) int {
	n, _ := fmt.Sscanf(s, "%d", new(int))
	if n == 0 {
		return 0
	}
	var v int
	fmt.Sscanf(s, "%d", &v)
	return v
}
```

