### 2.2 `counter.go`

```go
// pncounter/counter.go
package pncounter

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"sync"
	"time"
)

// NodeID must be globally unique (e.g. UUID, hostname+pid)
type NodeID string

// PNState is the serialisable representation of a PN‑Counter.
// It is safe to send over the wire because it contains only primitive types.
type PNState struct {
	P map[NodeID]uint64 `json:"p"` // increments per replica
	N map[NodeID]uint64 `json:"n"` // decrements per replica
}

// Counter implements an eventually‑consistent PN‑Counter.
type Counter struct {
	mu      sync.RWMutex // protects p, n
	nodeID  NodeID
	p, n    map[NodeID]uint64
	// optional persistence hook (e.g. write‑ahead log, RocksDB)
	persist func(state PNState) error
}

// New creates a fresh counter for this replica.
func New(nodeID NodeID, persistFn func(state PNState) error) *Counter {
	if nodeID == "" {
		panic("nodeID cannot be empty")
	}
	return &Counter{
		nodeID:  nodeID,
		p:       make(map[NodeID]uint64),
		n:       make(map[NodeID]uint64),
		persist: persistFn,
	}
}

// Increment adds delta (must be >0) to the local replica.
func (c *Counter) Increment(delta uint64) error {
	if delta == 0 {
		return errors.New("delta must be > 0")
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	c.p[c.nodeID] += delta
	return c.save()
}

// Decrement adds delta (must be >0) to the local replica's *negative* part.
func (c *Counter) Decrement(delta uint64) error {
	if delta == 0 {
		return errors.New("delta must be > 0")
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	c.n[c.nodeID] += delta
	return c.save()
}

// Value returns the current logical value of the counter.
func (c *Counter) Value() int64 {
	c.mu.RLock()
	defer c.mu.RUnlock()
	var inc, dec uint64
	for _, v := range c.p {
		inc += v
	}
	for _, v := range c.n {
		dec += v
	}
	// int64 is safe because the difference of two uint64s fits in int64
	return int64(inc) - int64(dec)
}

// State returns a deep‑copy of the internal state for replication.
func (c *Counter) State() PNState {
	c.mu.RLock()
	defer c.mu.RUnlock()
	// shallow copy of maps is enough because values are primitives
	pCopy := make(map[NodeID]uint64, len(c.p))
	nCopy := make(map[NodeID]uint64, len(c.n))
	for k, v := range c.p {
		pCopy[k] = v
	}
	for k, v := range c.n {
		nCopy[k] = v
	}
	return PNState{P: pCopy, N: nCopy}
}

// Merge integrates a remote state into the local counter.
// It follows the CRDT merge rule: element‑wise max.
func (c *Counter) Merge(remote PNState) error {
	c.mu.Lock()
	defer c.mu.Unlock()
	changed := false

	for id, val := range remote.P {
		if cur, ok := c.p[id]; !ok || val > cur {
			c.p[id] = val
			changed = true
		}
	}
	for id, val := range remote.N {
		if cur, ok := c.n[id]; !ok || val > cur {
			c.n[id] = val
			changed = true
		}
	}
	if changed && c.persist != nil {
		return c.persist(c.State())
	}
	return nil
}

// save persists the current state if a persistence hook was supplied.
func (c *Counter) save() error {
	if c.persist == nil {
		return nil
	}
	return c.persist(c.State())
}

// MarshalJSON implements json.Marshaler for easy debugging / logging.
func (c *Counter) MarshalJSON() ([]byte, error) {
	return json.Marshal(c.State())
}

// UnmarshalJSON restores a Counter from a JSON blob.
// It does NOT set the persistence hook – callers must do that manually.
func (c *Counter) UnmarshalJSON(data []byte) error {
	var s PNState
	if err := json.Unmarshal(data, &s); err != nil {
		return err
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	c.p = s.P
	c.n = s.N
	return nil
}
```

### 2.3 Persistence (optional)

You can plug any durable store (file, BadgerDB, etc.) by passing a `func(PNState) error` to `New`.  
