## 3. Replication layer (gRPC)

The CRDT itself is **transport‑agnostic**. Below is a tiny gRPC service that:

* Exposes a `Merge(PNState)` RPC.  
* Retries on transient failures with exponential back‑off (max 5 attempts).  
* Guarantees **at‑most‑once** delivery because the server merges idempotently.

### 3.1 Protobuf definition (`proto/pncounter.proto`)

```proto
syntax = "proto3";

package pncounter;

option go_package = "github.com/yourorg/pncounter/replication/proto;proto";

message PNState {
  map<string, uint64> p = 1;
  map<string, uint64> n = 2;
}

service PNReplica {
  // Push a remote state to this replica.
  rpc Merge (PNState) returns (MergeResponse);
}

message MergeResponse {
  bool ok = 1;
}
```

Generate Go code:

```bash
protoc --go_out=. --go-grpc_out=. proto/pncounter.proto
```

### 3.2 Server (`replication/server.go`)

```go
// pncounter/replication/server.go
package replication

import (
	"context"
	"log"
	"net"

	pb "github.com/yourorg/pncounter/replication/proto"
	"github.com/yourorg/pncounter"
	"google.golang.org/grpc"
)

type server struct {
	pb.UnimplementedPNReplicaServer
	counter *pncounter.Counter
}

// Merge implements the gRPC endpoint.
func (s *server) Merge(ctx context.Context, req *pb.PNState) (*pb.MergeResponse, error) {
	remote := pncounter.PNState{
		P: make(map[pncounter.NodeID]uint64, len(req.P)),
		N: make(map[pncounter.NodeID]uint64, len(req.N)),
	}
	for k, v := range req.P {
		remote.P[pncounter.NodeID(k)] = v
	}
	for k, v := range req.N {
		remote.N[pncounter.NodeID(k)] = v
	}
	if err := s.counter.Merge(remote); err != nil {
		return nil, err
	}
	return &pb.MergeResponse{Ok: true}, nil
}

// Start launches the gRPC server on the supplied address.
func Start(addr string, ctr *pncounter.Counter) error {
	lis, err := net.Listen("tcp", addr)
	if err != nil {
		return err
	}
	s := grpc.NewServer()
	pb.RegisterPNReplicaServer(s, &server{counter: ctr})
	log.Printf("PN‑Replica listening on %s", addr)
	return s.Serve(lis)
}
```

### 3.3 Client with retry (`replication/client.go`)

```go
// pncounter/replication/client.go
package replication

import (
	"context"
	"time"

	pb "github.com/yourorg/pncounter/replication/proto"
	"github.com/yourorg/pncounter"
	"google.golang.org/grpc"
	"google.golang.org/grpc/status"
)

// Client wraps a gRPC connection and implements retry logic.
type Client struct {
	conn   *grpc.ClientConn
	client pb.PNReplicaClient
}

// NewClient creates a client to the remote replica at addr (e.g. "host:50051").
func NewClient(addr string) (*Client, error) {
	conn, err := grpc.Dial(addr,
		grpc.WithInsecure(), // replace with TLS in prod
		grpc.WithBlock(),
		grpc.WithTimeout(5*time.Second),
	)
	if err != nil {
		return nil, err
	}
	return &Client{
		conn:   conn,
		client: pb.NewPNReplicaClient(conn),
	}, nil
}

// Close shuts down the underlying connection.
func (c *Client) Close() error {
	return c.conn.Close()
}

// PushState sends the local state to the remote replica.
// It retries on transient errors (deadline exceeded, unavailable, etc.).
func (c *Client) PushState(ctx context.Context, state pncounter.PNState) error {
	// Convert to protobuf
	req := &pb.PNState{
		P: make(map[string]uint64, len(state.P)),
		N: make(map[string]uint64, len(state.N)),
	}
	for k, v := range state.P {
		req.P[string(k)] = v
	}
	for k, v := range state.N {
		req.N[string(k)] = v
	}

	var backoff = 100 * time.Millisecond
	const maxAttempts = 5

	for attempt := 1; attempt <= maxAttempts; attempt++ {
		_, err := c.client.Merge(ctx, req)
		if err == nil {
			return nil // success
		}
		// Check if error is retryable
		st, _ := status.FromError(err)
		if st.Code() == grpcCodes.Unavailable || st.Code() == grpcCodes.DeadlineExceeded {
			// transient – back‑off and retry
			time.Sleep(backoff)
			backoff *= 2
			continue
		}
		// non‑retryable → give up
		return err
	}
	return fmt.Errorf("exhausted retries pushing state to %s", c.conn.Target())
}
```

> **Note** – In production you should replace `grpc.WithInsecure()` with TLS credentials and use a connection pool if you have many peers.

### 3.4 Periodic anti‑entropy goroutine

```go
// pncounter/replication/antientropy.go
package replication

import (
	"context"
	"log"
	"time"

	"github.com/yourorg/pncounter"
)

// AntiEntropy periodically pushes the local state to all known peers.
func AntiEntropy(ctx context.Context, ctr *pncounter.Counter, peers []string, interval time.Duration) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			state := ctr.State()
			for _, addr := range peers {
				go func(addr string) {
					client, err := NewClient(addr)
					if err != nil {
						log.Printf("[AE] cannot connect to %s: %v", addr, err)
						return
					}
					defer client.Close()
					if err := client.PushState(context.Background(), state); err != nil {
						log.Printf("[AE] push to %s failed: %v", addr, err)
					}
				}(addr)
			}
		}
	}
}
```

The anti‑entropy loop guarantees **eventual convergence** even when messages are lost or nodes are temporarily partitioned.

