## 4. Full example (main program)

```go
// cmd/node/main.go
package main

import (
	"context"
	"flag"
	"log"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/google/uuid"
	"github.com/yourorg/pncounter"
	"github.com/yourorg/pncounter/replication"
)

func main() {
	var (
		addr   = flag.String("listen", ":50051", "local gRPC listen address")
		peers  = flag.String("peers", "", "comma‑separated list of remote replica addresses")
	)
	flag.Parse()

	nodeID := NodeID(uuid.NewString())
	log.Printf("Starting PN‑Counter replica %s", nodeID)

	// Simple file‑based persistence (optional)
	persistFn := func(state pncounter.PNState) error {
		b, _ := json.Marshal(state)
		return os.WriteFile("state.json", b, 0o600)
	}
	counter := pncounter.New(nodeID, persistFn)

	// Load persisted state if present
	if data, err := os.ReadFile("state.json"); err == nil {
		_ = json.Unmarshal(data, counter) // ignore error – best‑effort
	}

	// Start gRPC server
	go func() {
		if err := replication.Start(*addr, counter); err != nil {
			log.Fatalf("gRPC server failed: %v", err)
		}
	}()

	// Parse peers
	var peerList []string
	if *peers != "" {
		peerList = strings.Split(*peers, ",")
	}

	// Launch anti‑entropy background task
	ctx, cancel := context.WithCancel(context.Background())
	go replication.AntiEntropy(ctx, counter, peerList, 2*time.Second)

	// Demo: simple CLI that reads commands from stdin
	go func() {
		scanner := bufio.NewScanner(os.Stdin)
		fmt.Println("Enter +N to inc, -N to dec, q to quit")
		for scanner.Scan() {
			line := strings.TrimSpace(scanner.Text())
			switch {
			case line == "q":
				cancel()
				return
			case strings.HasPrefix(line, "+"):
				val, _ := strconv.ParseUint(line[1:], 10, 64)
				_ = counter.Increment(val)
			case strings.HasPrefix(line, "-"):
				val, _ := strconv.ParseUint(line[1:], 10, 64)
				_ = counter.Decrement(val)
			case line == "v":
				fmt.Printf("Current value: %d\n", counter.Value())
			default:
				fmt.Println("unknown command")
			}
		}
	}()

	// Graceful shutdown on SIGINT/SIGTERM
	sigc := make(chan os.Signal, 1)
	signal.Notify(sigc, syscall.SIGINT, syscall.SIGTERM)
	<-sigc
	cancel()
	log.Println("Shutting down...")
	time.Sleep(1 * time.Second) // give anti‑entropy a chance to finish
}
```

