## 6. Testing eventual convergence (integration test)

```go
// integration_test.go
package integration

import (
	"context"
	"testing"
	"time"

	"github.com/google/uuid"
	"github.com/yourorg/pncounter"
	"github.com/yourorg/pncounter/replication"
)

func TestConvergenceWithPartition(t *testing.T) {
	// three in‑process replicas
	ids := []pncounter.NodeID{pncounter.NodeID(uuid.NewString()), pncounter.NodeID(uuid.NewString()), pncounter.NodeID(uuid.NewString())}
	counters := make([]*pncounter.Counter, 3)
	servers := make([]*replication.Server, 3) // wrapper we will create below

	for i := 0; i < 3; i++ {
		counters[i] = pncounter.New(ids[i], nil)
	}
	// start gRPC servers on random ports
	addrs := []string{}
	for i := 0; i < 3; i++ {
		addr := fmt.Sprintf("127.0.0.1:%d", 60000+i)
		addrs = append(addrs, addr)
		go replication.Start(addr, counters[i])
	}
	// give them a moment to listen
	time.Sleep(200 * time.Millisecond)

	// anti‑entropy with full mesh
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go replication.AntiEntropy(ctx, counters[0], []string{addrs[1], addrs[2]}, 500*time.Millisecond)
	go replication.AntiEntropy(ctx, counters[1], []string{addrs[0], addrs[2]}, 500*time.Millisecond)
	go replication.AntiEntropy(ctx, counters[2], []string{addrs[0], addrs[1]}, 500*time.Millisecond)

	// Simulate a partition: stop anti‑entropy for node 2 for 2 seconds
	time.Sleep(500 * time.Millisecond)
	cancel() // stop all anti‑entropy
	// node 0 and 1 keep talking
	ctxA, cancelA := context.WithCancel(context.Background())
	defer cancelA()
	go replication.AntiEntropy(ctxA, counters[0], []string{addrs[1]}, 300*time.Millisecond)
	go replication.AntiEntropy(ctxA, counters[1], []string{addrs[0]}, 300*time.Millisecond)

	// Perform ops while node 2 is isolated
	_ = counters[0].Increment(7) // +7 on node0
	_ = counters[1].Decrement(2) // -2 on node1

	// Wait for convergence between 0 and 1
	time.Sleep(2 * time.Second)

	// Re‑enable node2 anti‑entropy
	ctxB, cancelB := context.WithCancel(context.Background())
	defer cancelB()
	go replication.AntiEntropy(ctxB, counters[2], []string{addrs[0], addrs[1]}, 300*time.Millisecond)

	// Wait for full mesh to converge
	time.Sleep(3 * time.Second)

	// All three should see the same value: 7‑2 = 5
	for i, ctr := range counters {
		if v := ctr.Value(); v != 5 {
			t.Fatalf("replica %d value = %d, want 5", i, v)
		}
	}
}
```

The test demonstrates:

* **Partition** (node 2 isolated).  
* **Concurrent updates** on the other two nodes.  
* **Healing** and eventual convergence to the correct value.

