## 8. Quick copy‑paste starter (single file)

If you need a **single‑file** version for a hackathon, copy the following into `pncounter.go`. It contains the core Counter, a tiny HTTP replication endpoint (no gRPC), and a `main` that runs three processes locally.

```go
// pncounter.go
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"strconv"
	"sync"
	"time"

	"github.com/google/uuid"
)

type NodeID string

type PNState struct {
	P map[NodeID]uint64 `json:"p"`
	N map[NodeID]uint64 `json:"n"`
}

type Counter struct {
	mu     sync.RWMutex
	id     NodeID
	p, n   map[NodeID]uint64
}

func New(id NodeID) *Counter {
	return &Counter{
		id: id,
		p:  make(map[NodeID]uint64),
		n:  make(map[NodeID]uint64),
	}
}
func (c *Counter) Increment(d uint64) {
	c.mu.Lock()
	c.p[c.id] += d
	c.mu.Unlock()
}
func (c *Counter) Decrement(d uint64) {
	c.mu.Lock()
	c.n[c.id] += d
	c.mu.Unlock()
}
func (c *Counter) Value() int64 {
	c.mu.RLock()
	defer c.mu.RUnlock()
	var inc, dec uint64
	for _, v := range c.p { inc += v }
	for _, v := range c.n { dec += v }
	return int64(inc) - int64(dec)
}
func (c *Counter) State() PNState {
	c.mu.RLock()
	defer c.mu.RUnlock()
	pCopy := make(map[NodeID]uint64, len(c.p))
	nCopy := make(map[NodeID]uint64, len(c.n))
	for k, v := range c.p { pCopy[k] = v }
	for k, v := range c.n { nCopy[k] = v }
	return PNState{P: pCopy, N: nCopy}
}
func (c *Counter) Merge(s PNState) {
	c.mu.Lock()
	defer c.mu.Unlock()
	for id, v := range s.P {
		if cur, ok := c.p[id]; !ok || v > cur {
			c.p[id] = v
		}
	}
	for id, v := range s.N {
		if cur, ok := c.n[id]; !ok || v > cur {
			c.n[id] = v
		}
	}
}

// ---------- HTTP replication ----------
func serve(c *Counter, port int, peers []string) {
	mux := http.NewServeMux()
	mux.HandleFunc("/state", func(w http.ResponseWriter, r *http.Request) {
		if r.Method == http.MethodGet {
			json.NewEncoder(w).Encode(c.State())
			return
		}
		if r.Method == http.MethodPost {
			var s PNState
			if err := json.NewDecoder(r.Body).Decode(&s); err != nil {
				http.Error(w, err.Error(), http.StatusBadRequest)
				return
			}
			c.Merge(s)
			w.WriteHeader(http.StatusNoContent)
			return
		}
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
	})
	srv := &http.Server{Addr: fmt.Sprintf(":%d", port), Handler: mux}
	go srv.ListenAndServe()
	// anti‑entropy
	go func() {
		tick := time.NewTicker(2 * time.Second)
		for range tick.C {
			state := c.State()
			b, _ := json.Marshal(state)
			for _, p := range peers {
				url := fmt.Sprintf("http://%s/state", p)
				req, _ := http.NewRequest(http.MethodPost, url, bytes.NewReader(b))
				req.Header.Set("Content-Type", "application/json")
				// simple retry
				for i := 0; i < 3; i++ {
					resp, err := http.DefaultClient.Do(req)
					if err == nil && resp.StatusCode == http.StatusNoContent {
						break
					}
					time.Sleep(time.Duration(i+1) * 200 * time.Millisecond)
				}
			}
		}
	}()
}

// ---------- demo ----------
func main() {
	if len(os.Args) < 3 {
		fmt.Println("usage: go run pncounter.go <port> <peer1,peer2,...>")
		return
	}
	port, _ := strconv.Atoi(os.Args[1])
	peerList := strings.Split(os.Args[2], ",")
	id := NodeID(uuid.NewString())
	c := New(id)

	serve(c, port, peerList)

	// simple CLI
	scanner := bufio.NewScanner(os.Stdin)
	fmt.Println("type +N / -N / v / q")
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		switch {
		case line == "q":
			return
		case line == "v":
			fmt.Println("value =", c.Value())
		case strings.HasPrefix(line, "+"):
			if d, _ := strconv.ParseUint(line[1:], 10, 64); d > 0 {
				c.Increment(d)
			}
		case strings.HasPrefix(line, "-"):
			if d, _ := strconv.ParseUint(line[1:], 10, 64); d > 0 {
				c.Decrement(d)
			}
		}
	}
}
```

