## 3. The code (single file for clarity)

```go
// kvnode/main.go
package main

import (
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"log"
	"net"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"
)

/* ---------- Types used by the consensus module ---------- */

type NodeID string

type LogEntry struct {
	Term  int
	Key   string
	Value string
}

type AppendEntryReq struct {
	Term    int
	Leader  NodeID
	PrevIdx int
	PrevTerm int
	Entries []LogEntry
	LeaderCommit int
}

type AppendEntryResp struct {
	Term    int
	Success bool
}

/* ---------- Server state ---------- */

type Server struct {
	mu          sync.Mutex
	id          NodeID
	peers       map[NodeID]string // id → address (host:port)
	term        int
	votedFor    *NodeID
	log         []LogEntry
	commitIdx   int
	lastApplied int

	// volatile state for leader
	nextIndex  map[NodeID]int
	matchIndex map[NodeID]int

	// state machine (the KV map)
	store map[string]string

	// leader tracking
	leader *NodeID

	// HTTP server
	httpSrv *http.Server

	// timers
	electionTimeout time.Duration
	heartbeatInterval time.Duration
	rpcTimeout time.Duration
}

// ---------- Helper ----------

func (s *Server) logf(format string, a ...any) {
	log.Printf("[node %s] %s", s.id, fmt.Sprintf(format, a...))
}

/* ---------- RPC client ---------- */

func (s *Server) sendAppendEntries(ctx context.Context, target NodeID, req AppendEntryReq) (AppendEntryResp, error) {
	addr := s.peers[target]
	url := fmt.Sprintf("http://%s/_raft/append", addr)

	body, _ := json.Marshal(req)
	httpReq, err := http.NewRequestWithContext(ctx, "POST", url, strings.NewReader(string(body)))
	if err != nil {
		return AppendEntryResp{}, err
	}
	httpReq.Header.Set("Content-Type", "application/json")
	resp, err := http.DefaultClient.Do(httpReq)
	if err != nil {
		return AppendEntryResp{}, err
	}
	defer resp.Body.Close()
	var r AppendEntryResp
	if err := json.NewDecoder(resp.Body).Decode(&r); err != nil {
		return AppendEntryResp{}, err
	}
	return r, nil
}

/* ---------- Raft core ---------- */

func (s *Server) becomeFollower(term int, leader *NodeID) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if term > s.term {
		s.term = term
		s.votedFor = nil
	}
	s.leader = leader
	s.logf("become follower (term=%d, leader=%v)", s.term, s.leader)
}

func (s *Server) becomeCandidate() {
	s.mu.Lock()
	s.term++
	s.votedFor = &s.id
	term := s.term
	s.mu.Unlock()

	s.logf("starting election (term=%d)", term)

	votes := 1 // vote for self
	var mu sync.Mutex
	var wg sync.WaitGroup
	for pid := range s.peers {
		wg.Add(1)
		go func(pid NodeID) {
			defer wg.Done()
			// In this tiny implementation we just ask the peer for its term.
			// If its term <= our term we count the vote.
			ctx, cancel := context.WithTimeout(context.Background(), s.rpcTimeout)
			defer cancel()
			// a tiny “requestVote” RPC – we reuse AppendEntry with empty entries
			req := AppendEntryReq{
				Term: term,
				Leader: s.id,
				PrevIdx: -1,
				PrevTerm: -1,
				Entries: nil,
				LeaderCommit: s.commitIdx,
			}
			resp, err := s.sendAppendEntries(ctx, pid, req)
			if err != nil {
				return
			}
			if resp.Term > term {
				// discovered higher term → step down
				s.becomeFollower(resp.Term, nil)
				return
			}
			if resp.Success {
				mu.Lock()
				votes++
				mu.Unlock()
			}
		}(pid)
	}
	wg.Wait()

	majority := len(s.peers)/2 + 1
	if votes >= majority {
		s.becomeLeader()
	} else {
		s.logf("election lost (got %d votes, need %d)", votes, majority)
	}
}

func (s *Server) becomeLeader() {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.leader = &s.id
	s.logf("elected leader (term=%d)", s.term)

	// initialise leader volatile state
	s.nextIndex = make(map[NodeID]int)
	s.matchIndex = make(map[NodeID]int)
	next := len(s.log) // first index to send to a follower
	for pid := range s.peers {
		s.nextIndex[pid] = next
		s.matchIndex[pid] = 0
	}
	// start heartbeats
	go s.heartbeatLoop()
}

/* ---------- Heartbeat & replication ---------- */

func (s *Server) heartbeatLoop() {
	ticker := time.NewTicker(s.heartbeatInterval)
	defer ticker.Stop()
	for {
		s.mu.Lock()
		if s.leader == nil || *s.leader != s.id {
			s.mu.Unlock()
			return // no longer leader
		}
		s.mu.Unlock()

		<-ticker.C
		s.replicate(nil) // empty AppendEntry = heartbeat
	}
}

// replicate sends the given entries (or just a heartbeat) to all followers.
func (s *Server) replicate(entries []LogEntry) {
	s.mu.Lock()
	term := s.term
	leaderCommit := s.commitIdx
	s.mu.Unlock()

	var wg sync.WaitGroup
	for pid := range s.peers {
		wg.Add(1)
		go func(pid NodeID) {
			defer wg.Done()
			s.mu.Lock()
			prevIdx := s.nextIndex[pid] - 1
			prevTerm := 0
			if prevIdx >= 0 && prevIdx < len(s.log) {
				prevTerm = s.log[prevIdx].Term
			}
			req := AppendEntryReq{
				Term: term,
				Leader: s.id,
				PrevIdx: prevIdx,
				PrevTerm: prevTerm,
				Entries: entries,
				LeaderCommit: leaderCommit,
			}
			s.mu.Unlock()

			ctx, cancel := context.WithTimeout(context.Background(), s.rpcTimeout)
			defer cancel()
			resp, err := s.sendAppendEntries(ctx, pid, req)
			if err != nil {
				s.logf("append to %s failed: %v", pid, err)
				return
			}
			s.mu.Lock()
			defer s.mu.Unlock()
			if resp.Term > s.term {
				s.becomeFollower(resp.Term, nil)
				return
			}
			if resp.Success {
				if len(entries) > 0 {
					s.nextIndex[pid] = s.nextIndex[pid] + len(entries)
					s.matchIndex[pid] = s.nextIndex[pid] - 1
				}
			} else {
				// decrement nextIndex and retry later
				if s.nextIndex[pid] > 0 {
					s.nextIndex[pid]--
				}
			}
		}(pid)
	}
	wg.Wait()

	// If we just replicated a real entry, try to advance commitIdx
	if len(entries) > 0 {
		s.advanceCommit()
	}
}

// advanceCommit checks if a log entry is replicated on a majority and, if so,
// marks it committed and applies it to the state machine.
func (s *Server) advanceCommit() {
	s.mu.Lock()
	defer s.mu.Unlock()
	N := len(s.log) - 1 // index of the newly appended entry
	majority := len(s.peers)/2 + 1
	for i := s.commitIdx + 1; i <= N; i++ {
		matchCount := 1 // leader itself
		for _, idx := range s.matchIndex {
			if idx >= i {
				matchCount++
			}
		}
		if matchCount >= majority && s.log[i].Term == s.term {
			s.commitIdx = i
			// apply to state machine
			ent := s.log[i]
			s.store[ent.Key] = ent.Value
			s.logf("committed %s=%s (idx=%d)", ent.Key, ent.Value, i)
		}
	}
}

/* ---------- RPC handler (AppendEntry) ---------- */

func (s *Server) handleAppendEntry(w http.ResponseWriter, r *http.Request) {
	var req AppendEntryReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()

	// 1. Reply false if term is stale
	if req.Term < s.term {
		json.NewEncoder(w).Encode(AppendEntryResp{Term: s.term, Success: false})
		return
	}
	// 2. If term is newer, become follower
	if req.Term > s.term {
		s.term = req.Term
		s.votedFor = nil
		s.leader = &req.Leader
	}
	// 3. Reset leader info (heartbeat)
	s.leader = &req.Leader

	// 4. Log consistency check
	if req.PrevIdx >= 0 {
		if req.PrevIdx >= len(s.log) || s.log[req.PrevIdx].Term != req.PrevTerm {
			json.NewEncoder(w).Encode(AppendEntryResp{Term: s.term, Success: false})
			return
		}
	}
	// 5. Append any new entries
	if len(req.Entries) > 0 {
		// truncate conflicting entries
		newIdx := req.PrevIdx + 1
		if newIdx < len(s.log) {
			s.log = s.log[:newIdx]
		}
		s.log = append(s.log, req.Entries...)
	}
	// 6. Update commit index
	if req.LeaderCommit > s.commitIdx {
		lastIdx := len(s.log) - 1
		if req.LeaderCommit < lastIdx {
			s.commitIdx = req.LeaderCommit
		} else {
			s.commitIdx = lastIdx
		}
		// apply all newly committed entries
		for i := s.lastApplied + 1; i <= s.commitIdx; i++ {
			ent := s.log[i]
			s.store[ent.Key] = ent.Value
			s.lastApplied = i
		}
	}
	json.NewEncoder(w).Encode(AppendEntryResp{Term: s.term, Success: true})
}

/* ---------- Client API (GET/PUT) ---------- */

func (s *Server) handlePut(w http.ResponseWriter, r *http.Request) {
	// key is the last element of the path: /kv/:key
	parts := strings.Split(r.URL.Path, "/")
	if len(parts) < 3 {
		http.Error(w, "missing key", http.StatusBadRequest)
		return
	}
	key := parts[2]
	valBytes, err := io.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "cannot read body", http.StatusBadRequest)
		return
	}
	value := string(valBytes)

	s.mu.Lock()
	leader := s.leader
	s.mu.Unlock()

	// 1️⃣ If we are not the leader, redirect the client
	if leader == nil || *leader != s.id {
		if leader != nil {
			leaderAddr := s.peers[*leader]
			redirect := fmt.Sprintf("http://%s%s", leaderAddr, r.URL.Path)
			http.Redirect(w, r, redirect, http.StatusTemporaryRedirect)
			return
		}
		// no known leader → unavailable
		s.unavailable(w, "no leader known")
		return
	}

	// 2️⃣ Append entry to our own log
	s.mu.Lock()
	entry := LogEntry{Term: s.term, Key: key, Value: value}
	s.log = append(s.log, entry)
	idx := len(s.log) - 1
	s.mu.Unlock()

	// 3️⃣ Replicate to followers and wait for majority
	ackCh := make(chan bool, len(s.peers))
	ctx, cancel := context.WithTimeout(context.Background(), s.rpcTimeout)
	defer cancel()

	// send to each follower
	for pid := range s.peers {
		go func(pid NodeID) {
			s.mu.Lock()
			prevIdx := idx - 1
			prevTerm := 0
			if prevIdx >= 0 && prevIdx < len(s.log) {
				prevTerm = s.log[prevIdx].Term
			}
			s.mu.Unlock()
			req := AppendEntryReq{
				Term: s.term,
				Leader: s.id,
				PrevIdx: prevIdx,
				PrevTerm: prevTerm,
				Entries: []LogEntry{entry},
				LeaderCommit: s.commitIdx,
			}
			resp, err := s.sendAppendEntries(ctx, pid, req)
			if err != nil {
				ackCh <- false
				return
			}
			ackCh <- resp.Success && resp.Term == s.term
		}(pid)
	}

	// count acks (leader counts as one)
	majority := len(s.peers)/2 + 1
	acks := 1
	timeout := false
	for i := 0; i < len(s.peers); i++ {
		select {
		case ok := <-ackCh:
			if ok {
				acks++
			}
		case <-ctx.Done():
			timeout = true
			break
		}
	}
	if timeout || acks < majority {
		s.unavailable(w, "no quorum – write rejected")
		// rollback the uncommitted entry (optional)
		s.mu.Lock()
		if len(s.log)-1 == idx {
			s.log = s.log[:idx] // drop the entry
		}
		s.mu.Unlock()
		return
	}

	// 4️⃣ Commit locally (majority already knows)
	s.mu.Lock()
	s.commitIdx = idx
	s.store[key] = value
	s.mu.Unlock()

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "OK")
}

func (s *Server) handleGet(w http.ResponseWriter, r *http.Request) {
	parts := strings.Split(r.URL.Path, "/")
	if len(parts) < 3 {
		http.Error(w, "missing key", http.StatusBadRequest)
		return
	}
	key := parts[2]

	s.mu.Lock()
	leader := s.leader
	val, ok := s.store[key]
	s.mu.Unlock()

	// If we are not the leader, forward (or error)
	if leader == nil || *leader != s.id {
		if leader != nil {
			leaderAddr := s.peers[*leader]
			redirect := fmt.Sprintf("http://%s%s", leaderAddr, r.URL.Path)
			http.Redirect(w, r, redirect, http.StatusTemporaryRedirect)
			return
		}
		s.unavailable(w, "no leader known")
		return
	}
	if !ok {
		http.Error(w, "key not found", http.StatusNotFound)
		return
	}
	w.WriteHeader(http.StatusOK)
	fmt.Fprint(w, val)
}

/* ---------- Helper for 503 responses ---------- */

type errResp struct {
	Error string `json:"error"`
}

func (s *Server) unavailable(w http.ResponseWriter, msg string) {
	w.WriteHeader(http.StatusServiceUnavailable)
	json.NewEncoder(w).Encode(errResp{Error: msg})
}

/* ---------- Election timer (simple) ---------- */

func (s *Server) electionLoop() {
	for {
		// wait a random timeout between 150‑300 ms
		to := s.electionTimeout + time.Duration(rand.Intn(150))*time.Millisecond
		time.Sleep(to)

		s.mu.Lock()
		if s.leader != nil && *s.leader == s.id {
			s.mu.Unlock()
			continue // we are leader, no election needed
		}
		s.mu.Unlock()

		s.becomeCandidate()
	}
}

/* ---------- Server bootstrap ---------- */

func main() {
	var (
		idFlag    = flag.String("id", "", "unique node id (e.g. A)")
		portFlag  = flag.Int("port", 0, "listen port")
		peersFlag = flag.String("peers", "", "comma‑separated list id=host:port")
	)
	flag.Parse()
	if *idFlag == "" || *portFlag == 0 {
		log.Fatal("id and port are required")
	}
	peers := make(map[NodeID]string)
	if *peersFlag != "" {
		for _, p := range strings.Split(*peersFlag, ",") {
			kv := strings.SplitN(p, "=", 2)
			if len(kv) != 2 {
				log.Fatalf("bad peer spec: %s", p)
			}
			peers[NodeID(kv[0])] = kv[1]
		}
	}

	s := &Server{
		id:                NodeID(*idFlag),
		peers:             peers,
		term:              0,
		votedFor:          nil,
		log:               []LogEntry{},
		commitIdx:         -1,
		lastApplied:       -1,
		store:             make(map[string]string),
		leader:            nil,
		electionTimeout:  300 * time.Millisecond,
		heartbeatInterval: 100 * time.Millisecond,
		rpcTimeout:        500 * time.Millisecond,
	}
	mux := http.NewServeMux()
	mux.HandleFunc("/kv/", func(w http.ResponseWriter, r *http.Request) {
		if r.Method == http.MethodPut {
			s.handlePut(w, r)
		} else if r.Method == http.MethodGet {
			s.handleGet(w, r)
		} else {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		}
	})
	mux.HandleFunc("/_raft/append", s.handleAppendEntry)

	s.httpSrv = &http.Server{
		Addr:    fmt.Sprintf(":%d", *portFlag),
		Handler: mux,
	}
	// start background loops
	go s.electionLoop()

	s.logf("starting on %s (peers=%v)", s.httpSrv.Addr, s.peers)
	if err := s.httpSrv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
		log.Fatalf("listen error: %v", err)
	}
}
```

