## 7.  Full source file (copy‑paste ready)

```cpp
// kd_tree_2d.cpp
// Compile with:  g++ -std=c++17 -O2 -Wall kd_tree_2d.cpp -o kd_tree_2d

#include <algorithm>
#include <cmath>
#include <iostream>
#include <limits>
#include <memory>
#include <vector>

// ---------------------------------------------------------------
// 1️⃣  Point definition
// ---------------------------------------------------------------
struct Point {
    double x, y;
    double dist2(const Point& other) const {
        double dx = x - other.x;
        double dy = y - other.y;
        return dx*dx + dy*dy;
    }
};

// ---------------------------------------------------------------
// 2️⃣  KD‑Tree class (static construction, NN query)
// ---------------------------------------------------------------
class KDTree2D {
public:
    // Public node type is hidden; users only see Point* results.
    struct Node {
        Point pt;
        std::unique_ptr<Node> left, right;
        explicit Node(const Point& p) : pt(p) {}
    };

    // -----------------------------------------------------------------
    // Build from a vector of points (copies the data)
    // -----------------------------------------------------------------
    explicit KDTree2D(const std::vector<Point>& points) {
        std::vector<Point> pts = points;          // copy because we will reorder
        root = buildRecursive(std::move(pts), 0);
    }

    // -----------------------------------------------------------------
    // Nearest neighbour query
    // Returns {pointer to nearest point, squared distance}
    // -----------------------------------------------------------------
    std::pair<const Point*, double> nearest(const Point& query) const {
        const Point* best = nullptr;
        double bestDist2 = std::numeric_limits<double>::infinity();
        nearestRecursive(root.get(), query, 0, best, bestDist2);
        return {best, bestDist2};
    }

private:
    std::unique_ptr<Node> root;

    // -----------------------------------------------------------------
    // Recursive builder (median split)
    // -----------------------------------------------------------------
    static std::unique_ptr<Node> buildRecursive(std::vector<Point>&& pts, int depth) {
        if (pts.empty()) return nullptr;

        const int axis = depth % 2;
        size_t mid = pts.size() / 2;

        auto cmp = [axis](const Point& a, const Point& b) {
            return (axis == 0) ? a.x < b.x : a.y < b.y;
        };
        std::nth_element(pts.begin(), pts.begin() + mid, pts.end(), cmp);

        std::unique_ptr<Node> node = std::make_unique<Node>(pts[mid]);

        std::vector<Point> leftVec(pts.begin(), pts.begin() + mid);
        std::vector<Point> rightVec(pts.begin() + mid + 1, pts.end());

        node->left  = buildRecursive(std::move(leftVec), depth + 1);
        node->right = buildRecursive(std::move(rightVec), depth + 1);
        return node;
    }

    // -----------------------------------------------------------------
    // Recursive NN search with pruning
    // -----------------------------------------------------------------
    static void nearestRecursive(const Node* node,
                                 const Point& query,
                                 int depth,
                                 const Point*& best,
                                 double& bestDist2) {
        if (!node) return;

        // 1. Check current node
        double d2 = node->pt.dist2(query);
        if (d2 < bestDist2) {
            bestDist2 = d2;
            best = &node->pt;
        }

        // 2. Choose which side to explore first
        const int axis = depth % 2;
        double diff = (axis == 0) ? query.x - node->pt.x
                                  : query.y - node->pt.y;

        const Node* first  = diff < 0 ? node->left.get()  : node->right.get();
        const Node* second = diff < 0 ? node->right.get() : node->left.get();

        // 3. Recurse into the nearer side
        nearestRecursive(first, query, depth + 1, best, bestDist2);

        // 4. Possibly explore the far side (if hypersphere crosses the split)
        if (diff*diff < bestDist2) {
            nearestRecursive(second, query, depth + 1, best, bestDist2);
        }
    }
};

// ---------------------------------------------------------------
// 3️⃣  Demo driver
// ---------------------------------------------------------------
int main() {
    // ---- a small static point set ---------------------------------
    std::vector<Point> points = {
        {2.0, 3.0}, {5.0, 4.0}, {9.0, 6.0},
        {4.0, 7.0}, {8.0, 1.0}, {7.0, 2.0}
    };

    // ---- build the tree -------------------------------------------
    KDTree2D tree(points);

    // ---- queries ---------------------------------------------------
    std::vector<Point> queries = {
        {9.0, 2.0},
        {3.0, 4.5},
        {6.0, 5.0}
    };

    for (const auto& q : queries) {
        auto [nearestPt, dist2] = tree.nearest(q);
        if (nearestPt) {
            std::cout << "Query (" << q.x << ", " << q.y << ") → "
                      << "nearest (" << nearestPt->x << ", " << nearestPt->y << ") "
                      << "dist = " << std::sqrt(dist2) << '\n';
        } else {
            std::cout << "Tree empty!\n";
        }
    }
    return 0;
}
```

**Compile & run**

```bash
g++ -std=c++17 -O2 -Wall kd_tree_2d.cpp -o kd_tree_2d
./kd_tree_2d
```

You should see the same output as shown earlier.

---

## 8.  Where to go from here?

* **Performance tuning** – store the splitting axis inside each node to avoid recomputing `depth % 2`.  
* **Bulk loading** – if you have millions of points, allocate a single `std::vector<Node>` and use indices instead of `unique_ptr`.  
* **Radius search** – replace the “best distance” test with a fixed radius `R` and collect all points whose `dist2 <= R*R`.  
* **Higher‑dimensional data** – replace the `axis` logic with a template parameter `constexpr size_t K`.  

---

### TL;DR

* Build a balanced kd‑tree by recursively splitting on the median of the current axis (`x` then `y`).  
* For a query, walk down the tree, keep the best point seen so far, and **prune** any subtree whose splitting line lies farther than the current best distance.  
* The provided code does exactly that, is fully self‑contained, and can be used as a starting point for more sophisticated spatial‑search tasks. Happy coding! 🚀

Below is a **stand‑alone, production‑ready implementation of MurmurHash3‑x64 128‑bit** (the 128‑bit variant that Google’s original “MurmurHash3” paper recommends for non‑cryptographic hashing).  

* It is **fast** (a few CPU cycles per 8‑byte block).  
* It has **excellent avalanche behaviour** – a single‑bit change in the input flips roughly half the output bits.  
* In practice it shows **very low collision rates** for typical data sets (it is used in many databases, caches and file‑systems).  

> **Important** – MurmurHash3 is **not** a cryptographic hash. If you need resistance to deliberate attacks, use SHA‑256/Blake2/XXH3‑128‑k2. For “good enough” general‑purpose hashing (hash tables, checksums, deduplication, etc.) MurmurHash3‑128 is a solid choice.

---

## 1. How it works (high‑level)

1. **Initialize two 64‑bit state variables** (`h1`, `h2`) with a seed (default 0).  
2. **Process the input in 16‑byte (128‑bit) chunks**.  
   * Each chunk is split into two 64‑bit little‑endian words `k1` and `k2`.  
   * Each word is multiplied by a constant, rotated, multiplied again, and XOR‑ed into the state.  
   * After mixing each word, the two state variables are further mixed together (rotate, add, multiply).  
3. **Handle the tail** (the last < 16 bytes) with a similar “mix‑in” but without the full‑chunk loop.  
4. **Finalisation** – a series of XORs, rotates and multiplications (the “fmix64” function) that avalanche any remaining patterns and produce the final 128‑bit result.

The constants (`c1`, `c2`, `c3`, `c4`) are carefully chosen odd numbers that guarantee good diffusion across all bits. The algorithm is deterministic, portable (little‑endian only – the code does the conversion for you), and runs in **O(n)** time with **O(1)** extra memory.

---

## 2. Reference implementation (C++17)

```cpp
// murmurhash3_128.h
#pragma once
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <array>

namespace murmur3 {

/* -------------------------------------------------------------
   Helper: rotate left (C++20 has std::rotl, but we keep it C++17)
   ------------------------------------------------------------- */
static inline uint64_t rotl64(uint64_t x, int8_t r) noexcept {
    return (x << r) | (x >> (64 - r));
}

/* -------------------------------------------------------------
   fmix64 – final avalanche mix, taken from the original paper
   ------------------------------------------------------------- */
static inline uint64_t fmix64(uint64_t k) noexcept {
    k ^= k >> 33;
    k *= 0xff51afd7ed558ccdULL;
    k ^= k >> 33;
    k *= 0xc4ceb9fe1a85ec53ULL;
    k ^= k >> 33;
    return k;
}

/* -------------------------------------------------------------
   MurmurHash3_x64_128
   Input:
      - key   : pointer to data
      - len   : length in bytes
      - seed  : 32‑bit seed (default 0)
   Output:
      - 128‑bit hash as std::array<uint64_t,2>  (h1, h2)
   ------------------------------------------------------------- */
inline std::array<uint64_t, 2> hash128(const void* key,
                                      std::size_t len,
                                      uint32_t seed = 0) noexcept
{
    const uint8_t* data = static_cast<const uint8_t*>(key);
    const std::size_t nblocks = len / 16;

    // ----- 1. Initialise state -----
    uint64_t h1 = static_cast<uint64_t>(seed);
    uint64_t h2 = static_cast<uint64_t>(seed);

    const uint64_t c1 = 0x87c37b91114253d5ULL;
    const uint64_t c2 = 0x4cf5ad432745937fULL;

    // ----- 2. Body: 16‑byte blocks -----
    const uint64_t* blocks = reinterpret_cast<const uint64_t*>(data);
    for (std::size_t i = 0; i < nblocks; ++i) {
        // little‑endian load
        uint64_t k1 = blocks[i * 2 + 0];
        uint64_t k2 = blocks[i * 2 + 1];

        // mix k1
        k1 *= c1;  k1 = rotl64(k1,31);  k1 *= c2;  h1 ^= k1;
        h1 = rotl64(h1,27);  h1 += h2;  h1 = h1*5 + 0x52dce729;

        // mix k2
        k2 *= c2;  k2 = rotl64(k2,33);  k2 *= c1;  h2 ^= k2;
        h2 = rotl64(h2,31);  h2 += h1;  h2 = h2*5 + 0x38495ab5;
    }

    // ----- 3. Tail (remaining <16 bytes) -----
    const uint8_t* tail = data + nblocks * 16;
    uint64_t k1 = 0;
    uint64_t k2 = 0;

    switch (len & 15) {               // fall‑through is intentional
        case 15: k2 ^= uint64_t(tail[14]) << 48;
        case 14: k2 ^= uint64_t(tail[13]) << 40;
        case 13: k2 ^= uint64_t(tail[12]) << 32;
        case 12: k2 ^= uint64_t(tail[11]) << 24;
        case 11: k2 ^= uint64_t(tail[10]) << 16;
        case 10: k2 ^= uint64_t(tail[ 9]) << 8;
        case  9: k2 ^= uint64_t(tail[ 8]) << 0;
                 k2 *= c2; k2 = rotl64(k2,33); k2 *= c1; h2 ^= k2;
        case  8: k1 ^= uint64_t(tail[ 7]) << 56;
        case  7: k1 ^= uint64_t(tail[ 6]) << 48;
        case  6: k1 ^= uint64_t(tail[ 5]) << 40;
        case  5: k1 ^= uint64_t(tail[ 4]) << 32;
        case  4: k1 ^= uint64_t(tail[ 3]) << 24;
        case  3: k1 ^= uint64_t(tail[ 2]) << 16;
        case  2: k1 ^= uint64_t(tail[ 1]) << 8;
        case  1: k1 ^= uint64_t(tail[ 0]) << 0;
                 k1 *= c1; k1 = rotl64(k1,31); k1 *= c2; h1 ^= k1;
        // case 0: nothing left to do
    };

    // ----- 4. Finalisation -----
    h1 ^= static_cast<uint64_t>(len);
    h2 ^= static_cast<uint64_t>(len);

    h1 += h2;
    h2 += h1;

    h1 = fmix64(h1);
    h2 = fmix64(h2);

    h1 += h2;
    h2 += h1;

    return {h1, h2};
}

/* -------------------------------------------------------------
   Convenience overload for std::string / std::vector / raw bytes
   ------------------------------------------------------------- */
template <class T>
inline std::array<uint64_t,2> hash128(const T& container,
                                      uint32_t seed = 0) noexcept
{
    return hash128(container.data(),
                   container.size() * sizeof(typename T::value_type),
                   seed);
}

} // namespace murmur3
```

### How to use it

```cpp
