// src/lib.rs (or src/main.rs)

/// Constant‑time equality for byte slices.
///
/// # Panics
///
/// Panics if the slices have different lengths.
pub fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    assert_eq!(a.len(), b.len(), "Slices must have the same length");
    let mut diff: u8 = 0;
    for (&x, &y) in a.iter().zip(b.iter()) {
        diff |= x ^ y;
    }
    diff == 0
}

/// Variant that tolerates different lengths (returns `false` on mismatch).
pub fn constant_time_eq_len(a: &[u8], b: &[u8]) -> bool {
    let max_len = a.len().max(b.len());
    let mut diff: u8 = (a.len() ^ b.len()) as u8;
    for i in 0..max_len {
        let x = *a.get(i).unwrap_or(&0);
        let y = *b.get(i).unwrap_or(&0);
        diff |= x ^ y;
    }
    diff == 0
}

/// Very defensive version that uses volatile reads to keep the loop alive.
#[inline(never)]
pub fn constant_time_eq_volatile(a: &[u8], b: &[u8]) -> bool {
    assert_eq!(a.len(), b.len());
    let mut diff: u8 = 0;
    unsafe {
        for i in 0..a.len() {
            let x = core::ptr::read_volatile(a.as_ptr().add(i));
            let y = core::ptr::read_volatile(b.as_ptr().add(i));
            diff |= x ^ y;
        }
    }
    diff == 0
}

/* -------------------------------------------------------------------------- */
/* Example usage ------------------------------------------------------------- */

