    let candidate = b"my‑super‑secret‑token";

    if constant_time_eq(secret, candidate) {
        println!("✅ Authenticated");
    } else {
        println!("❌ Authentication failed");
    }
}

/* -------------------------------------------------------------------------- */
/* Tests -------------------------------------------------------------------- */

