</dependency>
*/

import jakarta.json.Json;
import jakarta.json.JsonObject;
import jakarta.json.JsonReader;

import java.io.StringReader;

public class JsonParsingDemo {

    public static void main(String[] args) {
        // -----------------------------------------------------------------
        // 1️⃣ The JSON we want to parse (could come from a file, HTTP body, …)
        // -----------------------------------------------------------------
        String json = """
                {
                  "id"      : 123,
                  "name"    : "Acme Widgets",
                  "active"  : true,
                  "tags"    : ["hardware","sale"],
                  "address" : {
                      "city"    : "Springfield",
                      "zipCode" : "01101"
                  }
                }
                """;

        // -----------------------------------------------------------------
        // 2️⃣ Create a JsonReader that reads from the String
        // -----------------------------------------------------------------
        try (JsonReader reader = Json.createReader(new StringReader(json))) {
            // -----------------------------------------------------------------
            // 3️⃣ Read the top‑level JSON value – in this case an object
            // -----------------------------------------------------------------
            JsonObject root = reader.readObject();

            // -----------------------------------------------------------------
            // 4️⃣ Extract data from the object (type‑safe getters)
            // -----------------------------------------------------------------
            int    id      = root.getInt("id");
            String name    = root.getString("name");
            boolean active = root.getBoolean("active");

            // Nested object
            JsonObject address = root.getJsonObject("address");
            String city = address.getString("city");
            String zip  = address.getString("zipCode");

            // Array – we just print the raw JSON array here
            var tags = root.getJsonArray("tags");

            // -----------------------------------------------------------------
            // 5️⃣ Use the values (here we just print them)
            // -----------------------------------------------------------------
            System.out.println("id      = " + id);
            System.out.println("name    = " + name);
            System.out.println("active  = " + active);
            System.out.println("city    = " + city);
            System.out.println("zipCode = " + zip);
            System.out.println("tags    = " + tags);
        }
    }
}
```

