```js
// 2️⃣ retry‑example.js
// --------------------------------------------------------------
import axios from "axios";
import axiosRetry from "axios-retry";

/**
 * Configure axios‑retry once (usually at app start‑up)
 *
 * • `retries` – max number of attempts (original request + retries)
 * • `retryDelay` – function that returns the ms to wait before the next try.
 *   The default is exponential back‑off (2^retryCount * 1000) but you can
 *   customise it (e.g. jitter, fixed, etc.).
 * • `retryCondition` – decides *whether* a request should be retried.
 *   The default retries on network errors & on HTTP status >= 500.
 */
axiosRetry(axios, {
  retries: 3,                     // try up to 3 extra times (4 total attempts)
  retryDelay: axiosRetry.exponentialDelay, // 1s, 2s, 4s … (see below)
  // optional: add jitter to avoid thundering‑herd
  // retryDelay: (retryCount) => {
  //   const delay = axiosRetry.exponentialDelay(retryCount);
  //   const jitter = Math.random() * 100; // ±0‑100 ms
  //   return delay + jitter;
  // },
  retryCondition: (error) => {
    // Retry on network errors, 5xx, or on a custom status (e.g. 429 Too Many Requests)
    const shouldRetry =
      axiosRetry.isNetworkOrIdempotentRequestError(error) ||
      error.response?.status === 429;
    return shouldRetry;
  },
});

/**
 * Example request – any axios call now automatically gets the retry logic.
 */
async function fetchUser(id) {
  try {
    const response = await axios.get(`https://jsonplaceholder.typicode.com/users/${id}`);
    console.log("✅ Got data:", response.data);
    return response.data;
  } catch (err) {
    // After all retries have been exhausted this block runs
    console.error("❌ Request failed after retries:", err.message);
    // You can inspect err.response, err.code, etc.
    throw err;
  }
}

/**
 * Run a demo – try a valid ID and an invalid one to see the retry behaviour.
 */
(async () => {
  // Successful request (no retries)
  await fetchUser(1);

  // Force a failure (status 404) – by default 404 is *not* retried
  // but we can change the condition above if you want to retry it.
  await fetchUser(9999).catch(() => {}); // swallow for demo
})();
```

Run it:

```bash
node retry-example.js
```

You should see something like:

```
✅ Got data: { id: 1, name: 'Leanne Graham', … }
❌ Request failed after retries: Request failed with status code 404
```

If you point the URL at a flaky endpoint (or temporarily disconnect your network) you’ll see the exponential back‑off delays printed by `axios-retry` (it logs internally when `axios.defaults.debug = true` or you can add your own `console.log` inside `retryDelay`).

---

## How `axios-retry` works (the gist)

1. **Interceptor injection** – `axiosRetry(axios, options)` registers a **response interceptor** on the supplied `axios` instance.  
2. **When a request fails** the interceptor receives the error object.  
3. It calls `options.retryCondition(error)` (or the built‑in default) to decide *if* the request is eligible for a retry.  
4. If it should retry and the current attempt count is `< options.retries`, the interceptor:
   * **Computes a delay** with `options.retryDelay(attemptNumber)`.  
   * **Pauses** (`setTimeout`) for that many milliseconds.  
   * **Re‑issues the request** using the original config (including headers, body, etc.).  
5. The process repeats until either the request succeeds or the retry limit is hit, at which point the error is propagated to your `catch` block.

### Built‑in helpers

| Helper | What it does |
|--------|--------------|
| `axiosRetry.isNetworkOrIdempotentRequestError(error)` | Returns `true` for network errors (`ECONNABORTED`, DNS failures, etc.) **or** for idempotent HTTP methods (`GET`, `HEAD`, `OPTIONS`, `PUT`, `DELETE`) that received a 5xx response. |
| `axiosRetry.exponentialDelay(retryCount)` | Returns `Math.pow(2, retryCount) * 1000` (1 s, 2 s, 4 s …). Good for most back‑off strategies. |
| `axiosRetry.isRetryableError(error)` | Alias for the default condition (network errors + 5xx). |

### Customising the back‑off

You can replace `retryDelay` with any function that returns a number of milliseconds:

```js
// Fixed 2‑second delay
retryDelay: () => 2000

// Linear back‑off: 1s, 2s, 3s …
retryDelay: (count) => count * 1000

// Exponential with jitter (recommended for distributed systems)
retryDelay: (count) => {
  const base = Math.pow(2, count) * 1000; // 1s, 2s, 4s …
  const jitter = Math.random() * 300;    // ±0‑300 ms
  return base + jitter;
}
```

### When to *not* use it

* **Non‑idempotent POST/PUT that changes state** – retrying could cause duplicate writes. If you must retry such calls, make sure the server is designed to be idempotent (e.g., using an idempotency key).  
* **Very low latency requirements** – each retry adds at least a second of delay by default. Adjust `retryDelay` or `retries` accordingly.

---

