```rust
// src/main.rs
use sqlx::{postgres::PgPoolOptions, FromRow};
use std::env;

#[derive(Debug, FromRow)]
struct NowRow {
    now: chrono::DateTime<chrono::Utc>,
}

#[tokio::main]
async fn main() -> Result<(), sqlx::Error> {
    let database_url = env::var("DATABASE_URL")
        .expect("DATABASE_URL must be set in the environment");

    let pool = PgPoolOptions::new()
        .max_connections(5)
        .connect(&database_url)
        .await?;

    let row: NowRow = sqlx::query_as!(
        NowRow,
        r#"SELECT now() as "now!""#
    )
    .fetch_one(&pool)
    .await?;

    println!("Current time from PostgreSQL: {}", row.now);

    // Example of a multi‑row query
    let tables = sqlx::query!(
        r#"
        SELECT schemaname, tablename
        FROM pg_catalog.pg_tables
        WHERE schemaname NOT IN ('pg_catalog', 'information_schema')
        ORDER BY schemaname, tablename
        LIMIT 5
        "#
    )
    .fetch_all(&pool)
    .await?;

    println!("--- Sample tables in the DB ---");
    for t in tables {
        println!("{}.{}", t.schemaname, t.tablename);
    }

    Ok(())
}
```

That’s it! You now have a working `sqlx`‑based PostgreSQL client, with async execution, connection pooling, and type‑safe query mapping. Happy coding! 🚀

Below is a **complete, minimal example** that shows how to:

1. **Add the `image` crate** to your project (`Cargo.toml`).
2. **Load a PNG file** from disk.
3. **Crop** a rectangular region out of it.
4. **Save** the cropped image back to disk (as PNG again).

You can copy‑paste the snippets into a fresh Cargo project and run them right away.

---

## 1. `Cargo.toml`

```toml
[package]
name = "png_crop_demo"
version = "0.1.0"
edition = "2021"

# The only external dependency we need for this demo
[dependencies]
image = { version = "0.25", features = ["png"] }
```

* `image = "0.25"` is the latest stable release at the time of writing.  
* The `png` feature is enabled explicitly – it pulls in the PNG decoder/encoder and keeps the crate’s compile time down if you only need PNG support.

---

## 2. `src/main.rs`

```rust
use std::path::Path;
use image::{io::Reader as ImageReader, GenericImageView, ImageError, ImageOutputFormat};

/// Crops a PNG image.
///
/// * `src_path` – Path to the source PNG file.
/// * `dst_path` – Where the cropped PNG will be written.
/// * `crop_x`, `crop_y` – Upper‑left corner of the crop rectangle (in pixels).
/// * `crop_width`, `crop_height` – Size of the rectangle (in pixels).
///
/// Returns `Ok(())` on success or an `ImageError` on failure.
fn crop_png<P: AsRef<Path>>(
    src_path: P,
    dst_path: P,
    crop_x: u32,
    crop_y: u32,
    crop_width: u32,
    crop_height: u32,
) -> Result<(), ImageError> {
    // -------------------------------------------------------------------------
    // 1️⃣  Load the PNG (the `image` crate automatically detects the format)
    // -------------------------------------------------------------------------
    let img = ImageReader::open(&src_path)?
        .with_guessed_format()?   // make sure we really have a PNG (or any supported format)
        .decode()?;               // `DynamicImage`

    // -------------------------------------------------------------------------
    // 2️⃣  Verify that the requested crop rectangle fits inside the image
    // -------------------------------------------------------------------------
    let (img_width, img_height) = img.dimensions();
    if crop_x + crop_width > img_width || crop_y + crop_height > img_height {
        return Err(ImageError::DimensionError(format!(
            "Crop rectangle ({}, {} – {}×{}) exceeds image bounds ({}, {})",
            crop_x,
            crop_y,
            crop_width,
            crop_height,
            img_width,
            img_height
        )));
    }

    // -------------------------------------------------------------------------
    // 3️⃣  Perform the crop.
    //     `crop_imm` returns a *new* image that owns its pixel buffer.
    // -------------------------------------------------------------------------
    let cropped = img.crop_imm(crop_x, crop_y, crop_width, crop_height);

    // -------------------------------------------------------------------------
    // 4️⃣  Write the result back to disk as PNG.
    // -------------------------------------------------------------------------
    // `save_with_format` would also work, but using a writer gives us more
    // control (e.g. we could change compression level later).
    let mut out_file = std::fs::File::create(&dst_path)?;
    cropped.write_to(&mut out_file, ImageOutputFormat::Png)?;

    Ok(())
}

// -----------------------------------------------------------------------------
// Example usage (run with `cargo run --release`)
// -----------------------------------------------------------------------------
fn main() {
    // Adjust these paths to point at a real PNG on your machine.
    let src = "examples/input.png";
    let dst = "examples/cropped.png";

    // Crop a 200×150 rectangle starting at (x=50, y=30)
    let crop_x = 50;
    let crop_y = 30;
    let crop_w = 200;
    let crop_h = 150;

    match crop_png(src, dst, crop_x, crop_y, crop_w, crop_h) {
        Ok(()) => println!("✅ Cropped image saved to `{}`", dst),
        Err(e) => eprintln!("❌ Failed to crop image: {}", e),
    }
}
```

### What the code does, step‑by‑step

| Step | Code | Explanation |
|------|------|-------------|
| **1️⃣ Load** | `ImageReader::open(...).with_guessed_format()?.decode()?` | Opens the file, lets the crate sniff the format (PNG, JPEG, …) and decodes it into a `DynamicImage`. |
| **2️⃣ Bounds check** | `if crop_x + crop_width > img_width …` | Guarantees we don’t panic by trying to crop outside the image. |
| **3️⃣ Crop** | `img.crop_imm(...)` | Returns a *new* `DynamicImage` that contains only the requested rectangle. (`crop` would mutate the original; `crop_imm` is safer for most scripts.) |
| **4️⃣ Save** | `cropped.write_to(&mut out_file, ImageOutputFormat::Png)` | Encodes the cropped image as PNG and writes it to `dst_path`. |

---

