## 3. `main.go`

```go
package main

import (
	"bufio"
	"fmt"
	"io"
	"log"
	"os"
	"strings"
	"time"

	"github.com/adrianmo/go-nmea"
	"github.com/tarm/serial"
)

// ---------------------------------------------------------------------
// Helper: read NMEA sentences from any io.Reader (serial, file, strings)
// ---------------------------------------------------------------------
func readSentences(r io.Reader, out chan<- string) {
	scanner := bufio.NewScanner(r)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" {
			out <- line
		}
	}
	if err := scanner.Err(); err != nil {
		log.Printf("scanner error: %v", err)
	}
	close(out)
}

// ---------------------------------------------------------------------
// Helper: parse a single NMEA sentence and print the fields we care about
// ---------------------------------------------------------------------
func handleSentence(raw string) {
	// The go-nmea library automatically validates the checksum.
	// If you want to ignore checksum errors you can use nmea.ParseRaw.
	s, err := nmea.Parse(raw)
	if err != nil {
		// Most of the time a parse error means a malformed sentence or bad checksum.
		// We just log it and move on.
		log.Printf("parse error: %v (raw=%q)", err, raw)
		return
	}

	switch s.DataType() {
	case nmea.TypeGGA:
		// Global Positioning System Fix Data
		gga := s.(nmea.GGA)
		fmt.Printf("[GGA] %s  Lat: %8.5f %s  Lon: %9.5f %s  Fix: %d  Alt: %.1f %s\n",
			gga.Time,
			gga.Latitude, gga.LatitudeDirection,
			gga.Longitude, gga.LongitudeDirection,
			gga.FixQuality,
			gga.Altitude, gga.AltitudeUnits)

	case nmea.TypeRMC:
		// Recommended Minimum Navigation Information
		rmc := s.(nmea.RMC)
		fmt.Printf("[RMC] %s  Lat: %8.5f %s  Lon: %9.5f %s  Speed: %.1f kn  Course: %.1f°  Valid: %t\n",
			rmc.Time,
			rmc.Latitude, rmc.LatitudeDirection,
			rmc.Longitude, rmc.LongitudeDirection,
			rmc.Speed,
			rmc.Course,
			rmc.Valid)

	// Add more cases if you need other sentence types (GSV, VTG, GSA, etc.)
	default:
		// For everything else we just print the raw sentence (useful for debugging)
		fmt.Printf("[%s] %s\n", s.DataType(), raw)
	}
}

// ---------------------------------------------------------------------
// Main entry point
// ---------------------------------------------------------------------
func main() {
	// -----------------------------------------------------------------
	// 1️⃣ Choose your input source
	// -----------------------------------------------------------------
	var src io.Reader

	// ---- a) From a serial port (most common) -----------------------
	// Uncomment the block below if you have a GPS dongle on /dev/ttyUSB0
	/*
		c := &serial.Config{
			Name:        "/dev/ttyUSB0", // Windows: "COM3", macOS: "/dev/cu.usbserial"
			Baud:        9600,
			ReadTimeout: time.Second * 5,
		}
		s, err := serial.OpenPort(c)
		if err != nil {
			log.Fatalf("failed to open serial port: %v", err)
		}
		defer s.Close()
		src = s
	*/

	// ---- b) From a file (e.g. a log dump) -------------------------
	// Uncomment if you have a file with one NMEA sentence per line.
	/*
		f, err := os.Open("gps.log")
		if err != nil {
			log.Fatalf("cannot open file: %v", err)
		}
		defer f.Close()
		src = f
	*/

	// ---- c) From a hard‑coded string slice (quick demo) ------------
	// This is the fallback that always works, great for a minimal demo.
	sample := []string{
		"$GPGGA,123519,4807.038,N,01131.000,E,1,08,0.9,545.4,M,46.9,M,,*47",
		"$GPRMC,123520,A,4807.038,N,01131.000,E,022.4,084.4,230394,003.1,W*6A",
		"$GPGGA,123521,3723.2475,N,12158.3416,W,1,10,0.78,9.0,M,-34.0,M,,*76",
		"$GPRMC,123522,A,3723.2475,N,12158.3416,W,0.13,309.62,120598,015.5,E*67",
	}
	src = strings.NewReader(strings.Join(sample, "\n"))

	// -----------------------------------------------------------------
	// 2️⃣ Spin up a goroutine that streams raw sentences into a channel
	// -----------------------------------------------------------------
	sentences := make(chan string, 100) // buffered so the scanner never blocks
	go readSentences(src, sentences)

	// -----------------------------------------------------------------
	// 3️⃣ Consume the channel and parse each sentence
	// -----------------------------------------------------------------
	for raw := range sentences {
		handleSentence(raw)
	}
}
```

### What the program does, step‑by‑step

| Step | What happens | Why it matters |
|------|--------------|----------------|
| **Choose input source** | You can read from a serial port, a file, or a hard‑coded slice. | Real‑world GPS modules speak over UART (serial). For testing you can just feed strings. |
| **`readSentences`** | Uses a `bufio.Scanner` to split the stream on new‑lines, trims whitespace, and pushes each line onto a channel. | Keeps the parsing logic completely decoupled from I/O, making it easy to add buffering, time‑outs, or multiplex several sources. |
| **`handleSentence`** | Calls `nmea.Parse` (which validates the checksum) and then switches on the sentence type (`GGA`, `RMC`, …). | The library returns a concrete struct for each type, so you get typed fields (`Latitude`, `Longitude`, `Time`, etc.) without manual string slicing. |
| **Printing** | Formats the most useful fields in a human‑readable line. | Shows you that the parsing succeeded and gives you the data you’d normally feed into a map, database, or UI. |

