Below is a **minimal, self‑contained** example that shows how the (still‑experimental) `inline_proof_blocks` language feature can be used to embed *compiler‑checked* proofs directly next to the code they justify.

```rust
//! Demonstrates the `inline_proof_blocks` feature.
//! The example proves that `max` really returns the larger of its two arguments.

#![feature(inline_proof_blocks)]   // <‑‑ enable the feature for the whole crate
#![allow(dead_code)]               // (just to keep the example tidy)

/// A *pure* helper that implements the mathematical definition of `max`.
///
/// The `#[pure]` attribute tells the verifier that the function has no side‑effects
/// and can be used inside proof blocks.
#[pure]
fn max_def(a: i32, b: i32) -> i32 {
    if a >= b { a } else { b }
}

/// Returns the greater of `a` and `b`.
///
/// The contract is expressed with the `#[ensures]` attribute.  The body contains an
/// `proof { … }` block that the compiler checks against the contract.
#[ensures(result == max_def(a, b))]
fn max(a: i32, b: i32) -> i32 {
    // ----------------------------------------------------------------------
    //  Proof block – everything inside is *checked* by the verifier.
    //  It may only call `#[pure]` functions and use `assert!`/`assert_eq!`.
    // ----------------------------------------------------------------------
    proof {
        // The implementation we are about to return is exactly `max_def`.
        // Because `max_impl` is marked `#[pure]` the verifier can unfold it.
        assert_eq!(max_impl(a, b), max_def(a, b));
    }

    // ----------------------------------------------------------------------
    //  Actual (executable) implementation.
    // ----------------------------------------------------------------------
    max_impl(a, b)
}

/// The concrete implementation used at run‑time.
///
/// Marked `#[pure]` so the verifier can reason about it inside `proof {}` blocks.
#[pure]
fn max_impl(a: i32, b: i32) -> i32 {
    if a >= b { a } else { b }
}

/* -------------------------------------------------------------------------
   A tiny test harness – the verifier does **not** run this, it only checks the
   proof blocks above.  The test is here to show that the code also works at
   run‑time.
   ------------------------------------------------------------------------- */
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sanity_check() {
        assert_eq!(max(5, 3), 5);
        assert_eq!(max(2, 9), 9);
        assert_eq!(max(-1, -4), -1);
    }
}
