#![feature(implicit_async_everywhere)]

use std::future::Future;
use std::pin::Pin;
use std::task::{Context, Poll};
use std::time::Duration;
use tokio::time::sleep;

async fn fetch_data() -> i32 {
    sleep(Duration::from_secs(1)).await;
    42
}

// regular function, not marked async, but we can .await
fn compute() -> i32 {
    // The compiler implicitly transforms this block into an async fn,
    // so we can use .await directly.
    let value = fetch_data().await;
