        std::cout << "  Message          : " << res.message << '\n';
    }
    std::cout << "===========================\n";
}

// ---------------------------------------------------------------
// 3️⃣  Main – perform the calibration.
// ---------------------------------------------------------------
int main()
{
    using namespace kitt;               // bring API symbols into scope
    using namespace std::chrono_literals;

    std::cout << "=== K.I.T.T. Drive‑Control Calibration Demo ===\n";

    // -----------------------------------------------------------------
    // 3.1️⃣  Create a DriveControl object – this opens the communication
    //       channel (e.g. USB, CAN, Ethernet) and performs basic init.
    // -----------------------------------------------------------------
    DriveControl drive;
    if (!drive.isConnected()) {
        std::cerr << "ERROR: Could not connect to the K.I.T.T. drive controller.\n";
        return EXIT_FAILURE;
    }
    std::cout << "Connected to controller, firmware v"
              << drive.firmwareVersion() << "\n";

    // -----------------------------------------------------------------
    // 3.2️⃣  Optional: put the hardware into a known safe state.
    // -----------------------------------------------------------------
    drive.setBrake(true);               // engage brake while we calibrate
    std::this_thread::sleep_for(200ms); // give the brake time to settle

    // -----------------------------------------------------------------
    // 3.3️⃣  Run the built‑in calibration routine.
    //       The call blocks until the procedure finishes (≈ 2‑3 s).
    // -----------------------------------------------------------------
    std::cout << "Starting calibration …\n";
    DriveCalibrationResult result = drive.calibrate();

    // -----------------------------------------------------------------
    // 3.4️⃣  Show the outcome.
    // -----------------------------------------------------------------
    printResult(result);

    if (!result.success) {
        std::cerr << "Calibration failed – aborting.\n";
        return EXIT_FAILURE;
    }

    // -----------------------------------------------------------------
    // 3.5️⃣  Release the brake and verify that the controller is ready.
    // -----------------------------------------------------------------
    drive.setBrake(false);
    std::cout << "Brake released. Drive‑control is now ready for motion commands.\n";

    // -----------------------------------------------------------------
    // 3.6️⃣  (Optional) Persist the calibration data for later runs.
    // -----------------------------------------------------------------
    if (!drive.saveCalibration(result)) {
        std::cerr << "WARNING: Could not store calibration data to non‑volatile memory.\n";
    } else {
        std::cout << "Calibration data saved to flash.\n";
    }

    std::cout << "=== Calibration complete ===\n";
    return EXIT_SUCCESS;
}
```

### What the Example Does

| Step | Action | Reason |
|------|--------|--------|
| **1️⃣ Include** | `#include <kitt/drive_control.hpp>` | Pulls in the public API (`DriveControl`, `DriveCalibrationResult`, …). |
| **2️⃣ Helper** | `printResult()` | Formats the result for human‑readable output. |
| **3.1️⃣ Create** | `DriveControl drive;` | Opens the communication channel and checks connectivity. |
| **3.2️⃣ Safe state** | `drive.setBrake(true);` | Guarantees the vehicle cannot move while the sensors are being zeroed. |
| **3.3️⃣ Calibrate** | `drive.calibrate();` | Executes the firmware‑level calibration routine (zero‑offset, scale factor, temperature compensation). |
| **3.4️⃣ Report** | `printResult(result);` | Shows success flag, measured parameters, and any error information. |
| **3.5️⃣ Ready** | `drive.setBrake(false);` | Releases the brake so the system can accept motion commands. |
| **3.6️⃣ Persist** | `drive.saveCalibration(result);` | Stores the new parameters in non‑volatile memory (optional but recommended). |

### API Highlights (for the internal docs)

| Function | Description |
|----------|-------------|
| `bool DriveControl::isConnected() const;` | Returns `true` if the controller handshake succeeded. |
| `std::string DriveControl::firmwareVersion() const;` | Human‑readable firmware identifier. |
| `void DriveControl::setBrake(bool engaged);` | Engages (`true`) or releases (`false`) the mechanical brake. |
| `DriveCalibrationResult DriveControl::calibrate();` | Runs the full calibration sequence and returns a struct with the outcome. |
| `bool DriveControl::saveCalibration(const DriveCalibrationResult&);` | Writes the supplied calibration data to the controller’s flash; returns success flag. |

> **Tip:** In production code you’ll likely want to wrap the whole sequence in a retry loop and add timeout handling for `calibrate()`. The SDK also provides an asynchronous version (`calibrateAsync`) if blocking the calling thread is undesirable.

