## 11. TL;DR – Minimal “copy‑paste” version

If you just want a **single file** to compile quickly (Linux/macOS) without the wrapper class, you can use the following **self‑contained** program. It does the same thing but keeps everything in `main()`.

```cpp
// quic_simple_client.cpp
#include <msquic.h>
#include <iostream>
#include <vector>
#include <future>
#include <cstring>
#include <arpa/inet.h>
#include <unistd.h>

static const QUIC_API_TABLE* MsQuic = nullptr;

struct ConnCtx {
    std::promise<void> connected;
    std::promise<void> sent;
};

extern "C" QUIC_STATUS QUIC_API ConnCallback(HQUIC, void* ctx, QUIC_CONNECTION_EVENT* ev) {
    ConnCtx* c = static_cast<ConnCtx*>(ctx);
    switch (ev->Type) {
        case QUIC_CONNECTION_EVENT_CONNECTED:
            c->connected.set_value();
            break;
        case QUIC_CONNECTION_EVENT_SHUTDOWN_INITIATED_BY_TRANSPORT:
        case QUIC_CONNECTION_EVENT_SHUTDOWN_INITIATED_BY_PEER:
        case QUIC_CONNECTION_EVENT_SHUTDOWN_COMPLETE:
            c->connected.set_exception(std::make_exception_ptr(std::runtime_error("Conn shutdown")));
            break;
        default: break;
    }
    return QUIC_STATUS_SUCCESS;
}

extern "C" QUIC_STATUS QUIC_API StreamCallback(HQUIC, void* ctx, QUIC_STREAM_EVENT* ev) {
    ConnCtx* c = static_cast<ConnCtx*>(ctx);
    if (ev->Type == QUIC_STREAM_EVENT_SEND_COMPLETE) {
        c->sent.set_value();
    }
    return QUIC_STATUS_SUCCESS;
}

int main(int argc, char* argv[]) {
    if (argc != 3) { std::cerr << "Usage: " << argv[0] << " <ip> <port>\n"; return 1; }
    const char* ip   = argv[1];
    uint16_t   port  = static_cast<uint16_t>(std::stoi(argv[2]));

    if (QUIC_FAILED(MsQuicOpen(&MsQuic))) { std::cerr << "MsQuicOpen failed\n"; return 1; }

    // Registration
    QUIC_REGISTRATION_CONFIG reg = {"simple-client", QUIC_EXECUTION_PROFILE_LOW_LATENCY};
    HQUIC regHandle = nullptr;
    MsQuic->RegistrationOpen(&reg, &regHandle);

    // ALPN = "hq-29"
    uint8_t alpnBuf[] = {5, 'h','q','-','2','9'};
    QUIC_BUFFER alpn = {sizeof(alpnBuf), alpnBuf};

    // Configuration (no cert validation)
    QUIC_SETTINGS settings = {};
    HQUIC cfg = nullptr;
    MsQuic->ConfigurationOpen(regHandle, &alpn, 1, &settings, sizeof(settings), nullptr, &cfg);
    QUIC_CREDENTIAL_CONFIG cred = {};
    cred.Type = QUIC_CREDENTIAL_TYPE_NONE;
    cred.Flags = QUIC_CREDENTIAL_FLAG_NO_CERTIFICATE_VALIDATION;
    MsQuic->ConfigurationLoadCredential(cfg, &cred);

    // Connection
    ConnCtx ctx;
    HQUIC conn = nullptr;
    MsQuic->ConnectionOpen(regHandle, ConnCallback, &ctx, &conn);

    // Resolve address (IPv4 only)
    sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_port   = htons(port);
    inet_pton(AF_INET, ip, &addr.sin_addr);

    MsQuic->ConnectionStart(conn, cfg,
        QUIC_ADDRESS_FAMILY_INET,
        reinterpret_cast<const QUIC_ADDR*>(&addr),
        port);

    // Wait for handshake
    ctx.connected.get_future().get();

    // Open a unidirectional stream
    HQUIC stream = nullptr;
    MsQuic->StreamOpen(conn, QUIC_STREAM_OPEN_FLAG_UNIDIRECTIONAL,
                       StreamCallback, &ctx, &stream);

    // Build payload (5 MiB)
    std::vector<uint8_t> payload(5*1024*1024, 0xAA);
    QUIC_BUFFER buf{static_cast<uint32_t>(payload.size()), payload.data()};

    MsQuic->StreamSend(stream, &buf, 1, QUIC_SEND_FLAG_FIN, nullptr);
    ctx.sent.get_future().get();   // blocks until ACKed

    std::cout << "All data ACKed – loss‑less!\n";

    // Cleanup
    MsQuic->StreamClose(stream);
    MsQuic->ConnectionClose(conn);
    MsQuic->ConfigurationClose(cfg);
    MsQuic->RegistrationClose(regHandle);
    return 0;
}
```

Compile with:

```bash
g++ -std=c++17 -I/path/to/msquic/include -L/path/to/msquic/lib -lmsquic -pthread quic_simple_client.cpp -o quic-simple-client
```

Run against the test server as before. The program will exit only after the remote side has ACKed **every** byte – that is the loss‑less guarantee you wanted.

