## 3. Minimal client – “UDP‑Reliable‑Exactly‑Once”

```go
// udp_exactlyonce_client.go
package main

import (
	"encoding/binary"
	"flag"
	"fmt"
	"log"
	"net"
	"time"
)

const (
	magic   uint16 = 0x55AA
	dataMsg byte   = 0x01
	ackMsg  byte   = 0x02

	maxPayload = 1024
)

var (
	serverAddr = flag.String("s", "127.0.0.1:9000", "server address")
	msg        = flag.String("msg", "hello world", "payload to send")
	timeout    = flag.Duration("t", 2*time.Second, "ACK timeout")
	retries    = flag.Int("r", 5, "max retransmission attempts")
)

func main() {
	flag.Parse()

	remote, err := net.ResolveUDPAddr("udp", *serverAddr)
	if err != nil {
		log.Fatalf("resolve: %v", err)
	}
	conn, err := net.DialUDP("udp", nil, remote)
	if err != nil {
		log.Fatalf("dial: %v", err)
	}
	defer conn.Close()

	seq := uint32(time.Now().UnixNano()) // any unique per‑process number works
	payload := []byte(*msg)
	if len(payload) > maxPayload {
		log.Fatalf("payload too big (%d > %d)", len(payload), maxPayload)
	}

	packet := make([]byte, 7+len(payload))
	binary.BigEndian.PutUint16(packet[0:2], magic)
	packet[2] = dataMsg
	binary.BigEndian.PutUint32(packet[3:7], seq)
	copy(packet[7:], payload)

	ackBuf := make([]byte, 7)

	for attempt := 1; attempt <= *retries; attempt++ {
		_, err = conn.Write(packet)
		if err != nil {
			log.Fatalf("write: %v", err)
		}
		// Wait for ACK
		conn.SetReadDeadline(time.Now().Add(*timeout))
		n, _, err := conn.ReadFromUDP(ackBuf)
		if err != nil {
			if ne, ok := err.(net.Error); ok && ne.Timeout() {
				log.Printf("attempt %d: timeout, retrying...", attempt)
				continue
			}
			log.Fatalf("read: %v", err)
		}
		if n != 7 || binary.BigEndian.Uint16(ackBuf[0:2]) != magic || ackBuf[2] != ackMsg {
			log.Printf("attempt %d: malformed ACK, retrying...", attempt)
			continue
		}
		ackSeq := binary.BigEndian.Uint32(ackBuf[3:7])
		if ackSeq != seq {
			log.Printf("attempt %d: ACK for wrong seq (%d), retrying...", attempt, ackSeq)
			continue
		}
		// Success!
		fmt.Printf("Server ACKed seq=%d after %d attempt(s)\n", seq, attempt)
		return
	}
	log.Fatalf("exhausted %d attempts without ACK", *retries)
}
```

### How the client works

1. **Pick a unique sequence number** – here we just use the current nanosecond timestamp; any monotonically‑increasing per‑client value works.
2. **Build** a DATA packet (`magic | type | seq | payload`).
3. **Send** it and **wait** for an ACK (blocking `ReadFromUDP` with a deadline).
4. If the ACK is missing, malformed, or for a different sequence number, **re‑send** (up to `-r` times).
5. On success the client prints a short confirmation and exits.

