## 4️⃣ SDK Helper – `CognivaultConfig.java`

```java
package com.example.cognivault.config;

import com.cognivault.sdk.auth.OAuth2Client;
import com.cognivault.sdk.auth.TokenProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * Configures a reusable {@link TokenProvider} that obtains an OAuth‑2 access token
 * using the client‑credentials flow. The provider caches the token until it expires.
 */
@Configuration
public class CognivaultConfig {

    @Value("${cognivault.base-url}")
    private String baseUrl;

    @Value("${cognivault.client-id}")
    private String clientId;

    @Value("${cognivault.client-secret}")
    private String clientSecret;

    @Value("${cognivault.token-endpoint}")
    private String tokenEndpoint;

    @Value("${cognivault.scopes}")
    private String scopes;   // comma‑separated list

    @Bean
    public TokenProvider cognivaultTokenProvider() {
        OAuth2Client client = new OAuth2Client.Builder()
                .baseUrl(baseUrl)
                .tokenEndpoint(tokenEndpoint)
                .clientId(clientId)
                .clientSecret(clientSecret)
                .scopes(scopes.split(","))
                .build();

        // The SDK handles token caching, refresh, and thread‑safety.
        return client.getTokenProvider();
    }
}
```

*If you don’t have the SDK, replace the bean with a simple `RestTemplate` that posts to the token endpoint and caches the JWT yourself.*

