Below is a **self‑contained** C++ program that compiles cleanly with the GCC/Clang option `-fconstant‑time`.  
The flag tells the compiler to emit *branch‑free* (i.e. timing‑invariant) code for any conditional constructs it can transform, which is exactly what we need for cryptographic‑style routines.

```cpp
// ct_example.cpp
// Compile with:  g++ -O2 -fconstant-time -std=c++20 ct_example.cpp -o ct_example
//                clang++ -O2 -fconstant-time -std=c++20 ct_example.cpp -o ct_example

#include <cstddef>
#include <cstdint>
#include <iostream>

/* -------------------------------------------------------------
 * Constant‑time equality test for two byte buffers.
 *
 * Returns 1 if the buffers are identical, 0 otherwise.
 * No data‑dependent branches or memory accesses are used.
 * ------------------------------------------------------------- */
int ct_memcmp(const uint8_t *a, const uint8_t *b, std::size_t len)
{
    uint8_t diff = 0;

    // The loop itself is data‑independent; the body only uses
    // bitwise operations, which the compiler can keep branch‑free.
    for (std::size_t i = 0; i < len; ++i) {
        diff |= a[i] ^ b[i];
    }

    /*  At this point:
     *      diff == 0  → buffers are equal
     *      diff != 0  → at least one byte differs
     *
     *  The following expression converts the result to 0/1 without a branch:
     *
     *      (diff - 1) >> 8   yields 0xFF…FF when diff == 0,
     *                        0x00…00 when diff != 0.
     *
     *  Masking with 1 gives the final 0/1 answer.
     */
    return static_cast<int>((1 & ((diff - 1) >> 8)));
}

/* -------------------------------------------------------------
 * Constant‑time conditional select.
 *
 * `mask` must be either 0xFFFFFFFF (all bits 1) or 0x00000000 (all bits 0).
 * The function returns `a` when mask == 0xFFFFFFFF, otherwise `b`.
 * ------------------------------------------------------------- */
uint32_t ct_select(uint32_t mask, uint32_t a, uint32_t b)
{
    // (mask & a) | (~mask & b) is a classic branch‑free mux.
    return (mask & a) | (~mask & b);
}

/* -------------------------------------------------------------
 * Demo driver
 * ------------------------------------------------------------- */
int main()
{
    // Two test buffers – they differ only in the last byte.
    uint8_t buf1[5] = {0xDE, 0xAD, 0xBE, 0xEF, 0x01};
    uint8_t buf2[5] = {0xDE, 0xAD, 0xBE, 0xEF, 0x02};

    // Constant‑time equality test
    int eq12 = ct_memcmp(buf1, buf2, sizeof(buf1));
    int eq11 = ct_memcmp(buf1, buf1, sizeof(buf1));

    std::cout << "buf1 vs buf2 : " << eq12 << " (expected 0)\n";
    std::cout << "buf1 vs buf1 : " << eq11 << " (expected 1)\n";

    // Constant‑time select demo
    uint32_t a = 0xAAAAAAAA;
    uint32_t b = 0x55555555;

