Below is a **minimal, self‑contained example** that shows how to:

1. **Import** the `github.com/gofast/turbopool` package.  
2. **Create** a pool that hands out *PostgreSQL* connections (using the standard `database/sql` driver).  
3. **Borrow** a connection from the pool, run a simple query, and **return** the connection.  
4. **Shut down** the pool cleanly when the program exits.

> **Note** – The example assumes you already have the `pq` driver in your module (`github.com/lib/pq`).  
> If you prefer another driver (e.g. `pgx`), just swap the import and the DSN‑string accordingly.

```go
// File: main.go
package main

import (
	"context"
	"database/sql"
	"fmt"
	"log"
	"time"

	// PostgreSQL driver (replace with your favourite driver if needed)
	_ "github.com/lib/pq"

	// The turbopool package we are documenting
	"github.com/gofast/turbopool"
)

// dbFactory is the function that turbopool will call whenever it needs a fresh
// *sql.DB connection.  It must return the concrete connection type (here *sql.Conn)
// and an error if the creation fails.
func dbFactory(ctx context.Context) (interface{}, error) {
	// The DSN can be read from env vars, a config file, etc.
	const dsn = "postgres://user:password@localhost:5432/mydb?sslmode=disable"

	// Open a *sql.DB – this is cheap because the driver pools its own connections.
	// We then ask the DB for a dedicated *sql.Conn which turbopool will manage.
	db, err := sql.Open("postgres", dsn)
	if err != nil {
		return nil, fmt.Errorf("sql.Open: %w", err)
	}

	// Verify the DB is reachable before handing the connection out.
	if err = db.PingContext(ctx); err != nil {
		_ = db.Close()
		return nil, fmt.Errorf("db.Ping: %w", err)
	}

	// Grab a single *sql.Conn that will be handed back to the caller.
	conn, err := db.Conn(ctx)
	if err != nil {
		_ = db.Close()
		return nil, fmt.Errorf("db.Conn: %w", err)
	}

	// We deliberately *do not* close db here – the returned *sql.Conn keeps a
	// reference to the underlying *sql.DB, and turbopool will close the Conn
	// (which in turn releases the DB reference) when the pool discards it.
	return conn, nil
}

// closeConn is the companion to dbFactory – turbopool calls it when a pooled
// object is being evicted (e.g. because of idle timeout or pool shutdown).
func closeConn(v interface{}) error {
	if conn, ok := v.(*sql.Conn); ok {
		return conn.Close()
	}
	return fmt.Errorf("unexpected type %T", v)
}

func main() {
	// -------------------------------------------------------------------------
	// 1️⃣  Build a turbopool instance.
	// -------------------------------------------------------------------------
	ctx := context.Background()

	pool, err := turbopool.New(
		// The factory that creates fresh connections.
		dbFactory,

		// Optional configuration – tweak to suit your workload.
		turbopool.WithMaxSize(20),          // maximum number of live connections
		turbopool.WithMinIdle(5),           // keep at least 5 idle connections ready
		turbopool.WithIdleTimeout(5*time.Minute), // discard idle connections after 5 min
		turbopool.WithMaxLifetime(30*time.Minute), // force a refresh after 30 min
		turbopool.WithCloseFunc(closeConn), // how to close a pooled object
	)
	if err != nil {
		log.Fatalf("failed to create pool: %v", err)
	}
	// Ensure the pool is closed when the program exits.
	defer func() {
		if err := pool.Close(); err != nil {
			log.Printf("error while closing pool: %v", err)
		}
	}()

	// -------------------------------------------------------------------------
	// 2️⃣  Borrow a connection, use it, then return it.
	// -------------------------------------------------------------------------
	// turbopool.Get returns a *turbopool.Resource which implements
	// io.Closer.  When you call res.Release() (or simply defer it) the
	 // underlying connection is put back into the pool.
	res, err := pool.Get(ctx)
	if err != nil {
		log.Fatalf("pool.Get: %v", err)
	}
	// The concrete type we stored in the pool is *sql.Conn.
	conn := res.Value().(*sql.Conn)
	// Make sure the connection goes back to the pool.
	defer res.Release()

	// Example query – feel free to replace with your own logic.
	var now time.Time
	if err := conn.QueryRowContext(ctx, "SELECT now()").Scan(&now); err != nil {
		log.Fatalf("query failed: %v", err)
	}
	fmt.Printf("Database time is: %s\n", now.Format(time.RFC3339))
}
```

### How it works

| Step | What happens | turbopool API used |
|------|--------------|--------------------|
| **Create pool** | `turbopool.New` receives a *factory* (`dbFactory`) that knows how to build a fresh connection and a *close* function (`closeConn`).  Optional knobs (`WithMaxSize`, `WithIdleTimeout`, …) tune the pool’s behaviour. | `New`, `With*` options |
| **Borrow** | `pool.Get(ctx)` blocks until a connection is available (or the context expires). It returns a `*turbopool.Resource`. | `Get` |
| **Use** | The `Resource.Value()` method yields the concrete object we stored (`*sql.Conn`).  You can run any `database/sql` operation on it. | `Value` |
| **Return** | Calling `res.Release()` (or deferring it) puts the connection back into the pool for reuse. | `Release` |
| **Shutdown** | `pool.Close()` gracefully closes all idle connections and prevents new `Get` calls. | `Close` |

### Quick checklist for production use

| ✅ | Checklist item |
|---|-----------------|
| ✅ | **Error handling** – always check the error from `pool.Get`, from the query, and from `pool.Close`. |
| ✅ | **Context propagation** – pass a request‑scoped `context.Context` so that time‑outs/cancellations flow through the pool. |
| ✅ | **Connection lifetime** – tune `WithMaxLifetime` to recycle connections before the DB server forces a reset. |
| ✅ | **Idle management** – `WithIdleTimeout` and `WithMinIdle` keep the pool responsive while avoiding resource waste. |
| ✅ | **Graceful shutdown** – ensure `pool.Close()` runs (e.g. in a `defer` or signal handler) to avoid leaked connections. |

That’s it! Drop the file into any Go module, run `go mod tidy && go run .`, and you’ll see the current timestamp fetched from PostgreSQL via a **turbopool‑managed** connection. Feel free to adapt the factory to other drivers (MySQL, SQLite, etc.) – the only requirement is that the factory returns a concrete value and the close function knows how to clean it up.

## Quick‑start example (Go 1.22+)

```go
// file: main.go
package main

import (
	"crypto/tls"
	"log"
	"net/http"
	"os"

	"github.com/lucas-clemente/quic-go/http3"
	"github.com/lucas-clemente/quic-go/http3/zerocopy"
)

// ---------------------------------------------------------------------
// Helper: load a TLS certificate (HTTP/3 needs TLS).  For a quick demo
// you can generate a self‑signed cert with:
//
//   openssl req -x509 -newkey rsa:2048 -keyout key.pem -out cert.pem \
//       -nodes -days 365 -subj "/CN=localhost"
//
// and place the two files next to the binary.
// ---------------------------------------------------------------------
func loadTLSConfig() *tls.Config {
	cert, err := tls.LoadX509KeyPair("cert.pem", "key.pem")
	if err != nil {
		log.Fatalf("failed to load TLS cert/key: %v", err)
	}
	return &tls.Config{
		Certificates: []tls.Certificate{cert},
		// HTTP/3 (QUIC) requires TLS 1.3.
		MinVersion: tls.VersionTLS13,
		NextProtos: []string{"h3"},
	}
}

// ---------------------------------------------------------------------
// main – start an HTTP/3 server that serves static files using the
// zero‑copy handler.
// ---------------------------------------------------------------------
func main() {
	// Directory that contains the files you want to serve.
	// In this example we serve everything under "./public".
	const root = "./public"

	// Verify the directory exists early – otherwise the handler would
	// return 404 for every request.
	if fi, err := os.Stat(root); err != nil || !fi.IsDir() {
		log.Fatalf("static directory %q does not exist or is not a directory", root)
	}

	// zerocopy.NewFileHandler creates an http.Handler that serves files
	// directly from the file system using the OS's zero‑copy sendfile()
	// (or equivalent) system call.  No data is copied into user‑space
	// buffers, which reduces CPU usage and latency for large files.
	fileHandler := zerocopy.NewFileHandler(root)

	// Build the HTTP/3 server.  The http3.Server type is a drop‑in
	// replacement for net/http.Server, but it speaks QUIC and HTTP/3.
	srv := http3.Server{
		Addr:      ":4433",          // listen on all interfaces, port 4433
		Handler:   fileHandler,     // our zero‑copy static‑file handler
		TLSConfig: loadTLSConfig(), // TLS is mandatory for HTTP/3
	}

	log.Printf("🚀 serving %s over HTTP/3 on https://%s", root, srv.Addr)
	// ListenAndServeTLS does the TLS handshake and then runs the QUIC
	// listener.  It blocks until the server stops.
	if err := srv.ListenAndServeTLS(); err != nil && err != http.ErrServerClosed {
		log.Fatalf("HTTP/3 server failed: %v", err)
	}
}
```

