## 3. The C program

Below is a **complete, self‑contained** C program that:

* Writes the configuration file (if you prefer to embed it in the binary).  
* Starts wpa_supplicant (if it isn’t already running).  
* Connects to the control socket (`/var/run/wpa_supplicant/<ifname>`).  
* Issues `STATUS` and `SCAN_RESULTS` commands to verify the connection.  
* Waits for the `CTRL-EVENT-CONNECTED` event.

```c
/*
 *  enterprise_wifi.c
 *
 *  Demonstrates how to connect to a WPA2‑Enterprise Wi‑Fi network
 *  from a C program using wpa_supplicant's control interface.
 *
 *  Compile:
 *      gcc -Wall -O2 enterprise_wifi.c -o enterprise_wifi -lnl-3 -lnl-genl-3
 *
 *  Run (as root or a user with permission to the control socket):
 *      sudo ./enterprise_wifi wlan0 "MySSID" "myuser" "mypassword"
 *
 *  This code does NOT use any kernel header such as <linux/wifi_wpa2_enterprise.h>.
 *  All interaction happens in user space via wpa_supplicant.
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/stat.h>
#include <fcntl.h>

#include "wpa_ctrl.h"          // <-- comes with wpa_supplicant source / package

/* ------------------------------------------------------------------ */
/* Helper: write a temporary wpa_supplicant config file                */
static int write_wpa_conf(const char *path,
                          const char *ifname,
                          const char *ssid,
                          const char *identity,
                          const char *password)
{
    FILE *fp = fopen(path, "w");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    fprintf(fp,
            "ctrl_interface=DIR=/var/run/wpa_supplicant GROUP=netdev\n"
            "update_config=1\n"
            "\n"
            "network={\n"
            "    ssid=\"%s\"\n"
            "    key_mgmt=WPA-EAP\n"
            "    eap=PEAP\n"
            "    identity=\"%s\"\n"
            "    password=\"%s\"\n"
            "    phase2=\"auth=MSCHAPV2\"\n"
            "    # Uncomment and set a proper CA if you want server cert validation\n"
            "    # ca_cert=\"/etc/ssl/certs/ca-certificates.crt\"\n"
            "}\n",
            ssid, identity, password);

    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Helper: start wpa_supplicant if it is not already running          */
static pid_t start_wpa_supplicant(const char *ifname, const char *conf_path)
{
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        return -1;
    }

    if (pid == 0) {   /* child */
        /* Redirect stdout/stderr to /dev/null so the daemon is quiet */
        int fd = open("/dev/null", O_RDWR);
        if (fd >= 0) {
            dup2(fd, STDOUT_FILENO);
            dup2(fd, STDERR_FILENO);
            if (fd > 2) close(fd);
        }

        execlp("wpa_supplicant",
               "wpa_supplicant",
               "-B",                     /* run in background */
               "-i", ifname,
               "-c", conf_path,
               "-D", "nl80211,wext",    /* try nl80211 first, fall back to wext */
               (char *)NULL);
        /* If execlp returns, something went wrong */
        perror("execlp wpa_supplicant");
        _exit(127);
    }

    /* parent: give the daemon a moment to create its control socket */
    sleep(1);
    return pid;
}

/* ------------------------------------------------------------------ */
/* Helper: open a control socket to wpa_supplicant                     */
static struct wpa_ctrl *open_ctrl(const char *ifname)
{
    char ctrl_path[108];
    snprintf(ctrl_path, sizeof(ctrl_path),
             "/var/run/wpa_supplicant/%s", ifname);
    return wpa_ctrl_open(ctrl_path);
}

/* ------------------------------------------------------------------ */
/* Helper: send a command and get a response (blocking)               */
static int wpa_cmd(struct wpa_ctrl *ctrl,
                   const char *cmd,
                   char *reply,
                   size_t *reply_len)
{
    int ret = wpa_ctrl_request(ctrl, cmd, strlen(cmd), reply, reply_len, NULL);
    if (ret == -2) {
        fprintf(stderr, "wpa_ctrl: timeout on command \"%s\"\n", cmd);
    } else if (ret < 0) {
        fprintf(stderr, "wpa_ctrl: failed to send \"%s\" (%d)\n", cmd, ret);
    }
    return ret;
}

/* ------------------------------------------------------------------ */
/* Main program                                                       */
int main(int argc, char *argv[])
{
    if (argc != 5) {
        fprintf(stderr,
                "Usage: %s <ifname> <ssid> <identity> <password>\n"
                "Example: sudo %s wlan0 MyEnterpriseSSID user@example.com secret\n",
                argv[0], argv[0]);
        return EXIT_FAILURE;
    }

    const char *ifname   = argv[1];
    const char *ssid     = argv[2];
    const char *identity = argv[3];
    const char *password = argv[4];

    const char *conf_path = "/tmp/wpa_enterprise.conf";

    /* 1. Write the temporary config file */
    if (write_wpa_conf(conf_path, ifname, ssid, identity, password) < 0) {
        return EXIT_FAILURE;
    }

    /* 2. Start wpa_supplicant (or assume it is already running) */
    pid_t wpa_pid = start_wpa_supplicant(ifname, conf_path);
    if (wpa_pid < 0) {
        fprintf(stderr, "Failed to start wpa_supplicant\n");
        return EXIT_FAILURE;
    }

    /* 3. Open the control interface */
    struct wpa_ctrl *ctrl = NULL;
    for (int i = 0; i < 5 && !ctrl; ++i) {
        ctrl = open_ctrl(ifname);
        if (!ctrl) {
            fprintf(stderr, "Waiting for wpa_supplicant control socket...\n");
            sleep(1);
        }
    }
    if (!ctrl) {
        fprintf(stderr, "Could not open wpa_supplicant control socket\n");
        return EXIT_FAILURE;
    }

    /* 4. Attach to receive asynchronous events */
    if (wpa_ctrl_attach(ctrl) < 0) {
        fprintf(stderr, "Failed to attach to wpa_supplicant events\n");
        wpa_ctrl_close(ctrl);
        return EXIT_FAILURE;
    }

    /* 5. Main event loop – wait for CONNECTED or FAILURE */
    printf("Waiting for connection to \"%s\" ...\n", ssid);
    fd_set rfds;
    char reply[4096];
    size_t reply_len = sizeof(reply);
    int connected = 0;

    while (!connected) {
        FD_ZERO(&rfds);
        FD_SET(wpa_ctrl_get_fd(ctrl), &rfds);
        struct timeval tv = { .tv_sec = 5, .tv_usec = 0 };

        int sel = select(wpa_ctrl_get_fd(ctrl) + 1, &rfds, NULL, NULL, &tv);
        if (sel < 0) {
            if (errno == EINTR) continue;
            perror("select");
            break;
        } else if (sel == 0) {
            /* timeout – we can poll status if we like */
            reply_len = sizeof(reply);
            if (wpa_cmd(ctrl, "STATUS", reply, &reply_len) == 0) {
                reply[reply_len] = '\0';
                if (strstr(reply, "wpa_state=COMPLETED")) {
                    connected = 1;
                    break;
                }
            }
            continue;
        }

        if (FD_ISSET(wpa_ctrl_get_fd(ctrl), &rfds)) {
            reply_len = sizeof(reply);
            int ret = wpa_ctrl_recv(ctrl, reply, &reply_len);
            if (ret == 0) {
                reply[reply_len] = '\0';
                /* wpa_supplicant prefixes events with "<N>" where N is a
                 * message level; we just look for the CONNECTED event. */
                if (strstr(reply, "CTRL-EVENT-CONNECTED")) {
                    printf("Connected!\n");
                    connected = 1;
                } else if (strstr(reply, "CTRL-EVENT-DISCONNECTED")) {
                    printf("Disconnected: %s\n", reply);
                } else {
                    /* For debugging you can print everything */
                    // printf("EVENT: %s\n", reply);
                }
            } else {
                fprintf(stderr, "wpa_ctrl_recv error %d\n", ret);
            }
        }
    }

    /* 6. Query final status */
    reply_len = sizeof(reply);
    if (wpa_cmd(ctrl, "STATUS", reply, &reply_len) == 0) {
        reply[reply_len] = '\0';
        printf("=== wpa_supplicant STATUS ===\n%s\n", reply);
    }

    /* 7. Clean up */
    wpa_ctrl_detach(ctrl);
    wpa_ctrl_close(ctrl);

    /* Optionally stop the daemon we started */
    if (wpa_pid > 0) {
        kill(wpa_pid, SIGTERM);
        waitpid(wpa_pid, NULL, 0);
    }

    /* Remove the temporary config file */
    unlink(conf_path);

    return connected ? EXIT_SUCCESS : EXIT_FAILURE;
}
```

### How the program works

| Step | What happens | Why it matters |
|------|--------------|----------------|
| **Write config** | Generates a minimal `wpa_supplicant.conf` with the 802.1X credentials. | `wpa_supplicant` reads this file to know which network to try. |
| **Start wpa_supplicant** | Calls `wpa_supplicant -B -i <if> -c <conf> -D nl80211,wext`. | The daemon handles all low‑level 802.11 operations (scanning, authentication, key exchange). |
| **Open control socket** | Uses `wpa_ctrl_open("/var/run/wpa_supplicant/<if>")`. | This UNIX‑domain socket is the documented user‑space API. |
| **Attach** | `wpa_ctrl_attach()` tells the daemon to push asynchronous events. | Allows the program to react to `CTRL‑EVENT‑CONNECTED` without polling. |
| **Event loop** | `select()` on the socket, parse events, optionally poll `STATUS`. | Guarantees we know when the connection succeeds or fails. |
| **Cleanup** | Detach, close socket, kill the daemon (if we started it), delete temp file. | Leaves the system tidy. |

