    <groupId>com.example</groupId>
    <artifactId>turbo‑parser‑demo</artifactId>
    <version>1.0.0</version>
    <properties>
        <java.version>11</java.version>   <!-- any Java 8+ works -->
        <javax.json.version>1.1.6</javax.json.version>
    </properties>

    <dependencies>
        <!-- GlassFish (Eclipse) implementation of JSR‑353 (JSON‑P) -->
        <dependency>
            <groupId>org.glassfish</groupId>
            <artifactId>javax.json</artifactId>
            <version>${javax.json.version}</version>
        </dependency>
    </dependencies>

    <build>
        <plugins>
            <!-- Compiler plugin to enforce the Java version -->
            <plugin>
                <groupId>org.apache.maven.plugins</groupId>
                <artifactId>maven-compiler-plugin</artifactId>
                <version>3.11.0</version>
                <configuration>
                    <source>${java.version}</source>
                    <target>${java.version}</target>
                </configuration>
            </plugin>
        </plugins>
    </build>
