export function startReliableWs() {
  const ws = new ReliableWebSocket('ws://localhost:8080', {
    // same options as the Node version
  });

  ws.addEventListener('open', () => {
    console.log('✅ WS opened (reliable)');
    ws.send('Hello from the browser!');
  });

