/* ------------------------------------------------------------
   2️⃣  Import the library
   • CommonJS (Node)      : const { cloneDeep } = require('lodash-turbo');
   • ES‑Modules (modern)  : import { cloneDeep } from 'lodash-turbo';
------------------------------------------------------------ */
import { cloneDeep } from 'lodash-turbo';

// ------------------------------------------------------------
