    contacts: {
      email: 'ada@example.com',
      phones: ['+1‑555‑1234', '+1‑555‑5678'],
    },
  },
  roles: ['admin', 'editor'],
};

// ------------------------------------------------------------
// 4️⃣  Deep‑clone it
// ------------------------------------------------------------
const userCopy = cloneDeep(user);

// ------------------------------------------------------------
// 5️⃣  Prove the clone is independent
// ------------------------------------------------------------
userCopy.profile.name = 'Grace Hopper';
userCopy.profile.contacts.phones.push('+1‑555‑9999');

console.log('Original:', user.profile.name);               // → "Ada Lovelace"
console.log('Clone   :', userCopy.profile.name);           // → "Grace Hopper"

console.log('Original phones:', user.profile.contacts.phones);
// → [ '+1‑555‑1234', '+1‑555‑5678' ]

console.log('Clone phones   :', userCopy.profile.contacts.phones);
