```cpp
// format_simd_demo.cpp
// Compile with:  g++ -std=c++23 -O2 -march=native -fexperimental-format format_simd_demo.cpp
//                clang++ -std=c++23 -O2 -march=native -fexperimental-format format_simd_demo.cpp

#include <format>          // std::format_to_simd, std::format_context
#include <vector>
#include <string>
#include <span>
#include <iostream>

int main()
{
    // -----------------------------------------------------------------
    // 1️⃣  Build a big collection of numbers we want to format.
    // -----------------------------------------------------------------
    constexpr std::size_t N = 1'000'000;          // 1 million values
    std::vector<int> numbers(N);
    for (std::size_t i = 0; i < N; ++i)
        numbers[i] = static_cast<int>(i);        // just 0,1,2,… for demo

    // -----------------------------------------------------------------
    // 2️⃣  Allocate a destination buffer that is *big enough*.
    // -----------------------------------------------------------------
