	"golang.org/x/exp/arena"
)

func main() {
	// Create one arena that lives for the whole program.
	a := arena.NewArena()
	defer a.Free()

	// ---- First batch -------------------------------------------------
	p1 := a.New(Point{}) // allocate inside arena
	// … use p1 …

	// ---- Reset -------------------------------------------------------
	a.Reset() // all previous arena allocations are now invalid

	// ---- Second batch ------------------------------------------------
	p2 := a.New(Point{}) // re‑uses the same underlying memory
	// … use p2 …
}
```

