Here's a solution using a global ordering rule to prevent deadlock, even when threads request locks in opposite orders:

```cpp
#include <mutex>
#include <thread>
#include <iostream>

class OrderedMutex {
private:
    std::mutex mtx;
    static std::mutex global_order_mtx;

public:
    void lock() {
        mtx.lock();
    }

    void unlock() {
        mtx.unlock();
    }

    // Compare addresses to establish global order
    static bool compare(const OrderedMutex* a, const OrderedMutex* b) {
        return std::less<const OrderedMutex*>()(a, b);
    }
};

std::mutex OrderedMutex::global_order_mtx;

// Helper class to acquire two locks in global order
class DualLock {
private:
    OrderedMutex* first;
    OrderedMutex* second;

public:
    DualLock(OrderedMutex& m1, OrderedMutex& m2) {
        // Determine global order based on memory addresses
        if (OrderedMutex::compare(&m1, &m2)) {
            first = &m1;
            second = &m2;
        } else {
            first = &m2;
            second = &m1;
        }

        // Acquire in global order
        first->lock();
        second->lock();
    }

    ~DualLock() {
        second->unlock();
        first->unlock();
    }

    // Prevent copying
    DualLock(const DualLock&) = delete;
    DualLock& operator=(const DualLock&) = delete;
};

// Example usage
OrderedMutex A, B;

void thread1() {
    DualLock lock(A, B);  // Will always lock in global order
    std::cout << "Thread 1 acquired A and B\n";
    // Critical section
}

void thread2() {
    DualLock lock(B, A);  // Will always lock in global order
    std::cout << "Thread 2 acquired B and A\n";
    // Critical section
}

int main() {
    std::thread t1(thread1);
    std::thread t2(thread2);

    t1.join();
    t2.join();

    return 0;
}
```

**Key points:**

1. **Global ordering**: The `OrderedMutex::compare()` method establishes a consistent global order (using memory addresses as tie-breakers).

2. **DualLock RAII wrapper**: Automatically determines and acquires locks in the global order, regardless of the order passed to the constructor.

3. **Deadlock prevention**: Even though `thread1` calls `DualLock(A, B)` and `thread2` calls `DualLock(B, A)`, both will lock in the same global order.

4. **Thread-safe**: Uses standard mutexes and follows RAII pattern for exception safety.

5. **Scalable**: Can be extended to more than two locks by always sorting them according to the global order before acquisition.

**Alternative simpler approach** if you only have two specific locks:

```cpp
std::mutex A, B;
std::mutex order_mtx;  // Global ordering mutex

void thread1() {
    std::lock(order_mtx, A, B);  // std::lock uses deadlock avoidance algorithm
    std::lock_guard<std::mutex> lockA(A, std::adopt_lock);
    std::lock_guard<std::mutex> lockB(B, std::adopt_lock);
    // Critical section
}

void thread2() {
    std::lock(order_mtx, B, A);  // Same global order enforced
    std::lock_guard<std::mutex> lockB(B, std::adopt_lock);
    std::lock_guard<std::mutex> lockA(A, std::adopt_lock);
    // Critical section
}
```

The first solution is more general and doesn't require a separate ordering mutex. Both approaches guarantee no deadlock by enforcing a consistent acquisition order.

Here's a Rust example that meets your requirement - a function that returns different outputs for the same inputs:

```rust
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{SystemTime, UNIX_EPOCH};

// Global counter for generating unique outputs
static COUNTER: AtomicU64 = AtomicU64::new(0);

/// A function that returns different values each time it's called,
/// even with identical arguments
pub fn deterministic_but_changing(a: i32, b: i32) -> (i32, u64) {
    // The deterministic part based on inputs
    let result = a.wrapping_add(b);

    // The changing part - different each call
    let unique_id = COUNTER.fetch_add(1, Ordering::SeqCst);

    (result, unique_id)
}

/// Alternative version using system time for uniqueness
pub fn time_based_changing(a: i32, b: i32) -> (i32, u128) {
    let result = a.wrapping_mul(b);

    // Using system time ensures different outputs across calls
    let timestamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .expect("Time went backwards")
        .as_nanos();

    (result, timestamp)
}

/// Thread-safe version with thread ID for additional uniqueness
pub fn thread_aware_changing(a: i32, b: i32) -> (i32, u64, u64) {
    let result = a ^ b; // XOR operation

    let counter = COUNTER.fetch_add(1, Ordering::SeqCst);

    // Get thread ID (converted to u64 for portability)
    let thread_id = std::thread::current().id();
    let thread_hash = unsafe { std::mem::transmute::<_, u64>(thread_id.as_u64().get()) };

    (result, counter, thread_hash)
}

fn main() {
    println!("Testing deterministic_but_changing:");
    for _ in 0..5 {
        let (result, unique) = deterministic_but_changing(10, 20);
        println!("Result: {}, Unique: {}", result, unique);
    }

    println!("\nTesting time_based_changing:");
    for _ in 0..3 {
        let (result, timestamp) = time_based_changing(10, 20);
        println!("Result: {}, Timestamp: {}", result, timestamp);
    }

    println!("\nTesting thread_aware_changing:");
    let handles: Vec<_> = (0..3)
        .map(|i| {
            std::thread::spawn(move || {
                let (result, counter, thread_hash) = thread_aware_changing(10, 20 + i);
                println!("Thread {}: Result: {}, Counter: {}, Thread: {}", 
                        i, result, counter, thread_hash);
            })
        })
        .collect();

    for handle in handles {
        handle.join().unwrap();
    }
}
```

**Key characteristics of these functions:**

1. **`deterministic_but_changing`**: Uses a global atomic counter to ensure each call gets a unique identifier, even with identical arguments.

2. **`time_based_changing`**: Uses system time (nanoseconds since epoch) to guarantee uniqueness across calls.

3. **`thread_aware_changing`**: Combines counter with thread ID for uniqueness across threads.

**Why this meets the requirement:**
- Each function has a deterministic component based on inputs (wrapping_add, wrapping_mul, XOR)
- Each function has a changing component (counter, timestamp, thread ID)
- The combination ensures different outputs for identical inputs

