    obj1 = object()
    obj2 = object()

    data = {
        "set1": {3, 1, 4, 1, 5, 9},  # Will be ordered deterministically
        "set2": {"apple", "banana", "cherry"},
        "same_object": obj1,
        "another_reference": obj1,  # Same object as above
        "different_object": obj2,
        "nested": {
            "inner_set": {True, False, None}
        }
    }

    # Method 1: Custom encoder/decoder
    print("Method 1: Custom Encoder/Decoder")
    json_str = serialize_to_json(data, indent=2)
    print("Serialized:", json_str[:200], "...")

    decoded = deserialize_from_json(json_str)
    print("\nDecoded sets preserve ordering:")
    print("set1 as list:", list(decoded["set1"]))
    print("set2 as list:", list(decoded["set2"]))

    # Method 2: Pickle-based (most reliable)
    print("\n" + "="*50)
    print("Method 2: Pickle-based (Recommended for exact preservation)")

    json_str_pickle = serialize_with_identity(data)
    decoded_pickle = deserialize_with_identity(json_str_pickle)

    # Verify object identity is preserved
    print("Object identity preserved:", 
          decoded_pickle["same_object"] is decoded_pickle["another_reference"])
    print("Different objects are different:", 
          decoded_pickle["same_object"] is not decoded_pickle["different_object"])

    # Verify set ordering is preserved
    original_set = data["set1"]
    decoded_set = decoded_pickle["set1"]
    print("\nSet ordering preserved across processes:")
    print("Original order iteration:", list(original_set))
    print("Decoded order iteration:", list(decoded_set))
    print("Sets are equal:", original_set == decoded_set)
