### 1. Basic Structures and Message Types

```cpp
#include <iostream>
#include <vector>
#include <string>
#include <map>
#include <set>
#include <queue>
#include <memory>
#include <mutex>
#include <thread>
#include <chrono>
#include <random>
#include <functional>
#include <sstream>
#include <iomanip>
#include <openssl/sha.h>

enum MessageType {
    PRE_PREPARE,
    PREPARE,
    COMMIT,
    REPLY
};

struct Message {
    MessageType type;
    int view_number;
    int sequence_number;
    std::string digest;
    int sender_id;
    std::string content;
    std::string signature; // In production, use proper cryptographic signatures

    std::string serialize() const {
        return std::to_string(static_cast<int>(type)) + "|" +
               std::to_string(view_number) + "|" +
               std::to_string(sequence_number) + "|" +
               digest + "|" +
               std::to_string(sender_id) + "|" +
               content;
    }

    static Message deserialize(const std::string& str) {
        Message msg;
        std::istringstream iss(str);
        std::string token;

        std::getline(iss, token, '|');
        msg.type = static_cast<MessageType>(std::stoi(token));

        std::getline(iss, token, '|');
        msg.view_number = std::stoi(token);

        std::getline(iss, token, '|');
        msg.sequence_number = std::stoi(token);

        std::getline(iss, msg.digest, '|');
        std::getline(iss, token, '|');
        msg.sender_id = std::stoi(token);

        std::getline(iss, msg.content);

        return msg;
    }
};

class Cryptographic {
public:
    static std::string sha256(const std::string& str) {
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256_CTX sha256;
        SHA256_Init(&sha256);
        SHA256_Update(&sha256, str.c_str(), str.size());
        SHA256_Final(hash, &sha256);

        std::stringstream ss;
        for(int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
            ss << std::hex << std::setw(2) << std::setfill('0') << (int)hash[i];
        }
        return ss.str();
    }
};
