### 2. Node Class Implementation

```cpp
class PBFTNode {
private:
    int node_id;
    int total_nodes;
    int f; // Maximum faulty nodes
    int current_view;
    int last_executed;

    // Message logs
    std::map<int, std::map<std::string, std::set<int>>> prepare_certificates;
    std::map<int, std::map<std::string, std::set<int>>> commit_certificates;
    std::map<int, Message> pre_prepare_messages;

    // Request queue
    std::queue<std::string> request_queue;
    std::map<int, bool> executed_requests;

    // Network simulation
    std::function<void(int, const Message&)> send_message_callback;

    std::mutex mtx;

public:
    PBFTNode(int id, int n, std::function<void(int, const Message&)> send_callback)
        : node_id(id), total_nodes(n), f((n - 1) / 3), 
          current_view(0), last_executed(0),
          send_message_callback(send_callback) {
        std::cout << "Node " << node_id << " initialized. f = " << f 
                  << ", quorum = " << (2*f + 1) << std::endl;
    }

    void receive_request(const std::string& request) {
        std::lock_guard<std::mutex> lock(mtx);
        request_queue.push(request);
        process_requests();
    }

    void receive_message(const Message& msg) {
        std::lock_guard<std::mutex> lock(mtx);

        switch(msg.type) {
            case PRE_PREPARE:
                handle_pre_prepare(msg);
                break;
            case PREPARE:
                handle_prepare(msg);
                break;
            case COMMIT:
                handle_commit(msg);
                break;
            case REPLY:
                // Client would handle this
                break;
        }
    }

private:
    void process_requests() {
        while (!request_queue.empty()) {
            std::string request = request_queue.front();
            request_queue.pop();

            int sequence_number = last_executed + 1;
            std::string digest = Cryptographic::sha256(request);

            // As primary (node 0 in current view)
            if (node_id == (current_view % total_nodes)) {
                Message pre_prepare_msg = {
                    PRE_PREPARE,
                    current_view,
                    sequence_number,
                    digest,
                    node_id,
                    request
                };

                pre_prepare_messages[sequence_number] = pre_prepare_msg;

                // Broadcast PRE-PREPARE
                broadcast_message(pre_prepare_msg);
            }
        }
    }

    void handle_pre_prepare(const Message& msg) {
        // Verify message
        if (msg.view_number != current_view) return;
        if (msg.sender_id != (current_view % total_nodes)) return;

        std::string computed_digest = Cryptographic::sha256(msg.content);
        if (computed_digest != msg.digest) return;

        // Store pre-prepare
        pre_prepare_messages[msg.sequence_number] = msg;

        // Send PREPARE
        Message prepare_msg = {
            PREPARE,
            msg.view_number,
            msg.sequence_number,
            msg.digest,
            node_id,
            ""
        };

        send_message_callback(-1, prepare_msg); // Broadcast
    }

    void handle_prepare(const Message& msg) {
        std::string key = std::to_string(msg.view_number) + ":" + 
                         std::to_string(msg.sequence_number) + ":" + 
                         msg.digest;

        prepare_certificates[msg.sequence_number][key].insert(msg.sender_id);

        // Check if we have 2f prepares (including our own if we're primary)
        if (prepare_certificates[msg.sequence_number][key].size() >= 2*f) {
            // Send COMMIT
            Message commit_msg = {
                COMMIT,
                msg.view_number,
                msg.sequence_number,
                msg.digest,
                node_id,
                ""
            };

            send_message_callback(-1, commit_msg);
        }
    }

    void handle_commit(const Message& msg) {
        std::string key = std::to_string(msg.view_number) + ":" + 
                         std::to_string(msg.sequence_number) + ":" + 
                         msg.digest;

        commit_certificates[msg.sequence_number][key].insert(msg.sender_id);

        // Check if we have 2f+1 commits
        if (commit_certificates[msg.sequence_number][key].size() >= 2*f + 1) {
            execute_request(msg.sequence_number, msg.digest);
        }
    }

    void execute_request(int sequence_number, const std::string& digest) {
        if (executed_requests[sequence_number]) return;

        // Find the corresponding request
        auto it = pre_prepare_messages.find(sequence_number);
        if (it != pre_prepare_messages.end() && 
            Cryptographic::sha256(it->second.content) == digest) {

            std::cout << "Node " << node_id << " executing request " 
                      << sequence_number << ": " << it->second.content << std::endl;

            executed_requests[sequence_number] = true;
            last_executed = sequence_number;

            // Send reply to client (simulated)
            Message reply_msg = {
                REPLY,
                current_view,
                sequence_number,
                digest,
                node_id,
                "EXECUTED"
            };

            // In real implementation, send to client
            std::cout << "Node " << node_id << " sending REPLY for request " 
                      << sequence_number << std::endl;
        }
    }

    void broadcast_message(const Message& msg) {
        send_message_callback(-1, msg);
    }
};
```

### 3. Network and System Manager

```cpp
class ByzantineAgreementSystem {
private:
    std::vector<std::unique_ptr<PBFTNode>> nodes;
    std::map<int, std::vector<Message>> message_queues;
    std::mutex mtx;
    bool running;

public:
    ByzantineAgreementSystem(int n) {
        // Create n nodes
        for (int i = 0; i < n; i++) {
            nodes.push_back(std::make_unique<PBFTNode>(
                i, n, 
                [this, i](int target, const Message& msg) {
                    this->send_message(i, target, msg);
                }
            ));
        }
        running = true;
    }

    void send_message(int sender_id, int target_id, const Message& msg) {
        std::lock_guard<std::mutex> lock(mtx);

        if (target_id == -1) { // Broadcast
            for (int i = 0; i < nodes.size(); i++) {
                if (i != sender_id) {
                    // Simulate network delay
                    std::this_thread::sleep_for(std::chrono::milliseconds(10));
                    nodes[i]->receive_message(msg);
                }
            }
        } else if (target_id >= 0 && target_id < nodes.size()) {
            nodes[target_id]->receive_message(msg);
        }
    }

    void submit_request(const std::string& request) {
        std::cout << "\n=== Submitting request: " << request << " ===" << std::endl;

        // Client sends request to all nodes
        for (auto& node : nodes) {
            node->receive_request(request);
        }
    }

    void simulate_byzantine_node(int node_id, const std::string& malicious_request) {
        std::cout << "\n=== Node " << node_id << " acting Byzantine ===" << std::endl;

        // Byzantine node sends conflicting messages
        Message malicious_msg = {
            PRE_PREPARE,
            0, // current view
            999, // sequence number
            Cryptographic::sha256(malicious_request),
            node_id,
            malicious_request
        };

        send_message(node_id, -1, malicious_msg);
    }

    void stop() {
        running = false;
    }
};
