I'll help you implement the **Kundu-Rahman constant-time Dijkstra algorithm** (also known as the "bucket-based" or "dial's" Dijkstra). This is a specialized version of Dijkstra's algorithm that runs in **O(V + E + C)** time where C is the maximum edge weight, making it efficient for graphs with small integer weights.

Here's a complete implementation:

```java
import java.util.*;

public class KunduRahmanDijkstra {

    static class Edge {
        int to;
        int weight;

        Edge(int to, int weight) {
            this.to = to;
            this.weight = weight;
        }
    }

    public static int[] shortestPaths(List<List<Edge>> graph, int source, int maxWeight) {
        int n = graph.size();
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[source] = 0;

        // Create buckets (Dial's implementation)
        // We need maxWeight * (n-1) + 1 buckets in worst case
        int maxDistance = maxWeight * (n - 1);
        List<LinkedList<Integer>> buckets = new ArrayList<>(maxDistance + 1);

        // Initialize buckets
        for (int i = 0; i <= maxDistance; i++) {
            buckets.add(new LinkedList<>());
        }

        // Add source to bucket 0
        buckets.get(0).add(source);

        // Current bucket index
        int currentBucket = 0;

        // Process buckets
        while (currentBucket <= maxDistance) {
            // Skip empty buckets
            if (buckets.get(currentBucket).isEmpty()) {
                currentBucket++;
                continue;
            }

            // Get vertex from current bucket
            int u = buckets.get(currentBucket).removeFirst();

            // If this distance is outdated (we found a better path already)
            if (dist[u] < currentBucket) {
                continue;
            }

            // Relax all edges from u
            for (Edge edge : graph.get(u)) {
                int v = edge.to;
                int newDist = dist[u] + edge.weight;

                if (newDist < dist[v]) {
                    // Remove from old bucket if it was there
                    if (dist[v] != Integer.MAX_VALUE && dist[v] <= maxDistance) {
                        buckets.get(dist[v]).remove((Integer) v);
                    }

                    // Update distance
                    dist[v] = newDist;

                    // Add to new bucket
                    if (newDist <= maxDistance) {
                        buckets.get(newDist).add(v);
                    }
                }
            }
        }

        return dist;
    }

    // Alternative implementation using array of sets (more efficient removal)
    public static int[] shortestPathsOptimized(List<List<Edge>> graph, int source, int maxWeight) {
        int n = graph.size();
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[source] = 0;

        int maxDistance = maxWeight * (n - 1);

        // Using array of HashSets for faster removal
        List<Set<Integer>> buckets = new ArrayList<>(maxDistance + 1);
        for (int i = 0; i <= maxDistance; i++) {
            buckets.add(new HashSet<>());
        }

        buckets.get(0).add(source);
        int currentBucket = 0;
        int processed = 0;

        while (processed < n && currentBucket <= maxDistance) {
            // Skip empty buckets
            if (buckets.get(currentBucket).isEmpty()) {
                currentBucket++;
                continue;
            }

            // Get a vertex from current bucket
            Iterator<Integer> it = buckets.get(currentBucket).iterator();
            int u = it.next();
            it.remove();

            // Skip if outdated
            if (dist[u] != currentBucket) {
                continue;
            }

            processed++;

            // Relax edges
            for (Edge edge : graph.get(u)) {
                int v = edge.to;
                int newDist = dist[u] + edge.weight;

                if (newDist < dist[v]) {
                    // Remove from old bucket
                    if (dist[v] != Integer.MAX_VALUE) {
                        buckets.get(dist[v]).remove(v);
                    }

                    dist[v] = newDist;

                    if (newDist <= maxDistance) {
                        buckets.get(newDist).add(v);
                    }
                }
            }
        }

        return dist;
    }

    // Example usage
    public static void main(String[] args) {
        // Create a graph with 5 vertices
        int n = 5;
        List<List<Edge>> graph = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        // Add edges (directed graph)
        graph.get(0).add(new Edge(1, 2));
        graph.get(0).add(new Edge(2, 4));
        graph.get(1).add(new Edge(2, 1));
        graph.get(1).add(new Edge(3, 7));
        graph.get(2).add(new Edge(3, 3));
        graph.get(2).add(new Edge(4, 5));
        graph.get(3).add(new Edge(4, 2));

        int source = 0;
        int maxWeight = 7; // Maximum edge weight in the graph

