public class OptimizedPetrovMatching {

    public static int[] findMaximumMatching(int[][] graph, int n, int m) {
        int[] matchL = new int[n];
        int[] matchR = new int[m];
        Arrays.fill(matchL, -1);
        Arrays.fill(matchR, -1);

        // Array to track visited vertices during DFS
        int[] visited = new int[m];
        int visitToken = 1;

        // Greedy initialization
        for (int u = 0; u < n; u++) {
            for (int v : graph[u]) {
                if (matchR[v] == -1) {
                    matchL[u] = v;
                    matchR[v] = u;
                    break;
                }
            }
        }

        // Augmentation for bounded degree graphs
        for (int u = 0; u < n; u++) {
            if (matchL[u] == -1) {
                visitToken++;
                if (dfs(u, graph, matchL, matchR, visited, visitToken)) {
                    // Augmentation successful
                }
            }
        }

        return matchL;
    }

    private static boolean dfs(int u, int[][] graph, int[] matchL, int[] matchR, 
                              int[] visited, int token) {
        for (int v : graph[u]) {
            if (visited[v] != token) {
                visited[v] = token;
                if (matchR[v] == -1 || dfs(matchR[v], graph, matchL, matchR, visited, token)) {
                    matchL[u] = v;
                    matchR[v] = u;
                    return true;
                }
            }
        }
        return false;
    }
}
