// Structure to represent a polynomial with coefficients
typedef struct {
    double *coeffs;
    int degree;
} Polynomial;

// Function to create a polynomial
Polynomial* create_polynomial(int degree) {
    Polynomial *poly = (Polynomial*)malloc(sizeof(Polynomial));
    poly->degree = degree;
    poly->coeffs = (double*)calloc(degree + 1, sizeof(double));
    return poly;
}

// Function to free polynomial memory
void free_polynomial(Polynomial *poly) {
    if (poly) {
        free(poly->coeffs);
        free(poly);
    }
}

// Function to perform convolution of two polynomials
Polynomial* convolve(Polynomial *a, Polynomial *b) {
    int result_degree = a->degree + b->degree;
    Polynomial *result = create_polynomial(result_degree);

    for (int i = 0; i <= a->degree; i++) {
        for (int j = 0; j <= b->degree; j++) {
            result->coeffs[i + j] += a->coeffs[i] * b->coeffs[j];
        }
    }

    return result;
}

