    // Always returns a value, never throws
  }

  function parseObject(): { [key: string]: JsonValue } {
    // Implementation returns object or empty object on error
    // Always returns a value, never throws
  }

  // ... similar implementations for other parse functions

  function skipWhitespace(): void {
    while (index < input.length && /\s/.test(input[index])) {
      index++;
    }
  }

  function isDigit(char: string): boolean {
    return char >= '0' && char <= '9';
  }

  const result = parseValue();
  skipWhitespace();

  // If we didn't consume entire input or parsing failed
  if (index < input.length || result === null) {
