import java.util.Map;
import java.util.HashMap;

public class SimpleInterpreter {
    public enum Expr {
        LIT, ADD, SUB, VAR
    }

    public static class AST {
        Expr type;
        int value;
        String varName;
        AST left, right;

        // Constructor for literals
        AST(int val) {
            type = Expr.LIT;
            value = val;
        }

        // Constructor for variables
        AST(String name) {
            type = Expr.VAR;
            varName = name;
        }

        // Constructor for binary operations
        AST(Expr op, AST l, AST r) {
            type = op;
            left = l;
            right = r;
        }
    }

    public static int interpret(AST node, Map<String, Integer> env) {
        switch(node.type) {
            case LIT:
                return node.value;
            case VAR:
                return env.get(node.varName);
            case ADD:
                return interpret(node.left, env) + interpret(node.right, env);
            case SUB:
                return interpret(node.left, env) - interpret(node.right, env);
            default:
                throw new RuntimeException("Unknown expression type");
        }
    }

    public static void main(String[] args) {
        // Example: (x + 5) - 3 where x = 10
        Map<String, Integer> env = new HashMap<>();
        env.put("x", 10);

        AST expr = new AST(Expr.SUB,
                          new AST(Expr.ADD,
                                 new AST("x"),
                                 new AST(5)),
                          new AST(3));

        System.out.println("Result: " + interpret(expr, env)); // Should print 12
    }
}
```

