import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.Random;
import java.util.Map;
import java.util.HashMap;

public class InterpreterVerification {

    // A "compiler" that generates Java code
    public static String compileToJava(AST ast) {
        return compileExpr(ast);
    }

    private static String compileExpr(AST node) {
        switch(node.type) {
            case LIT: return Integer.toString(node.value);
            case VAR: return "env.get(\"" + node.varName + "\")";
            case ADD: return "(" + compileExpr(node.left) + " + " + compileExpr(node.right) + ")";
            case SUB: return "(" + compileExpr(node.left) + " - " + compileExpr(node.right) + ")";
            default: throw new RuntimeException("Unknown node type");
        }
    }

    @Test
    void testSemanticPreservation() {
        Random rand = new Random(42);

        for (int i = 0; i < 1000; i++) {
            // Generate random AST
            AST ast = generateRandomAST(rand, 3);

            // Generate random environment
            Map<String, Integer> env = generateRandomEnv(rand);

            // Interpret
            int interpretedResult = SimpleInterpreter.interpret(ast, env);

            // Compile and execute
            String javaCode = compileToJava(ast);
            int compiledResult = executeCompiled(javaCode, env);

            assertEquals(interpretedResult, compiledResult,
                "Mismatch for AST and env");
        }
    }

    private int executeCompiled(String expr, Map<String, Integer> env) {
        // In real implementation, you'd use JavaCompiler API
        // For this example, we'll evaluate directly
        return evalExpression(expr, env);
    }

    private int evalExpression(String expr, Map<String, Integer> env) {
        // Simple evaluator for our generated expressions
        // In practice, use a proper expression evaluator
        return new Object() {
            int pos = -1, ch;

            void nextChar() {
                ch = (++pos < expr.length()) ? expr.charAt(pos) : -1;
            }

            int parse() {
                nextChar();
                int x = parseExpression();
                if (pos < expr.length()) throw new RuntimeException("Unexpected: " + (char)ch);
                return x;
            }

            int parseExpression() {
                int x = parseTerm();
                for (;;) {
                    if (eat('+')) x += parseTerm();
                    else if (eat('-')) x -= parseTerm();
                    else return x;
                }
            }

            int parseTerm() {
                if (eat('(')) {
                    int x = parseExpression();
                    if (!eat(')')) throw new RuntimeException("Missing ')'");
                    return x;
                } else if (Character.isDigit(ch)) {
                    int start = pos;
                    while (Character.isDigit(ch)) nextChar();
                    return Integer.parseInt(expr.substring(start, pos));
                } else if (ch == 'e') {
                    // Parse env.get("x")
                    nextChar(); // 'n'
                    nextChar(); // 'v'
                    nextChar(); // '.'
                    nextChar(); // 'g'
                    nextChar(); // 'e'
                    nextChar(); // 't'
                    nextChar(); // '('
                    nextChar(); // '"'
                    int start = pos;
                    while (ch != '"') nextChar();
                    String varName = expr.substring(start, pos);
                    nextChar(); // '"'
                    nextChar(); // ')'
                    return env.get(varName);
                }
                throw new RuntimeException("Unexpected: " + (char)ch);
            }

            boolean eat(int charToEat) {
                while (ch == ' ') nextChar();
                if (ch == charToEat) {
                    nextChar();
                    return true;
                }
                return false;
            }
        }.parse();
    }

    // Helper methods to generate random ASTs and environments
    private AST generateRandomAST(Random rand, int depth) {
        if (depth == 0 || rand.nextBoolean()) {
            if (rand.nextBoolean()) {
                return new AST(rand.nextInt(100));
            } else {
                return new AST("var" + rand.nextInt(5));
            }
        }

        Expr op = rand.nextBoolean() ? Expr.ADD : Expr.SUB;
        return new AST(op, 
                      generateRandomAST(rand, depth - 1),
                      generateRandomAST(rand, depth - 1));
    }

    private Map<String, Integer> generateRandomEnv(Random rand) {
        Map<String, Integer> env = new HashMap<>();
        for (int i = 0; i < 5; i++) {
            env.put("var" + i, rand.nextInt(100));
        }
        return env;
    }
}
