pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* worker_thread_atomic(void* arg) {
    printf("Worker: Waiting for flag (atomic)...\n");

    // Wait atomically
    while (atomic_load(&flag) == 0) {
        // Could add small delay to reduce CPU usage
        usleep(1000);
    }

    printf("Worker: Flag changed, proceeding...\n");
    return NULL;
}

void* worker_thread_condvar(void* arg) {
    printf("Worker: Waiting with condition variable...\n");

    pthread_mutex_lock(&mutex);
    while (flag == 0) {
        pthread_cond_wait(&cond, &mutex);
    }
    pthread_mutex_unlock(&mutex);

    printf("Worker: Woken up, flag = %d\n", flag);
    return NULL;
}

int main() {
    pthread_t thread1, thread2;

    // Method 1: Using atomics
    printf("=== Using C11 Atomics ===\n");
    pthread_create(&thread1, NULL, worker_thread_atomic, NULL);
    sleep(1);
    printf("Main: Setting atomic flag\n");
    atomic_store(&flag, 1);
    pthread_join(thread1, NULL);

    // Reset for next test
    flag = 0;

    // Method 2: Using condition variables (most efficient)
    printf("\n=== Using Condition Variables ===\n");
    pthread_create(&thread2, NULL, worker_thread_condvar, NULL);
    sleep(1);

    pthread_mutex_lock(&mutex);
    flag = 1;
    printf("Main: Signaling condition variable\n");
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);

    pthread_join(thread2, NULL);

