impl MinimalPerfectHash {
    fn new<K: Hash>(keys: &[K], values: &[u64]) -> Self {
        assert_eq!(keys.len(), values.len());
        let n = keys.len();

        // Simple displacement method (simplified)
        let mut displacement = vec![0; n];
        let mut table = vec![None; n];

        // In reality, you'd use a proper MPH algorithm like CHD
        for (i, key) in keys.iter().enumerate() {
            let mut hasher = RandomXxHashBuilder64::default().build_hasher();
            key.hash(&mut hasher);
            let hash = hasher.finish() as usize % n;

            // Linear probing for displacement
            let mut d = 0;
            while table[(hash + d) % n].is_some() {
                d += 1;
            }
            displacement[hash % n] = d as u32;
            table[(hash + d) % n] = Some(values[i]);
        }

        Self {
            displacement,
            values: table,
            hasher_builder: RandomXxHashBuilder64::default(),
        }
    }

    fn get<K: Hash>(&self, key: &K) -> Option<u64> {
        let mut hasher = self.hasher_builder.build_hasher();
        key.hash(&mut hasher);
        let hash = hasher.finish() as usize % self.values.len();
        let d = self.displacement[hash] as usize;
        self.values[(hash + d) % self.values.len()]
    }
