    bits: BitVec,
    hashes: usize,
    size: usize,
}

impl ApproximateHashSet {
    fn new(memory_bytes: usize, false_positive_rate: f64) -> Self {
        let bits = memory_bytes * 8;
        let size = (-(bits as f64) * (false_positive_rate.ln() / (2.0f64.ln().powi(2)))).ceil() as usize;
        let hashes = ((bits as f64 / size as f64) * 2.0f64.ln()).ceil() as usize;

        Self {
            bits: BitVec::from_elem(bits, false),
            hashes,
            size,
        }
    }

    fn insert<K: Hash>(&mut self, key: &K) {
        for i in 0..self.hashes {
            let mut hasher = XxHash64::with_seed(i as u64);
            key.hash(&mut hasher);
            let hash = hasher.finish() as usize % self.bits.len();
            self.bits.set(hash, true);
        }
    }

    fn contains<K: Hash>(&self, key: &K) -> bool {
        for i in 0..self.hashes {
            let mut hasher = XxHash64::with_seed(i as u64);
            key.hash(&mut hasher);
            let hash = hasher.finish() as usize % self.bits.len();
            if !self.bits[hash] {
                return false;
            }
        }
        true
    }
}
```

### 3. **Cuckoo Filter** (Better than Bloom)
More efficient with 1MB constraint:

```rust
use fnv::FnvHasher;
use std::hash::{Hash, Hasher};
use std::mem;

struct CuckooFilter {
    buckets: Vec<Vec<u16>>,  // Fingerprint storage
    bucket_size: usize,
    num_buckets: usize,
}

impl CuckooFilter {
    fn new(memory_mb: usize) -> Self {
        let total_bits = memory_mb * 1024 * 1024 * 8;
        let bucket_size = 4;  // Standard cuckoo filter parameter
        let fingerprint_bits = 16;  // 2 bytes per fingerprint

        let num_buckets = total_bits / (bucket_size * fingerprint_bits);

        Self {
            buckets: vec![Vec::with_capacity(bucket_size); num_buckets],
            bucket_size,
            num_buckets,
        }
    }

    fn fingerprint<K: Hash>(&self, key: &K) -> u16 {
        let mut hasher = FnvHasher::default();
        key.hash(&mut hasher);
        (hasher.finish() & 0xFFFF) as u16
    }

    fn hash1<K: Hash>(&self, key: &K) -> usize {
        let mut hasher = FnvHasher::default();
        key.hash(&mut hasher);
        (hasher.finish() as usize) % self.num_buckets
    }

    fn hash2(&self, i: usize, fp: u16) -> usize {
        (i ^ (fp as usize)) % self.num_buckets
    }

    fn insert<K: Hash>(&mut self, key: &K) -> bool {
        let fp = self.fingerprint(key);
        let i1 = self.hash1(key);
        let i2 = self.hash2(i1, fp);

        if self.buckets[i1].len() < self.bucket_size {
            self.buckets[i1].push(fp);
            return true;
        }

        if self.buckets[i2].len() < self.bucket_size {
            self.buckets[i2].push(fp);
            return true;
        }

        // Cuckoo eviction (simplified)
        false
    }

    fn contains<K: Hash>(&self, key: &K) -> bool {
        let fp = self.fingerprint(key);
        let i1 = self.hash1(key);
        let i2 = self.hash2(i1, fp);

        self.buckets[i1].contains(&fp) || self.buckets[i2].contains(&fp)
    }
}
```

### 4. **External Perfect Hash with 1MB Index**
If you have external storage (disk/DB):

```rust
use std::collections::HashMap;
use std::fs::{File, OpenOptions};
use std::io::{Seek, SeekFrom, Write, Read};
use std::path::Path;

struct ExternalPerfectHash {
    index: HashMap<u64, u64>,  // 1MB in-memory index
    data_file: File,
}

impl ExternalPerfectHash {
    fn new<P: AsRef<Path>>(path: P, max_index_entries: usize) -> std::io::Result<Self> {
        // Calculate memory usage: each entry ~16 bytes (u64 key + u64 offset)
        // 1MB / 16 bytes = ~65,536 entries max

        let data_file = OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .open(path)?;

        Ok(Self {
            index: HashMap::with_capacity(max_index_entries),
            data_file,
        })
    }

    fn insert<K: Hash>(&mut self, key: &K, value: &[u8]) -> std::io::Result<()> {
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        key.hash(&mut hasher);
        let key_hash = hasher.finish();

        // Store offset in index
        let offset = self.data_file.seek(SeekFrom::End(0))?;
        self.index.insert(key_hash, offset);

        // Write to external storage
        self.data_file.write_all(&(value.len() as u32).to_le_bytes())?;
        self.data_file.write_all(value)?;

        Ok(())
    }

    fn get<K: Hash>(&mut self, key: &K) -> std::io::Result<Option<Vec<u8>>> {
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        key.hash(&mut hasher);
        let key_hash = hasher.finish();

        if let Some(&offset) = self.index.get(&key_hash) {
            self.data_file.seek(SeekFrom::Start(offset))?;

            let mut len_bytes = [0u8; 4];
            self.data_file.read_exact(&mut len_bytes)?;
            let len = u32::from_le_bytes(len_bytes) as usize;

            let mut buffer = vec![0u8; len];
            self.data_file.read_exact(&mut buffer)?;

            Ok(Some(buffer))
        } else {
            Ok(None)
        }
    }
}
```

