    // This comparison executes in constant time
    a.ct_eq(b).into()
}

fn conditional_select<T: ConditionallySelectable>(a: T, b: T, choice: Choice) -> T {
    // This selection executes in constant time
    T::conditional_select(&a, &b, choice)
}
