Here's a minimal working example of a lease-based lock with fencing tokens in Go, including clear failure handling:

```go
package main

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"
)

// Errors for clear failure handling
var (
	ErrLockAcquireTimeout = errors.New("lock acquire timeout")
	ErrLockNotHeld        = errors.New("lock not held")
	ErrStaleToken         = errors.New("stale fencing token")
)

// FencingLock represents a lease-based lock with fencing tokens
type FencingLock struct {
	mu            sync.RWMutex
	lockHolder    string
	fencingToken  int64
	leaseDuration time.Duration
	expiresAt     time.Time
	stopRenewal   chan struct{}
}

// LockResult represents the result of acquiring a lock
type LockResult struct {
	Token      int64
	CancelFunc context.CancelFunc
}

// NewFencingLock creates a new fencing lock
func NewFencingLock(leaseDuration time.Duration) *FencingLock {
	return &FencingLock{
		leaseDuration: leaseDuration,
		stopRenewal:   make(chan struct{}),
	}
}

// TryAcquire attempts to acquire the lock with a timeout
func (fl *FencingLock) TryAcquire(ctx context.Context, holderID string) (*LockResult, error) {
	fl.mu.Lock()
	defer fl.mu.Unlock()

	// Check if lock is already held by someone else
	if fl.lockHolder != "" && fl.lockHolder != holderID && time.Now().Before(fl.expiresAt) {
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(time.Until(fl.expiresAt)):
			// Wait for lock to expire
		}
	}

	// Generate new fencing token (monotonically increasing)
	fl.fencingToken++
	fl.lockHolder = holderID
	fl.expiresAt = time.Now().Add(fl.leaseDuration)

	// Create context for renewal cancellation
	renewCtx, cancel := context.WithCancel(context.Background())

	// Start lease renewal in background
	go fl.renewLease(renewCtx, holderID, fl.fencingToken)

	return &LockResult{
		Token:      fl.fencingToken,
		CancelFunc: cancel,
	}, nil
}

// renewLease periodically renews the lease while lock is held
func (fl *FencingLock) renewLease(ctx context.Context, holderID string, expectedToken int64) {
	ticker := time.NewTicker(fl.leaseDuration / 2)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			fl.mu.Lock()
			// Verify we still hold the lock with the same token
			if fl.lockHolder == holderID && fl.fencingToken == expectedToken {
				fl.expiresAt = time.Now().Add(fl.leaseDuration)
				fmt.Printf("Lease renewed for holder %s, token %d\n", holderID, expectedToken)
			} else {
				fl.mu.Unlock()
				return // Lost lock or token changed
			}
			fl.mu.Unlock()
		}
	}
}

// ValidateToken checks if a fencing token is still valid
func (fl *FencingLock) ValidateToken(holderID string, token int64) error {
	fl.mu.RLock()
	defer fl.mu.RUnlock()

	if fl.lockHolder != holderID {
		return ErrLockNotHeld
	}

	if token < fl.fencingToken {
		return ErrStaleToken
	}

	if time.Now().After(fl.expiresAt) {
		return ErrLockNotHeld // Lease expired
	}

	return nil
}

// Release releases the lock
func (fl *FencingLock) Release(holderID string, token int64) error {
	fl.mu.Lock()
	defer fl.mu.Unlock()

	if fl.lockHolder != holderID {
		return ErrLockNotHeld
	}

	if token < fl.fencingToken {
		return ErrStaleToken
	}

	// Clear lock state
	fl.lockHolder = ""
	fl.expiresAt = time.Time{}
	fmt.Printf("Lock released by holder %s, token %d\n", holderID, token)

	return nil
}

// Example usage with failure handling
func main() {
	lock := NewFencingLock(5 * time.Second)

	// Example 1: Successful lock acquisition and use
	fmt.Println("=== Example 1: Successful operation ===")
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	result, err := lock.TryAcquire(ctx, "client-1")
	if err != nil {
		fmt.Printf("Failed to acquire lock: %v\n", err)
		return
	}
	defer result.CancelFunc()

	fmt.Printf("Lock acquired with token: %d\n", result.Token)

	// Simulate doing work with fencing token validation
	err = lock.ValidateToken("client-1", result.Token)
	if err != nil {
		fmt.Printf("Token validation failed: %v\n", err)
		return
	}

	// Simulate work
	time.Sleep(2 * time.Second)

	// Release lock
	err = lock.Release("client-1", result.Token)
	if err != nil {
		fmt.Printf("Failed to release lock: %v\n", err)
	}

	// Example 2: Concurrent access with fencing
	fmt.Println("\n=== Example 2: Concurrent access ===")
	var wg sync.WaitGroup
	wg.Add(2)

	// Client 1 acquires lock
	go func() {
		defer wg.Done()
		ctx1, _ := context.WithTimeout(context.Background(), 3*time.Second)
		result1, err := lock.TryAcquire(ctx1, "client-1")
		if err != nil {
			fmt.Printf("Client 1 failed: %v\n", err)
			return
		}
		defer result1.CancelFunc()

		fmt.Printf("Client 1 acquired lock with token: %d\n", result1.Token)
		time.Sleep(6 * time.Second) // Hold lock longer than lease

		// This should fail due to stale token
		err = lock.ValidateToken("client-1", result1.Token)
		if err != nil {
			fmt.Printf("Client 1 token validation: %v\n", err)
		}
	}()

	// Client 2 tries to acquire lock
	go func() {
		defer wg.Done()
		time.Sleep(2 * time.Second) // Wait for client 1 to have lock

		ctx2, _ := context.WithTimeout(context.Background(), 10*time.Second)
		result2, err := lock.TryAcquire(ctx2, "client-2")
		if err != nil {
			fmt.Printf("Client 2 failed: %v\n", err)
			return
		}
		defer result2.CancelFunc()

		fmt.Printf("Client 2 acquired lock with token: %d\n", result2.Token)

		// Client 1's token should now be stale
		err = lock.ValidateToken("client-1", 1) // Token 1 from client 1
		if errors.Is(err, ErrStaleToken) {
			fmt.Println("Correctly detected stale token from client 1")
		}
	}()

	wg.Wait()

	// Example 3: Error scenarios
	fmt.Println("\n=== Example 3: Error handling ===")

	// Try to release lock not held
	err = lock.Release("client-1", 999)
	if errors.Is(err, ErrLockNotHeld) {
		fmt.Println("Correctly detected lock not held")
	}

	// Try to acquire with timeout
	shortCtx, shortCancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer shortCancel()

	_, err = lock.TryAcquire(shortCtx, "client-3")
	if errors.Is(err, context.DeadlineExceeded) {
		fmt.Println("Correctly timed out on lock acquisition")
	}
}
```

Key features of this implementation:

1. **Lease-based locking**: Locks have a finite duration and must be renewed
2. **Fencing tokens**: Monotonically increasing tokens prevent stale lock holders
3. **Clear failure handling**: Specific error types for different failure scenarios
4. **Automatic renewal**: Background goroutine renews lease while lock is held
5. **Thread-safe**: Proper synchronization with mutexes
6. **Context support**: Timeouts and cancellation via context

The fencing tokens work by:
- Generating a new token each time the lock is acquired
- Validating tokens before any operation
- Rejecting operations with stale (lower) tokens
- Ensuring only the current lock holder with the latest token can perform operations

This pattern is particularly useful in distributed systems where network partitions or process pauses could cause a client to believe it still holds a lock when it doesn't.

Here's a Java example demonstrating Raft-style consensus with partial synchrony and failure handling:

```java
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

// Node states in Raft
enum NodeState {
    FOLLOWER, CANDIDATE, LEADER
}

// Raft Node implementation
class RaftNode {
    private final int nodeId;
    private final List<RaftNode> allNodes;
    private volatile NodeState state = NodeState.FOLLOWER;
    private volatile int currentTerm = 0;
    private volatile Integer votedFor = null;
    private volatile int commitIndex = 0;
    private volatile int lastApplied = 0;

    // Leader-specific state
    private final Map<Integer, Integer> nextIndex = new ConcurrentHashMap<>();
    private final Map<Integer, Integer> matchIndex = new ConcurrentHashMap<>();

    // Election timeout (partial synchrony assumption)
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private ScheduledFuture<?> electionTimeout;
    private final Random random = new Random();

    // Heartbeat interval
    private static final int HEARTBEAT_INTERVAL_MS = 150;
    private ScheduledFuture<?> heartbeatTask;

    // Log entries
    private final List<LogEntry> log = new CopyOnWriteArrayList<>();

    // For consensus tracking
    private final AtomicInteger votesReceived = new AtomicInteger(0);
    private final Object electionLock = new Object();

    public RaftNode(int nodeId, List<RaftNode> allNodes) {
        this.nodeId = nodeId;
        this.allNodes = allNodes;
        resetElectionTimeout();
    }

    // Log entry structure
    static class LogEntry {
        final int term;
        final String command;

        LogEntry(int term, String command) {
            this.term = term;
            this.command = command;
        }
    }

    // RPC Request/Response classes
    static class AppendEntriesRequest {
        final int term;
        final int leaderId;
        final int prevLogIndex;
        final int prevLogTerm;
        final List<LogEntry> entries;
        final int leaderCommit;

        AppendEntriesRequest(int term, int leaderId, int prevLogIndex, 
                           int prevLogTerm, List<LogEntry> entries, int leaderCommit) {
            this.term = term;
            this.leaderId = leaderId;
            this.prevLogIndex = prevLogIndex;
            this.prevLogTerm = prevLogTerm;
            this.entries = entries;
            this.leaderCommit = leaderCommit;
        }
    }

    static class AppendEntriesResponse {
        final int term;
        final boolean success;

        AppendEntriesResponse(int term, boolean success) {
            this.term = term;
            this.success = success;
        }
    }

    static class RequestVoteRequest {
        final int term;
        final int candidateId;
        final int lastLogIndex;
        final int lastLogTerm;

        RequestVoteRequest(int term, int candidateId, int lastLogIndex, int lastLogTerm) {
            this.term = term;
            this.candidateId = candidateId;
            this.lastLogIndex = lastLogIndex;
            this.lastLogTerm = lastLogTerm;
        }
    }

    static class RequestVoteResponse {
        final int term;
        final boolean voteGranted;

        RequestVoteResponse(int term, boolean voteGranted) {
            this.term = term;
            this.voteGranted = voteGranted;
        }
    }

    // Reset election timeout (partial synchrony: timeout eventually occurs)
    private void resetElectionTimeout() {
        if (electionTimeout != null) {
            electionTimeout.cancel(false);
        }

        // Random timeout between 150-300ms (prevents split votes)
        int timeout = 150 + random.nextInt(150);
        electionTimeout = scheduler.schedule(this::startElection, timeout, TimeUnit.MILLISECONDS);
    }

    // Start new election
    private void startElection() {
        synchronized (electionLock) {
            if (state == NodeState.LEADER) return;

            System.out.println("Node " + nodeId + ": Starting election for term " + (currentTerm + 1));

            state = NodeState.CANDIDATE;
            currentTerm++;
            votedFor = nodeId;
            votesReceived.set(1); // Vote for self

            // Request votes from other nodes
            RequestVoteRequest request = new RequestVoteRequest(
                currentTerm, nodeId, 
                log.size() - 1,
                log.isEmpty() ? 0 : log.get(log.size() - 1).term
            );

            for (RaftNode node : allNodes) {
                if (node.nodeId != nodeId) {
                    CompletableFuture.runAsync(() -> {
                        RequestVoteResponse response = node.handleRequestVote(request);
                        handleVoteResponse(response);
                    });
                }
            }

            resetElectionTimeout();
        }
    }

    // Handle vote request from other nodes
    public RequestVoteResponse handleRequestVote(RequestVoteRequest request) {
        synchronized (electionLock) {
            // If request term is older, reject
            if (request.term < currentTerm) {
                return new RequestVoteResponse(currentTerm, false);
            }

            // Update term if newer
            if (request.term > currentTerm) {
                currentTerm = request.term;
                state = NodeState.FOLLOWER;
                votedFor = null;
            }

            // Check if we can grant vote
            boolean canVote = (votedFor == null || votedFor == request.candidateId) &&
                            isCandidateLogUpToDate(request);

            if (canVote) {
                votedFor = request.candidateId;
                resetElectionTimeout();
                return new RequestVoteResponse(currentTerm, true);
            }

            return new RequestVoteResponse(currentTerm, false);
        }
    }

    private boolean isCandidateLogUpToDate(RequestVoteRequest request) {
        if (log.isEmpty()) return true;

        int lastLogTerm = log.get(log.size() - 1).term;
        if (request.lastLogTerm > lastLogTerm) return true;
        if (request.lastLogTerm == lastLogTerm && request.lastLogIndex >= log.size() - 1) return true;

        return false;
    }

    // Handle vote response
    private void handleVoteResponse(RequestVoteResponse response) {
        synchronized (electionLock) {
            // Update term if newer
            if (response.term > currentTerm) {
                currentTerm = response.term;
                state = NodeState.FOLLOWER;
                votedFor = null;
                return;
            }

            // Check if still candidate in same term
            if (state != NodeState.CANDIDATE || response.term != currentTerm) {
                return;
            }

            if (response.voteGranted) {
                int votes = votesReceived.incrementAndGet();

                // Become leader if majority votes received
                if (votes > allNodes.size() / 2) {
                    System.out.println("Node " + nodeId + ": Elected leader for term " + currentTerm);
                    becomeLeader();
                }
            }
        }
    }

    // Transition to leader
    private void becomeLeader() {
        state = NodeState.LEADER;

        // Initialize leader state
        for (RaftNode node : allNodes) {
            if (node.nodeId != nodeId) {
                nextIndex.put(node.nodeId, log.size());
                matchIndex.put(node.nodeId, 0);
            }
        }

        // Cancel election timeout
        if (electionTimeout != null) {
            electionTimeout.cancel(false);
        }

        // Start sending heartbeats
        startHeartbeats();

        // Send initial empty AppendEntries as heartbeat
        sendHeartbeats();
    }

    private void startHeartbeats() {
        if (heartbeatTask != null) {
            heartbeatTask.cancel(false);
        }

        heartbeatTask = scheduler.scheduleAtFixedRate(
            this::sendHeartbeats,
            0, HEARTBEAT_INTERVAL_MS, TimeUnit.MILLISECONDS
        );
    }

    private void sendHeartbeats() {
        if (state != NodeState.LEADER) return;

        for (RaftNode node : allNodes) {
            if (node.nodeId != nodeId) {
                CompletableFuture.runAsync(() -> {
                    AppendEntriesRequest request = createAppendEntriesRequest(node.nodeId);
                    AppendEntriesResponse response = node.handleAppendEntries(request);
                    handleAppendEntriesResponse(node.nodeId, response);
                }).exceptionally(e -> {
                    // Handle network failure (partial synchrony: may be temporary)
                    System.err.println("Node " + nodeId + ": Failed to send heartbeat to " + 
                                     node.nodeId + ": " + e.getMessage());
                    return null;
                });
            }
        }
    }

    private AppendEntriesRequest createAppendEntriesRequest(int followerId) {
        int nextIdx = nextIndex.getOrDefault(followerId, 0);
        int prevLogIndex = nextIdx - 1;
        int prevLogTerm = (prevLogIndex >= 0 && prevLogIndex < log.size()) ? 
                         log.get(prevLogIndex).term : 0;

        List<LogEntry> entries = new ArrayList<>();
        if (nextIdx < log.size()) {
            entries = log.subList(nextIdx, log.size());
        }

        return new AppendEntriesRequest(
            currentTerm, nodeId, prevLogIndex, prevLogTerm, 
            entries, commitIndex
        );
    }

    // Handle AppendEntries RPC (heartbeat or log replication)
    public AppendEntriesResponse handleAppendEntries(AppendEntriesRequest request) {
        synchronized (electionLock) {
            // Reset election timeout on valid leader communication
            resetElectionTimeout();

            // Reply false if term < currentTerm
            if (request.term < currentTerm) {
                return new AppendEntriesResponse(currentTerm, false);
            }

            // If RPC request contains higher term, update current term
            if (request.term > currentTerm) {
                currentTerm = request.term;
                state = NodeState.FOLLOWER;
                votedFor = null;
            }

            // If we were candidate or leader, become follower
            if (state != NodeState.FOLLOWER) {
                state = NodeState.FOLLOWER;
            }

            // Check log consistency
            if (request.prevLogIndex >= 0) {
                if (log.size() <= request.prevLogIndex || 
                    log.get(request.prevLogIndex).term != request.prevLogTerm) {
                    return new AppendEntriesResponse(currentTerm, false);
                }
            }

            // Append new entries (simplified - in real Raft, handle conflicts)
            if (request.entries != null && !request.entries.isEmpty()) {
                // Remove conflicting entries
                int startIndex = request.prevLogIndex + 1;
                if (log.size() > startIndex) {
                    log.subList(startIndex, log.size()).clear();
                }
                log.addAll(request.entries);
            }

            // Update commit index
            if (request.leaderCommit > commitIndex) {
                commitIndex = Math.min(request.leaderCommit, log.size() - 1);
                applyCommittedEntries();
            }

            return new AppendEntriesResponse(currentTerm, true);
        }
    }

    private void handleAppendEntriesResponse(int followerId, AppendEntriesResponse response) {
        synchronized (electionLock) {
            if (state != NodeState.LEADER) return;

            // Update term if newer
            if (response.term > currentTerm) {
                currentTerm = response.term;
                state = NodeState.FOLLOWER;
                votedFor = null;
                resetElectionTimeout();
                return;
            }

            if (response.success) {
                // Update matchIndex and nextIndex for follower
                int newNextIndex = nextIndex.get(followerId) + 1;
                nextIndex.put(followerId, newNextIndex);
                matchIndex.put(followerId, newNextIndex - 1);

                // Update commit index
                updateCommitIndex();
            } else {
                // Decrement nextIndex and retry
                nextIndex.put(followerId, Math.max(0, nextIndex.get(followerId) - 1));
            }
        }
    }

    private void updateCommitIndex() {
        // Find the highest index replicated on majority of nodes
        for (int i = commitIndex + 1; i < log.size(); i++) {
            int count = 1; // Count self
            for (RaftNode node : allNodes) {
                if (node.nodeId != nodeId && matchIndex.getOrDefault(node.nodeId, 0) >= i) {
                    count++;
                }
            }

            if (count > allNodes.size() / 2 && log.get(i).term == currentTerm) {
                commitIndex = i;
            }
        }

        applyCommittedEntries();
    }

    private void applyCommittedEntries() {
        while (lastApplied < commitIndex) {
            lastApplied++;
            LogEntry entry = log.get(lastApplied);
            System.out.println("Node " + nodeId + ": Applying command: " + entry.command + 
                             " (term: " + entry.term + ")");
            // In real implementation, apply to state machine
        }
    }

    // Client request handling (leader only)
    public boolean proposeCommand(String command) {
        if (state != NodeState.LEADER) {
            System.out.println("Node " + nodeId + ": Not leader, redirecting");
            return false;
        }

        synchronized (electionLock) {
            LogEntry entry = new LogEntry(currentTerm, command);
            log.add(entry);
            System.out.println("Node " + nodeId + ": Proposed command: " + command);

            // Replicate to followers
            sendHeartbeats();
            return true;
        }
    }

    public void stop() {
        scheduler.shutdown();
        if (electionTimeout != null) electionTimeout.cancel(false);
        if (heartbeatTask != null) heartbeatTask.cancel(false);
    }
}

// Example usage
public class RaftConsensusExample {
    public static void main(String[] args) throws InterruptedException {
        // Create 3 nodes (typical Raft cluster size)
        List<RaftNode> nodes = new ArrayList<>();
        for (int i = 0; i < 3; i++) {
            nodes.add(new RaftNode(i, nodes));
        }

        // Wait for election
        Thread.sleep(1000);

        // Find leader and propose commands
        for (RaftNode node : nodes) {
            if (node.proposeCommand("SET key1=value1")) {
                System.out.println("Command proposed to leader");
                break;
            }
        }

        // Wait for replication
        Thread.sleep(500);

        // Simulate network partition by stopping one node
        System.out.println("\n--- Simulating network partition ---");
        nodes.get(1).stop();

        // Try to propose another command
        Thread.sleep(2000);
        for (RaftNode node : nodes) {
            if (node.proposeCommand("SET key2=value2")) {
                System.out.println("Command proposed after partition");
                break;
            }
        }

        // Wait and clean up
        Thread.sleep(2000);
        for (RaftNode node : nodes) {
            node.stop();
        }
    }
}
```

## Key Features Demonstrated:

### 1. **Partial Synchrony Assumptions:**
- Timeouts for leader election (150-300ms random range)
- Heartbeats sent periodically (150ms intervals)
- Network failures handled with try-catch and retry logic

### 2. **Raft Consensus Components:**
- **Leader Election:** Timeout-based transition to candidate, request votes
- **Log Replication:** AppendEntries RPC for heartbeats and log replication
- **Safety:** Term numbers, log consistency checks, majority voting

### 3. **Failure Handling:**
- **Network Partitions:** Nodes continue operating, detect stale leaders via terms
- **Leader Failure:** Election timeout triggers new election
- **Log Inconsistency:** NextIndex backtracking on failed AppendEntries
- **Split Votes:** Randomized election timeouts prevent repeated deadlocks

### 4. **Safety Properties:**
- **Election Safety:** At most one leader per term
- **Leader Append-Only:** Leaders never overwrite or delete entries
- **Log Matching:** If logs have same index/term, all preceding entries match
- **Leader Completeness:** Committed entries present in future leaders' logs

### 5. **Partial Synchrony Implications:**
- Messages may be delayed but eventually delivered
- Clocks may drift but timeout bounds exist
- System makes progress during "good periods" (GST - Global Stabilization Time)

The example shows how Raft maintains consensus despite temporary asynchrony, with clear failure detection and recovery mechanisms.

