Here's a JavaScript example implementing Lamport clocks with message timestamps and failure handling:

```javascript
/**
 * Lamport Clock implementation with total ordering and failure handling
 */
class LamportClock {
  constructor(nodeId) {
    this.nodeId = nodeId;
    this.counter = 0;
    this.pendingMessages = new Map(); // For tracking unacknowledged messages
    this.messageHistory = []; // For total ordering
  }

  /**
   * Increment local counter and return timestamp
   */
  tick() {
    this.counter++;
    return this.counter;
  }

  /**
   * Update counter based on received timestamp
   */
  receive(timestamp) {
    this.counter = Math.max(this.counter, timestamp) + 1;
    return this.counter;
  }

  /**
   * Send a message with Lamport timestamp
   */
  sendMessage(content, recipientCallback) {
    const timestamp = this.tick();
    const message = {
      id: `${this.nodeId}-${timestamp}-${Date.now()}`,
      sender: this.nodeId,
      content,
      timestamp,
      sentAt: Date.now()
    };

    // Track pending message
    this.pendingMessages.set(message.id, {
      message,
      recipientCallback,
      retries: 0,
      acknowledged: false
    });

    try {
      // Simulate sending with potential failure
      this._attemptSend(message);
      return message.id;
    } catch (error) {
      this._handleSendError(message.id, error);
      throw new Error(`Failed to send message: ${error.message}`);
    }
  }

  /**
   * Receive a message and update clock
   */
  receiveMessage(message) {
    // Validate message structure
    if (!this._validateMessage(message)) {
      throw new Error('Invalid message format');
    }

    // Update Lamport clock
    this.receive(message.timestamp);

    // Add to total order
    const orderedMessage = {
      ...message,
      receivedAt: Date.now(),
      logicalTime: this.counter,
      totalOrderKey: `${message.timestamp}.${this.nodeId}`
    };

    this.messageHistory.push(orderedMessage);

    // Sort by total order (timestamp, then sender ID for tie-breaking)
    this.messageHistory.sort((a, b) => {
      if (a.timestamp !== b.timestamp) {
        return a.timestamp - b.timestamp;
      }
      return a.sender.localeCompare(b.sender);
    });

    // Send acknowledgment
    this._sendAck(message.id, message.sender);

    return orderedMessage;
  }

  /**
   * Acknowledge receipt of a message
   */
  acknowledgeMessage(messageId, senderId) {
    const pending = this.pendingMessages.get(messageId);
    if (pending && pending.message.sender === this.nodeId) {
      pending.acknowledged = true;
      this.pendingMessages.delete(messageId);
      console.log(`Message ${messageId} acknowledged by ${senderId}`);
    }
  }

  /**
   * Get total ordered message history
   */
  getTotalOrder() {
    return [...this.messageHistory];
  }

  /**
   * Check for unacknowledged messages and retry
   */
  checkPendingMessages() {
    const now = Date.now();
    const TIMEOUT = 5000; // 5 seconds
    const MAX_RETRIES = 3;

    for (const [messageId, pending] of this.pendingMessages.entries()) {
      if (!pending.acknowledged && now - pending.sentAt > TIMEOUT) {
        if (pending.retries < MAX_RETRIES) {
          pending.retries++;
          console.log(`Retrying message ${messageId} (attempt ${pending.retries})`);
          this._attemptSend(pending.message);
        } else {
          console.error(`Message ${messageId} failed after ${MAX_RETRIES} retries`);
          this.pendingMessages.delete(messageId);
          // In production, you might want to emit an event or callback here
        }
      }
    }
  }

  // Private methods
  _attemptSend(message) {
    // Simulate network failure 10% of the time
    if (Math.random() < 0.1) {
      throw new Error('Network failure simulated');
    }

    // In real implementation, this would be actual network communication
    console.log(`Node ${this.nodeId} sending:`, {
      id: message.id,
      content: message.content,
      timestamp: message.timestamp
    });

    // Simulate recipient processing
    setTimeout(() => {
      if (message.recipientCallback) {
        message.recipientCallback(message);
      }
    }, Math.random() * 100); // Random delay
  }

  _sendAck(messageId, senderId) {
    // Simulate sending acknowledgment
    console.log(`Node ${this.nodeId} acknowledging message ${messageId} from ${senderId}`);
    // In real implementation, send ACK back to sender
  }

  _validateMessage(message) {
    return message &&
      typeof message.id === 'string' &&
      typeof message.sender === 'string' &&
      typeof message.timestamp === 'number' &&
      Number.isInteger(message.timestamp) &&
      message.timestamp > 0;
  }

  _handleSendError(messageId, error) {
    console.error(`Send error for ${messageId}:`, error.message);
    this.pendingMessages.delete(messageId);
  }
}

// Example usage with failure handling
async function demonstrateLamportClocks() {
  console.log('=== Lamport Clock Demonstration ===\n');

  // Create two nodes
  const nodeA = new LamportClock('Node-A');
  const nodeB = new LamportClock('Node-B');

  // Simulate message exchange with callbacks
  const messagesSent = [];

  // Node A sends to Node B
  try {
    const msgId1 = nodeA.sendMessage('Hello from A', (msg) => {
      console.log(`\nNode B receiving: ${msg.content}`);
