      console.log(`\nNode A receiving: ${msg.content}`);
      const received = nodeA.receiveMessage(msg);
      nodeA.acknowledgeMessage(msg.id, msg.sender);
      messagesSent.push({ from: 'B', to: 'A', id: msg.id, success: true });
    });
    console.log(`Node B sent message: ${msgId2}`);
  } catch (error) {
    console.error('Failed to send from B to A:', error.message);
    messagesSent.push({ from: 'B', to: 'A', success: false, error: error.message });
  }

  // Wait for async operations
  await new Promise(resolve => setTimeout(resolve, 1000));

  // Check for pending messages (simulating retry logic)
  nodeA.checkPendingMessages();
  nodeB.checkPendingMessages();

  // Display results
  console.log('\n=== Results ===');
  console.log('Node A counter:', nodeA.counter);
  console.log('Node B counter:', nodeB.counter);

  console.log('\nNode A message history (total order):');
  nodeA.getTotalOrder().forEach(msg => {
    console.log(`  [${msg.timestamp}] ${msg.sender}: ${msg.content}`);
  });

  console.log('\nNode B message history (total order):');
  nodeB.getTotalOrder().forEach(msg => {
    console.log(`  [${msg.timestamp}] ${msg.sender}: ${msg.content}`);
  });

  console.log('\nMessage delivery summary:');
  messagesSent.forEach(msg => {
    console.log(`  ${msg.from} → ${msg.to}: ${msg.success ? '✓' : '✗'} ${msg.error || ''}`);
  });

  // Verify total order consistency
  const orderA = nodeA.getTotalOrder().map(m => m.totalOrderKey);
  const orderB = nodeB.getTotalOrder().map(m => m.totalOrderKey);

  console.log('\nTotal order consistency check:');
  console.log('Orders match:', JSON.stringify(orderA) === JSON.stringify(orderB));
}

