Here's a wait-free consensus implementation using compare-and-swap (CAS) with failure handling:

```java
import java.util.concurrent.atomic.AtomicReference;
import java.util.concurrent.atomic.AtomicInteger;

public class WaitFreeConsensus<T> {
    private static final int MAX_THREADS = 128;

    // Consensus state
    private final AtomicReference<Proposal<T>> decision = new AtomicReference<>(null);
    private final AtomicInteger[] announce;
    private final Proposal<T>[] proposals;

    // Failure tracking
    private final AtomicInteger activeThreads = new AtomicInteger(0);
    private final boolean[] threadFailed;

    @SuppressWarnings("unchecked")
    public WaitFreeConsensus(int maxParticipants) {
        if (maxParticipants > MAX_THREADS) {
            throw new IllegalArgumentException("Maximum participants exceeded");
        }

        announce = new AtomicInteger[maxParticipants];
        proposals = (Proposal<T>[]) new Proposal[maxParticipants];
        threadFailed = new boolean[maxParticipants];

        for (int i = 0; i < maxParticipants; i++) {
            announce[i] = new AtomicInteger(-1);
            threadFailed[i] = false;
        }
    }

    public static class Proposal<T> {
        final T value;
        final int threadId;
        final long timestamp;

        public Proposal(T value, int threadId) {
            this.value = value;
            this.threadId = threadId;
            this.timestamp = System.nanoTime();
        }
    }

    /**
     * Propose a value and wait for consensus decision
     * @param threadId unique thread identifier (0 <= threadId < maxParticipants)
     * @param value the value being proposed
     * @return the consensus value
     * @throws ConsensusException if consensus cannot be reached
     */
    public T propose(int threadId, T value) throws ConsensusException {
        validateThreadId(threadId);

        try {
            activeThreads.incrementAndGet();

            // Phase 1: Announce proposal
            Proposal<T> myProposal = new Proposal<>(value, threadId);
            proposals[threadId] = myProposal;
            announce[threadId].set(1);

            // Phase 2: Help other threads and decide
            Proposal<T> winner = null;

            for (int i = 0; i < proposals.length; i++) {
                if (threadFailed[i]) continue;

                int status = announce[i].get();
                if (status == 1) {
                    Proposal<T> otherProposal = proposals[i];
                    if (otherProposal != null) {
                        // Try to decide this proposal
                        if (winner == null || 
                            otherProposal.timestamp < winner.timestamp ||
                            (otherProposal.timestamp == winner.timestamp && 
                             otherProposal.threadId < winner.threadId)) {
                            winner = otherProposal;
                        }
                    }
                }
            }

            if (winner == null) {
                throw new ConsensusException("No valid proposals found");
            }

            // Try to establish consensus
            if (decision.compareAndSet(null, winner)) {
                // We successfully set the consensus
                return winner.value;
            } else {
                // Consensus already reached, return the decided value
                return decision.get().value;
            }

        } catch (Exception e) {
            markThreadFailed(threadId);
            throw new ConsensusException("Thread " + threadId + " failed during consensus", e);
        } finally {
            activeThreads.decrementAndGet();
            announce[threadId].set(-1); // Clean up
        }
    }

    /**
     * Check if consensus has been reached
     */
    public boolean isDecided() {
        return decision.get() != null;
    }

    /**
     * Get the current consensus value (if decided)
     */
    public T getDecision() {
        Proposal<T> decided = decision.get();
        return decided != null ? decided.value : null;
    }

    /**
     * Reset consensus for a new round (only if no active threads)
     */
    public boolean reset() {
        if (activeThreads.get() == 0) {
            decision.set(null);
            for (int i = 0; i < announce.length; i++) {
                announce[i].set(-1);
                proposals[i] = null;
            }
            return true;
        }
        return false;
    }

    /**
     * Mark a thread as failed
     */
    private synchronized void markThreadFailed(int threadId) {
        threadFailed[threadId] = true;
        announce[threadId].set(-1);
        proposals[threadId] = null;
    }

    /**
     * Check if a thread has failed
     */
    public boolean isThreadFailed(int threadId) {
        validateThreadId(threadId);
        return threadFailed[threadId];
    }

    /**
     * Recover a failed thread
     */
    public synchronized void recoverThread(int threadId) {
        validateThreadId(threadId);
        threadFailed[threadId] = false;
    }

    private void validateThreadId(int threadId) {
        if (threadId < 0 || threadId >= announce.length) {
            throw new IllegalArgumentException("Invalid thread ID");
        }
    }

    public static class ConsensusException extends Exception {
        public ConsensusException(String message) {
            super(message);
        }

        public ConsensusException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}

// Example usage
class ConsensusExample {
    public static void main(String[] args) {
        WaitFreeConsensus<String> consensus = new WaitFreeConsensus<>(4);

        Thread[] threads = new Thread[4];

        for (int i = 0; i < 4; i++) {
            final int threadId = i;
            threads[i] = new Thread(() -> {
                try {
                    String proposal = "Value-from-thread-" + threadId;
                    String result = consensus.propose(threadId, proposal);
                    System.out.println("Thread " + threadId + " decided on: " + result);
                } catch (WaitFreeConsensus.ConsensusException e) {
                    System.err.println("Thread " + threadId + " failed: " + e.getMessage());
                }
            });
        }

        for (Thread t : threads) {
            t.start();
        }

        for (Thread t : threads) {
            try {
                t.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        System.out.println("Final consensus: " + consensus.getDecision());
    }
}
```

## How It Works:

### 1. **Wait-Free Guarantee**
- Every thread completes in a bounded number of steps regardless of other threads' behavior
- No locks or blocking operations
- Linearization point is the successful CAS operation on the `decision` atomic reference

### 2. **Core Algorithm**
1. **Announce Phase**: Each thread announces its proposal in its dedicated slot
2. **Help Phase**: Threads scan all announcements to find the "winning" proposal (earliest timestamp, with thread ID as tiebreaker)
3. **Decision Phase**: Threads attempt to CAS the global decision with the winner
4. **Fallback**: If CAS fails, consensus was already reached by another thread

### 3. **Failure Handling**
- **Thread Failure Detection**: Threads mark themselves as failed if exceptions occur
- **Clean State**: Failed threads clean up their announcement slots
- **Isolation**: Failed threads don't block progress of other threads
- **Recovery**: Failed threads can be explicitly recovered

### 4. **Key Properties**
- **Validity**: The decided value must be proposed by some thread
- **Agreement**: All threads decide the same value
- **Termination**: Every correct thread eventually decides (wait-free)
- **Fault Tolerance**: Survives thread crashes during execution

### 5. **Atomic Operations**
- `AtomicReference.compareAndSet()`: For establishing consensus
- `AtomicInteger.get()/set()`: For announcement coordination
- No locks or blocking synchronization

The algorithm ensures that even if some threads crash, the remaining threads can still reach consensus in bounded time, making it truly wait-free and fault-tolerant.

Here's a Java example that computes a discrete logarithm using the Baby-Step Giant-Step algorithm for a 16-bit group:

```java
import java.math.BigInteger;
import java.util.HashMap;
import java.util.Map;

public class BabyStepGiantStep {

    /**
     * Computes discrete logarithm: find x such that base^x ≡ target (mod modulus)
     * using Baby-Step Giant-Step algorithm.
     * 
     * @param base The generator/base
     * @param target The target value
     * @param modulus The modulus (prime for group)
     * @return The exponent x, or -1 if not found
     */
    public static long discreteLog(long base, long target, long modulus) {
        // Ensure we're working with positive values
        base = Math.floorMod(base, modulus);
        target = Math.floorMod(target, modulus);

        // Handle edge cases
        if (target == 1) return 0;
        if (base == 0) return -1;

        // m = ceil(sqrt(n)) where n is the group order (modulus-1 for prime)
        long m = (long) Math.ceil(Math.sqrt(modulus - 1));

        // Baby steps: store base^j for j = 0, 1, ..., m-1
        Map<Long, Long> babySteps = new HashMap<>();
        long current = 1;

        for (long j = 0; j < m; j++) {
            babySteps.putIfAbsent(current, j); // Store smallest j
            current = (current * base) % modulus;
        }

        // Compute base^(-m) = base^(modulus-1-m) using Fermat's little theorem
        // Since modulus is prime, base^(modulus-1) ≡ 1 (mod modulus)
        long baseInvM = modPow(base, modulus - 1 - m, modulus);

        // Giant steps: target * (base^(-m))^i for i = 0, 1, ..., m-1
        current = target;

        for (long i = 0; i < m; i++) {
            // Check if current value exists in baby steps
            if (babySteps.containsKey(current)) {
                long j = babySteps.get(current);
                long x = i * m + j;

                // Verify the solution
                if (modPow(base, x, modulus) == target % modulus) {
                    return x;
                }
            }
            current = (current * baseInvM) % modulus;
        }

        return -1; // No solution found
    }

    /**
     * Modular exponentiation: (base^exponent) % modulus
     */
    private static long modPow(long base, long exponent, long modulus) {
        long result = 1;
        base = base % modulus;

        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % modulus;
            }
            exponent >>= 1;
            base = (base * base) % modulus;
        }

        return result;
    }

    /**
     * Example usage with a 16-bit prime modulus
     */
    public static void main(String[] args) {
        // Using a 16-bit prime (65521 is the largest 16-bit prime)
        long modulus = 65521L;  // 2^16 - 15 = 65521 (prime)
        long base = 3L;         // Generator for the multiplicative group
        long target = 12345L;   // Target value

        System.out.println("Computing discrete logarithm:");
        System.out.println("Find x such that " + base + "^x ≡ " + target + " (mod " + modulus + ")");
        System.out.println();

        long startTime = System.nanoTime();
        long result = discreteLog(base, target, modulus);
        long endTime = System.nanoTime();

        if (result != -1) {
            System.out.println("Solution found: x = " + result);

            // Verify the result
            long verification = modPow(base, result, modulus);
            System.out.println("Verification: " + base + "^" + result + " mod " + modulus + 
                             " = " + verification);
            System.out.println("Target was: " + target);

            if (verification == target % modulus) {
                System.out.println("✓ Solution verified!");
            }
        } else {
            System.out.println("No solution found.");
        }

        System.out.printf("\nComputation time: %.3f ms\n", (endTime - startTime) / 1_000_000.0);

        // Additional test cases
        System.out.println("\n--- Additional Tests ---");

        // Test 1: Simple case
        long testBase = 2;
        long testExp = 42;
        long testTarget = modPow(testBase, testExp, modulus);
        long testResult = discreteLog(testBase, testTarget, modulus);
        System.out.println("Test 1: log_" + testBase + "(" + testTarget + ") = " + testResult + 
                          " (expected: " + testExp + ")");

        // Test 2: Edge case - target = 1
        testResult = discreteLog(base, 1, modulus);
        System.out.println("Test 2: log_" + base + "(1) = " + testResult + " (expected: 0)");
    }
}
```

## Key Points for Internal Documentation:

### Algorithm Overview:
1. **Baby Steps**: Precompute `base^j mod p` for `j = 0, 1, ..., m-1` and store in a hash map
2. **Giant Steps**: Compute `target * (base^(-m))^i mod p` for `i = 0, 1, ..., m-1` and check against baby steps
3. **Solution**: When a match is found, `x = i*m + j`

### Complexity:
- **Time**: O(√n) where n is group order
- **Space**: O(√n) for storing baby steps
- For 16-bit groups (n ≤ 65535): √n ≤ 256, very fast

### Important Notes:
1. The modulus should be prime for the multiplicative group to work correctly
2. The algorithm finds the smallest non-negative solution
3. Returns -1 if no solution exists
4. Uses Fermat's Little Theorem to compute `base^(-m)`

### Limitations:
- Memory usage grows with √n (problematic for large groups)
- For production use with larger groups, consider:
  - Using a proper BigInteger implementation
  - Adding time-memory trade-off optimizations
  - Implementing in a space-efficient way for very large groups

This implementation is suitable for educational purposes and small groups (≤16-bit). For cryptographic applications with large groups, specialized libraries should be used.

I'll provide a CP (Consistency-Partition tolerance) key-value store that prioritizes consistency over availability during network partitions. This implementation uses a simple majority quorum approach.

```python
import threading
import time
import socket
import json
from typing import Dict, Optional, Tuple, List
from enum import Enum
import logging

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class NodeState(Enum):
    LEADER = "leader"
    FOLLOWER = "follower"
    UNAVAILABLE = "unavailable"

class CPKeyValueStore:
    def __init__(self, node_id: str, nodes: List[Tuple[str, int]], port: int):
        """
        Initialize a CP key-value store node.

        Args:
            node_id: Unique identifier for this node
            nodes: List of (host, port) for all nodes in the cluster
            port: Port this node listens on
        """
        self.node_id = node_id
        self.nodes = nodes
        self.port = port

        # State
        self.state = NodeState.FOLLOWER
        self.data = {}
        self.term = 0
        self.commit_index = 0
        self.last_applied = 0

        # Quorum calculation
        self.quorum_size = len(nodes) // 2 + 1

        # Network partition simulation
        self.partitioned_nodes = set()

        # Locks for thread safety
        self.lock = threading.Lock()
        self.heartbeat_lock = threading.Lock()

        # Heartbeat tracking
        self.last_heartbeat = time.time()
        self.heartbeat_interval = 1.0
        self.election_timeout = 3.0

        # Start server
        self.server_thread = threading.Thread(target=self._start_server, daemon=True)
        self.server_thread.start()

        # Start background tasks
        threading.Thread(target=self._election_timer, daemon=True).start()
        threading.Thread(target=self._heartbeat_sender, daemon=True).start()

        logger.info(f"Node {node_id} started on port {port}")

    def _start_server(self):
        """Start TCP server to handle client requests and node communication."""
        server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server.bind(('localhost', self.port))
        server.listen(5)

        while True:
            try:
                client, addr = server.accept()
                threading.Thread(target=self._handle_connection, args=(client,), daemon=True).start()
            except Exception as e:
                logger.error(f"Server error: {e}")

    def _handle_connection(self, client: socket.socket):
        """Handle incoming connections."""
        try:
            data = client.recv(4096).decode('utf-8')
            if data:
                message = json.loads(data)
                response = self._process_message(message)
                client.send(json.dumps(response).encode('utf-8'))
        except Exception as e:
            logger.error(f"Connection error: {e}")
        finally:
            client.close()

    def _process_message(self, message: Dict) -> Dict:
        """Process incoming messages."""
        msg_type = message.get('type')

        if msg_type == 'heartbeat':
            return self._handle_heartbeat(message)
        elif msg_type == 'vote_request':
            return self._handle_vote_request(message)
        elif msg_type == 'vote_response':
            return self._handle_vote_response(message)
        elif msg_type == 'append_entries':
            return self._handle_append_entries(message)
        elif msg_type == 'client_request':
            return self._handle_client_request(message)
        elif msg_type == 'check_quorum':
            return self._handle_check_quorum(message)
        else:
            return {'type': 'error', 'message': 'Unknown message type'}

    def _handle_heartbeat(self, message: Dict) -> Dict:
        """Handle heartbeat from leader."""
        with self.heartbeat_lock:
            self.last_heartbeat = time.time()
            self.state = NodeState.FOLLOWER
            self.term = message.get('term', self.term)

            # Check if we're partitioned from the majority
            if self._is_in_minority_partition():
                self.state = NodeState.UNAVAILABLE
                return {'type': 'heartbeat_response', 'success': False, 'partitioned': True}

            return {'type': 'heartbeat_response', 'success': True}

    def _handle_vote_request(self, message: Dict) -> Dict:
        """Handle vote request for leader election."""
        candidate_term = message.get('term')
        candidate_id = message.get('candidate_id')

        # Check if we're partitioned
        if self._is_in_minority_partition():
            return {'type': 'vote_response', 'vote_granted': False, 'reason': 'partitioned'}

        # Standard Raft vote granting logic
        if candidate_term > self.term:
            self.term = candidate_term
            self.state = NodeState.FOLLOWER
            return {'type': 'vote_response', 'vote_granted': True}

        return {'type': 'vote_response', 'vote_granted': False}

    def _handle_append_entries(self, message: Dict) -> Dict:
        """Handle append entries (write operations) from leader."""
        # If we're in minority partition, reject writes
        if self._is_in_minority_partition():
            self.state = NodeState.UNAVAILABLE
            return {'type': 'append_response', 'success': False, 'partitioned': True}

        # Apply the operation
        operation = message.get('operation')
        key = message.get('key')
        value = message.get('value')

        with self.lock:
            if operation == 'set':
                self.data[key] = value
                return {'type': 'append_response', 'success': True}
            elif operation == 'delete':
                if key in self.data:
                    del self.data[key]
                    return {'type': 'append_response', 'success': True}
                return {'type': 'append_response', 'success': False}

        return {'type': 'append_response', 'success': False}

    def _handle_client_request(self, message: Dict) -> Dict:
        """Handle client read/write requests."""
        operation = message.get('operation')
        key = message.get('key')
        value = message.get('value')

        # Check if we can serve the request
        if self.state == NodeState.UNAVAILABLE:
            return {
                'type': 'client_response',
                'success': False,
                'error': 'Node unavailable due to network partition'
            }

        # Only leader handles writes
        if operation in ['set', 'delete'] and self.state != NodeState.LEADER:
            return {
                'type': 'client_response',
                'success': False,
                'error': 'Not the leader'
            }

        # For writes, need to achieve consensus
        if operation in ['set', 'delete']:
            success = self._replicate_operation(operation, key, value)
            return {
                'type': 'client_response',
                'success': success,
                'value': value if operation == 'set' else None
            }

        # For reads, serve from local state
        elif operation == 'get':
            with self.lock:
                value = self.data.get(key)
                return {
                    'type': 'client_response',
                    'success': value is not None,
                    'value': value
                }

        return {'type': 'client_response', 'success': False, 'error': 'Invalid operation'}

    def _handle_check_quorum(self, message: Dict) -> Dict:
        """Handle quorum check requests."""
        # If we're partitioned, respond with partitioned status
        if self._is_in_minority_partition():
            return {'type': 'quorum_response', 'available': False, 'partitioned': True}
        return {'type': 'quorum_response', 'available': True}

    def _replicate_operation(self, operation: str, key: str, value: Optional[str] = None) -> bool:
        """Replicate an operation to majority of nodes."""
        responses = []

        for node_host, node_port in self.nodes:
            if node_port == self.port:  # Skip self
                continue

            # Skip partitioned nodes
            if node_port in self.partitioned_nodes:
                continue

            try:
                response = self._send_message(
                    node_host, node_port,
                    {
                        'type': 'append_entries',
                        'operation': operation,
                        'key': key,
                        'value': value,
                        'term': self.term
                    }
                )
                if response and response.get('success'):
                    responses.append(True)
            except:
                pass

        # Count self
        responses.append(True)

        # Check if we have quorum
        if len(responses) >= self.quorum_size:
            # Apply locally
            with self.lock:
                if operation == 'set':
                    self.data[key] = value
                elif operation == 'delete' and key in self.data:
                    del self.data[key]
            return True

        return False

    def _is_in_minority_partition(self) -> bool:
        """Check if this node is in a minority partition."""
        # Simulate network partition - in real system, this would be detected
        # through heartbeat failures and quorum checks
        available_nodes = 1  # Count self

        for node_host, node_port in self.nodes:
            if node_port == self.port:
                continue

            # Skip if we've marked this node as partitioned
            if node_port in self.partitioned_nodes:
                continue

            try:
                response = self._send_message(
                    node_host, node_port,
                    {'type': 'check_quorum'}
                )
                if response and response.get('available'):
                    available_nodes += 1
            except:
                # Connection failed, node might be partitioned
                pass

        # If we can't reach a majority, we're in minority partition
        return available_nodes < self.quorum_size

    def _send_message(self, host: str, port: int, message: Dict) -> Optional[Dict]:
        """Send a message to another node."""
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(1.0)
            sock.connect((host, port))
            sock.send(json.dumps(message).encode('utf-8'))

            response = sock.recv(4096)
            sock.close()

            if response:
                return json.loads(response.decode('utf-8'))
        except Exception as e:
            logger.debug(f"Failed to send message to {host}:{port}: {e}")

        return None

    def _election_timer(self):
        """Background thread for leader election timeout."""
        while True:
            time.sleep(0.1)

            if self.state == NodeState.FOLLOWER:
                with self.heartbeat_lock:
                    if time.time() - self.last_heartbeat > self.election_timeout:
                        # Start election
                        self._start_election()

    def _start_election(self):
        """Start a leader election."""
        logger.info(f"Node {self.node_id} starting election for term {self.term + 1}")

        self.term += 1
        votes_received = 1  # Vote for self

        for node_host, node_port in self.nodes:
            if node_port == self.port:
                continue

            try:
                response = self._send_message(
                    node_host, node_port,
                    {
                        'type': 'vote_request',
                        'term': self.term,
                        'candidate_id': self.node_id
                    }
                )

                if response and response.get('vote_granted'):
                    votes_received += 1
            except:
                pass

        # Check if we won the election
        if votes_received >= self.quorum_size:
            self.state = NodeState.LEADER
            logger.info(f"Node {self.node_id} elected as leader for term {self.term}")
        else:
            self.state = NodeState.FOLLOWER

    def _heartbeat_sender(self):
        """Background thread for sending heartbeats (if leader)."""
        while True:
            time.sleep(self.heartbeat_interval)

            if self.state == NodeState.LEADER:
                # Check if we still have quorum
                if self._is_in_minority_partition():
                    self.state = NodeState.UNAVAILABLE
                    logger.warning(f"Leader {self.node_id} lost quorum, becoming unavailable")
                    continue

                # Send heartbeats to followers
                for node_host, node_port in self.nodes:
                    if node_port == self.port:
                        continue

                    try:
                        self._send_message(
                            node_host, node_port,
                            {
                                'type': 'heartbeat',
                                'term': self.term,
                                'leader_id': self.node_id
                            }
                        )
                    except:
                        pass

    def set_partition(self, node_ports: List[int]):
        """Simulate a network partition affecting specific nodes."""
        self.partitioned_nodes = set(node_ports)
        logger.info(f"Node {self.node_id} partition set: {self.partitioned_nodes}")

        # Re-evaluate our state
        if self._is_in_minority_partition():
            self.state = NodeState.UNAVAILABLE

    def clear_partition(self):
        """Clear simulated network partition."""
        self.partitioned_nodes.clear()
        logger.info(f"Node {self.node_id} partition cleared")

    # Client API
    def set(self, key: str, value: str) -> bool:
        """Set a key-value pair."""
        response = self._send_message(
            'localhost', self.port,
            {
                'type': 'client_request',
                'operation': 'set',
                'key': key,
                'value': value
            }
        )
        return response.get('success', False) if response else False

    def get(self, key: str) -> Optional[str]:
        """Get a value by key."""
        response = self._send_message(
            'localhost', self.port,
            {
                'type': 'client_request',
                'operation': 'get',
                'key': key
            }
        )
        return response.get('value') if response and response.get('success') else None

    def delete(self, key: str) -> bool:
        """Delete a key."""
        response = self._send_message(
            'localhost', self.port,
            {
                'type': 'client_request',
                'operation': 'delete',
                'key': key
            }
        )
        return response.get('success', False) if response else False


# Example usage and test
def run_demo():
    """Run a demonstration of the CP key-value store."""
    # Create a 3-node cluster
    nodes = [('localhost', 5001), ('localhost', 5002), ('localhost', 5003)]

    # Start nodes
    node1 = CPKeyValueStore("node1", nodes, 5001)
    node2 = CPKeyValueStore("node2", nodes, 5002)
    node3 = CPKeyValueStore("node3", nodes, 5003)

    time.sleep(2)  # Wait for election

    # Test normal operation
    print("\n=== Normal Operation ===")
    leader_port = 5001  # Assuming node1 becomes leader
    if node1.set("key1", "value1"):
        print("Write successful")

    value = node1.get("key1")
    print(f"Read key1: {value}")

    # Simulate network partition isolating node1
    print("\n=== Network Partition (node1 isolated) ===")
    node1.set_partition([5002, 5003])  # node1 cannot reach others
    node2.set_partition([5001])  # node2 cannot reach node1
    node3.set_partition([5001])  # node3 cannot reach node1

    time.sleep(2)

    # Try to write through node1 (should fail - minority partition)
    if not node1.set("key2", "value2"):
        print("Write failed as expected - node1 is in minority partition")

    # Try to write through node2 (should succeed - majority partition)
    if node2.set("key2", "value2"):
        print("Write successful through node2 (majority)")

    # Read from node1 (should fail - unavailable)
    value = node1.get("key2")
    print(f"Read from partitioned node1: {value}")

    # Read from node2 (should succeed)
    value = node2.get("key2")
    print(f"Read from node2: {value}")

    # Heal partition
    print("\n=== Partition Healed ===")
    node1.clear_partition()
    node2.clear_partition()
    node3.clear_partition()

    time.sleep(2)

    # All nodes should be available again
    value = node1.get("key2")
    print(f"Read from node1 after healing: {value}")

if __name__ == "__main__":
    run_demo()
```

## How It Works:

### **CP (Consistency-Partition tolerance) Design:**
1. **Consistency First**: The system prioritizes data consistency over availability
2. **Quorum-based Operations**: All writes require acknowledgment from a majority of nodes
3. **Partition Handling**: Nodes in the minority side of a partition become unavailable

### **Key Components:**

1. **Leader Election**: 
   - Uses a Raft-like election protocol
   - Only nodes that can communicate with a majority can become leaders

2. **Quorum Management**:
   - Calculates `quorum_size = n/2 + 1`
   - Operations require quorum acknowledgment
   - Nodes check quorum membership via heartbeat responses

3. **Partition Detection**:
   - Nodes periodically check connectivity to peers
   - If a node cannot reach a majority, it transitions to `UNAVAILABLE` state
   - Unavailable nodes reject all client requests

4. **Failure Handling**:
   - **Minority Partition**: Nodes become unavailable, preserving consistency
   - **Majority Partition**: Continue operating normally
   - **Network Healing**: Nodes automatically rejoin when connectivity is restored

### **Behavior During Partitions:**
- **Minority Side**: All nodes become unavailable, rejecting reads and writes
- **Majority Side**: Continue operating normally with full consistency
- **Client Requests**: Fail fast with clear error messages when node is unavailable

### **Trade-offs:**
- ✅ **Strong Consistency**: All successful operations are durable and consistent
- ✅ **Clear Failure Modes**: Clients get explicit "unavailable" errors
- ❌ **Reduced Availability**: Minority partitions cannot serve requests
- ❌ **Complexity**: Requires quorum management and leader election

This implementation ensures that during network partitions, the system maintains consistency by making the minority side unavailable, preventing split-brain scenarios and inconsistent data.

I'll show you how to build a minimal perfect hash function (MPHF) in Rust. Here's a complete implementation using the CHD algorithm (Hash, Displace and Compress), which is efficient and practical:

## 1. Basic Implementation

```rust
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::marker::PhantomData;

pub struct MinimalPerfectHash<K: Hash> {
    // First-level hash table
    first_level: Vec<u32>,
    // Second-level hash table with displacement values
    second_level: Vec<u32>,
    // Number of buckets in first level
    bucket_count: usize,
    // Phantom data to hold key type
    _marker: PhantomData<K>,
}

impl<K: Hash> MinimalPerfectHash<K> {
    /// Create a minimal perfect hash for the given keys
    pub fn new(keys: &[K]) -> Self {
        let n = keys.len();

        // Choose bucket count (typically n/4 to n/2)
        let bucket_count = (n / 4).max(1);

        // Step 1: Distribute keys into buckets
        let mut buckets: Vec<Vec<&K>> = vec![Vec::new(); bucket_count];

        for key in keys {
            let hash = Self::hash1(key) as usize % bucket_count;
            buckets[hash].push(key);
        }

        // Sort buckets by size (largest first) for better distribution
        let mut sorted_buckets: Vec<_> = buckets.into_iter().enumerate().collect();
        sorted_buckets.sort_by(|a, b| b.1.len().cmp(&a.1.len()));

        // Step 2: Build displacement table
        let mut second_level = vec![0; n];
        let mut occupied = vec![false; n];
        let mut first_level = vec![0; bucket_count];

        for (bucket_idx, bucket_keys) in sorted_buckets {
            if bucket_keys.is_empty() {
                continue;
            }

            // Try different displacement values
            let mut displacement = 0u32;
            let mut success = false;

            while !success {
                success = true;
                let mut temp_occupied = occupied.clone();

                for &key in &bucket_keys {
                    let hash = (Self::hash2(key).wrapping_add(displacement) as usize) % n;

                    if temp_occupied[hash] {
                        success = false;
                        break;
                    }
                    temp_occupied[hash] = true;
                }

                if success {
                    first_level[bucket_idx] = displacement;
                    for &key in &bucket_keys {
                        let hash = (Self::hash2(key).wrapping_add(displacement) as usize) % n;
                        second_level[hash] = Self::hash3(key);
                        occupied[hash] = true;
                    }
                } else {
                    displacement += 1;
                }
            }
        }

        Self {
            first_level,
            second_level,
            bucket_count,
            _marker: PhantomData,
        }
    }

    /// Get the perfect hash value for a key (0..n-1)
    pub fn get(&self, key: &K) -> Option<usize> {
        let bucket_hash = Self::hash1(key) as usize % self.bucket_count;
        let displacement = self.first_level[bucket_hash];

        let hash = (Self::hash2(key).wrapping_add(displacement) as usize) % self.second_level.len();

        // Verify with third hash to handle collisions
        if self.second_level[hash] == Self::hash3(key) {
            Some(hash)
        } else {
            None
        }
    }

    /// First hash function
    fn hash1(key: &K) -> u64 {
        let mut hasher = DefaultHasher::new();
        key.hash(&mut hasher);
        hasher.finish()
    }

    /// Second hash function (different seed)
    fn hash2(key: &K) -> u64 {
        let mut hasher = DefaultHasher::new();
        // Use a different seed by hashing a constant
        0xdeadbeef.hash(&mut hasher);
        key.hash(&mut hasher);
        hasher.finish()
    }

    /// Third hash function for verification
    fn hash3(key: &K) -> u32 {
        let mut hasher = DefaultHasher::new();
        0xcafebabe.hash(&mut hasher);
        key.hash(&mut hasher);
        (hasher.finish() & 0xFFFFFFFF) as u32
    }
}

impl<K: Hash> std::fmt::Debug for MinimalPerfectHash<K> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "MinimalPerfectHash {{ size: {} }}", self.second_level.len())
    }
}
```

