pub struct MPHBuilder<K: Hash> {
    keys: Vec<K>,
}

impl<K: Hash> MPHBuilder<K> {
    pub fn new() -> Self {
        Self { keys: Vec::new() }
    }

    pub fn add_key(mut self, key: K) -> Self {
        self.keys.push(key);
        self
    }

    pub fn add_keys<I>(mut self, keys: I) -> Self 
    where
        I: IntoIterator<Item = K>
    {
        self.keys.extend(keys);
        self
    }

    pub fn build(self) -> MinimalPerfectHash<K> {
        MinimalPerfectHash::new(&self.keys)
    }
}
