## 4. Advanced Version with Better Hashing

```rust
use twox_hash::XxHash64;
use std::hash::Hasher;

pub struct AdvancedMPH<K: Hash> {
    displacements: Vec<u32>,
    fingerprints: Vec<u32>,
    bucket_mask: usize,
}

impl<K: Hash> AdvancedMPH<K> {
    pub fn new(keys: &[K]) -> Self {
        let n = keys.len();
        let bucket_count = (n * 3 / 4).next_power_of_two();
        let bucket_mask = bucket_count - 1;

        // Use xxHash for better distribution
        let mut buckets: Vec<Vec<(u64, &K)>> = vec![Vec::new(); bucket_count];

        for key in keys {
            let hash = Self::xxhash(key, 0);
            buckets[(hash as usize) & bucket_mask].push((hash, key));
        }

        // Sort by bucket size
        let mut sorted_buckets: Vec<_> = buckets.into_iter().enumerate().collect();
        sorted_buckets.sort_by(|a, b| b.1.len().cmp(&a.1.len()));

        let mut displacements = vec![0; bucket_count];
        let mut fingerprints = vec![0; n];
        let mut occupied = vec![false; n];

        for (bucket_idx, bucket) in sorted_buckets {
            if bucket.is_empty() {
                continue;
            }

            let mut d = 0u32;
            'displacement: loop {
                let mut temp_occupied = occupied.clone();

                for &(hash, key) in &bucket {
                    let idx = (hash.wrapping_add(d as u64) as usize) % n;

                    if temp_occupied[idx] {
                        d += 1;
                        continue 'displacement;
                    }
                    temp_occupied[idx] = true;
                }

                // Found valid displacement
                displacements[bucket_idx] = d;
                for &(hash, key) in &bucket {
                    let idx = (hash.wrapping_add(d as u64) as usize) % n;
                    fingerprints[idx] = Self::fingerprint(key);
                    occupied[idx] = true;
                }
                break;
            }
        }

        Self {
            displacements,
            fingerprints,
            bucket_mask,
        }
    }

    pub fn get(&self, key: &K) -> Option<usize> {
        let hash = Self::xxhash(key, 0);
        let bucket_idx = (hash as usize) & self.bucket_mask;
        let d = self.displacements[bucket_idx];

        let idx = (hash.wrapping_add(d as u64) as usize) % self.fingerprints.len();

        if self.fingerprints[idx] == Self::fingerprint(key) {
            Some(idx)
        } else {
            None
        }
    }

    fn xxhash(key: &K, seed: u64) -> u64 {
        let mut hasher = XxHash64::with_seed(seed);
        key.hash(&mut hasher);
        hasher.finish()
    }

    fn fingerprint(key: &K) -> u32 {
        (Self::xxhash(key, 1) & 0xFFFFFFFF) as u32
    }
}
```

## Key Points:

1. **Minimal Perfect Hash**: Maps N keys to 0..N-1 with no collisions
2. **Two-level hashing**: First level distributes to buckets, second level resolves collisions
3. **Static/Compile-time**: Best for fixed key sets (build once, use many times)
4. **Memory efficient**: Uses ~2-4 bits per key in practice

