typedef struct {
    uint64_t h1;
    uint64_t h2;
} hash128_t;

// Rotate left helper
static inline uint64_t rotl64(uint64_t x, int r) {
    return (x << r) | (x >> (64 - r));
}

// Mixing function (based on MurmurHash3 finalizer)
static inline uint64_t fmix64(uint64_t k) {
    k ^= k >> 33;
    k *= 0xff51afd7ed558ccdULL;
    k ^= k >> 33;
    k *= 0xc4ceb9fe1a85ec53ULL;
    k ^= k >> 33;
    return k;
}

// Main hash function
hash128_t hash128(const void *data, size_t len, uint64_t seed) {
    const uint8_t *bytes = (const uint8_t *)data;
    const size_t nblocks = len / 16;

    uint64_t h1 = seed;
    uint64_t h2 = seed;

    const uint64_t c1 = 0x87c37b91114253d5ULL;
    const uint64_t c2 = 0x4cf5ad432745937fULL;

    // Process 128-bit blocks
    const uint64_t *blocks = (const uint64_t *)bytes;
    for (size_t i = 0; i < nblocks; i++) {
        uint64_t k1 = blocks[i * 2];
        uint64_t k2 = blocks[i * 2 + 1];

        k1 *= c1; k1 = rotl64(k1, 31); k1 *= c2;
        h1 ^= k1;
        h1 = rotl64(h1, 27); h1 += h2; h1 = h1 * 5 + 0x52dce729;

        k2 *= c2; k2 = rotl64(k2, 33); k2 *= c1;
        h2 ^= k2;
        h2 = rotl64(h2, 31); h2 += h1; h2 = h2 * 5 + 0x38495ab5;
    }

    // Process remaining bytes
    const uint8_t *tail = bytes + nblocks * 16;
    uint64_t k1 = 0;
    uint64_t k2 = 0;

    switch (len & 15) {
        case 15: k2 ^= ((uint64_t)tail[14]) << 48;
        case 14: k2 ^= ((uint64_t)tail[13]) << 40;
        case 13: k2 ^= ((uint64_t)tail[12]) << 32;
        case 12: k2 ^= ((uint64_t)tail[11]) << 24;
        case 11: k2 ^= ((uint64_t)tail[10]) << 16;
        case 10: k2 ^= ((uint64_t)tail[9]) << 8;
        case  9: k2 ^= ((uint64_t)tail[8]) << 0;
                 k2 *= c2; k2 = rotl64(k2, 33); k2 *= c1; h2 ^= k2;

        case  8: k1 ^= ((uint64_t)tail[7]) << 56;
        case  7: k1 ^= ((uint64_t)tail[6]) << 48;
        case  6: k1 ^= ((uint64_t)tail[5]) << 40;
        case  5: k1 ^= ((uint64_t)tail[4]) << 32;
        case  4: k1 ^= ((uint64_t)tail[3]) << 24;
        case  3: k1 ^= ((uint64_t)tail[2]) << 16;
        case  2: k1 ^= ((uint64_t)tail[1]) << 8;
        case  1: k1 ^= ((uint64_t)tail[0]) << 0;
                 k1 *= c1; k1 = rotl64(k1, 31); k1 *= c2; h1 ^= k1;
    }

    // Finalization
    h1 ^= len;
    h2 ^= len;

    h1 += h2;
    h2 += h1;

    h1 = fmix64(h1);
    h2 = fmix64(h2);

    h1 += h2;
    h2 += h1;

    hash128_t result = {h1, h2};
    return result;
}

// Helper function to compare two hashes
int hash128_equal(hash128_t a, hash128_t b) {
    return (a.h1 == b.h1) && (a.h2 == b.h2);
}

// Example usage
#include <stdio.h>

int main() {
    const char *test1 = "Hello, world!";
    const char *test2 = "Hello, world?";

    hash128_t h1 = hash128(test1, strlen(test1), 0);
    hash128_t h2 = hash128(test2, strlen(test2), 0);

    printf("Hash 1: %016llx%016llx\n", h1.h1, h1.h2);
    printf("Hash 2: %016llx%016llx\n", h2.h1, h2.h2);
    printf("Equal: %s\n", hash128_equal(h1, h2) ? "yes" : "no");

    return 0;
}
```

## How It Works:

1. **128-bit Output**: The hash produces two 64-bit values (h1 and h2) for a 128-bit result.

2. **Avalanche Effect**: 
   - Uses rotation operations (`rotl64`) to diffuse bits
   - Multiplication by large prime constants spreads changes
   - The `fmix64` finalizer ensures all input bits affect all output bits

3. **Processing**:
   - Processes data in 128-bit (16-byte) blocks
   - Each block undergoes multiple mixing operations
   - Handles remaining bytes with a switch statement

4. **Key Techniques**:
   - **Rotation**: Circular bit shifts (31, 33, 27 positions) for bit diffusion
   - **Multiplication**: By carefully chosen constants to avalanche bits
   - **XOR mixing**: Combines internal state with input data
   - **Finalization**: Additional mixing to ensure uniform distribution

5. **Collision Resistance**:
   - Each input bit affects multiple internal state bits quickly
   - Non-linear operations (multiplication, XOR) prevent simple collisions
   - The 128-bit output space makes accidental collisions extremely unlikely

This design is inspired by established hash functions like MurmurHash3 and CityHash, providing good practical performance while maintaining strong avalanche behavior. The seed parameter allows for different hash values from the same input, useful for preventing hash-flooding attacks.

Here's a minimal working example showing where `atomic_thread_fence` is necessary for correct ordering:

```cpp
#include <atomic>
#include <thread>
#include <iostream>
#include <cassert>

// Shared data
struct Data {
    int x = 0;
    int y = 0;
};

Data data;
std::atomic<bool> ready(false);

// Thread 1: Producer
void producer() {
    // Non-atomic writes to shared data
    data.x = 42;
    data.y = 100;

    // Memory fence ensures all writes above complete before this store
    std::atomic_thread_fence(std::memory_order_release);

    // Signal that data is ready
    ready.store(true, std::memory_order_relaxed);
}

// Thread 2: Consumer
void consumer() {
    // Wait for the signal
    while (!ready.load(std::memory_order_relaxed)) {
        // spin
    }

    // Memory fence ensures this load happens after the fence in producer
    std::atomic_thread_fence(std::memory_order_acquire);

    // Now we can safely read the data
    std::cout << "x = " << data.x << ", y = " << data.y << std::endl;
    assert(data.x == 42);  // Should hold with proper fencing
    assert(data.y == 100); // Should hold with proper fencing
}

int main() {
    std::thread t1(producer);
    std::thread t2(consumer);

    t1.join();
    t2.join();

    return 0;
}
```

## Key Points:

1. **Without the fences**: The compiler/CPU could reorder operations, potentially allowing the consumer to see `ready == true` but stale values of `data.x` and `data.y`.

2. **With fences**:
   - `release` fence in producer: Ensures all writes before the fence are visible to other threads before any write after the fence
   - `acquire` fence in consumer: Ensures all reads after the fence see the effects of writes that happened before a matching release fence

3. **Alternative using atomic operations directly** (often cleaner):
```cpp
// Producer
data.x = 42;
data.y = 100;
ready.store(true, std::memory_order_release);  // Implicit release fence

// Consumer
while (!ready.load(std::memory_order_acquire)) {}  // Implicit acquire fence
// Now safe to read data
```

## When to use `atomic_thread_fence` directly:

1. **Multiple atomics with single fence**:
```cpp
// More efficient than multiple release/acquire operations
std::atomic_thread_fence(std::memory_order_release);
atomic1.store(val1, std::memory_order_relaxed);
atomic2.store(val2, std::memory_order_relaxed);
atomic3.store(val3, std::memory_order_relaxed);
```

2. **Non-atomic to atomic synchronization** (as shown in the example)

3. **Complex synchronization patterns** where you need fine-grained control

## Memory Ordering Options:

- `memory_order_relaxed`: No ordering guarantees
- `memory_order_acquire`: No reads/writes can move before this load
- `memory_order_release`: No reads/writes can move after this store  
- `memory_order_acq_rel`: Both acquire and release semantics
- `memory_order_seq_cst`: Sequential consistency (strongest, default)

The example demonstrates the classic "release-acquire" pattern using fences, which is essential when synchronizing non-atomic data through an atomic flag.

Here's an implementation using C++11's `std::atomic`:

```cpp
#include <atomic>
#include <cstdint>

class AtomicCounter {
private:
    std::atomic<int64_t> counter_{0};

public:
    // Increment the counter by 1 and return the new value
    int64_t increment() {
        return ++counter_;
    }

    // Decrement the counter by 1 and return the new value
    int64_t decrement() {
        return --counter_;
    }

    // Add a specific value to the counter and return the new value
    int64_t add(int64_t value) {
        return counter_.fetch_add(value, std::memory_order_acq_rel) + value;
    }

    // Subtract a specific value from the counter and return the new value
    int64_t subtract(int64_t value) {
        return counter_.fetch_sub(value, std::memory_order_acq_rel) - value;
    }

    // Get the current value
    int64_t get() const {
        return counter_.load(std::memory_order_acquire);
    }

    // Set the counter to a specific value
    void set(int64_t value) {
        counter_.store(value, std::memory_order_release);
    }

    // Compare and swap: set to new_value only if current value == expected
    bool compare_and_swap(int64_t expected, int64_t new_value) {
        return counter_.compare_exchange_strong(expected, new_value,
                                                std::memory_order_acq_rel);
    }
};
```

## How It Works:

1. **Atomic Operations**: `std::atomic<int64_t>` ensures that all operations on the 64-bit integer are atomic - they complete without interruption from other threads.

2. **Memory Ordering**: The code uses specific memory orderings:
   - `memory_order_acq_rel`: For read-modify-write operations (acquire-release semantics)
   - `memory_order_acquire`: For loads (ensures subsequent reads see writes from other threads)
   - `memory_order_release`: For stores (ensures previous writes are visible to other threads)

3. **Thread Safety**: Multiple threads can safely call these methods concurrently without data races.

4. **Key Operations**:
   - `fetch_add()`/`fetch_sub()`: Atomically add/subtract and return the old value
   - `load()`/`store()`: Atomic read/write
   - `compare_exchange_strong()`: Atomic compare-and-swap (CAS) operation

## Usage Example:
```cpp
#include <iostream>
#include <thread>
#include <vector>

int main() {
    AtomicCounter counter;
    std::vector<std::thread> threads;

    // Launch 10 threads that each increment 1000 times
    for (int i = 0; i < 10; ++i) {
        threads.emplace_back([&counter]() {
            for (int j = 0; j < 1000; ++j) {
                counter.increment();
            }
        });
    }

    // Wait for all threads
    for (auto& t : threads) {
        t.join();
    }

    std::cout << "Final counter value: " << counter.get() << std::endl;
    // Output: Final counter value: 10000
    return 0;
}
```

This implementation provides a thread-safe 64-bit counter that works correctly across all modern platforms, even on 32-bit systems where 64-bit operations might not be naturally atomic.

Here are several ways to copy data to the GPU and synchronize in C++ using CUDA:

## 1. **Basic CUDA Memory Copy with Stream Synchronization**

```cpp
#include <iostream>
#include <cuda_runtime.h>

#define CHECK_CUDA(call) { \
    cudaError_t err = call; \
    if (err != cudaSuccess) { \
        std::cerr << "CUDA error: " << cudaGetErrorString(err) \
                  << " at " << __FILE__ << ":" << __LINE__ << std::endl; \
        exit(EXIT_FAILURE); \
    } \
}

int main() {
    const size_t N = 1024;
    const size_t size = N * sizeof(float);

    // Host memory
    float *h_data = new float[N];
    float *h_result = new float[N];

    // Initialize host data
    for (size_t i = 0; i < N; i++) {
        h_data[i] = static_cast<float>(i);
    }

    // Device memory
    float *d_data = nullptr;
    float *d_result = nullptr;

    // Create CUDA stream
    cudaStream_t stream;
    CHECK_CUDA(cudaStreamCreate(&stream));

    // Allocate device memory
    CHECK_CUDA(cudaMalloc(&d_data, size));
    CHECK_CUDA(cudaMalloc(&d_result, size));

    // Copy data to device (async with stream)
    CHECK_CUDA(cudaMemcpyAsync(d_data, h_data, size, 
                               cudaMemcpyHostToDevice, stream));

    // Synchronize stream to ensure copy is complete
    CHECK_CUDA(cudaStreamSynchronize(stream));

    // --- Your kernel execution would go here ---
    // Example: myKernel<<<blocks, threads, 0, stream>>>(d_data, d_result, N);

    // Copy results back from device (async with stream)
    CHECK_CUDA(cudaMemcpyAsync(h_result, d_result, size, 
                               cudaMemcpyDeviceToHost, stream));

    // Synchronize stream to ensure copy back is complete
    CHECK_CUDA(cudaStreamSynchronize(stream));

    // Alternative: Wait for all operations in stream to complete
    // CHECK_CUDA(cudaStreamSynchronize(stream));

    // Cleanup
    CHECK_CUDA(cudaFree(d_data));
    CHECK_CUDA(cudaFree(d_result));
    CHECK_CUDA(cudaStreamDestroy(stream));

    delete[] h_data;
    delete[] h_result;

    return 0;
}
```

## 2. **Using Events for Precise Synchronization**

```cpp
#include <iostream>
#include <cuda_runtime.h>

#define CHECK_CUDA(call) { /* same as above */ }

__global__ void processData(float* data, float* result, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N) {
        result[idx] = data[idx] * 2.0f;  // Simple processing
    }
}

int main() {
    const size_t N = 1024;
    const size_t size = N * sizeof(float);

    // Host memory
    float *h_data = new float[N];
    float *h_result = new float[N];

    // Initialize
    for (size_t i = 0; i < N; i++) {
        h_data[i] = static_cast<float>(i);
    }

    // Device memory
    float *d_data = nullptr;
    float *d_result = nullptr;

    // Create stream and events
    cudaStream_t stream;
    cudaEvent_t startEvent, stopEvent, copyEvent;

    CHECK_CUDA(cudaStreamCreate(&stream));
    CHECK_CUDA(cudaEventCreate(&startEvent));
    CHECK_CUDA(cudaEventCreate(&stopEvent));
    CHECK_CUDA(cudaEventCreate(&copyEvent));

    // Allocate device memory
    CHECK_CUDA(cudaMalloc(&d_data, size));
    CHECK_CUDA(cudaMalloc(&d_result, size));

    // Record start event
    CHECK_CUDA(cudaEventRecord(startEvent, stream));

    // Async copy to device
    CHECK_CUDA(cudaMemcpyAsync(d_data, h_data, size, 
                               cudaMemcpyHostToDevice, stream));

    // Record event after copy
    CHECK_CUDA(cudaEventRecord(copyEvent, stream));

    // Wait for copy to complete before launching kernel
    CHECK_CUDA(cudaStreamWaitEvent(stream, copyEvent, 0));

    // Launch kernel
    const int blockSize = 256;
    const int gridSize = (N + blockSize - 1) / blockSize;
    processData<<<gridSize, blockSize, 0, stream>>>(d_data, d_result, N);

    // Record event after kernel
    CHECK_CUDA(cudaEventRecord(stopEvent, stream));

    // Async copy back results
    CHECK_CUDA(cudaMemcpyAsync(h_result, d_result, size, 
                               cudaMemcpyDeviceToHost, stream));

    // Synchronize the stream (waits for all operations)
    CHECK_CUDA(cudaStreamSynchronize(stream));

    // Calculate elapsed time
    float milliseconds = 0;
    CHECK_CUDA(cudaEventElapsedTime(&milliseconds, startEvent, stopEvent));
    std::cout << "Kernel execution time: " << milliseconds << " ms" << std::endl;

    // Verify results
    for (size_t i = 0; i < N; i++) {
        if (h_result[i] != h_data[i] * 2.0f) {
            std::cerr << "Mismatch at index " << i << std::endl;
            break;
        }
    }

    // Cleanup
    CHECK_CUDA(cudaFree(d_data));
    CHECK_CUDA(cudaFree(d_result));
    CHECK_CUDA(cudaStreamDestroy(stream));
    CHECK_CUDA(cudaEventDestroy(startEvent));
    CHECK_CUDA(cudaEventDestroy(stopEvent));
    CHECK_CUDA(cudaEventDestroy(copyEvent));

    delete[] h_data;
    delete[] h_result;

    return 0;
}
```

## 3. **Simplified Version with Default Stream**

```cpp
#include <iostream>
#include <cuda_runtime.h>

int main() {
    const size_t N = 1024;
    const size_t size = N * sizeof(float);

    // Host memory
    float *h_data = new float[N];
    float *h_result = new float[N];

    // Initialize
    for (size_t i = 0; i < N; i++) {
        h_data[i] = static_cast<float>(i);
    }

    // Device memory
    float *d_data = nullptr;
    float *d_result = nullptr;

    // Allocate
    cudaMalloc(&d_data, size);
    cudaMalloc(&d_result, size);

    // Copy to device (synchronous - blocks CPU)
    cudaMemcpy(d_data, h_data, size, cudaMemcpyHostToDevice);

    // --- Your kernel would go here ---
    // myKernel<<<blocks, threads>>>(d_data, d_result, N);

    // Synchronize device (waits for all kernels to complete)
    cudaDeviceSynchronize();

    // Copy back results
    cudaMemcpy(h_result, d_result, size, cudaMemcpyDeviceToHost);

