    cudaFree(d_data);
    cudaFree(d_result);

    delete[] h_data;
    delete[] h_result;

    return 0;
}
```

## Key Points:

1. **Async vs Sync Copies**:
   - `cudaMemcpyAsync()`: Non-blocking, requires stream
   - `cudaMemcpy()`: Blocking, uses default stream

2. **Synchronization Methods**:
   - `cudaStreamSynchronize(stream)`: Wait for specific stream
   - `cudaDeviceSynchronize()`: Wait for all streams
   - `cudaEventSynchronize(event)`: Wait for specific event

3. **Best Practices**:
   - Use streams for overlapping computation and data transfer
   - Use events for timing and precise synchronization
   - Always check CUDA errors (use macros like `CHECK_CUDA`)
   - Prefer async operations with streams for better performance

4. **Compilation**:
   ```bash
   nvcc -o program program.cu -std=c++11
   ```

Choose approach 1 for basic stream usage, approach 2 for precise timing/control, or approach 3 for simple synchronous operations.

Here's an example of using `fetch_add` on an atomic counter in C++:

```cpp
#include <atomic>
#include <iostream>

int main() {
    std::atomic<int> counter{0};

    // fetch_add atomically adds to the counter and returns the old value
    int old_value = counter.fetch_add(5);

    std::cout << "Old value: " << old_value << std::endl;  // Output: 0
    std::cout << "New value: " << counter.load() << std::endl;  // Output: 5

    // Another thread-safe increment
    old_value = counter.fetch_add(3);
    std::cout << "Old value: " << old_value << std::endl;  // Output: 5
    std::cout << "New value: " << counter.load() << std::endl;  // Output: 8

    return 0;
}
```

## How `fetch_add` works:

**Atomic Operation**: `fetch_add` performs the addition as a single, indivisible operation. This means:
- No other thread can see an intermediate state
- The operation is guaranteed to complete without interruption from other threads

**Two-step process** (atomic):
1. **Read** the current value
2. **Add** the specified amount and store the result

**Return value**: It returns the **old value** (before the addition), not the new value.

**Memory ordering**: By default, it uses `memory_order_seq_cst` (sequential consistency), ensuring:
- No reordering of memory operations across the atomic operation
- All threads see the same order of modifications

## Thread-safe example:
```cpp
#include <atomic>
#include <thread>
#include <vector>

std::atomic<int> shared_counter{0};

void increment_counter(int times) {
    for (int i = 0; i < times; ++i) {
        shared_counter.fetch_add(1);  // Thread-safe increment
    }
}

int main() {
    std::vector<std::thread> threads;

    // Create 10 threads that each increment 1000 times
    for (int i = 0; i < 10; ++i) {
        threads.emplace_back(increment_counter, 1000);
    }

    // Wait for all threads
    for (auto& t : threads) {
        t.join();
    }

    // Result will always be 10000 (10 threads × 1000 increments)
    std::cout << "Final counter: " << shared_counter << std::endl;

    return 0;
}
```

## Key points:
1. **Thread-safe**: Multiple threads can safely call `fetch_add` concurrently
2. **No data races**: The operation prevents race conditions
3. **Use cases**: Reference counting, statistics gathering, ID generation, etc.
4. **Alternatives**: `fetch_sub` for subtraction, `exchange` for swap, `compare_exchange` for conditional updates

The atomicity ensures that even if multiple threads increment simultaneously, every increment is properly counted without lost updates.

Here's a working example using `CLOCK_MONOTONIC` with `clock_gettime()`:

```c
#include <stdio.h>
#include <time.h>
#include <unistd.h>

// Function to get current monotonic time in nanoseconds
long long get_monotonic_time_ns() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
}

// Function to get current monotonic time in milliseconds
long long get_monotonic_time_ms() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;
}

int main() {
    // Example 1: Simple timing measurement
    long long start = get_monotonic_time_ns();

    // Simulate some work
    for (int i = 0; i < 1000000; i++) {
        // Some dummy work
    }

    long long end = get_monotonic_time_ns();
    long long elapsed_ns = end - start;

    printf("Elapsed time: %lld ns (%.3f ms)\n", 
           elapsed_ns, elapsed_ns / 1000000.0);

    // Example 2: Timing a sleep operation
    start = get_monotonic_time_ms();
    usleep(500000); // Sleep for 500ms
    end = get_monotonic_time_ms();

    printf("Sleep duration: %lld ms\n", end - start);

    // Example 3: Using timespec directly
    struct timespec ts1, ts2;
    clock_gettime(CLOCK_MONOTONIC, &ts1);
    usleep(100000); // 100ms
    clock_gettime(CLOCK_MONOTONIC, &ts2);

    // Calculate difference manually
    long diff_ns = (ts2.tv_sec - ts1.tv_sec) * 1000000000L + 
                   (ts2.tv_nsec - ts1.tv_nsec);
    printf("Direct calculation: %ld ns\n", diff_ns);

    return 0;
}
```

**Compile with:**
```bash
gcc -o monotonic_timer monotonic_timer.c -lrt
```

## How it works:

1. **`CLOCK_MONOTONIC` vs `CLOCK_REALTIME`:**
   - `CLOCK_MONOTONIC`: Counts time from an arbitrary point (usually system boot). It's **monotonic** - always increases at a constant rate and is unaffected by system time changes (NTP adjustments, manual time changes).
   - `CLOCK_REALTIME`: System wall-clock time that can jump forward/backward if the system time is adjusted.

2. **`clock_gettime()` function:**
   - Takes two parameters: the clock type (`CLOCK_MONOTONIC`) and a pointer to `struct timespec`
   - `struct timespec` contains:
     - `tv_sec`: Seconds
     - `tv_nsec`: Nanoseconds (0-999,999,999)

3. **Why your tech lead wants this:**
   - **Reliable for timing intervals**: Not affected by system time changes
   - **Good for performance measurements**: Consistent, monotonic progression
   - **Suitable for timeouts and intervals**: Won't have gaps or jumps
   - **Better precision**: Nanosecond resolution (though actual precision depends on hardware)

4. **Common use cases:**
   - Performance profiling
   - Game loop timing
   - Animation timing
   - Network timeout calculations
   - Benchmarking code sections

**Note:** On some systems, you may need to link with `-lrt` (real-time library). The monotonic clock is ideal for measuring elapsed time between two points in your code without worrying about external time adjustments.

I'll show you how to implement a HyperLogLog sketch in C++ for approximate distinct counting. Here's a complete implementation with explanations:

```cpp
#include <iostream>
#include <vector>
#include <cmath>
#include <cstdint>
#include <functional>
#include <algorithm>
#include <limits>
#include <random>

class HyperLogLog {
private:
    int b;  // number of bits for bucket index (precision parameter)
    int m;  // number of buckets = 2^b
    std::vector<uint8_t> registers;  // M[0..m-1]

    // Alpha constant for bias correction
    double alpha;

    // Hash function (using std::hash as base)
    std::hash<std::string> hasher;

    // Helper to count leading zeros in a 64-bit integer
    int countLeadingZeros(uint64_t x) {
        if (x == 0) return 64;
        return __builtin_clzll(x);  // GCC/Clang builtin
    }

public:
    // Constructor with precision parameter (b between 4 and 16 typically)
    HyperLogLog(int precision = 12) : b(precision) {
        if (b < 4) b = 4;
        if (b > 16) b = 16;

        m = 1 << b;  // 2^b buckets
        registers.resize(m, 0);

        // Set alpha constant based on m
        if (m == 16) {
            alpha = 0.673;
        } else if (m == 32) {
            alpha = 0.697;
        } else if (m == 64) {
            alpha = 0.709;
        } else {
            alpha = 0.7213 / (1.0 + 1.079 / m);
        }
    }

    // Add an element to the sketch
    void add(const std::string& element) {
        // Hash the element
        size_t hash_value = hasher(element);

        // Get bucket index from first b bits
        uint32_t bucket_index = hash_value >> (64 - b);

        // Get remaining bits for counting leading zeros
        uint64_t remaining_bits = hash_value << b;
        int leading_zeros = countLeadingZeros(remaining_bits) + 1 - b;

        // Update register if we found more leading zeros
        if (leading_zeros > registers[bucket_index]) {
            registers[bucket_index] = leading_zeros;
        }
    }

    // Add an integer element (convenience method)
    void add(int value) {
        add(std::to_string(value));
    }

    // Estimate the cardinality
    double estimate() const {
        // Calculate raw estimate
        double sum = 0.0;
        int zero_registers = 0;

        for (int i = 0; i < m; i++) {
            sum += 1.0 / (1 << registers[i]);  // 2^(-register[i])
            if (registers[i] == 0) {
                zero_registers++;
            }
        }

        double estimate = alpha * m * m / sum;

        // Apply corrections for small and large ranges
        if (estimate <= 2.5 * m) {
            // Small range correction
            if (zero_registers != 0) {
                estimate = m * std::log(static_cast<double>(m) / zero_registers);
            }
        } else if (estimate > (1.0 / 30.0) * (1ULL << 32)) {
            // Very large range correction
            estimate = - (1ULL << 32) * std::log(1.0 - estimate / (1ULL << 32));
        }

        return estimate;
    }

    // Merge another HyperLogLog sketch (must have same precision)
    void merge(const HyperLogLog& other) {
        if (b != other.b) {
            throw std::invalid_argument("HyperLogLog sketches must have same precision to merge");
        }

        for (int i = 0; i < m; i++) {
            if (other.registers[i] > registers[i]) {
                registers[i] = other.registers[i];
            }
        }
    }

    // Get memory usage in bytes
    size_t memoryUsage() const {
        return sizeof(*this) + registers.size() * sizeof(uint8_t);
    }

    // Get precision parameter
    int getPrecision() const { return b; }

    // Get number of buckets
    int getBucketCount() const { return m; }

    // Reset the sketch
    void clear() {
        std::fill(registers.begin(), registers.end(), 0);
    }

    // Print statistics (for debugging)
    void printStats() const {
        std::cout << "HyperLogLog Sketch:" << std::endl;
        std::cout << "  Precision (b): " << b << std::endl;
        std::cout << "  Buckets (m): " << m << std::endl;
        std::cout << "  Memory: " << memoryUsage() << " bytes" << std::endl;

        int max_val = *std::max_element(registers.begin(), registers.end());
        int min_val = *std::min_element(registers.begin(), registers.end());
        std::cout << "  Max register value: " << max_val << std::endl;
        std::cout << "  Min register value: " << min_val << std::endl;
    }
};

// Example usage and testing
int main() {
    // Create HyperLogLog sketch with precision 12 (4096 buckets, ~4KB memory)
    HyperLogLog hll(12);

    std::cout << "=== HyperLogLog Demonstration ===\n" << std::endl;
    hll.printStats();

    // Test with random data
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1, 1000000);

    std::cout << "\nAdding 100,000 random integers (1-1,000,000):" << std::endl;

    int actual_distinct = 0;
    std::vector<bool> seen(1000001, false);

    for (int i = 0; i < 100000; i++) {
        int value = dis(gen);
        hll.add(value);

        if (!seen[value]) {
            seen[value] = true;
            actual_distinct++;
        }

        // Print progress every 10,000 items
        if ((i + 1) % 10000 == 0) {
            double estimate = hll.estimate();
            double error = std::abs(estimate - actual_distinct) / actual_distinct * 100;
            std::cout << "  After " << (i + 1) << " items: "
                      << "Actual=" << actual_distinct
                      << ", Estimate=" << static_cast<int>(estimate)
                      << ", Error=" << error << "%" << std::endl;
        }
    }

    // Final results
    double final_estimate = hll.estimate();
    double final_error = std::abs(final_estimate - actual_distinct) / actual_distinct * 100;

    std::cout << "\n=== Final Results ===" << std::endl;
    std::cout << "Actual distinct count: " << actual_distinct << std::endl;
    std::cout << "Estimated count: " << static_cast<int>(final_estimate) << std::endl;
    std::cout << "Error: " << final_error << "%" << std::endl;
    std::cout << "Memory used: " << hll.memoryUsage() << " bytes (~" 
              << hll.memoryUsage() / 1024 << " KB)" << std::endl;

    // Demonstrate merging two sketches
    std::cout << "\n=== Merging Demonstration ===" << std::endl;

    HyperLogLog hll1(10);
    HyperLogLog hll2(10);

    // Add different sets to each sketch
    for (int i = 0; i < 5000; i++) {
        hll1.add(i);           // Elements 0-4999
        hll2.add(i + 2500);    // Elements 2500-7499 (overlap of 2500)
    }

    double est1 = hll1.estimate();
    double est2 = hll2.estimate();

    // Merge hll2 into hll1
    hll1.merge(hll2);
    double merged_est = hll1.estimate();

    std::cout << "Sketch 1 estimate: " << static_cast<int>(est1) << std::endl;
    std::cout << "Sketch 2 estimate: " << static_cast<int>(est2) << std::endl;
    std::cout << "Merged estimate: " << static_cast<int>(merged_est) << std::endl;
    std::cout << "Expected (7500 distinct): 7500" << std::endl;

    return 0;
}
```

## Key Concepts Explained:

1. **HyperLogLog Algorithm**:
   - Uses probabilistic counting with hash functions
   - Divides hash space into `m = 2^b` buckets
   - Records maximum number of leading zeros in each bucket
   - Estimates cardinality using harmonic mean

2. **Memory Efficiency**:
   - Each bucket stores only 5-6 bits typically
   - Precision `b=12` uses 4096 buckets × 1 byte = ~4KB
   - Error rate ≈ 1.04/√m (1.6% for b=12)

3. **Implementation Details**:
   - `add()`: Hashes element, updates appropriate bucket
   - `estimate()`: Computes cardinality with bias corrections
   - `merge()`: Combines two sketches (for distributed counting)
   - Uses built-in hash function (can be replaced with better hash like MurmurHash3)

4. **Accuracy Trade-offs**:
   - Higher `b` = more memory, better accuracy
   - Typical `b` values: 10-16 (1KB-64KB memory)
   - Standard error: 1.04/√(2^b)

