#include <stdio.h>
#include <pthread.h>
#include <unistd.h>

_Bool flag = false;

void* worker_thread(void* arg) {
    printf("Worker: Starting...\n");

    // Wait for flag to become true
    while (!__atomic_load_n(&flag, __ATOMIC_ACQUIRE)) {
        usleep(100000);
    }

    printf("Worker: Flag is true, proceeding!\n");

    return NULL;
}

int main() {
    pthread_t thread;

    printf("Main: Creating worker thread\n");
    pthread_create(&thread, NULL, worker_thread, NULL);

    sleep(2);

    printf("Main: Setting flag to true\n");
    __atomic_store_n(&flag, true, __ATOMIC_RELEASE);

    pthread_join(thread, NULL);
    printf("Main: Thread finished\n");

    return 0;
}
