## Option 3: Using POSIX Mutex (Portable Alternative)

```c
#include <stdbool.h>
#include <stdio.h>
#include <pthread.h>
#include <unistd.h>

typedef struct {
    pthread_mutex_t mutex;
    bool flag;
} thread_flag_t;

thread_flag_t shared_flag = {
    .mutex = PTHREAD_MUTEX_INITIALIZER,
    .flag = false
};

void* worker_thread(void* arg) {
    printf("Worker: Starting...\n");

    while (1) {
        pthread_mutex_lock(&shared_flag.mutex);
        if (shared_flag.flag) {
            pthread_mutex_unlock(&shared_flag.mutex);
            break;
        }
        pthread_mutex_unlock(&shared_flag.mutex);
        usleep(100000);
    }

    printf("Worker: Flag is true, proceeding!\n");
    return NULL;
}

int main() {
    pthread_t thread;

    printf("Main: Creating worker thread\n");
    pthread_create(&thread, NULL, worker_thread, NULL);

    sleep(2);

    printf("Main: Setting flag to true\n");
    pthread_mutex_lock(&shared_flag.mutex);
    shared_flag.flag = true;
    pthread_mutex_unlock(&shared_flag.mutex);

    pthread_join(thread, NULL);
    printf("Main: Thread finished\n");

    pthread_mutex_destroy(&shared_flag.mutex);

    return 0;
}
```

