#[cfg(test)]
mod tests {
    use super::*;
    use std::time::Instant;

    #[test]
    fn test_constant_time_eq() {
        // Test equal slices
        assert!(constant_time_eq(b"hello", b"hello"));

        // Test different slices
        assert!(!constant_time_eq(b"hello", b"world"));

        // Test different lengths
        assert!(!constant_time_eq(b"hello", b"hell"));

        // Test empty slices
        assert!(constant_time_eq(b"", b""));
    }

    #[test]
    fn test_timing_consistency() {
        // This is a simple check - proper timing tests require specialized equipment
        let data1 = vec![0u8; 1024];
        let data2 = vec![0u8; 1024];
        let data3 = vec![1u8; 1024];

        // Measure time for equal comparison
        let start = Instant::now();
        for _ in 0..1000 {
            let _ = constant_time_eq(&data1, &data2);
        }
        let equal_time = start.elapsed();

        // Measure time for different comparison
        let start = Instant::now();
        for _ in 0..1000 {
            let _ = constant_time_eq(&data1, &data3);
        }
        let diff_time = start.elapsed();

        // Times should be roughly equal (within small margin)
        let ratio = (equal_time.as_nanos() as f64) / (diff_time.as_nanos() as f64);
        assert!(ratio > 0.9 && ratio < 1.1, 
                "Timing difference too large: ratio = {}", ratio);
    }
}
