## 3. More Robust Example with Reconnection Logic:

```javascript
const WebSocket = require('ws');

class WebSocketClient {
  constructor(url, options = {}) {
    this.url = url;
    this.options = options;
    this.reconnectInterval = options.reconnectInterval || 3000;
    this.maxReconnectAttempts = options.maxReconnectAttempts || 5;
    this.reconnectAttempts = 0;
    this.shouldReconnect = true;

    this.connect();
  }

  connect() {
    this.ws = new WebSocket(this.url, this.options.protocols);

    this.ws.on('open', () => {
      console.log('WebSocket connected');
      this.reconnectAttempts = 0; // Reset reconnect attempts on successful connection
      this.onOpen();
    });

    this.ws.on('message', (data) => {
      this.onMessage(data);
    });

    this.ws.on('error', (error) => {
      console.error('WebSocket error:', error);
      this.onError(error);
    });

    this.ws.on('close', (code, reason) => {
      console.log(`WebSocket closed: ${code} - ${reason}`);
      this.onClose(code, reason);

      // Attempt reconnection
      if (this.shouldReconnect && this.reconnectAttempts < this.maxReconnectAttempts) {
        setTimeout(() => {
          this.reconnectAttempts++;
          console.log(`Reconnecting... Attempt ${this.reconnectAttempts}`);
          this.connect();
        }, this.reconnectInterval);
      }
    });
  }

  send(data) {
    if (this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(data);
      return true;
    } else {
      console.warn('WebSocket is not open. Message not sent.');
      return false;
    }
  }

  close() {
    this.shouldReconnect = false;
    this.ws.close();
  }

  // Override these methods in your implementation
  onOpen() {}
  onMessage(data) {
    console.log('Received:', data.toString());
  }
  onError(error) {}
  onClose(code, reason) {}
}

// Usage example
const client = new WebSocketClient('wss://echo.websocket.org', {
  reconnectInterval: 2000,
  maxReconnectAttempts: 10
});

// Override methods
client.onOpen = function() {
  console.log('Connection established!');
  this.send('Hello from WebSocket client!');
};

client.onMessage = function(data) {
  console.log('Server says:', data.toString());
};

// To send a message later
setTimeout(() => {
  client.send('Another message after 2 seconds');
}, 2000);

// To close connection
// setTimeout(() => client.close(), 5000);
```

## 4. WebSocket Server Example (if you need to create one):

```javascript
const WebSocket = require('ws');

const wss = new WebSocket.Server({ port: 8080 });

wss.on('connection', function connection(ws) {
  console.log('New client connected');

  ws.on('message', function message(data) {
    console.log('Received from client:', data.toString());

    // Echo the message back
    ws.send(`Server received: ${data}`);
  });

  ws.on('close', () => {
    console.log('Client disconnected');
  });

  // Send welcome message
  ws.send('Welcome to WebSocket server!');
});

console.log('WebSocket server running on ws://localhost:8080');
```

## Key Points:

1. **Connection States**: WebSocket has 4 states: `CONNECTING` (0), `OPEN` (1), `CLOSING` (2), `CLOSED` (3)
2. **Error Handling**: Always implement error handling and reconnection logic
3. **Message Types**: WebSocket can send both text and binary data
4. **Ping/Pong**: The `ws` package supports automatic ping/pong for connection health checks

