## Complete Working Example

```javascript
import DOMPurify from 'dompurify';

// Function to handle user input
function handleUserInput() {
    // Get user input (e.g., from a textarea)
    const userInput = document.getElementById('userInput').value;

    // Sanitize the input
    const sanitizedHTML = DOMPurify.sanitize(userInput, {
        // Optional configuration
        ALLOWED_TAGS: ['p', 'b', 'i', 'em', 'strong', 'a'],
        ALLOWED_ATTR: ['href', 'target', 'title']
    });

    // Safely display the sanitized content
    document.getElementById('output').innerHTML = sanitizedHTML;

    // Log what was removed (for debugging)
    console.log('Sanitized output:', sanitizedHTML);
}

// Example with custom configuration
function sanitizeWithConfig() {
    const config = {
        ALLOWED_TAGS: ['p', 'span', 'br', 'b', 'i', 'em', 'strong'],
        ALLOWED_ATTR: ['class', 'style'],
        FORBID_TAGS: ['script', 'iframe', 'object'],
        FORBID_ATTR: ['onclick', 'onload', 'onerror']
    };

    const dirtyHTML = '<p style="color: red;">Hello <script>alert("bad")</script>World</p>';
    const cleanHTML = DOMPurify.sanitize(dirtyHTML, config);

    return cleanHTML; // Returns: <p style="color: red;">Hello World</p>
}

// Example for Node.js (if using JSDOM)
import { JSDOM } from 'jsdom';

function sanitizeInNode() {
    const { window } = new JSDOM('');
    const DOMPurify = require('dompurify')(window);

    const dirty = '<div><script>alert("xss")</script>Safe content</div>';
    const clean = DOMPurify.sanitize(dirty);

    return clean;
}
