        .worker_threads(4) // 4 threads in the pool
        .enable_all()
        .build()
        .unwrap();

    rt.block_on(async {
        // Your async code here
    });
}
```

Here's a complete implementation using the `csv` crate to read CSV data into structs:

```rust
// Cargo.toml dependencies:
// [dependencies]
// csv = "1.3"
// serde = { version = "1.0", features = ["derive"] }

use serde::Deserialize;
use std::error::Error;
use std::fs::File;

#[derive(Debug, Deserialize)]
struct Person {
    name: String,
    age: u32,
    city: String,
    #[serde(rename = "employed")]
    is_employed: bool,
}

fn read_csv_file(file_path: &str) -> Result<Vec<Person>, Box<dyn Error>> {
    // Open the file
    let file = File::open(file_path)?;

    // Create a CSV reader
    let mut reader = csv::Reader::from_reader(file);

    // Deserialize each record into a Person struct
    let mut people = Vec::new();
    for result in reader.deserialize() {
        let person: Person = result?;
        people.push(person);
    }

    Ok(people)
}

fn main() -> Result<(), Box<dyn Error>> {
    // Example CSV content (save this as "people.csv"):
    // name,age,city,employed
    // Alice,30,New York,true
    // Bob,25,Los Angeles,false
    // Charlie,35,Chicago,true

    let people = read_csv_file("people.csv")?;

    // Print all people
    for person in &people {
        println!("{:?}", person);
    }

    // Access specific fields
    println!("\nFirst person's name: {}", people[0].name);
    println!("Number of records: {}", people.len());

    Ok(())
}
```

## How It Works:

1. **Dependencies**: The `csv` crate handles CSV parsing, while `serde` provides serialization/deserialization capabilities.

2. **Struct Definition**: 
   - The `Person` struct represents each CSV row
   - `#[derive(Debug, Deserialize)]` enables both debugging output and CSV deserialization
   - `#[serde(rename = "employed")]` maps the CSV column "employed" to the struct field `is_employed`

3. **Reading Process**:
   - `File::open()` opens the CSV file
   - `csv::Reader::from_reader()` creates a CSV reader from the file
   - `reader.deserialize()` returns an iterator over deserialized records
   - Each record is automatically converted from CSV strings to the appropriate Rust types (String, u32, bool)

4. **Type Conversion**: The `csv` crate with `serde` automatically handles:
   - String → String (no conversion needed)
   - "30" → u32 (parses as integer)
   - "true"/"false" → bool (parses as boolean)

5. **Error Handling**: The `?` operator propagates errors (file not found, malformed CSV, type conversion errors).

