Here's a Python implementation to decode ADS-B position messages:

```python
import math

def decode_adsb_position(msg, even_msg, odd_msg, even_time, odd_time):
    """
    Decode ADS-B position from two messages (even/odd format)

    Args:
        msg: Current message (bytes or bytearray)
        even_msg: Previous even message
        odd_msg: Previous odd message
        even_time: Timestamp of even message
        odd_time: Timestamp of odd message

    Returns:
        tuple: (latitude, longitude, altitude) or None if insufficient data
    """
    if len(msg) < 7:
        return None

    # Convert to integer representation
    if isinstance(msg, bytes) or isinstance(msg, bytearray):
        msg_int = int.from_bytes(msg[:7], 'big')
    else:
        msg_int = msg

    # Extract message type (bits 32-37)
    msg_type = (msg_int >> 51) & 0x3F

    # Check if this is a position message (types 9-18, 20-22)
    if not (9 <= msg_type <= 18 or 20 <= msg_type <= 22):
        return None

    # Extract format type (bit 48) - 0 for even, 1 for odd
    format_type = (msg_int >> 48) & 0x1

    # Store message in appropriate slot
    if format_type == 0:  # Even
        even_msg = msg_int
        even_time = even_time
    else:  # Odd
        odd_msg = msg_int
        odd_time = odd_time

    # Need both even and odd messages to compute position
    if even_msg is None or odd_msg is None:
        return None

    # Time check - messages should be within 10 seconds
    if abs(even_time - odd_time) > 10:
        return None

    # Decode CPR encoded position
    return decode_cpr_position(even_msg, odd_msg)

def decode_cpr_position(even_msg, odd_msg):
    """
    Decode Compact Position Reporting (CPR) encoded position
    """
    # Extract CPR data from messages
    even_lat_cpr = (even_msg >> 29) & 0x1FFFF  # 17 bits
    even_lon_cpr = (even_msg >> 12) & 0x1FFFF  # 17 bits

    odd_lat_cpr = (odd_msg >> 29) & 0x1FFFF   # 17 bits
    odd_lon_cpr = (odd_msg >> 12) & 0x1FFFF   # 17 bits

    # Decode altitude (in feet)
    alt = decode_altitude(even_msg)

    # CPR decoding constants
    NZ = 15  # Number of latitude zones

    # Calculate latitude index
    j = math.floor((59 * even_lat_cpr - 60 * odd_lat_cpr) / 131072 + 0.5)

    # Calculate latitudes
    even_lat = 6.0 * (j % 60 + even_lat_cpr / 131072)
    odd_lat = 6.0 * (j % 60 + odd_lat_cpr / 131072)

    # Normalize latitudes
    if even_lat >= 270:
        even_lat -= 360
    if odd_lat >= 270:
        odd_lat -= 360

    # Select latitude based on format (use even for even, odd for odd)
    lat = even_lat if j % 2 == 0 else odd_lat

    # Calculate longitude
    if lat < 0:
        NL = NL_function(lat - 1)  # Southern hemisphere
    else:
        NL = NL_function(lat)      # Northern hemisphere

    if NL == 0:
        return None

    m = math.floor((even_lon_cpr * (NL - 1) - odd_lon_cpr * NL) / 131072 + 0.5)

    # Calculate longitudes
    even_lon = 360.0 / NL * (m % NL + even_lon_cpr / 131072)
    odd_lon = 360.0 / NL * (m % NL + odd_lon_cpr / 131072)

    # Normalize longitudes
    if even_lon >= 180:
        even_lon -= 360
    if odd_lon >= 180:
        odd_lon -= 360

    # Select longitude
    lon = even_lon if j % 2 == 0 else odd_lon

    return lat, lon, alt

