## Option 2: Manual Parsing (Minimal Example)

If you want a minimal implementation without external dependencies:

```go
package main

import (
    "fmt"
    "log"
    "strconv"
    "strings"
)

// ParseGPGGA parses a GPGGA sentence
func ParseGPGGA(sentence string) (lat, lon, alt float64, err error) {
    // Remove checksum if present
    parts := strings.Split(sentence, "*")
    fields := strings.Split(parts[0], ",")

    if len(fields) < 10 {
        return 0, 0, 0, fmt.Errorf("invalid GPGGA sentence")
    }

    // Parse latitude (DDMM.MMMM format)
    if fields[2] != "" && fields[3] != "" {
        lat, err = parseCoord(fields[2], fields[3])
        if err != nil {
            return 0, 0, 0, err
        }
    }

    // Parse longitude (DDDMM.MMMM format)
    if fields[4] != "" && fields[5] != "" {
        lon, err = parseCoord(fields[4], fields[5])
        if err != nil {
            return 0, 0, 0, err
        }
    }

    // Parse altitude
    if fields[9] != "" {
        alt, err = strconv.ParseFloat(fields[9], 64)
        if err != nil {
            return 0, 0, 0, err
        }
    }

    return lat, lon, alt, nil
}

// parseCoord converts NMEA coordinate (DDMM.MMMM) to decimal degrees
func parseCoord(value, direction string) (float64, error) {
    if len(value) < 4 {
        return 0, fmt.Errorf("invalid coordinate")
    }

    // Extract degrees and minutes
    deg, err := strconv.ParseFloat(value[:2], 64)
    if err != nil {
        return 0, err
    }

    min, err := strconv.ParseFloat(value[2:], 64)
    if err != nil {
        return 0, err
    }

    // Convert to decimal degrees
    decimal := deg + min/60.0

    // Apply direction
    if direction == "S" || direction == "W" {
        decimal = -decimal
    }

    return decimal, nil
}

func main() {
    // Example GPGGA sentence
    sentence := "$GPGGA,092750.000,5321.6802,N,00630.3372,W,1,8,1.03,61.7,M,55.2,M,,*76"

    lat, lon, alt, err := ParseGPGGA(sentence)
    if err != nil {
        log.Fatal(err)
    }

    fmt.Printf("Latitude: %.6f\n", lat)
    fmt.Printf("Longitude: %.6f\n", lon)
    fmt.Printf("Altitude: %.1f meters\n", alt)
}
```

