import ca.uhn.fhir.context.FhirContext;
import ca.uhn.fhir.context.FhirVersionEnum;
import ca.uhn.fhir.validation.FhirValidator;
import ca.uhn.fhir.validation.ValidationResult;
import org.hl7.fhir.instance.model.api.IBaseResource;
import org.hl7.fhir.r4.model.Bundle;

public class FhirBundleValidator {
    private final FhirContext fhirContext;
    private final FhirValidator validator;

    public FhirBundleValidator() {
        // Initialize FHIR context for R4 (or choose your FHIR version)
        fhirContext = FhirContext.forR4();

        // Create validator with built-in schemas and terminology
        validator = fhirContext.newValidator();

        // Register validation modules
        validator.registerValidatorModule(
            new ca.uhn.fhir.validation.schematron.SchematronBaseValidator());
        validator.registerValidatorModule(
            new ca.uhn.fhir.validation.schematron.SchematronBaseValidator());
    }

    public ValidationResult validateBundle(String bundleJson) {
        try {
            // Parse the JSON bundle
            IBaseResource resource = fhirContext.newJsonParser()
                .parseResource(bundleJson);

            // Validate the resource
            return validator.validateWithResult(resource);

        } catch (Exception e) {
            throw new ValidationException("Failed to parse or validate bundle", e);
        }
    }

    public ValidationResult validateBundle(Bundle bundle) {
        // Validate directly from Bundle object
        return validator.validateWithResult(bundle);
    }

    public boolean isValid(String bundleJson) {
        ValidationResult result = validateBundle(bundleJson);
        return result.isSuccessful();
    }

    public void printValidationMessages(String bundleJson) {
        ValidationResult result = validateBundle(bundleJson);

        if (result.isSuccessful()) {
            System.out.println("✅ Bundle is valid!");
        } else {
            System.out.println("❌ Validation issues found:");
            result.getMessages().forEach(message -> {
                System.out.printf("  - %s: %s (Location: %s)%n",
                    message.getSeverity(),
                    message.getMessage(),
                    message.getLocationString());
            });
        }
    }

    // Helper method to load validation profiles if needed
