## 1. Basic CAN Frame Structure

First, let's define a standard CAN frame structure:

```cpp
#include <iostream>
#include <cstdint>
#include <vector>
#include <string>
#include <cstring>
#include <chrono>
#include <thread>

// Standard CAN frame structure (Linux SocketCAN compatible)
struct CanFrame {
    uint32_t can_id;      // 32-bit CAN ID + EFF/RTR/ERR flags
    uint8_t can_dlc;      // Data Length Code (0-8)
    uint8_t data[8];      // Data payload
    uint8_t __pad;        // Padding
    uint8_t __res0;       // Reserved
    uint8_t __res1;       // Reserved

    // Constructor
    CanFrame() : can_id(0), can_dlc(0) {
        memset(data, 0, sizeof(data));
    }

    // Helper method to print frame
    void print() const {
        std::cout << std::hex << "ID: 0x" << can_id 
                  << std::dec << " DLC: " << static_cast<int>(can_dlc) 
                  << " Data: ";
        for (int i = 0; i < can_dlc; i++) {
            printf("%02X ", data[i]);
        }
        std::cout << std::endl;
    }
};
```

## 2. Using SocketCAN (Linux)

If you're on Linux with SocketCAN support:

```cpp
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <net/if.h>
#include <linux/can.h>
#include <linux/can/raw.h>
#include <unistd.h>
#include <fcntl.h>

class SocketCanReader {
private:
    int socket_fd;
    std::string interface_name;

public:
    SocketCanReader(const std::string& ifname = "can0") 
        : interface_name(ifname), socket_fd(-1) {}

    ~SocketCanReader() {
        if (socket_fd >= 0) {
            close(socket_fd);
        }
    }

    bool initialize() {
        // Create socket
        socket_fd = socket(PF_CAN, SOCK_RAW, CAN_RAW);
        if (socket_fd < 0) {
            std::cerr << "Error creating socket" << std::endl;
            return false;
        }

        // Get interface index
        struct ifreq ifr;
        strcpy(ifr.ifr_name, interface_name.c_str());
        if (ioctl(socket_fd, SIOCGIFINDEX, &ifr) < 0) {
            std::cerr << "Error getting interface index" << std::endl;
            close(socket_fd);
            return false;
        }

        // Bind socket to CAN interface
        struct sockaddr_can addr;
        addr.can_family = AF_CAN;
        addr.can_ifindex = ifr.ifr_ifindex;

        if (bind(socket_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
            std::cerr << "Error binding socket" << std::endl;
            close(socket_fd);
            return false;
        }

        // Set non-blocking mode (optional)
        int flags = fcntl(socket_fd, F_GETFL, 0);
        fcntl(socket_fd, F_SETFL, flags | O_NONBLOCK);

        std::cout << "SocketCAN initialized on " << interface_name << std::endl;
        return true;
    }

    bool readFrame(CanFrame& frame, int timeout_ms = 1000) {
        struct can_frame raw_frame;

        // Set timeout using select()
        fd_set read_set;
        FD_ZERO(&read_set);
        FD_SET(socket_fd, &read_set);

        struct timeval timeout;
        timeout.tv_sec = timeout_ms / 1000;
        timeout.tv_usec = (timeout_ms % 1000) * 1000;

        int ready = select(socket_fd + 1, &read_set, NULL, NULL, &timeout);

        if (ready > 0) {
            ssize_t nbytes = read(socket_fd, &raw_frame, sizeof(struct can_frame));

            if (nbytes < 0) {
                std::cerr << "Error reading CAN frame" << std::endl;
                return false;
            }

            if (nbytes < sizeof(struct can_frame)) {
                std::cerr << "Incomplete CAN frame" << std::endl;
                return false;
            }

            // Convert to our CanFrame structure
            frame.can_id = raw_frame.can_id;
            frame.can_dlc = raw_frame.can_dlc;
            memcpy(frame.data, raw_frame.data, 8);

            return true;
        }

        return false; // Timeout
    }

    void continuousRead() {
        CanFrame frame;
        std::cout << "Starting continuous CAN read..." << std::endl;

        while (true) {
            if (readFrame(frame, 100)) {
                frame.print();

                // Example: Process specific CAN IDs
                if ((frame.can_id & 0x1FFFFFFF) == 0x100) {
                    processEngineRPM(frame);
                }
            }

            // Small delay to prevent CPU hogging
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
    }

private:
    void processEngineRPM(const CanFrame& frame) {
        if (frame.can_dlc >= 2) {
            uint16_t rpm = (frame.data[0] << 8) | frame.data[1];
            std::cout << "Engine RPM: " << rpm << std::endl;
        }
    }
};
```

## 3. Using PCAN-USB (Windows/Linux with PCAN API)

```cpp
#ifdef _WIN32
#include <windows.h>
#include "PCANBasic.h"
#else
// Linux PCAN API headers would go here
#endif

class PcanReader {
private:
    TPCANHandle channel;
    TPCANBaudrate baudrate;

public:
    PcanReader(TPCANHandle chan = PCAN_USBBUS1, 
               TPCANBaudrate baud = PCAN_BAUD_500K) 
        : channel(chan), baudrate(baud) {}

    bool initialize() {
#ifdef _WIN32
        TPCANStatus status = CAN_Initialize(channel, baudrate, 0, 0, 0);

        if (status != PCAN_ERROR_OK) {
            std::cerr << "PCAN initialization failed: " 
                      << GetFormattedError(status) << std::endl;
            return false;
        }

        std::cout << "PCAN initialized successfully" << std::endl;
        return true;
#else
        std::cerr << "PCAN not implemented for this platform" << std::endl;
        return false;
#endif
    }

    bool readFrame(CanFrame& frame) {
#ifdef _WIN32
        TPCANMsg canMsg;
        TPCANTimestamp timestamp;

        TPCANStatus status = CAN_Read(channel, &canMsg, &timestamp);

        if (status == PCAN_ERROR_OK) {
            frame.can_id = canMsg.ID;
            frame.can_dlc = canMsg.LEN;
            memcpy(frame.data, canMsg.DATA, 8);
            return true;
        } else if (status != PCAN_ERROR_QRCVEMPTY) {
            std::cerr << "PCAN read error: " 
                      << GetFormattedError(status) << std::endl;
        }
#endif
        return false;
    }

private:
    std::string GetFormattedError(TPCANStatus status) {
        char buffer[256];
        CAN_GetErrorText(status, 0, buffer);
        return std::string(buffer);
    }
};
```

