```rust
//! Example demonstrating inline proof blocks for formal verification
//! Requires: #![feature(inline_proof_blocks)]

#![feature(inline_proof_blocks)]

/// A simple function with an embedded proof of correctness
pub fn safe_div(dividend: i32, divisor: i32) -> Option<i32> {
    // Precondition: divisor must not be zero
    proof {
        // The compiler will verify this proof at compile time
        assert!(divisor != 0, "Division by zero is undefined");
    }

    if divisor == 0 {
        None
    } else {
        Some(dividend / divisor)
    }
}

/// Function with loop invariant proof
pub fn sum_first_n(n: u32) -> u32 {
    let mut sum = 0;
    let mut i = 0;

    proof {
        // Loop invariant: sum == Σ_{k=0}^{i-1} k
        invariant!(sum == i * (i - 1) / 2);
    }

    while i <= n {
        sum += i;
        i += 1;
    }

    // Postcondition proof
    proof {
        // When loop ends, i = n + 1, so sum = n*(n+1)/2
        assert!(sum == n * (n + 1) / 2);
    }

    sum
}

/// Array access with bounds checking proof
pub fn get_element(arr: &[i32], index: usize) -> Option<i32> {
    proof {
        // Compile-time bounds check
        assert!(index < arr.len(), "Index out of bounds");
    }

    arr.get(index).copied()
}

/// Example with mathematical property proof
pub fn is_even_squared(n: u32) -> bool {
    let squared = n * n;

    proof {
        // Mathematical proof: n² is even iff n is even
        // n = 2k ⇒ n² = 4k² (even)
        // n = 2k+1 ⇒ n² = 4k² + 4k + 1 (odd)
        lemma!(squared % 2 == 0 ⇒ n % 2 == 0);
        lemma!(n % 2 == 0 ⇒ squared % 2 == 0);
    }

    squared % 2 == 0
}

#[cfg(test)]
mod tests {
