## Option 1: Using MsQuic (Microsoft's QUIC Implementation)

Here's a basic QUIC client implementation using MsQuic:

```cpp
#include <msquic.hpp>
#include <iostream>
#include <thread>
#include <chrono>

class QuicLosslessClient {
private:
    HQUIC connection = nullptr;
    HQUIC stream = nullptr;
    bool connected = false;

public:
    QuicLosslessClient() {
        // Initialize MsQuic
        QUIC_STATUS status = MsQuicOpen2(nullptr, nullptr);
        if (QUIC_FAILED(status)) {
            std::cerr << "MsQuicOpen2 failed: " << status << std::endl;
            throw std::runtime_error("Failed to initialize MsQuic");
        }
    }

    ~QuicLosslessClient() {
        if (stream) MsQuic->StreamClose(stream);
        if (connection) MsQuic->ConnectionClose(connection);
        MsQuicClose(nullptr);
    }

    bool connect(const std::string& server, uint16_t port) {
        // Create registration
        HQUIC registration;
        QUIC_STATUS status = MsQuic->RegistrationOpen(
            &QUIC_REGISTRATION_CONFIG{ "quic-client" },
            &registration);

        if (QUIC_FAILED(status)) {
            std::cerr << "RegistrationOpen failed: " << status << std::endl;
            return false;
        }

        // Create configuration
        HQUIC configuration;
        status = MsQuic->ConfigurationOpen(
            registration,
            &QUIC_BUFFER{ sizeof("h3"), (uint8_t*)"h3" }, // ALPN
            1,
            nullptr,
            0,
            nullptr,
            &configuration);

        // Create connection
        status = MsQuic->ConnectionOpen(
            registration,
            [](HQUIC, void*, QUIC_CONNECTION_EVENT*) -> QUIC_STATUS {
                return QUIC_STATUS_SUCCESS;
            },
            nullptr,
            &connection);

        // Start connection
        status = MsQuic->ConnectionStart(
            connection,
            configuration,
            QUIC_ADDRESS_FAMILY_UNSPEC,
            server.c_str(),
            port);

        // Wait for connection (simplified - in real code use async callbacks)
        std::this_thread::sleep_for(std::chrono::seconds(2));

        connected = true;
        return true;
    }

    bool createStream() {
        if (!connected) return false;

        QUIC_STATUS status = MsQuic->StreamOpen(
            connection,
            QUIC_STREAM_OPEN_FLAG_UNIDIRECTIONAL,
            [](HQUIC stream, void* context, QUIC_STREAM_EVENT* event) -> QUIC_STATUS {
                auto* self = static_cast<QuicLosslessClient*>(context);
                return self->handleStreamEvent(stream, event);
            },
            this,
            &stream);

        if (QUIC_FAILED(status)) {
            std::cerr << "StreamOpen failed: " << status << std::endl;
            return false;
        }

        status = MsQuic->StreamStart(stream, QUIC_STREAM_START_FLAG_NONE);
        return QUIC_SUCCEEDED(status);
    }

    QUIC_STATUS handleStreamEvent(HQUIC stream, QUIC_STREAM_EVENT* event) {
        switch (event->Type) {
            case QUIC_STREAM_EVENT_SEND_COMPLETE:
                std::cout << "Data sent successfully" << std::endl;
                break;
            case QUIC_STREAM_EVENT_RECEIVE:
                std::cout << "Received " << event->RECEIVE.TotalBufferLength 
                          << " bytes" << std::endl;
                break;
            case QUIC_STREAM_EVENT_PEER_SEND_SHUTDOWN:
                std::cout << "Peer shutdown send" << std::endl;
                break;
            case QUIC_STREAM_EVENT_PEER_SEND_ABORTED:
                std::cerr << "Peer aborted send" << std::endl;
                break;
        }
        return QUIC_STATUS_SUCCESS;
    }

    bool sendData(const std::vector<uint8_t>& data) {
        if (!stream) return false;

        QUIC_BUFFER buffer = { data.size(), const_cast<uint8_t*>(data.data()) };
        QUIC_STATUS status = MsQuic->StreamSend(stream, &buffer, 1, QUIC_SEND_FLAG_NONE, nullptr);

        return QUIC_SUCCEEDED(status);
    }

    void close() {
        if (stream) {
            MsQuic->StreamShutdown(stream, QUIC_STREAM_SHUTDOWN_FLAG_GRACEFUL, 0);
            MsQuic->StreamClose(stream);
            stream = nullptr;
        }
        connected = false;
    }
};

int main() {
    try {
        QuicLosslessClient client;

        if (client.connect("127.0.0.1", 4433)) {
            std::cout << "Connected successfully" << std::endl;

            if (client.createStream()) {
                std::cout << "Stream created" << std::endl;

                // Send some test data
                std::string message = "Hello QUIC!";
                std::vector<uint8_t> data(message.begin(), message.end());

                if (client.sendData(data)) {
                    std::cout << "Data sent" << std::endl;
                }

                // Keep connection alive for a bit
                std::this_thread::sleep_for(std::chrono::seconds(5));
            }

            client.close();
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
```

