        ngtcp2_transport_params params;
        ngtcp2_transport_params_default(&params);

        int rv = ngtcp2_conn_client_new(&conn, nullptr, &settings, &params, &callbacks, this);
        if (rv != 0) {
            throw std::runtime_error("Failed to create ngtcp2 connection");
        }
    }

    ~Ngtcp2LosslessClient() {
        if (conn) ngtcp2_conn_del(conn);
