    // Create mask without branching
    uint8_t mask = static_cast<uint8_t>(-static_cast<uint8_t>(condition));

    for (size_t i = 0; i < length; ++i) {
        // Select bytes using bitwise operations
        uint8_t true_byte = src_true[i] & mask;
        uint8_t false_byte = src_false[i] & ~mask;
        dst[i] = true_byte | false_byte;
    }
}

// Example: Constant-time array lookup (prevents cache timing attacks)
template<size_t N>
uint8_t constant_time_lookup(const std::array<uint8_t, N>& table, uint8_t index) {
    uint8_t result = 0;

    // Compare index with each possible value
    for (size_t i = 0; i < N; ++i) {
        // Create mask: 0xFF if i == index, 0x00 otherwise
        uint8_t mask = static_cast<uint8_t>(
            ~static_cast<uint32_t>(i ^ index) >> 31
        ) & 0xFF;

        // Select table entry using mask
        result |= table[i] & mask;
