package main

import (
    "io"
    "os"
    "syscall"
)

// Zero-copy between file descriptors (Linux/Unix only)
func zeroCopyFile(dst *os.File, src *os.File) (int64, error) {
    dstFd := int(dst.Fd())
    srcFd := int(src.Fd())

    // Use sendfile for zero-copy file transfer
    var offset int64 = 0
    var written int64 = 0

    for {
        n, err := syscall.Sendfile(dstFd, srcFd, &offset, 1<<31-1)
        if n > 0 {
            written += int64(n)
        }
        if err != nil {
            if err == syscall.EAGAIN {
                continue
            }
            if err == syscall.EINTR {
                continue
            }
            return written, err
        }
        if n == 0 {
            break // EOF
        }
    }
    return written, nil
}
```

