    // Encrypt
    int cipher_len = optimized_rsa_encrypt(rsa, 
                                          (unsigned char*)message, 
                                          strlen(message), 
                                          ciphertext);

    if (cipher_len > 0) {
        printf("Encryption successful. Ciphertext length: %d\n", cipher_len);

        // Decrypt
        int plain_len = optimized_rsa_decrypt(rsa, ciphertext, 
                                             cipher_len, decrypted);

        if (plain_len > 0) {
            decrypted[plain_len] = '\0';
            printf("Decrypted: %s\n", decrypted);
        }
    }

    // Cleanup
    RSA_free(rsa);
    EVP_cleanup();
    CRYPTO_cleanup_all_ex_data();

    return 0;
}
```

