    fprintf(fp, "}\n");
    fclose(fp);

    printf("Configuration created. Start wpa_supplicant with:\n");
    printf("wpa_supplicant -i wlan0 -c /etc/wpa_supplicant/wpa_supplicant.conf\n");
}

