Here's working code using `javax.json.TurboParser` to parse a JSON string:

```java
import javax.json.Json;
import javax.json.JsonObject;
import javax.json.JsonValue;
import javax.json.stream.JsonParser;
import javax.json.stream.JsonParser.Event;
import java.io.StringReader;

public class TurboParserExample {
    public static void main(String[] args) {
        String jsonString = """
            {
                "name": "John Doe",
                "age": 30,
                "isEmployed": true,
                "skills": ["Java", "JSON", "REST"],
                "address": {
                    "street": "123 Main St",
                    "city": "Anytown"
                }
            }
            """;

        // Method 1: Parse and get as JsonObject
        System.out.println("=== Method 1: Parse to JsonObject ===");
        JsonObject jsonObject = parseToJsonObject(jsonString);
        System.out.println("Name: " + jsonObject.getString("name"));
        System.out.println("Age: " + jsonObject.getInt("age"));
        System.out.println("Skills: " + jsonObject.getJsonArray("skills"));

        System.out.println("\n=== Method 2: Stream parsing ===");
        // Method 2: Stream parsing (more control)
        streamParseJson(jsonString);
    }

    public static JsonObject parseToJsonObject(String jsonString) {
        try (JsonParser parser = Json.createParser(new StringReader(jsonString))) {
            // Move to the first event (START_OBJECT)
            parser.next();
            // Parse the entire object
            return parser.getObject();
        }
    }

    public static void streamParseJson(String jsonString) {
        try (JsonParser parser = Json.createParser(new StringReader(jsonString))) {
            String currentKey = null;

            while (parser.hasNext()) {
                Event event = parser.next();

                switch (event) {
                    case START_OBJECT:
                        System.out.println("Start object" + 
                            (currentKey != null ? " for key: " + currentKey : ""));
                        break;
                    case END_OBJECT:
                        System.out.println("End object");
                        break;
                    case START_ARRAY:
                        System.out.println("Start array for key: " + currentKey);
                        break;
                    case END_ARRAY:
                        System.out.println("End array");
                        break;
                    case KEY_NAME:
                        currentKey = parser.getString();
                        System.out.println("Key: " + currentKey);
                        break;
                    case VALUE_STRING:
                        System.out.println("String value for '" + currentKey + "': " + parser.getString());
                        break;
                    case VALUE_NUMBER:
                        System.out.println("Number value for '" + currentKey + "': " + parser.getInt());
                        break;
                    case VALUE_TRUE:
                    case VALUE_FALSE:
                        System.out.println("Boolean value for '" + currentKey + "': " + 
                            (event == Event.VALUE_TRUE));
                        break;
                    case VALUE_NULL:
                        System.out.println("Null value for '" + currentKey + "'");
                        break;
                }
            }
        }
    }
}
```

