Here's how to use `ws-reliable` to create a reliable WebSocket connection in JavaScript:

## Installation

First, install the package:

```bash
npm install ws-reliable
```

## Basic Usage Example

```javascript
const ReliableWebSocket = require('ws-reliable');

// Create a reliable WebSocket connection
const ws = new ReliableWebSocket('wss://your-websocket-server.com', {
  // Connection options
  reconnectInterval: 1000, // Time between reconnection attempts (ms)
  maxReconnectAttempts: 10, // Maximum reconnection attempts
  heartbeatInterval: 30000, // Send heartbeat every 30 seconds
  heartbeatTimeout: 5000, // Time to wait for heartbeat response
  debug: true // Enable debug logging
});

// Event Listeners
ws.on('open', () => {
  console.log('WebSocket connection established');

  // Send a message
  ws.send(JSON.stringify({ type: 'greeting', message: 'Hello Server!' }));
});

ws.on('message', (data) => {
  console.log('Received message:', data);

  // Parse if it's JSON
  try {
    const parsed = JSON.parse(data);
    console.log('Parsed data:', parsed);
  } catch (e) {
    // Handle non-JSON messages
    console.log('Raw message:', data);
  }
});

ws.on('close', (code, reason) => {
  console.log(`Connection closed: ${code} - ${reason}`);
});

ws.on('error', (error) => {
  console.error('WebSocket error:', error);
});

ws.on('reconnect', (attempt) => {
  console.log(`Reconnection attempt #${attempt}`);
});

ws.on('reconnect-failed', () => {
  console.error('Failed to reconnect after maximum attempts');
});

// Manual reconnection (if needed)
// ws.reconnect();

// Close connection gracefully
// ws.close();
```

## Advanced Example with Custom Configuration

```javascript
const ReliableWebSocket = require('ws-reliable');

class WebSocketManager {
  constructor(url) {
    this.ws = new ReliableWebSocket(url, {
      reconnectInterval: 2000,
      maxReconnectAttempts: Infinity, // Keep trying forever
      heartbeatInterval: 25000,
      heartbeatTimeout: 10000,
      debug: process.env.NODE_ENV === 'development'
    });

    this.setupEventHandlers();
    this.messageQueue = [];
    this.isConnected = false;
  }

  setupEventHandlers() {
    this.ws.on('open', () => {
      this.isConnected = true;
      console.log('Connected to WebSocket server');

      // Send any queued messages
      this.flushMessageQueue();
    });

    this.ws.on('message', this.handleMessage.bind(this));

    this.ws.on('close', () => {
      this.isConnected = false;
      console.log('Disconnected from WebSocket server');
    });

    this.ws.on('reconnect', (attempt) => {
      console.log(`Attempting to reconnect (attempt ${attempt})`);
    });
  }

  handleMessage(data) {
    try {
      const message = JSON.parse(data);
      console.log('Received:', message);

      // Handle different message types
      switch (message.type) {
        case 'ping':
          this.send({ type: 'pong', timestamp: Date.now() });
          break;
        case 'data':
          this.processData(message.payload);
          break;
        default:
          console.log('Unknown message type:', message.type);
      }
    } catch (error) {
      console.log('Non-JSON message:', data);
    }
  }

  send(data) {
    const message = typeof data === 'string' ? data : JSON.stringify(data);

    if (this.isConnected) {
      this.ws.send(message);
    } else {
      // Queue message if not connected
      this.messageQueue.push(message);
      console.log('Message queued, waiting for connection...');
    }
  }

  flushMessageQueue() {
    while (this.messageQueue.length > 0) {
      const message = this.messageQueue.shift();
      this.ws.send(message);
    }
  }

  processData(payload) {
    // Process your data here
    console.log('Processing data:', payload);
  }

  disconnect() {
    this.ws.close();
  }
}

// Usage
const wsManager = new WebSocketManager('wss://your-server.com/ws');

// Send messages
wsManager.send({ type: 'subscribe', channel: 'updates' });
wsManager.send({ type: 'command', action: 'start' });
```

