Now, let's create a simple example that loads a PNG and applies smart cropping:

```rust
use image::io::Reader as ImageReader;
use image_smartcrop::SmartCrop;
use std::error::Error;

fn main() -> Result<(), Box<dyn Error>> {
    // Load an image from file
    let img = ImageReader::open("input.png")?.decode()?;

    // Convert to RGB8 if needed (smartcrop works with RGB images)
    let rgb_img = img.to_rgb8();

    // Create a smart crop instance
    let mut smartcrop = SmartCrop::new();

    // Configure the crop (optional)
    smartcrop
        .width(300)    // Target width
        .height(200)   // Target height
        .aspect(1.5);  // Aspect ratio (width/height)

    // Find the best crop
    let result = smartcrop.crop(&rgb_img);

    match result {
        Ok(crop) => {
            println!("Found crop at: x={}, y={}, width={}, height={}", 
                     crop.top_left.x, crop.top_left.y, crop.width, crop.height);

            // Apply the crop to get the cropped image
            let cropped_img = image::imageops::crop_imm(
                &rgb_img,
                crop.top_left.x,
                crop.top_left.y,
                crop.width,
                crop.height
            ).to_image();

            // Save the cropped image
            cropped_img.save("output_cropped.png")?;
            println!("Cropped image saved as 'output_cropped.png'");
        }
        Err(e) => {
            eprintln!("Failed to find crop: {}", e);
        }
    }

    Ok(())
}
```

