    if !Path::new(input_path).exists() {
        return Err(format!("Input file '{}' not found", input_path).into());
    }

    // Load and decode the image
    println!("Loading image from: {}", input_path);
    let img = ImageReader::open(input_path)?.decode()?;

    // Get original dimensions
    let (orig_width, orig_height) = img.dimensions();
    println!("Original dimensions: {}x{}", orig_width, orig_height);

    // Convert to RGB8 format required by smartcrop
    let rgb_img = img.to_rgb8();

    // Create and configure smart crop
    let mut smartcrop = SmartCrop::new();

    // Set target dimensions
    smartcrop.width(width).height(height);

    // Optional: Configure the algorithm
    smartcrop
        .boost(0.2)           // Boost factor for face detection
        .detail_weight(0.2)   // Weight for detail (edges)
        .skin_bias(0.01)      // Bias toward skin tones
        .skin_weight(1.8)     // Weight for skin color detection
        .saturation_bias(0.2) // Bias toward saturated colors
        .saturation_weight(0.3); // Weight for saturation

    // Find the best crop region
    println!("Finding optimal crop for {}x{}...", width, height);
    let result = smartcrop.crop(&rgb_img)?;

    println!("Selected crop region:");
