        &rgb_img,
        result.top_left.x,
        result.top_left.y,
        result.width,
        result.height
    ).to_image();

    // Save the result
    cropped_img.save(output_path)?;
    println!("Cropped image saved to: {}", output_path);

    Ok(())
}

