use tokio::time::{sleep, Duration};

// An async function that simulates some work
async fn do_work(id: u32, seconds: u64) -> u32 {
    println!("Task {} started - will take {} seconds", id, seconds);

    // Simulate work by sleeping
    sleep(Duration::from_secs(seconds)).await;

    println!("Task {} completed!", id);
    id * 10 // Return some result
}

#[tokio::main]
async fn main() {
    println!("Starting async tasks...");

    // Run multiple async tasks concurrently
    let task1 = do_work(1, 2);
    let task2 = do_work(2, 1);
    let task3 = do_work(3, 3);

    // Wait for all tasks to complete and get their results
    let (result1, result2, result3) = tokio::join!(task1, task2, task3);

    println!("All tasks completed!");
    println!("Results: {}, {}, {}", result1, result2, result3);

    // Example with tokio::spawn for background tasks
    println!("\n--- Running background tasks ---");

    let handle = tokio::spawn(async {
        println!("Background task starting...");
        sleep(Duration::from_secs(1)).await;
        println!("Background task finished!");
        42
    });

    // Do other work while the background task runs
    println!("Main thread doing other work...");
    sleep(Duration::from_millis(500)).await;
    println!("Main thread still working...");

    // Wait for the background task to complete
    let result = handle.await.expect("Task panicked");
    println!("Background task returned: {}", result);
}
```

Here's also a more practical example showing how to use async I/O:

```rust
use tokio::io::{self, AsyncReadExt, AsyncWriteExt};
use tokio::net::TcpListener;
use tokio::time::{sleep, Duration};

// A simple echo server example
async fn run_echo_server() -> io::Result<()> {
    let listener = TcpListener::bind("127.0.0.1:8080").await?;
    println!("Echo server listening on 127.0.0.1:8080");

    loop {
        let (mut socket, _) = listener.accept().await?;

        // Spawn a new task for each connection
        tokio::spawn(async move {
            let mut buf = [0; 1024];

            loop {
                let n = match socket.read(&mut buf).await {
                    Ok(0) => return, // Connection closed
                    Ok(n) => n,
                    Err(e) => {
                        eprintln!("Failed to read from socket: {}", e);
                        return;
                    }
                };

                // Echo back what was received
                if let Err(e) = socket.write_all(&buf[0..n]).await {
                    eprintln!("Failed to write to socket: {}", e);
                    return;
                }
            }
        });
    }
}

#[tokio::main]
async fn main() -> io::Result<()> {
    println!("Tokio async examples");

    // Example 1: Simple async tasks
    println!("\n=== Example 1: Simple async tasks ===");

    let task = tokio::spawn(async {
        sleep(Duration::from_secs(1)).await;
        "Hello from spawned task!"
    });

    println!("Main thread continues while task runs...");

    let message = task.await.expect("Task failed");
    println!("Received: {}", message);

    // Example 2: Multiple concurrent operations
    println!("\n=== Example 2: Concurrent operations ===");

    let futures = vec![
        tokio::spawn(async { sleep(Duration::from_millis(300)).await; 1 }),
        tokio::spawn(async { sleep(Duration::from_millis(200)).await; 2 }),
        tokio::spawn(async { sleep(Duration::from_millis(100)).await; 3 }),
    ];

    for future in futures {
        let result = future.await.expect("Task failed");
        println!("Task completed with result: {}", result);
    }

    // Uncomment to run the echo server example:
    // println!("\n=== Example 3: Echo Server ===");
    // run_echo_server().await?;

    Ok(())
}
