```javascript
// index.js
const dotenv = require('dotenv');

// Load .env file from a custom path
dotenv.config({ path: '/custom/path/to/.env' });

// Or with additional options
dotenv.config({
  path: '.env',           // Path to .env file (default)
  encoding: 'utf8',       // File encoding (default)
  debug: false            // Enable debug mode (default: false)
});

// Access environment variables
const config = {
  database: {
    url: process.env.DATABASE_URL,
    username: process.env.DB_USERNAME,
    password: process.env.DB_PASSWORD
  },
  server: {
    port: process.env.PORT || 3000,  // Default value if not set
    nodeEnv: process.env.NODE_ENV || 'development'
  },
  api: {
    key: process.env.API_KEY,
    secret: process.env.API_SECRET
  }
};

console.log('Server starting on port:', config.server.port);
console.log('Environment:', config.server.nodeEnv);
```

## Example .env file

Create a `.env` file in your project root:

```env
# .env
DATABASE_URL=postgresql://localhost:5432/mydb
DB_USERNAME=admin
DB_PASSWORD=secret123
PORT=8080
NODE_ENV=development
API_KEY=your_api_key_here
API_SECRET=your_secret_here
```

## ES Module Syntax (Node.js 14+)

```javascript
// index.mjs or with "type": "module" in package.json
import dotenv from 'dotenv';
dotenv.config();

// Or using top-level await
import { config } from 'dotenv';
config();

console.log(process.env.API_KEY);
```

## How It Works

1. **Loading**: When you call `dotenv.config()`, it reads your `.env` file
2. **Parsing**: It parses the key-value pairs from the file
3. **Setting**: It adds these variables to `process.env` object
4. **Access**: You can then access them via `process.env.VARIABLE_NAME`

## Important Notes

- **Never commit `.env` files** to version control - add `.env` to your `.gitignore`
- Create a `.env.example` file with placeholder values to document required variables
- For production, use actual environment variables (not `.env` files)
- The `.env` file should be in your project's root directory by default

## Best Practice Pattern

```javascript
// config.js
const dotenv = require('dotenv');
const path = require('path');

// Load environment variables based on NODE_ENV
const envFile = process.env.NODE_ENV === 'test' ? '.env.test' : '.env';
dotenv.config({ path: path.resolve(__dirname, envFile) });

// Validate required environment variables
const requiredEnvVars = ['DATABASE_URL', 'API_KEY'];
requiredEnvVars.forEach(varName => {
  if (!process.env[varName]) {
    throw new Error(`Missing required environment variable: ${varName}`);
  }
});

module.exports = {
  port: process.env.PORT || 3000,
  nodeEnv: process.env.NODE_ENV || 'development',
  databaseUrl: process.env.DATABASE_URL,
  apiKey: process.env.API_KEY
};
```

This approach keeps your environment configuration organized and validates that all required variables are present before your application starts.

Here's a working example using Node.js 26's built-in `node:orm` module:

```javascript
import { ORM, DataTypes } from 'node:orm';

// Define a User model
const User = ORM.define('User', {
  id: {
    type: DataTypes.INTEGER,
    primaryKey: true,
    autoIncrement: true
  },
  username: {
    type: DataTypes.STRING,
    allowNull: false,
    unique: true
  },
  email: {
    type: DataTypes.STRING,
    allowNull: false,
    validate: {
      isEmail: true
    }
  },
  age: {
    type: DataTypes.INTEGER,
    validate: {
      min: 0
    }
  },
  createdAt: {
    type: DataTypes.DATE,
    defaultValue: DataTypes.NOW
  }
});

// Define a Post model with a foreign key relationship
const Post = ORM.define('Post', {
  id: {
    type: DataTypes.INTEGER,
    primaryKey: true,
    autoIncrement: true
  },
  title: {
    type: DataTypes.STRING,
    allowNull: false
  },
  content: {
    type: DataTypes.TEXT
  },
  userId: {
    type: DataTypes.INTEGER,
    references: {
      model: User,
      key: 'id'
    }
  }
});

// Define relationships
User.hasMany(Post, { foreignKey: 'userId' });
Post.belongsTo(User, { foreignKey: 'userId' });

async function main() {
  try {
    // Initialize database connection
    await ORM.init({
      dialect: 'sqlite',
      storage: './database.sqlite',
      logging: console.log
    });

    // Sync models with database (creates tables)
    await ORM.sync({ force: true });
    console.log('Database synced!');

    // Create a user
    const user = await User.create({
      username: 'john_doe',
      email: 'john@example.com',
      age: 30
    });
    console.log('User created:', user.toJSON());

    // Create a post associated with the user
    const post = await Post.create({
      title: 'My First Post',
      content: 'Hello, world!',
      userId: user.id
    });
    console.log('Post created:', post.toJSON());

    // Query with eager loading
    const userWithPosts = await User.findOne({
      where: { username: 'john_doe' },
      include: [Post]
    });
    console.log('User with posts:', JSON.stringify(userWithPosts, null, 2));

    // Update a record
    await User.update(
      { age: 31 },
      { where: { username: 'john_doe' } }
    );

    // Find all users
    const allUsers = await User.findAll();
    console.log('All users:', allUsers.map(u => u.toJSON()));

    // Transaction example
    await ORM.transaction(async (t) => {
      const newUser = await User.create({
        username: 'jane_doe',
        email: 'jane@example.com',
        age: 25
      }, { transaction: t });

      await Post.create({
        title: 'Jane\'s Post',
        content: 'Transaction test',
        userId: newUser.id
      }, { transaction: t });
    });

  } catch (error) {
    console.error('Error:', error);
  }
}

main();
```

## How It Works:

1. **Model Definition**: You define models using `ORM.define()` which maps JavaScript classes to database tables. Each property corresponds to a table column.

2. **Data Types**: The `DataTypes` object provides type definitions (STRING, INTEGER, DATE, etc.) that map to appropriate SQL types.

3. **Relationships**: You can define associations between models using `hasMany()`, `belongsTo()`, `hasOne()`, etc., which automatically handle foreign keys.

4. **CRUD Operations**: The ORM provides methods like:
   - `create()` - Insert new records
   - `findAll()`, `findOne()` - Query records
   - `update()` - Modify existing records
   - `destroy()` - Delete records

5. **Query Building**: You can build complex queries using the `where` clause with operators, includes for eager loading, and transactions for atomic operations.

6. **Database Sync**: `ORM.sync()` creates/alters tables based on your model definitions. Use `{ force: true }` cautiously as it drops and recreates tables.

7. **Validation**: Built-in validators (isEmail, min/max values, etc.) ensure data integrity before database operations.

The ORM handles SQL generation, parameter binding, and result mapping automatically, allowing you to work with JavaScript objects instead of writing raw SQL queries.

Here's an example of using Go 1.35's `arena.Reset` API to reuse an arena allocator:

```go
package main

import (
    "arena"
    "fmt"
    "time"
)

type Data struct {
    ID    int
    Value string
}

func main() {
    // Create an arena
    a := arena.NewArena()
    defer a.Free() // Always free the arena when done

    // Use the arena multiple times with Reset
    for i := 0; i < 3; i++ {
        processBatch(a, i)

        // Reset the arena to reuse it for next batch
        a.Reset()

        // Optional: Add a small delay to see the effect
        time.Sleep(100 * time.Millisecond)
    }
}

func processBatch(a *arena.Arena, batchNum int) {
    fmt.Printf("Processing batch %d\n", batchNum)

    // Allocate multiple objects in the arena
    objects := make([]*Data, 0, 10)

    for j := 0; j < 5; j++ {
        // Allocate Data struct in arena
        d := arena.New[Data](a)
        d.ID = batchNum*100 + j
        d.Value = fmt.Sprintf("Value-%d-%d", batchNum, j)

        objects = append(objects, d)
    }

    // Use the allocated objects
    for _, obj := range objects {
        fmt.Printf("  Object: ID=%d, Value=%s\n", obj.ID, obj.Value)
    }

    // Note: No need to free individual objects - they'll be freed when arena is reset/freed
    fmt.Printf("Batch %d complete. Arena will be reset.\n\n", batchNum)
}
```

**Key points about `arena.Reset()`:**

1. **Reuse without reallocation**: `Reset()` allows you to reuse the same arena memory for multiple allocation cycles without freeing and reallocating the underlying memory.

2. **Performance benefit**: This is useful when you have repetitive allocation patterns (like processing batches of data) and want to avoid the overhead of repeated memory allocation/deallocation.

3. **Memory safety**: After `Reset()`, all previously allocated objects in the arena become invalid. Don't use them after resetting.

4. **Usage pattern**:
   ```go
   a := arena.NewArena()
   defer a.Free()

   for {
       // Allocate objects
       // Use objects

       a.Reset() // Reuse arena for next iteration
   }
   ```

**Important warnings:**
- Arena API is experimental and may change
- Only use arenas for performance-critical code where you've measured benefits
- Never use arena-allocated objects after calling `Reset()` or `Free()`
- Be careful with arena-allocated slices - they don't grow automatically

**Alternative without Reset (if you need to keep objects alive between resets):**
```go
// If you need to keep some objects alive, allocate them outside the reset cycle
type PersistentData struct {
    Cache *Data // Allocated in separate arena or heap
}

func processWithPersistent(a *arena.Arena, persistent *PersistentData) {
    // Process batch
    a.Reset() // Only resets allocations made in 'a', not persistent.Cache
}
```

Remember to benchmark with and without arenas to ensure they actually improve performance for your specific use case.

In Rust 2027 edition (currently in nightly), you can use `async Drop` to perform asynchronous cleanup. Here's a minimal working example:

```rust
#![feature(async_drop)]

use std::time::Duration;
use tokio::time::sleep;

struct AsyncResource {
    name: String,
}

impl AsyncResource {
    fn new(name: &str) -> Self {
        println!("Creating resource: {}", name);
        Self {
            name: name.to_string(),
        }
    }

    async fn cleanup(&self) {
        println!("Starting async cleanup for: {}", self.name);
        // Simulate async cleanup (e.g., closing network connections, flushing buffers)
        sleep(Duration::from_millis(100)).await;
        println!("Completed async cleanup for: {}", self.name);
    }
}

impl Drop for AsyncResource {
    fn drop(&mut self) {
        println!("Synchronous drop for: {}", self.name);
        // Note: Cannot call async methods here!
    }
}

impl async Drop for AsyncResource {
    async fn drop(&mut self) {
        println!("Async drop starting for: {}", self.name);
        self.cleanup().await;
        println!("Async drop completed for: {}", self.name);
    }
}

#[tokio::main]
async fn main() {
    {
        let resource = AsyncResource::new("test_resource");
        println!("Resource created, going out of scope soon...");
    } // Async drop happens here

    println!("After resource scope");

    // Example with explicit drop
    println!("\n--- Explicit drop example ---");
    let resource2 = AsyncResource::new("explicit_resource");
    drop(resource2).await; // Note: explicit drop now returns a Future

    println!("Main function ending");
}
```

## Key Points:

1. **Enable the feature**: You need `#![feature(async_drop)]` since this is still experimental.

2. **Dual implementation**: You can have both regular `Drop` and `async Drop`:
   - Regular `Drop` runs synchronously (immediately)
   - `async Drop` runs asynchronously when awaited

3. **How it works**:
   - When a value goes out of scope, the compiler generates code that awaits the async drop
   - Explicit `drop(value).await` is now possible
   - The async drop runs before the synchronous drop

4. **Important notes**:
   - The async drop runs **before** the synchronous drop
   - You need an async runtime (like Tokio) to await the drop
   - The value is still accessible in the async drop method

## Compilation and Running:

To compile this example, you need:
- Nightly Rust: `rustup default nightly`
- Enable the feature flag
- An async runtime (Tokio in this example)

Add to your `Cargo.toml`:
```toml
[dependencies]
tokio = { version = "1", features = ["full"] }
```

Run with:
```bash
RUSTFLAGS="--cfg async_drop" cargo +nightly run
```

## Alternative: Using `AsyncDrop` trait (older approach)

Before Rust 2027, you might see code using a custom `AsyncDrop` trait:

```rust
trait AsyncDrop {
    async fn async_drop(&mut self);
}

impl AsyncDrop for AsyncResource {
    async fn async_drop(&mut self) {
        self.cleanup().await;
    }
}
```

But with Rust 2027, the built-in `async Drop` is more ergonomic and integrated with the language's drop semantics.

I'll help you write code using C++29's `std::simd_sort` with execution policies. However, I should note that C++29 is still in development, and `std::simd_sort` is a proposed feature. Let me write code based on the current proposals and expected syntax:

```cpp
#include <algorithm>
#include <execution>
#include <vector>
#include <iostream>
#include <random>
#include <chrono>

int main() {
    // Create a large vector to demonstrate SIMD sorting
    const size_t size = 1000000;
    std::vector<int> data(size);

    // Fill with random values
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<int> dist(1, 1000000);

    for (auto& val : data) {
        val = dist(gen);
    }

    std::cout << "Sorting " << size << " elements with std::simd_sort...\n";

    // Start timing
    auto start = std::chrono::high_resolution_clock::now();

    // Use std::simd_sort with execution policy
    // Note: std::execution::simd is the execution policy for SIMD operations
    std::simd_sort(std::execution::simd, data.begin(), data.end());

    // End timing
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start);

    std::cout << "Sorting completed in " << duration.count() << " ms\n";

    // Verify the sort
    bool is_sorted = std::is_sorted(std::execution::par, data.begin(), data.end());
    std::cout << "Vector is " << (is_sorted ? "sorted" : "NOT sorted") << "\n";

    // Example with custom comparator
    std::vector<double> double_data = {3.14, 2.71, 1.41, 1.62, 2.35};

    std::cout << "\nBefore sorting doubles: ";
    for (const auto& val : double_data) {
        std::cout << val << " ";
    }
    std::cout << "\n";

    // Sort in descending order using SIMD
    std::simd_sort(std::execution::simd, double_data.begin(), double_data.end(),
                   std::greater<double>());

    std::cout << "After sorting (descending): ";
    for (const auto& val : double_data) {
        std::cout << val << " ";
    }
    std::cout << "\n";

    // Example with parallel SIMD (if supported)
    std::vector<float> float_data(size);
    std::generate(float_data.begin(), float_data.end(), [&gen, &dist]() {
        return static_cast<float>(dist(gen));
    });

    // Using parallel SIMD execution policy if available
    // Note: std::execution::par_simd combines parallel and SIMD execution
    std::simd_sort(std::execution::par_simd, float_data.begin(), float_data.end());

    std::cout << "\nFloat vector sorted with par_simd policy\n";

    return 0;
}
```

**Key points about this code:**

1. **Execution Policies:**
   - `std::execution::simd` - Uses SIMD instructions without parallel execution
   - `std::execution::par_simd` - Combines parallel execution with SIMD (if supported)

2. **std::simd_sort features:**
   - Automatically uses SIMD instructions for sorting
   - Works with various data types (int, float, double)
   - Supports custom comparators
   - Integrates with existing execution policies

3. **Compilation notes:**
   - This would require a C++29-compliant compiler
   - You might need compiler flags to enable SIMD instructions (like `-march=native` for GCC/Clang)
   - The actual implementation might vary as the standard is finalized

**Alternative approach for current C++ standards (C++17/20/23):**

