Here's a Java example using value-type generics (Project Valhalla) to store primitives in a generic list without boxing:

```java
import java.util.List;
import java.util.ArrayList;

public class ValueTypeGenericsExample {
    public static void main(String[] args) {
        // Create a list that stores int primitives directly (no boxing)
        List<int> intList = new ArrayList<>();

        // Add primitive int values directly
        intList.add(42);
        intList.add(100);
        intList.add(-5);
        intList.add(0);

        // Retrieve primitive int values directly
        int first = intList.get(0);  // No unboxing needed
        int sum = 0;

        // Iterate and work with primitives directly
        for (int num : intList) {
            sum += num;  // num is primitive int, not Integer
            System.out.println("Value: " + num);
        }

        System.out.println("Sum: " + sum);
        System.out.println("List size: " + intList.size());

        // Example with other primitive types
        List<double> doubleList = new ArrayList<>();
        doubleList.add(3.14);
        doubleList.add(2.718);

        List<boolean> boolList = new ArrayList<>();
        boolList.add(true);
        boolList.add(false);

        // Performance comparison
        long start = System.nanoTime();
        List<int> primitiveList = new ArrayList<>();
        for (int i = 0; i < 1_000_000; i++) {
            primitiveList.add(i);  // No boxing overhead
        }
        long end = System.nanoTime();
        System.out.println("Primitive list time: " + (end - start) / 1_000_000 + " ms");

        // Traditional approach with boxing (for comparison)
        start = System.nanoTime();
        List<Integer> boxedList = new ArrayList<>();
        for (int i = 0; i < 1_000_000; i++) {
            boxedList.add(i);  // Autoboxing occurs here
        }
        end = System.nanoTime();
        System.out.println("Boxed list time: " + (end - start) / 1_000_000 + " ms");
    }
}
```

**Key Benefits Demonstrated:**

1. **No Boxing Overhead**: Primitive values are stored directly in the list's backing array
2. **Direct Access**: Retrieval returns primitive values, not wrapper objects
3. **Memory Efficiency**: No heap allocation for wrapper objects
4. **Cache Locality**: Better performance due to contiguous primitive storage

**Important Notes:**

- This feature is part of Project Valhalla (value types and specialized generics)
- The syntax `List<int>` is now valid (previously only `List<Integer>` was allowed)
- Works with all primitive types: `int`, `double`, `boolean`, `float`, `long`, `short`, `byte`, `char`
- Backward compatible - existing `List<Integer>` code still works
- Significant performance improvements for numeric-heavy applications

**Requirements:**
- Java 30 (or later with Project Valhalla features enabled)
- Compile with appropriate flags if using early access builds

This example shows how value-type generics eliminate the boxing penalty that has existed in Java collections since their inception, providing both performance benefits and cleaner code.

I'll show you how to implement a `useServerState` hook that automatically syncs state between client and server using React 20's features. Here's a complete implementation:

```jsx
// useServerState.js
import { useState, useEffect, useCallback, useRef } from 'react';

// Server-side state store (simulated)
const serverStateStore = new Map();

export function useServerState(key, initialValue) {
  const [state, setState] = useState(initialValue);
  const [isSyncing, setIsSyncing] = useState(false);
  const [error, setError] = useState(null);
  const abortControllerRef = useRef(null);

  // Fetch initial state from server on mount
  useEffect(() => {
    const fetchInitialState = async () => {
      try {
        setIsSyncing(true);
        const response = await fetch(`/api/state/${key}`);
        if (response.ok) {
          const serverState = await response.json();
          setState(serverState.value);
        }
      } catch (err) {
        console.warn(`Could not fetch initial state for ${key}:`, err);
      } finally {
        setIsSyncing(false);
      }
    };

    fetchInitialState();
  }, [key]);

  // Sync state to server
  const syncToServer = useCallback(async (newValue) => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }

    abortControllerRef.current = new AbortController();

    try {
      setIsSyncing(true);
      setError(null);

      const response = await fetch(`/api/state/${key}`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ value: newValue }),
        signal: abortControllerRef.current.signal,
      });

      if (!response.ok) {
        throw new Error(`Server responded with ${response.status}`);
      }

      const result = await response.json();
      return result.success;
    } catch (err) {
      if (err.name !== 'AbortError') {
        setError(err.message);
        console.error('Failed to sync state to server:', err);
      }
      return false;
    } finally {
      setIsSyncing(false);
    }
  }, [key]);

  // Optimistic update with server sync
  const setServerState = useCallback(async (newValueOrUpdater) => {
    const newValue = typeof newValueOrUpdater === 'function'
      ? newValueOrUpdater(state)
      : newValueOrUpdater;

    // Optimistic update
    setState(newValue);

    // Sync to server in background
    syncToServer(newValue).catch(() => {
      // On failure, revert to last known server state
      fetch(`/api/state/${key}`)
        .then(res => res.ok ? res.json() : null)
        .then(serverState => {
          if (serverState) {
            setState(serverState.value);
          }
        });
    });
  }, [state, key, syncToServer]);

  // Real-time updates via WebSocket or Server-Sent Events
  useEffect(() => {
    const eventSource = new EventSource(`/api/state/${key}/stream`);

    eventSource.onmessage = (event) => {
      const data = JSON.parse(event.data);
      if (data.key === key) {
        setState(data.value);
      }
    };

    eventSource.onerror = () => {
      console.warn('SSE connection lost, attempting reconnect...');
    };

    return () => eventSource.close();
  }, [key]);

  return [state, setServerState, { isSyncing, error }];
}

// Server API endpoints (Node.js/Express example)
export function createServerStateAPI(app) {
  // Get state
  app.get('/api/state/:key', (req, res) => {
    const { key } = req.params;
    const value = serverStateStore.get(key) || null;
    res.json({ key, value });
  });

  // Update state
  app.post('/api/state/:key', (req, res) => {
    const { key } = req.params;
    const { value } = req.body;

    serverStateStore.set(key, value);

    // Broadcast to all connected clients
    broadcastStateUpdate(key, value);

    res.json({ success: true, key, value });
  });

  // Server-Sent Events for real-time updates
  const clients = new Map();

  app.get('/api/state/:key/stream', (req, res) => {
    const { key } = req.params;

    res.writeHead(200, {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      'Connection': 'keep-alive',
    });

    const clientId = Date.now();
    clients.set(clientId, { res, key });

    req.on('close', () => {
      clients.delete(clientId);
    });
  });

  function broadcastStateUpdate(key, value) {
    clients.forEach((client, clientId) => {
      if (client.key === key) {
        client.res.write(`data: ${JSON.stringify({ key, value })}\n\n`);
      }
    });
  }
}

// Example component usage
function Counter() {
  const [count, setCount, { isSyncing, error }] = useServerState('counter', 0);

  return (
    <div>
      <h2>Counter: {count}</h2>
      {isSyncing && <small>Syncing...</small>}
      {error && <small style={{ color: 'red' }}>Error: {error}</small>}
      <button onClick={() => setCount(c => c + 1)}>Increment</button>
      <button onClick={() => setCount(0)}>Reset</button>
    </div>
  );
}

// Example with form
function UserProfile() {
  const [user, setUser] = useServerState('user-profile', {
    name: '',
    email: '',
    preferences: {}
  });

  const updateField = (field, value) => {
    setUser(prev => ({ ...prev, [field]: value }));
  };

  return (
    <div>
      <input
        value={user.name}
        onChange={(e) => updateField('name', e.target.value)}
        placeholder="Name"
      />
      <input
        value={user.email}
        onChange={(e) => updateField('email', e.target.value)}
        placeholder="Email"
      />
    </div>
  );
}
```

## How It Works:

