        return self._data.items()

    def keys(self):
        """Get configuration keys."""
        return self._data.keys()

    def values(self):
        """Get configuration values."""
        return self._data.values()

    def update(self, new_data):
        """
        Create a new ImmutableConfig with updated data.

        Args:
            new_data: Dict or mapping with updates

        Returns:
            New ImmutableConfig instance with merged data
        """
        # Create a new frozenmap by merging current data with updates
        merged = self._data.update(new_data)
        new_config = ImmutableConfig()
        new_config._data = merged
        return new_config

    def remove(self, key):
        """
        Create a new ImmutableConfig without the specified key.

        Args:
            key: Key to remove

        Returns:
            New ImmutableConfig instance without the key
        """
        if key not in self._data:
            return self

        # Create a new frozenmap without the key
        new_data = {k: v for k, v in self._data.items() if k != key}
        new_config = ImmutableConfig()
        new_config._data = frozenmap(new_data)
        return new_config

