from __future__ import annotations

import json
from typing import Any, Callable, Dict, List, Optional


# --- Wire format tags ---
_TAG = "__py__"      # marks a tagged object envelope
_ID = "__id__"       # first-occurrence id
_REF = "__ref__"     # back-reference to a previously seen id
_TYPE = "__type__"   # container/object type


def _default_sort_key(x: Any):
    """Stable sort key: comparable items sort naturally; otherwise fall back to repr."""
    try:
        return (0, x)
    except TypeError:
        return (1, repr(type(x)), repr(x))


# ---------------------------------------------------------------------------
# Encoder
# ---------------------------------------------------------------------------
class _Encoder:
    def __init__(self, sort_key: Optional[Callable] = None):
        self._sort_key = sort_key or _default_sort_key
        self._id_map: Dict[int, int] = {}   # id(obj) -> sequential ref id
        self._objects: List[Any] = []       # keeps originals alive (id stability)

    def encode(self, obj: Any) -> str:
        # Reset state so the encoder is reusable.
        self._id_map.clear()
        self._objects.clear()
        return json.dumps(self._convert(obj))

    # -- internal ---------------------------------------------------------
    def _convert(self, obj: Any) -> Any:
        # Primitives are immutable → identity is irrelevant.
        if obj is None or isinstance(obj, (bool, int, float, str)):
            return obj

        obj_id = id(obj)
        if obj_id in self._id_map:
            return {_TAG: True, _REF: self._id_map[obj_id]}

        new_id = len(self._objects)
        self._id_map[obj_id] = new_id
        self._objects.append(obj)  # pin in memory so id() stays valid

        if isinstance(obj, set):
            items = sorted(obj, key=self._sort_key)
            return {_TAG: True, _ID: new_id, _TYPE: "set",
                    "items": [self._convert(i) for i in items]}
        if isinstance(obj, frozenset):
            items = sorted(obj, key=self._sort_key)
            return {_TAG: True, _ID: new_id, _TYPE: "frozenset",
                    "items": [self._convert(i) for i in items]}
        if isinstance(obj, list):
            return {_TAG: True, _ID: new_id, _TYPE: "list",
                    "items": [self._convert(i) for i in obj]}
        if isinstance(obj, tuple):
            return {_TAG: True, _ID: new_id, _TYPE: "tuple",
                    "items": [self._convert(i) for i in obj]}
        if isinstance(obj, dict):
            return {_TAG: True, _ID: new_id, _TYPE: "dict",
                    "items": [[self._convert(k), self._convert(v)] for k, v in obj.items()]}

        # Arbitrary object: serialize its __dict__.
        return {_TAG: True, _ID: new_id, _TYPE: "object",
                "class": f"{type(obj).__module__}.{type(obj).__qualname__}",
                "data": self._convert(obj.__dict__)}


# ---------------------------------------------------------------------------
# Decoder
# ---------------------------------------------------------------------------
class _Decoder:
    def __init__(self, class_registry: Optional[Dict[str, type]] = None):
        self._objects: List[Any] = []
        self._class_registry = class_registry or {}

    def decode(self, s: str) -> Any:
        self._objects.clear()
        return self._convert(json.loads(s))

    def _convert(self, obj: Any) -> Any:
        if not isinstance(obj, dict):
            return obj
        if obj.get(_TAG) is not True:
            # Plain (un-tagged) dict — recurse into values.
            return {k: self._convert(v) for k, v in obj.items()}

        if _REF in obj:
            return self._objects[obj[_REF]]

        obj_id = obj[_ID]
        t = obj[_TYPE]

        # Grow the object table so obj_id is a valid index.
        if len(self._objects) <= obj_id:
            self._objects.extend([None] * (obj_id - len(self._objects) + 1))

        if t == "set":
            result = set(self._convert(i) for i in obj["items"])
        elif t == "frozenset":
            result = frozenset(self._convert(i) for i in obj["items"])
        elif t == "list":
            result = [self._convert(i) for i in obj["items"])
        elif t == "tuple":
            result = tuple(self._convert(i) for i in obj["items"])
        elif t == "dict":
            result = {self._convert(k): self._convert(v) for k, v in obj["items"]}
        elif t == "object":
            class_path = obj["class"]
            cls = self._class_registry.get(class_path)
            if cls is None:
                result = type(class_path.rsplit(".", 1)[-1], (), {})()
            else:
                result = cls.__new__(cls)
            data = self._convert(obj["data"])
            result.__dict__.update(data)
        else:
            raise ValueError(f"Unknown type tag: {t!r}")

        self._objects[obj_id] = result
        return result


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------
def dumps(obj: Any, *, sort_key: Optional[Callable] = None) -> str:
    """Serialize `obj` to a JSON string, preserving set order and object identity."""
    return _Encoder(sort_key=sort_key).encode(obj)


