type LockRequest struct {
    ClientID string
    TTL      time.Duration
    Reply    chan *LockResponse
}

type LockResponse struct {
    Token FencingToken
    Err   error
}

// LockServer is a simple lock coordinator
// In production, this would be replicated via Raft/Paxos
type LockServer struct {
    mu sync.Mutex

    currentHolder string
    currentToken  FencingToken
    leaseExpiry   time.Time

    nextToken FencingToken

    requests chan *LockRequest
    stop     chan struct{}
}

func NewLockServer() *LockServer {
    s := &LockServer{
        nextToken: 1,
        requests:  make(chan *LockRequest, 100),
        stop:      make(chan struct{}),
    }
    go s.run()
    return s
}

func (s *LockServer) Acquire(clientID string, ttl time.Duration) (FencingToken, error) {
    reply := make(chan *LockResponse, 1)
    s.requests <- &LockRequest{
        ClientID: clientID,
        TTL:      ttl,
        Reply:    reply,
    }
    resp := <-reply
    return resp.Token, resp.Err
}

func (s *LockServer) run() {
    ticker := time.NewTicker(50 * time.Millisecond)
    defer ticker.Stop()

    for {
        select {
        case req := <-s.requests:
            s.handleRequest(req)
        case <-ticker.C:
            s.checkExpiry()
        case <-s.stop:
            return
        }
    }
}

func (s *LockServer) handleRequest(req *LockRequest) {
    s.mu.Lock()
    defer s.mu.Unlock()

    // Check if lock is free or expired
    if s.currentHolder == "" || time.Now().After(s.leaseExpiry) {
        // Grant lock
        s.currentHolder = req.ClientID
        s.currentToken = s.nextToken
        s.nextToken++
        s.leaseExpiry = time.Now().Add(req.TTL)
        req.Reply <- &LockResponse{Token: s.currentToken}
        return
    }

