const Ok = <T,>(value: T): Result<T, never> => ({ ok: true, value });
const Err = <E,>(error: E): Result<never, E> => ({ ok: false, error });

type Json =
  | { tag: "null" }
  | { tag: "bool"; value: boolean }
  | { tag: "num"; value: number }
  | { tag: "str"; value: string }
  | { tag: "arr"; value: Json[] }
  | { tag: "obj"; value: [string, Json][] };

function parse(input: string): Result<Json, string> {
  let i = 0;
  const peek = () => i < input.length ? input[i] : null;
  const eat = () => input[i++];

  const skipWs = () => {
    while (i < input.length && " \t\n\r".includes(input[i])) i++;
  };

  const parseString = (): Result<Json, string> => {
    if (eat() !== '"') return Err("expected '\"'");
    let s = "";
    while (i < input.length && peek() !== '"') {
      const c = eat();
      if (c === '\\') {
        if (i >= input.length) return Err("unterminated escape");
        const e = eat();
        if (e === '"') s += '"';
        else if (e === '\\') s += '\\';
        else if (e === '/') s += '/';
        else if (e === 'b') s += '\b';
        else if (e === 'f') s += '\f';
        else if (e === 'n') s += '\n';
        else if (e === 'r') s += '\r';
        else if (e === 't') s += '\t';
        else if (e === 'u') {
          // \uXXXX
          if (i + 4 > input.length) return Err("invalid unicode escape");
          const hex = input.slice(i, i + 4);
          i += 4;
          const code = parseInt(hex, 16);
          if (isNaN(code)) return Err("invalid unicode escape");
          s += String.fromCharCode(code);
        } else return Err(`invalid escape \\${e}`);
      } else if (c === '"') break;
      else s += c;
    }
    if (peek() !== '"') return Err("unterminated string");
    eat(); // consume closing quote
    return Ok({ tag: "str", value: s });
  };

  // ... similar for other types

  const parseValue = (): Result<Json, string> => {
    const c = peek();
    if (c === null) return Err("unexpected end of input");
    if (c === '"') return parseString();
    if (c === '{') return parseObject();
    if (c === '[') return parseArray();
    if (c === 't' || c === 'f') return parseBool();
    if (c === 'n') return parseNull();
    if (c === '-' || (c >= '0' && c <= '9')) return parseNumber();
    return Err(`unexpected character '${c}'`);
  };

  skipWs();
  const result = parseValue();
  if (!result.ok) return result;
  skipWs();
  if (i < input.length) return Err("trailing content");
  return result;
}
