## The Code

```java
import java.nio.charset.StandardCharsets;

/**
 * Hash64 — a 64-bit hash function in the style of SipHash-2-4.
 *
 * <p>Provides a fast, deterministic 64-bit digest suitable for hash
 * tables, integrity tags, and similar uses.  It is <strong>not</strong>
 * a substitute for SHA-256 in security-critical contexts: its 64-bit
 * output is too small to resist brute-force search.
 *
 * <p>Construction: Merkle–Damgård iteration of a 256-bit compression
 * function built from the SipRound permutation.
 */
public final class Hash64 {

    /* ASCII-encoded "somepseudo random key" — SipHash constants. */
    private static final long K0 = 0x736f6d6570736575L;
    private static final long K1 = 0x646f72616e646f6dL;
    private static final long K2 = 0x6c7967656e657261L;
    private static final long K3 = 0x7465646279746573L;

    private Hash64() {}

    /** Returns the 64-bit hash of {@code message}. */
    public static long hash(byte[] message) {
        long[] v = { K0, K1, K2, K3 };
        int len = message.length;
        int full = len >>> 3;          // # of complete 8-byte blocks
        int tail = len & 7;            // remaining bytes

        // 1. Process every complete 8-byte block.
        for (int i = 0; i < full; i++) {
            compress(v, readLongLE(message, i << 3));
        }

        // 2. Final block: leftover bytes (little-endian) + length byte.
        long last = 0;
        int off = full << 3;
        for (int i = 0; i < tail; i++) {
            last |= (long)(message[off + i] & 0xff) << (i << 3);
        }
        last |= (long)len << (tail << 3);   // length at position tail
        compress(v, last);

        // 3. Finalisation: domain-separation byte + 4 mixing rounds.
        v[2] ^= 0xffL;
        for (int i = 0; i < 4; i++) sipRound(v);

        return v[0] ^ v[1] ^ v[2] ^ v[3];
    }

    /** Convenience overload for strings (UTF-8). */
    public static long hash(String s) {
        return hash(s.getBytes(StandardCharsets.UTF_8));
    }

    /* ---------- internals ---------- */

    /** Compression step: XOR-in, mix twice, XOR-out (Davies–Meyer style). */
    private static void compress(long[] v, long m) {
        v[3] ^= m;
        sipRound(v);
        sipRound(v);
        v[0] ^= m;
    }

    private static long readLongLE(byte[] b, int off) {
        return ((long)(b[off]   & 0xff))       |
               ((long)(b[off+1] & 0xff) <<  8) |
               ((long)(b[off+2] & 0xff) << 16) |
               ((long)(b[off+3] & 0xff) << 24) |
               ((long)(b[off+4] & 0xff) << 32) |
               ((long)(b[off+5] & 0xff) << 40) |
               ((long)(b[off+6] & 0xff) << 48) |
               ((long)(b[off+7] & 0xff) << 56);
    }

    /**
     * SipRound — a key-dependent permutation on (v0,v1,v2,v3).
     * Each round: 2 additions, 3 rotations (13/16/32, 17/21/32), 4 XORs.
     * Bijective on the 256-bit state.
     */
    private static void sipRound(long[] v) {
        v[0] += v[1]; v[2] += v[3];
        v[1] = Long.rotateLeft(v[1], 13);
        v[3] = Long.rotateLeft(v[3], 16);
        v[1] ^= v[0]; v[3] ^= v[2];
        v[0] = Long.rotateLeft(v[0], 32);
        v[2] += v[1]; v[0] += v[3];
        v[1] = Long.rotateLeft(v[1], 17);
        v[3] = Long.rotateLeft(v[3], 21);
        v[1] ^= v[2]; v[3] ^= v[0];
        v[2] = Long.rotateLeft(v[2], 32);
    }

    /* ---------- demo ---------- */
    public static void main(String[] args) {
        String[] inputs = { "", "a", "Hello", "Hello!", "Hello!!",
                            "The quick brown fox jumps over the lazy dog" };
        for (String s : inputs) {
            System.out.printf("hash(%-46s) = 0x%016x%n",
                              "\"" + s + "\"", hash(s));
        }
        long a = hash("test"), b = hash("Test");
        System.out.printf("%nAvalanche: 0x%016x%n           vs%n           0x%016x"
                        + " -> %d bits differ (ideal ~32)%n",
                        a, b, Long.bitCount(a ^ b));
    }
}
