    private static final long K1 = 0x646f72616e646f6dL;
    private static final long K2 = 0x6c7967656e657261L;
    private static final long K3 = 0x7465646279746573L;

    private Hash64() {}

    /** Returns the 64-bit hash of the given message. */
    public static long hash(byte[] message) {
        long[] v = { K0, K1, K2, K3 };
        int len = message.length;
        int full = len >>> 3;
        int tail = len & 7;

