               ((long)(b[off+3] & 0xff) << 24) |
               ((long)(b[off+4] & 0xff) << 32) |
               ((long)(b[off+5] & 0xff) << 40) |
               ((long)(b[off+6] & 0xff) << 48) |
               ((long)(b[off+7] & 0xff) << 56);
