        v[0] = Long.rotateLeft(v[0], 32);
        v[2] += v[1]; v[0] += v[3];
        v[1] = Long.rotateLeft(v[1], 17);
        v[3] = Long.rotateLeft(v[3], 21);
        v[1] ^= v[2]; v[3] ^= v[0];
        v[2] = Long.rotateLeft(v[2], 32);
