const NUM_ACCOUNTS = 4;
const INITIAL_BALANCE = 1000;
const NUM_TRANSFERS = 100_000;
const NUM_WORKERS = 4;

// Shared memory: balances + locks
const sab = new SharedArrayBuffer(
  (NUM_ACCOUNTS + NUM_ACCOUNTS) * Int32Array.BYTES_PER_ELEMENT
);

// Initialize balances
const i32 = new Int32Array(sab);
for (let i = 0; i < NUM_ACCOUNTS; i++) i32[i] = INITIAL_BALANCE;

const expectedTotal = NUM_ACCOUNTS * INITIAL_BALANCE;

// Spawn workers
const workers = await Promise.all(
