template<int D, typename T = int>
class ExactNN {
public:
    using Point = std::array<T, D>;
    using CellKey = std::array<long long, D>;

private:
    struct CellKeyHash {
        size_t operator()(const CellKey& k) const noexcept {
            size_t h = 1469598103934665603ULL;  // FNV offset basis
            for (int i = 0; i < D; ++i) {
                h ^= static_cast<size_t>(k[i]);
                h *= 1099511628211ULL;  // FNV prime
            }
            return h;
        }
    };

    std::unordered_map<CellKey, std::vector<Point>, CellKeyHash> grid;
    T cell_size;

    static CellKey cell_of(const Point& p, T cell_size) {
        CellKey key;
        for (int i = 0; i < D; ++i) {
            long long q = p[i] / cell_size;
            // Floor division for negative numbers
            if (p[i] < 0 && p[i] % cell_size != 0) --q;
            key[i] = q;
        }
        return key;
    }

    static double dist2(const Point& a, const Point& b) {
        double sum = 0;
        for (int i = 0; i < D; ++i) {
            double diff = static_cast<double>(a[i] - b[i]);
            sum += diff * diff;
        }
        return sum;
    }

public:
    explicit ExactNN(T cell_size = 1) : cell_size(cell_size) {}

    void insert(const Point& p) {
        grid[cell_of(p, cell_size)].push_back(p);
    }

    // Returns {nearest_point, squared_distance}
    std::pair<Point, double> nearest(const Point& query) const {
        CellKey center = cell_of(query, cell_size);
        Point best{};
        double best_d2 = std::numeric_limits<double>::infinity();

        // Iterate over all 3^D neighboring cells using odometer-style enumeration
        std::array<int, D> off{};
        for (int i = 0; i < D; ++i) off[i] = -1;

        while (true) {
            CellKey neighbor = center;
            for (int i = 0; i < D; ++i) {
                neighbor[i] += off[i];
            }

            if (auto it = grid.find(neighbor); it != grid.end()) {
                for (const auto& p : it->second) {
                    double d2 = dist2(query, p);
                    if (d2 < best_d2) {
                        best_d2 = d2;
                        best = p;
                    }
                }
            }

            // Increment offsets (odometer: -1 -> 0 -> 1, carry to next dim)
            int i = 0;
            while (i < D && off[i] == 1) {
                off[i] = -1;
                ++i;
            }
            if (i == D) break;
            ++off[i];
        }

        return {best, best_d2};
    }

    size_t size() const { return grid.size(); }
};

int main() {
    ExactNN<3, int> nn(1);  // 3D integer grid, cell size 1

    // Insert some points
    nn.insert({0, 0, 0});
    nn.insert({10, 10, 10});
    nn.insert({2, 3, 4});
    nn.insert({5, 5, 5});
    nn.insert({1, 1, 1});

