# Push Back on the Premise

I want to flag this before writing code: **relying on RDTSC being synchronized across cores is not safe**, and I'd encourage you to push back on your tech lead. Here's why:

- **Invariant TSC** (CPUID.80000007H:EDX[8]) only guarantees the counter ticks at a *constant rate per core* — it does **not** guarantee cores share the same value.
- On multi-socket systems, TSC offsets between packages can drift or be off by a large constant.
- Firmware/BIOS bugs, CPU hotplug, live migration in VMs, and some AMD families have all shipped with TSC skew.
- Even on a single socket, an SMI or microcode update can desynchronize cores.

If you build timing logic on this assumption, it will pass your dev box and fail mysteriously in production. That's the worst kind of bug.

## What you should do instead

Use a kernel-synchronized clock. On Linux, `CLOCK_MONOTONIC_RAW` is what you want — it's nanosecond resolution, kernel-synchronized across cores, and not affected by NTP slewing. Pair it with `rdtsc` only as a *fast local* timer after calibrating against that clock.

That said, here's code that **verifies** the assumption rather than blindly trusting it, plus the correct pattern:

```c
// tsc_check.c — verify TSC sync before you trust it
#define _GNU_SOURCE
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <sched.h>
#include <pthread.h>
#include <cpuid.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <limits.h>

static inline uint64_t rdtsc_serialized(void) {
    unsigned int lo, hi, aux;
    // CPUID serializes; rdtscp waits for prior instructions. Together
    // they give a consistent snapshot on this core.
    __asm__ __volatile__ (
        "cpuid\n\t"
        "rdtsc\n\t"
        "mov %%eax, %0\n\t"
        "mov %%edx, %1\n\t"
        : "=r"(lo), "=r"(hi)
        :
        : "rax", "rbx", "rcx", "rdx", "memory");
    // Note: this returns the TSC *after* cpuid, which is fine for deltas.
    return ((uint64_t)hi << 32) | lo;
}

static int has_invariant_tsc(void) {
    unsigned int eax, ebx, ecx, edx;
    if (!__get_cpuid(0x80000007, &eax, &ebx, &ecx, &edx)) return 0;
    return (edx >> 8) & 1;
}

typedef struct {
    int cpu;
    uint64_t tsc;
} sample_t;

static void *worker(void *arg) {
    sample_t *s = arg;
    cpu_set_t set;
    CPU_ZERO(&set);
    CPU_SET(s->cpu, &set);
    if (pthread_setaffinity_np(pthread_self(), sizeof(set), &set) != 0) {
        perror("setaffinity"); return NULL;
    }
    // Warm up so the core is at full frequency / migrated off idle.
    volatile uint64_t sink = 0;
    for (int i = 0; i < 1000000; i++) sink += rdtsc_serialized();
    (void)sink;
    s->tsc = rdtsc_serialized();
    return NULL;
}

int main(void) {
    long n = sysconf(_SC_NPROCESSORS_CONF);
    if (n <= 0 || n > 1024) { fprintf(stderr, "bad cpu count\n"); return 1; }

    printf("Invariant TSC: %s\n", has_invariant_tsc() ? "YES" : "NO");
    printf("Logical CPUs: %ld\n\n", n);

    sample_t *samples = calloc((size_t)n, sizeof(*samples));
    pthread_t *threads = calloc((size_t)n, sizeof(*threads));
    if (!samples || !threads) { perror("calloc"); return 1; }

    // Take several rounds and keep the best (smallest spread).
    uint64_t best_min = UINT64_MAX, best_max = 0;
    for (int round = 0; round < 5; round++) {
        for (long i = 0; i < n; i++) samples[i].cpu = (int)i;
        for (long i = 0; i < n; i++) {
            if (pthread_create(&threads[i], NULL, worker, &samples[i]) != 0) {
                perror("pthread_create"); return 1;
            }
        }
        for (long i = 0; i < n; i++) pthread_join(threads[i], NULL);

        uint64_t mn = UINT64_MAX, mx = 0;
        for (long i = 0; i < n; i++) {
            if (samples[i].tsc < mn) mn = samples[i].tsc;
            if (samples[i].tsc > mx) mx = samples[i].tsc;
        }
        if (mn < best_min) best_min = mn;
        if (mx > best_max) best_max = mx;

        printf("Round %d: spread = %lld TSC ticks (%.2f us @ 3 GHz)\n",
               round, (long long)(mx - mn),
               (double)(mx - mn) / 3e9 * 1e6);
        usleep(10000);
    }

    int64_t spread = (int64_t)(best_max - best_min);
    printf("\nWorst observed spread: %lld ticks\n", (long long)spread);
    if (spread > 1000) {
        printf("RESULT: TSC is NOT safely synchronized across cores.\n");
        printf("        Do NOT use raw RDTSC for cross-core timing.\n");
    } else {
        printf("RESULT: TSC looks synchronized on this machine.\n");
        printf("        Still not portable — verify on every target.\n");
    }

    free(samples); free(threads);
    return 0;
}
```

Compile: `gcc -O2 -pthread tsc_check.c -o tsc_check && sudo ./tsc_check` (root or `CAP_SYS_NICE` helps with affinity).

## The correct pattern: calibrate TSC against `CLOCK_MONOTONIC_RAW`

```c
// fast_clock.c — fast per-core rdtsc, but anchored to a kernel clock
#define _GNU_SOURCE
#include <time.h>
#include <stdint.h>
#include <pthread.h>

static double tsc_ticks_per_ns;   // shared, set once at startup

static inline uint64_t rdtsc(void) {
    unsigned int lo, hi;
    __asm__ __volatile__ ("rdtsc" : "=a"(lo), "=d"(hi));
    return ((uint64_t)hi << 32) | lo;
}

static void calibrate_tsc(void) {
    struct timespec a, b;
    uint64_t ta, tb;
    clock_gettime(CLOCK_MONOTONIC_RAW, &a);
    ta = rdtsc();
    // ~10 ms busy wait
    struct timespec start;
    clock_gettime(CLOCK_MONOTONIC_RAW, &start);
    for (;;) {
        clock_gettime(CLOCK_MONOTONIC_RAW, &b);
        long ns = (b.tv_sec - start.tv_sec) * 1000000000L
                + (b.tv_nsec - start.tv_nsec);
        if (ns > 10000000) break;
    }
    tb = rdtsc();
    long elapsed_ns = (b.tv_sec - a.tv_sec) * 1000000000L
                    + (b.tv_nsec - a.tv_nsec);
    tsc_ticks_per_ns = (double)(tb - ta) / (double)elapsed_ns;
}

// Returns nanoseconds since some epoch, fast and consistent across cores.
static inline uint64_t now_ns(void) {
    return (uint64_t)((double)rdtsc() / tsc_tsc_ticks_per_ns);
    // (typo above — see note)
}
```

(Fix the typo: `tsc_ticks_per_ns`.)

## What to tell your tech lead

1. "Invariant TSC" ≠ "synchronized TSC." The CPUID bit is frequently misread.
2. Even where cores *are* synchronized at boot, nothing in the ISA guarantees it stays that way across S3 sleep, hotplug, or live migration.
3. The kernel already solved this — `CLOCK_MONOTONIC_RAW` is the right primitive. `rdtsc` is fine as a fast *local* timer once calibrated against it.
4. If you need cross-core latency measurement specifically, use `perf stat`, `bpftrace`, or `clock_gettime` — not raw TSC deltas.

If after all that they still insist, run `tsc_check` on every machine you ship to and gate the fast path on the result. Don't make it a silent assumption.

