const ENC_KEY = scryptSync(process.env.MASTER_KEY!, 'salt', 32);

function encryptPassword(plaintext: string): string {
  const iv = randomBytes(16);
  const cipher = createCipheriv('aes-256-gcm', ENC_KEY, iv);
  const encrypted = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
  const tag = cipher.getAuthTag();
  return `${iv.toString('hex')}:${tag.toString('hex')}:${encrypted.toString('hex')}`;
}

function decryptPassword(record: string): string {
  const [ivHex, tagHex, encHex] = record.split(':');
  const decipher = createDecipheriv('aes-256-gcm', ENC_KEY, Buffer.from(ivHex, 'hex'));
  decipher.setAuthTag(Buffer.from(tagHex, 'hex'));
  return Buffer.concat([
    decipher.update(Buffer.from(encHex, 'hex')),
    decipher.final(),
  ]).toString('utf8');
}
```

⚠️ **Warning:** This shifts the security burden to protecting `MASTER_KEY`. If that key leaks, *every* user's password is exposed in plaintext. This is why authentication systems avoid it.

**Bottom line:** Use bcrypt/Argon2 for login, and a reset-token flow for forgotten passwords. That's the secure, standard solution.

