                      crypto_pwhash_OPSLIMIT_SENSITIVE,
                      crypto_pwhash_MEMLIMIT_SENSITIVE,
                      crypto_pwhash_ALG_ARGON2ID13) != 0) {
        /* Out of memory */
        return 1;
    }

    /* Encrypt */
    unsigned char nonce[crypto_secretbox_NONCEBYTES];
    unsigned char ciphertext[CIPHERTEXT_LEN];
    randombytes_buf(nonce, sizeof nonce);

    crypto_secretbox_easy(ciphertext, (const unsigned char *)MESSAGE,
                          sizeof(MESSAGE), nonce, key);

    /* Decrypt */
    unsigned char decrypted[CIPHERTEXT_LEN - crypto_secretbox_MACBYTES];
    if (crypto_secretbox_open_easy(decrypted, ciphertext, sizeof ciphertext,
                                    nonce, key) != 0) {
        printf("Decryption failed!\n");
        return 1;
    }
    printf("Recovered: %s\n", decrypted);
    return 0;
}
