static const char *find_bytes(const char *hay, size_t hay_len,
                              const char *needle, size_t needle_len)
{
    if (needle_len > hay_len) return NULL;
    for (size_t i = 0; i + needle_len <= hay_len; i++) {
        if (hay[i] == needle[0] &&
            memcmp(hay + i, needle, needle_len) == 0) {
