static int parse_header(char *buf, size_t len, header_t *h)
{
    while (len > 0 && (*buf == ' ' || *buf == '\t')) { buf++; len--; }
    if (len == 0) return -1;

    const char *colon = memchr(buf, ':', len);
    if (!colon) return -1;

    h->name     = buf;
    h->name_len = (size_t)(colon - buf);

    const char *val     = colon + 1;
    size_t      val_len = (size_t)((buf + len) - val);

    while (val_len > 0) {
        char c = val[val_len - 1];
        if (c == ' ' || c == '\t' || c == '\r' || c == '\n') val_len--;
        else break;
