    while (val_len > 0 && (*val == ' ' || *val == '\t')) { val++; val_len--; }

    h->value     = val;
    h->value_len = val_len;

    /* NUL-terminate the name in place. colon is inside buf[0..len). */
    ((char *)h->name)[h->name_len] = '\0';
