    char  *buf = NULL;
    size_t cap = 0, len = 0;

    for (;;) {
        if (cap - len < 1024) {
            if (cap >= MAX_REQSZ) break;
            size_t new_cap = cap ? cap * 2 : INITIAL_BUFSZ;
            if (new_cap > MAX_REQSZ) new_cap = MAX_REQSZ;
