            if (!nb) { free(buf); return -1; }
            buf = nb;
            cap = new_cap;
        }
        ssize_t n = read(fd, buf + len, cap - len);
        if (n < 0) {
            if (errno == EINTR) continue;
            free(buf);
            return -1;
        }
        if (n == 0) break;
        len += (size_t)n;
        if (find_bytes(buf, len, "\r\n\r\n", 4) ||
            find_bytes(buf, len, "\n\n", 2)) {
            break;
        }
    }

    *out_buf = buf;
    return (ssize_t)len;
}

