    ssize_t len = read_request(fd, &buf);
    if (len <= 0) { free(buf); return; }

    request_t req;
    if (parse_request(buf, (size_t)len, &req) != 0) {
        static const char err[] =
            "HTTP/1.1 400 Bad Request\r\n"
            "Content-Length: 0\r\n\r\n";
        write(fd, err, sizeof err - 1);
        free(buf);
        return;
    }

    size_t resp_len;
    char *resp = make_response(&req, &resp_len);
    if (resp) {
        write(fd, resp, resp_len);
        free(resp);
    }
    free(buf);
