Below is a self-contained, single-file Java 17 example. It implements the core of Raft (terms, leader election with randomized timeouts, log replication, term/prev-index checks) under a simulated partially-synchronous network where messages can be dropped, delayed, or reordered, and nodes can crash. The failure paths are explicit so you can map them to the protocol.

```java
// RaftDemo.java  --  javac RaftDemo.java && java RaftDemo
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * Minimal Raft-style consensus under partial synchrony.
 *
 * Partial-synchrony assumption (DLS):
 *   There exists an unknown Global Stabilization Time (GST) after which
 *   messages are delivered within a bounded delay and nodes process at a
 *   bounded rate. Before GST, the network may drop, delay, duplicate, or
 *   reorder messages arbitrarily.
 *
 * The implementation makes this explicit by:
 *   - randomizing election timeouts (so collisions are unlikely after GST),
 *   - retrying RPCs indefinitely (no upper bound on message delay),
 *   - never trusting a single response (majority quorums).
 */
public class RaftDemo {

    /* ---------- Domain model ---------- */

    enum Role { FOLLOWER, CANDIDATE, LEADER }

    static class LogEntry {
        final long term;
        final String cmd;
        LogEntry(long term, String cmd) { this.term = term; this.cmd = cmd; }
        public String toString() { return "t" + term + ":" + cmd; }
    }

    interface Message {}

    static class RequestVoteReq implements Message {
        final int from, to; final long term, lastLogIdx, lastLogTerm;
        RequestVoteReq(int f, int t, long term, long li, long lt) {
            from=f; to=t; term=term; lastLogIdx=li; lastLogTerm=lt;
        }
    }
    static class RequestVoteResp implements Message {
        final int from, to; final long term; final boolean granted;
        RequestVoteResp(int f, int t, long term, boolean g) {
            from=f; to=t; term=term; granted=g;
        }
    }
    static class AppendEntriesReq implements Message {
        final int from, to; final long term, prevLogIdx, prevLogTerm;
        final List<LogEntry> entries; final long leaderCommit;
        AppendEntriesReq(int f,int t,long term,long pli,long plt,
                         List<LogEntry> e,long lc){
            from=f; to=t; term=term; prevLogIdx=pli; prevLogTerm=plt;
            entries=e; leaderCommit=lc;
        }
    }
    static class AppendEntriesResp implements Message {
        final int from, to; final long term; final boolean success;
        final long matchIndex;
        AppendEntriesResp(int f,int t,long term,boolean s,long mi){
            from=f; to=t; term=term; success=s; matchIndex=mi;
        }
    }

    /* ---------- Simulated network ---------- */

    /**
     * Partially-synchronous network: messages may be dropped, delayed,
     * duplicated, or reordered. After `stabilizeAt` simulated ms, delivery
     * becomes reliable within `maxDelay` ms. Nodes may also be "crashed"
     * (their inbound queue is shut down).
     */
    static class Network {
        final long stabilizeAt;      // simulated ms
        final long maxDelay;         // simulated ms after GST
        final Random rnd = new Random(42);
        final List<BlockingQueue<Message>> inbound;
        final AtomicInteger now = new AtomicInteger();

        Network(int nodes, long stabilizeAt, long maxDelay) {
            this.stabilizeAt = stabilizeAt;
            this.maxDelay = maxDelay;
            this.inbound = new ArrayList<>();
            for (int i = 0; i < nodes; i++)
                inbound.add(new LinkedBlockingQueue<>());
        }

        void send(Message m) {
            // Drop ~10% of messages before GST, none after.
            if (now.get() < stabilizeAt && rnd.nextDouble() < 0.10) return;
            int dest = destOf(m);
            if (dest < 0) return;
            long delay = now.get() < stabilizeAt
                    ? rnd.nextLong(0, 3 * maxDelay)   // arbitrary pre-GST
                    : rnd.nextLong(0, maxDelay);      // bounded post-GST
            // Capture by value for the delayed task.
            Message mm = m;
            long d = delay;
            CompletableFuture.delayedRun(() -> {
                if (!inbound.get(dest).isShutdown()) inbound.get(dest).offer(mm);
            }, d, TimeUnit.MILLISECONDS);
        }

        void crash(int id) { inbound.get(id).shutdownNow(); }
        void recover(int id) {
            // Replace the queue so the node can receive again.
            synchronized (inbound) {
                if (inbound.get(id).isShutdown())
                    inbound.set(id, new LinkedBlockingQueue<>());
            }
        }
        void tick(long ms) { now.addAndGet((int) ms); }

        private int destOf(Message m) {
            if (m instanceof RequestVoteReq r)   return r.to;
            if (m instanceof RequestVoteResp r)  return r.to;
            if (m instanceof AppendEntriesReq r) return r.to;
            if (m instanceof AppendEntriesResp r)return r.to;
            return -1;
        }
    }

    /* ---------- Raft node ---------- */

    static class RaftNode implements Runnable {
        final int id;
        final int peers;
        final Network net;

        // Persistent state (would be on disk in real Raft).
        long currentTerm = 0;
        int votedFor = -1;
        final List<LogEntry> log = new ArrayList<>();
        // Volatile state.
        Role role = Role.FOLLOWER;
        int leaderId = -1;
        // Leader-only state.
        final long[] nextIndex, matchIndex;
        // Timers.
        long electionDeadline = 0;     // simulated ms
        long heartbeatDeadline = 0;    // simulated ms (leader only)
        final long electionTimeoutMin = 300;
        final long electionTimeoutMax = 500;
        final long heartbeatInterval  = 100;

        // For demo: client commands to replicate.
        final BlockingQueue<String> clientCommands = new LinkedBlockingQueue<>();
        volatile boolean stop = false;

        RaftNode(int id, int peers, Network net) {
            this.id = id; this.peers = peers; this.net = net;
            this.nextIndex  = new long[peers];
            this.matchIndex = new long[peers];
            resetElectionDeadline();
        }

        public void run() {
            while (!stop) {
                try {
                    Message m = poll(50);   // 50ms simulated tick
                    if (m != null) handle(m);
                    tick();
                } catch (Throwable t) {
                    // Any unexpected failure: step down to follower.
                    log(id, "ERROR " + t + " -> stepping down");
                    becomeFollower(currentTerm, -1);
                }
            }
        }

        /* ----- Event loop helpers ----- */

        private Message poll(long timeoutMs) throws InterruptedException {
            return net.inbound.get(id).poll(timeoutMs, TimeUnit.MILLISECONDS);
        }

        private void tick() {
            long now = net.now.get();
            if (role != Role.LEADER && now >= electionDeadline) {
                startElection();
            }
            if (role == Role.LEADER && now >= heartbeatDeadline) {
                broadcastHeartbeatsOrEntries();
                heartbeatDeadline = now + heartbeatInterval;
            }
        }

        private void resetElectionDeadline() {
            long now = net.now.get();
            electionDeadline = now + electionTimeoutMin
                    + net.rnd.nextLong(electionTimeoutMax - electionTimeoutMin);
        }

        /* ----- RPC handlers ----- */

        private void handle(Message m) {
            if (m instanceof RequestVoteReq r)        onRequestVote(r);
            else if (m instanceof RequestVoteResp r)  onRequestVoteResp(r);
            else if (m instanceof AppendEntriesReq r) onAppendEntries(r);
            else if (m instanceof AppendEntriesResp r)onAppendEntriesResp(r);
        }

        private void onRequestVote(RequestVoteReq r) {
            // Reply false if term is stale.
            if (r.term < currentTerm) {
                net.send(new RequestVoteResp(id, r.from, currentTerm, false));
                return;
            }
            if (r.term > currentTerm) becomeFollower(r.term, -1);

            boolean upToDate = isCandidateLogUpToDate(r.lastLogIdx, r.lastLogTerm);
            boolean grant = upToDate && (votedFor == -1 || votedFor == r.from);
            if (grant) {
                votedFor = r.from;
                resetElectionDeadline();   // grant => reset election timer
            }
            net.send(new RequestVoteResp(id, r.from, currentTerm, grant));
        }

        private void onRequestVoteResp(RequestVoteResp r) {
            if (r.term > currentTerm) becomeFollower(r.term, -1);
            if (role != Role.CANDIDATE || r.term != currentTerm) return;
            if (r.granted) votes.incrementAndGet();
            if (votes.get() > peers / 2) becomeLeader();
        }

        private void onAppendEntries(AppendEntriesReq r) {
            if (r.term < currentTerm) {
                net.send(new AppendEntriesResp(id, r.from, currentTerm, false, -1));
                return;
            }
            // Valid leader contact: reset election timer and step down.
            becomeFollower(r.term, r.from);
            resetElectionDeadline();

            // Consistency check.
            if (r.prevLogIdx > 0) {
                if (r.prevLogIdx >= log.size()
                        || log.get((int) r.prevLogIdx).term != r.prevLogTerm) {
                    net.send(new AppendEntriesResp(id, r.from, currentTerm, false, -1));
                    return;
                }
            }
            // Append any new entries.
            int idx = (int) r.prevLogIdx;
            for (LogEntry e : r.entries) {
                idx++;
                if (idx < log.size() && log.get(idx).term != e.term) {
                    // Conflict: truncate from here.
                    while (log.size() > idx) log.remove(log.size() - 1);
                }
                if (idx >= log.size()) log.add(e);
            }
            // Advance commit index.
            if (r.leaderCommit > commitIndex)
                commitIndex = Math.min(r.leaderCommit, log.size() - 1);

            net.send(new AppendEntriesResp(id, r.from, currentTerm, true, log.size() - 1));
        }

        private void onAppendEntriesResp(AppendEntriesResp r) {
            if (r.term > currentTerm) becomeFollower(r.term, -1);
            if (role != Role.LEADER || r.term != currentTerm) return;
            if (r.success) {
                matchIndex[r.from] = r.matchIndex;
                nextIndex[r.from]  = r.matchIndex + 1;
                advanceCommitIndex();
            } else {
                // Back up nextIndex and retry on next heartbeat.
                nextIndex[r.from] = Math.max(0, nextIndex[r.from] - 1);
            }
        }

        /* ----- State transitions ----- */

        AtomicInteger votes = new AtomicInteger(1); // votes for self

        private void startElection() {
            currentTerm++;
            role = Role.CANDIDATE;
            votedFor = id;
            votes.set(1);
            resetElectionDeadline();
            log(id, "starting election for term " + currentTerm);
            for (int p = 0; p < peers; p++) if (p != id) {
                net.send(new RequestVoteReq(id, p, currentTerm,
                        log.size() - 1, lastLogTerm()));
            }
        }

        private void becomeLeader() {
            role = Role.LEADER;
            leaderId = id;
            Arrays.fill(nextIndex, log.size());
            Arrays.fill(matchIndex, -1);
            heartbeatDeadline = net.now.get();
            log(id, "became LEADER for term " + currentTerm);
            broadcastHeartbeatsOrEntries();
        }

        private void becomeFollower(long term, int leader) {
            if (term > currentTerm) { currentTerm = term; votedFor = -1; }
            role = Role.FOLLOWER;
            leaderId = leader;
        }

        /* ----- Replication ----- */

        long commitIndex = -1;

        private void broadcastHeartbeatsOrEntries() {
            for (int p = 0; p < peers; p++) if (p != id) sendAppend(p);
        }

        private void sendAppend(int peer) {
            long ni = nextIndex[peer];
            long prevIdx = ni - 1;
            long prevTerm = prevIdx >= 0 ? log.get((int) prevIdx).term : 0;
            List<LogEntry> slice = new ArrayList<>(
                    log.subList((int) ni, log.size()));
            net.send(new AppendEntriesReq(id, peer, currentTerm,
                    prevIdx, prevTerm, slice, commitIndex));
        }

        private void advanceCommitIndex() {
            for (long n = log.size() - 1; n > commitIndex; n--) {
                if (log.get((int) n).term != currentTerm) continue;
                int replicated = 1;
                for (int p = 0; p < peers; p++)
                    if (p != id && matchIndex[p] >= n) replicated++;
                if (replicated > peers / 2) { commitIndex = n; break; }
            }
        }

        /* ----- Client API (demo) ----- */

        void submit(String cmd) {
            if (role != Role.LEADER) {
                log(id, "reject submit: not leader (leader=" + leaderId + ")");
                return;
            }
            log.add(new LogEntry(currentTerm, cmd));
            log(id, "appended " + cmd + " at index " + (log.size() - 1));
            broadcastHeartbeatsOrEntries();
        }

        /* ----- Utilities ----- */

        private long lastLogTerm() {
            return log.isEmpty() ? 0 : log.get(log.size() - 1).term;
        }

        private boolean isCandidateLogUpToDate(long idx, long term) {
            long myTerm = lastLogTerm();
            if (term != myTerm) return term > myTerm;
            return idx >= log.size() - 1;
        }

        private static void log(int id, String s) {
            System.out.printf("[t=%4d] node %d: %s%n",
                    System.currentTimeMillis() % 100000, id, s);
        }
    }

    /* ---------- Demo driver ---------- */

    public static void main(String[] args) throws Exception {
        final int N = 5;
        Network net = new Network(N, /*GST*/ 2000, /*maxDelay*/ 80);
        List<RaftNode> nodes = new ArrayList<>();
        ExecutorService pool = Executors.newFixedThreadPool(N);
        for (int i = 0; i < N; i++) {
            RaftNode n = new RaftNode(i, N, net);
            nodes.add(n);
            pool.submit(n);
        }

        // 1) Wait for a leader to emerge.
        RaftNode leader = waitForLeader(nodes, 3000);
        log(">>> leader elected: node " + leader.id);

        // 2) Replicate a few commands.
        leader.submit("SET x=1");
        leader.submit("SET y=2");
        Thread.sleep(400);
        log(">>> commitIndex on leader = " + leader.commitIndex);

        // 3) Crash the leader -> new election.
        log(">>> crashing leader " + leader.id);
        net.crash(leader.id);
        Thread.sleep(800);
        RaftNode leader2 = waitForLeader(nodes, 3000);
        log(">>> new leader: node " + leader2.id);

        // 4) Partition: isolate one follower, then heal.
        log(">>> partitioning node 0");
        net.crash(0);
        Thread.sleep(400);
        leader2.submit("SET z=3");
        Thread.sleep(400);
        log(">>> healing partition");
        net.recover(0);
        Thread.sleep(600);
        log(">>> node 0 commitIndex = " + nodes.get(0).commitIndex
                + ", leader commitIndex = " + leader2.commitIndex);

        // 5) Stop.
        nodes.forEach(n -> n.stop = true);
        pool.shutdownNow();
    }

    private static RaftNode waitForLeader(List<RaftNode> nodes, long timeoutMs)
            throws InterruptedException {
        long deadline = System.currentTimeMillis() + timeoutMs;
        while (System.currentTimeMillis() < deadline) {
            for (RaftNode n : nodes)
                if (n.role == Role.LEADER) return n;
            Thread.sleep(50);
        }
        throw new IllegalStateException("no leader elected within " + timeoutMs + "ms");
    }

    private static void log(String s) {
        System.out.printf("[t=%4d] %s%n",
                System.currentTimeMillis() % 100000, s);
    }
}
```

### How it maps to the partial-synchrony model

| Concern | Where it's handled |
|---|---|
| **Unknown GST** | `Network` flips from arbitrary delays/drops to bounded delay at `stabilizeAt`. The protocol itself never assumes GST has arrived — it just keeps retrying. |
| **Bounded election timeout** | `resetElectionDeadline()` picks a random value in `[300, 500)` ms. Randomization ensures that, after GST, some candidate's timeout fires while every other node's timer is still armed, so a single leader wins. |
| **Heartbeats** | Leader sends `AppendEntries` (possibly empty) every `heartbeatInterval` ms to suppress follower elections. |
| **Term monotonicity** | Any RPC with a higher term forces the receiver to `becomeFollower` — this is the only way leadership legitimacy is transferred. |
| **Log safety** | `RequestVote` grants only if the candidate's log is at-least-as-up-to-date (`isCandidateLogUpToDate`); `AppendEntries` rejects if `prevLogIdx/prevLogTerm` don't match, forcing the leader to back up `nextIndex`. |
| **Failure handling** | Message loss → RPCs are retried on every tick/heartbeat. Node crash → `Network.crash(id)` shuts down the inbound queue; the rest of the cluster elects a new leader because the crashed node stops sending heartbeats. Network partition → minority side's election fails (no majority), majority side continues. Recovery → `recover(id)` reopens the queue; the node catches up via `AppendEntries` consistency checks. |
| **Liveness vs. safety** | Safety (at-most-one leader per term, log matching) holds at all times. Liveness (eventual commits) holds only after GST, which is the standard Raft/Paxos guarantee. |

### Things deliberately left out (for brevity)

- Persistent storage / `fsync` of term, votedFor, and log.
- Snapshotting and log compaction.
- Membership changes (joint consensus).
- Read-index / lease-based reads (only committed reads are safe here).
- Real RPC framework — `Network` is an in-process simulation.

These are orthogonal to the partial-synchrony story; the file is meant as a readable reference for the timeout-driven election and replication loop, not a production library.

# Lease-Based Lock with Fencing Tokens in Go

The core idea: the lock server issues a **monotonically increasing fencing token** with each acquisition. The client must include this token on every downstream write. The downstream resource tracks the highest token it has seen and rejects anything older — even if the client still *thinks* it holds the lock.

## The Code

```go
package main

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"
)

// ─── Sentinel errors (use errors.Is to match) ────────────────────────────────
var (
	ErrLockHeld       = errors.New("lock currently held by another client")
	ErrLockNotHeld    = errors.New("lock not held by this client")
	ErrLeaseExpired   = errors.New("local lease expired")
	ErrStaleFencingTk = errors.New("stale fencing token rejected by resource")
)

// ─── Lock server ─────────────────────────────────────────────────────────────
// In production, replace with etcd / Consul / ZooKeeper — they give you these
// guarantees (leases + revision numbers) out of the box.
type LockServer struct {
	mu           sync.Mutex
	holder       string
	fencingToken int64
	leaseExpiry  time.Time
}

type Lease struct {
	FencingToken int64
	ValidUntil   time.Time
}

func NewLockServer() *LockServer { return &LockServer{} }

func (s *LockServer) Acquire(clientID string, ttl time.Duration) (*Lease, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now()
	if s.holder != "" && now.Before(s.leaseExpiry) {
		return nil, fmt.Errorf("%w: holder=%s until=%s",
			ErrLockHeld, s.holder, s.leaseExpiry.Format(time.RFC3339))
	}
	s.fencingToken++ // monotonic — every successful Acquire gets a fresh token
	s.holder = clientID
	s.leaseExpiry = now.Add(ttl)
	return &Lease{FencingToken: s.fencingToken, ValidUntil: s.leaseExpiry}, nil
}

func (s *LockServer) Renew(clientID string, ttl time.Duration) (*Lease, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.holder != clientID {
		return nil, ErrLockNotHeld
	}
	s.leaseExpiry = time.Now().Add(ttl)
	return &Lease{FencingToken: s.fencingToken, ValidUntil: s.leaseExpiry}, nil
}

func (s *LockServer) Release(clientID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.holder != clientID {
		return ErrLockNotHeld
	}
	s.holder = ""
	return nil
}

// ─── Downstream resource that validates fencing tokens ───────────────────────
type Storage struct {
	mu          sync.Mutex
	highestSeen int64
	data        map[string]string
}

func NewStorage() *Storage { return &Storage{data: make(map[string]string)} }

func (s *Storage) Write(key, value string, token int64) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if token < s.highestSeen {
		// A newer lock holder has already written — this write is unsafe.
		return fmt.Errorf("%w: got=%d highest=%d",
			ErrStaleFencingTk, token, s.highestSeen)
	}
	s.highestSeen = token
	s.data[key] = value
	return nil
}

func (s *Storage) Read(key string) (string, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	v, ok := s.data[key]
	return v, ok
}

// ─── Client: holds the lease, renews in background, writes with token ────────
type Client struct {
	ID      string
	server  *LockServer
	storage *Storage

	mu           sync.Mutex
	fencingToken int64
	leaseExpiry  time.Time
	renewCancel  context.CancelFunc
	renewDone    chan struct{}
}

func NewClient(id string, srv *LockServer, st *Storage) *Client {
	return &Client{ID: id, server: srv, storage: st, renewDone: make(chan struct{})}
}

func (c *Client) Acquire(ctx context.Context, ttl time.Duration) error {
	l, err := c.server.Acquire(c.ID, ttl)
	if err != nil {
		return err
	}
	c.setLease(l)

	renewCtx, cancel := context.WithCancel(ctx)
	c.mu.Lock()
	c.renewCancel = cancel
	c.mu.Unlock()

	go c.renewLoop(renewCtx, ttl)
	return nil
}

// renewLoop keeps the lease alive. If renewal fails (lock lost / network
// partition), it invalidates the local token so subsequent Writes fail fast.
func (c *Client) renewLoop(ctx context.Context, ttl time.Duration) {
	defer close(c.renewDone)
	tick := time.NewTicker(ttl / 3) // renew well before expiry
	defer tick.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-tick.C:
			l, err := c.server.Renew(c.ID, ttl)
			if err != nil {
				c.invalidate() // fencingToken → 0
				return
			}
			c.setLease(l)
		}
	}
}

func (c *Client) setLease(l *Lease) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.fencingToken = l.FencingToken
	c.leaseExpiry = l.ValidUntil
}

func (c *Client) invalidate() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.fencingToken = 0
}

// Write is the only safe path to mutate the resource. Three failure modes:
//   1. token == 0          → we lost the lease locally
//   2. local expiry passed → we know we're stale
//   3. ErrStaleFencingTk   → the resource itself rejected us
func (c *Client) Write(key, value string) error {
	c.mu.Lock()
	token := c.fencingToken
	expiry := c.leaseExpiry
	c.mu.Unlock()

	if token == 0 {
		return ErrLockNotHeld
	}
	if time.Now().After(expiry) {
		return ErrLeaseExpired
	}
	return c.storage.Write(key, value, token)
}

func (c *Client) Release() error {
	c.mu.Lock()
	cancel := c.renewCancel
	c.renewCancel = nil
	c.fencingToken = 0
	c.mu.Unlock()

	if cancel != nil {
		cancel()
		<-c.renewDone // wait for the renew goroutine to exit cleanly
	}
	return c.server.Release(c.ID)
}

// ─── Demo: shows the failure modes in action ─────────────────────────────────
func main() {
	srv := NewLockServer()
	store := NewStorage()
	c1 := NewClient("client-1", srv, store)
	c2 := NewClient("client-2", srv, store)
	ctx := context.Background()

	// 1. c1 acquires the lock.
	if err := c1.Acquire(ctx, 500*time.Millisecond); err != nil {
		panic(err)
	}
	fmt.Println("✓ c1 acquired lock")

	// 2. c2 is blocked while c1 holds it.
	if err := c2.Acquire(ctx, 500*time.Millisecond); errors.Is(err, ErrLockHeld) {
		fmt.Printf("✓ c2 blocked as expected: %v\n", err)
	}

	// 3. c1 writes successfully.
