import (
	"context"
	"errors"
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

// Errors
var (
	ErrLockNotHeld     = errors.New("lock not held")
	ErrLockHeldByOther = errors.New("lock held by another client")
	ErrFencingToken    = errors.New("stale fencing token")
	ErrLeaseExpired    = errors.New("lease expired")
)

// LockServer manages distributed locks with leases and fencing tokens
type LockServer struct {
	mu sync.Mutex

	// Lock state
	holder       string    // client ID of current holder
	fencingToken int64     // monotonic token
	leaseExpiry  time.Time // when current lease expires
}

// LockInfo returned to client on successful acquisition
type LockInfo struct {
	FencingToken int64
	LeaseExpiry  time.Time
}

func NewLockServer() *LockServer {
	return &LockServer{}
}

// Acquire attempts to acquire the lock with a lease
func (s *LockServer) Acquire(clientID string, leaseDuration time.Duration) (*LockInfo, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	now := time.Now()

	// Check if lock is available (expired or unheld)
	if s.holder != "" && now.Before(s.leaseExpiry) {
		return nil, fmt.Errorf("%w: held by %s until %v", ErrLockHeldByOther, s.holder, s.leaseExpiry)
	}

	// Grant lock
	s.holder = clientID
	s.fencingToken++
	s.leaseExpiry = now.Add(leaseDuration)

	return &LockInfo{
		FencingToken: s.fencingToken,
		LeaseExpiry:  s.leaseExpiry,
	}, nil
}

// Renew extends the lease for the current holder
func (s *LockServer) Renew(clientID string, leaseDuration time.Duration) (*LockInfo, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	if s.holder != clientID {
		return nil, ErrLockNotHeld
	}

	s.leaseExpiry = time.Now().Add(leaseDuration)
	return &LockInfo{
		FencingToken: s.fencingToken,
		LeaseExpiry:  s.leaseExpiry,
	}, nil
}

// Release explicitly releases the lock
func (s *LockServer) Release(clientID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	if s.holder != clientID {
		return ErrLockNotHeld
	}

	s.holder = ""
	return nil
}

// Storage represents a downstream resource that validates fencing tokens
type Storage struct {
	mu             sync.Mutex
	highestSeen    int64
	data           map[string]string
}

func NewStorage() *Storage {
	return &Storage{data: make(map[string]string)}
}

