```javascript
// lamport.js — Lamport clock with total-order tie-breaking and failure handling.

class LamportClock {
  /**
   * @param {string} nodeId  Unique identifier for this node (used as tie-breaker).
   */
  constructor(nodeId) {
    if (!nodeId || typeof nodeId !== 'string') {
      throw new TypeError('nodeId must be a non-empty string');
    }
    this.nodeId = nodeId;
    this.time = 0;
  }

  /** Tick the local clock for an internal event. Returns the new timestamp. */
  local() {
    this.time += 1;
    return this.snapshot();
  }

  /**
   * Merge a remote timestamp into the local clock (on receive).
   * Returns the local timestamp to stamp the receive event with.
   */
  receive(remote) {
    this._validate(remote);
    this.time = Math.max(this.time, remote.time) + 1;
    return this.snapshot();
  }

  /** Snapshot of the current (time, nodeId) pair for ordering. */
  snapshot() {
    return { time: this.time, nodeId: this.nodeId };
  }

  // --- failure handling ---------------------------------------------------

  _validate(remote) {
    if (remote == null || typeof remote !== 'object') {
      throw new TypeError('remote timestamp must be an object');
    }
    if (!Number.isInteger(remote.time) || remote.time < 0) {
      throw new RangeError(`invalid remote time: ${remote.time}`);
    }
    if (typeof remote.nodeId !== 'string' || remote.nodeId.length === 0) {
      throw new RangeError('remote timestamp missing nodeId');
    }
    if (remote.time > this.time + 1_000_000) {
      // Guard against absurd jumps (clock-skew / replay / corruption).
      throw new RangeError(
        `remote time ${remote.time} implausibly far ahead of local ${this.time}`
      );
    }
  }
}

/**
 * Total order comparator for two Lamport timestamps.
 * Returns negative if a < b, positive if a > b, 0 if equal.
 */
function compare(a, b) {
  if (a.time !== b.time) return a.time - b.time;
  return a.nodeId < b.nodeId ? -1 : a.nodeId > b.nodeId ? 1 : 0;
}

// --- demo -----------------------------------------------------------------

const a = new LamportClock('node-A');
const b = new LamportClock('node-B');

const events = [
  { ...a.local(), kind: 'A.local' },          // (1, A)
  { ...b.local(), kind: 'B.local' },          // (1, B)
  { ...a.receive(b.snapshot()), kind: 'A.recv-from-B' }, // (2, A)
  { ...b.local(), kind: 'B.local' },          // (2, B)
];

events.sort(compare);
console.log(events.map(e => `${e.time}@${e.nodeId} ${e.kind}`).join('\n'));

// Failure cases — each throws a descriptive error:
// new LamportClock().local();                       // TypeError: nodeId required
// a.receive({ time: -1, nodeId: 'x' });             // RangeError: invalid remote time
// a.receive({ time: 'NaN', nodeId: 'x' });          // TypeError: not an object / not integer
// a.receive({ time: 9_999_999, nodeId: 'x' });      // RangeError: implausibly far ahead
```

**Design notes**

- **Total order** — `compare()` orders by `(time, nodeId)`, so concurrent events at the same logical time are deterministically ordered by node id.
- **Failure handling** — every public entry point validates inputs and throws typed errors (`TypeError` / `RangeError`) for: missing `nodeId`, non-object or non-integer remote times, negative times, and implausibly large jumps (catches skew, replay, or corruption).
- **Causal correctness** — `receive()` enforces `local = max(local, remote) + 1`, the standard Lamport rule that preserves happens-before.

