// ---------- Digest / Hash ----------
inline std::string digest(const std::string& s) {
    // Simple non-cryptographic digest for educational purposes
    std::hash<std::string> h;
    size_t v = h(s);
    std::ostringstream oss;
    oss << std::hex << std::setw(16) << std::setfill('0') << v;
    return oss.str();
}

// ---------- Types ----------
using View = int;
using SequenceNum = int;
using ReplicaId = int;
using ClientId = int;

constexpr int INVALID = -1;

// ---------- Message ----------
enum class MsgType { REQUEST, PRE_PREPARE, PREPARE, COMMIT, REPLY, VIEW_CHANGE, NEW_VIEW };

struct Message {
    MsgType type;
    View view;
    SequenceNum seq;
    ReplicaId sender;
    std::string digest;       // digest of request
    std::string payload;      // request payload
    // For VIEW_CHANGE / NEW_VIEW
    std::set<ReplicaId> sent_set;  // which replicas sent prepare for this seq
    std::vector<std::shared_ptr<Message>> prepared_proofs; // P set
    std::vector<std::shared_ptr<Message>> view_changes;     // V set for NEW_VIEW

    std::string debug() const {
        std::ostringstream oss;
        oss << "Msg{type=" << static_cast<int>(type)
            << ", view=" << view << ", seq=" << seq
            << ", sender=" << sender
            << ", digest=" << digest.substr(0, 8) << "...}";
        return oss.str();
    }
};

// ---------- Request ----------
struct Request {
    ClientId client_id;
    std::string operation;
    std::string digest() const { return pbft::digest(operation); }
};

// ---------- Log entry state ----------
enum class Phase { NULL_PHASE, PRE_PREPARED, PREPARED, COMMITTED };

struct LogEntry {
    Phase phase = Phase::NULL_PHASE;
    std::shared_ptr<Message> pre_prepare;
    std::set<ReplicaId> prepares;   // replicas that sent prepare
    std::set<ReplicaId> commits;    // replicas that sent commit
    std::string payload;
};

// ---------- Network interface ----------
class Network;
extern Network* g_network;

class Network {
public:
    using Handler = std::function<void(const Message&)>;

    void register_handler(ReplicaId id, Handler h) {
        std::lock_guard<std::mutex> lk(mu_);
        handlers_[id] = std::move(h);
    }

    void send(ReplicaId to, const Message& m) {
        if (drop_probability_(to, m)) return;  // simulate drop
        std::lock_guard<std::mutex> lk(mu_);
        if (handlers_.count(to)) {
            // async delivery
            std::thread([h = handlers_[to], m]() {
                std::this_thread::sleep_for(std::chrono::milliseconds(1));
                h(m);
            }).detach();
        }
    }

    void broadcast(const std::vector<ReplicaId>& ids, const Message& m) {
        for (auto id : ids) send(id, m);
    }

    void set_drop_rule(std::function<bool(ReplicaId, const Message&)> rule) {
        drop_probability_ = std::move(rule);
    }

    static Network& instance() {
        static Network n;
        return n;
    }

private:
    std::mutex mu_;
    std::map<ReplicaId, Handler> handlers_;
    std::function<bool(ReplicaId, const Message&)> drop_probability_ = 
        [](ReplicaId, const Message&) { return false; };
};

// ---------- Replica ----------
class Replica {
public:
    Replica(ReplicaId id, int f, const std::vector<ReplicaId>& all_ids)
        : id_(id), f_(f), n_(static_cast<int>(all_ids.size())),
          all_ids_(all_ids), view_(0), seq_(0) {
        assert(n_ == 3 * f_ + 1);
        log_.clear();
    }

    ReplicaId id() const { return id_; }
    bool is_primary() const { return id_ == view_ % n_; }
    int quorum() const { return 2 * f_ + 1; }

    void start() {
        running_ = true;
        // Start timer threads
        timer_thread_ = std::thread([this]() { timer_loop(); });
    }

    void stop() {
        running_ = false;
        cv_.notify_all();
        if (timer_thread_.joinable()) timer_thread_.join();
    }

    // Client submits a request
    void submit_request(const Request& req) {
        if (!is_primary()) {
            std::cout << "[Replica " << id_ << "] Not primary, ignoring client request\n";
            return;
        }
        handle_request(req);
    }

    // Network delivers a message
    void receive(const Message& m) {
        std::lock_guard<std::mutex> lk(mu_);
        switch (m.type) {
            case MsgType::REQUEST: handle_request(Request{0, m.payload}); break;
            case MsgType::PRE_PREPARE: handle_pre_prepare(m); break;
            case MsgType::PREPARE: handle_prepare(m); break;
            case MsgType::COMMIT: handle_commit(m); break;
            case MsgType::VIEW_CHANGE: handle_view_change(m); break;
            case MsgType::NEW_VIEW: handle_new_view(m); break;
            default: break;
        }
    }

private:
    ReplicaId id_;
    int f_;
    int n_;
    std::vector<ReplicaId> all_ids_;
    View view_;
    SequenceNum seq_;

    std::mutex mu_;
    std::map<SequenceNum, LogEntry> log_;
    std::atomic<bool> running_{false};
    std::condition_variable cv_;
    std::thread timer_thread_;

    // ---------- Phase handlers ----------
    void handle_request(const Request& req) {
        SequenceNum n = ++seq_;
        Message pp;
        pp.type = MsgType::PRE_PREPARE;
        pp.view = view_;
        pp.seq = n;
        pp.sender = id_;
        pp.digest = req.digest();
        pp.payload = req.operation;

        log_[n] = LogEntry{Phase::PRE_PREPARED, std::make_shared<Message>(pp), {}, {}, req.operation};

        std::cout << "[Replica " << id_ << "] (primary) PRE-PREPARE seq=" << n 
                  << " digest=" << pp.digest.substr(0,8) << "\n";

        for (auto rid : all_ids_) {
            if (rid != id_) Network::instance().send(rid, pp);
        }
    }

    void handle_pre_prepare(const Message& m) {
        if (m.view != view_) return;
        if (m.sender != view_ % n_) return;  // not from primary
        if (log_.count(m.seq)) return;       // already have it

        log_[m.seq] = LogEntry{Phase::PRE_PREPARED, std::make_shared<Message>(m), {}, {}, m.payload};

        std::cout << "[Replica " << id_ << "] PRE-PREPARED seq=" << m.seq << "\n";

        // Send PREPARE
        Message p;
        p.type = MsgType::PREPARE;
        p.view = m.view;
        p.seq = m.seq;
        p.sender = id_;
        p.digest = m.digest;

        for (auto rid : all_ids_) {
            if (rid != id_) Network::instance().send(rid, p);
        }
    }

    void handle_prepare(const Message& m) {
        if (m.view != view_) return;
        auto it = log_.find(m.seq);
        if (it == log_.end()) return;
        auto& entry = it->second;
        if (entry.phase == Phase::NULL_PHASE) return;
        if (m.digest != entry.pre_prepare->digest) return;  // mismatch

        entry.prepares.insert(m.sender);

        if (entry.phase == Phase::PRE_PREPARED && 
            static_cast<int>(entry.prepares.size()) >= quorum() - 1) {
            // We have 2f prepares (including our implicit one)
            entry.phase = Phase::PREPARED;
            std::cout << "[Replica " << id_ << "] PREPARED seq=" << m.seq 
                      << " (" << entry.prepares.size() << " prepares)\n";

            // Send COMMIT
            Message c;
            c.type = MsgType::COMMIT;
            c.view = m.view;
            c.seq = m.seq;
            c.sender = id_;
            c.digest = m.digest;

            for (auto rid : all_ids_) {
                if (rid != id_) Network::instance().send(rid, c);
            }
        }
    }

    void handle_commit(const Message& m) {
        if (m.view != view_) return;
        auto it = log_.find(m.seq);
        if (it == log_.end()) return;
        auto& entry = it->second;
        if (entry.phase < Phase::PREPARED) return;  // not prepared yet
        if (m.digest != entry.pre_prepare->digest) return;

        entry.commits.insert(m.sender);

        if (entry.phase == Phase::PREPARED && 
            static_cast<int>(entry.commits.size()) >= quorum() - 1) {
            entry.phase = Phase::COMMITTED;
            std::cout << "[Replica " << id_ << "] COMMITTED seq=" << m.seq 
                      << " (" << entry.commits.size() << " commits)\n";

            // Execute and reply
            execute(m.seq, entry.payload);
        }
    }

    void execute(SequenceNum seq, const std::string& payload) {
        std::cout << "[Replica " << id_ << "] EXECUTE seq=" << seq 
                  << " op=\"" << payload << "\"\n";
        // In real system: send REPLY to client
    }

    // ---------- View change ----------
    void handle_view_change(const Message& m) {
        // Simplified: collect view changes, when 2f+1 received, trigger new view
        // (omitted for brevity in this educational version)
    }

    void handle_new_view(const Message& m) {
        // (omitted for brevity)
    }

    void timer_loop() {
        while (running_) {
            std::unique_lock<std::mutex> lk(mu_);
            cv_.wait_for(lk, std::chrono::seconds(2), [this]() { return !running_; });
            // Check for timeouts, trigger view change if needed
        }
    }
};

Network* g_network = nullptr;

