## `tob.go`

```go
// Package tob implements total-order broadcast on top of hashicorp/raft.
//
// Raft's replicated log already provides total order: every committed entry
// appears at the same index on every replica, and entries are applied in log
// order. TOB is therefore a thin layer that turns "propose a log entry" into
// "broadcast" and "FSM.Apply" into "deliver".
//
// Idempotency: every Message carries a unique ID. The FSM dedups by ID, so
// clients may safely retry Broadcast after a timeout or leadership loss.
package tob

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log"
	"net"
	"os"
	"sync"
	"sync/atomic"
	"time"

	"github.com/hashicorp/raft"
)

// ---------- Public types ----------

// Message is the unit of broadcast. ID must be globally unique so retries
// are idempotent.
type Message struct {
	ID      string `json:"id"`
	Sender  string `json:"sender"`
	Payload []byte `json:"payload"`
}

// Delivery is what consumers receive. LogIndex is the Raft log position;
// deliveries on every node share the same LogIndex sequence (total order).
type Delivery struct {
	Message  Message
	LogIndex uint64
	LogTerm  uint64
}

// Errors returned by Broadcast.
var (
	ErrShuttingDown   = errors.New("tob: shutting down")
	ErrNotLeader      = errors.New("tob: not leader")
	ErrLeadershipLost = errors.New("tob: leadership lost")
	ErrApplyTimeout   = errors.New("tob: apply timed out")
)

// Peer describes a Raft peer for bootstrap.
type Peer struct {
	ID      string
	Address string
}

// Config configures a TOB node.
type Config struct {
	NodeID        string
	BindAddr      string
	Bootstrap     bool
	Peers         []Peer
	DeliverBuffer int           // delivery channel buffer (default 256)
	ApplyTimeout  time.Duration // per-broadcast apply timeout (default 5s)
}

// TOB is the total-order broadcast handle. Safe for concurrent use.
type TOB struct {
	cfg       Config
	raft      *raft.Raft
	fsm       *fsm
	deliverCh chan Delivery
	seen      *dedup
	done      chan struct{}
	closed    atomic.Bool
	wg        sync.WaitGroup
}

// New starts a TOB node. It returns once the Raft node is created;
// leadership (if any) is established asynchronously.
func New(cfg Config) (*TOB, error) {
	if cfg.DeliverBuffer <= 0 {
		cfg.DeliverBuffer = 256
	}
	if cfg.ApplyTimeout <= 0 {
		cfg.ApplyTimeout = 5 * time.Second
	}
	t := &TOB{
		cfg:       cfg,
		deliverCh: make(chan Delivery, cfg.DeliverBuffer),
		seen:      newDedup(),
		done:      make(chan struct{}),
	}
	t.fsm = &fsm{tob: t}

	// ----- Raft setup (in-memory for the demo; use BoltDB in production) -----
	rc := raft.DefaultConfig()
	rc.LocalID = raft.ServerID(cfg.NodeID)
	rc.Logger = log.New(os.Stderr, fmt.Sprintf("[raft %s] ", cfg.NodeID),
		log.LstdFlags|log.Lmsgprefix)

	logStore := raft.NewInmemStore()
	stableStore := raft.NewInmemStore()
	snapshotStore := raft.NewInmemSnapshotStore()

	addr, err := net.ResolveTCPAddr("tcp", cfg.BindAddr)
	if err != nil {
		return nil, err
	}
	transport, err := raft.NewTCPTransport(cfg.BindAddr, addr, 3, 10*time.Second)
	if err != nil {
		return nil, err
	}

	r, err := raft.NewRaft(rc, t.fsm, logStore, stableStore, snapshotStore, transport)
	if err != nil {
		return nil, err
	}
	t.raft = r

	if cfg.Bootstrap {
		servers := make([]raft.Server, 0, len(cfg.Peers))
		for _, p := range cfg.Peers {
			servers = append(servers, raft.Server{
				ID:      raft.ServerID(p.ID),
				Address: raft.ServerAddress(p.Address),
			})
		}
		bf := r.BootstrapCluster(raft.Configuration{Servers: servers})
		if err := bf.Error(); err != nil && !errors.Is(err, raft.ErrCantBootstrap) {
			return nil, fmt.Errorf("bootstrap: %w", err)
		}
	}
	return t, nil
}

// Broadcast proposes a message for total-order delivery. It blocks until the
// entry is committed and applied locally (i.e. it has been or is about to be
// delivered on this node, and is guaranteed to be delivered on every other
// node in the same order).
//
// Safe to retry with the same Message.ID: the FSM dedups by ID.
func (t *TOB) Broadcast(m Message) error {
	if t.closed.Load() {
		return ErrShuttingDown
	}
	if m.ID == "" {
		return errors.New("tob: Message.ID required")
	}
	if t.seen.seen(m.ID) {
		return nil // already delivered locally; idempotent retry
	}

	data, err := json.Marshal(m)
	if err != nil {
		return err
	}

	f := t.raft.Apply(data, t.cfg.ApplyTimeout)
	if err := f.Error(); err != nil {
		switch {
		case errors.Is(err, raft.ErrNotLeader):
			return ErrNotLeader
		case errors.Is(err, raft.ErrLeadershipLost):
			return ErrLeadershipLost
		case errors.Is(err, raft.ErrRaftShutdown):
			return ErrShuttingDown
		case errors.Is(err, raft.ErrEnqueueTimeout):
			return ErrApplyTimeout
		default:
			return err
		}
	}
	return nil
}

// Deliveries returns the channel of committed, ordered deliveries. The same
// sequence is observed on every node (total order). Closed on Shutdown.
func (t *TOB) Deliveries() <-chan Delivery { return t.deliverCh }

// LeaderHint returns the address of the current leader, or "" if unknown.
// Clients should redirect to this address after an ErrNotLeader error.
func (t *TOB) LeaderHint() string {
	addr, _ := t.raft.LeaderWithID()
	return string(addr)
}

// IsLeader reports whether this node currently believes it is the leader.
func (t *TOB) IsLeader() bool { return t.raft.State() == raft.Leader }

// Shutdown stops the node gracefully.
func (t *TOB) Shutdown() {
	if !t.closed.CompareAndSwap(false, true) {
		return
	}
	close(t.done)
	if f := t.raft.Shutdown(); f.Error() != nil {
		log.Printf("tob[%s]: raft shutdown: %v", t.cfg.NodeID, f.Error())
	}
	t.wg.Wait()
	close(t.deliverCh)
}

// ---------- FSM ----------

type fsm struct{ tob *TOB }

// Apply is called by Raft in log order for every committed entry. We dedup
// by Message.ID, then push the delivery onto the user channel.
//
// Backpressure: if the consumer is slow, we block here with a timeout. This
// stalls Raft's apply loop but does not affect safety — the entry is already
// committed and will be re-applied on snapshot restore if we time out. In
// production, swap this for a persistent delivery queue.
func (f *fsm) Apply(l *raft.Log) interface{} {
	if l.Type != raft.LogCommand {
		return nil
	}
	var msg Message
	if err := json.Unmarshal(l.Data, &msg); err != nil {
		log.Printf("tob[%s]: corrupt log entry at index %d: %v",
			f.tob.cfg.NodeID, l.Index, err)
		return nil
	}
	if f.tob.seen.add(msg.ID, l.Index) {
		return nil // duplicate, already delivered
	}

	d := Delivery{Message: msg, LogIndex: l.Index, LogTerm: l.Term}

	timer := time.NewTimer(30 * time.Second)
	defer timer.Stop()
	select {
	case f.tob.deliverCh <- d:
	case <-timer.C:
		log.Printf("tob[%s]: delivery timeout at index %d (consumer too slow)",
			f.tob.cfg.NodeID, l.Index)
	case <-f.tob.done:
	}
	return nil
}

// Snapshot/Restore: a production implementation must persist the dedup set
// (and last applied index) so a restored node doesn't re-deliver messages.
func (f *fsm) Snapshot() (raft.FSMSnapshot, error) { return &noopSnapshot{}, nil }
func (f *fsm) Restore(_ io.ReadCloser) error        { return nil }

type noopSnapshot struct{}

func (noopSnapshot) Persist(_ raft.SnapshotSink) error { return nil }
func (noopSnapshot) Release()                          {}

// ---------- Dedup ----------

type dedup struct {
	mu sync.RWMutex
	m  map[string]uint64
}

func newDedup() *dedup { return &dedup{m: map[string]uint64{}} }

func (d *dedup) seen(id string) bool {
	d.mu.RLock()
	_, ok := d.m[id]
	d.mu.RUnlock()
	return ok
}

// add records id. Returns true if it was already present.
func (d *dedup) add(id string, idx uint64) bool {
	d.mu.Lock()
	defer d.mu.Unlock()
	if _, ok := d.m[id]; ok {
		return true
	}
	d.m[id] = idx
	return false
}
