## `main.go` — demo with 3 nodes

```go
package main

import (
	"fmt"
	"log"
	"sync"
	"time"

	"example.com/tob"
)

func main() {
	peers := []tob.Peer{
		{ID: "n1", Address: "127.0.0.1:7001"},
		{ID: "n2", Address: "127.0.0.1:7002"},
		{ID: "n3", Address: "127.0.0.1:7003"},
	}

	nodes := make(map[string]*tob.TOB)
	for _, p := range peers {
		t, err := tob.New(tob.Config{
			NodeID:    p.ID,
			BindAddr:  p.Address,
			Bootstrap: p.ID == "n1",
			Peers:     peers,
		})
		if err != nil {
			log.Fatalf("start %s: %v", p.ID, err)
		}
		nodes[p.ID] = t
	}
	defer func() {
		for _, t := range nodes {
			t.Shutdown()
		}
	}()

	// Wait for a leader to be elected.
	var leader *tob.TOB
	for leader == nil {
		for _, t := range nodes {
			if t.IsLeader() {
				leader = t
				break
			}
		}
		time.Sleep(100 * time.Millisecond)
	}
	fmt.Println("leader elected:", leader.LeaderHint())

	// One delivery consumer per node.
	var wg sync.WaitGroup
	for id, t := range nodes {
		wg.Add(1)
		go func(id string, t *tob.TOB) {
			defer wg.Done()
			for d := range t.Deliveries() {
				fmt.Printf("[%s] idx=%-3d term=%d id=%-6s payload=%s\n",
					id, d.LogIndex, d.LogTerm, d.Message.ID, string(d.Message.Payload))
			}
		}(id, t)
	}

	// Broadcast 5 messages through the leader.
	for i := 1; i <= 5; i++ {
		msg := tob.Message{
			ID:      fmt.Sprintf("msg-%d", i),
			Sender:  "client",
			Payload: []byte(fmt.Sprintf("hello-%d", i)),
		}
		if err := leader.Broadcast(msg); err != nil {
			log.Printf("broadcast %d: %v", i, err)
		}
		time.Sleep(200 * time.Millisecond)
	}

	// Demonstrate idempotent retry: re-broadcast msg-3 with the same ID.
	fmt.Println("--- retrying msg-3 (should be deduped) ---")
	_ = leader.Broadcast(tob.Message{
		ID: "msg-3", Sender: "client", Payload: []byte("hello-3-retry"),
	})

	time.Sleep(2 * time.Second)
	fmt.Println("done")
	wg.Wait()
}
