// Package tob implements total-order broadcast on top of hashicorp/raft.
//
// Total-order broadcast (also called atomic broadcast) guarantees that
// messages broadcast by any node are delivered to all nodes in the same
// order. Raft already provides this property for its replicated log: every
// committed entry appears at the same position in every replica's log, and
// entries are applied in log order. TOB is therefore just a thin layer that:
//
//  1. Lets clients "broadcast" by proposing a message as a Raft log entry.
//  2. Lets clients "deliver" by reading from a channel that the FSM pushes
//     to as it applies committed entries.
//
// Failure handling is delegated to Raft where possible, and augmented with
// idempotency (message IDs) so that retries are safe.
package tob

import (
    "encoding/json"
    "errors"
    "fmt"
    "io"
    "log"
    "net"
    "os"
    "sync"
    "sync/atomic"
    "time"

    "github.com/hashicorp/raft"
)

// ---------- Public API ----------

// Message is the unit of broadcast. ID must be unique across all broadcasts
// so that retries are idempotent.
type Message struct {
    ID      string `json:"id"`
    Sender  string `json:"sender"`
    Payload []byte `json:"payload"`
}

// Delivery is what consumers receive. LogIndex is the Raft log position of
// the message; deliveries on every node share the same LogIndex sequence.
type Delivery struct {
    Message  Message
    LogIndex uint64
    LogTerm  uint64
}

// Errors returned by Broadcast.
var (
    ErrShuttingDown   = errors.New("tob: shutting down")
    ErrNotLeader      = errors.New("tob: not leader")
    ErrLeadershipLost = errors.New("tob: leadership lost")
    ErrApplyTimeout   = errors.New("tob: apply timed out")
)

// Peer describes a Raft peer for bootstrap.
type Peer struct {
    ID      string
    Address string
}

// Config configures a TOB node.
type Config struct {
    NodeID    string
    BindAddr  string
    DataDir   string        // empty => in-memory
    Bootstrap bool
    Peers     []Peer
    DeliverBuffer int      // delivery channel buffer (default 256)
    ApplyTimeout time.Duration // per-broadcast apply timeout (default 5s)
}

// TOB is the total-order broadcast handle. Safe for concurrent use.
type TOB struct {
    cfg       Config
    raft      *raft.Raft
    fsm       *fsm
    deliverCh chan Delivery
    seen      *dedup
    done      chan struct{}
    closed    atomic.Bool
    wg        sync.WaitGroup
}

// New starts a TOB node. It returns once the Raft node is created; leadership
// (if any) is established asynchronously.
func New(cfg Config) (*TOB, error) {
    if cfg.DeliverBuffer <= 0 {
        cfg.DeliverBuffer = 256
    }
    if cfg.ApplyTimeout <= 0 {
        cfg.ApplyTimeout = 5 * time.Second
    }
    t := &TOB{
        cfg:       cfg,
        deliverCh: make(chan Delivery, cfg.DeliverBuffer),
        seen:      newDedup(),
        done:      make(chan struct{}),
    }
    t.fsm = &fsm{tob: t}

    // ----- Raft setup -----
    rc := raft.DefaultConfig()
    rc.LocalID = raft.ServerID(cfg.NodeID)
    rc.Logger = log.New(os.Stderr, fmt.Sprintf("[raft %s] ", cfg.NodeID),
        log.LstdFlags|log.Lmsgprefix)

    var logStore raft.LogStore
    var stableStore raft.StableStore
    var snapshotStore raft.SnapshotStore
    if cfg.DataDir == "" {
        logStore = raft.NewInmemStore()
        stableStore = raft.NewInmemStore()
        snapshotStore = raft.NewInmemSnapshotStore()
    } else {
        // (file-backed stores omitted for brevity; use raft.NewLogCache +
        //  bolt-backed stores in production)
        return nil, errors.New("file-backed stores not implemented in this demo")
    }

    addr, err := net.ResolveTCPAddr("tcp", cfg.BindAddr)
    if err != nil {
        return nil, err
    }
    transport, err := raft.NewTCPTransportWithLogger(
        cfg.BindAddr, addr, 3, 10*time.Second,
        log.New(os.Stderr, fmt.Sprintf("[raft-trans %s] ", cfg.NodeID),
            log.LstdFlags|log.Lmsgprefix))
    if err != nil {
        return nil, err
    }

    r, err := raft.NewRaft(rc, t.fsm, logStore, stableStore, snapshotStore, transport)
    if err != nil {
        return nil, err
    }
    t.raft = r

    if cfg.Bootstrap {
        servers := make([]raft.Server, 0, len(cfg.Peers))
        for _, p := range cfg.Peers {
            servers = append(servers, raft.Server{
                ID:      raft.ServerID(p.ID),
                Address: raft.ServerAddress(p.Address),
            })
        }
        if f := r.BootstrapCluster(raft.Configuration{Servers: servers}); f.Error() != nil {
            // Ignore "already bootstrapped" errors.
            if !errors.Is(f.Error(), raft.ErrCantBootstrap) {
                return nil, fmt.Errorf("bootstrap: %w", f.Error())
            }
        }
    }
    return t, nil
}

// Broadcast proposes a message for total-order delivery. It returns once the
// message has been committed and applied on the local FSM (i.e. it has been
// or will shortly be delivered locally, and is guaranteed to be delivered on
// every other node in the same order).
//
// Failure handling:
//   - If this node is not the leader, returns ErrNotLeader. The caller should
//     retry against the leader reported by LeaderHint().
//   - If leadership is lost mid-apply (e.g. the leader is partitioned), returns
//     ErrLeadershipLost. The caller should retry; Raft guarantees the entry
//     was either committed (and will be applied) or not, never half-applied.
//   - If the apply times out, returns ErrApplyTimeout. The caller may retry;
//     if the entry was actually committed, the FSM's dedup check will discard
//     the duplicate.
//   - If the message ID has already been delivered, Broadcast returns nil
//     immediately (idempotent retry).
func (t *TOB) Broadcast(m Message) error {
    if t.closed.Load() {
        return ErrShuttingDown
    }
    if m.ID == "" {
        return errors.New("tob: message.ID required")
    }
    if t.seen.seen(m.ID) {
        return nil // already delivered locally; idempotent
    }

    data, err := json.Marshal(m)
    if err != nil {
        return err
    }

    f := t.raft.Apply(data, t.cfg.ApplyTimeout)
    if err := f.Error(); err != nil {
        switch {
        case errors.Is(err, raft.ErrNotLeader):
            return ErrNotLeader
        case errors.Is(err, raft.ErrLeadershipLost):
            return ErrLeadershipLost
        case errors.Is(err, raft.ErrRaftShutdown):
            return ErrShuttingDown
        case errors.Is(err, raft.ErrEnqueueTimeout):
            return ErrApplyTimeout
        default:
            return err
        }
    }
    return nil
}

// Deliveries returns the channel of committed, ordered deliveries. The same
// sequence is observed on every node (total order). The channel is closed on
// shutdown.
func (t *TOB) Deliveries() <-chan Delivery { return t.deliverCh }

// LeaderHint returns the address of the current leader, or "" if unknown.
// Clients can use this to redirect broadcasts after an ErrNotLeader error.
func (t *TOB) LeaderHint() string {
    addr, _ := t.raft.LeaderWithID()
    return string(addr)
}

// IsLeader reports whether this node currently believes it is the leader.
func (t *TOB) IsLeader() bool { return t.raft.State() == raft.Leader }

// Shutdown stops the node gracefully.
func (t *TOB) Shutdown() {
    if !t.closed.CompareAndSwap(false, true) {
        return
    }
    close(t.done)
    if f := t.raft.Shutdown(); f.Error() != nil {
        log.Printf("tob[%s]: raft shutdown: %v", t.cfg.NodeID, f.Error())
    }
    t.wg.Wait()
    close(t.deliverCh)
}

// ---------- FSM ----------

type fsm struct{ tob *TOB }

func (f *fsm) Apply(l *raft.Log) interface{} {
    if l.Type != raft.LogCommand {
        return nil
    }
    var msg Message
    if err := json.Unmarshal(l.Data, &msg); err != nil {
        log.Printf("tob[%s]: corrupt log entry at index %d: %v",
            f.tob.cfg.NodeID, l.Index, err)
