import java.util.HashMap;
import java.util.Map;

/**
 * Computes a discrete logarithm x such that g^x ≡ h (mod p)
 * using the Baby-step Giant-step algorithm.
 *
 * Time complexity: O(√n) where n is the group order.
 *
 * NOTE: For educational/internal use only. Real-world discrete logs
 * use groups far larger than 16 bits (e.g., 256-bit curves).
 */
public class BabyStepGiantStep {

    /**
     * Returns x such that g^x ≡ h (mod p), or throws if none exists.
     */
    public static long discreteLog(long g, long h, long p) {
        long n = p - 1;                       // order of Z_p*
        long m = (long) Math.ceil(Math.sqrt(n));

        // ---- Baby step: build table of g^j mod p for j in [0, m) ----
        Map<Long, Long> table = new HashMap<>();
        long power = 1;
        for (long j = 0; j < m; j++) {
            table.put(power, j);
            power = (power * g) % p;
        }

        // ---- Giant step: factor = g^(-m) mod p ----
        // Using Fermat: g^(p-1) ≡ 1 (mod p), so g^(-m) ≡ g^(p-1-m).
        long gInvM = modPow(modPow(g, m, p), p - 2, p);

        // ---- Match: walk h * (g^(-m))^i and look up in table ----
        long gamma = h % p;
        for (long i = 0; i < m; i++) {
            Long j = table.get(gamma);
            if (j != null) {
                long x = (i * m + j) % n;
                // Sanity check before returning
                if (modPow(g, x, p) == h) {
                    return x;
                }
            }
            gamma = (gamma * gInvM) % p;
        }

        throw new IllegalArgumentException("No discrete log found.");
    }

    /** Fast modular exponentiation: base^exp mod mod. */
    private static long modPow(long base, long exp, long mod) {
        long result = 1;
        base = ((base % mod) + mod) % mod;
        while (exp > 0) {
            if ((exp & 1L) == 1L) {
                result = (result * base) % mod;
            }
            exp >>= 1;
            base = (base * base) % mod;
        }
        return result;
    }

    // -------------------- Demo --------------------
    public static void main(String[] args) {
        // Tiny 16-bit prime group: Z_p* with p = 65521 (largest prime < 2^16)
        long p = 65521L;
        long g = 3L;

        // Pick a "secret" exponent and compute the public value
        long secretX = 12345L;
        long h = modPow(g, secretX, p);

        System.out.println("Group      : Z_" + p + "*  (16-bit)");
        System.out.println("Generator g: " + g);
        System.out.println("Public h   : " + h);
        System.out.println("Secret x   : " + secretX);
        System.out.println();

        long recovered = discreteLog(g, h, p);
        System.out.println("Recovered x: " + recovered);
        System.out.println("Match      : " + (recovered == secretX));
