// wait_free_consensus.cpp
// Build: g++ -std=c++17 -O2 -pthread wait_free_consensus.cpp -o consensus

#include <atomic>
#include <cstdint>
#include <iostream>
#include <vector>
#include <thread>
#include <cassert>
#include <set>

namespace wait_free {

enum class Status : int {
    WON     =  0,  // Our value was chosen
    ADOPTED =  1,  // We adopted another thread's value
    ERR_ID  = -1,  // Invalid thread_id
    ERR_VAL = -2   // Invalid value (doesn't fit in 32 bits)
};

class BinaryConsensus {
public:
    // Sentinel meaning "no proposal yet". Reserved — never use as a thread_id.
    static constexpr uint64_t EMPTY = 0xFFFFFFFFULL;

private:
    // Pack (thread_id, value) into one 64-bit word so the whole consensus
    // state updates with a single CAS on any 64-bit platform.
    //   bits 63..32 : thread_id  (EMPTY = undecided)
    //   bits 31..0  : value
    std::atomic<uint64_t> state_{pack(0, EMPTY)};

    static constexpr uint64_t VALUE_MASK   = 0xFFFFFFFFULL;
    static constexpr uint64_t THREAD_SHIFT = 32;

    static uint64_t pack(uint64_t v, uint64_t tid) noexcept {
        return (tid << THREAD_SHIFT) | (v & VALUE_MASK);
    }
    static uint64_t value_of(uint64_t s) noexcept { return s & VALUE_MASK; }
    static uint64_t tid_of  (uint64_t s) noexcept { return s >> THREAD_SHIFT; }

public:
    BinaryConsensus() noexcept = default;
    BinaryConsensus(const BinaryConsensus&) = delete;
    BinaryConsensus& operator=(const BinaryConsensus&) = delete;

    // Propose a value. Wait-free: completes in at most one CAS.
    //
    //   my_value     : proposed value, must fit in 32 bits
    //   my_thread_id : unique id, must be != EMPTY and fit in 32 bits
    //   decided      : output — the value chosen by consensus
    Status propose(uint64_t my_value,
                   uint64_t my_thread_id,
                   uint64_t& decided) noexcept {

        // ---- Input validation (failure handling) ----
        if (my_thread_id == EMPTY || my_thread_id > VALUE_MASK) {
            decided = 0;
            return Status::ERR_ID;
        }
        if (my_value > VALUE_MASK) {
            decided = 0;
            return Status::ERR_VAL;
        }

        // ---- The single CAS that does all the work ----
        uint64_t expected = pack(0, EMPTY);          // we expect "undecided"
        const uint64_t desired = pack(my_value, my_thread_id);

        if (state_.compare_exchange_strong(
                expected, desired,
                std::memory_order_acq_rel,
                std::memory_order_acquire)) {
            // CAS succeeded → our value is the consensus decision
            decided = my_value;
            return Status::WON;
        }

        // CAS failed → another thread won the race.
        // compare_exchange_strong updated `expected` to the current state,
        // so we can read the winner's value directly from it. No extra load.
        decided = value_of(expected);
        return Status::ADOPTED;
    }

    // Inspection helpers (for testing)
    bool     has_decided()  const noexcept { return tid_of(state_.load(std::memory_order_acquire))   != EMPTY; }
    uint64_t current_value() const noexcept { return value_of(state_.load(std::memory_order_acquire)); }
};

} // namespace wait_free


// ============================================================================
// Tests
// ============================================================================
int main() {
    using namespace wait_free;

    std::cout << "=== Wait-Free Consensus Demo ===\n\n";

    // ---- Test 1: single thread ----
    {
        std::cout << "[Test 1] Single thread\n";
        BinaryConsensus c;
        uint64_t v;
        auto s = c.propose(42, 0, v);
        std::cout << "  propose(42) -> status=" << (int)s
                  << " decided=" << v << "\n";
        assert(s == Status::WON && v == 42);
        std::cout << "  PASS\n\n";
    }

    // ---- Test 2: 8 threads must all agree ----
    {
        std::cout << "[Test 2] 8 threads must agree on the same value\n";
        constexpr int N = 8;
        BinaryConsensus c;
        std::vector<uint64_t> results(N);
        std::vector<Status>   statuses(N);
        std::vector<std::thread> ts;

        for (int i = 0; i < N; ++i) {
            ts.emplace_back([&c, &results, &statuses, i] {
                statuses[i] = c.propose(100 + i, i, results[i]);
            });
        }
        for (auto& t : ts) t.join();

        std::set<uint64_t> unique(results.begin(), results.end());
        for (int i = 0; i < N; ++i) {
            std::cout << "  Thread " << i << " proposed " << (100 + i)
                      << " -> status=" << (int)statuses[i]
                      << " decided=" << results[i] << "\n";
        }
        assert(unique.size() == 1);  // agreement
        std::cout << "  PASS\n\n";
    }

    // ---- Test 3: invalid input is rejected ----
    {
        std::cout << "[Test 3] Invalid input is rejected\n";
        BinaryConsensus c;
        uint64_t v;

        auto s1 = c.propose(10, BinaryConsensus::EMPTY, v);
        std::cout << "  propose(10, EMPTY) -> " << (int)s1 << "\n";
        assert(s1 == Status::ERR_ID);

        auto s2 = c.propose(0x100000000ULL, 0, v);  // value > 32 bits
        std::cout << "  propose(2^32, 0) -> " << (int)s2 << "\n";
        assert(s2 == Status::ERR_VAL);

        std::cout << "  PASS\n\n";
    }

    // ---- Test 4: one-shot semantics ----
    {
        std::cout << "[Test 4] Consensus is one-shot (later calls adopt)\n";
        BinaryConsensus c;
        uint64_t v;
        c.propose(100, 0, v);              // first wins
        auto s = c.propose(200, 1, v);     // second adopts
        std::cout << "  propose(200) -> status=" << (int)s
                  << " decided=" << v << "\n";
        assert(s == Status::ADOPTED && v == 100);
        std::cout << "  PASS\n\n";
    }

    std::cout << "All tests passed.\n";
    return 0;
}
