    static constexpr uint64_t THREAD_ID_SHIFT = 32;

    static uint64_t pack(uint64_t value, uint64_t thread_id) noexcept {
        return (thread_id << THREAD_ID_SHIFT) | (value & VALUE_MASK);
    }

    static uint64_t unpack_value(uint64_t packed) noexcept {
        return packed & VALUE_MASK;
    }

    static uint64_t unpack_thread_id(uint64_t packed) noexcept {
        return packed >> THREAD_ID_SHIFT;
    }

public:
    BinaryConsensus() noexcept : state_(pack(0, EMPTY)) {}

    // Non-copyable, non-movable
    BinaryConsensus(const BinaryConsensus&) = delete;
    BinaryConsensus& operator=(const BinaryConsensus&) = delete;

