    ConsensusStatus propose(uint64_t my_value, 
                            uint64_t my_thread_id,
                            uint64_t& decided_value) noexcept {
        // ---- Input validation ----
        if (my_thread_id == EMPTY || my_thread_id > VALUE_MASK) {
            decided_value = 0;
            return ConsensusStatus::ERROR;
        }
        if (my_value > VALUE_MASK) {
            decided_value = 0;
            return ConsensusStatus::ERROR;
        }

        // ---- Try to install our proposal ----
        uint64_t expected = pack(0, EMPTY);  // we expect the state to be empty
        uint64_t desired = pack(my_value, my_thread_id);

        // compare_exchange_strong: atomically replace expected with desired
        // iff state_ == expected. On failure, expected is updated to current state.
        if (state_.compare_exchange_strong(
                expected, desired,
                std::memory_order_acq_rel,
                std::memory_order_acquire)) {
            // CAS succeeded: we won the race
            decided_value = my_value;
            return ConsensusStatus::WON;
        }

        // ---- CAS failed: another thread installed their proposal ----
        // 'expected' now holds the current state (set by compare_exchange_strong)
        decided_value = unpack_value(expected);
        return ConsensusStatus::ADOPTED;
    }

