namespace wait_free {

// Status code returned by propose()
enum class ConsensusStatus : int {
    WON      =  0,  // Our value was chosen by consensus
    ADOPTED  =  1,  // We adopted another thread's value
    ERR_ID   = -1,  // Invalid thread_id (== EMPTY or > 32 bits)
    ERR_VAL  = -2   // Invalid value (> 32 bits)
};

// Wait-free binary consensus using a single CAS operation.
//
// Thread-safety: All public methods are safe to call concurrently from
// multiple threads.
//
// Wait-freedom: Every call to propose() completes in at most one CAS
// operation (O(1) steps), regardless of other threads' behavior.
class BinaryConsensus {
public:
    // Sentinel: indicates no proposal has been made yet.
    // Must not be used as a thread_id.
    static constexpr uint64_t EMPTY = 0xFFFFFFFFULL;

private:
    // We pack (thread_id, value) into a single 64-bit atomic so that
    // the entire consensus state can be updated with one CAS.
    //   bits 63..32 : thread_id (0 means "no proposal")
    //   bits 31..0  : proposed value
    std::atomic<uint64_t> state_;

    static constexpr uint64_t VALUE_MASK    = 0xFFFFFFFFULL;
    static constexpr uint64_t THREAD_SHIFT  = 32;

    static uint64_t pack(uint64_t value, uint64_t tid) noexcept {
        return (tid << THREAD_SHIFT) | (value & VALUE_MASK);
    }
    static uint64_t value_of(uint64_t s) noexcept { return s & VALUE_MASK; }
    static uint64_t tid_of(uint64_t s) noexcept { return s >> THREAD_SHIFT; }

public:
    BinaryConsensus() noexcept : state_(pack(0, EMPTY)) {}

    BinaryConsensus(const BinaryConsensus&) = delete;
    BinaryConsensus& operator=(const BinaryConsensus&) = delete;

    // Propose a value. Returns the consensus decision.
    //
    // my_value    : the value this thread proposes (0 .. 2^32-1)
    // my_thread_id: unique non-EMPTY id for this thread (0 .. 2^32-2)
    // decided     : set to the value chosen by consensus
    //
    // Return value tells you whether YOUR value won or you adopted another.
    ConsensusStatus propose(uint64_t my_value,
                            uint64_t my_thread_id,
                            uint64_t& decided) noexcept {
        // --- Failure handling: validate inputs ---
        if (my_thread_id == EMPTY || my_thread_id > VALUE_MASK) {
            decided = 0;
            return ConsensusStatus::ERR_ID;
        }
        if (my_value > VALUE_MASK) {
            decided = 0;
            return ConsensusStatus::ERR_VAL;
        }

        // --- The core wait-free CAS ---
        // We expect the state to be "empty" (no proposal yet).
        // If so, atomically replace it with our proposal.
        uint64_t expected = pack(0, EMPTY);
        const uint64_t desired = pack(my_value, my_thread_id);

        if (state_.compare_exchange_strong(
                expected, desired,
                std::memory_order_acq_rel,
                std::memory_order_acquire)) {
            // CAS succeeded -> our value is the consensus decision
            decided = my_value;
            return ConsensusStatus::WON;
        }

        // CAS failed -> another thread installed their proposal first.
        // compare_exchange_strong updated 'expected' to the current state,
        // so we can read the winner's value directly from it.
        decided = value_of(expected);
        return ConsensusStatus::ADOPTED;
    }

    // Inspect the current state (for testing).
    // Returns true if a decision has been made.
    bool has_decided() const noexcept {
        return tid_of(state_.load(std::memory_order_acquire)) != EMPTY;
    }

    uint64_t current_value() const noexcept {
        return value_of(state_.load(std::memory_order_acquire));
    }
};

} // namespace wait_free
