    # Each pigeon in some hole, no two pigeons in same hole
    # Variables: x_ij = pigeon i in hole j
    # For 3 pigeons, 2 holes: 6 variables
    # Each pigeon in at least one hole: (x_i1 ∨ x_i2) for i=1,2,3
    # No two pigeons in same hole: (¬x_i1 ∨ ¬x_j1) and (¬x_i2 ∨ ¬x_j2) for i<j
    ph_clauses = []
    for i in range(1, 4):
        ph_clauses.append([2*(i-1)+1, 2*(i-1)+2])  # pigeon i in some hole
    for i in range(1, 4):
        for j in range(i+1, 4):
            ph_clauses.append([-(2*(i-1)+1), -(2*(j-1)+1)])  # not both in hole 1
            ph_clauses.append([-(2*(i-1)+2), -(2*(j-1)+2)])  # not both in hole 2
    result = solve_sat(6, ph_clauses)
    print("Pigeonhole(3,2):", "SAT" if result else "UNSAT")
