# Copying Data to GPU and Synchronising a CUDA Stream

Here's a complete example showing the typical workflow: allocate device memory, upload data, launch a kernel, synchronise the stream, then read results back.

## Minimal Example

```cpp
#include <cuda_runtime.h>
#include <iostream>
#include <vector>

// A simple kernel that doubles each element
__global__ void doubleValues(const float* in, float* out, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        out[idx] = in[idx] * 2.0f;
    }
}

void checkCuda(cudaError_t err, const char* msg) {
    if (err != cudaSuccess) {
        std::cerr << "CUDA error: " << msg << " - "
                  << cudaGetErrorString(err) << std::endl;
        std::exit(EXIT_FAILURE);
    }
}

int main() {
    const int N = 1024;
    const size_t bytes = N * sizeof(float);

    // 1. Host data
    std::vector<float> h_in(N), h_out(N);
    for (int i = 0; i < N; ++i) h_in[i] = static_cast<float>(i);

    // 2. Allocate device memory
    float *d_in = nullptr, *d_out = nullptr;
    checkCuda(cudaMalloc(&d_in,  bytes), "malloc d_in");
    checkCuda(cudaMalloc(&d_out, bytes), "malloc d_out");

    // 3. Create a non-default stream
    cudaStream_t stream;
    checkCuda(cudaStreamCreate(&stream), "stream create");

    // 4. Copy host -> device asynchronously on the stream
    checkCuda(cudaMemcpyAsync(d_in, h_in.data(), bytes,
                              cudaMemcpyHostToDevice, stream),
              "memcpy H2D");

    // 5. Launch kernel on the same stream
    int block = 256;
    int grid  = (N + block - 1) / block;
    doubleValues<<<grid, block, 0, stream>>>(d_in, d_out, N);

    // 6. Copy device -> host asynchronously on the same stream
    checkCuda(cudaMemcpyAsync(h_out.data(), d_out, bytes,
                              cudaMemcpyDeviceToHost, stream),
              "memcpy D2H");

    // 7. Synchronise the stream — blocks until all above work is done
    checkCuda(cudaStreamSynchronize(stream), "stream sync");

    // 8. Check the result
    bool ok = true;
    for (int i = 0; i < N; ++i) {
        if (h_out[i] != h_in[i] * 2.0f) { ok = false; break; }
    }
    std::cout << (ok ? "OK" : "FAIL") << std::endl;

    // 9. Cleanup
    cudaFree(d_in);
    cudaFree(d_out);
    cudaStreamDestroy(stream);
    return 0;
}
```

## Key Points

| Step | API | Purpose |
|------|-----|---------|
| Allocate | `cudaMalloc` | Device memory |
| Upload | `cudaMemcpyAsync(..., HostToDevice, stream)` | Async H→D on a stream |
| Launch | `kernel<<<grid, block, 0, stream>>>()` | Run on the same stream |
| Download | `cudaMemcpyAsync(..., DeviceToHost, stream)` | Async D→H on the same stream |
| Sync | `cudaStreamSynchronize(stream)` | Wait for **that** stream only |
| (Alt) | `cudaDeviceSynchronize()` | Wait for **all** streams + default |

## Why Use a Stream?

- **Ordering**: Operations submitted to the same stream execute in FIFO order. The D→H copy won't start until the kernel finishes.
- **Concurrency**: Different streams can run in parallel on the GPU.
- **Lower latency**: `cudaMemcpyAsync` returns immediately; the copy overlaps with host work.

## Common Pitfalls

1. **Forgetting to sync before reading** — `h_out` will contain garbage. Always `cudaStreamSynchronize` (or use a synchronous `cudaMemcpy`) before using host-side results.
2. **Mixing streams** — If you launch the kernel on the default stream (`0`) but copy on a custom stream, ordering is **not** guaranteed unless you use `cudaStreamSynchronize` or events.
3. **Page-locked memory** — For true async overlap, allocate host buffers with `cudaMallocHost` (pinned). Plain pageable memory forces `cudaMemcpyAsync` to behave synchronously internally.
4. **Not checking return codes** — Kernel launches don't return errors directly; follow them with `cudaGetLastError()`.

## Pinned-Host Variant (Recommended for Performance)

```cpp
float *h_in_pin = nullptr, *h_out_pin = nullptr;
cudaMallocHost(&h_in_pin,  bytes);   // page-locked
cudaMallocHost(&h_out_pin, bytes);

// ... fill h_in_pin ...

cudaMemcpyAsync(d_in, h_in_pin, bytes, cudaMemcpyHostToDevice, stream);
doubleValues<<<grid, block, 0, stream>>>(d_in, d_out, N);
cudaMemcpyAsync(h_out_pin, d_out, bytes, cudaMemcpyDeviceToHost, stream);
cudaStreamSynchronize(stream);

// use h_out_pin ...
```

This lets the H↔D copies truly overlap with kernel execution and with host code.

