Here's a ready-to-use template in C++ (C++20). The key idea: a **release store** by the writer guarantees that all prior writes are visible to a thread that does an **acquire load** and sees the stored value.

## Single "data ready" flag (producer/consumer)

```cpp
#include <atomic>
#include <thread>
#include <cstdint>

struct SharedState {
    // The protected payload
    uint64_t payload_a = 0;
    uint64_t payload_b = 0;

    // 0 = not ready, 1 = ready
    std::atomic<int> ready{0};
};

// Producer
void publish(SharedState& s, uint64_t a, uint64_t b) {
    s.payload_a = a;
    s.payload_b = b;
    // Release: everything above is visible to a thread that acquires `ready`.
    s.ready.store(1, std::memory_order_release);
}

// Consumer
bool consume(SharedState& s, uint64_t& out_a, uint64_t& out_b) {
    // Acquire: if we see ready==1, payload_a/b are guaranteed visible.
    if (s.ready.load(std::memory_order_acquire) != 1) {
        return false;
    }
    out_a = s.payload_a;
    out_b = s.payload_b;
    return true;
}
```

## Multiple flags (state machine)

```cpp
#include <atomic>
#include <cstdint>

enum : uint32_t {
    FLAG_INIT   = 1u << 0,
    FLAG_CONFIG = 1u << 1,
    FLAG_DATA   = 1u << 2,
    FLAG_DONE   = 1u << 3,
};

struct SharedFlags {
    std::atomic<uint32_t> flags{0};
    // ... other state ...
};

// Writer: set a flag, releasing all prior writes.
void set_flag(SharedFlags& s, uint32_t flag) {
    // (do writes to other state here)
    s.flags.fetch_or(flag, std::memory_order_release);
}

// Reader: wait until a flag is observed, then read state.
bool wait_flag(SharedFlags& s, uint32_t flag) {
    uint32_t observed = s.flags.load(std::memory_order_acquire);
    return (observed & flag) != 0;
}
```

