class HyperLogLog {
public:
    // precision p: number of index bits. m = 2^p buckets.
    // Standard error ≈ 0.804 / sqrt(m).
    //   p=12 → ~1.6% error,  4 KiB
    //   p=14 → ~0.8% error, 16 KiB   (Flajolet et al. recommend this)
    //   p=16 → ~0.4% error, 64 KiB
    explicit HyperLogLog(uint8_t precision = 14)
        : p_(precision), m_(1u << precision) {
        if (precision < 4 || precision > 16) {
            throw std::invalid_argument("precision must be in [4, 16]");
        }
        M_.assign(m_, 0);
    }

    // Add an arbitrary value. We hash it with std::hash and then
    // re-mix with SplitMix64 to make the bit distribution uniform
    // even when std::hash is poor (e.g. identity for integers).
    template <typename T>
    void add(const T& value) {
        uint64_t h = static_cast<uint64_t>(std::hash<T>{}(value));
        add_hash(h);
    }

    // Add a pre-computed 64-bit hash (e.g. from MurmurHash3, xxHash).
    // Use this if you already have a good hash for your key type.
    void add_hash(uint64_t raw) {
        uint64_t h = splitmix64(raw + salt_);
        uint32_t idx = static_cast<uint32_t>(h) & (m_ - 1); // lower p bits
        uint64_t w   = h >> p_;                              // upper 64-p bits
        uint8_t  r   = rho(w);
        if (r > M_[idx]) M_[idx] = r;
    }

    // Merge another HLL with the same precision (take max of buckets).
    // This is what makes HLL sketches composable in distributed systems.
    void merge(const HyperLogLog& other) {
        if (other.p_ != p_) {
            throw std::invalid_argument("precision mismatch");
        }
        for (uint32_t i = 0; i < m_; ++i) {
            if (other.M_[i] > M_[i]) M_[i] = other.M_[i];
        }
    }

    // Estimated number of distinct elements added so far.
    double estimate() const {
        double sum = 0.0;
        uint32_t zeros = 0;
        for (uint32_t j = 0; j < m_; ++j) {
            sum += std::ldexp(1.0, -static_cast<int>(M_[j]));
            if (M_[j] == 0) ++zeros;
        }
        double alpha = alpha_m(m_);
        double E = alpha * static_cast<double>(m_) * static_cast<double>(m_) / sum;

        // Small-range correction (linear counting) — better when many
        // buckets are still zero, i.e. cardinality is small.
        if (E <= 2.5 * static_cast<double>(m_) && zeros != 0) {
            E = static_cast<double>(m_) *
                std::log(static_cast<double>(m_) / static_cast<double>(zeros));
        }
        // Large-range correction — better when E is close to 2^64.
        constexpr double two64 = 18446744073709551616.0; // 2^64
        if (E > two64 / 30.0) {
            E = -two64 * std::log(1.0 - E / two64);
        }
        return E;
    }

    uint8_t  precision()    const { return p_; }
    uint32_t num_buckets()  const { return m_; }
    size_t   memory_bytes() const { return M_.size() * sizeof(uint8_t); }

private:
    // SplitMix64 — fast, well-distributed bit mixer.
    // (Vigna, "Further scramblings of Marsaglia's xorshift generators", 2018)
    static uint64_t splitmix64(uint64_t x) {
        x += 0x9e3779b97f4a7c15ULL;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
        x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
        x ^= x >> 31;
        return x;
    }

    // Position of the leftmost 1-bit in w, 1-indexed.
    // w has 64-p significant bits (upper p bits are zero).
    // Returns 64-p+1 if w == 0.
    static uint8_t rho(uint64_t w, uint8_t p) {
        if (w == 0) return 64 - p + 1;
        return static_cast<uint8_t>(__builtin_clzll(w) - p) + 1;
    }

