Run it in another terminal:
```bash
node client.js
```

## 4. Adding Auto-Reconnect (Reliability)

Network connections drop — here's a simple reconnect strategy:

```js
// reliable-client.js
const WebSocket = require('ws');

let ws;
let reconnectAttempts = 0;
const MAX_DELAY = 30000; // 30 seconds max

function connect() {
  ws = new WebSocket('ws://localhost:8080');

  ws.on('open', () => {
    console.log('✅ Connected');
    reconnectAttempts = 0; // reset on success
    ws.send('Hello again!');
  });

  ws.on('message', (data) => {
    console.log('📩 Received:', data.toString());
  });

  ws.on('close', () => {
    console.log('❌ Disconnected. Reconnecting...');
    scheduleReconnect();
  });

  ws.on('error', (err) => {
    console.error('⚠️ Error:', err.message);
  });
}

function scheduleReconnect() {
  const delay = Math.min(1000 * 2 ** reconnectAttempts, MAX_DELAY);
  reconnectAttempts++;
  console.log(`⏳ Reconnecting in ${delay / 1000}s (attempt ${reconnectAttempts})`);
  setTimeout(connect, delay);
}

connect();
```

## 5. Broadcasting to All Clients (Server)

```js
// broadcast.js
const WebSocket = require('ws');
const wss = new WebSocket.Server({ port: 8080 });

wss.on('connection', (ws) => {
  ws.on('message', (data) => {
    // Send to every connected client
    wss.clients.forEach((client) => {
      if (client.readyState === WebSocket.OPEN) {
        client.send(data.toString());
      }
    });
  });
});
```

## Key Concepts to Remember

| Event | When it fires |
|-------|---------------|
| `open` | Connection successfully established |
| `message` | A message is received |
| `close` | Connection is closed |
| `error` | An error occurred |

| ReadyState | Meaning |
|------------|---------|
| `CONNECTING` | Socket is being created |
| `OPEN` | Connection is ready to communicate |
| `CLOSING` | Connection is closing |
| `CLOSED` | Connection is closed |

