    q->elem_size = elem_size;
    q->capacity  = capacity;
    q->mask      = capacity - 1;
    q->buf       = malloc(elem_size * capacity);
    if (!q->buf) return -1;
    atomic_init(&q->head, 0);
    atomic_init(&q->tail, 0);
    return 0;
}

static inline void spsc_destroy(spsc_ring_t *q) {
    free(q->buf);
    q->buf = NULL;
}

/* Producer-only. Returns 0 on success, -1 if the ring is full. */
static inline int spsc_push(spsc_ring_t *q, const void *item) {
    const size_t head = atomic_load_explicit(&q->head, memory_order_relaxed);
    /* Acquire pairs with the consumer's release-store to tail, so we
     * observe the consumer's progress before deciding the ring is full. */
    const size_t tail = atomic_load_explicit(&q->tail, memory_order_acquire);

    if (head - tail >= q->capacity)
        return -1;  /* full */

    memcpy(q->buf + (head & q->mask) * q->elem_size, item, q->elem_size);

    /* Release pairs with the consumer's acquire-load of head, ensuring
     * the element write above is visible before the new head is seen. */
    atomic_store_explicit(&q->head, head + 1, memory_order_release);
    return 0;
}

/* Consumer-only. Returns 0 on success, -1 if the ring is empty. */
static inline int spsc_pop(spsc_ring_t *q, void *item) {
    const size_t tail = atomic_load_explicit(&q->tail, memory_order_relaxed);
    /* Acquire pairs with the producer's release-store to head, so we
     * observe the freshly written element before reading it. */
    const size_t head = atomic_load_explicit(&q->head, memory_order_acquire);

    if (tail == head)
        return -1;  /* empty */

    memcpy(item, q->buf + (tail & q->mask) * q->elem_size, q->elem_size);

    /* Release pairs with the producer's acquire-load of tail, ensuring
     * the element read above completes before we advertise the slot free. */
    atomic_store_explicit(&q->tail, tail + 1, memory_order_release);
    return 0;
}
```

