```js
import _ from 'lodash';

const original = {
  user: {
    name: 'Alice',
    address: { city: 'Wonderland', zip: '12345' },
    hobbies: ['reading', 'chess'],
  },
};

const clone = _.cloneDeep(original);

// Mutate the clone without affecting the original
clone.user.address.city = 'Looking-Glass Land';
clone.user.hobbies.push('gardening');

console.log(original.user.address.city); // 'Wonderland'
console.log(original.user.hobbies);      // ['reading', 'chess']
