# ---------------------------------------------------------------------------
# Offline code-system dictionary (subset)
# ---------------------------------------------------------------------------

CODE_SYSTEMS: Dict[str, Dict[str, str]] = {
    "http://hl7.org/fhir/observation-status": {
        "registered": "Registered", "preliminary": "Preliminary",
        "final": "Final", "amended": "Amended",
