    },
    "http://hl7.org/fhir/condition-clinical": {
        "active": "Active", "recurrence": "Recurrence",
        "relapse": "Relapse", "inactive": "Inactive",
        "remission": "Remission", "resolved": "Resolved",
    },
    "http://hl7.org/fhir/request-status": {
        "draft": "Draft", "active": "Active", "on-hold": "On Hold",
        "revoked": "Revoked", "completed": "Completed",
        "entered-in-error": "Entered in Error", "unknown": "Unknown",
    },
    "http://hl7.org/fhir/medicationrequest-intent": {
        "proposal": "Proposal", "plan": "Plan", "order": "Order",
        "original-order": "Original Order", "reflex-order": "Reflex Order",
        "filler-order": "Filler Order", "instance-order": "Instance Order",
        "option": "Option",
    },
    "http://hl7.org/fhir/bundle-type": {
        "document": "Document", "message": "Message",
        "transaction": "Transaction", "transaction-response": "Transaction Response",
        "batch": "Batch", "batch-response": "Batch Response",
        "history": "History List", "searchset": "Search Results",
        "collection": "Collection",
    },
    "http://hl7.org/fhir/administrative-gender": {
        "male": "Male", "female": "Female",
        "other": "Other", "unknown": "Unknown",
    },
