def validate_coded_value(value: str, system: Optional[str],
                         path: str, result: ValidationResult) -> None:
    if system in CODE_SYSTEMS and value not in CODE_SYSTEMS[system]:
        result.add(Severity.WARNING, path,
                   f"Code {value!r} not in known code system {system}")


# ---------------------------------------------------------------------------
# Reference extraction
# ---------------------------------------------------------------------------

def extract_references(obj: Any, path: str = "") -> List[Tuple[str, str]]:
    refs: List[Tuple[str, str]] = []
    if isinstance(obj, dict):
        if isinstance(obj.get("reference"), str):
            refs.append((f"{path}.reference", obj["reference"]))
        for k, v in obj.items():
            refs.extend(extract_references(v, f"{path}.{k}"))
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            refs.extend(extract_references(v, f"{path}[{i}]"))
    return refs


# ---------------------------------------------------------------------------
# Validator
# ---------------------------------------------------------------------------

class FHIRBundleValidator:
    def __init__(self, strict: bool = False) -> None:
        self.strict = strict
        self.known_full_urls: set = set()
        self.known_ids: Dict[str, set] = {}

    # ---- public ----------------------------------------------------------

    def validate(self, bundle: Any) -> ValidationResult:
        result = ValidationResult()

        if not isinstance(bundle, dict):
            result.add(Severity.ERROR, "$", "Bundle must be a JSON object")
            return result

        if bundle.get("resourceType") != "Bundle":
            result.add(Severity.ERROR, "resourceType",
                       f"Expected 'Bundle', got {bundle.get('resourceType')!r}")
            return result

        self._validate_resource(bundle, "Bundle", "$", result)

        bundle_type = bundle.get("type")
        if isinstance(bundle_type, str):
            validate_coded_value(bundle_type,
                                 "http://hl7.org/fhir/bundle-type",
                                 "$.type", result)

        entries = bundle.get("entry", [])
        if not isinstance(entries, list):
            result.add(Severity.ERROR, "$.entry", "Bundle.entry must be an array")
            return result

        self._index_entries(entries, result)

        for i, entry in enumerate(entries):
            self._validate_entry(entry, i, bundle_type, result)

        self._validate_references(bundle, result)
        return result

    # ---- indexing --------------------------------------------------------

    def _index_entries(self, entries: List[Any], result: ValidationResult) -> None:
        for i, entry in enumerate(entries):
            if not isinstance(entry, dict):
                result.add(Severity.ERROR, f"$.entry[{i}]", "Entry must be an object")
                continue
            full_url = entry.get("fullUrl")
            if isinstance(full_url, str):
                if full_url in self.known_full_urls:
                    result.add(Severity.ERROR, f"$.entry[{i}].fullUrl",
                               f"Duplicate fullUrl: {full_url}")
                self.known_full_urls.add(full_url)

            resource = entry.get("resource")
            if isinstance(resource, dict):
                rtype = resource.get("resourceType")
                rid = resource.get("id")
                if isinstance(rtype, str) and isinstance(rid, str):
                    self.known_ids.setdefault(rtype, set()).add(rid)

    # ---- entry -----------------------------------------------------------

    def _validate_entry(self, entry: Dict[str, Any], index: int,
                        bundle_type: Optional[str],
                        result: ValidationResult) -> None:
        path = f"$.entry[{index}]"

        if "resource" not in entry and "response" not in entry:
            result.add(Severity.ERROR, path,
                       "Entry must contain 'resource' or 'response'")
            return

        resource = entry.get("resource")
        if resource is None:
            return
        if not isinstance(resource, dict):
            result.add(Severity.ERROR, f"{path}.resource", "Resource must be an object")
            return

        rtype = resource.get("resourceType")
        if not isinstance(rtype, str):
            result.add(Severity.ERROR, f"{path}.resource", "Resource missing resourceType")
            return

        self._validate_resource(resource, rtype, f"{path}.resource", result)

        request = entry.get("request")
        if isinstance(request, dict) and bundle_type in ("transaction", "batch"):
            self._validate_request(request, rtype, resource.get("id"), path, result)

    def _validate_request(self, request: Dict[str, Any], rtype: str,
                          rid: Any, entry_path: str,
                          result: ValidationResult) -> None:
        url = request.get("url")
        method = (request.get("method") or "").lower()

        if not isinstance(url, str):
            result.add(Severity.ERROR, f"{entry_path}.request.url",
                       "Request URL required in transaction/batch")
            return

        if method not in ("get", "post", "put", "delete", "patch", "head"):
            result.add(Severity.ERROR, f"{entry_path}.request.method",
                       f"Invalid HTTP method: {method!r}")

        if method in ("put", "delete") and isinstance(rid, str):
            expected = f"{rtype}/{rid}"
            if url != expected:
                result.add(Severity.ERROR, f"{entry_path}.request.url",
                           f"URL {url!r} does not match resource {expected!r}")
        elif method == "post" and "/" in url and not url.startswith(rtype):
            result.add(Severity.WARNING, f"{entry_path}.request.url",
                       f"POST URL {url!r} should typically be {rtype!r}")

    # ---- resource --------------------------------------------------------

    def _validate_resource(self, resource: Dict[str, Any], rtype: str,
                           path: str, result: ValidationResult) -> None:
        schema = RESOURCE_SCHEMA.get(rtype)
        if schema is None:
            result.add(Severity.WARNING, path,
                       f"No offline schema for {rtype!r}; shallow validation only")
            return

        for req in schema.get("required", []):
            if req not in resource:
                result.add(Severity.ERROR, path,
                           f"Missing required field {req!r} for {rtype}")

        fields = schema.get("fields", {})
        for key, value in resource.items():
            if key not in fields:
                if self.strict:
                    result.add(Severity.WARNING, f"{path}.{key}",
                               f"Unknown field {key!r} for {rtype}")
                continue
            self._check_field(value, fields[key], f"{path}.{key}", result)

    # ---- field -----------------------------------------------------------

    def _check_field(self, value: Any, expected: str, path: str,
                     result: ValidationResult) -> None:
        if "|" in expected:
            if not any(self._matches_type(value, o) for o in expected.split("|")):
                result.add(Severity.ERROR, path,
                           f"Value does not match any of choice types: {expected}")
            return

        if not self._matches_type(value, expected):
            result.add(Severity.ERROR, path, f"Expected type {expected}")
            return

        if expected in ("date", "dateTime", "uri", "url", "canonical"):
            validate_primitive(value, expected, path, result)
        elif expected == "CodeableConcept":
            self._validate_codeable_concept(value, path, result)
        elif expected == "Reference":
            self._validate_reference(value, path, result)
        elif expected == "Period":
            self._validate_period(value, path, result)

    def _matches_type(self, value: Any, type_name: str) -> bool:
        primitives = {"code", "string", "uri", "url", "canonical",
                      "id", "instant", "date", "dateTime", "markdown",
                      "base64Binary", "oid", "positiveInt", "unsignedInt"}
        if type_name in primitives:
            return isinstance(value, str)
        if type_name == "boolean":
            return isinstance(value, bool)
        if type_name == "integer":
            return isinstance(value, int) and not isinstance(value, bool)
        if type_name == "decimal":
            return isinstance(value, (int, float)) and not isinstance(value, bool)
        # Complex / backbone types
        return isinstance(value, (dict, list))

    def _validate_codeable_concept(self, cc: Dict[str, Any], path: str,
                                  result: ValidationResult) -> None:
        for i, coding in enumerate(cc.get("coding", []) or []):
            if isinstance(coding, dict):
                system = coding.get("system")
                code = coding.get("code")
                if isinstance(system, str) and isinstance(code, str):
                    validate_coded_value(code, system,
                                         f"{path}.coding[{i}]", result)

    def _validate_reference(self, ref: Dict[str, Any], path: str,
                            result: ValidationResult) -> None:
        if not any(k in ref for k in ("reference", "identifier", "display")):
            result.add(Severity.ERROR, path,
                       "Reference needs one of: reference, identifier, display")

    def _validate_period(self, period: Dict[str, Any], path: str,
                         result: ValidationResult) -> None:
        start, end = period.get("start"), period.get("end")
        if (isinstance(start, str) and isinstance(end, str)) and start > end:
            result.add(Severity.ERROR, path,
                       f"Period.start {start!r} is after Period.end {end!r}")

    # ---- references ------------------------------------------------------

    def _validate_references(self, bundle: Dict[str, Any],
                             result: ValidationResult) -> None:
        for path, ref in extract_references(bundle):
            if "://" in ref or ref.startswith("urn:"):
                continue
            if "/" not in ref:
                continue
            rtype, _, rid = ref.partition("/")
            if not rid:
                continue
            known = self.known_ids.get(rtype, set())
            if rid in known:
                continue
            urn = f"urn:uuid:{rid}" if not rid.startswith("urn:uuid:") else rid
            if ref in self.known_full_urls or urn in self.known_full_urls:
                continue
            result.add(Severity.WARNING, path,
                       f"Reference {ref!r} does not resolve within the bundle")


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def main() -> int:
    import argparse

    ap = argparse.ArgumentParser(description="Offline FHIR R4 Bundle Validator")
    ap.add_argument("file", help="Path to FHIR bundle JSON file")
    ap.add_argument("--strict", action="store_true",
                    help="Warn on unknown fields")
    ap.add_argument("--quiet", action="store_true",
                    help="Only print errors")
    args = ap.parse_args()

    try:
        with open(args.file, "r", encoding="utf-8") as f:
            bundle = json.load(f)
    except json.JSONDecodeError as e:
        print(f"ERROR: Invalid JSON: {e}")
        return 2
    except FileNotFoundError:
        print(f"ERROR: File not found: {args.file}")
        return 2

    result = FHIRBundleValidator(strict=args.strict).validate(bundle)

    issues = result.errors if args.quiet else result.issues
    for issue in issues:
        print(issue)

    print(f"\nErrors: {len(result.errors)}, Warnings: {len(result.warnings)}")
    return 0 if result.valid else 1


if __name__ == "__main__":
    sys.exit(main())
```

