class FHIRBundleValidator:
    def __init__(self, strict: bool = False):
        self.strict = strict
        self.known_full_urls = set()
        self.known_ids: Dict[str, set] = {}  # resourceType -> {ids}

    def validate(self, bundle: Dict[str, Any]) -> ValidationResult:
        result = ValidationResult()

        if not isinstance(bundle, dict):
            result.add(Severity.ERROR, "$", "Bundle must be a JSON object")
            return result

        if bundle.get("resourceType") != "Bundle":
            result.add(
                Severity.ERROR,
                "resourceType",
                f"Expected resourceType 'Bundle', got '{bundle.get('resourceType')}'",
            )
            return result

        # Validate bundle-level fields
        self._validate_resource(bundle, "Bundle", "$", result)

        # Validate bundle type
        bundle_type = bundle.get("type")
        if bundle_type:
            validate_coded_value(
                bundle_type,
                "http://hl7.org/fhir/bundle-type",
                "$.type",
                result,
            )

        # Index entries for reference resolution
        entries = bundle.get("entry", [])
        if not isinstance(entries, list):
            result.add(Severity.ERROR, "$.entry", "Bundle.entry must be an array")
            return result

        self._index_entries(entries, result)

        # Validate each entry
        for i, entry in enumerate(entries):
            self._validate_entry(entry, i, bundle_type, result)

        # Validate references
        self._validate_references(bundle, result)

        return result

    def _index_entries(self, entries: List[Any], result: ValidationResult):
        for i, entry in enumerate(entries):
            if not isinstance(entry, dict):
                result.add(Severity.ERROR, f"$.entry[{i}]", "Entry must be an object")
                continue
            full_url = entry.get("fullUrl")
            if full_url:
                if full_url in self.known_full_urls:
                    result.add(
                        Severity.ERROR,
                        f"$.entry[{i}].fullUrl",
                        f"Duplicate fullUrl: {full_url}",
                    )
                self.known_full_urls.add(full_url)

            resource = entry.get("resource", {})
            if isinstance(resource, dict):
                rtype = resource.get("resourceType")
                rid = resource.get("id")
                if rtype and rid:
                    self.known_ids.setdefault(rtype, set()).add(rid)

    def _validate_entry(
        self,
        entry: Dict[str, Any],
        index: int,
        bundle_type: Optional[str],
        result: ValidationResult,
    ):
        path = f"$.entry[{index}]"

        if "resource" not in entry and "response" not in entry:
            result.add(
                Severity.ERROR,
                path,
                "Entry must contain either 'resource' or 'response'",
            )
            return

        resource = entry.get("resource")
        if resource is None:
            return

        if not isinstance(resource, dict):
            result.add(Severity.ERROR, f"{path}.resource", "Resource must be an object")
            return

        rtype = resource.get("resourceType")
        if not rtype:
            result.add(Severity.ERROR, f"{path}.resource", "Resource missing resourceType")
            return

        # Validate the resource itself
        self._validate_resource(resource, rtype, f"{path}.resource", result)

        # Validate request URL matches resource type/id
        request = entry.get("request")
        if request and bundle_type in ("transaction", "batch"):
            self._validate_request_url(request, rtype, resource.get("id"), path, result)

    def _validate_request_url(
        self,
        request: Dict[str, Any],
        rtype: str,
        rid: Optional[str],
        entry_path: str,
        result: ValidationResult,
    ):
        url = request.get("url")
        if not url:
            result.add(
                Severity.ERROR,
                f"{entry_path}.request.url",
                "Request URL is required in transaction/batch bundles",
            )
            return

        method = request.get("method", "").lower()
        if method not in ("get", "post", "put", "delete", "patch", "head"):
            result.add(
                Severity.ERROR,
                f"{entry_path}.request.method",
                f"Invalid HTTP method: {method}",
            )

        # URL should match ResourceType/[id] for PUT/DELETE
        if method in ("put", "delete") and rid:
            expected = f"{rtype}/{rid}"
            if url != expected:
                result.add(
                    Severity.ERROR,
                    f"{entry_path}.request.url",
                    f"Request URL '{url}' does not match resource '{expected}'",
                )
        elif method == "post":
            if "/" in url and not url.startswith(rtype):
                result.add(
                    Severity.WARNING,
                    f"{entry_path}.request.url",
                    f"POST URL '{url}' should typically be the resource type '{rtype}'",
                )

    def _validate_resource(
        self,
        resource: Dict[str, Any],
        rtype: str,
        path: str,
        result: ValidationResult,
    ):
        schema = RESOURCE_SCHEMA.get(rtype)
        if not schema:
            result.add(
                Severity.WARNING,
                path,
                f"No offline schema for resource type '{rtype}'; performing shallow validation only",
            )
            return

        # Check required fields
        for req in schema.get("required", []):
            if req not in resource:
                result.add(
                    Severity.ERROR,
                    path,
                    f"Missing required field '{req}' for {rtype}",
                )

        # Check field types and primitive formats
        fields = schema.get("fields", {})
        for key, value in resource.items():
            if key not in fields:
                if self.strict:
                    result.add(
                        Severity.WARNING,
                        f"{path}.{key}",
                        f"Unknown field '{key}' for {rtype}",
                    )
                continue

            expected = fields[key]
            self._check_field(value, expected, f"{path}.{key}", result)

    def _check_field(self, value: Any, expected: str, path: str, result: ValidationResult):
        # Handle choice types like "boolean|integer"
        if "|" in expected:
            for opt in expected.split("|"):
                if self._matches_type(value, opt):
                    return
            result.add(
                Severity.ERROR,
                path,
                f"Value does not match any of choice types: {expected}",
            )
            return

        if not self._matches_type(value, expected):
            result.add(
                Severity.ERROR,
                path,
                f"Field type mismatch: expected {expected}",
            )
            return

        # Primitive format checks
        if expected in ("date", "dateTime", "uri", "url", "canonical"):
            validate_primitive(value, expected, path, result)

        # Recurse into complex types
        if expected == "CodeableConcept":
            self._validate_codeable_concept(value, path, result)
        elif expected == "Reference":
            self._validate_reference(value, path, result)
        elif expected == "Period":
            self._validate_period(value, path, result)

    def _matches_type(self, value: Any, type_name: str) -> bool:
        if type_name == "code" or type_name == "string" or type_name == "uri" or \
           type_name == "url" or type_name == "canonical" or type_name == "id" or \
           type_name == "instant" or type_name == "date" or type_name == "dateTime":
            return isinstance(value, str)
        if type_name == "boolean":
            return isinstance(value, bool)
        if type_name == "integer":
            return isinstance(value, int) and not isinstance(value, bool)
        if type_name == "decimal":
            return isinstance(value, (int, float)) and not isinstance(value, bool)
        if type_name.startswith("CodeableConcept") or type_name.startswith("Reference") or \
           type_name.startswith("Period") or type_name.startswith("Quantity") or \
           type_name.startswith("Coding") or type_name.startswith("HumanName") or \
           type_name.startswith("Address") or type_name.startswith("ContactPoint") or \
           type_name.startswith("Meta") or type_name.startswith("Dosage"):
            return isinstance(value, dict)
        if type_name.startswith("Bundle.entry") or type_name.startswith("Patient.contact"):
            return isinstance(value, (dict, list))
        return True

    def _validate_codeable_concept(
        self, cc: Dict[str, Any], path: str, result: ValidationResult
    ):
        if "coding" in cc:
            for i, coding in enumerate(cc["coding"]):
                if isinstance(coding, dict):
                    system = coding.get("system")
                    code = coding.get("code")
                    if system and code:
                        validate_coded_value(code, system, f"{path}.coding[{i}]", result)

    def _validate_reference(self, ref: Dict[str, Any], path: str, result: ValidationResult):
        if "reference" not in ref and "identifier" not in ref and "display" not in ref:
            result.add(
                Severity.ERROR,
                path,
                "Reference must have at least one of: reference, identifier, display",
            )

    def _validate_period(self, period: Dict[str, Any], path: str, result: ValidationResult):
        start = period.get("start")
        end = period.get("end")
        if start and end and isinstance(start, str) and isinstance(end, str):
            if start > end:
                result.add(
                    Severity.ERROR,
                    path,
                    f"Period.start '{start}' is after Period.end '{end}'",
                )

    def _validate_references(self, bundle: Dict[str, Any], result: ValidationResult):
        refs = extract_references(bundle)
        for path, ref in refs:
            # Only check internal references (no URL scheme)
            if "://" in ref or ref.startswith("urn:"):
                continue
            if "/" not in ref:
                continue

            rtype, _, rid = ref.partition("/")
            if not rid:
                continue

            known = self.known_ids.get(rtype, set())
            if rid not in known:
                # Check if it matches a fullUrl
                full_url = f"urn:uuid:{rid}" if not rid.startswith("urn:uuid:") else rid
                if full_url not in self.known_full_urls and ref not in self.known_full_urls:
                    result.add(
                        Severity.WARNING,
                        path,
                        f"Reference '{ref}' does not resolve to a known resource in the bundle",
                    )


# ---------- CLI ----------

def main():
