#include <quiche.h>

#define LOCAL_CONN_ID_LEN 16
#define MAX_DATAGRAM_SIZE 1350
#define MAX_STREAM_DATA 65536

static int make_socket(struct sockaddr_in *local, struct sockaddr_in *peer) {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) return -1;

    if (bind(sock, (struct sockaddr *)local, sizeof(*local)) < 0) {
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)peer, sizeof(*peer)) < 0) {
        close(sock);
        return -1;
    }

    return sock;
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s HOST PORT MESSAGE\n", argv[0]);
        return 1;
    }

    const char *host = argv[1];
    uint16_t port = (uint16_t)atoi(argv[2]);
    const char *message = argv[3];

    // Set up addresses
    struct sockaddr_in local = {0};
    local.sin_family = AF_INET;
    local.sin_port = 0;
    inet_pton(AF_INET, "0.0.0.0", &local.sin_addr);

    struct sockaddr_in peer = {0};
    peer.sin_family = AF_INET;
    peer.sin_port = htons(port);
    inet_pton(AF_INET, host, &peer.sin_addr);

    int sock = make_socket(&local, &peer);
    if (sock < 0) {
        perror("socket");
        return 1;
    }

    // Generate connection ID
    uint8_t conn_id[LOCAL_CONN_ID_LEN];
    for (int i = 0; i < LOCAL_CONN_ID_LEN; i++) {
        conn_id[i] = rand() & 0xff;
    }

    // Configure quiche
    quiche_config *config = quiche_config_new(QUICHE_PROTOCOL_VERSION);
    quiche_config_set_application_protos(config, 
        (uint8_t *)"\x0ahq-interop", 11);
    quiche_config_set_max_idle_timeout(config, 5000);
    quiche_config_set_max_recv_udp_payload_size(config, MAX_DATAGRAM_SIZE);
    quiche_config_set_max_send_udp_payload_size(config, MAX_DATAGRAM_SIZE);
    quiche_config_set_initial_max_data(config, 10000000);
    quiche_config_set_initial_max_stream_data_bidi_local(config, 1000000);
    quiche_config_set_initial_max_stream_data_bidi_remote(config, 1000000);
    quiche_config_set_initial_max_streams_bidi(config, 100);
    quiche_config_set_disable_active_migration(config, true);

    // Skip certificate verification for example
    quiche_config_set_verify_peer(config, false);

    // Create connection
    quiche_conn *conn = quiche_connect(host, (const struct sockaddr *)&local,
        sizeof(local), (const struct sockaddr *)&peer, sizeof(peer),
        config);

    if (!conn) {
        fprintf(stderr, "quiche_connect failed\n");
        return 1;
    }

    // Allocate SCID
    quiche_conn_set_scids(conn, conn_id, LOCAL_CONN_ID_LEN);

    // Handshake loop
    uint8_t buf[MAX_DATAGRAM_SIZE];
    ssize_t read;

    while (!quiche_conn_is_established(conn)) {
        // Send outgoing
        ssize_t written = 0;
        while ((written = quiche_conn_send(conn, buf, sizeof(buf))) > 0) {
            ssize_t sent = send(sock, buf, written, 0);
            if (sent != written) {
                perror("send");
            }
        }

        // Receive
        struct timeval tv = {0, 1000}; // 1ms
        setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

        while ((read = recv(sock, buf, sizeof(buf), 0)) > 0) {
            ssize_t done = quiche_conn_recv(conn, buf, read);
            if (done < 0) {
                fprintf(stderr, "quiche_conn_recv failed\n");
                return 1;
            }
        }
    }

    printf("Connection established!\n");

    // Send request on stream 0
    quiche_stream_send(conn, 0, (uint8_t *)message, strlen(message), false);

    // Stream response
    bool sent_fin = false;
    while (!sent_fin) {
        // Send
        ssize_t written = quiche_conn_send(conn, buf, sizeof(buf));
        if (written > 0) {
            send(sock, buf, written, 0);
        }

        // Receive
        read = recv(sock, buf, sizeof(buf), 0);
        if (read > 0) {
            quiche_conn_recv(conn, buf, read);
        }

        // Read stream
        ssize_t stream_read = quiche_stream_recv(conn, 0, buf, sizeof(buf));
        if (stream_read > 0) {
            fwrite(buf, 1, stream_read, stdout);
        } else if (stream_read == 0) {
            sent_fin = true;
        }
    }

    printf("\n");

    // Close
    quiche_conn_close(conn, true, 0, NULL, 0);

    // Drain
    while (true) {
        ssize_t written = quiche_conn_send(conn, buf, sizeof(buf));
        if (written <= 0) break;
        send(sock, buf, written, 0);
    }

    quiche_conn_free(conn);
    quiche_config_free(config);
    close(sock);

    return 0;
}
