/*
 * Minimal QUIC client using quiche.
 *
 * Demonstrates a reliable (lossless) stream-based exchange with a QUIC server.
 *
 * Build (after installing quiche):
 *   gcc quic_client.c -o quic_client -lquiche
 *
 * Usage:
 *   ./quic_client <server-ip> <port> <message>
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#include <quiche.h>

#define LOCAL_CONN_ID_LEN 16
#define MAX_DATAGRAM_SIZE 1350

static void die(const char *msg) {
    fprintf(stderr, "%s: %s\n", msg, strerror(errno));
    exit(1);
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s HOST PORT MESSAGE\n", argv[0]);
        return 1;
    }

    const char *host = argv[1];
    uint16_t    port = (uint16_t)atoi(argv[2]);
    const char *msg  = argv[3];
    size_t      msglen = strlen(msg);

    /* ---- UDP socket ---- */
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) die("socket");

    struct sockaddr_in local = {0};
    local.sin_family = AF_INET;
    local.sin_port   = 0;
    if (inet_pton(AF_INET, "0.0.0.0", &local.sin_addr) != 1) die("pton local");

    if (bind(sock, (struct sockaddr *)&local, sizeof(local)) < 0)
        die("bind");

    struct sockaddr_in peer = {0};
    peer.sin_family = AF_INET;
    peer.sin_port   = htons(port);
    if (inet_pton(AF_INET, host, &peer.sin_addr) != 1) die("pton peer");

    if (connect(sock, (struct sockaddr *)&peer, sizeof(peer)) < 0)
        die("connect");

    /* ---- quiche config ---- */
    quiche_config *config = quiche_config_new(QUICHE_PROTOCOL_VERSION);
    if (!config) die("quiche_config_new");

    /* ALPN: "hq-interop" prefixed by its 1-byte length (0x0a = 10) */
    const uint8_t alpn[] = "\x0ahq-interop";
    quiche_config_set_application_protos(config, alpn, sizeof(alpn) - 1);

    quiche_config_set_max_idle_timeout(config, 5000);
    quiche_config_set_max_recv_udp_payload_size(config, MAX_DATAGRAM_SIZE);
    quiche_config_set_max_send_udp_payload_size(config, MAX_DATAGRAM_SIZE);
    quiche_config_set_initial_max_data(config, 10 * 1024 * 1024);
    quiche_config_set_initial_max_stream_data_bidi_local(config, 1024 * 1024);
    quiche_config_set_initial_max_stream_data_bidi_remote(config, 1024 * 1024);
    quiche_config_set_initial_max_streams_bidi(config, 100);
    quiche_config_set_disable_active_migration(config, true);

    /* Skip certificate verification for the example. */
    quiche_config_set_verify_peer(config, false);

    /* ---- connection ---- */
    quiche_conn *conn = quiche_connect(host,
        (const struct sockaddr *)&local,  sizeof(local),
        (const struct sockaddr *)&peer,   sizeof(peer),
        config);
    if (!conn) die("quiche_connect");

    uint8_t scid[LOCAL_CONN_ID_LEN];
    srand((unsigned)time(NULL));
    for (size_t i = 0; i < LOCAL_CONN_ID_LEN; i++) scid[i] = rand() & 0xff;
    quiche_conn_set_scids(conn, scid, LOCAL_CONN_ID_LEN);

    /* ---- handshake loop ---- */
    uint8_t buf[MAX_DATAGRAM_SIZE];
    struct timeval tv = { .tv_sec = 0, .tv_usec = 2 * 1000 }; /* 2 ms */
    setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

    while (!quiche_conn_is_established(conn)) {
        ssize_t written = quiche_conn_send(conn, buf, sizeof(buf));
        if (written > 0) {
            if (send(sock, buf, written, 0) < 0) die("send");
        } else if (written < 0) {
            fprintf(stderr, "quiche_conn_send: %zd\n", written);
            return 1;
        }

        ssize_t read = recv(sock, buf, sizeof(buf), 0);
        if (read > 0) {
            ssize_t done = quiche_conn_recv(conn, buf, read);
            if (done < 0) {
                fprintf(stderr, "quiche_conn_recv: %zd\n", done);
                return 1;
            }
        }
    }
    fprintf(stderr, "handshake complete\n");

    /* ---- send request on stream 0 ---- */
    ssize_t sent = quiche_stream_send(conn, 0, (const uint8_t *)msg, msglen, true);
    if (sent < 0) {
        fprintf(stderr, "quiche_stream_send: %zd\n", sent);
        return 1;
    }

    /* ---- read response until FIN ---- */
    bool got_fin = false;
    while (!got_fin) {
        ssize_t written = quiche_conn_send(conn, buf, sizeof(buf));
        if (written > 0) {
            if (send(sock, buf, written, 0) < 0) die("send");
        }

        ssize_t read = recv(sock, buf, sizeof(buf), 0);
        if (read > 0) {
            if (quiche_conn_recv(conn, buf, read) < 0) continue;
        }

        bool fin = false;
        ssize_t n = quiche_stream_recv(conn, 0, buf, sizeof(buf), &fin);
        if (n > 0) {
            fwrite(buf, 1, (size_t)n, stdout);
        }
        if (fin) got_fin = true;
    }
    fputc('\n', stdout);

    /* ---- graceful close ---- */
    quiche_conn_close(conn, true, 0, NULL, 0);

    for (int i = 0; i < 5; i++) {
        ssize_t written = quiche_conn_send(conn, buf, sizeof(buf));
        if (written <= 0) break;
        send(sock, buf, written, 0);
    }

    quiche_conn_free(conn);
    quiche_config_free(config);
    close(sock);
    return 0;
}
```

