response_text:
# UDP with Reliable Exactly-Once Delivery in Go

Standard UDP provides no reliability or deduplication. To get "exactly-once" semantics, you need an application-layer protocol on top. There are two practical approaches:

## Option 1: QUIC (Recommended)

QUIC is a UDP-based transport that natively provides reliability, ordering, and stream multiplexing. Use the `quic-go` library:

```bash
go get github.com/quic-go/quic-go
```

**Server:**
```go
package main

import (
    "context"
    "crypto/rand"
    "crypto/rsa"
    "crypto/tls"
    "crypto/x509"
    "crypto/rand"
    "encoding/pem"
    "fmt"
    "log"
    "math/big"
    "time"

    "github.com/quic-go/quic-go"
)

func main() {
    listener, err := quic.ListenAddr("0.0.0.0:4242", generateTLSConfig(), &quic.Config{
        MaxIdleTimeout:  30 * time.Second,
        KeepAlivePeriod: 10 * time.Second,
    })
    if err != nil {
        log.Fatal(err)
    }
    defer listener.Close()

    log.Println("QUIC server listening on :4242")

    for {
        conn, err := listener.Accept(context.Background())
        if err != nil {
            continue
        }
        go handleConn(conn)
    }
}

func handleConn(conn *quic.Conn) {
    defer conn.Close()
    for {
        stream, err := conn.AcceptStream(context.Background())
        if err != nil {
            return
        }
        go handleStream(stream)
    }
}

func handleStream(stream *quic.Stream) {
    defer stream.Close()
    buf := make([]byte, 4096)
    n, err := stream.Read(buf)
    if err != nil {
        return
    }
    msg := string(buf[:n])
    log.Printf("Received: %s", msg)
    stream.Write([]byte("ACK: " + msg))
}

func generateTLSConfig() *tls.Config {
    key, _ := rsa.GenerateKey(rand.Reader, 2048)
    tmpl := &x509.Certificate{
        SerialNumber: big.NewInt(1),
        NotBefore:    time.Now(),
        NotAfter:     time.Now().Add(24 * time.Hour),
        KeyUsage:     x509.KeyUsageDigitalSignature | x509.KeyUsageKeyEncipherment,
        ExtKeyUsage:  []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
    }
    certDER, _ := x509.CreateCertificate(rand.Reader, tmpl, tmpl, &key.PublicKey, key)
    certPEM := pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: certDER})
    keyPEM := pem.EncodeToMemory(&pem.Block{Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(key)})
    tlsCert, _ := tls.X509KeyPair(certPEM, keyPEM)
    return &tls.Config{Certificates: []tls.Certificate{tlsCert}, NextProtos: []string{"my-app"}}
}
```

**Client:**
```go
package main

import (
    "context"
    "crypto/tls"
    "fmt"
    "log"
    "time"

    "github.com/quic-go/quic-go"
)

func main() {
    tlsCfg := &tls.Config{InsecureSkipVerify: true, NextProtos: []string{"my-app"}}
    conn, err := quic.DialAddr(context.Background(), "localhost:4242", tlsCfg, nil)
    if err != nil {
        log.Fatal(err)
    }
    defer conn.Close()

    stream, err := conn.OpenStreamSync(context.Background())
    if err != nil {
        log.Fatal(err)
    }
    defer stream.Close()

    stream.Write([]byte("hello exactly-once"))
    buf := make([]byte, 4096)
    stream.SetReadDeadline(time.Now().Add(5 * time.Second))
    n, _ := stream.Read(buf)
    fmt.Printf("Server replied: %s\n", buf[:n])
}
```

QUIC gives you exactly-once delivery per stream for free — no dedup logic needed.

---

## Option 2: Custom UDP with Reliability + Dedup

If you need raw UDP (e.g., for a custom protocol), implement two things:
1. **Reliability** — sequence numbers + ACKs + retransmissions
2. **Exactly-once** — server-side dedup window

**Packet format:**
```
| type (1B) | seq (4B) | payload_len (2B) | payload |
```

**Server (`server.go`):**
```go
package main

import (
    "encoding/binary"
    "fmt"
    "log"
    "net"
    "sync"
    "time"
)

const (
    TypeData = 1
    TypeAck  = 2
    HeaderSize = 7
    DedupTTL   = 30 * time.Second
)

type Server struct {
    conn    *net.UDPConn
    mu      sync.Mutex
    seen    map[uint32]time.Time
}

func NewServer() *Server {
    return &Server{seen: make(map[uint32]time.Time)}
}

func (s *Server) Start(addr string) error {
    udpAddr, err := net.ResolveUDPAddr("udp", addr)
    if err != nil {
        return err
    }
    conn, err := net.ListenUDP("udp", udpAddr)
    if err != nil {
        return err
    }
    s.conn = conn
    defer conn.Close()

    go s.cleanupLoop()
    log.Printf("UDP server listening on %s", addr)

    buf := make([]byte, 2048)
    for {
        n, remote, err := conn.ReadFromUDP(buf)
        if err != nil {
            log.Println("read err:", err)
            continue
        }
        if n < HeaderSize {
            continue
        }
        pktType := buf[0]
        if pktType != TypeData {
            continue
        }
        seq := binary.BigEndian.Uint32(buf[1:5])
        payloadLen := binary.BigEndian.Uint16(buf[5:7])
        if int(HeaderSize+payloadLen) > n {
            continue
        }
        payload := buf[HeaderSize : HeaderSize+payloadLen]

        if s.alreadySeen(seq) {
            log.Printf("duplicate seq=%d, re-ACKing", seq)
            s.sendAck(remote, seq)
            continue
        }
        s.markSeen(seq)

        // ---- Exactly-once processing happens here ----
        fmt.Printf("[seq=%d] %s\n", seq, string(payload))
        // ----------------------------------------------

