    }
}

func (s *Server) alreadySeen(seq uint32) bool {
    s.mu.Lock()
    defer s.mu.Unlock()
    _, ok := s.seen[seq]
    return ok
}

func (s *Server) markSeen(seq uint32) {
    s.mu.Lock()
    defer s.mu.Unlock()
    s.seen[seq] = time.Now()
}

func (s *Server) sendAck(addr *net.UDPAddr, seq uint32) {
    pkt := make([]byte, HeaderSize)
    pkt[0] = TypeAck
    binary.BigEndian.PutUint32(pkt[1:5], 0)
    binary.BigEndian.PutUint16(pkt[5:7], 0)
    // piggyback the acked seq in payload area for simplicity
    binary.BigEndian.PutUint32(pkt[1:5], seq)
    s.conn.WriteToUDP(pkt, addr)
}

func (s *Server) cleanupLoop() {
    t := time.NewTicker(5 * time.Second)
    defer t.Stop()
    for range t.C {
        cutoff := time.Now().Add(-DedupTTL)
        s.mu.Lock()
        for seq, ts := range s.seen {
            if ts.Before(cutoff) {
                delete(s.seen, seq)
            }
        }
        s.mu.Unlock()
    }
}

