func sendReliable(conn *net.UDPConn, seq uint32, payload []byte) error {
    pkt := make([]byte, HeaderSize+len(payload))
    pkt[0] = TypeData
    binary.BigEndian.PutUint32(pkt[1:5], seq)
    binary.BigEndian.PutUint16(pkt[5:7], uint16(len(payload)))
    copy(pkt[HeaderSize:], payload)

    for attempt := 0; attempt < MaxRetries; attempt++ {
        // Simulate ~20% packet loss to demonstrate retransmit + dedup
        if rand.Intn(5) == 0 && attempt == 0 {
            log.Printf("simulating loss for seq=%d", seq)
            // skip send, fall through to wait
        } else {
            if _, err := conn.Write(pkt); err != nil {
                return err
            }
        }

        if waitForAck(conn, seq) {
            return nil
        }
        log.Printf("retry %d for seq=%d", attempt+1, seq)
    }
    return fmt.Errorf("seq=%d failed after %d retries", seq, MaxRetries)
}

func waitForAck(conn *net.UDPConn, expectedSeq uint32) bool {
    conn.SetReadDeadline(time.Now().Add(Timeout))
    buf := make([]byte, HeaderSize)
    for {
        n, err := conn.Read(buf)
        if err != nil {
            return false
        }
        if n < HeaderSize || buf[0] != TypeAck {
            continue
        }
        ackSeq := binary.BigEndian.Uint32(buf[1:5])
        if ackSeq == expectedSeq {
            return true
        }
    }
}
