package main

import (
    "encoding/binary"
    "fmt"
    "log"
    "net"
    "sync"
    "time"
)

const (
    MaxPacketSize = 1024
    HeaderSize    = 8 // 4 bytes seq + 4 bytes ack
    DedupWindow   = 1000
)

type Server struct {
    conn     *net.UDPConn
    mu       sync.Mutex
    seen     map[uint32]time.Time // sequence number -> time seen
    lastSeq  uint32
}

func NewServer() *Server {
    return &Server{
        seen: make(map[uint32]time.Time),
    }
}

func (s *Server) Start(addr string) error {
    udpAddr, err := net.ResolveUDPAddr("udp", addr)
    if err != nil {
        return err
    }

    conn, err := net.ListenUDP("udp", udpAddr)
    if err != nil {
        return err
    }
    s.conn = conn
    defer conn.Close()

    // Cleanup old entries periodically
    go s.cleanupLoop()

    buf := make([]byte, MaxPacketSize)
    for {
        n, remoteAddr, err := conn.ReadFromUDP(buf)
        if err != nil {
            log.Println("Read error:", err)
            continue
        }

        if n < HeaderSize {
            continue
        }

        seq := binary.BigEndian.Uint32(buf[0:4])
        payload := buf[HeaderSize:n]

        if s.isDuplicate(seq) {
            // Still send ACK for duplicates (idempotent)
            s.sendAck(remoteAddr, seq)
            continue
        }

        s.markSeen(seq)

        // Process the message
        fmt.Printf("Received [seq=%d]: %s\n", seq, string(payload))

        // Send ACK
        s.sendAck(remoteAddr, seq)
    }
}

func (s *Server) isDuplicate(seq uint32) bool {
    s.mu.Lock()
    defer s.mu.Unlock()
    _, exists := s.seen[seq]
    return exists
}

func (s *Server) markSeen(seq uint32) {
    s.mu.Lock()
    defer s.mu.Unlock()
    s.seen[seq] = time.Now()
    s.lastSeq = seq
}

func (s *Server) sendAck(addr *net.UDPAddr, seq uint32) {
    ack := make([]byte, HeaderSize)
    binary.BigEndian.PutUint32(ack[0:4], 0) // seq = 0 for ACK
    binary.BigEndian.PutUint32(ack[4:8], seq) // ack = received seq
    s.conn.WriteToUDP(ack, addr)
}

func (s *Server) cleanupLoop() {
    ticker := time.NewTicker(10 * time.Second)
    defer ticker.Stop()

    for range ticker.C {
        s.mu.Lock()
        cutoff := time.Now().Add(-30 * time.Second)
        for seq, t := range s.seen {
            if t.Before(cutoff) {
                delete(s.seen, seq)
            }
        }
        s.mu.Unlock()
    }
}

func main() {
    server := NewServer()
    log.Println("UDP server listening on :4242")
    if err := server.Start(":4242"); err != nil {
        log.Fatal(err)
    }
}
