```python
"""
time_travel_variables.py

A small interpreter demonstrating the `time_travel_variables` language feature,
which allows reading a variable's *future* value — i.e., the value it will hold
at the next assignment to that variable.

Syntax:
    let x = <expr>;          // assignment
    print(<expr>);           // print
    <expr> ::= <number>
              | <identifier>
              | future <identifier>   // read variable's next value

Example program:
    let x = 10;
    let y = future x;        // y = 20 (x's next value)
    let x = 20;
    print(y);                // 20
    print(future x);         // 30 (x's next value)
    let x = 30;
"""

from __future__ import annotations
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Union


# ============== AST ==============

@dataclass
class Program:
    stmts: List['Stmt']

@dataclass
class LetStmt:
    name: str
    expr: 'Expr'
    index: int = -1  # filled in by analyzer

@dataclass
class PrintStmt:
    expr: 'Expr'
    index: int = -1

@dataclass
class Lit:
    value: Any

@dataclass
class Var:
    name: str

@dataclass
class Future:
    name: str  # future(name) reads the next value of `name`

Expr = Union[Lit, Var, Future]
Stmt = Union[LetStmt, PrintStmt]


# ============== Future-value Analyzer ==============

class FutureAnalyzer:
    """
    Pre-computes, for each statement index, the "future value" of every variable
    — i.e., the value that variable will hold at its *next* assignment after
    that point.
    """

    def analyze(self, program: Program) -> Dict[int, Dict[str, Any]]:
        # Step 1: number each statement
        for i, stmt in enumerate(program.stmts):
            stmt.index = i

        # Step 2: evaluate each assignment's RHS in the env built up to that point
        # (without future refs) to get the assigned value
        env: Dict[str, Any] = {}
        assigned_value_at: Dict[int, Any] = {}  # stmt index -> value assigned

        for stmt in program.stmts:
            if isinstance(stmt, LetStmt):
                val = self._eval_plain(stmt.expr, env)
                assigned_value_at[stmt.index] = val
                env[stmt.name] = val

        # Step 3: walk backwards to compute, for each point i, the next value
        # of each variable after point i
        future_at: Dict[int, Dict[str, Any]] = {i: {} for i in range(len(program.stmts))}
        next_val: Dict[str, Any] = {}
        for i in range(len(program.stmts) - 1, -1, -1):
            stmt = program.stmts[i]
            if isinstance(stmt, LetStmt) and i in assigned_value_at:
                # At point i, the next value of stmt.name (after this stmt) is next_val[name]
                future_at[i][stmt.name] = next_val.get(stmt.name)
                # After this stmt, the next value of stmt.name becomes the value just assigned
                next_val[stmt.name] = assigned_value_at[i]

        return future_at

    def _eval_plain(self, expr: Expr, env: Dict[str, Any]) -> Any:
        """Evaluate an expression without future refs."""
        if isinstance(expr, Lit):
            return expr.value
        elif isinstance(expr, Var):
            return env[expr.name]
        elif isinstance(expr, Future):
            raise ValueError("future refs not allowed in plain eval")


# ============== Interpreter ==============

class Interpreter:
    def __init__(self):
        self.env: Dict[str, Any] = {}
        self.future_at: Dict[int, Dict[str, Any]] = {}

    def run(self, program: Program):
        analyzer = FutureAnalyzer()
        self.future_at = analyzer.analyze(program)

        for stmt in program.stmts:
            self._exec(stmt)

    def _exec(self, stmt: Stmt):
        if isinstance(stmt, LetStmt):
            val = self._eval(stmt.expr, stmt.index)
            self.env[stmt.name] = val
        elif isinstance(stmt, PrintStmt):
            val = self._eval(stmt.expr, stmt.index)
            print(val)

    def _eval(self, expr: Expr, point: int) -> Any:
        if isinstance(expr, Lit):
            return expr.value
        elif isinstance(expr, Var):
            return self.env[expr.name]
        elif isinstance(expr, Future):
            # Look up the future value of expr.name at this point
            future = self.future_at.get(point, {})
            if expr.name not in future:
                raise NameError(
                    f"Variable '{expr.name}' has no future value at this point "
                    f"(no later assignment)"
                )
            return future[expr.name]


# ============== Parser ==============

class Parser:
    def parse(self, source: str) -> Program:
        self.tokens = self._tokenize(source)
        self.pos = 0
        stmts = []
        while self.pos < len(self.tokens):
            stmts.append(self._parse_stmt())
        return Program(stmts=stmts)

    def _tokenize(self, source: str) -> List[str]:
