"""
time_travel_variables
=====================

A small interpreter that demonstrates the `time_travel_variables` language
feature: the ability to read a variable's *future* value — i.e., the value
it will hold at its next assignment.

Syntax
------
    let <ident> = <expr>;
    print(<expr>);

    <expr> ::= <integer>
             | <ident>                  // current value
             | future <ident>           // next assigned value

Semantics
---------
`future x` evaluated at program point P yields the value that `x` will hold
at the *next* assignment to `x` after P. If no such assignment exists, a
runtime error is raised.

Example
-------
    let x = 10;          // x = 10
    let y = future x;    // y = 20  (x's next value)
    let x = 20;          // x = 20
    print(y);            // 20
    print(future x);     // 30  (x's next value)
    let x = 30;          // x = 30

How it works
------------
The interpreter runs in two phases:

1. **Analysis phase.** The program is walked forward to evaluate every
   assignment's RHS in the *current* environment (without `future` refs),
   recording the value each `let` statement assigns. Then the program is
   walked *backwards* to build, for each statement index `i`, a table
   `future_at[i][name] = value` giving the next value of `name` after `i`.

2. **Execution phase.** Statements are executed in order. When a `future x`
   expression is evaluated at statement `i`, the precomputed
   `future_at[i]['x']` is returned.

This is essentially a form of dataflow analysis: the "future" of a variable
is its *next* definition in the control-flow graph (a single straight-line
program here, so it's just the next textual assignment).
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Union


# ─────────────────────────── AST ───────────────────────────

@dataclass
class Program:
    stmts: List["Stmt"]


@dataclass
class LetStmt:
    name: str
    expr: "Expr"
    index: int = -1


@dataclass
class PrintStmt:
    expr: "Expr"
    index: int = -1


@dataclass
class Lit:
    value: int


@dataclass
class Var:
    name: str


@dataclass
class Future:
    name: str


Expr = Union[Lit, Var, Future]
Stmt = Union[LetStmt, PrintStmt]


# ─────────────────────────── Lexer ───────────────────────────

TOKEN_RE = re.compile(r"\s+|(?P<NUMBER>\d+)|(?P<ID>[a-zA-Z_]\w*)|(?P<SEMI>;)|(?P<EQ>=)|(?P<LP>\()|(?P<RP>\))")


def tokenize(source: str) -> List[str]:
    tokens: List[str] = []
    for m in TOKEN_RE.finditer(source):
        if m.group().strip() == "":
            continue
        kind = m.lastgroup
        if kind == "NUMBER":
            tokens.append(("NUMBER", int(m.group())))
        elif kind == "ID":
            tokens.append(("ID", m.group()))
        else:
            tokens.append((kind, m.group()))
    return tokens


# ─────────────────────────── Parser ───────────────────────────

class ParseError(Exception):
    pass


class Parser:
    def __init__(self, tokens: List[tuple]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Optional[tuple]:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def eat(self, kind: str) -> tuple:
        tok = self.peek()
        if tok is None or tok[0] != kind:
            raise ParseError(f"Expected {kind}, got {tok}")
        self.pos += 1
        return tok

    def parse_program(self) -> Program:
        stmts = []
        while self.peek() is not None:
            stmts.append(self.parse_stmt())
        return Program(stmts=stmts)

    def parse_stmt(self) -> Stmt:
        tok = self.peek()
        if tok is None:
            raise ParseError("Unexpected end of input")
        if tok[0] == "ID" and tok[1] == "let":
            return self.parse_let()
        if tok[0] == "ID" and tok[1] == "print":
            return self.parse_print()
        raise ParseError(f"Unexpected token: {tok}")

    def parse_let(self) -> LetStmt:
        self.eat("ID")  # 'let'
        name = self.eat("ID")[1]
        self.eat("EQ")
        expr = self.parse_expr()
        self.eat("SEMI")
        return LetStmt(name=name, expr=expr)

    def parse_print(self) -> PrintStmt:
        self.eat("ID")  # 'print'
        self.eat("LP")
        expr = self.parse_expr()
        self.eat("RP")
        self.eat("SEMI")
        return PrintStmt(expr=expr)

    def parse_expr(self) -> Expr:
        tok = self.peek()
        if tok is None:
            raise ParseError("Unexpected end of input in expression")
        if tok[0] == "NUMBER":
            self.pos += 1
            return Lit(value=tok[1])
        if tok[0] == "ID":
            if tok[1] == "future":
                self.pos += 1
                name = self.eat("ID")[1]
                return Future(name=name)
            self.pos += 1
            return Var(name=tok[1])
        raise ParseError(f"Unexpected token in expression: {tok}")


# ─────────────────────────── Analyzer ───────────────────────────

class FutureAnalyzer:
    """
    Computes, for each statement index `i`, the value that each variable
    will hold at its *next* assignment after `i`.
    """

    def analyze(self, program: Program) -> Dict[int, Dict[str, int]]:
        # Number statements
        for i, stmt in enumerate(program.stmts):
            stmt.index = i

        # Forward pass: evaluate each assignment's RHS in the current env
        # (no future refs allowed here) to determine the assigned value.
        env: Dict[str, int] = {}
        assigned: Dict[int, int] = {}  # stmt index -> value assigned by that stmt

        for stmt in program.stmts:
            if isinstance(stmt, LetStmt):
                val = self._eval_plain(stmt.expr, env)
                assigned[stmt.index] = val
                env[stmt.name] = val

        # Backward pass: build future_at[i][name] = next value of `name` after i
        future_at: Dict[int, Dict[str, int]] = {
            i: {} for i in range(len(program.stmts))
        }
        next_val: Dict[str, int] = {}
        for i in range(len(program.stmts) - 1, -1, -1):
            stmt = program.stmts[i]
            if isinstance(stmt, LetStmt) and i in assigned:
                future_at[i][stmt.name] = next_val.get(stmt.name)
                next_val[stmt.name] = assigned[i]

        return future_at

    def _eval_plain(self, expr: Expr, env: Dict[str, int]) -> int:
        if isinstance(expr, Lit):
            return expr.value
        if isinstance(expr, Var):
            return env[expr.name]
        if isinstance(expr, Future):
            raise ValueError("future references not allowed in plain evaluation")
        raise ValueError(f"Unknown expression: {expr!r}")


# ─────────────────────────── Interpreter ───────────────────────────

class TimeTravelError(Exception):
    pass


class Interpreter:
    def __init__(self):
        self.env: Dict[str, int] = {}
        self.future_at: Dict[int, Dict[str, int]] = {}

    def run(self, program: Program) -> None:
        self.future_at = FutureAnalyzer().analyze(program)
        for stmt in program.stmts:
            self.exec_stmt(stmt)

    def exec_stmt(self, stmt: Stmt) -> None:
        if isinstance(stmt, LetStmt):
            val = self.eval_expr(stmt.expr, stmt.index)
            self.env[stmt.name] = val
        elif isinstance(stmt, PrintStmt):
            val = self.eval_expr(stmt.expr, stmt.index)
            print(val)

    def eval_expr(self, expr: Expr, point: int) -> int:
        if isinstance(expr, Lit):
            return expr.value
        if isinstance(expr, Var):
            if expr.name not in self.env:
                raise TimeTravelError(f"Undefined variable: {expr.name}")
            return self.env[expr.name]
        if isinstance(expr, Future):
            future = self.future_at.get(point, {})
            if expr.name not in future or future[expr.name] is None:
                raise TimeTravelError(
                    f"Variable '{expr.name}' has no future value at this point "
                    f"(no later assignment)"
                )
            return future[expr.name]
        raise ValueError(f"Unknown expression: {expr!r}")


# ─────────────────────────── Public API ───────────────────────────

def run(source: str) -> None:
    """Parse and execute a program written in the time-travel language."""
    tokens = tokenize(source)
    program = Parser(tokens).parse_program()
    Interpreter().run(program)


