"""
time_travel_variables
=====================

A small interpreter demonstrating the `time_travel_variables` language feature:
the ability to read a variable's *future* value — i.e., the value it will hold
at its next assignment.

Syntax
------
    let <ident> = <expr>;
    print(<expr>);

    <expr> ::= <integer>
             | <ident>                  // current value
             | future <ident>           // next assigned value

Semantics
---------
`future x` evaluated at program point P yields the value that `x` will hold
at the *next* assignment to `x` after P. If no such assignment exists, a
`TimeTravelError` is raised.

Example
-------
    let x = 10;
    let y = future x;    // y = 20
    let x = 20;
    print(y);            // 20
    print(future x);     // 30
    let x = 30;

How it works
------------
The interpreter runs in two phases:

1. **Analysis.** The program is scanned to find, for each variable, the list
   of statement indices where it is assigned. From this we derive, for every
   program point P and variable v:
     - `prev_at[P][v]` — the index of the most recent assignment to v before P
     - `next_at[P][v]` — the index of the next assignment to v at or after P

   We then walk the program *backwards* (from last statement to first),
   evaluating each `let` statement's RHS at its own point. Because `Var` refs
   look backward (to `prev_at`) and `Future` refs look forward (to `next_at`),
   walking backwards guarantees that every referenced assignment has already
   been evaluated. This gives us `assigned[i]` — the value written by
   statement i.

2. **Execution.** Statements are executed in order. When a `future x`
   expression is evaluated at statement i, we look up
   `assigned[next_at[i]['x']]`.

This is essentially a one-step dataflow analysis: `future x` is the *next
definition* of x in the (straight-line) control-flow graph.
"""

from __future__ import annotations

import re
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Tuple, Union


# ═══════════════════════════ AST ═══════════════════════════

@dataclass
class Program:
    stmts: List["Stmt"]


@dataclass
class LetStmt:
    name: str
    expr: "Expr"
    index: int = -1


@dataclass
class PrintStmt:
    expr: "Expr"
    index: int = -1


@dataclass
class Lit:
    value: int


@dataclass
class Var:
    name: str


@dataclass
class Future:
    name: str


Expr = Union[Lit, Var, Future]
Stmt = Union[LetStmt, PrintStmt]


# ═══════════════════════════ Errors ═══════════════════════════

class TimeTravelError(Exception):
    """Raised when a future reference cannot be resolved."""


class ParseError(Exception):
    """Raised when the source cannot be parsed."""


# ═══════════════════════════ Lexer ═══════════════════════════

# Token kinds: NUMBER, ID, SEMI, EQ, LP, RP
_TOKEN_RE = re.compile(
    r"""
    \s+           |   # whitespace (skip)
    (?P<NUMBER>\d+)|   # integer literal
    (?P<ID>[a-zA-Z_]\w*)|  # identifier or keyword
    (?P<SEMI>;)   |   # semicolon
    (?P<EQ>=)     |   # equals
    (?P<LP>\()    |   # left paren
    (?P<RP>\))        # right paren
    """,
    re.VERBOSE,
)


def tokenize(source: str) -> List[Tuple[str, Any]]:
    tokens: List[Tuple[str, Any]] = []
    for m in _TOKEN_RE.finditer(source):
        kind = m.lastgroup
        if kind is None:
            continue  # whitespace
        if kind == "NUMBER":
            tokens.append((kind, int(m.group())))
        elif kind == "ID":
            tokens.append((kind, m.group()))
        else:
            tokens.append((kind, m.group()))
    if any(t[0] is None for t in tokens):
        raise ParseError(f"Unexpected character in source")
    return tokens


# ═══════════════════════════ Parser ═══════════════════════════

class Parser:
    def __init__(self, tokens: List[Tuple[str, Any]]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Optional[Tuple[str, Any]]:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def eat(self, kind: str) -> Tuple[str, Any]:
        tok = self.peek()
        if tok is None or tok[0] != kind:
            raise ParseError(f"Expected {kind}, got {tok}")
        self.pos += 1
        return tok

    def parse(self) -> Program:
        stmts: List[Stmt] = []
        while self.peek() is not None:
            stmts.append(self._stmt())
        return Program(stmts=stmts)

    def _stmt(self) -> Stmt:
        tok = self.peek()
        if tok is None:
            raise ParseError("Unexpected end of input")
        if tok[0] == "ID" and tok[1] == "let":
            return self._let()
        if tok[0] == "ID" and tok[1] == "print":
            return self._print()
        raise ParseError(f"Expected statement, got {tok}")

    def _let(self) -> LetStmt:
        self.eat("ID")  # 'let'
        name_tok = self.eat("ID")
        self.eat("EQ")
        expr = self._expr()
        self.eat("SEMI")
        return LetStmt(name=name_tok[1], expr=expr)

    def _print(self) -> PrintStmt:
        self.eat("ID")  # 'print'
        self.eat("LP")
        expr = self._expr()
        self.eat("RP")
        self.eat("SEMI")
        return PrintStmt(expr=expr)

    def _expr(self) -> Expr:
        tok = self.peek()
        if tok is None:
            raise ParseError("Unexpected end of input in expression")
        if tok[0] == "NUMBER":
            self.pos += 1
            return Lit(value=tok[1])
        if tok[0] == "ID":
            if tok[1] == "future":
                self.pos += 1
                name_tok = self.eat("ID")
                return Future(name=name_tok[1])
            self.pos += 1
            return Var(name=tok[1])
        raise ParseError(f"Unexpected token in expression: {tok}")


# ═══════════════════════════ Analyzer ═══════════════════════════

class FutureAnalyzer:
    """
    Computes, for each statement index, the value that each variable will
    hold at its *next* assignment after that point.
    """

    def analyze(self, program: Program) -> Dict[int, Dict[str, int]]:
        n = len(program.stmts)
        for i, stmt in enumerate(program.stmts):
            stmt.index = i

        # Collect assignment indices per variable
        assign_idx: Dict[str, List[int]] = {}
        for i, stmt in enumerate(program.stmts):
            if isinstance(stmt, LetStmt):
                assign_idx.setdefault(stmt.name, []).append(i)

        # For each program point p ∈ [0..n] and each variable v, compute:
        #   prev_at[p][v] = largest assignment index to v that is < p  (or None)
        #   next_at[p][v] = smallest assignment index to v that is >= p (or None)
        prev_at: List[Dict[str, Optional[int]]] = [{} for _ in range(n + 1)]
        next_at: List[Dict[str, Optional[int]]] = [{} for _ in range(n + 1)]

        for v, idxs in assign_idx.items():
            for p in range(n + 1):
                # prev
                prev = None
                for idx in idxs:
                    if idx < p:
                        prev = idx
                    else:
                        break
                prev_at[p][v] = prev
                # next
                nxt = None
                for idx in idxs:
                    if idx >= p:
                        nxt = idx
                        break
                next_at[p][v] = nxt

        # Walk *backwards* to evaluate each assignment's RHS.
        # At point p:
        #   Var(v)   -> assigned[prev_at[p][v]]   (already computed: prev < p ≤ current i)
        #   Future(v)-> assigned[next_at[p][v]]   (already computed: next > i, and we go backward)
        assigned: Dict[int, int] = {}
        for i in range(n - 1, -1, -1):
            stmt = program.stmts[i]
            if isinstance(stmt, LetStmt):
                assigned[i] = self._eval(stmt.expr, i, prev_at, next_at, assigned)

        # Build future_at[i][v] = assigned[next_at[i][v]] for each stmt i
        future_at: Dict[int, Dict[str, int]] = {i: {} for i in range(n)}
        for i in range(n):
            for v in assign_idx:
                nxt = next_at[i][v]
                if nxt is not None:
                    future_at[i][v] = assigned[nxt]

        return future_at

    def _eval(
        self,
        expr: Expr,
        point: int,
        prev_at: List[Dict[str, Optional[int]]],
        next_at: List[Dict[str, Optional[int]]],
        assigned: Dict[int, int],
    ) -> int:
        if isinstance(expr, Lit):
            return expr.value
        if isinstance(expr, Var):
            prev = prev_at[point][expr.name]
            if prev is None:
                raise TimeTravelError(f"Undefined variable '{expr.name}'")
            return assigned[prev]
        if isinstance(expr, Future):
            nxt = next_at[point][expr.name]
            if nxt is None:
                raise TimeTravelError(
                    f"Variable '{expr.name}' has no future value at this point "
                    f"(no later assignment)"
                )
            return assigned[nxt]
        raise ValueError(f"Unknown expression: {expr!r}")


# ═══════════════════════════ Interpreter ═══════════════════════════

class Interpreter:
    def __init__(self):
        self.env: Dict[str, int] = {}
        self.future_at: Dict[int, Dict[str, int]] = {}

    def run(self, program: Program) -> None:
        self.future_at = FutureAnalyzer().analyze(program)
        for stmt in program.stmts:
            self._exec(stmt)

    def _exec(self, stmt: Stmt) -> None:
        if isinstance(stmt, LetStmt):
            self.env[stmt.name] = self._eval(stmt.expr, stmt.index)
        elif isinstance(stmt, PrintStmt):
            print(self._eval(stmt.expr, stmt.index))

    def _eval(self, expr: Expr, point: int) -> int:
        if isinstance(expr, Lit):
            return expr.value
        if isinstance(expr, Var):
            if expr.name not in self.env:
                raise TimeTravelError(f"Undefined variable '{expr.name}'")
            return self.env[expr.name]
        if isinstance(expr, Future):
            future = self.future_at.get(point, {})
            if expr.name not in future:
                raise TimeTravelError(
                    f"Variable '{expr.name}' has no future value at this point"
                )
            return future[expr.name]
        raise ValueError(f"Unknown expression: {expr!r}")


# ═══════════════════════════ Public API ═══════════════════════════

def run(source: str) -> None:
    """Parse and execute a program in the time-travel language."""
    tokens = tokenize(source)
    program = Parser(tokens).parse()
    Interpreter().run(program)


