#!/usr/bin/env python3
"""
MU-TH-UR 6000 Job Scheduler Client
Connects to the MU-TH-UR 6000 mainframe to submit, monitor, and manage jobs.
"""

import argparse
import json
import os
import sys
import time
import uuid
from dataclasses import dataclass, asdict, field
from datetime import datetime
from enum import Enum
from typing import Optional

try:
    import requests
    HAS_REQUESTS = True
except ImportError:
    HAS_REQUESTS = False


# ─────────────────────────────────────────────────────────────────────────────
# Data model
# ─────────────────────────────────────────────────────────────────────────────

class Priority(Enum):
    LOWEST  = 0
    LOW     = 1
    NORMAL  = 2
    HIGH    = 3
    CRITICAL = 4   # Company directive — overrides all

class JobState(Enum):
    QUEUED     = "QUEUED"
    RUNNING    = "RUNNING"
    COMPLETED  = "COMPLETED"
    FAILED     = "FAILED"
    CANCELLED  = "CANCELLED"

@dataclass
class Job:
    id: str
    name: str
    command: str
    priority: int
    state: str = JobState.QUEUED.value
    submitted_at: float = field(default_factory=time.time)
    started_at: Optional[float] = None
    finished_at: Optional[float] = None
    exit_code: Optional[int] = None
    output: str = ""

    def short(self) -> str:
        return (f"[{self.id[:8]}] {self.state:<10} P{self.priority} "
                f"{self.name}  ({self.command[:40]})")


# ─────────────────────────────────────────────────────────────────────────────
# In-memory mock backend (used when no server is reachable)
# ─────────────────────────────────────────────────────────────────────────────

class MockMotherBackend:
    """Simulates the MU-TH-UR 6000 for offline / demo use."""

    def __init__(self):
        self.jobs: dict[str, Job] = {}
        self.tick = 0

    def submit(self, name, command, priority) -> Job:
        job = Job(id=str(uuid.uuid4()), name=name, command=command,
                  priority=priority.value if isinstance(priority, Priority) else int(priority))
        self.jobs[job.id] = job
        return job

    def list(self) -> list[Job]:
        self._advance()
        return sorted(self.jobs.values(),
                      key=lambda j: (-j.priority, j.submitted_at))

    def status(self, job_id) -> Optional[Job]:
        self._advance()
        return self._resolve(job_id)

    def cancel(self, job_id) -> Optional[Job]:
        job = self._resolve(job_id)
        if job and job.state in (JobState.QUEUED.value, JobState.RUNNING.value):
            job.state = JobState.CANCELLED.value
            job.finished_at = time.time()
        return job

    def _resolve(self, job_id) -> Optional[Job]:
        # accept prefix match
        matches = [j for j in self.jobs.values() if j.id.startswith(job_id)]
        if len(matches) == 1:
            return matches[0]
        if len(matches) > 1:
            raise ValueError(f"ambiguous id '{job_id}'")
        return None

    def _advance(self):
        """Crank the simulation forward a tick."""
        self.tick += 1
        for job in self.jobs.values():
            if job.state == JobState.QUEUED.value and self.tick % 2 == 0:
                job.state = JobState.RUNNING.value
                job.started_at = time.time()
            elif job.state == JobState.RUNNING.value and self.tick % 3 == 0:
                job.state = JobState.COMPLETED.value
                job.finished_at = time.time()
                job.exit_code = 0
                job.output = f"[mock output for: {job.command}]"


# ─────────────────────────────────────────────────────────────────────────────
# The client
# ─────────────────────────────────────────────────────────────────────────────

BANNER = r"""
        _.-'~~~~~~`-._
       /      ||      \
      |  M U - T H - U R  |
      |       6000        |
       \      ||      /
        `-._      _.-'
            `----'
   WEYLAND-YUTANI :: JOB SCHEDULER CLIENT
"""

class MotherClient:
    def __init__(self, endpoint: Optional[str] = None, timeout: float = 5.0):
        self.endpoint = endpoint.rstrip("/") if endpoint else None
        self.timeout = timeout
        self.mock = MockMotherBackend()
        self._online = False
        if self.endpoint and HAS_REQUESTS:
            self._probe()

    def _probe(self):
        try:
            r = requests.get(f"{self.endpoint}/health", timeout=self.timeout)
            self._online = r.ok
        except Exception:
            self._online = False

    # ── transport layer ────────────────────────────────────────────────────
    def _rpc(self, method: str, path: str, **kw):
        if not self._online:
            return None  # caller falls back to mock
        try:
            fn = getattr(requests, method)
            r = fn(f"{self.endpoint}{path}", timeout=self.timeout, **kw)
            r.raise_for_status()
            return r.json()
        except Exception as e:
            print(f"[warn] mainframe link failed: {e}; using local cache",
                  file=sys.stderr)
            self._online = False
            return None

    # ── public API ─────────────────────────────────────────────────────────
    def submit(self, name: str, command: str,
               priority: Priority = Priority.NORMAL) -> Job:
        data = self._rpc("post", "/jobs", json={
            "name": name, "command": command, "priority": priority.value
        })
        if data:
            return Job(**data)
        return self.mock.submit(name, command, priority)

    def list(self) -> list[Job]:
        data = self._rpc("get", "/jobs")
        if data:
            return [Job(**j) for j in data]
        return self.mock.list()

    def status(self, job_id: str) -> Optional[Job]:
        data = self._rpc("get", f"/jobs/{job_id}")
        if data:
            return Job(**data)
        return self.mock.status(job_id)

    def cancel(self, job_id: str) -> Optional[Job]:
        data = self._rpc("delete", f"/jobs/{job_id}")
        if data:
            return Job(**data)
        return self.mock.cancel(job_id)

    @property
    def mode(self) -> str:
        return f"ONLINE ({self.endpoint})" if self._online else "OFFLINE (mock)"


# ─────────────────────────────────────────────────────────────────────────────
# REPL
# ─────────────────────────────────────────────────────────────────────────────

PROMPT = "mother> "

HELP = """\
commands:
  submit <name> <cmd> [priority]   enqueue a job
  list                              show all jobs
  status <id-prefix>                show job details
  cancel <id-prefix>                cancel a queued/running job
  mode                              show connection mode
  help                              this text
  quit / exit                       disconnect
"""

def fmt_job(j: Job, verbose: bool = False) -> str:
    if not verbose:
        return j.short()
    d = asdict(j)
    d["submitted_at"] = datetime.fromtimestamp(j.submitted_at).isoformat()
    if j.started_at:
        d["started_at"] = datetime.fromtimestamp(j.started_at).isoformat()
    if j.finished_at:
        d["finished_at"] = datetime.fromtimestamp(j.finished_at).isoformat()
    return json.dumps(d, indent=2)

def repl(client: MotherClient):
    print(BANNER)
    print(f"link status: {client.mode}")
    print(HELP)
    while True:
        try:
            line = input(PROMPT).strip()
        except (EOFError, KeyboardInterrupt):
            print("\ndisconnected.")
            break
        if not line:
            continue
        parts = line.split()
        cmd, args = parts[0].lower(), parts[1:]

        try:
            if cmd in ("quit", "exit"):
                print("disconnected.")
                break
            elif cmd == "help":
                print(HELP)
            elif cmd == "mode":
                print(f"link status: {client.mode}")
            elif cmd == "submit":
                if len(args) < 2:
                    print("usage: submit <name> <command> [priority]")
                    continue
                name, command = args[0], args[1]
                prio = Priority.NORMAL
                if len(args) >= 3:
                    try:
                        prio = Priority[args[2].upper()]
                    except KeyError:
                        try:
                            prio = Priority(int(args[2]))
                        except ValueError:
                            print(f"unknown priority: {args[2]}")
                            continue
                job = client.submit(name, command, prio)
                print(f"submitted: {job.short()}")
            elif cmd == "list":
                jobs = client.list()
                if not jobs:
                    print("(no jobs)")
                for j in jobs:
                    print(fmt_job(j))
            elif cmd == "status":
                if not args:
                    print("usage: status <id-prefix>")
                    continue
                job = client.status(args[0])
                if job is None:
                    print(f"no such job: {args[0]}")
                else:
                    print(fmt_job(job, verbose=True))
            elif cmd == "cancel":
                if not args:
                    print("usage: cancel <id-prefix>")
                    continue
                job = client.cancel(args[0])
                if job is None:
                    print(f"no such job: {args[0]}")
                else:
                    print(f"cancelled: {job.short()}")
            else:
                print(f"unknown command: {cmd}  (type 'help')")
        except Exception as e:
            print(f"error: {e}")


# ─────────────────────────────────────────────────────────────────────────────
# CLI entry point
# ─────────────────────────────────────────────────────────────────────────────

def main():
    ap = argparse.ArgumentParser(
        description="MU-TH-UR 6000 job scheduler client")
    ap.add_argument("--endpoint", default=os.environ.get("MOTHER_URL"),
                    help="mainframe REST endpoint (e.g. http://localhost:7460)")
    ap.add_argument("command", nargs="?", help="one-shot command (else REPL)")
    ap.add_argument("args", nargs=argparse.REMAINDER)
    args = ap.parse_args()

    client = MotherClient(args.endpoint)

    if args.command:
        # one-shot mode
        if args.command == "submit" and len(args.args) >= 2:
            prio = Priority.NORMAL
            if len(args.args) >= 3:
                prio = Priority[args.args[2].upper()]
            print(fmt_job(client.submit(args.args[0], args.args[1], prio)))
        elif args.command == "list":
            for j in client.list():
                print(fmt_job(j))
        elif args.command == "status" and args.args:
            j = client.status(args.args[0])
            print(fmt_job(j, verbose=True) if j else "not found")
        elif args.command == "cancel" and args.args:
            j = client.cancel(args.args[0])
            print(fmt_job(j) if j else "not found")
        else:
            ap.print_help()
    else:
        repl(client)


if __name__ == "__main__":
    main()
```

## How it works

**Architecture.** The client is a thin transport layer over a REST API exposed by the MU-TH-UR 6000 scheduler. It speaks JSON over HTTP to an endpoint like `http://mainframe:7460`. If the `requests` library is missing or the mainframe is unreachable, it transparently falls back to an in-process `MockMotherBackend` so the client is always usable for demos and testing.

**Job lifecycle.** A job moves through `QUEUED → RUNNING → COMPLETED|FAILED|CANCELLED`. Each job carries a UUID, a human-readable name, the command to execute, a priority (0–4, with `CRITICAL` reserved for company directives), timestamps, and an exit code once finished.

**Commands.**
- `submit <name> <cmd> [priority]` — enqueues a job.
- `list` — shows all jobs, sorted by descending priority then submission time.
- `status <id-prefix>` — full details; prefix matching means you only need the first few characters of a UUID.
- `cancel <id-prefix>` — aborts a queued or running job.

**Two modes of use.**
1. **Interactive REPL** — run with no arguments for a prompt where you can issue commands in a session.
2. **One-shot CLI** — `mother submit "backup" "/usr/bin/rsync -a /data /backup" HIGH` for scripting.

**Connection awareness.** The client probes `/health` on startup and prints `ONLINE (endpoint)` or `OFFLINE (mock)` so you always know whether you're talking to a real mainframe or the local simulator. If the link drops mid-session, RPC failures are caught and the client degrades gracefully to the mock backend with a warning on stderr.

**Extending it.** Swap the mock for a real scheduler (SLURM, PBS, Nomad, Kubernetes Jobs) by replacing the four methods in `MotherClient` — the REPL and CLI don't need to change.

Quick caveat first: `-fconstant-time` isn't a standard flag in GCC, Clang, or MSVC as far as I know. There has been academic work on such a flag (notably some GCC research patches), but it hasn't landed in mainline compilers. If you're referring to a specific custom toolchain or research branch, let me know and I can tailor this.

That said, here's a small constant-time C++ example that demonstrates the patterns such a flag would be designed to enforce:

```cpp
// constant_time.hpp
#pragma once
#include <cstddef>
#include <cstdint>

// Constant-time byte-slice equality. No early exit on mismatch.
inline bool ct_equal(const uint8_t* a, const uint8_t* b, std::size_t len) {
    uint8_t diff = 0;
    for (std::size_t i = 0; i < len; ++i) {
        diff = static_cast<uint8_t>(diff | (a[i] ^ b[i]));
    }
    // Branch-free normalization to 0/1.
    return static_cast<uint8_t>(-(diff != 0)) >> 7 ^ 1U;
}

// Constant-time select: returns a if pick == 0, b if pick == 1.
inline std::uint32_t ct_select(std::uint32_t a, std::uint32_t b,
                               std::uint32_t pick) {
    const std::uint32_t mask = static_cast<std::uint32_t>(-(pick & 1U));
    return (a & ~mask) | (b & mask);
}

// Constant-time conditional copy: if pick == 1, overwrite dst with src.
inline void ct_copy(std::uint8_t* dst, const std::uint8_t* src,
                    std::size_t len, std::uint32_t pick) {
    const std::uint8_t mask = static_cast<std::uint8_t>(-(pick & 1U));
    for (std::size_t i = 0; i < len; ++i) {
        dst[i] = static_cast<std::uint8_t>((dst[i] & ~mask) | (src[i] & mask));
    }
}
```

```cpp
// example.cpp
#include "constant_time.hpp"
#include <cstdio>

int main() {
    const std::uint8_t key[]  = {0xDE, 0xAD, 0xBE, 0xEF};
    const std::uint8_t good[] = {0xDE, 0xAD, 0xBE, 0xEF};
    const std::uint8_t bad[]  = {0xDE, 0xAD, 0xBE, 0xEE};

    std::printf("good match: %d\n",  static_cast<int>(ct_equal(key, good, 4)));
    std::printf("bad  match: %d\n",  static_cast<int>(ct_equal(key, bad,  4)));

    // Branch-free ternary.
    std::uint32_t a = 0x1111'1111, b = 0x2222'2222;
    std::printf("pick=0 -> %08x\n", ct_select(a, b, 0));
    std::printf("pick=1 -> %08x\n", ct_select(a, b, 1));
}
```

A few notes for the doc:

- **No data-dependent branches.** Every control-flow decision is rewritten as arithmetic on a mask of all-0s or all-1s.
- **No data-dependent memory access.** Indexing is fixed; `ct_copy` always walks the whole buffer.
- **Compiler caveats.** Even with a hypothetical `-fconstant-time`, optimizers can still break constant-time code via undefined behavior, table-based optimizations, or secret-dependent `memcmp`/`strcmp` substitution. The real-world verification stack is usually:
  - **dudect** — statistical timing-leak detector.
  - **valgrind + ctgrind** — dynamic taint analysis.
  - **valentine** or **timing-safe-compare** style audits.
  - **libsodium** / **BearSSL** as reference implementations.

