```cpp
// example.cpp
#include <gsl/zerocopy_span>
#include <array>
#include <cstdio>
#include <type_traits>

// gsl::zerocopy_span<T> is a non-owning view that *requires* the element
// type to be trivially copyable (safe to memcpy). It's a stricter
// gsl::span<T> with a static_assert baked in.

// 1. Function taking a read-only non-owning view
double average(gsl::zerocopy_span<const int> values) {
    if (values.empty()) return 0.0;
    long sum = 0;
    for (auto v : values) sum += v;
    return static_cast<double>(sum) / values.size();
}

// 2. Function taking a mutable non-owning view, modifying in place
void scale(gsl::zerocopy_span<int> values, int factor) {
    for (auto& v : values) v *= factor;
}

// 3. Function taking a sub-view via .subspan()
void print_window(gsl::zerocopy_span<const int> values, size_t offset, size_t count) {
    auto window = values.subspan(offset, count);
    std::printf("window[%zu..%zu): ", offset, offset + count);
    for (auto v : window) std::printf("%d ", v);
    std::printf("\n");
}

int main() {
    // --- From a C-style array ---
    int raw[] = {1, 2, 3, 4, 5, 6, 7, 8};
    std::printf("raw avg = %.2f\n", average(raw));          // implicit conversion

    // --- From a std::array ---
    std::array<int, 5> arr = {{10, 20, 30, 40, 50}};
    std::printf("arr avg = %.2f\n", average(arr));

    // --- From a pointer + length ---
    int* p = raw;
    average(gsl::zerocopy_span<const int>(p, 4));           // explicit ctor

    // --- Mutate through the view ---
    scale(arr, 3);
    std::printf("arr after scale(3): ");
    for (auto v : arr) std::printf("%d ", v);
    std::printf("\n");

    // --- Subspan ---
    print_window(arr, 1, 3);                                // prints "20 30 40" * 3 = 60 90 120

    // --- Inspect the view itself ---
    gsl::zerocopy_span<const int> view{arr};
    static_assert(std::is_same<typename decltype(view)::element_type, const int>::value,
                  "element_type is const int");
    std::printf("size=%zu  data[0]=%d  front=%d  back=%d\n",
                view.size(), view.data()[0], view.front(), view.back());

    // --- This would fail to compile: std::vector<std::unique_ptr<int>>
    //     is not trivially copyable, so zerocopy_span rejects it.
    // std::vector<std::unique_ptr<int>> v;
    // average(gsl::zerocopy_span<const std::unique_ptr<int>>(v.data(), v.size()));
    //   error: static_assert: "non-trivial copy constructor"
}
```

