# Important Clarification First

`<linux/wifi_wpa2_enterprise.h>` is a **kernel-space header**, part of the Linux kernel's `cfg80211` subsystem. It's intended for **wireless driver authors** who want to implement 802.1X authentication offload in kernel modules — **not** for userspace applications that simply want to join an enterprise Wi-Fi network.

If you try to `#include <linux/wifi_wpa2_enterprise.h>` in a normal userspace C program, it won't work — those headers live under the kernel source tree and depend on kernel-internal types.

For connecting to WPA2-Enterprise from userspace, the standard approach is to talk to **`wpa_supplicant`**, which is the de facto userspace daemon that handles 802.1X/EAP authentication on Linux. You can drive it from C in two main ways:

1. **Control interface** (Unix socket, text-based protocol) — simple
2. **D-Bus interface** (`fi.w1.wpa_supplicant1`) — the modern, structured way

Below is a minimal example using the **control interface**, which is the easiest to demonstrate.

---

## Step 1: Make sure `wpa_supplicant` is installed and running

```bash
sudo apt install wpa_supplicant   # Debian/Ubuntu
```

Start it with a control interface socket:

```bash
sudo wpa_supplicant -i wlan0 -c /etc/wpa_supplicant/wpa_supplicant.conf \
    -O /var/run/wpa_supplicant
```

A minimal config that lets you control everything from your program:

```
ctrl_interface=/var/run/wpa_supplicant
update_config=1
```

---

## Step 2: C program that connects to an enterprise network

This program adds a WPA2-Enterprise network (EAP-PEAP/MSCHAPv2 is shown, but you can swap EAP methods), enables it, and waits for a connection.

```c
/*
 * wpa2e_connect.c
 *
 * Connects to a WPA2-Enterprise network via the wpa_supplicant
 * control interface (Unix datagram socket).
 *
 * Build:  gcc -o wpa2e_connect wpa2e_connect.c
 * Run:    sudo ./wpa2e_connect wlan0 my-ssid username password
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <sys/un.h>
#include <poll.h>

#define WPA_CTRL_PATH "/var/run/wpa_supplicant"

static int ctrl_conn = -1;
static int mon_conn  = -1;

/* Connect to wpa_supplicant's control socket for a given interface. */
static int wpa_open(const char *ifname, int *sock)
{
    int fd;
    struct sockaddr_un addr;

    fd = socket(AF_UNIX, SOCK_DGRAM, 0);
    if (fd < 0) {
        perror("socket");
        return -1;
    }

    memset(&addr, 0, sizeof(addr));
    addr.sun_family = AF_UNIX;
    snprintf(addr.sun_path, sizeof(addr.sun_path),
             "%s/%s", WPA_CTRL_PATH, ifname);

    if (connect(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "connect(%s): %s\n",
                addr.sun_path, strerror(errno));
        close(fd);
        return -1;
    }
    *sock = fd;
    return 0;
}

/* Send a command and read the reply. */
static int wpa_cmd(int fd, const char *cmd, char *reply, size_t rlen)
{
    int n;

    if (send(fd, cmd, strlen(cmd), 0) < 0) {
        perror("send");
        return -1;
    }

    n = recv(fd, reply, rlen - 1, 0);
    if (n < 0) {
        perror("recv");
        return -1;
    }
    reply[n] = '\0';

    /* Replies are "OK\n" or "FAIL <reason>\n" */
    return (strncmp(reply, "OK", 2) == 0) ? 0 : -1;
}

/* Attach for unsolicited events on the monitor socket. */
static int wpa_attach(int fd)
{
    char reply[64];
    return wpa_cmd(fd, "ATTACH", reply, sizeof(reply));
}

/* Wait until we see a CTRL-EVENT-CONNECTED or a failure. */
static int wait_for_connection(int fd, int timeout_ms)
{
    char buf[2048];
    struct pollfd pfd = { .fd = fd, .events = POLLIN };
    int elapsed = 0;

    while (elapsed < timeout_ms) {
        int n;
        int wait = (timeout_ms - elapsed > 1000) ? 1000 : (timeout_ms - elapsed);

        n = poll(&pfd, 1, wait);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("poll");
            return -1;
        }
        if (n == 0) {                       /* timeout tick */
            elapsed += wait;
            continue;
        }

        n = recv(fd, buf, sizeof(buf) - 1, 0);
        if (n <= 0) return -1;
        buf[n] = '\0';

        /* wpa_supplicant prefixes unsolicited messages with "<N>" priority */
        if (strstr(buf, "CTRL-EVENT-CONNECTED")) {
            printf("[wpa] Connected!\n%s", buf);
            return 0;
        }
        if (strstr(buf, "CTRL-EVENT-DISCONNECTED") ||
            strstr(buf, "CTRL-EVENT-ASSOC-REJECT")  ||
            strstr(buf, "CTRL-EVENT-EAP-FAILURE")) {
            fprintf(stderr, "[wpa] Connection failed:\n%s", buf);
            return -1;
        }
        elapsed += wait;
    }
    fprintf(stderr, "[wpa] Timeout waiting for connection\n");
    return -1;
}

int main(int argc, char *argv[])
{
    const char *ifname, *ssid, *identity, *password;
    char cmd[1024], reply[256];
    long net_id;

    if (argc != 5) {
        fprintf(stderr,
            "Usage: %s <iface> <ssid> <identity> <password>\n"
            "Example: %s wlan0 'Corp-WiFi' alice 's3cret'\n",
            argv[0], argv[0]);
        return 1;
    }
    ifname   = argv[1];
    ssid     = argv[2];
    identity = argv[3];
    password = argv[4];

    if (wpa_open(ifname, &ctrl_conn) < 0) return 1;
    if (wpa_open(ifname, &mon_conn)  < 0) { close(ctrl_conn); return 1; }
    if (wpa_attach(mon_conn) < 0) {
        fprintf(stderr, "ATTACH failed\n");
        return 1;
    }

    /* Remove any old network with the same SSID (ignore errors). */
    snprintf(cmd, sizeof(cmd), "REMOVE_NETWORK all");
    wpa_cmd(ctrl_conn, cmd, reply, sizeof(reply));

    /* Add a fresh network and remember its id. */
    if (wpa_cmd(ctrl_conn, "ADD_NETWORK", reply, sizeof(reply)) < 0) {
        fprintf(stderr, "ADD_NETWORK failed: %s", reply);
        return 1;
    }
    net_id = strtol(reply, NULL, 10);

    /* Configure WPA2-Enterprise with EAP-PEAP + MSCHAPv2.
     * Swap these set_network lines for TTLS, TLS, SIM, etc. as needed. */
    snprintf(cmd, sizeof(cmd),
             "SET_NETWORK %ld ssid \"%s\"", net_id, ssid);
    if (wpa_cmd(ctrl_conn, cmd, reply, sizeof(reply)) < 0) goto fail;

    snprintf(cmd, sizeof(cmd),
             "SET_NETWORK %ld key_mgmt WPA-EAP", net_id);
    if (wpa_cmd(ctrl_conn, cmd, reply, sizeof(reply)) < 0) goto fail;

    snprintf(cmd, sizeof(cmd),
             "SET_NETWORK %ld eap PEAP", net_id);
    if (wpa_cmd(ctrl_conn, cmd, reply, sizeof(reply)) < 0) goto fail;

    snprintf(cmd, sizeof(cmd),
             "SET_NETWORK %ld identity \"%s\"", net_id, identity);
    if (wpa_cmd(ctrl_conn, cmd, reply, sizeof(reply)) < 0) goto fail;

    snprintf(cmd, sizeof(cmd),
             "SET_NETWORK %ld password \"%s\"", net_id, password);
    if (wpa_cmd(ctrl_conn, cmd, reply, sizeof(reply)) < 0) goto fail;

    snprintf(cmd, sizeof(cmd),
             "SET_NETWORK %ld phase2 \"auth=MSCHAPV2\"", net_id);
    if (wpa_cmd(ctrl_conn, cmd, reply, sizeof(reply)) < 0) goto fail;

    /* Optional but recommended: validate the server certificate.
     * ca_cert must be a PEM file path readable by wpa_supplicant (root). */
