import { jwtVerify } from 'jose';

const { payload, protectedHeader } = await jwtVerify(jwt, publicKey);
console.log('Header:', protectedHeader);  // { alg: 'EdDSA' }
console.log('Payload:', payload);
```

### Using an existing JWK (e.g., from a file or env var)

```js
import { SignJWT, importJWK, jwtVerify } from 'jose';
import { readFileSync } from 'fs';

const privateJwk = JSON.parse(readFileSync('./private.jwk', 'utf8'));
const publicJwk  = JSON.parse(readFileSync('./public.jwk',  'utf8'));

// Import as a CryptoKey (note: Ed25519 JWKs need `alg: 'EdDSA'` to disambiguate)
const privateKey = await importJWK({ ...privateJwk, alg: 'EdDSA' }, 'EdDSA');
const publicKey  = await importJWK({ ...publicJwk,  alg: 'EdDSA' }, 'EdDSA');

const jwt = await new SignJWT({ foo: 'bar' })
  .setProtectedHeader({ alg: 'EdDSA' })
  .setIssuedAt()
  .setExpirationTime('1h')
  .sign(privateKey);

const { payload } = await jwtVerify(jwt, publicKey);
```

