That said, here's how to achieve **streaming a large file with low memory** using well-established Node.js primitives, plus a note on true zero-copy.

## Option 1: Built-in streams (recommended starting point)

Node's `fs.createReadStream` already reads in chunks (default 64 KB), so memory stays flat regardless of file size.

```js
const fs = require('node:fs');
const { pipeline } = require('node:stream/promises');
const zlib = require('node:zlib');

async function streamCopy(src, dest, { compress = false } = {}) {
  const reader = fs.createReadStream(src, { highWaterMark: 64 * 1024 });
  const writer = fs.createWriteStream(dest, { highWaterMark: 64 * 1024 });

  const middle = compress ? zlib.createGzip() : null;

  try {
    await pipeline(reader, ...(middle ? [middle] : []), writer);
  } catch (err) {
    // pipeline auto-destroys streams on error; clean up partial file
    await fs.promises.unlink(dest).catch(() => {});
    throw err;
  }
}

// Usage
await streamCopy('/data/huge.bin', '/data/huge-copy.bin');
await streamCopy('/data/huge.bin', '/data/huge.bin.gz', { compress: true });
```

