#include <iterator>
#include <vector>
#include <iostream>

int main() {
    std::vector<double> xs = {1.0, 2.5, 3.14159, 1e10};

    std::format_to(std::ostream_iterator<char>(std::cout), "{:.3f}\n", xs[0]);
    // Or batch into a buffer:
    std::string buf;
    for (double x : xs)
        std::format_to(std::back_inserter(buf), "{:.3f}\n", x);
