use tokio::task::JoinSet;

#[tokio::main]
async fn main() {
    let mut set = JoinSet::new();

    for i in 0..10 {
        set.spawn(async move {
            // simulate work
            tokio::time::sleep(std::time::Duration::from_millis(100)).await;
