from collections.abc import Mapping, Hashable


class FrozenMap(Mapping, Hashable):
    """
    An immutable, hashable mapping.

    Once created, a FrozenMap cannot be modified. Any "change" returns
    a new FrozenMap instance. Because it's hashable, it can be used as
    a dict key or set member.
    """

    __slots__ = ('_items', '_hash')

    def __init__(self, *args, **kwargs):
        # Build a regular dict, then freeze it
        d = dict(*args, **kwargs)
        # Store as a sorted tuple of (key, value) pairs
        # Sorting ensures deterministic hashing
        self._items = tuple(sorted(d.items(), key=lambda kv: _sort_key(kv[0])))
        self._hash = None  # Computed lazily

    def __hash__(self):
        if self._hash is None:
            # XOR the hashes of all key-value pairs
            # XOR is commutative, so order doesn't matter
            h = 0
            for k, v in self._items:
                h ^= hash((k, v))
            self._hash = h
        return self._hash

    def __getitem__(self, key):
        # Linear search - could be optimized with a dict
        for k, v in self._items:
            if k == key:
                return v
        raise KeyError(key)

    def __iter__(self):
        for k, v in self._items:
            yield k

    def __len__(self):
        return len(self._items)

    def __repr__(self):
        items = ', '.join(f'{k!r}: {v!r}' for k, v in self._items)
        return f'FrozenMap({{{items}}})'

    def __eq__(self, other):
        if isinstance(other, FrozenMap):
            return self._items == other._items
        return NotImplemented

    def __or__(self, other):
        """Return a new FrozenMap with merged entries."""
        result = dict(self._items)
        result.update(other)
        return FrozenMap(result)

    def __sub__(self, other):
        """Return a new FrozenMap without keys in other."""
        result = dict(self._items)
        for key in other:
            result.pop(key, None)
        return FrozenMap(result)

    def __ror__(self, other):
        return FrozenMap(other) | self

    def set(self, key, value):
        """Return a new FrozenMap with key set to value."""
        result = dict(self._items)
        result[key] = value
        return FrozenMap(result)

    def delete(self, key):
        """Return a new FrozenMap without key."""
        result = dict(self._items)
        del result[key]
        return FrozenMap(result)

    def discard(self, key):
        """Return a new FrozenMap without key if present."""
        result = dict(self._items)
        result.pop(key, None)
        return FrozenMap(result)


def _sort_key(key):
    """Return a sort key for a dict key."""
    # For deterministic sorting, we need to handle unorderable types
    # by falling back to their repr
    try:
        return (0, key)
    except TypeError:
        return (1, repr(key))
